def _text(value, name):
    if not isinstance(value, str) or not value.strip():
        raise ValidationError(f"{name} must be a nonempty string")
    return value


def load_runtime_environment_files(configured):
    """Load owner-local env files into this process without persisting secrets."""
    configured = list(configured or [])
    if not configured:
        return
    loaded = {}
    visited = set()

    def parse(path):
        values = {}
        try:
            lines = path.read_text().splitlines()
        except (OSError, UnicodeError) as exc:
            raise ValidationError(f"runtime environment file is unreadable: {path}") from exc
        for raw_line in lines:
            line = raw_line.strip()
            if not line or line.startswith("#"):
                continue
            if line.startswith("export "):
                line = line[7:].lstrip()
            if "=" not in line:
                continue
            key, value = line.split("=", 1)
            key = key.strip()
            if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", key):
                continue
            value = value.strip()
            if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
                value = value[1:-1]
            values[key] = value
        return values

    def resolve_reference(path, reference):
        candidate = Path(reference)
        if candidate.is_absolute():
            candidates = [candidate]
        else:
            repo_root = Path(__file__).resolve().parents[2]
            candidates = [
                path.parent / candidate,
                path.parent.parent / candidate,
                Path.cwd() / candidate,
                repo_root / candidate,
            ]
        for item in candidates:
            try:
                resolved = item.resolve()
            except OSError:
                continue
            if resolved.is_file():
                return resolved
        raise ValidationError(
            f"runtime environment reference is unavailable: {reference}")

    def visit(path):
        path = path.resolve()
        if path in visited:
            return
        visited.add(path)
        values = parse(path)
        loaded.update(values)
        nested = values.get("SCISAURUS_QWEN_ENV_FILE")
        if nested:
            visit(resolve_reference(path, nested))

    for configured_path in configured:
        path = Path(configured_path)
        if not path.is_absolute():
            path = Path.cwd() / path
        if not path.is_file():
            raise ValidationError(f"runtime environment file is unavailable: {path}")
        visit(path)
    for key, value in loaded.items():
        os.environ.setdefault(key, value)


def default_runtime_environment_files(repo_root=None):
    """Return the owner-local env files used by a checked-out Sci-saurus run.

    Older workflow descriptors predate ``runtime_env_files`` and therefore
    cannot name the credential file without being regenerated.  The launcher
    still has a stable, repository-owned location for those files.  Only
    existing files are returned; no environment variable is guessed and no
    secret is copied into a workflow artifact.
    """
    root = (Path(repo_root).resolve() if repo_root is not None
            else Path(__file__).resolve().parents[2])
    candidates = (
        root / "local-private" / "openalex.env",
        root / "local-private" / "ollama-cloud.env",
        root / "local-private" / "ollama-recovery.env",
    )
    return [str(path) for path in candidates if path.is_file()]


def default_openalex_shared_state_path(repo_root=None):
    """Return the repository-owned OpenAlex account ledger path."""
    root = (Path(repo_root).resolve() if repo_root is not None
            else Path(__file__).resolve().parents[2])
    return root / "local-private" / "provider-state" / "openalex-rate-state.json"


def default_openalex_shared_topic_cache_path(repo_root=None):
    """Return the repository-owned cross-mission topic cache path."""
    root = (Path(repo_root).resolve() if repo_root is not None
            else Path(__file__).resolve().parents[2])
    return root / "local-private" / "provider-cache" / "topic-openalex.json"


def _identifier(value, name):
    if not isinstance(value, str) or not IDENTIFIER.fullmatch(value):
        raise ValidationError(f"{name} must be a bounded lowercase identifier")
    return value


def _positive_number(value, name):
    if type(value) not in (int, float) or not math.isfinite(value) or value <= 0:
        raise ValidationError(f"{name} must be finite and positive")


def _validate_topic_preferences(value):
    """Validate optional scientific topic-selection preferences.

    Preferences narrow the search objective without replacing the evidence,
    maturity, or feasibility gates applied to the selected topic.
    """
    allowed = {"mode", "must_have", "avoid"}
    if (not isinstance(value, dict) or "mode" not in value
            or set(value) - allowed):
        raise ValidationError(
            "workflow topic_preferences requires mode and permits must_have and avoid")
    if value["mode"] not in {"general", "computational_native"}:
        raise ValidationError(
            "workflow topic_preferences.mode must be general or computational_native")
    for field in ("must_have", "avoid"):
        items = value.get(field, [])
        if (not isinstance(items, list) or len(items) > 12
                or any(not isinstance(item, str) or not item.strip() or len(item) > 240
                       for item in items)):
            raise ValidationError(
                f"workflow topic_preferences.{field} must be a list of at most twelve nonempty strings of 240 characters or fewer")


def validate_workflow(value):
    """Validate the immutable composer workflow contract."""
    fields = {"schema_version", "id", "revision", "project_id", "objective", "stages", "time_policy", "completion"}
    allowed_fields = fields | {"retry_policy", "continuation_policy", "agenda_policy",
                               "organization", "exploration_seed",
                               "topic_reuse_allowed", "experiment_catalog", "topic_exclusions",
                               "topic_history_path", "capability_foundry_config_path",
                               "topic_preferences", "runtime_env_files", "progression_policy"}
    if not isinstance(value, dict) or set(value) - allowed_fields or not fields.issubset(value):
        raise ValidationError(
            f"composer workflow requires {sorted(fields)} and permits ['agenda_policy', 'capability_foundry_config_path', 'continuation_policy', 'exploration_seed', 'experiment_catalog', 'organization', 'progression_policy', 'retry_policy', 'runtime_env_files', 'topic_exclusions', 'topic_history_path', 'topic_preferences', 'topic_reuse_allowed']")
    if value["schema_version"] != SCHEMA_VERSION:
        raise ValidationError(f"composer workflow schema must be {SCHEMA_VERSION}")
    _identifier(value["id"], "workflow id")
    if type(value["revision"]) is not int or value["revision"] < 1:
        raise ValidationError("workflow revision must be a positive integer")
    _text(value["project_id"], "workflow project_id")
    _text(value["objective"], "workflow objective")
    if "exploration_seed" in value and (
            type(value["exploration_seed"]) is not int or value["exploration_seed"] < 0):
        raise ValidationError("workflow exploration_seed must be a non-negative integer when configured")
    if "topic_reuse_allowed" in value and type(value["topic_reuse_allowed"]) is not bool:
        raise ValidationError("workflow topic_reuse_allowed must be Boolean when configured")
    if "topic_preferences" in value:
        _validate_topic_preferences(value["topic_preferences"])
    agenda_policy = value.get("agenda_policy")
    if "progression_policy" in value and (not isinstance(value["progression_policy"], str)
            or value["progression_policy"] not in {
                "evidence_first", "full_pass", FORWARD_FIRST_POLICY,
            }):
        raise ValidationError(
            "progression_policy must be evidence_first, full_pass, or forward_first")
    if agenda_policy is not None:
        if (not isinstance(agenda_policy, dict)
                or set(agenda_policy) != {"mode"}
                or agenda_policy.get("mode") not in {"adaptive", "ordered"}):
            raise ValidationError(
                "workflow agenda_policy requires exactly mode=adaptive or mode=ordered")
    if "topic_history_path" in value:
        history_path = value["topic_history_path"]
        if not isinstance(history_path, str) or not history_path.strip():
            raise ValidationError("workflow topic_history_path must be a nonempty absolute path")
        if not Path(history_path).is_absolute():
            raise ValidationError("workflow topic_history_path must be an absolute path")
        if Path(history_path).exists() and not Path(history_path).is_file():
            raise ValidationError("workflow topic_history_path must name a file")
    if "runtime_env_files" in value:
        env_files = value["runtime_env_files"]
        if (not isinstance(env_files, list) or not env_files
                or len(env_files) > 8
                or any(not isinstance(item, str) or not Path(item).is_absolute()
                       or not Path(item).is_file() for item in env_files)):
            raise ValidationError(
                "workflow runtime_env_files must contain one to eight existing absolute files")
    if "capability_foundry_config_path" in value:
        foundry_path = value["capability_foundry_config_path"]
        if (not isinstance(foundry_path, str) or not Path(foundry_path).is_absolute()
                or not Path(foundry_path).is_file()):
            raise ValidationError(
                "workflow capability_foundry_config_path must be an existing absolute file")
        from scisaurus.runtime.capability_foundry import validate_foundry_config
        try:
            validate_foundry_config(json.loads(Path(foundry_path).read_text()))
        except (OSError, ValueError, TypeError) as exc:
            raise ValidationError("workflow capability foundry config is unreadable") from exc
    if "topic_exclusions" in value:
        exclusions = value["topic_exclusions"]
        if (not isinstance(exclusions, dict)
                or set(exclusions) != {"capability_ids", "topic_ids"}
                or not isinstance(exclusions["capability_ids"], list)
                or not isinstance(exclusions["topic_ids"], list)):
            raise ValidationError("workflow topic_exclusions requires capability_ids and topic_ids lists")
        for name in ("capability_ids", "topic_ids"):
            if len(exclusions[name]) != len(set(exclusions[name])):
                raise ValidationError(f"workflow topic_exclusions.{name} must be unique")
            for item in exclusions[name]:
                _identifier(item, f"workflow topic exclusion {name} entry")
    if "experiment_catalog" in value:
        catalog = value["experiment_catalog"]
        if (not isinstance(catalog, list) or not catalog
                or len(catalog) > 16):
            raise ValidationError("workflow experiment_catalog must contain one to sixteen entries")
        catalog_ids = set()
        for entry in catalog:
            if not isinstance(entry, dict) or set(entry) != {"id", "config_path"}:
                raise ValidationError("workflow experiment_catalog entries require exactly id and config_path")
            entry_id = _identifier(entry["id"], "experiment catalog id")
            if entry_id in catalog_ids:
                raise ValidationError("workflow experiment_catalog IDs must be unique")
            catalog_ids.add(entry_id)
            path = Path(entry["config_path"])
            if not path.is_absolute() or not path.is_file():
                raise ValidationError("experiment catalog config_path must be an existing absolute file")
    stages = value["stages"]
    if not isinstance(stages, list) or not stages:
        raise ValidationError("composer workflow requires at least one stage")
    stage_ids, outputs = set(), set()
    stage_fields = {"id", "kind", "config_path", "project_dir", "depends_on", "estimate_seconds", "bindings",
                    "deadline_seconds", "reuse_completed", "reuse_output_path"}
    allowed_stage_fields = stage_fields | {"quota"}
    for stage in stages:
        if not isinstance(stage, dict) or not stage_fields.issubset(stage) or set(stage) - allowed_stage_fields:
            raise ValidationError(
                f"composer stage requires {sorted(stage_fields)} and permits quota")
        stage_id = _identifier(stage["id"], "stage id")
        if stage_id in stage_ids:
            raise ValidationError("composer stage IDs must be unique")
        stage_ids.add(stage_id)
        if stage["kind"] not in STAGE_KINDS:
            raise ValidationError(f"unsupported composer stage kind: {stage['kind']}")
        for key in ("config_path", "project_dir"):
            path = Path(stage[key])
            if not path.is_absolute() or not path.exists():
                raise ValidationError(f"stage {stage_id} {key} must be an existing absolute path")
        _positive_number(stage["estimate_seconds"], f"stage {stage_id} estimate_seconds")
        _positive_number(stage["deadline_seconds"], f"stage {stage_id} deadline_seconds")
        if "quota" in stage:
            quota = stage["quota"]
            if not isinstance(quota, dict) or set(quota) != STAGE_QUOTA_FIELDS:
                raise ValidationError(
                    f"stage {stage_id} quota requires exactly {sorted(STAGE_QUOTA_FIELDS)}")
            if (type(quota["max_model_calls"]) is not int
                    or quota["max_model_calls"] < 1):
                raise ValidationError(f"stage {stage_id} quota max_model_calls must be a positive integer")
            for field in ("max_input_tokens", "max_output_tokens"):
                if type(quota[field]) is not int or quota[field] < 1:
                    raise ValidationError(f"stage {stage_id} quota {field} must be a positive integer")
            if (type(quota["max_openalex_requests"]) is not int
                    or quota["max_openalex_requests"] < 0):
                raise ValidationError(
                    f"stage {stage_id} quota max_openalex_requests must be a nonnegative integer")
        deps = stage["depends_on"]
        if not isinstance(deps, list) or len(deps) != len(set(deps)) or any(not isinstance(dep, str) for dep in deps):
            raise ValidationError(f"stage {stage_id} depends_on must be a unique string list")
        if stage_id in deps:
            raise ValidationError(f"stage {stage_id} cannot depend on itself")
        bindings = stage["bindings"]
        if not isinstance(bindings, list):
            raise ValidationError(f"stage {stage_id} bindings must be a list")
        for binding in bindings:
            if not isinstance(binding, dict) or set(binding) != {"target", "source"}:
                raise ValidationError(f"stage {stage_id} binding must have target and source")
            _text(binding["target"], f"stage {stage_id} binding target")
            _text(binding["source"], f"stage {stage_id} binding source")
        if type(stage["reuse_completed"]) is not bool:
            raise ValidationError(f"stage {stage_id} reuse_completed must be Boolean")
        checkpoint = stage["reuse_output_path"]
        if checkpoint is not None:
            if (not isinstance(checkpoint, str) or not Path(checkpoint).is_absolute()
                    or not Path(checkpoint).is_file()):
                raise ValidationError(f"stage {stage_id} reuse_output_path must be an existing absolute file or null")
        if stage["reuse_completed"] and checkpoint is None:
            # A stage may use its conventional output/run.json when no file is
            # supplied.  The explicit Boolean is what makes that reuse a
            # deliberate workflow decision rather than an implicit fallback.
            pass
        outputs.add(stage_id)
    for stage in stages:
        if set(stage["depends_on"]) - stage_ids:
            raise ValidationError(f"stage {stage['id']} depends on an unknown stage")
    # Dependency graph must be acyclic; a topological order is also used for
    # deterministic dispatch and restart accounting.
    visiting, visited = set(), set()
    by_id = {stage["id"]: stage for stage in stages}
    def visit(stage_id):
        if stage_id in visiting:
            raise ValidationError("composer stage graph must be acyclic")
        if stage_id in visited:
            return
        visiting.add(stage_id)
        for dep in by_id[stage_id]["depends_on"]:
            visit(dep)
        visiting.remove(stage_id)
        visited.add(stage_id)
    for stage_id in stage_ids:
        visit(stage_id)

    ancestor_cache = {}

    def ancestors(stage_id):
        if stage_id not in ancestor_cache:
            found = set()
            pending = list(by_id[stage_id]["depends_on"])
            while pending:
                current = pending.pop()
                if current in found:
                    continue
                found.add(current)
                pending.extend(by_id[current]["depends_on"])
            ancestor_cache[stage_id] = found
        return ancestor_cache[stage_id]

    # A topic admitted only for evidence gathering must never flow directly
    # into execution. Any experiment downstream of topic discovery therefore
    # needs a survey ancestor that is itself downstream of that topic. Runtime
    # admission additionally checks the survey's actual gap verdict.
    for stage in stages:
        if stage["kind"] != "experiment":
            continue
        experiment_ancestors = ancestors(stage["id"])
        topic_ancestors = {
            stage_id for stage_id in experiment_ancestors
            if by_id[stage_id]["kind"] == "topic_discovery"
        }
        for topic_id in topic_ancestors:
            has_literature_gate = any(
                by_id[stage_id]["kind"] == "survey"
                and topic_id in ancestors(stage_id)
                for stage_id in experiment_ancestors
            )
            if not has_literature_gate:
                raise ValidationError(
                    f"experiment stage {stage['id']} requires a survey between "
                    f"topic stage {topic_id} and experiment admission")
    policy = value["time_policy"]
    policy_fields = {"first_result_seconds", "target_seconds", "hard_seconds", "checkpoint_seconds"}
    if not isinstance(policy, dict) or set(policy) != policy_fields:
        raise ValidationError(f"time_policy requires exactly {sorted(policy_fields)}")
    for key in policy_fields:
        _positive_number(policy[key], f"time_policy.{key}")
    if not (policy["first_result_seconds"] <= policy["target_seconds"] <= policy["hard_seconds"]):
        raise ValidationError("composer time policy requires first_result <= target <= hard")
    for stage in stages:
        if stage["deadline_seconds"] > policy["hard_seconds"]:
            raise ValidationError(f"stage {stage['id']} deadline_seconds cannot exceed composer hard_seconds")
    retry_policy = value.get("retry_policy")
    if retry_policy is not None:
        retry_fields = {"mode", "max_attempts", "backoff_seconds"}
        if not isinstance(retry_policy, dict) or set(retry_policy) - retry_fields \
                or "backoff_seconds" not in retry_policy:
            raise ValidationError(f"retry_policy requires backoff_seconds and permits {sorted(retry_fields - {'backoff_seconds'})}")
        mode = retry_policy.get("mode", "bounded")
        if mode not in {"bounded", "until_deadline"}:
            raise ValidationError("retry_policy.mode must be bounded or until_deadline")
        attempts = retry_policy.get("max_attempts")
        if mode == "bounded":
            if type(attempts) is not int or not 1 <= attempts <= 8:
                raise ValidationError("retry_policy.max_attempts must be an integer between one and eight for bounded mode")
        elif attempts is not None and (type(attempts) is not int or attempts < 1):
            raise ValidationError("retry_policy.max_attempts may be omitted or a positive integer in until_deadline mode")
        if (type(retry_policy["backoff_seconds"]) not in (int, float)
                or not math.isfinite(retry_policy["backoff_seconds"])
                or retry_policy["backoff_seconds"] < 0):
                raise ValidationError("retry_policy.backoff_seconds must be finite and non-negative")
    continuation_policy = value.get("continuation_policy")
    if continuation_policy is not None:
        continuation_fields = {"mode", "max_cycles"}
        if (not isinstance(continuation_policy, dict)
                or set(continuation_policy) - continuation_fields
                or not continuation_policy):
            raise ValidationError("continuation_policy permits mode and max_cycles")
        mode = continuation_policy.get("mode", "bounded")
        if mode not in {"bounded", "until_deadline"}:
            raise ValidationError("continuation_policy.mode must be bounded or until_deadline")
        cycles = continuation_policy.get("max_cycles")
        if mode == "bounded":
            if type(cycles) is not int or not 0 <= cycles <= 8:
                raise ValidationError("continuation_policy.max_cycles must be an integer between zero and eight for bounded mode")
        elif cycles is not None and (type(cycles) is not int or cycles < 0):
            raise ValidationError("continuation_policy.max_cycles may be omitted or a non-negative integer in until_deadline mode")
    organization = value.get("organization")
    if organization is not None:
        from scisaurus.runtime.departments import validate_organization
        validated_organization = validate_organization(organization)
        configured_departments = {item["id"] for item in validated_organization["departments"]}
        required_departments = {stage_role(stage["kind"]).split(".", 1)[0] for stage in stages}
        if required_departments - configured_departments:
            raise ValidationError(
                "project organization is missing stage-owning departments: "
                + ", ".join(sorted(required_departments - configured_departments)))
    completion = value["completion"]
    completion_fields = {"required_stage_ids", "release_requires_human"}
    if not isinstance(completion, dict) or set(completion) != completion_fields:
        raise ValidationError(f"completion requires exactly {sorted(completion_fields)}")
    required = completion["required_stage_ids"]
    if not isinstance(required, list) or not required or len(required) != len(set(required)) or set(required) - stage_ids:
        raise ValidationError("completion.required_stage_ids must name unique known stages")
    if type(completion["release_requires_human"]) is not bool:
        raise ValidationError("completion.release_requires_human must be Boolean")
    canonical_bytes(value)
    return value


def _set_path(container, path, value):
    parts = path.split(".")
    if not parts or any(not part for part in parts):
        raise ValidationError("binding target path is invalid")
    current = container
    for part in parts[:-1]:
        if not isinstance(current, dict) or part not in current:
            raise ValidationError(f"binding target does not exist: {path}")
        current = current[part]
    if not isinstance(current, dict) or parts[-1] not in current:
        raise ValidationError(f"binding target does not exist: {path}")
    current[parts[-1]] = deepcopy(value)


def _get_path(container, path):
    current = container
    for part in path.split("."):
        if not isinstance(current, dict) or part not in current:
            raise ValidationError(f"binding source does not exist: {path}")
        current = current[part]
    return deepcopy(current)


class ComposerRunner:
    """Execute a complete stage graph with a durable composer feedback loop.

    The stage runners are deliberately called through a small allowlist.  A
    workflow cannot smuggle an arbitrary shell command into the control plane;
    operations that need a program or MCP service remain inside their own
    project-scoped runner.
    """

    @property
    def usage(self):
        return self._accounting_state["usage"]

    @usage.setter
    def usage(self, value):
        if not hasattr(self, "_accounting_state"):
            self._accounting_state = {"usage": value, "stage_usage_totals": {},
                                      "pending_stage_usage": {}, "foundry_usage": {}}
        else:
            self._accounting_state["usage"] = value

    @property
    def foundry_usage(self):
        return self._accounting_state["foundry_usage"]

    @foundry_usage.setter
    def foundry_usage(self, value):
        self._accounting_state["foundry_usage"] = value

    @property
    def stage_usage_totals(self):
        return self._accounting_state["stage_usage_totals"]

    @stage_usage_totals.setter
    def stage_usage_totals(self, value):
        self._accounting_state["stage_usage_totals"] = value

    @property
    def pending_stage_usage(self):
        return self._accounting_state["pending_stage_usage"]

    @pending_stage_usage.setter
    def pending_stage_usage(self, value):
        self._accounting_state["pending_stage_usage"] = value


    def __init__(self, workflow, *, resume=False, clock=time.monotonic, on_progress=None,
                 additional_seconds=None, stop_after_stage=None):
        self.control = None
        self._runtime_environment_before = None
        self._runtime_environment_after = None
        try:
            self._initialize_composer(workflow, resume=resume, clock=clock,
                                      on_progress=on_progress, additional_seconds=additional_seconds,
                                      stop_after_stage=stop_after_stage)
        except BaseException:
            self.close()
            raise

    def _initialize_composer(self, workflow, *, resume, clock, on_progress, additional_seconds, stop_after_stage):
        self.workflow = deepcopy(validate_workflow(workflow))
        if stop_after_stage is not None and (not isinstance(stop_after_stage, str)
                or stop_after_stage not in {stage["id"] for stage in self.workflow["stages"]}):
            raise ValidationError("stop_after_stage must name a declared workflow stage")
        self.stop_after_stage = stop_after_stage
        self._runtime_environment_before = dict(os.environ)
        self._runtime_environment_after = None
        try:
            self._load_runtime_environment()
        finally:
            self._runtime_environment_after = dict(os.environ)
        if additional_seconds is not None and not resume:
            raise ValidationError("additional_seconds is only valid when resuming a Composer project")
        self.root = Path(self.workflow["project_id"]).resolve()
        # project_id is the stable identity; the workflow's project directory
        # is derived from it so a config cannot redirect the control ledger.
        self.root.mkdir(parents=True, exist_ok=True)
        self.topic_history_path = self._resolve_topic_history_path()
        self.topic_history_scope = self._topic_history_scope_key()
        self._migrate_legacy_topic_history()
        self.topic_history = self._load_topic_history()
        existing = (self.root / "state" / "control.sqlite").exists()
        if existing and not resume:
            raise ValidationError("composer project already exists; pass resume=True to continue it")
        if resume and not existing:
            raise ValidationError("composer resume requires an existing project")
        self.control = ControlStore(self.root)
        self.store = ArtifactStore(self.control)
        self.messages = MessageBus(self.control)
        self.store.init_project(principal_note=f"composer:{self.workflow['id']}")
        self.tasks = TaskManager(self.control)
        from scisaurus.runtime.departments import DepartmentRuntime
        self.departments = DepartmentRuntime(
            self.control, self.store, self.messages, self.tasks,
            project_id=self.workflow["project_id"], organization=self.workflow.get("organization"),
        )
        if resume:
            # Specialist attempts have their own leases in addition to the
            # Composer stage attempt.  Reconcile those durable child leases
            # before restoring the checkpoint so a restarted run cannot
            # silently reuse an in-flight external call.
            self.departments.reconcile_interrupted_assignments()
        # The live progress ticker runs in a background thread while the
        # project ledger is deliberately bound to the Composer thread.  Keep a
        # plain-data snapshot for that ticker; SQLite connections are not
        # shared across threads.
        self.organization_snapshot = deepcopy(self.departments.snapshot())
        self.clock = clock
        self.on_progress = on_progress or (lambda state: None)
        self._progress_lock = threading.Lock()
        self._live_progress_epoch = 0
        self.started = self.clock()
        # ``monotonic`` is the right clock while this process is alive, but it
        # cannot survive a pause/restart.  Keep a wall-clock fence alongside
        # it so ``--resume`` cannot silently grant the mission another hard
        # window.  The monotonic deadline remains the fast local check.
        self.started_epoch = time.time()
        self.deadline_epoch = self.started_epoch + float(self.workflow["time_policy"]["hard_seconds"])
        policy = self.workflow["time_policy"]
        self.deadline = self.started + float(policy["hard_seconds"])
        self.next_checkpoint = self.started
        self.run_id = uuid.uuid4().hex
        # A fresh mission receives one entropy-backed exploration seed.  It is
        # persisted in the run input/checkpoints so retries and resumes repeat
        # the same proposal, while two independently created missions explore
        # different literature samples and topic generations.  A workflow can
        # pin the seed when exact replay is desired.
        configured_seed = self.workflow.get("exploration_seed")
        self.exploration_seed = (configured_seed if configured_seed is not None
                                 else secrets.randbits(63))
        self.context = {}
        self.stage_records = {}
        self.feedback = []
        self.blockers = []
        self.usage = {
            "model_calls": 0, "input_tokens": 0, "output_tokens": 0,
            "openalex_requests": 0,
        }
        self.foundry_usage = {}
        self.continuation_cycles = 0
        # A bounded continuation policy is a lease for one Composer
        # invocation.  A resumed legacy checkpoint may already contain many
        # historical cycles; charging those cycles against the new lease
        # would make the first recoverable stage quota stop before any fresh
        # work is dispatched.  The baseline is reset only when a process
        # explicitly resumes an existing checkpoint, while the durable
        # historical counter remains unchanged for auditability.
        self._continuation_budget_baseline = 0
        self.reopened_stage_ids = set()
        self.continuation_pending_stage_ids = set()
        self.active_research_requests = []
        self.department_activity = []
        self.deadline_extensions = []
        self.deadline_decisions = []
        self.agenda_decisions = []
        self.retry_schedule = {}
        self.state_revision = 0
        self._restored_agenda_policy = None
        self._restored_topic_lineage_reconciliation = None
        self._restored_execution_frontier = None
        self._execution_started = False
        # A hold can echo the same work order in every returned stage packet.
        # Persist semantic identities so a resume cannot turn an unchanged
        # repair into another cycle of the same experiment.
        self._attempted_request_signatures = set()
        self.format_recovery_ledger = {}
        self.status = "running"
        self._child_progress = {}
        self.stage_usage_totals = {}
        self.pending_stage_usage = {}
        self._progress_snapshot = {
            "schema_version": "composer-checkpoint-1", "workflow_id": self.workflow["id"],
            "run_id": self.run_id,
            "status": self.status, "phase": "initialized", "elapsed_seconds": 0.0,
            "remaining_seconds": max(0.0, float(self.workflow["time_policy"]["hard_seconds"])),
            "started_at_epoch": self.started_epoch, "deadline_at_epoch": self.deadline_epoch,
            "exploration_seed": self.exploration_seed,
            "retry_policy": self._retry_policy(),
            "continuation_policy": self._continuation_policy(),
            "agenda_policy": self._agenda_policy(),
            "agenda_decisions": [],
            "retry_schedule": {},
            "state_revision": self.state_revision,
            "continuation_cycles": 0, "reopened_stage_ids": [],
            "continuation_budget_baseline": 0,
            "continuation_budget_used": 0,
            "continuation_pending_stage_ids": [], "active_research_requests": [],
            "attempted_request_signatures": [],
            "format_recovery_ledger": {},
            "department_activity": [], "stages": {}, "context": {}, "feedback": [],
            "blockers": [], "active_blockers": [],
            "blocker_counts": {"active": 0, "historical": 0},
            "usage": deepcopy(self.usage), "foundry_usage": {}, "deadline_decisions": [],
            "deadline_extensions": [],
            "organization": deepcopy(self.organization_snapshot),
            "topic_history_path": str(self.topic_history_path),
            "topic_history_scope": self.topic_history_scope,
            "topic_history_entries": len(self.topic_history.get("entries", [])),
        }
        self._workflow_record = None
        if not existing:
            self._workflow_record = self._publish("command/composer/workflow", "note", self.workflow, "command.composer")
            self._publish("inputs/composer-run", "note", {
                "schema_version": "composer-run-input-1", "workflow_ref": self._workflow_record["artifact_ref"],
                "run_id": self.run_id, "resume": False,
                "exploration_seed": self.exploration_seed,
                "agenda_policy": self._agenda_policy(),
            }, "command.composer")
        else:
            head = self.store.head("command/composer/workflow")
            workflow_policy_update = None
            if head is None:
                raise ValidationError("composer resume workflow does not match the original immutable workflow")
            stored_workflow = json.loads(self.store.read_body(head["body_hash"]))
            if stored_workflow != self.workflow:
                if not self._is_continuation_policy_relaxation(
                        stored_workflow, self.workflow):
                    raise ValidationError(
                        "composer resume workflow does not match the original immutable workflow")
                workflow_policy_update = {
                    "previous_workflow_ref": head["artifact_ref"],
                    "previous_policy": deepcopy(stored_workflow.get("continuation_policy")),
                    "current_policy": deepcopy(self.workflow.get("continuation_policy")),
                }
            self._restore()
            if workflow_policy_update is not None:
                self._workflow_record = self._publish(
                    "command/composer/workflow", "note", self.workflow,
                    "command.composer",
                    subjects=[workflow_policy_update["previous_workflow_ref"]],
                )
                self._publish("inputs/composer-run", "note", {
                    "schema_version": "composer-run-input-1",
                    "workflow_ref": self._workflow_record["artifact_ref"],
                    "run_id": self.run_id,
                    "resume": True,
                    "exploration_seed": self.exploration_seed,
                    "agenda_policy": self._agenda_policy(),
                    "workflow_policy_update": workflow_policy_update,
                }, "command.composer",
                    subjects=[workflow_policy_update["previous_workflow_ref"],
                              self._workflow_record["artifact_ref"]],
                )
                self._checkpoint("resume:continuation_policy_relaxed", force=True)
            if isinstance(self._restored_topic_lineage_reconciliation, dict):
                self.department_activity.append(
                    deepcopy(self._restored_topic_lineage_reconciliation))
                self._checkpoint(
                    "resume:reject_unjustified_topic_refinement", force=True)
            reconciled_orphan_attempts = self._reconcile_orphaned_duplicate_stage_attempts()
            if reconciled_orphan_attempts:
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "reconcile_orphaned_stage_attempts",
                    "attempts": reconciled_orphan_attempts,
                })
                self._checkpoint("reconciled_orphaned_stage_attempts", force=True)
            reconciled_argument_reviews = self._reconcile_restored_argument_review_pairs()
            if reconciled_argument_reviews:
                self._checkpoint("reconciled_argument_review_pairings", force=True)
            refreshed_lineages = self._reconcile_restored_stage_topic_lineage()
            if refreshed_lineages:
                self._checkpoint("resume:refresh_current_topic_lineage", force=True)
            self._continuation_budget_baseline = max(
                0, int(self.continuation_cycles or 0))
            self.active_research_requests = self._scope_active_research_requests(
                self.active_research_requests)
            self._reconcile_misclassified_model_budget_orders()
            by_id = {item["id"]: item for item in self.workflow.get("stages", [])
                     if isinstance(item, dict) and isinstance(item.get("id"), str)}
            survey_evidence_routes = self._reconcile_experiment_survey_evidence_routes(by_id)
            if survey_evidence_routes:
                self.department_activity.extend(survey_evidence_routes)
            refreshed_experiment_reconciliation = (
                self._refresh_restored_experiment_reconciliation())
            if refreshed_experiment_reconciliation:
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "refresh_restored_experiment_attempt_evidence",
                    **refreshed_experiment_reconciliation,
                })
                self._checkpoint(
                    "resume:refresh_experiment_attempt_reconciliation", force=True)
            # A stopped process can leave older generations of department
            # work orders in ``running`` even after the Composer checkpoint
            # has advanced to a newer continuation.  Fence those rows during
            # resume, before the dashboard or scheduler treats them as live.
            # Keep every request in the restored continuation: requests may
            # belong to a later stage and remain intentionally open until
            # that stage gets its turn.
            active_request_ids = {
                item.get("id") for item in self.active_research_requests
                if isinstance(item, dict) and isinstance(item.get("id"), str)
            }
            retired_work_orders = self.departments.retire_superseded_work_orders(
                active_request_ids,
                reason="superseded work order fenced during Composer resume",
            )
            if retired_work_orders:
                self.organization_snapshot = deepcopy(self.departments.snapshot())
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "retire_superseded_work_orders_on_resume",
                    "work_orders": retired_work_orders,
                })
            if self._sync_foundry_usage():
                self._checkpoint("recovered_usage", force=True)
            if self._reconcile_duplicate_foundry_settlements():
                self._checkpoint("recovered_duplicate_settlement", force=True)
        if additional_seconds is not None:
            self._extend_deadline(additional_seconds)

    def close(self):
        if self.control is not None:
            self.control.close()
            self.control = None
        # Loading owner-local env files is process-local setup, not a durable
        # mutation of the caller's shell. Restore only values that are still
        # exactly the values this runner installed; a child test or caller
        # that deliberately changed a variable while the runner was alive is
        # left untouched.
        before = self._runtime_environment_before or {}
        after = self._runtime_environment_after or {}
        for key, loaded_value in after.items():
            if os.environ.get(key) != loaded_value or before.get(key) == loaded_value:
                continue
            if key in before:
                os.environ[key] = before[key]
            else:
                os.environ.pop(key, None)
        self._runtime_environment_after = None

    @staticmethod
    def _is_continuation_policy_relaxation(previous, requested):
        """Allow only a same-mission switch from bounded continuation to its deadline."""
        if not isinstance(previous, dict) or not isinstance(requested, dict):
            return False
        previous_policy = previous.get("continuation_policy")
        requested_policy = requested.get("continuation_policy")
        if (not isinstance(previous_policy, dict)
                or not isinstance(requested_policy, dict)
                or previous_policy.get("mode", "bounded") != "bounded"
                or requested_policy.get("mode") != "until_deadline"
                or requested_policy.get("max_cycles") is not None):
            return False
        return (
            {key: value for key, value in previous.items()
             if key != "continuation_policy"}
            == {key: value for key, value in requested.items()
                if key != "continuation_policy"}
        )

    def _publish(self, logical_id, artifact_type, body, author, *, subjects=()):
        return self.store.publish_artifact(logical_id=logical_id, artifact_type=artifact_type,
                                           author=author, body=canonical_bytes(body),
                                           inputs=[{"ref": ref, "purpose": "subject"} for ref in dict.fromkeys(subjects)],
                                           media_type="application/json")

    def _record_failed_stage_usage(self, error, *, stage_id=None):
        """Merge bounded work consumed by a failed stage into run accounting."""
        # A Composer-level budget admission failure reports the observed
        # ledger snapshot in its diagnostics.  That snapshot is not work
        # performed by this failed attempt and must not be charged a second
        # time as if it were a fresh provider call.
        if bool(getattr(error, "usage_is_snapshot", False)):
            return {key: 0 for key in self.usage}
        usage = getattr(error, "usage", None)
        if not isinstance(usage, dict) or not usage:
            snapshot = getattr(error, "topic_budget", None)
            usage = snapshot.get("usage", {}) if isinstance(snapshot, dict) else {}
        if not isinstance(usage, dict):
            usage = {}
        actual = {}
        for key in self.usage:
            value = usage.get(key, 0)
            if type(value) in (int, float) and math.isfinite(value) and value >= 0:
                actual[key] = value
        panel_charged = getattr(error, "repair_panel_usage", {})
        panel_charged = panel_charged if isinstance(panel_charged, dict) else {}
        foundry_charged = getattr(error, "foundry_usage", {})
        foundry_charged = foundry_charged if isinstance(foundry_charged, dict) else {}
        uncharged = {
            key: max(0, value - panel_charged.get(key, 0) - foundry_charged.get(key, 0))
            for key, value in actual.items()
        }
        self._settle_pending_stage_usage(
            stage_id, already_charged=True, additional_usage=uncharged,
            settle_pending=stage_id is not None)
        return actual

    @staticmethod
    def _copy_error_accounting(source, target):
        """Preserve cost ownership when changing an error's runtime type."""
        for name in ("usage", "usage_is_snapshot", "foundry_usage", "repair_panel_usage", "usage_includes_foundry"):
            if hasattr(source, name):
                setattr(target, name, deepcopy(getattr(source, name)))
        return target

    def _record_capability_repair_panel_usage(self, stage, panel, *, already_charged=False):
        """Settle a completed Methods invoice before downstream authoring."""
        usage = panel.get("usage")
        if not isinstance(usage, dict):
            return {}
        totals = {key: usage.get(key, 0) for key in self.usage}
        if any(type(value) not in (int, float) or not math.isfinite(value)
               or value < 0 for value in totals.values()):
            raise ValidationError("Methods repair invoice has invalid usage")
        ledger = panel.get("ledger")
        ledger = ledger if isinstance(ledger, dict) else {}
        plan_ref = ledger.get("assignment_plan_ref")
        if not isinstance(plan_ref, str) or not plan_ref:
            raise ValidationError("Methods invoice requires its assignment plan identity")
        invoice = {
            "schema_version": "capability-repair-usage-1", "stage_id": stage["id"],
            "input_sha256": panel.get("input_sha256"),
            "assignment_plan_ref": ledger.get("assignment_plan_ref"),
            "chief_synthesis_ref": ledger.get("chief_synthesis_ref"),
            "verifier_artifact_ref": ledger.get("verifier_artifact_ref"),
            "usage": totals,
            "settled_before_invoice": already_charged,
        }
        if isinstance(panel.get("model_budget_owner"), dict):
            invoice["model_budget_owner"] = deepcopy(panel["model_budget_owner"])
        digest = hashlib.sha256(canonical_bytes({
            "stage_id": stage["id"], "assignment_plan_ref": plan_ref,
        })).hexdigest()
        namespace = f"repair-panel:{stage['id']}:{digest}"
        prior = self.stage_usage_totals.get(namespace, {})
        delta = {key: max(0, value - prior.get(key, 0))
                 for key, value in totals.items()}
        record = self.store.head(f"command/capability-repair-usage/{digest}")
        if record is None:
            record = self._publish(f"command/capability-repair-usage/{digest}",
                                   "note", invoice, "command.composer")
        else:
            stored_invoice = json.loads(self.store.read_body(record["body_hash"]))
            if stored_invoice["usage"] != totals:
                raise ValidationError("Methods invoice changes a completed assignment's usage")
            if ("model_budget_owner" in stored_invoice
                    and stored_invoice["model_budget_owner"] != invoice.get("model_budget_owner")):
                raise ValidationError("Methods invoice changes a completed assignment's budget owner")
            already_charged = already_charged or stored_invoice.get("settled_before_invoice") is True
        panel["usage_invoice_ref"] = record["artifact_ref"]
        self.pending_stage_usage[namespace] = {
            "stage_id": stage["id"], "totals": totals, "delta": delta,
        }
        self._settle_pending_stage_usage(stage["id"], namespaces={namespace},
                                        already_charged=already_charged)
        return {key: 0 for key in delta} if already_charged else delta

    def _reconcile_repair_panel_invoices(self):
        """Recover durable invoices; require attempt evidence for legacy panels."""
        rows = self.control._conn.execute(
            "SELECT a.logical_id,a.body_hash FROM artifacts a JOIN "
            "(SELECT logical_id,MAX(version) version FROM artifacts "
            "WHERE logical_id LIKE 'command/capability-repair-usage/%' GROUP BY logical_id) h "
            "ON a.logical_id=h.logical_id AND a.version=h.version").fetchall()
        stage_ids = {stage["id"] for stage in self.workflow["stages"]}
        for row in rows:
            try:
                invoice = json.loads(self.store.read_body(row["body_hash"]))
                if (not isinstance(invoice, dict) or not isinstance(invoice.get("usage"), dict)
                        or ("settled_before_invoice" in invoice
                            and type(invoice["settled_before_invoice"]) is not bool)):
                    raise ValidationError("Methods invoice has invalid accounting fields")
                stage_id = invoice["stage_id"]
                plan_ref = invoice["assignment_plan_ref"]
                digest = hashlib.sha256(canonical_bytes({
                    "stage_id": stage_id, "assignment_plan_ref": plan_ref,
                })).hexdigest()
                if (invoice["schema_version"] != "capability-repair-usage-1"
                        or stage_id not in stage_ids
                        or row["logical_id"] != f"command/capability-repair-usage/{digest}"):
                    raise ValidationError("Methods invoice has invalid stage ownership")
                self.store.get(plan_ref)
                chief = self.store.get(invoice["chief_synthesis_ref"])
                chief_usage = json.loads(self.store.read_body(chief["body_hash"]))["usage"]
                if not isinstance(chief_usage, dict):
                    raise ValidationError("Methods synthesis has invalid accounting fields")
                if any(chief_usage.get(key, 0) != invoice["usage"].get(key, 0)
                       for key in self.usage):
                    raise ValidationError("Methods invoice differs from its immutable synthesis")
                panel = {"usage": invoice["usage"], "input_sha256": invoice.get("input_sha256"),
                         "ledger": {name: invoice.get(name) for name in (
                             "assignment_plan_ref", "chief_synthesis_ref", "verifier_artifact_ref")}}
                if "model_budget_owner" in invoice:
                    panel["model_budget_owner"] = deepcopy(invoice["model_budget_owner"])
                self._record_capability_repair_panel_usage({"id": stage_id}, panel)
            except (KeyError, NotFoundError, TypeError, ValueError) as exc:
                raise ValidationError("Methods invoice accounting evidence is unavailable") from exc
        for stage_id, context in self.context.items():
            panel = context.get("capability_repair_panel") if isinstance(context, dict) else None
            if not isinstance(panel, dict):
                continue
            usage = panel.get("usage")
            if not isinstance(usage, dict) or not any(usage.get(key, 0) for key in self.usage):
                continue
            ledger = panel.get("ledger")
            ledger = ledger if isinstance(ledger, dict) else {}
            try:
                digest = hashlib.sha256(canonical_bytes({
                    "stage_id": stage_id, "assignment_plan_ref": ledger["assignment_plan_ref"],
                })).hexdigest()
                if self.store.head(f"command/capability-repair-usage/{digest}") is not None:
                    self._record_capability_repair_panel_usage({"id": stage_id}, panel)
                    continue
                plan = self.store.get(ledger["assignment_plan_ref"])
                chief = self.store.get(ledger["chief_synthesis_ref"])
                chief_body = json.loads(self.store.read_body(chief["body_hash"]))
                chief_usage = chief_body["usage"]
                if any(chief_usage.get(key, 0) != usage.get(key, 0) for key in self.usage):
                    raise ValidationError("Methods invoice differs from its immutable synthesis")
                created = datetime.fromisoformat(plan["created_at"]).timestamp()
                record = self.stage_records.get(stage_id, {})
                attempt_ids = {item.get("attempt_id") for item in record.get("attempts", [])
                               if isinstance(item, dict)} | {record.get("attempt_id")}
                owners = []
                for attempt_id in attempt_ids - {None}:
                    attempt = self.tasks.get_attempt(attempt_id)
                    start = datetime.fromisoformat(attempt["created_at"]).timestamp()
                    end = (datetime.fromisoformat(attempt["finished_at"]).timestamp()
                           if attempt.get("finished_at") else None)
                    if start <= created:
                        owners.append((start, end, attempt))
                latest_start = max((item[0] for item in owners), default=None)
                owners = [item for item in owners if item[0] == latest_start
                          and (item[1] is None or created <= item[1])]
                if len(owners) != 1:
                    raise ValidationError("Methods invoice has no unique stage attempt owner")
                owner = owners[0][2]
                if owner["state"] in {"started", "result_unknown"}:
                    self._record_capability_repair_panel_usage({"id": stage_id}, panel)
                elif (owner["state"] == "failed"
                      and all(owner["usage"].get("actual", {}).get(key, 0) == usage.get(key, 0)
                              for key in self.usage)):
                    # A failed attempt consisting solely of this invoice has
                    # already settled its exact aggregate in the old owner.
                    self._record_capability_repair_panel_usage(
                        {"id": stage_id}, panel, already_charged=True)
                else:
                    raise ValidationError("legacy Methods invoice payment is ambiguous")
            except (KeyError, NotFoundError, TypeError, ValueError) as exc:
                raise ValidationError("Methods invoice accounting evidence is unavailable") from exc

    def _repair_panel_usage_total(self, stage_id):
        prefix = f"repair-panel:{stage_id}:"
        return {key: sum(totals.get(key, 0)
                         for namespace, totals in self.stage_usage_totals.items()
                         if namespace.startswith(prefix))
                for key in self.usage}

    def _repair_panel_invoice_owner(self, stage_id, invoice):
        """Bind immutable Methods costs to the unique containing parent attempt."""
        bodies, records = {}, {}
        for name, schema in (("assignment_plan_ref", "department-stage-assignment-1"),
                             ("chief_synthesis_ref", "department-chief-synthesis-1")):
            record = self.store.get(invoice[name])
            raw = self.store.read_body(record["body_hash"])
            body = json.loads(raw)
            if (hashlib.sha256(raw).hexdigest() != record["body_hash"]
                    or body.get("schema_version") != schema
                    or body.get("project_id") != self.workflow["project_id"]
                    or body.get("stage_kind") != "experiment"):
                raise ValidationError("Methods budget invoice has invalid immutable provenance")
            bodies[name], records[name] = body, record
        plan, chief = bodies["assignment_plan_ref"], bodies["chief_synthesis_ref"]
        panel_id = plan.get("stage_id")
        base = re.sub(r"[^a-z0-9-]+", "-", str(stage_id).casefold()).strip("-") or "experiment"
        suffix = ("-repair-panel-" + panel_id.rsplit("-repair-panel-", 1)[1]
                  if isinstance(panel_id, str) and "-repair-panel-" in panel_id else None)
        if (plan.get("stage_id") != chief.get("stage_id")
                or suffix is None or panel_id != base[:64 - len(suffix)] + suffix
                or plan.get("attempt_number") != chief.get("attempt_number")
                or any(chief.get("usage", {}).get(key, 0) != invoice["usage"].get(key, 0)
                       for key in self.usage)):
            raise ValidationError("Methods budget invoice differs from its immutable synthesis")
        start = datetime.fromisoformat(records["assignment_plan_ref"]["created_at"]).timestamp()
        finish = datetime.fromisoformat(records["chief_synthesis_ref"]["created_at"]).timestamp()
        if finish < start:
            raise ValidationError("Methods budget invoice has reversed provenance interval")
        record = self.stage_records.get(stage_id, {})
        candidates = {item.get("attempt_id"): item.get("cycle")
                      for item in record.get("attempts", []) if isinstance(item, dict)}
        if isinstance(record.get("attempt_id"), str):
            candidates.setdefault(record["attempt_id"], None)
        owners = []
        for attempt_id, cycle in candidates.items():
            if not isinstance(attempt_id, str):
                continue
            attempt = self.tasks.get_attempt(attempt_id)
            task = self.tasks.get(attempt["task_id"])
            opened = datetime.fromisoformat(attempt["created_at"]).timestamp()
            closed = (datetime.fromisoformat(attempt["finished_at"]).timestamp()
                      if attempt.get("finished_at") else None)
            if (attempt.get("lease_owner") == "command.composer"
                    and task.get("payload", {}).get("stage_id") == stage_id
                    and opened <= start):
                owners.append((opened, closed, attempt_id, cycle))
        latest = max((item[0] for item in owners), default=None)
        owners = [item for item in owners if item[0] == latest
                  and (item[1] is None or finish <= item[1])]
        if len(owners) != 1:
            raise ValidationError("Methods budget invoice has ambiguous parent attempt/cycle ownership")
        attempt_id, cycle = owners[0][2:]
        attempt = self.tasks.get_attempt(attempt_id)
        if "model_budget_cycle" in attempt.get("payload", {}):
            cycle = attempt["payload"]["model_budget_cycle"]
        elif invoice.get("model_budget_owner") is None:
            if cycle is not None and (type(cycle) is not int or cycle < 0):
                raise ValidationError("Methods budget invoice has invalid admitted cycle ownership")
            checkpoint_row = self.control._conn.execute(
                "SELECT body_hash FROM artifacts WHERE artifact_type='progress_checkpoint' "
                "AND logical_id LIKE 'command/composer/checkpoints/%' AND created_at>=? AND created_at<=? "
                "ORDER BY created_at ASC LIMIT 1", (attempt["created_at"], records["assignment_plan_ref"]["created_at"])).fetchone()
            checkpoint_raw = self.store.read_body(checkpoint_row["body_hash"]) if checkpoint_row else None
            if checkpoint_raw is not None and hashlib.sha256(checkpoint_raw).hexdigest() != checkpoint_row["body_hash"]:
                raise ValidationError("Methods budget admission checkpoint digest differs from its artifact")
            checkpoint = json.loads(checkpoint_raw) if checkpoint_raw is not None else None
            if (not isinstance(checkpoint, dict)
                    or checkpoint.get("schema_version") != "composer-checkpoint-1"
                    or checkpoint.get("workflow_id") != self.workflow["id"]
                    or checkpoint.get("stages", {}).get(stage_id, {}).get("attempt_id") != attempt_id):
                raise ValidationError("Methods budget invoice has ambiguous admitted cycle ownership")
            admitted_global_cycle = checkpoint.get("continuation_cycles")
            reopened = checkpoint.get("reopened_stage_ids")
            if (type(admitted_global_cycle) is not int or admitted_global_cycle < 0
                    or not isinstance(reopened, list)
                    or any(not isinstance(item, str) for item in reopened)):
                raise ValidationError("Methods budget invoice has invalid immutable admission scope")
            admitted_model_cycle = (admitted_global_cycle
                                    if stage_id in reopened else 0)
            if cycle is not None and cycle not in (admitted_global_cycle, admitted_model_cycle):
                raise ValidationError("Methods budget invoice has ambiguous admitted cycle ownership")
            cycle = admitted_model_cycle
        elif isinstance(invoice.get("model_budget_owner"), dict):
            cycle = invoice["model_budget_owner"].get("cycle")
        if type(cycle) is not int or cycle < 0:
            raise ValidationError("Methods budget invoice has invalid admitted cycle ownership")
        return {"attempt_id": attempt_id, "cycle": cycle,
                "cycle_pinned": "model_budget_cycle" in attempt.get("payload", {})}

    def _legacy_stage_model_invoices(self, stage_id, scope):
        """Return exact old-scope contributions belonging to this admitted window."""
        contributions = {}
        rows = self.control._conn.execute(
            "SELECT a.logical_id,a.body_hash FROM artifacts a JOIN "
            "(SELECT logical_id,MAX(version) version FROM artifacts "
            "WHERE logical_id LIKE 'command/capability-repair-usage/%' GROUP BY logical_id) h "
            "ON a.logical_id=h.logical_id AND a.version=h.version")
        for row in rows:
            raw = self.store.read_body(row["body_hash"])
            invoice = json.loads(raw)
            if invoice.get("stage_id") != stage_id:
                continue
            invoice_digest = hashlib.sha256(canonical_bytes({
                "stage_id": stage_id, "assignment_plan_ref": invoice.get("assignment_plan_ref")})).hexdigest()
            if (invoice.get("schema_version") != "capability-repair-usage-1"
                    or row["logical_id"] != f"command/capability-repair-usage/{invoice_digest}"):
                raise ValidationError("Methods budget invoice has invalid assignment identity")
            if hashlib.sha256(raw).hexdigest() != row["body_hash"]:
                raise ValidationError("Methods budget invoice digest differs from its artifact")
            owner = self._repair_panel_invoice_owner(stage_id, invoice)
            declared = invoice.get("model_budget_owner")
            expected_key = f"stage:{stage_id}:cycle:{owner['cycle']}"
            if declared is not None:
                bound = None
                plan_record = self.store.get(invoice["assignment_plan_ref"])
                plan_input = json.loads(self.store.read_body(plan_record["body_hash"])).get("input_ref", {})
                if isinstance(plan_input, dict) and isinstance(plan_input.get("ref"), str):
                    binding_record = self.store.get(plan_input["ref"])
                    binding_raw = self.store.read_body(binding_record["body_hash"])
                    if hashlib.sha256(binding_raw).hexdigest() != binding_record["body_hash"]:
                        raise ValidationError("Methods budget owner binding digest differs from its artifact")
                    binding = json.loads(binding_raw)
                    plan_body = json.loads(self.store.read_body(plan_record["body_hash"]))
                    if (binding.get("schema_version") != "capability-repair-budget-owner-1"
                            or binding.get("panel_stage_id") != plan_body.get("stage_id")
                            or binding.get("assignment_attempt_number") != plan_body.get("attempt_number")
                            or binding_record.get("author") != "command.composer"
                            or not self.tasks.get_attempt(owner["attempt_id"])["created_at"] <= binding_record["created_at"] <= plan_record["created_at"]):
                        raise ValidationError("Methods budget owner binding differs from its assignment")
                    bound = binding.get("model_budget_owner")
                declared_scope = declared.get("scope") if isinstance(declared, dict) else None
                if isinstance(declared_scope, dict):
                    validate_model_budget_scope(declared_scope)
                if (not isinstance(declared, dict) or set(declared) != {"scope", "attempt_id", "cycle"}
                        or type(declared.get("cycle")) is not int
                        or declared.get("cycle", -1) < 0
                        or declared.get("attempt_id") != owner["attempt_id"]
                        or bound != declared
                        or not isinstance(declared_scope, dict)
                        or (owner["cycle_pinned"] and declared.get("cycle") != owner["cycle"])
                        or declared_scope.get("model_call_budget_key") != f"stage:{stage_id}:cycle:{declared.get('cycle')}"
                        or declared_scope.get("model_call_budget_path") != scope["model_call_budget_path"]
                        or declared_scope.get("model_call_budget_limit") != scope["model_call_budget_limit"]
                        or declared_scope.get("model_token_budget_limits") != scope["model_token_budget_limits"]):
                    raise ValidationError("Methods budget invoice changes its admitted owner")
                continue
            if expected_key != scope["model_call_budget_key"]:
                continue
            usage = {key: invoice["usage"].get(key, 0)
                     for key in ("model_calls", "input_tokens", "output_tokens")}
            if any(type(value) is not int or value < 0 for value in usage.values()):
                raise ValidationError("Methods budget invoice has invalid physical usage")
            if not any(usage.values()):
                continue
            identity = invoice["assignment_plan_ref"]
            if identity in contributions and contributions[identity] != usage:
                raise ValidationError("Methods budget invoice changes an assignment's physical usage")
            contributions[identity] = usage
        return contributions

    @staticmethod
    def _legacy_stage_budget_projection(connection, scope, contributions):
        """Combine scoped HTTP rows with exact external costs without seed overlap."""
        key = scope["model_call_budget_key"]
        tables = {row[0] for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        physical = (connection.execute(
            "SELECT COUNT(*),COALESCE(SUM(observed_input),0),COALESCE(SUM(observed_output),0) "
            "FROM model_token_reservations WHERE budget_key=?", (key,)).fetchone()
            if "model_token_reservations" in tables else (0, 0, 0))
        prior = (connection.execute(
            "SELECT COALESCE(SUM(model_calls),0),COALESCE(SUM(input_tokens),0),"
            "COALESCE(SUM(output_tokens),0) FROM stage_model_budget_legacy_usage WHERE budget_key=?",
            (key,)).fetchone() if "stage_model_budget_legacy_usage" in tables else (0, 0, 0))
        if "stage_model_budget_legacy_usage" in tables:
            for row in connection.execute("SELECT invoice_id,model_calls,input_tokens,output_tokens "
                                          "FROM stage_model_budget_legacy_usage WHERE budget_key=?", (key,)):
                value = contributions.get(row[0])
                if value is None or tuple(value[name] for name in ("model_calls", "input_tokens", "output_tokens")) != tuple(row[1:]):
                    raise ValidationError("Methods budget migration lost its exact invoice provenance")
        if physical[0]:
            retained_ids = ({row[0] for row in connection.execute(
                "SELECT invoice_id FROM stage_model_budget_legacy_usage WHERE budget_key=?", (key,))}
                if "stage_model_budget_legacy_usage" in tables else set())
            if any(identity not in retained_ids for identity in contributions):
                raise ValidationError("Methods budget migration has ambiguous physical request overlap")
        calls = (connection.execute("SELECT used_calls FROM model_call_budgets WHERE budget_key=?", (key,)).fetchone()
                 if "model_call_budgets" in tables else None)
        tokens = (connection.execute("SELECT used_input,used_output FROM model_token_budgets WHERE budget_key=?", (key,)).fetchone()
                  if "model_token_budgets" in tables else None)
        recorded = (calls[0] if calls else 0, *(tokens or (0, 0)))
        if any(value > physical[i] + prior[i] for i, value in enumerate(recorded)):
            raise ValidationError("Methods budget migration has ambiguous preexisting seed ownership")
        dimensions = ("model_calls", "input_tokens", "output_tokens")
        return {name: physical[i] + sum(item[name] for item in contributions.values())
                for i, name in enumerate(dimensions)}

    def _restore_legacy_stage_model_budget(self, scope, contributions):
        if not contributions:
            return
        register_model_token_budget(scope)
        with closing(sqlite3.connect(scope["model_call_budget_path"], timeout=30)) as connection, connection:
            connection.execute("BEGIN IMMEDIATE")
            if connection.execute("SELECT 1 FROM sqlite_master WHERE name='model_call_budgets'").fetchone():
                limit = connection.execute("SELECT max_calls FROM model_call_budgets WHERE budget_key=?",
                                           (scope["model_call_budget_key"],)).fetchone()
                if limit is not None and limit[0] != scope["model_call_budget_limit"]:
                    raise ValidationError("persisted stage model-call limit changed")
            usage = self._legacy_stage_budget_projection(connection, scope, contributions)
            connection.execute("CREATE TABLE IF NOT EXISTS model_call_budgets "
                               "(budget_key TEXT PRIMARY KEY,max_calls INTEGER NOT NULL,used_calls INTEGER NOT NULL)")
            connection.execute("CREATE TABLE IF NOT EXISTS stage_model_budget_legacy_usage "
                "(budget_key TEXT NOT NULL,invoice_id TEXT NOT NULL,model_calls INTEGER NOT NULL,"
                "input_tokens INTEGER NOT NULL,output_tokens INTEGER NOT NULL,PRIMARY KEY(budget_key,invoice_id))")
            key = scope["model_call_budget_key"]
            for identity, value in contributions.items():
                prior = connection.execute("SELECT model_calls,input_tokens,output_tokens "
                    "FROM stage_model_budget_legacy_usage WHERE budget_key=? AND invoice_id=?", (key, identity)).fetchone()
                amounts = tuple(value[name] for name in ("model_calls", "input_tokens", "output_tokens"))
                if prior is not None and prior != amounts:
                    raise ValidationError("Methods budget migration changes a completed invoice")
                connection.execute("INSERT OR IGNORE INTO stage_model_budget_legacy_usage VALUES (?,?,?,?,?)",
                                   (key, identity, *amounts))
            connection.execute("INSERT INTO model_call_budgets VALUES (?,?,?) ON CONFLICT(budget_key) "
                "DO UPDATE SET used_calls=MAX(used_calls,excluded.used_calls)",
                (key, scope["model_call_budget_limit"], usage["model_calls"]))
            connection.execute("UPDATE model_token_budgets SET used_input=MAX(used_input,?),used_output=MAX(used_output,?) "
                               "WHERE budget_key=?", (usage["input_tokens"], usage["output_tokens"], key))

    def _merge_incremental_error_usage(self, error, incremental_usage):
        """Attach newly consumed work without charging a restored usage snapshot."""
        if not isinstance(incremental_usage, dict):
            return error
        existing = getattr(error, "usage", None)
        usage = ({} if getattr(error, "usage_is_snapshot", False)
                 else deepcopy(existing) if isinstance(existing, dict) else {})
        for key in self.usage:
            amount = incremental_usage.get(key, 0)
            if type(amount) not in (int, float) or not math.isfinite(amount) or amount < 0:
                continue
            current = usage.get(key, 0)
            if type(current) not in (int, float) or not math.isfinite(current) or current < 0:
                current = 0
            usage[key] = current + amount
        error.usage = usage
        error.usage_is_snapshot = False
        return error

    def _sync_foundry_usage(self):
        """Reconcile durable per-request charges with the last usage checkpoint."""
        totals = {}
        rows = self.control._conn.execute(
            "SELECT a.body_hash FROM artifacts a JOIN "
            "(SELECT logical_id,MAX(version) version FROM artifacts "
            "WHERE logical_id LIKE 'command/foundry-work/%' GROUP BY logical_id) h "
            "ON a.logical_id=h.logical_id AND a.version=h.version")
        for row in rows:
            body = json.loads(self.store.read_body(row["body_hash"]))
            for key, amount in body.get("usage", {}).items():
                if key in self.usage and type(amount) in (int, float) and math.isfinite(amount) and amount >= 0:
                    totals[key] = totals.get(key, 0) + amount
        incremental_usage = {}
        for key, total in totals.items():
            delta = total - self.foundry_usage.get(key, 0)
            if delta < 0:
                raise ValidationError("foundry usage ledger regressed below its recorded checkpoint")
            incremental_usage[key] = delta
        self._settle_pending_stage_usage(
            additional_usage=incremental_usage, settle_pending=False, foundry_totals=totals)
        return any(incremental_usage.values())

    def _duplicate_foundry_settlement_proofs(self):
        """Find repeated global payments whose complete owner costs are immutable."""
        keys = ("model_calls", "input_tokens", "output_tokens")
        def amounts(value):
            if not isinstance(value, dict):
                raise ValidationError("settlement evidence has invalid usage")
            result = {key: value.get(key, 0) for key in keys}
            if any(type(v) is not int or v < 0 for v in result.values()):
                raise ValidationError("settlement evidence has invalid usage")
            return result
        def difference(left, right):
            result = {key: amounts(left)[key] - amounts(right)[key] for key in keys}
            if any(v < 0 for v in result.values()):
                raise ValidationError("settlement evidence regresses")
            return result
        def plus(left, right):
            return {key: left[key] + right[key] for key in keys}
        rows = self.control._conn.execute(
            "SELECT artifact_ref,created_at FROM artifacts WHERE artifact_type='progress_checkpoint' "
            "AND logical_id LIKE 'command/composer/checkpoints/%' ORDER BY created_at,artifact_ref").fetchall()
        checkpoints = []
        for row in rows:
            manifest, digest, body = self._read_verified_artifact_json(row["artifact_ref"])
            if (manifest.get("author") == "command.composer"
                    and body.get("schema_version") == "composer-checkpoint-1"
                    and body.get("workflow_id") == self.workflow["id"]):
                checkpoints.append((manifest, digest, body))
        foundry_rows = self.control._conn.execute(
            "SELECT artifact_ref,created_at FROM artifacts WHERE logical_id LIKE 'command/foundry-work/%' "
            "ORDER BY created_at,version").fetchall()
        foundry = [self._read_verified_artifact_json(row["artifact_ref"]) for row in foundry_rows]
        def heads(at):
            result = {}
            for manifest, digest, body in foundry:
                if manifest["created_at"] <= at:
                    result[manifest["artifact_id"]] = (manifest, digest, body)
            return result
        def invoices(previous, current, stage_id, owner):
            refs, total = [], {key: 0 for key in keys}
            old, new = previous.get("stage_usage_totals", {}), current.get("stage_usage_totals", {})
            for name, value in new.items():
                if not name.startswith(f"repair-panel:{stage_id}:"):
                    continue
                delta = difference(value, old.get(name, {}))
                if not any(delta.values()):
                    continue
                ref = self.store.head("command/capability-repair-usage/" + name.rsplit(":", 1)[1])
                if ref is None:
                    raise ValidationError("settlement lacks its paid Methods invoice")
                manifest, digest, invoice = self._read_verified_artifact_json(ref["artifact_ref"])
                plan_manifest, _, plan = self._read_verified_artifact_json(invoice["assignment_plan_ref"])
                _, _, chief = self._read_verified_artifact_json(invoice["chief_synthesis_ref"])
                if (invoice.get("schema_version") != "capability-repair-usage-1"
                        or invoice.get("stage_id") != stage_id or amounts(invoice["usage"]) != amounts(value)
                        or chief.get("schema_version") != "department-chief-synthesis-1"
                        or plan.get("schema_version") != "department-stage-assignment-1"
                        or plan.get("project_id") != self.workflow["project_id"]
                        or chief.get("project_id") != self.workflow["project_id"]
                        or chief.get("stage_id") != plan.get("stage_id")
                        or chief.get("attempt_number") != plan.get("attempt_number")
                        or amounts(chief["usage"]) != amounts(value)
                        or not owner["created_at"] <= plan_manifest["created_at"] <= owner["finished_at"]):
                    raise ValidationError("settlement Methods invoice changes owner costs")
                refs.append({"ref": manifest["artifact_ref"], "sha256": digest})
                total = plus(total, delta)
            return total, refs
        def physical_reviews(start_at, end_at, stage_id, owner, paid_invoices):
            total, refs = {key: 0 for key in keys}, []
            paid_assignments = set()
            for item in paid_invoices:
                invoice = self._read_verified_artifact_json(item["ref"])[2]
                plan = self._read_verified_artifact_json(invoice["assignment_plan_ref"])[2]
                paid_assignments.add((plan["stage_id"], plan["attempt_number"]))
            rows = self.control._conn.execute(
                "SELECT artifact_ref FROM artifacts WHERE logical_id LIKE "
                "'command/departments/methods/assignments/%/execution' "
                "AND created_at>? AND created_at<=?", (start_at, end_at)).fetchall()
            for row in rows:
                manifest, digest, body = self._read_verified_artifact_json(row["artifact_ref"])
                report = body.get("report", {})
                if (body.get("stage_id"), body.get("attempt_number")) in paid_assignments:
                    continue
                if (report.get("provider_call_reused") is True
                        or not any(amounts(report.get("usage", {})).values())):
                    continue
                task = self.tasks.get(body["task_id"])
                payload = task.get("payload", {})
                physical = self.tasks.get_attempt(payload["attempt_id"])
                base = re.sub(r"[^a-z0-9-]+", "-", stage_id.casefold()).strip("-")
                panel_id = body.get("stage_id", "")
                if (body.get("schema_version") not in {"specialist-execution-1", "specialist-verifier-execution-1"}
                        or body.get("project_id") != self.workflow["project_id"]
                        or not panel_id.startswith(base + "-repair-panel-")
                        or payload.get("stage_id") != panel_id
                        or payload.get("assigned_role") != body.get("assigned_role")
                        or payload.get("assignment_id") != body.get("assignment_id")
                        or manifest.get("author") != body.get("assigned_role")
                        or physical.get("task_id") != body.get("task_id")
                        or physical.get("state") not in {"succeeded", "failed"}
                        or amounts(physical.get("usage", {}).get("actual", {})) != amounts(report["usage"])
                        or not owner["created_at"] <= manifest["created_at"] <= owner["finished_at"]):
                    raise ValidationError("unattributed physical review at a foundry settlement")
                refs.append({"ref": manifest["artifact_ref"], "sha256": digest})
                total = plus(total, amounts(report["usage"]))
            return total, refs
        proofs = []
        for index, (bm, bh, before) in enumerate(checkpoints[:-1]):
            phase = before.get("phase", "")
            if not phase.endswith(":capability_validation_failed"):
                continue
            stage_id = phase.rsplit(":", 1)[0]
            am, ah, after = checkpoints[index + 1]
            if after.get("phase") not in {f"{stage_id}:failed", f"{stage_id}:retrying"}:
                continue
            br, ar = before.get("stages", {}).get(stage_id, {}), after.get("stages", {}).get(stage_id, {})
            attempt_id = br.get("attempt_id")
            if not attempt_id or ar.get("attempt_id") != attempt_id:
                continue
            starts = [item for item in checkpoints[:index + 1]
                      if item[2].get("phase") == f"{stage_id}:admitted"
                      and item[2].get("stages", {}).get(stage_id, {}).get("attempt_id") == attempt_id]
            if len(starts) != 1:
                continue
            sm, sh, start = starts[0]
            owner = self.tasks.get_attempt(attempt_id)
            task = self.tasks.get(owner["task_id"])
            if (owner.get("state") != "failed" or not owner.get("finished_at")
                    or task.get("payload", {}).get("stage_id") != stage_id
                    or not owner["created_at"] <= sm["created_at"] <= bm["created_at"] <= am["created_at"]):
                continue
            try:
                paid = difference(before.get("foundry_usage", {}), start.get("foundry_usage", {}))
                if not any(paid.values()) or amounts(before.get("foundry_usage", {})) != amounts(after.get("foundry_usage", {})):
                    continue
                old_heads, paid_heads = heads(sm["created_at"]), heads(bm["created_at"])
                head_delta, head_proof = {key: 0 for key in keys}, []
                for logical, (manifest, digest, body) in paid_heads.items():
                    old = old_heads.get(logical)
                    delta = difference(body.get("usage", {}), old[2].get("usage", {}) if old else {})
                    if any(delta.values()):
                        if not owner["created_at"] <= manifest["created_at"] <= bm["created_at"]:
                            raise ValidationError("foundry payment lies outside its owner interval")
                        head_delta = plus(head_delta, delta)
                        head_proof.append({"ref": manifest["artifact_ref"], "sha256": digest,
                                           "previous_ref": old[0]["artifact_ref"] if old else None,
                                           "usage": delta})
                if head_delta != paid:
                    continue
                pre_other, pre_refs = invoices(start, before, stage_id, owner)
                post_other, post_refs = invoices(before, after, stage_id, owner)
                pre = difference(before["usage"], start["usage"])
                closure = difference(after["usage"], before["usage"])
                if closure != plus(paid, post_other) and not any(post_other.values()):
                    post_other, post_refs = physical_reviews(sm["created_at"], am["created_at"], stage_id, owner, pre_refs)
                recorded = next((item.get("usage") for item in ar.get("attempts", [])
                                 if item.get("attempt_id") == attempt_id), ar.get("usage"))
                if (pre != plus(paid, pre_other) or closure != plus(paid, post_other)
                        or amounts(recorded) != plus(pre, closure)
                        or amounts(owner.get("usage", {}).get("actual", {})) != amounts(recorded)):
                    continue
                proofs.append({"schema_version": "composer-accounting-correction-1",
                    "stage_id": stage_id, "attempt_id": attempt_id,
                    "checkpoint_refs": [{"ref": m["artifact_ref"], "sha256": h}
                                        for m, h in ((sm, sh), (bm, bh), (am, ah))],
                    "foundry_heads": head_proof, "other_invoices": pre_refs + post_refs,
                    "duplicate_usage": paid})
            except (KeyError, TypeError, ValueError, NotFoundError, ValidationError):
                # Incomplete or concurrent ownership cannot prove a refund.
                continue
        return proofs

    def _reconcile_duplicate_foundry_settlements(self):
        """Correct proven repeated global payments without altering physical quotas."""
        changed = False
        for proof in self._duplicate_foundry_settlement_proofs():
            identity = {"stage_id": proof["stage_id"], "attempt_id": proof["attempt_id"],
                        "closing_checkpoint": proof["checkpoint_refs"][-1]}
            digest = hashlib.sha256(canonical_bytes(identity)).hexdigest()
            namespace = f"accounting-correction:{digest}"
            logical = f"command/accounting-corrections/{digest}"
            record = self.store.head(logical)
            if record is not None and self._read_verified_artifact_json(record["artifact_ref"])[2] != proof:
                raise ValidationError("accounting correction changes its immutable proof")
            if namespace in self.stage_usage_totals:
                if self.stage_usage_totals[namespace] != proof["duplicate_usage"]:
                    raise ValidationError("accounting correction changes a settled proof")
                continue
            subjects = [item["ref"] for item in proof["checkpoint_refs"] + proof["foundry_heads"] + proof["other_invoices"]]
            if record is None:
                self._publish(logical, "note", proof, "command.composer", subjects=subjects)
            elif self._read_verified_artifact_json(record["artifact_ref"])[2] != proof:
                raise ValidationError("accounting correction changes its immutable proof")
            with self._progress_lock:
                state = deepcopy(self._accounting_state)
                for key, amount in proof["duplicate_usage"].items():
                    if state["usage"].get(key, 0) < amount:
                        raise ValidationError("accounting correction exceeds observed global usage")
                    state["usage"][key] -= amount
                state["stage_usage_totals"][namespace] = deepcopy(proof["duplicate_usage"])
                self._accounting_state = state
            changed = True
        return changed

    @staticmethod
    def _usage_delta(current, baseline):
        current = current if isinstance(current, dict) else {}
        baseline = baseline if isinstance(baseline, dict) else {}
        return {
            key: max(0, current.get(key, 0) - baseline.get(key, 0))
            for key in ("model_calls", "input_tokens", "output_tokens")
            if type(current.get(key, 0)) in (int, float)
            and type(baseline.get(key, 0)) in (int, float)
        }

    def _foundry_model_call_budget(self, stage, *, repair_panel_usage=None):
        """Reserve foundry calls inside the experiment stage envelope.

        Experiment production runs before its stage reviewers. Reports carried
        into a reopened work order therefore belong to an earlier attempt and
        are already accounted for by that attempt's usage ledger (or are reused
        with zero new usage). Before a repair panel runs, reserve its configured
        worst case. Once it completes, replace that reservation with the calls
        actually dispatched so unused panel capacity can fund the capability
        author and its independent admission review without exceeding the stage
        envelope.
        """
        if not self.workflow.get("capability_foundry_config_path"):
            return None
        quota = stage.get("quota") if isinstance(stage, dict) else None
        if not isinstance(quota, dict) or type(quota.get("max_model_calls")) is not int:
            return AUTONOMOUS_FOUNDRY_MODEL_CALL_LIMIT
        prior = self._stage_usage(stage["id"]).get("model_calls", 0)
        panel_required = self._capability_repair_panel_required(stage)
        if repair_panel_usage is None:
            repair_panel_reserve = (
                self._capability_repair_panel_model_call_reserve(stage)
                if panel_required else 0
            )
        else:
            panel_calls = repair_panel_usage.get("model_calls") \
                if isinstance(repair_panel_usage, dict) else None
            if type(panel_calls) is int and panel_calls >= 0:
                repair_panel_reserve = panel_calls
            elif panel_required:
                repair_panel_reserve = self._capability_repair_panel_model_call_reserve(stage)
            else:
                repair_panel_reserve = 0
        available = quota["max_model_calls"] - prior \
            - FOUNDRY_VERIFIER_MODEL_CALL_RESERVE - repair_panel_reserve
        return max(0, min(AUTONOMOUS_FOUNDRY_MODEL_CALL_LIMIT, available))

    def _capability_repair_panel_model_call_reserve(self, stage):
        """Reserve the configured Methods and verifier call ceilings, not a stale constant."""
        route = self.departments.stage_route(stage.get("kind", "experiment"))
        department = route["department"]
        appointments = list(route.get("required_roles", []))
        verifier = self.departments._resolve_assignment(department, "adversary")
        appointments.append(verifier)
        return sum(
            appointment["quota"]["max_calls"]
            for appointment in appointments
            if appointment.get("execution_kind") in {"model", "review"}
            and isinstance(appointment.get("quota"), dict)
            and type(appointment["quota"].get("max_calls")) is int
        )

    def _capability_repair_panel_required(self, stage):
        """Return whether a fresh capability needs an upper-model design panel."""
        if not isinstance(stage, dict) or stage.get("kind") != "experiment":
            return False
        context = self.context.get(stage.get("id"), {})
        context = context if isinstance(context, dict) else {}
        recovery = context.get("failure_recovery")
        if (isinstance(recovery, dict)
                and recovery.get("failure_class") == "evidence_input_unavailable"):
            return False
        error = context.get("error")
        if self._is_pre_execution_capability_failure(stage, context, error):
            return True
        # ``context`` is the previous attempt. The current stage record already
        # points at a new, empty attempt directory, so scoping this lookup to it
        # would hide the result that makes this a substantive repair.
        if not self._has_executed_experiment_result(
                context, self._stage_experiment_capability_id(stage)):
            return False
        requests = self._requests_for_stage(stage)
        substantive_repair = any(
            isinstance(item, dict)
            and item.get("kind") in EXPERIMENT_WORK_ORDER_KINDS
            for item in requests
        )
        if not substantive_repair:
            return False
        return (
            context.get("status") in STAGE_HOLD_STATUSES
            or context.get("review_status") == "scientific_assignment_blocked"
            or isinstance(context.get("failure_debt"), dict)
            or context.get("backfill_required") is True
        )

    def _foundry_progress(self, stage_id, phase, state):
        self._sync_foundry_usage()
        self._checkpoint(f"{stage_id}:capability_{phase}", force=True)

    def _verified_source_data_manifest(self, stage_id):
        """Return only current survey data whose immutable source blobs verify."""
        if not isinstance(stage_id, str):
            return None
        stages = {
            item.get("id"): item for item in self.workflow.get("stages", [])
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        }
        experiment_stage = stages.get(stage_id)
        if not isinstance(experiment_stage, dict):
            return None
        ancestors = self._stage_ancestor_ids(experiment_stage)
        manifests = []
        for ancestor_id in ancestors:
            if stages.get(ancestor_id, {}).get("kind") != "survey":
                continue
            context = self.context.get(ancestor_id)
            if (not isinstance(context, dict)
                    or context.get("survey_current") is not True
                    or context.get("assessment_current") is not True):
                continue
            manifest = context.get("source_data_manifest")
            if manifest is not None:
                manifests.append(manifest)
        if not manifests:
            return None
        if len(manifests) != 1:
            from scisaurus.runtime.capability_foundry import SourceDataUnavailable
            raise SourceDataUnavailable(
                "current survey provides multiple source-data manifests; resolve them into one "
                "explicit, lineage-bound dataset before experiment authoring")
        from scisaurus.runtime.capability_foundry import (
            SourceDataUnavailable, _validate_source_data_manifest,
        )
        manifest = manifests[0]
        try:
            _validate_source_data_manifest(manifest)
            for dataset in manifest["datasets"]:
                source_record = self.store.get(dataset["artifact_ref"])
                body_hash = source_record.get("body_hash")
                if not isinstance(body_hash, str):
                    raise ValidationError("source artifact has no immutable body hash")
                source_body = self.store.read_body(body_hash)
                observed_hash = hashlib.sha256(source_body).hexdigest()
                if (observed_hash != dataset["source_sha256"]
                        or body_hash != dataset["source_sha256"]):
                    raise ValidationError("source artifact digest does not match the manifest")
        except (NotFoundError, OSError, ValidationError, TypeError, KeyError) as exc:
            raise SourceDataUnavailable(
                "current survey source-data manifest is invalid or does not resolve to its "
                "immutable source artifact; do not substitute model-generated values") from exc
        return deepcopy(manifest)

    @staticmethod
    def _topic_maturity_requirement_scope(topic, topic_context):
        """Project only reviewer requirements that still apply to this evidence scope."""
        topic_context = topic_context if isinstance(topic_context, dict) else {}
        requirements = topic_context.get("maturity_open_requirements", [])
        evolution = topic_context.get("topic_evolution")
        evolution = evolution if isinstance(evolution, dict) else {}
        changed_dimensions = evolution.get("changed_dimensions", [])
        changed_dimensions = set(
            item for item in changed_dimensions if isinstance(item, str)
        ) if isinstance(changed_dimensions, list) else set()
        evidence_boundary_changed = (
            evolution.get("mode") in {"refinement", "pivot"}
            and bool(changed_dimensions.intersection({
                "evidence_mode", "data_regime", "measurement",
            }))
        )
        return scope_maturity_requirements_to_topic_evidence(
            topic, requirements,
            evidence_boundary_changed=evidence_boundary_changed,
        )

    @staticmethod
    def _topic_requires_source_data(topic, topic_context):
        """Detect empirical values required by the current topic, not its retired parent."""
        requirement_scope = ComposerRunner._topic_maturity_requirement_scope(
            topic, topic_context)
        return topic_requires_source_data(
            topic, additional_requirements=requirement_scope["active"])

    def _stage_usage_baseline(self, project_dir):
        namespace = hashlib.sha256(str(Path(project_dir).resolve()).encode()).hexdigest()
        if namespace in self.stage_usage_totals:
            return namespace, self.stage_usage_totals[namespace]
        record = self.store.head(f"command/stage-usage/{namespace}")
        prior = json.loads(self.store.read_body(record["body_hash"])) if record else {}
        return namespace, prior

    def _incremental_stage_usage(self, stage, usage):
        """Defer baseline advancement until the corresponding cost is settled."""
        if not isinstance(usage, dict) or not isinstance(usage.get("cumulative_usage"), dict):
            return usage
        totals = {key: value for key, value in usage["cumulative_usage"].items()
                  if type(value) in (int, float) and math.isfinite(value) and value >= 0}
        namespace, prior = self._stage_usage_baseline(stage["project_dir"])
        totals = {**prior, **{key: max(value, prior.get(key, 0))
                             for key, value in totals.items()}}
        delta = {key: max(0, value - prior.get(key, 0)) for key, value in totals.items()}
        self.pending_stage_usage[namespace] = {"stage_id": stage["id"],
                                               "totals": totals, "delta": delta}
        return delta

    def _settle_pending_stage_usage(self, stage_id=None, *, already_charged=False,
                                    additional_usage=None, settle_pending=True, foundry_totals=None,
                                    namespaces=None):
        """Commit costs and replay baselines as one interrupt-safe state swap."""
        original = self._accounting_state

        def commit():
            state = deepcopy(original)
            if foundry_totals is not None:
                state["foundry_usage"] = deepcopy(foundry_totals)
            for key, amount in (additional_usage or {}).items():
                if key in state["usage"]:
                    state["usage"][key] += amount
            settled_stages = []
            for namespace, pending in (list(state["pending_stage_usage"].items()) if settle_pending else []):
                if namespaces is not None and namespace not in namespaces:
                    continue
                if stage_id is not None and pending["stage_id"] != stage_id:
                    continue
                if not already_charged:
                    committed = state["stage_usage_totals"].get(namespace, {})
                    for key in state["usage"]:
                        delta = pending["delta"].get(key, 0)
                        if key in committed:
                            delta = max(0, pending["totals"].get(key, committed[key]) - committed[key])
                        state["usage"][key] += delta
                state["stage_usage_totals"][namespace] = deepcopy(pending["totals"])
                del state["pending_stage_usage"][namespace]
                settled_stages.append(pending["stage_id"])
            with self._progress_lock:
                self._accounting_state = state
            return settled_stages

        try:
            settled_stages = commit()
        except KeyboardInterrupt:
            if self._accounting_state is original:
                commit()
            raise
        for settled_stage in settled_stages:
            self._clear_child_progress(settled_stage)

    def _end_child_activity(self, stage_id):
        with self._progress_lock:
            child = self._child_progress.get(stage_id)
            if child:
                child["activity_active"] = False

    @staticmethod
    def _topic_attempt_usage(attempt):
        """Return the topic runner usage for one attempt, excluding reviewers.

        A successful Composer attempt stores both the core topic intake and
        the independently admitted specialist pool in ``usage``.  The topic
        descriptor's intake quota governs the runner itself, so prefer its
        explicit budget snapshot and fall back to the durable output for
        checkpoints written before that field existed.
        """
        if not isinstance(attempt, dict):
            return {}
        direct = attempt.get("topic_usage")
        if isinstance(direct, dict):
            return direct
        project_dir = attempt.get("project_dir")
        if isinstance(project_dir, str):
            output = Path(project_dir) / "topic-discovery.json"
            if output.is_file():
                try:
                    body = json.loads(output.read_text())
                except (OSError, TypeError, ValueError):
                    body = None
                if isinstance(body, dict) and isinstance(body.get("budget"), dict):
                    usage = body["budget"].get("usage")
                    if isinstance(usage, dict):
                        return usage
        usage = attempt.get("usage")
        return usage if isinstance(usage, dict) else {}

    @classmethod
    def _sum_topic_attempt_usage(cls, attempts, *, scope="all", cycle=None,
                                 include_stage_work=False):
        """Sum observed topic work for one bounded admission scope.

        Initial intake retries share one envelope.  Each continuation is a
        separate, deliberately admitted scientific pivot and gets its own
        envelope; otherwise a legacy run with many historical pivots could
        make every newly admitted direction fail before it is evaluated. The
        immutable workflow deadline and provider/model ledgers still bound the
        mission as a whole. Missing usage is treated as zero here; an
        interrupted provider call is reconciled separately by the
        stage/task lease machinery.
        """
        totals = {
            "model_calls": 0,
            "input_tokens": 0,
            "output_tokens": 0,
            "openalex_requests": 0,
        }
        if not isinstance(attempts, list):
            return totals
        selected_cycle = cycle
        if scope == "continuation" and selected_cycle is None:
            positive_cycles = [
                item.get("cycle") for item in attempts
                if isinstance(item, dict) and isinstance(item.get("cycle"), int)
                and item.get("cycle") > 0
            ]
            selected_cycle = max(positive_cycles) if positive_cycles else None
        for attempt in attempts:
            if not isinstance(attempt, dict):
                continue
            attempt_cycle = attempt.get("cycle", 0)
            if scope == "intake" and attempt_cycle not in (None, 0):
                continue
            if scope == "continuation" and attempt_cycle != selected_cycle:
                continue
            usage = cls._topic_attempt_usage(attempt)
            if include_stage_work:
                aggregate = attempt.get("usage")
                if isinstance(aggregate, dict):
                    usage = {
                        key: max(
                            aggregate.get(key, 0)
                            if type(aggregate.get(key, 0)) in (int, float)
                            and math.isfinite(aggregate.get(key, 0))
                            and aggregate.get(key, 0) >= 0 else 0,
                            usage.get(key, 0)
                            if type(usage.get(key, 0)) in (int, float)
                            and math.isfinite(usage.get(key, 0))
                            and usage.get(key, 0) >= 0 else 0,
                        )
                        for key in totals
                    }
            for key in totals:
                value = usage.get(key, 0)
                if type(value) in (int, float) and math.isfinite(value) and value >= 0:
                    totals[key] += value
        return totals

    def _topic_budgets_for_attempt(self, stage_id, configured_budgets, *, scope="intake",
                                   current_usage=None, reserved_usage=None):
        """Return the remaining scoped budget for one fresh topic intake.

        The topic runner's bounded repair budget is intentionally local so a
        rejected direction can be abandoned cleanly. The Composer carries a
        separate workflow-level ceiling for initial intake and each deliberate
        continuation pivot. The immutable deadline and provider/model ledgers
        remain the mission-wide guardrails while each pivot retains a real
        bounded repair path after a reviewer hold.
        """
        if not isinstance(configured_budgets, dict) or not configured_budgets:
            return configured_budgets
        record = self.stage_records.get(stage_id, {})
        budget_cycle = self.continuation_cycles if scope == "continuation" else None
        observed = self._sum_topic_attempt_usage(
            record.get("attempts", []), scope=scope, cycle=budget_cycle)
        stage_observed = self._sum_topic_attempt_usage(
            record.get("attempts", []), scope=scope, cycle=budget_cycle,
            include_stage_work=True)
        current_usage = current_usage if isinstance(current_usage, dict) else {}
        reserved_usage = reserved_usage if isinstance(reserved_usage, dict) else {}
        usage_by_budget = {
            "max_model_calls": "model_calls",
            "max_openalex_requests": "openalex_requests",
            "max_input_tokens": "input_tokens",
            "max_output_tokens": "output_tokens",
        }
        remaining = deepcopy(configured_budgets)
        stage = next((item for item in self.workflow.get("stages", [])
                      if isinstance(item, dict) and item.get("id") == stage_id), None)
        stage_quota = stage.get("quota") if isinstance(stage, dict) else None
        for budget_key, usage_key in usage_by_budget.items():
            if budget_key not in configured_budgets:
                continue
            if budget_key in MODEL_COST_LIMITS and not enforce_model_cost_limits():
                continue
            limit = configured_budgets[budget_key]
            used = observed[usage_key]
            available = limit - used
            if isinstance(stage_quota, dict) and budget_key in stage_quota:
                stage_used = stage_observed[usage_key]
                for projection in (current_usage, reserved_usage):
                    value = projection.get(usage_key, 0)
                    if (type(value) in (int, float) and math.isfinite(value)
                            and value >= 0):
                        stage_used += value
                available = min(available, stage_quota[budget_key] - stage_used)
                used = max(used, stage_used)
            if available < 1:
                diagnostics = [{
                    "kind": "composer_topic_budget",
                    "stage_id": stage_id,
                    "dimension": usage_key,
                    "limit": limit,
                    "observed": used,
                    "scope": (
                        f"continuation_cycle:{budget_cycle}"
                        if scope == "continuation" else "intake"
                    ),
                }]
                quota_error = QuotaExceededError(
                    "topic discovery mission quota exhausted: "
                    f"{usage_key}={used}, limit={limit}",
                    dimension=usage_key,
                    limit=limit,
                    observed=used,
                    # ``observed`` is a diagnostic snapshot, not consumption
                    # caused by the attempted admission itself.
                    usage={},
                    diagnostics=diagnostics,
                )
                quota_error.usage_is_snapshot = True
                quota_error.topic_budget_scope = scope
                raise quota_error
            remaining[budget_key] = int(available)
        return remaining

    @staticmethod
    def _topic_review_reservation(stage_assignment):
        """Reserve all model-backed topic reviewers before producer dispatch."""
        assignments = (stage_assignment.get("assignments", [])
                       if isinstance(stage_assignment, dict) else [])
        reservation = {}
        phases = {"specialist", "verifier"}
        usage_fields = {
            "max_calls": "model_calls",
            "max_input_tokens": "input_tokens",
            "max_output_tokens": "output_tokens",
        }
        for assignment in assignments:
            if (not isinstance(assignment, dict)
                    or assignment.get("assignment_phase") not in phases
                    or assignment.get("execution_kind") not in {"model", "review"}):
                continue
            quota = assignment.get("quota")
            if not isinstance(quota, dict):
                continue
            for source, target in usage_fields.items():
                value = quota.get(source)
                if type(value) is int and value > 0:
                    reservation[target] = reservation.get(target, 0) + value
        return reservation

    @staticmethod
    def _is_topic_intake_retry(error, stage):
        """Return whether a topic intake has an autonomous retry path."""
        return (
            not isinstance(error, PROVIDER_OPERATOR_STOP_ERRORS)
            and stage.get("kind") == "topic_discovery"
            and bool(getattr(error, "retryable_topic_intake", False))
        )

    @staticmethod
    def _normalize_topic_intake_failure(error, stage):
        """Preserve topic-repair classification across every runner boundary.

        A topic validation can be raised after the runner has assembled its
        result (for example while materializing the conditional research
        program) or before the runner's local exception boundary. Execution
        inventory errors are repairable contract failures, never evidence to
        reject or replace the scientific question.
        """
        if stage.get("kind") != "topic_discovery":
            return error
        if isinstance(error, (*PROVIDER_OPERATOR_STOP_ERRORS, ProviderCooldownError)):
            return error
        if getattr(error, "retryable_topic_intake", False):
            return error
        rejection_type = _topic_validation_rejection_type(error)
        if rejection_type not in {
                "feasibility_contract", "novelty", "refinement_contract"}:
            return error
        setattr(error, "retryable_topic_intake", True)
        setattr(error, "topic_intake_recoverable", True)
        setattr(
            error, "topic_retry_reason",
            "refinement_contract_failure" if rejection_type == "refinement_contract"
            else ("intake_contract_failure"
                  if rejection_type == "feasibility_contract"
                  else "scientific_candidate_rejected"),
        )
        return error

    @staticmethod
    def _is_local_topic_budget_exhaustion(error, stage):
        """Distinguish a Composer topic envelope from a provider quota.

        A topic envelope is intentionally finite for one exploration cycle. It
        must open a fresh bounded continuation without treating exhausted
        capacity as evidence against the selected topic. Provider/model quotas
        remain hard resource fences and do not match this predicate.
        """
        if (stage.get("kind") != "topic_discovery"
                or isinstance(error, PROVIDER_OPERATOR_STOP_ERRORS)):
            return False
        # Candidate/contract rejection is wrapped in QuotaExceededError only
        # to carry the bounded intake usage snapshot.  It is not permission to
        # reset the same local budget and repeat the same proposal portfolio.
        if getattr(error, "retryable_topic_intake", False):
            return False
        if isinstance(error, QuotaExceededError):
            if getattr(error, "topic_budget_scope", None) in {"intake", "continuation"}:
                return True
            diagnostics = getattr(error, "diagnostics", None)
            if isinstance(diagnostics, list) and any(
                    isinstance(item, dict) and item.get("kind") == "composer_topic_budget"
                    for item in diagnostics):
                return True
        return "topic discovery quota exhausted" in str(error).casefold()

    def _topic_budget_recovery_request(self, stage, context, error, *, next_cycle):
        """Resume the admitted topic's evidence path after a local budget reset."""
        topic = context.get("topic") if isinstance(context, dict) else None
        topic = topic if isinstance(topic, dict) else None
        has_topic_identity = (
            isinstance(topic, dict)
            and isinstance(topic.get("id"), str)
            and topic.get("id").strip()
        )
        admitted = (
            has_topic_identity
            and (
                context.get("admission_state") in {
                    "provisional_for_survey", "provisional_supported_for_experiment",
                    "admitted",
                }
                or context.get("status") in {"completed", "accepted"}
            )
        )
        survey_stage = next((candidate for candidate in self.workflow.get("stages", [])
                             if candidate.get("kind") == "survey"
                             and self._topic_stage_for_survey(candidate) == stage), None)
        survey = self._survey_context_for_topic(stage) if survey_stage else {}
        topic_label = (
            f"{topic.get('id')}: {topic.get('research_question') or topic.get('title') or 'selected topic'}"
            if has_topic_identity else "no topic had been admitted before the local envelope ended"
        )
        evidence = [
            "The topic-stage local allocation was exhausted; this is a resource boundary, not a scientific rejection.",
            "Retained direction: " + topic_label,
            "Continuation cycle: " + str(next_cycle),
        ]
        if isinstance(survey, dict):
            for key in ("gap_state", "survey_ref", "assessment_ref"):
                value = survey.get(key)
                if isinstance(value, str) and value.strip():
                    evidence.append(f"Existing survey {key}: {value.strip()}")
        error_text = str(error).strip()
        if error_text:
            evidence.append("Budget diagnostic: " + error_text[:900])

        request_id = f"auto-topic-budget-recovery-{next_cycle}"
        if admitted and survey_stage:
            return {
                "id": request_id,
                "kind": "literature_expansion",
                "owner": "research.intelligence",
                "objective": (
                    "Continue the literature assessment of the admitted topic from its accepted "
                    "source and coverage checkpoints. Resolve the remaining novelty, evidence, "
                    "or feasibility gap without sampling a replacement topic."
                ),
                "why": (
                    "The topic-stage call/retrieval envelope ended without scientific evidence "
                    "against the selected phenomenon; preserve that direction and spend the new "
                    "allocation only on its open literature decision."
                ),
                "success_condition": (
                    "The same admitted topic receives a current gap and novelty assessment from "
                    "the retained literature state; budget exhaustion alone does not authorize "
                    "a different phenomenon."
                ),
                "evidence_needed": " ".join(evidence),
                "source_stage_id": stage["id"],
                "target_stage_id": survey_stage["id"],
                "target_stage_kind": "survey",
                "repair_priority": "immediate",
                "recovery_mode": "continue_same_topic_after_local_budget",
            }

        return {
            "id": request_id,
            "kind": "topic_refinement",
            "owner": "research.intelligence",
            "objective": (
                f"Continue topic discovery in cycle {next_cycle}. "
                + ("Keep the selected scientific phenomenon and refine its question, "
                   "comparison, observable, or evidence boundary; do not replace it because "
                   "the local allocation ended."
                   if has_topic_identity else
                   "No topic was admitted before the local allocation ended; resume the "
                   "declared discovery objective using the retained candidate and rejection "
                   "history before inventing a new research direction.")
            ),
            "why": (
                "The previous topic-stage budget is spent, but quota exhaustion is not a "
                "scientific verdict. Resume with a fresh bounded allocation and retain the "
                "existing direction and evidence whenever one was admitted."
            ),
            "success_condition": (
                "A source-grounded, executable continuation addresses the recorded open "
                "question; an admitted parent's phenomenon remains unchanged."
            ),
            "evidence_needed": " ".join(evidence),
            "source_stage_id": stage["id"],
            "target_stage_id": stage["id"],
            "target_stage_kind": "topic_discovery",
            "repair_priority": "immediate",
            "recovery_mode": "continue_same_topic_after_local_budget",
        }

    @staticmethod
    def _is_operational_stage_failure(error):
        result = getattr(error, "stage_result", None)
        return (isinstance(error, StateError) and isinstance(result, dict)
                and isinstance(result.get("failure"), dict)
                and result["failure"].get("kind") == "operational_state")

    @staticmethod
    def _forward_failure_class(error):
        """Classify a failed attempt without turning every defect into a stop."""
        if ComposerRunner._is_operational_stage_failure(error):
            return "operational_recovery"
        if getattr(error, "failure_class", None) == "context_budget":
            return "resource_fence"
        if isinstance(error, (*PROVIDER_OPERATOR_STOP_ERRORS, ProviderCooldownError, QuotaExceededError,
                              ComposerHardDeadlineExceeded, ComposerStageDeadlineExceeded,
                              ComposerLateStageResult)):
            return "resource_fence"
        if isinstance(error, ModelCallError) and not getattr(error, "outcome_known", True):
            return "unknown_external_outcome"
        if isinstance(error, KeyboardInterrupt):
            return "process_interruption"
        text = str(error or "").casefold()
        if any(token in text for token in (
                "deadline", "quota", "cooldown", "result_unknown",
                "unknown external outcome", "provider is unavailable",
                "provider error", "authentication", "auth_required",
                "credential is unavailable", "credential is invalid",
                "access_denied", "provider configuration")):
            return "resource_fence"
        if isinstance(error, ModelWorkBlocked) or any(token in text for token in (
                "adversarial", "claim_support", "estimator_definedness",
                "independent_validation", "scientific", "hypothesis",
                "evidence contract", "review rejected", "insufficient evidence")):
            return "scientific_hold"
        return "mechanical_contract"

    @staticmethod
    def _topic_candidate_from_failure(error):
        """Recover a model-selected topic for a truthful provisional handoff."""
        traces = getattr(error, "candidate_attempt_trace", [])
        if not isinstance(traces, list):
            return None
        for trace in reversed(traces):
            if not isinstance(trace, dict):
                continue
            selected = trace.get("selected_topic")
            if isinstance(selected, dict) and isinstance(selected.get("id"), str):
                return deepcopy(selected)
        return None

    def _stage_experiment_capability_id(self, stage):
        """Return the capability identity expected by an experiment stage."""
        return self._stage_experiment_capability_id_from_context(
            self.workflow, getattr(self, "context", {}), stage)

    @staticmethod
    def _stage_experiment_capability_id_from_context(workflow, context_by_stage, stage):
        """Resolve an experiment capability from its current topic lineage."""
        if not isinstance(stage, dict) or stage.get("kind") != "experiment":
            return None
        by_id = {
            item.get("id"): item for item in workflow.get("stages", [])
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        }
        pending = list(stage.get("depends_on", []))
        seen = set()
        while pending:
            stage_id = pending.pop()
            if stage_id in seen or stage_id not in by_id:
                continue
            seen.add(stage_id)
            ancestor = by_id[stage_id]
            if ancestor.get("kind") == "topic_discovery":
                context = context_by_stage.get(stage_id, {})
                if isinstance(context, dict):
                    topic = context.get("topic")
                    if isinstance(topic, dict) and isinstance(
                            topic.get("experiment_capability_id"), str):
                        return topic["experiment_capability_id"]
                    generated = context.get("generated_capability")
                    generated_id = (generated.get("capability_id")
                                    if isinstance(generated, dict) else None)
                    descriptor_path = (generated.get("descriptor_path")
                                       if isinstance(generated, dict) else None)
                    question = (topic.get("research_question")
                                if isinstance(topic, dict) else context.get("question"))
                    if isinstance(generated_id, str) and isinstance(descriptor_path, str):
                        if not isinstance(question, str):
                            return generated_id
                        try:
                            descriptor = json.loads(Path(descriptor_path).read_text())
                        except (OSError, TypeError, ValueError):
                            descriptor = None
                        experiment = (descriptor.get("experiment")
                                      if isinstance(descriptor, dict) else None)
                        if (isinstance(experiment, dict)
                                and experiment.get("research_question") == question):
                            return generated_id
            pending.extend(ancestor.get("depends_on", []))
        return None

    def _stage_experiment_study_id(self, stage):
        """Resolve the study id paired with a selected catalog capability."""
        capability_id = self._stage_experiment_capability_id(stage)
        if not isinstance(capability_id, str):
            return None
        by_id = {
            item.get("id"): item for item in self.workflow.get("stages", [])
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        }
        pending = list(stage.get("depends_on", [])) if isinstance(stage, dict) else []
        seen = set()
        while pending:
            stage_id = pending.pop()
            if stage_id in seen or stage_id not in by_id:
                continue
            seen.add(stage_id)
            ancestor = by_id[stage_id]
            if ancestor.get("kind") == "topic_discovery":
                context = self.context.get(stage_id, {})
                generated = context.get("generated_capability") if isinstance(context, dict) else None
                if (isinstance(generated, dict)
                        and generated.get("capability_id") == capability_id
                        and isinstance(generated.get("descriptor_path"), str)):
                    try:
                        descriptor = json.loads(
                            Path(generated["descriptor_path"]).read_text())
                    except (OSError, TypeError, ValueError):
                        descriptor = None
                    experiment = descriptor.get("experiment") if isinstance(descriptor, dict) else None
                    study_id = experiment.get("id") if isinstance(experiment, dict) else None
                    topic = context.get("topic")
                    question = (topic.get("research_question")
                                if isinstance(topic, dict) else context.get("question"))
                    if (isinstance(study_id, str) and study_id
                            and (not isinstance(question, str)
                                 or experiment.get("research_question") == question)):
                        return study_id
            pending.extend(ancestor.get("depends_on", []))
        return None

    def _bind_reused_experiment_capability(self, stage, prior):
        """Reuse a result only when its old study identity maps to this capability."""
        if not prior.get("project_dir"):
            prior["project_dir"] = str(Path(stage["project_dir"]).resolve())
        capability_id = self._stage_experiment_capability_id(stage)
        if not isinstance(capability_id, str):
            return self._has_executed_experiment_result(prior)
        capability_ids, study_ids = _experiment_result_identity_sets(
            prior, base_dir=stage.get("project_dir"))
        if len(capability_ids) > 1 or len(study_ids) > 1:
            return False
        expected_study_id = self._stage_experiment_study_id(stage)
        if not study_ids:
            return False
        if expected_study_id is not None and study_ids != {expected_study_id}:
            return False
        if capability_ids:
            if capability_ids != {capability_id}:
                return False
        else:
            expected_study_id = expected_study_id or capability_id
            if study_ids != {expected_study_id}:
                return False
            # Legacy outputs did not persist this Composer-level identity.
            # Add it only after the selected catalog descriptor proves the
            # exact study-to-capability mapping.
            self._annotate_experiment_result_capability(stage, prior)
        return self._has_executed_experiment_result(prior, capability_id)

    def _annotate_experiment_result_capability(self, stage, result):
        """Attach the selected capability without overwriting a conflicting identity."""
        if (not isinstance(stage, dict) or not isinstance(result, dict)
                or stage.get("kind") != "experiment"):
            return result
        capability_id = self._stage_experiment_capability_id(stage)
        if isinstance(capability_id, str) and capability_id:
            existing = result.get("capability_id")
            if not isinstance(existing, str) or not existing or existing == capability_id:
                result["capability_id"] = capability_id
        return result

    def _current_experiment_result_project_dir(self, stage):
        """Return the namespace belonging to this stage's latest attempt."""
        if not isinstance(stage, dict):
            return None
        stage_id = stage.get("id")
        record = self.stage_records.get(stage_id) if isinstance(stage_id, str) else None
        if isinstance(record, dict) and isinstance(record.get("project_dir"), str):
            return record["project_dir"]
        return stage.get("project_dir")

    @staticmethod
    def _has_executed_experiment_result(context, expected_capability_id=None, *, project_dir=None):
        """Recognize only executed evidence for the current capability.

        A resumed stage can retain a results-package path from an older
        capability or project attempt.  Presence of that path alone is not
        proof that the current experiment ran.  Require result content and,
        when the current capability is known, an identity match.
        """
        context = context if isinstance(context, dict) else {}
        context_root = context.get("project_dir")
        result_root = project_dir if isinstance(project_dir, (str, os.PathLike)) else context_root
        scope_changed = False
        if isinstance(project_dir, (str, os.PathLike)) and isinstance(context_root, (str, os.PathLike)):
            try:
                scope_changed = Path(project_dir).resolve() != Path(context_root).resolve()
            except (OSError, RuntimeError, TypeError, ValueError):
                scope_changed = str(project_dir) != str(context_root)
        identity_context = context
        if scope_changed:
            # A checkpoint can carry inline measurements from an older attempt.
            # Only path-backed results inside the current attempt namespace are
            # eligible evidence after the scope changes.
            identity_context = {"project_dir": result_root}
            for key in ("raw_results", "results_package"):
                if isinstance(context.get(key), str):
                    identity_context[key] = context[key]
        capability_ids, study_ids = _experiment_result_identity_sets(
            identity_context, base_dir=result_root)
        raw_results = _read_experiment_result_payload(
            identity_context.get("raw_results"), base_dir=result_root)
        observed = _has_numeric_experiment_observations(raw_results)
        metrics = None if scope_changed else context.get("metrics")
        observed = observed or _has_numeric_experiment_metrics(metrics)

        package = _read_experiment_result_payload(
            identity_context.get("results_package"), base_dir=result_root)
        observed = (observed
                    or _has_numeric_experiment_observations(
                        package.get("observations") if isinstance(package, dict) else None)
                    or _has_numeric_experiment_metrics(
                        package.get("metrics") if isinstance(package, dict) else None))

        if not observed:
            return False
        if len(capability_ids) > 1 or len(study_ids) > 1:
            return False
        if expected_capability_id is not None:
            if capability_ids:
                return capability_ids == {expected_capability_id}
            # Older packages use their study id as the only available
            # capability identity. Preserve those packets when they match.
            return study_ids == {expected_capability_id}
        return True

    def _is_pre_execution_capability_failure(self, stage, context=None, error=None):
        """Detect generated-program failure before any current result exists."""
        if not isinstance(stage, dict) or stage.get("kind") != "experiment":
            return False
        context = context if isinstance(context, dict) else {}
        expected_capability_id = self._stage_experiment_capability_id(stage)
        if self._has_executed_experiment_result(
                context, expected_capability_id,
                project_dir=self._current_experiment_result_project_dir(stage)):
            return False
        failure_recovery = context.get("failure_recovery")
        if not isinstance(failure_recovery, dict):
            failure_recovery = {}
        current_failure_class = classify_failure(
            "experiment", error if error is not None else context.get("error"))
        if (current_failure_class == "resource_fence"
                or context.get("failure_class") == "resource_fence"
                or failure_recovery.get("failure_class") == "resource_fence"):
            return False
        if (current_failure_class == "harness_bug"
                or context.get("failure_class") == "harness_bug"):
            return False
        if current_failure_class == "experiment_failure":
            # A current, concrete executor/result failure supersedes stale
            # format-recovery state from an earlier author response.
            return True
        if failure_recovery.get("requires_capability_repair") is True:
            # A later transport failure must not erase the typed scientific
            # rejection retained in the same checkpoint.
            return True
        # A malformed provider envelope is a transport/model-contract
        # recovery, not a failed scientific capability.  Counting it against
        # the pre-execution design lease used to authorize an empty
        # experiment handoff after many retries.
        if (context.get("failure_class") == "model_contract"
                or failure_recovery.get("failure_class") == "model_contract"
                or failure_recovery.get("recovery_mode") == "format_repair_then_rerun"
                or context.get("review_status") in {
                    "model_contract_repair", "format_recovery_exhausted"}
                or (context.get("format_recovery") is True
                    and context.get("format_recovery_dispatched") is True)):
            return False
        messages = [str(error or ""), str(context.get("error") or "")]
        debt = context.get("failure_debt")
        if isinstance(debt, dict):
            messages.append(str(debt.get("error") or ""))
        lowered = " ".join(messages).casefold()
        return (
            "capability foundry" in lowered
            and any(token in lowered for token in (
                "did not admit", "did not finish normally", "author failed",
                "authoring failed", "no executable program", "program author",
            ))
        )

    def _experiment_handoff_requires_recovery(self, stage, context):
        """Keep an unexecuted experiment behind a model-contract repair.

        ``forward_first`` may carry a scientific result with unresolved debt,
        but it must never turn a provider-format failure into an input for
        interpretation or argument.  This predicate is deliberately scoped
        to experiments with no current observation so result-bearing review
        failures retain the ordinary Composer handoff policy.
        """
        if not isinstance(stage, dict) or stage.get("kind") != "experiment":
            return False
        if not isinstance(context, dict):
            return False
        if self._has_executed_experiment_result(
                context, self._stage_experiment_capability_id(stage),
                project_dir=self._current_experiment_result_project_dir(stage)):
            return False
        recovery = context.get("failure_recovery")
        recovery = recovery if isinstance(recovery, dict) else {}
        return (
            context.get("results_status") == "not_executed"
            and (
                recovery.get("recovery_mode") in {
                    "repair_then_rerun", "format_repair_then_rerun",
                    "experiment_diagnose_patch_execute_recalculate",
                    "refine_topic_to_available_evidence",
                }
                or recovery.get("failure_class") in {
                    "model_contract", "evidence_input_unavailable",
                }
                or context.get("review_status") == "model_contract_repair"
                or context.get("format_recovery") is True
            )
        )

    def _hold_unexecuted_experiment(self, stage, context, *, reason):
        """Convert a false provisional experiment into an executable hold.

        The specialist verifier can return ``candidate_needs_review`` after a
        transport/contract failure even though the experiment emitted no
        observation.  That status is valid for an evidence-bearing candidate,
        not for an empty experiment input.  Keep the failure scoped, recreate a
        same-stage format work order when necessary, and make the result
        release-blocking so Interpretation cannot manufacture claims from it.
        """
        held = deepcopy(context) if isinstance(context, dict) else {}
        for key in ("composer_decision", "progression_state", "backfill_required"):
            held.pop(key, None)
        held.update({
            "status": "research_expansion_required",
            "results_status": "not_executed",
            "release_blocking": True,
            "review_status": held.get("review_status") or "scientific_assignment_blocked",
            "error": held.get("error") or reason,
        })
        debt = held.get("failure_debt")
        debt = deepcopy(debt) if isinstance(debt, dict) else {}
        debt.update({
            "stage_id": stage.get("id"),
            "kind": "experiment",
            "failure_class": "unexecuted_experiment",
            "error": held["error"],
            "next_action": "repair the experiment contract or capability before downstream interpretation",
            "release_blocking": True,
        })
        held["failure_debt"] = debt
        requests = held.get("research_requests")
        requests = deepcopy(requests) if isinstance(requests, list) else []
        if not requests:
            request = self._format_contract_recovery_request(stage, held)
            if isinstance(request, dict):
                requests = [request]
        held["research_requests"] = requests
        return held

    def _pre_execution_repair_count(self, stage, error=None):
        """Return the durable repair count for an unexecuted capability.

        The count belongs to the current capability-repair lineage, not to
        every historical attempt of the stage. It selects the next distinct
        repair axis and is never itself a stop condition; the mission-wide
        provider, token, and deadline fences bound the work.
        """
        if not isinstance(stage, dict):
            return 0
        context = self.context.get(stage.get("id"), {})
        context = context if isinstance(context, dict) else {}
        count = context.get("capability_repair_attempts")
        if type(count) is int and count >= 0:
            return count
        # Legacy packets may retain only the repair plan/history. Recover a
        # count only from fields written by this capability-repair lineage;
        # ordinary stage attempt numbers and generic failure-debt counts span
        # unrelated topics and must not exhaust a fresh capability.
        counts = []
        if count is None:
            recovery = context.get("failure_recovery")
            recovery = recovery if isinstance(recovery, dict) else {}
            history = context.get("experiment_repair_history")
            if isinstance(history, list):
                for entry in history:
                    if not isinstance(entry, dict):
                        continue
                    value = entry.get("repair_count_after")
                    if type(value) is not int:
                        prior_count = entry.get("repair_attempts")
                        value = prior_count + 1 if type(prior_count) is int else None
                    if type(value) is int and value >= 0:
                        counts.append(value)
            plan = context.get("experiment_repair_plan")
            if not isinstance(plan, dict):
                plan = recovery.get("experiment_repair_plan")
            lineage = plan.get("lineage") if isinstance(plan, dict) else None
            lineage_count = (lineage.get("prior_capability_repair_attempts")
                             if isinstance(lineage, dict) else None)
            if type(lineage_count) is int and lineage_count >= 0:
                counts.append(lineage_count)
            # Foundry gate retries validate one generated capability; they are
            # not Composer-issued Methods source repairs. Never infer an
            # exhausted repair lease from that inner retry ledger. Legacy
            # checkpoints without explicit repair history get one fresh,
            # inspectable source-repair order rather than a topic pivot.
        if not counts:
            return 0
        return max(0, max(counts))

    @staticmethod
    def _is_experiment_repair_request(request):
        """Return whether a work order is an executable Methods repair.

        A scientific experiment repair may outlive a small continuation cycle
        lease in a forward-first mission. It remains fenced by the mission
        wall, stage quota, provider quota, and the experiment admission gates.
        """
        if not isinstance(request, dict):
            return False
        if request.get("target_stage_kind") == "experiment":
            return request.get("kind") in {
                "additional_experiment", "analysis_display", "analysis_repair",
            }
        return (
            request.get("kind") == "additional_experiment"
            and request.get("owner") == "methods.validation"
        )

    def _unresolved_experiment_attempt_inventory(self, stage, context, *, include_paths=False):
        """Merge the scoped checkpoint ledger with any carried recovery summary.

        Recovery directives are durable snapshots and can predate later
        interrupted attempts.  The experiment stage history is authoritative
        for those attempts; never let a stale empty summary authorize an
        equivalent execution.
        """
        context = context if isinstance(context, dict) else {}
        current_topic = self._current_topic_identity()
        current_topic_id = (
            current_topic.get("topic_id") if isinstance(current_topic, dict) else None
        )
        inventory = {}

        def include(value, *, checkpoint=False):
            if not isinstance(value, dict):
                return
            state = value.get("state")
            if state not in {"started", "unknown", "result_unknown"}:
                return
            topic_id = value.get("topic_id")
            if (isinstance(current_topic_id, str) and isinstance(topic_id, str)
                    and topic_id != current_topic_id):
                return
            fields = (
                "attempt_id", "attempt_number", "cycle", "state", "external_ref",
                "topic_id", "topic_cycle", "result_manifest",
            )
            if include_paths:
                fields += ("project_dir",)
            summary = {
                key: value[key]
                for key in fields
                if key in value
            }
            identity = summary.get("attempt_id")
            if not isinstance(identity, str) or not identity:
                identity = (summary.get("attempt_number"), summary.get("cycle"))
            prior = inventory.get(identity, {})
            if checkpoint:
                prior.update(summary)
            else:
                for key, item in summary.items():
                    prior.setdefault(key, item)
            inventory[identity] = prior

        carried = context.get("unresolved_prior_attempts")
        for item in carried if isinstance(carried, list) else []:
            include(item)

        stage_record = self.stage_records.get(stage.get("id")) if isinstance(stage, dict) else None
        stage_record = stage_record if isinstance(stage_record, dict) else {}
        history = stage_record.get("attempts")
        for item in history if isinstance(history, list) else []:
            include(item, checkpoint=True)

        # The active outer attempt may not yet have been appended to its
        # history.  Record it as unresolved so the resulting order can require
        # ledger reconciliation before any equivalent code execution.
        attempt_id = stage_record.get("attempt_id")
        if (stage_record.get("status") in {"running", "retrying"}
                and isinstance(attempt_id, str) and attempt_id):
            include({
                "attempt_id": attempt_id,
                "attempt_number": stage_record.get("attempt_number"),
                "cycle": self.continuation_cycles,
                "state": "started",
                "external_ref": stage_record.get("external_ref"),
                "topic_id": stage_record.get("topic_id"),
                "topic_cycle": stage_record.get("topic_cycle"),
                "result_manifest": stage_record.get("result_manifest"),
                "project_dir": stage_record.get("project_dir"),
            }, checkpoint=True)

        def sort_key(item):
            return (
                item.get("cycle") if type(item.get("cycle")) is int else -1,
                item.get("attempt_number") if type(item.get("attempt_number")) is int else -1,
                str(item.get("attempt_id", "")),
            )

        return sorted(inventory.values(), key=sort_key)

    def _experiment_attempt_reconciliation(self, stage, context):
        """Summarize every unresolved same-lineage attempt for a repair order."""
        unresolved = self._unresolved_experiment_attempt_inventory(stage, context)
        detailed_inventory = self._unresolved_experiment_attempt_inventory(
            stage, context, include_paths=True)
        topic_stage = next((item for item in self.workflow.get("stages", [])
                            if isinstance(item, dict)
                            and item.get("kind") == "topic_discovery"), None)
        topic_context = (self.context.get(topic_stage.get("id"))
                         if isinstance(topic_stage, dict) else None)
        topic_context = topic_context if isinstance(topic_context, dict) else {}
        selected_topic = topic_context.get("topic")
        evidence = self._unresolved_prior_attempt_evidence(
            stage, detailed_inventory,
            selected_topic=selected_topic if isinstance(selected_topic, dict) else None,
        )
        records = evidence.get("records")
        records = records if isinstance(records, dict) else {}
        worker_results = evidence.get("worker_results")
        worker_results = worker_results if isinstance(worker_results, dict) else {}
        evidence_records = []
        for item in detailed_inventory:
            attempt_number = item.get("attempt_number")
            cycle = item.get("cycle")
            key = (f"cycle-{cycle}-attempt-{attempt_number}"
                   if type(cycle) is int and type(attempt_number) is int else None)
            record = records.get(key) if isinstance(key, str) else None
            record = record if isinstance(record, dict) else {}
            attempt_record = {
                field: item.get(field)
                for field in ("attempt_id", "attempt_number", "cycle", "state",
                              "topic_id", "topic_cycle")
                if item.get(field) is not None
            }
            attempt_record["external_ref_recorded"] = bool(item.get("external_ref"))
            attempt_record["classification"] = record.get(
                "classification", "attempt_path_unavailable"
            )
            for field in ("stage_run", "stage_progress", "stage_result_check",
                          "generated_programs"):
                value = record.get(field)
                if value is not None:
                    attempt_record[field] = deepcopy(value)
            worker_rows = worker_results.get(key, []) if isinstance(key, str) else []
            if isinstance(worker_rows, list):
                attempt_record["worker_result_count"] = len(worker_rows)
                attempt_record["workers"] = [{
                    field: worker.get(field)
                    for field in ("task_id", "ok", "operation_outcome", "process_returncode",
                                  "capture_truncated", "capture_incomplete",
                                  "observation_count", "metric_count", "task_ledger")
                    if worker.get(field) is not None
                } for worker in worker_rows[:4] if isinstance(worker, dict)]
            evidence_records.append(attempt_record)
        artifact_evidence = {
            "attempt_count": evidence.get("attempt_count", 0),
            "inspected_count": evidence.get("inspected_count", 0),
            "missing_directory_count": evidence.get("missing_directory_count", 0),
            "recorded_attempt_count": len(evidence_records),
            "records": evidence_records,
            "admission_rule": evidence.get("admission_rule"),
        }
        artifact_evidence["sha256"] = hashlib.sha256(
            canonical_bytes(artifact_evidence)).hexdigest()
        return {
            "required": bool(unresolved),
            "unresolved_attempt_count": len(unresolved),
            "unresolved_attempts_sha256": hashlib.sha256(
                canonical_bytes(unresolved)).hexdigest(),
            "recent_unresolved_attempts": deepcopy(unresolved[-8:]),
            "omitted_attempt_count": max(0, len(unresolved) - 8),
            "artifact_evidence": artifact_evidence,
            "rule": (
                "The controller's checkpoint attempt ledger is authoritative. Before equivalent "
                "execution, reconcile every listed same-lineage attempt against its task ledger, "
                "run/progress report, worker result, and canonical stage result. A successful worker "
                "subprocess without an acknowledged stage result is not a released scientific result; "
                "generated source or figures alone are not results. Reuse prior output only when "
                "capability, input, source identity, and current independent checks agree. Keep "
                "ambiguous outcomes unresolved; launch equivalent work only after a material "
                "source/design change and evidence that no equivalent operation remains active."
            ),
        }

    def _refresh_restored_experiment_reconciliation(self):
        """Refresh persisted experiment repair orders from the current attempt ledger."""
        stage = next((item for item in self.workflow.get("stages", [])
                      if isinstance(item, dict) and item.get("kind") == "experiment"), None)
        if not isinstance(stage, dict):
            return None
        context = self.context.get(stage.get("id"))
        if not isinstance(context, dict):
            return None
        reconciliation = self._experiment_attempt_reconciliation(stage, context)
        refreshed_ids = set()

        def refresh(value, *, trusted_container=False):
            if not isinstance(value, dict):
                return
            plan = value.get("experiment_repair_plan")
            if not isinstance(plan, dict):
                return
            lineage = plan.get("lineage")
            if (not isinstance(lineage, dict)
                    or "prior_attempt_reconciliation" not in lineage
                    or (not trusted_container
                        and self._request_target_kind(value) != "experiment")):
                return
            objective = value.get("objective")
            if isinstance(objective, str) and objective:
                label_pattern = "(?:" + "|".join(
                    re.escape(label) for label in REVIEW_EVIDENCE_LABELS) + ")"
                nested_labels = re.compile(
                    rf"(?P<label>{label_pattern})(?:\s*{label_pattern})+")
                normalized_objective = nested_labels.sub(
                    lambda match: f"{match.group('label')} ", objective)
                if normalized_objective != objective:
                    value["objective"] = normalized_objective
                    request_id = value.get("id")
                    if isinstance(request_id, str):
                        refreshed_ids.add(request_id)
            request_lineage = value.get("attempt_lineage")
            if (isinstance(request_lineage, dict)
                    and "prior_attempt_reconciliation" in request_lineage
                    and request_lineage["prior_attempt_reconciliation"] != reconciliation):
                request_lineage["prior_attempt_reconciliation"] = deepcopy(reconciliation)
                request_id = value.get("id")
                if isinstance(request_id, str):
                    refreshed_ids.add(request_id)
            if lineage["prior_attempt_reconciliation"] != reconciliation:
                lineage["prior_attempt_reconciliation"] = deepcopy(reconciliation)
                request_id = value.get("id")
                if isinstance(request_id, str):
                    refreshed_ids.add(request_id)

        refresh(context, trusted_container=True)
        for field in ("research_requests", "research_expansion_requests",
                      "deferred_research_requests"):
            requests = context.get(field)
            if isinstance(requests, list):
                for request in requests:
                    refresh(request)
        deferred = context.get("deferred_experiment_repair")
        refresh(deferred, trusted_container=True)
        recovery = context.get("failure_recovery")
        refresh(recovery, trusted_container=True)
        for request in self.active_research_requests:
            refresh(request)
        if not refreshed_ids:
            return None
        return {
            "stage_id": stage["id"],
            "request_ids": sorted(refreshed_ids),
            "unresolved_attempt_count": reconciliation["unresolved_attempt_count"],
            "artifact_evidence_sha256": reconciliation["artifact_evidence"]["sha256"],
        }

    def _autonomous_experiment_repair_request(self, stage, context, error,
                                               repair_attempts):
        """Create a concrete code-and-evidence repair order for one lineage.

        A repeated pre-execution foundry failure must not become an empty
        provisional result for Interpretation. This order records a changed
        design axis and makes the next experiment responsible for diagnosis,
        source edits, replay, independent recalculation, and review.
        """
        if not isinstance(stage, dict) or stage.get("kind") != "experiment":
            return None
        context = context if isinstance(context, dict) else {}
        deferred_repair = context.get("deferred_experiment_repair")
        if isinstance(deferred_repair, dict):
            context = deepcopy(context)
            for key in (
                    "experiment_repair_plan", "capability_repair_panel",
                    "specialist_reports", "specialist_verifier",
                    "deferred_preexecution_review"):
                if not context.get(key) and deferred_repair.get(key) is not None:
                    context[key] = deepcopy(deferred_repair[key])
            context.pop("deferred_experiment_repair", None)
        recovery = context.get("failure_recovery")
        recovery = recovery if isinstance(recovery, dict) else {}
        history = context.get("experiment_repair_history")
        history = history if isinstance(history, list) else []
        panel = context.get("capability_repair_panel")
        panel = panel if isinstance(panel, dict) else {}
        panel_verifier = panel.get("verifier")
        panel_verifier = panel_verifier if isinstance(panel_verifier, dict) else {}
        diagnostics = recovery.get("model_diagnostics")
        diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
        prior_feedback = diagnostics.get("repair_feedback")
        prior_feedback = prior_feedback if isinstance(prior_feedback, dict) else {}
        pending_prior_issues = prior_feedback.get("prior_issues_pending_reassessment")
        pending_prior_issues = (
            pending_prior_issues if isinstance(pending_prior_issues, list) else [])

        evidence_labels = REVIEW_EVIDENCE_LABELS

        def evidence_strings(value):
            if not isinstance(value, list):
                return []
            cleaned = []
            for item in value:
                if not isinstance(item, str) or not item.strip():
                    continue
                text = item.strip()
                previous = None
                while text != previous:
                    previous = text
                    for label in evidence_labels:
                        if text.startswith(label):
                            text = text[len(label):].lstrip()
                            break
                if text:
                    cleaned.append(text[:1400])
            return cleaned

        def unique_evidence(values, limit):
            result = []
            seen = set()
            for item in values:
                if not isinstance(item, str) or not item.strip():
                    continue
                raw = item.strip()
                text = raw
                first_label = ""
                previous = None
                while text != previous:
                    previous = text
                    for label in evidence_labels:
                        if text.startswith(label):
                            if not first_label:
                                first_label = label
                            text = text[len(label):].lstrip()
                            break
                if not text:
                    continue
                key = " ".join(text.split()).casefold()
                if key in seen:
                    continue
                seen.add(key)
                result.append(f"{first_label}{text}"[:1400])
                if len(result) >= limit:
                    break
            return result

        # Checkpoint panels written by older runtimes called model-generated
        # findings "root_causes". They remain reviewer hypotheses until
        # reproduced from source, observations, or deterministic validation.
        diagnostic_hypotheses = evidence_strings(
            panel.get("diagnostic_hypotheses") or panel.get("root_causes"))
        proposed_changes = evidence_strings(
            panel.get("proposed_changes") or panel.get("required_changes"))
        prior_plan = context.get("experiment_repair_plan")
        prior_plan_evidence = evidence_strings(
            prior_plan.get("review_evidence") if isinstance(prior_plan, dict) else None)
        current_reviewer_evidence = unique_evidence([
            *(f"Persisted independent-review finding: {item}"
              for item in prior_plan_evidence),
            *(f"Unverified Methods-panel finding: {item}"
              for item in evidence_strings(panel.get("critical_findings"))),
            *(f"Unverified Methods-panel repair scope: {item}"
              for item in evidence_strings(panel.get("repair_scope"))),
            *(f"Unverified Methods-panel diagnosis hypothesis: {item}"
              for item in diagnostic_hypotheses),
            *(f"Unverified Methods-panel proposed change: {item}"
              for item in proposed_changes),
            *(f"Unverified Methods-verifier hypothesis: {item}"
              for item in evidence_strings(panel_verifier.get("critical_findings"))),
            *(f"Unverified Methods-verifier proposed scope: {item}"
              for item in evidence_strings(panel_verifier.get("repair_scope"))),
        ], 12)
        pending_issue_evidence = []
        pending_prior_issue_records = []
        for item in pending_prior_issues:
            if not isinstance(item, dict):
                continue
            finding = item.get("finding")
            evidence = item.get("evidence")
            required_change = item.get("required_change")
            if not all(isinstance(value, str) and value.strip()
                       for value in (finding, evidence, required_change)):
                continue
            pending_prior_issue_records.append({
                "finding": finding.strip()[:1200],
                "evidence": evidence.strip()[:1000],
                "required_change": required_change.strip()[:1000],
                **({"review_check_id": item["review_check_id"]}
                   if isinstance(item.get("review_check_id"), str) else {}),
            })
            pending_issue_evidence.append(
                "Reassess persisted finding against the exact current candidate; do not assume it "
                f"still applies. Finding: {finding.strip()[:600]} Evidence: "
                f"{evidence.strip()[:500]} Required change if still supported: "
                f"{required_change.strip()[:500]}"
            )
        reviewer_evidence = unique_evidence([
            *pending_issue_evidence, *current_reviewer_evidence,
        ], 12)
        if pending_issue_evidence:
            pending_issue_evidence = pending_issue_evidence[:12]
        if not reviewer_evidence:
            directives = recovery.get("review_directives")
            if isinstance(directives, list):
                reviewer_evidence = list(dict.fromkeys(
                    item.get("text", "").strip()[:1400]
                    for item in directives
                    if isinstance(item, dict)
                    and isinstance(item.get("text"), str)
                    and item["text"].strip()
                ))[:12]
        survey_request = self._route_unexecuted_experiment_to_survey(
            stage, context, error, reviewer_evidence)
        if survey_request is not None:
            return survey_request
        repair_axis = "review_directed" if reviewer_evidence else "failure_directed"
        repair_instruction = (
            "Reassess every retained independent-review finding as a hypothesis, not a confirmed defect. "
            "Reproduce it against the exact current executor, validator, raw observations, and result; "
            "repair only if the defect is confirmed. If the evidence contradicts the review, record the "
            "contradiction and preserve the supported result or claim scope. Do not blindly replay an old "
            "diff or substitute a generic repair."
            if reviewer_evidence else
            "Diagnose and repair the exact failed mechanism or execution assumption recorded in the "
            "immutable failure evidence before changing unrelated design dimensions."
        )
        repair_evidence = (
            "Every review hypothesis is either confirmed and repaired with a fresh replay, disproved with "
            "reproducible evidence, or recorded as a bounded unresolved limitation; independently "
            "recalculate any resulting scientific claim."
            if reviewer_evidence else
            "The diagnosed failure is bound to source or a deterministic check, corrected in the "
            "executor and validator as applicable, then replayed and independently recalculated."
        )
        prior_attempt_reconciliation = self._experiment_attempt_reconciliation(stage, context)
        cycle = self.continuation_cycles + 1
        digest = str(
            recovery.get("input_sha256")
            or context.get("failure_input_sha256")
            or hashlib.sha256(str(error).encode()).hexdigest()
        )[:12]
        safe_stage = re.sub(r"[^a-z0-9-]+", "-", str(stage.get("id", "experiment")).casefold()).strip("-")
        safe_stage = safe_stage[:20] or "experiment"
        request_id = f"auto-{safe_stage}-repair-{cycle}-{repair_axis}-{digest[:6]}"[:64]
        prior_gate = recovery.get("gate") or recovery.get("failure_class") or "scientific_admission"
        commands = recovery.get("repair_commands")
        commands = deepcopy(commands) if isinstance(commands, list) else []
        commands.extend([
            {
                "id": "methods-reconcile-prior-attempts",
                "operation": "inspect",
                "target": "all unresolved prior experiment attempts in the repair context",
                "instruction": prior_attempt_reconciliation["rule"],
                "acceptance_check": (
                    "The controller has classified the full checkpoint inventory represented by its "
                    "digest; no equivalent unresolved operation is dispatched."
                ),
            },
            {
                "id": "methods-diagnose-source-and-trace",
                "operation": "inspect",
                "target": "the exact executor, validator, raw trace, and failed gate",
                "instruction": (
                    "Reconstruct the failure from the immutable dossier before editing code; "
                    "treat reviewer diagnoses as hypotheses and bind any confirmed invalid assumption "
                    "to a source line, observed field, or deterministic check; document contradicted "
                    "hypotheses without forcing an edit."
                ),
                "acceptance_check": "Each diagnosis is confirmed by evidence, contradicted with evidence, or explicitly bounded as unresolved.",
            },
            {
                "id": "methods-edit-executor-and-validator",
                "operation": "edit_program",
                "target": "executor_source and validator_source",
                "instruction": repair_instruction,
                "acceptance_check": repair_evidence,
            },
            {
                "id": "methods-rerun-independent-review",
                "operation": "execute",
                "target": "a fresh capability revision and experiment attempt namespace",
                "instruction": (
                    "Run the repaired program, retain raw observations and trace, recompute every "
                    "primary outcome independently, then rerun deterministic and adversarial review."
                ),
                "acceptance_check": (
                    "The new result is executable, independently recalculated, and either admitted "
                    "or retained as an explicit bounded negative result."
                ),
            },
        ])
        checks = recovery.get("acceptance_checks")
        checks = deepcopy(checks) if isinstance(checks, list) else []
        checks.extend([
            repair_evidence,
            "The repaired code is executed in a new immutable attempt namespace.",
            "Prior unknown attempts are reconciled before any equivalent execution is dispatched.",
        ])
        plan = {
            "schema_version": "experiment-repair-plan-1",
            "mode": "diagnose_patch_execute_recalculate",
            "lineage": {
                "source_stage_id": stage.get("id"),
                "prior_capability_repair_attempts": repair_attempts,
                "continuation_cycle": cycle,
                "failure_input_sha256": recovery.get("input_sha256") or context.get("failure_input_sha256"),
                "prior_gate": prior_gate,
                "prior_attempt_reconciliation": prior_attempt_reconciliation,
            },
            "design_axis": repair_axis,
            "instruction": repair_instruction,
            "required_evidence": repair_evidence,
            "review_evidence": reviewer_evidence,
            "root_causes": [],
            "required_changes": [],
            "diagnostic_hypotheses": diagnostic_hypotheses[:8],
            "proposed_changes": proposed_changes[:8],
            "prior_findings_to_reassess": pending_prior_issue_records[:12],
            "must_preserve": [
                "the admitted topic and exact research question",
                "the prior failure dossier and raw diagnostic evidence",
                "independent validation rather than executor self-confirmation",
                "unresolved attempt states until their durable outcomes are reconciled",
            ],
            "must_verify": reviewer_evidence[:8],
            "must_change": [],
            "prohibited": [
                "forwarding an unexecuted result to interpretation",
                "patching result JSON instead of the executable source",
                "hiding an undefined or censored estimand with zero, NaN, or endpoint fallback",
            ],
        }
        history_entry = {
            "cycle": cycle,
            "repair_attempts": repair_attempts,
            "repair_count_after": repair_attempts + 1,
            "plan": deepcopy(plan),
            "error": str(error)[:2400],
            "dossier_ref": recovery.get("dossier_ref") or context.get("failure_dossier_ref"),
        }
        updated_history = (history + [history_entry])[-12:]
        request = {
            "id": request_id,
            "kind": "additional_experiment",
            "owner": "methods.validation",
            "target_stage_id": stage.get("id"),
            "target_stage_kind": "experiment",
            "repair_priority": "immediate",
            "objective": (
                "Diagnose, patch, and rerun the failed computational experiment. "
                f"{repair_instruction} "
                + ("Independent review evidence: " + " | ".join(reviewer_evidence[:5])
                   if reviewer_evidence else "Failure evidence: " + str(error)[:900])
            )[:1800],
            "why": (
                "The generated capability failed before producing an observation. The next bounded action "
                "is a topic-preserving, evidence-directed Methods source repair. "
                f"Gate={prior_gate}; this is not a validator-only retry."
            )[:1800],
            "success_condition": (
                "The repaired executor and validator run in a fresh namespace, every primary outcome "
                "is independently recalculated, unresolved prior attempts are reconciled without blind "
                "replay, and the result is admitted or recorded as a bounded negative result."
            ),
            "evidence_needed": (
                "Immutable failure dossier, exact executor/validator sources, raw observations, "
                "execution trace, each unresolved prior attempt's durable status/result evidence, "
                "deterministic replay, independent recalculation, and adversarial review."
            ),
            "source_stage_id": stage.get("id"),
            "failure_dossier_ref": recovery.get("dossier_ref") or context.get("failure_dossier_ref"),
            "failure_input_sha256": recovery.get("input_sha256") or context.get("failure_input_sha256"),
            "repair_commands": commands[-12:],
            "acceptance_checks": checks[-12:],
            "review_directives": deepcopy(recovery.get("review_directives", []))
                if isinstance(recovery.get("review_directives"), list) else [],
            "model_diagnostics": deepcopy(recovery.get("model_diagnostics", {}))
                if isinstance(recovery.get("model_diagnostics"), dict) else {},
            "recovery_mode": "experiment_diagnose_patch_execute_recalculate",
            "experiment_repair_plan": plan,
            "repair_strategy": repair_axis,
            "attempt_lineage": deepcopy(plan["lineage"]),
        }
        context.update({
            "stage_id": stage.get("id"),
            "kind": "experiment",
            "status": "research_expansion_required",
            "review_status": "scientific_assignment_blocked",
            "release_blocking": True,
            # Preserve the lineage counter across the new work order. Resetting
            # this field made every continuation look like the first repair and
            # allowed an unchanged capability to consume the whole mission.
            "capability_repair_attempts": max(
                int(repair_attempts) + 1, len(updated_history)),
            "experiment_repair_plan": deepcopy(plan),
            "experiment_repair_history": updated_history,
            "research_requests": [request],
            "research_expansion_requests": [],
            "failure_debt": {
                "stage_id": stage.get("id"),
                "kind": "experiment",
                "failure_class": "experiment_capability_repair",
                "error": str(error)[:4096],
                "attempts": repair_attempts,
                "next_action": "execute the diagnosis-patch-replay-recalculation work order",
                "release_blocking": True,
                "failure_dossier_ref": request.get("failure_dossier_ref"),
            },
        })
        if recovery:
            recovery = deepcopy(recovery)
            recovery["recovery_mode"] = "experiment_diagnose_patch_execute_recalculate"
            recovery["requires_capability_repair"] = True
            recovery["experiment_repair_plan"] = deepcopy(plan)
            context["failure_recovery"] = recovery
        self.context[stage["id"]] = context
        return request

    def _route_unexecuted_experiment_to_survey(self, stage, context, error,
                                               reviewer_evidence=None):
        """Resolve an admitted pilot's evidence deficit before repairing code.

        A code-capability repair is not actionable when the current same-topic
        survey explicitly admitted only an exploratory pilot for insufficient
        evidence. Give Research one source-backed acquisition pass first; the
        Methods repair remains deferred until the scientific input is usable.
        """
        if not self._is_pre_execution_capability_failure(stage, context, error):
            failure_text = error if error is not None else context.get("error")
            is_reproducible_harness_failure = (
                isinstance(stage, dict)
                and stage.get("kind") == "experiment"
                and isinstance(context, dict)
                and context.get("results_status") in {None, "not_executed"}
                and classify_failure("experiment", failure_text) == "harness_bug"
                and not self._has_executed_experiment_result(
                    context, self._stage_experiment_capability_id(stage),
                    project_dir=self._current_experiment_result_project_dir(stage))
            )
            if not is_reproducible_harness_failure:
                return None
        by_id = {
            item.get("id"): item for item in self.workflow.get("stages", [])
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        }
        pending = list(stage.get("depends_on", []))
        seen = set()
        survey_stage = None
        survey_context = None
        while pending:
            stage_id = pending.pop(0)
            if stage_id in seen:
                continue
            seen.add(stage_id)
            candidate = by_id.get(stage_id)
            if not isinstance(candidate, dict):
                continue
            if candidate.get("kind") == "survey":
                candidate_context = self.context.get(stage_id)
                if (isinstance(candidate_context, dict)
                        and self._request_context_matches_current_topic(
                            stage_id, candidate_context)):
                    survey_stage = candidate
                    survey_context = candidate_context
                    break
            pending.extend(candidate.get("depends_on", []))
        if not isinstance(survey_stage, dict) or not isinstance(survey_context, dict):
            return None
        topic_stage = self._topic_stage_for_survey(survey_stage)
        if not isinstance(topic_stage, dict):
            return None
        topic_context = self.context.get(topic_stage["id"])
        topic_context = topic_context if isinstance(topic_context, dict) else {}
        topic = topic_context.get("topic")
        topic = topic if isinstance(topic, dict) else {}
        topic_id = topic.get("id")
        question = topic.get("research_question") or topic.get("question")
        identity = self._current_topic_identity()
        if (not isinstance(topic_id, str) or not topic_id
                or not isinstance(question, str) or not question.strip()
                or not isinstance(identity, dict)
                or identity.get("topic_id") != topic_id
                or survey_context.get("gap_state") != "insufficient_evidence"
                or survey_context.get("topic_admission") != "exploratory_pilot"
                or survey_context.get("survey_current") is not True
                or survey_context.get("assessment_current") is not True):
            return None
        expansion_history = context.get("survey_evidence_expansion_history")
        expansion_history = expansion_history if isinstance(expansion_history, list) else []
        prior_expansion = next((item for item in reversed(expansion_history)
                                if isinstance(item, dict)
                                and item.get("topic_id") == identity["topic_id"]
                                and item.get("topic_cycle") == identity["topic_cycle"]), None)
        retained_request = None
        if prior_expansion is not None:
            request_id = prior_expansion.get("request_id")
            admissions = []
            candidates = [*self.active_research_requests]
            for decision in reversed(self.feedback):
                if (not isinstance(decision, dict)
                        or decision.get("action") != "continue_research"
                        or not isinstance(decision.get("research_requests"), list)):
                    continue
                for item in decision.get("research_requests", []):
                    if (isinstance(item, dict) and item.get("id") == request_id
                            and item.get("topic_id") == identity["topic_id"]
                            and item.get("topic_cycle") == identity["topic_cycle"]):
                        candidates.append(item)
                        if type(decision.get("cycle")) is int:
                            admissions.append((decision["cycle"], item))
            for value in self.context.values():
                if not isinstance(value, dict):
                    continue
                for key in ("research_requests", "research_expansion_requests"):
                    if isinstance(value.get(key), list):
                        candidates.extend(value[key])
            retained_request = next((deepcopy(item) for item in candidates
                                     if isinstance(item, dict)
                                     and item.get("id") == request_id
                                     and item.get("topic_id") == identity["topic_id"]
                                     and item.get("topic_cycle") == identity["topic_cycle"]
                                     and self._request_target_kind(item) == "survey"), None)
            admitted_cycles = [cycle for cycle, item in admissions
                               if isinstance(retained_request, dict)
                               and self._research_request_signature(item)
                               == self._research_request_signature(retained_request)]
            retained = (self._survey_acquisition_frontier_for_topic(
                survey_stage["id"], identity["topic_id"], identity["topic_cycle"], retained_request)
                if isinstance(retained_request, dict) else None)
            if retained is not None and admitted_cycles:
                attempt, project_dir, run, _ = retained
                if (type(attempt.get("cycle")) is int
                        and attempt["cycle"] >= min(admitted_cycles)
                        and isinstance(retained_request, dict)
                        and self._survey_request_was_fulfilled(project_dir, run, retained_request)):
                    return None
        survey_lineage = survey_context.get("topic_lineage")
        survey_cycles = [value for value in (
            survey_lineage.get("topic_cycle") if isinstance(survey_lineage, dict) else None,
            survey_context.get("topic_cycle"),
        ) if type(value) is int and value >= 0]
        if any(value != identity["topic_cycle"] for value in survey_cycles):
            return None
        deferred_survey_orders = survey_context.get("deferred_research_requests")
        if retained_request is None and isinstance(deferred_survey_orders, list) and any(
                isinstance(item, dict)
                and item.get("kind") == "literature_expansion"
                and item.get("owner") == "research.intelligence"
                for item in deferred_survey_orders):
            return None

        review_items = []
        for item in reviewer_evidence if isinstance(reviewer_evidence, list) else []:
            if isinstance(item, str) and item.strip():
                review_items.append(item.strip()[:1400])
        for source in (
                context.get("experiment_repair_plan"),
                context.get("capability_repair_panel"),
                context.get("specialist_verifier")):
            if not isinstance(source, dict):
                continue
            for key in ("review_evidence", "critical_findings", "repair_scope",
                        "diagnostic_hypotheses", "required_changes", "root_causes"):
                value = source.get(key)
                if isinstance(value, list):
                    review_items.extend(item.strip()[:1400] for item in value
                                        if isinstance(item, str) and item.strip())
        for request in self.active_research_requests:
            if (not isinstance(request, dict)
                    or request.get("source_stage_id") != stage.get("id")):
                continue
            directives = request.get("review_directives")
            if isinstance(directives, list):
                review_items.extend(
                    item["text"].strip()[:1400] for item in directives
                    if isinstance(item, dict) and isinstance(item.get("text"), str)
                    and item["text"].strip())
        review_items = list(dict.fromkeys(review_items))[:12]
        topic_cycle = identity["topic_cycle"]
        survey_ref = survey_context.get("survey_ref")
        assessment_ref = survey_context.get("assessment_ref")
        safe_topic = re.sub(r"[^a-z0-9-]+", "-", topic_id.casefold()).strip("-")[:24]
        request = {
            "id": f"auto-survey-evidence-{safe_topic or 'topic'}",
            "kind": "literature_expansion",
            "owner": "research.intelligence",
            "source_stage_id": stage["id"],
            "target_stage_id": survey_stage["id"],
            "target_stage_kind": "survey",
            "topic_id": topic_id,
            "topic_cycle": topic_cycle,
            "repair_policy_revision": SURVEY_EVIDENCE_REQUEST_POLICY_REVISION,
            "repair_priority": "immediate",
            "recovery_mode": "survey_evidence_before_experiment_repair",
            "objective": (
                "Resolve the missing literature evidence for the current question before any further "
                "experiment-code repair. Preserve the same physical phenomenon and question: "
                f"{question.strip()[:1600]} Search primary sources and citation chains; acquire and "
                "verify full text where available; extract comparable measurements with exact source "
                "locations and provenance. Do not invent values or present synthetic calculations as "
                "empirical evidence."
            )[:3600],
            "why": (
                "The current survey is explicitly exploratory-only because its gap assessment is "
                "insufficient, and the experiment has no executed result. Methods cannot repair a "
                "computational capability into evidence that the survey has not established."
            ),
            "success_condition": (
                "Publish a current survey and gap assessment that either (a) contains source-traceable "
                "measurements for the declared comparison, including definitions of the study variables "
                "and outcomes, units, controls, uncertainty, and exact page/figure/table, or (b) records a bounded "
                "targeted negative search with source coverage and the precise unavailable evidence. "
                "Then issue an evidence-based same-phenomenon decision: admit a feasible experiment, "
                "narrow the empirical claim, or explicitly reframe as a prediction/model study without "
                "claiming empirical confirmation."
            ),
            "evidence_needed": (
                "The immutable current survey and assessment, primary-source full-text spans and hashes, "
                "an extracted data table with units and uncertainty where available, search/citation-chain "
                "coverage, and the following independent-review findings: "
                + (" | ".join(review_items) if review_items else
                   "No reviewer finding was available; independently test whether the required comparison "
                   "is supported by source data." )
            )[:7000],
            "source_survey_ref": survey_ref,
            "source_assessment_ref": assessment_ref,
            "review_directives": [
                {"id": f"survey-evidence-review-{index + 1}",
                 "kind": "source_evidence_check", "source": "independent_review",
                 "text": item}
                for index, item in enumerate(review_items)
            ],
        }
        if topic_cycle is not None:
            request["topic_cycle"] = topic_cycle
        if retained_request is not None:
            request = retained_request

        if self._has_executed_experiment_result(
                context, self._stage_experiment_capability_id(stage),
                project_dir=self._current_experiment_result_project_dir(stage)):
            return None

        superseded = []
        for key in ("research_expansion_requests", "research_requests",
                    "deferred_research_requests"):
            values = context.get(key)
            if not isinstance(values, list):
                continue
            keep = []
            for item in values:
                if (isinstance(item, dict)
                        and self._request_target_kind(item) == "experiment"):
                    superseded.append(deepcopy(item))
                else:
                    keep.append(item)
            context[key] = keep
        stale_active = [item for item in self.active_research_requests
                        if isinstance(item, dict)
                        and item.get("source_stage_id") == stage["id"]
                        and self._request_target_kind(item) == "experiment"]
        superseded.extend(deepcopy(stale_active))
        if stale_active:
            stale_ids = {item.get("id") for item in stale_active}
            self.active_research_requests = [
                item for item in self.active_research_requests
                if not (isinstance(item, dict) and item.get("id") in stale_ids)
            ]
        if superseded:
            archive = context.get("superseded_research_requests")
            archive = deepcopy(archive) if isinstance(archive, list) else []
            for item in superseded:
                record = {
                    **item,
                    "superseded_reason": (
                        "same-topic survey evidence must be resolved before experiment execution"),
                }
                if not any(isinstance(old, dict)
                           and old.get("id") == record.get("id")
                           and old.get("superseded_reason") == record["superseded_reason"]
                           for old in archive):
                    archive.append(record)
            context["superseded_research_requests"] = archive[-24:]

        prior_plan = context.pop("experiment_repair_plan", None)
        recovery = context.get("failure_recovery")
        if isinstance(recovery, dict):
            recovery = deepcopy(recovery)
            nested_plan = recovery.pop("experiment_repair_plan", None)
            if prior_plan is None:
                prior_plan = nested_plan
            recovery["deferred_recovery_mode"] = recovery.get("recovery_mode")
            recovery["recovery_mode"] = "survey_evidence_before_experiment_repair"
            recovery["requires_capability_repair"] = False
            context["failure_recovery"] = recovery
        deferred = context.get("deferred_experiment_repair")
        deferred = deepcopy(deferred) if isinstance(deferred, dict) else {}
        if prior_plan is not None:
            lineage = prior_plan.get("lineage") if isinstance(prior_plan, dict) else None
            if not isinstance(lineage, dict):
                lineage = {"source_stage_id": stage.get("id")}
                prior_plan["lineage"] = lineage
            lineage["prior_attempt_reconciliation"] = (
                self._experiment_attempt_reconciliation(stage, context))
            deferred["experiment_repair_plan"] = deepcopy(prior_plan)
        for key in ("capability_repair_panel", "specialist_reports",
                    "specialist_verifier", "deferred_preexecution_review"):
            if key in context:
                deferred[key] = deepcopy(context.pop(key))
        if deferred:
            deferred["reason"] = (
                "Evidence acquisition for the admitted topic precedes any computational repair; "
                "reassess this Methods review only after the current survey is resolved.")
            context["deferred_experiment_repair"] = deferred

        request_signature = self._research_request_signature(request)
        already_present = any(
            isinstance(item, dict)
            and self._research_request_signature(item) == request_signature
            for item in self.active_research_requests
        )
        if not already_present:
            requests = context.get("research_requests")
            if not isinstance(requests, list):
                requests = []
            requests.append(deepcopy(request))
            context["research_requests"] = requests
            self.active_research_requests.append(deepcopy(request))
        expansion_history = deepcopy(expansion_history)
        if prior_expansion is None:
            expansion_history.append({
                "topic_id": topic_id,
                "topic_cycle": topic_cycle,
                "source_survey_ref": survey_ref,
                "source_assessment_ref": assessment_ref,
                "source_project_dir": survey_context.get("project_dir"),
                "request_id": request["id"],
            })
        context["survey_evidence_expansion_history"] = expansion_history[-8:]
        context.update({
            "stage_id": stage["id"],
            "kind": "experiment",
            "status": "research_expansion_required",
            "review_status": "scientific_assignment_blocked",
            "release_blocking": True,
            "failure_debt": {
                "stage_id": stage["id"],
                "kind": "experiment",
                "failure_class": "insufficient_survey_evidence",
                "error": str(error)[:4096],
                "next_action": "resolve same-topic survey evidence before deciding on experiment repair",
                "release_blocking": True,
                "failure_dossier_ref": context.get("failure_dossier_ref"),
            },
        })
        self.context[stage["id"]] = context
        return request

    def _reconcile_experiment_survey_evidence_routes(self, by_id):
        """Replace stale Methods orders when a resumed pilot lacks survey evidence."""
        reconciled = []
        for stage_id, stage in by_id.items():
            if not isinstance(stage, dict) or stage.get("kind") != "experiment":
                continue
            context = self.context.get(stage_id)
            if not isinstance(context, dict):
                continue
            review_evidence = []
            plan = context.get("experiment_repair_plan")
            if isinstance(plan, dict) and isinstance(plan.get("review_evidence"), list):
                review_evidence.extend(plan["review_evidence"])
            existing = []
            for key in ("research_expansion_requests", "research_requests",
                        "deferred_research_requests"):
                value = context.get(key)
                if isinstance(value, list):
                    existing.extend(item for item in value if isinstance(item, dict))
            existing.extend(item for item in self.active_research_requests
                            if isinstance(item, dict)
                            and item.get("source_stage_id") == stage_id)
            existing_signatures = {
                self._research_request_signature(item) for item in existing
            }
            request = self._route_unexecuted_experiment_to_survey(
                stage, context, context.get("error"), review_evidence)
            if not isinstance(request, dict):
                continue
            if self._research_request_signature(request) in existing_signatures:
                continue
            reconciled.append({
                "cycle": self.continuation_cycles,
                "action": "reopen_same_topic_survey_before_experiment_repair",
                "source_stage_id": stage_id,
                "target_stage_id": request["target_stage_id"],
                "topic_id": request["topic_id"],
                "superseded_request_ids": [
                    item.get("id") for item in context.get("superseded_research_requests", [])
                    if isinstance(item, dict) and item.get("superseded_reason")
                    == "same-topic survey evidence must be resolved before experiment execution"
                ][-12:],
                "next_action": "acquire source-backed evidence; do not rerun unadmitted experiment code",
                "model_calls": 0,
            })
        return reconciled

    def _composer_can_advance_after_admission(self, stage, error):
        """Return whether Composer authority may hand off a failed stage.

        The stage assignment is the Composer's admission decision.  Once that
        decision exists, deterministic validation, model output shape, and
        scientific review findings are evidence to carry forward rather than
        vetoes.  A process interruption is different: its external outcome
        is genuinely unknown and must be reconciled before another attempt.
        Provider cooldowns and hard deadline exceptions are also kept as
        resource fences because no downstream model call can be made safely
        while the resource is unavailable.
        """
        if not self._forward_first() or not isinstance(stage, dict):
            return False
        # An executable scientific repair order has priority over the
        # provisional handoff.  Forwarding here used to mark the failed scope
        # as a candidate immediately after issuing a dossier, so the next
        # adaptive cycle spent its budget on the same upstream work instead of
        # executing the repair that the reviewer requested.
        context = self.context.get(stage.get("id"), {})
        recovery = context.get("failure_recovery") if isinstance(context, dict) else None
        if self._experiment_handoff_requires_recovery(stage, context):
            return False
        observed_experiment = (
            isinstance(context, dict)
            and (
                context.get("results_status") not in {None, "not_executed"}
                or any(context.get(key) for key in (
                    "results_package", "raw_results", "metrics", "findings",
                    "execution_refs", "deterministic_validation_ref",
                ))
            )
        )
        repair_first = (
            stage.get("kind") in {"interpretation", "argument"}
            or stage.get("kind") == "experiment" and observed_experiment
        )
        # The recovery ledger is authoritative even when the failed runner
        # could not project its observed result into the top-level context.
        # In particular, capability authoring/admission failures can carry a
        # valid experiment repair order while ``results_package`` is absent.
        # Gating this check on ``observed_experiment`` allowed those failures
        # to become an empty forward-progress packet, after which a downstream
        # interpretation was admitted with no experiment input.  Any explicit
        # scientific repair order must be executed before a provisional handoff
        # for every research stage.
        if (isinstance(recovery, dict)
                and recovery.get("recovery_mode") == "repair_then_rerun"
                and isinstance(context.get("research_requests"), list)
                and context.get("research_requests")):
            return False
        # A malformed survey/assignment envelope has no current scientific
        # handoff. Forward-first is allowed to carry unresolved evidence, not
        # an absent assessment that the downstream stage cannot consume.
        if (isinstance(recovery, dict)
                and recovery.get("failure_class") == "model_contract"
                and (context.get("format_recovery") is True
                     or context.get("review_status") == "model_contract_repair")):
            return False
        # A generated capability that never executed is never a valid
        # downstream input. Once its source-level repair lease is exhausted,
        # _admit_scientific_blocker_recovery creates a changed experiment work
        # order; it must not become a provisional empty result.
        if self._is_pre_execution_capability_failure(
                stage, self.context.get(stage.get("id")), error):
            return False
        failure_class = self._forward_failure_class(error)
        return failure_class not in {"resource_fence", "operational_recovery", "unknown_external_outcome",
                                     "process_interruption"}

    def _authorize_forward_context(self, stage, context, *, reason):
        """Make Composer's handoff explicit without manufacturing evidence."""
        candidate = deepcopy(context) if isinstance(context, dict) else {}
        stage_id = stage["id"]
        prior_status = candidate.get("status")
        debt = candidate.get("failure_debt")
        if not isinstance(debt, dict):
            debt = {
                "stage_id": stage_id,
                "kind": stage.get("kind"),
                "failure_class": "scientific_hold" if prior_status in STAGE_HOLD_STATUSES
                else "composer_handoff",
                "error": candidate.get("error") or (
                    f"stage returned {prior_status}" if prior_status else reason),
                "attempts": candidate.get("attempt_number", 0),
                "next_action": "backfill or re-review this scope after downstream work",
            }
        debt["release_blocking"] = False
        debt["authority"] = "command.composer"
        candidate.update({
            "status": "candidate_needs_review",
            "composer_decision": "advance_with_findings",
            "progression_state": "advanced_with_findings",
            "evidence_state": candidate.get("evidence_state") or (
                "unverified" if candidate.get("results_status") == "not_executed"
                else "needs_review"),
            "release_blocking": False,
            "failure_debt": debt,
            "backfill_required": True,
            "preserve_work_orders": True,
        })
        if prior_status in STAGE_HOLD_STATUSES:
            candidate.setdefault("deferred_review_findings", {
                "decision": prior_status,
                "reason": candidate.get("error") or reason,
            })
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "composer_authorized_advance",
            "stage_id": stage_id,
            "from_status": prior_status,
            "reason": reason,
            "authority": "command.composer",
            "evidence_state": candidate["evidence_state"],
            "release_blocking": False,
        })
        return candidate

    @staticmethod
    def _has_scoped_research_work(context):
        """Keep a stage closed while an explicit repair/expansion order is open."""
        if not isinstance(context, dict):
            return False
        return any(
            isinstance(context.get(key), list)
            and any(isinstance(item, dict) and isinstance(item.get("id"), str)
                    for item in context[key])
            for key in ("research_expansion_requests", "research_requests")
        )

    def _should_authorize_forward_hold(self, outcome, context):
        return (self._forward_first()
                and outcome in STAGE_HOLD_STATUSES
                and not self._has_scoped_research_work(context))

    def _mark_forward_blockers_advisory(self, stage_id):
        """Keep blocker evidence while removing its authority to stop flow."""
        for blocker in self.blockers:
            if not isinstance(blocker, dict) or blocker.get("stage_id") != stage_id:
                continue
            blocker.update({
                "gating": False,
                "release_blocking": False,
                "disposition": "forwarded_with_findings",
                "authority": "command.composer",
            })

    @staticmethod
    def _prior_stage_artifact(stage, attempt_history):
        """Find the newest successful scientific artifact for a stage.

        A failed continuation must not erase the last usable packet.  The
        attempt ledger already records immutable per-attempt directories, so
        reusing the latest successful file is deterministic and does not
        require copying a mutable incumbent into the new continuation.
        """
        if not isinstance(stage, dict) or not isinstance(attempt_history, list):
            return None
        filenames = {
            "interpretation": ("interpretation.json", "output/interpretation.json"),
            "argument": ("argument.json", "output/argument.json"),
            "paper": ("output/run.json", "output/manuscript.json"),
        }.get(stage.get("kind"), ())
        for attempt in reversed(attempt_history):
            if not isinstance(attempt, dict) or attempt.get("state") != "succeeded":
                continue
            root = attempt.get("project_dir")
            if not isinstance(root, str):
                continue
            root = Path(root)
            for relative in filenames:
                path = root / relative
                if not path.is_file():
                    continue
                try:
                    payload = json.loads(path.read_text())
                except (OSError, ValueError, TypeError):
                    continue
                if isinstance(payload, dict):
                    return {"path": str(path.resolve()), "payload": payload}
        return None

    @staticmethod
    def _interpretation_package_from_artifact(artifact):
        """Project a successful interpretation output into its package shape."""
        if not isinstance(artifact, dict):
            return None
        payload = artifact.get("payload")
        if not isinstance(payload, dict):
            return None
        if (payload.get("schema_version") == "scientific-interpretation-package-1"
                and isinstance(payload.get("interpretation"), dict)):
            return deepcopy(payload)
        if (payload.get("schema_version") == "scientific-interpretation-1"
                and set(payload) >= {"schema_version", "research_question"}):
            return {
                "schema_version": "scientific-interpretation-package-1",
                "interpretation": deepcopy(payload),
                "status": "accepted",
            }
        return None

    def _materialize_forward_progress(self, stage, attempt_stage, error, context,
                                      specialist_bundle, attempt_history,
                                      *, force_advance=False):
        """Create an honest provisional node so the agenda can keep moving."""
        if not self._forward_first() and not force_advance:
            return None
        stage_id = stage.get("id") if isinstance(stage, dict) else None
        # The durable context is authoritative when failure analysis has
        # already issued a repair order. A caller may still hold the pre-error
        # runner envelope, especially after a model-contract failure. Check
        # both packets so a stale local projection cannot turn an unexecuted
        # experiment into a downstream input.
        authoritative_context = (
            self.context.get(stage_id) if isinstance(stage_id, str) else None
        )
        if (isinstance(stage, dict)
                and stage.get("kind") == "experiment"
                and isinstance(authoritative_context, dict)
                and self._experiment_handoff_requires_recovery(
                    stage, authoritative_context)):
            return None
        # Do not erase a scoped scientific repair order by materializing a
        # provisional packet.  This is a defensive second line behind
        # ``_composer_can_advance_after_admission`` for restored/legacy
        # checkpoints whose context was reconstructed between those calls.
        existing_recovery = (
            context.get("failure_recovery") if isinstance(context, dict) else None
        )
        existing_requests = context.get("research_requests") if isinstance(context, dict) else None
        if self._experiment_handoff_requires_recovery(stage, context):
            return None
        if (isinstance(existing_recovery, dict)
                and existing_recovery.get("recovery_mode") == "repair_then_rerun"
                and isinstance(existing_requests, list)
                and existing_requests):
            return None
        if (self._is_pre_execution_capability_failure(stage, context, error)
                and not force_advance):
            # An unexecuted generated program is not a useful provisional
            # result. Keep the failure scoped so the Composer can pivot the
            # executable direction instead of parking behind a release gate.
            return None
        failure_class = self._forward_failure_class(error)
        if failure_class in {"resource_fence", "operational_recovery", "unknown_external_outcome",
                             "process_interruption"} and not force_advance:
            return None
        stage_id = stage["id"]
        candidate = deepcopy(context) if isinstance(context, dict) else {}
        incumbent = self.context.get(stage_id)
        if not candidate and isinstance(incumbent, dict):
            candidate = deepcopy(incumbent)
        prior_artifact = self._prior_stage_artifact(stage, attempt_history)
        if stage.get("kind") == "interpretation":
            prior_package = self._interpretation_package_from_artifact(prior_artifact)
            if prior_package is not None and not isinstance(candidate.get("interpretation"), dict):
                # The scientific packet is explicitly marked as incumbent
                # evidence.  It is not re-admitted as a fresh interpretation;
                # the current failure debt remains attached to the handoff.
                candidate["interpretation"] = prior_package
                candidate["binding_output_path"] = prior_artifact["path"]
                candidate["incumbent_interpretation_path"] = prior_artifact["path"]
        elif stage.get("kind") == "argument" and prior_artifact is not None:
            # Paper composition may still inspect a prior argument while the
            # current repair is carried as debt.  Keep the visible forward
            # progress path separate from the immutable binding artifact.
            candidate["binding_output_path"] = prior_artifact["path"]
            candidate["incumbent_argument_path"] = prior_artifact["path"]
        if stage["kind"] == "topic_discovery" and not isinstance(candidate.get("topic"), dict):
            selected = self._topic_candidate_from_failure(error)
            if selected is None:
                if not force_advance:
                    # A topic-less packet cannot feed a survey honestly. It gets a
                    # bounded retry/pivot, not a fabricated question.
                    return None
                candidate["topic_resolution"] = "unresolved_after_composer_admission"
            else:
                candidate.update({
                    "topic": selected,
                    "selected_id": selected["id"],
                    "admission_state": "provisional_for_survey",
                })

        # Runner envelopes do not always repeat the workspace identity on a
        # late validation failure.  The attempt directory is the immutable
        # source of the survey/experiment handoff and must remain addressable
        # even when the public result is provisional.
        candidate.setdefault(
            "project_dir", str(Path(attempt_stage["project_dir"]).resolve()))

        output_root = Path(attempt_stage["project_dir"]).resolve() / "output"
        output_root.mkdir(parents=True, exist_ok=True)
        output_path = output_root / "forward-progress.json"
        available = {
            key: deepcopy(candidate.get(key))
            for key in (
                "output_path", "project_dir", "survey_ref", "assessment_ref",
                "nomination_ref", "incumbent_ref", "survey_current", "assessment_current",
                "gap_state", "topic_admission", "results_package", "argument_package_path",
                "topic", "selected_id", "results_status", "evidence_state",
                "binding_output_path", "incumbent_interpretation_path",
                "incumbent_argument_path",
            )
            if key in candidate
        }
        specialist_findings = []
        if isinstance(specialist_bundle, dict):
            for report in specialist_bundle.get("reports", []):
                if not isinstance(report, dict):
                    continue
                specialist_findings.append({
                    key: deepcopy(report[key])
                    for key in ("role_id", "status", "status_code", "error",
                                "artifact_ref", "verifier_artifact_ref")
                    if key in report
                })
        debt = {
            "stage_id": stage_id,
            "kind": stage["kind"],
            "failure_class": failure_class,
            "error": str(error)[:4096],
            "attempts": len(attempt_history),
            "next_action": "backfill this scope after the agenda completes higher-value work",
            "release_blocking": False if force_advance else True,
            "authority": "command.composer" if force_advance else "stage_runner",
        }
        body = {
            "schema_version": "composer-forward-progress-1",
            "status": "candidate_needs_review",
            "provisional": True,
            "stage_id": stage_id,
            "kind": stage["kind"],
            "composer_decision": "advance_with_findings" if force_advance else "defer",
            "evidence_state": "unverified",
            "failure_debt": debt,
            "available_context": available,
            "specialist_findings": specialist_findings,
            "attempt_history": deepcopy(attempt_history[-8:]),
            "usage": deepcopy(candidate.get("usage", {}))
                if isinstance(candidate.get("usage"), dict) else {},
            "specialist_usage": deepcopy(specialist_bundle.get("usage", {}))
                if isinstance(specialist_bundle, dict) else {},
        }
        if isinstance(prior_artifact, dict):
            package = self._interpretation_package_from_artifact(prior_artifact)
            if package is not None:
                # Keep the handoff self-contained for a legacy resume that
                # reconstructs context from only forward-progress.json.
                body["provisional_interpretation"] = package
                body["provisional_interpretation_path"] = prior_artifact["path"]
        artifact = self._publish(
            f"command/composer/forward-progress/{stage_id}/{self.continuation_cycles}-"
            f"{len(attempt_history)}",
            "note", body, "command.composer",
        )
        body["artifact_ref"] = artifact["artifact_ref"]
        output_path.write_bytes(canonical_bytes(body))

        candidate.update({
            "stage_id": stage_id,
            "kind": stage["kind"],
            "status": "candidate_needs_review",
            "provisional": True,
            "forward_progress": True,
            "composer_decision": "advance_with_findings" if force_advance else "defer",
            "progression_state": "advanced_with_findings" if force_advance else "deferred",
            "evidence_state": "unverified",
            "release_blocking": False if force_advance else True,
            "forward_progress_artifact": artifact["artifact_ref"],
            "forward_progress_path": str(output_path),
            "failure_debt": debt,
            "output_path": str(output_path),
            # Do not let a technical failure immediately regenerate the same
            # continuation. The debt is visible and can be backfilled later.
            "research_expansion_requests": [],
            "research_requests": [],
            "deferred_research_requests": [debt],
            "backfill_required": True,
            "preserve_work_orders": True,
        })
        if stage["kind"] == "survey":
            candidate.setdefault("gap_state", "insufficient_evidence")
            candidate.setdefault("topic_admission", "exploratory_pilot")
            candidate.setdefault("survey_current", False)
            candidate.setdefault("assessment_current", False)
        if stage["kind"] == "experiment":
            candidate.setdefault("results_status", "not_executed")
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "forward_provisional_stage",
            "stage_id": stage_id,
            "failure_class": failure_class,
            "artifact_ref": artifact["artifact_ref"],
            "composer_decision": "advance_with_findings" if force_advance else "defer",
            "release_blocking": False if force_advance else True,
            "next_action": debt["next_action"],
        })
        if force_advance:
            self._mark_forward_blockers_advisory(stage_id)
        return candidate

    def _remaining(self):
        remaining = self.deadline - self.clock()
        if isinstance(self.deadline_epoch, (int, float)) and math.isfinite(self.deadline_epoch):
            remaining = min(remaining, self.deadline_epoch - time.time())
        if remaining <= 0:
            raise ComposerHardDeadlineExceeded("composer hard deadline exceeded")
        return remaining

    def _stage_remaining(self, stage):
        """Consume the admitted attempt's wall time across all of its phases."""
        if isinstance(stage, str):
            stage = next(item for item in self.workflow["stages"] if item["id"] == stage)
        remaining = min(float(stage["deadline_seconds"]), self._remaining())
        deadline = stage.get("attempt_deadline_at_epoch")
        if deadline is None:
            deadline = self.stage_records.get(stage["id"], {}).get("attempt_deadline_at_epoch")
        if type(deadline) in (int, float) and math.isfinite(deadline):
            remaining = min(remaining, deadline - time.time())
        if remaining <= 0:
            raise ComposerStageDeadlineExceeded(f"stage attempt deadline exceeded: {stage['id']}")
        return remaining

    def _deadline_dispatch_floor(self):
        """Return the small control-plane window needed for safe dispatch.

        Stage estimates are forecasts, not execution fences.  In the
        deadline-governed mode, a residual window may still produce a useful
        accepted stage result, so the Composer keeps admitting work until only
        this checkpoint-and-ledger margin remains.  The margin follows the
        configured checkpoint cadence and is capped to keep it small relative
        to a scientific stage.
        """
        checkpoint = float(self.workflow["time_policy"]["checkpoint_seconds"])
        return max(0.5, min(5.0, checkpoint / 10.0))

    def _deadline_exhausted(self):
        """Return whether the immutable mission wall has been reached."""
        remaining = self.deadline - self.clock()
        if isinstance(self.deadline_epoch, (int, float)) and math.isfinite(self.deadline_epoch):
            remaining = min(remaining, self.deadline_epoch - time.time())
        return remaining <= 0

    def _extend_deadline(self, additional_seconds):
        """Apply an explicit human extension without mutating the workflow graph."""
        if not isinstance(additional_seconds, (int, float)) or isinstance(additional_seconds, bool) \
                or not math.isfinite(additional_seconds) or additional_seconds <= 0:
            raise ValidationError("additional_seconds must be finite and positive")
        extension = float(additional_seconds)
        if self._workflow_record is None and not (self.root / "state" / "control.sqlite").exists():
            raise ValidationError("a deadline extension requires an existing Composer project")
        old_deadline_epoch = self.deadline_epoch
        old_deadline = self.deadline
        new_deadline_epoch = old_deadline_epoch + extension
        new_deadline = old_deadline + extension
        body = {
            "schema_version": "composer-deadline-extension-1",
            "workflow_id": self.workflow["id"], "run_id": self.run_id,
            "additional_seconds": extension,
            "previous_deadline_at_epoch": old_deadline_epoch,
            "deadline_at_epoch": new_deadline_epoch,
            "created_at": now_iso(),
        }
        record = self._publish(
            f"command/composer/deadline-extensions/{uuid.uuid4().hex}",
            "decision_note", body, "principal")
        self.deadline_epoch = new_deadline_epoch
        self.deadline = new_deadline
        self.deadline_extensions.append({
            "additional_seconds": extension,
            "previous_deadline_at_epoch": old_deadline_epoch,
            "deadline_at_epoch": new_deadline_epoch,
            "artifact_ref": record["artifact_ref"],
        })
        # Persist the extension immediately.  If the process is interrupted
        # before the next stage boundary, resume still sees the new mission
        # wall rather than silently discarding the human decision.
        self._checkpoint("deadline_extended", force=True)

    def interim_report(self, *, stop_reason=None, persist=True):
        """Return and optionally persist a concise human-readable run snapshot.

        The Composer's full checkpoint and ledger remain the source of truth.
        This projection is intentionally small: it tells an operator what was
        completed, what is active or held, why execution stopped, and exactly
        how to resume with an explicit deadline extension.
        """
        now = self.clock()
        remaining = self.deadline - now
        if isinstance(self.deadline_epoch, (int, float)) and math.isfinite(self.deadline_epoch):
            remaining = min(remaining, self.deadline_epoch - time.time())
        rows = []
        completed, active, pending, held, blocked = [], [], [], [], []
        for stage in self.workflow["stages"]:
            stage_id = stage["id"]
            record = self.stage_records.get(stage_id, {})
            status = record.get("status", "pending")
            attempts = record.get("attempts", [])
            if not isinstance(attempts, list):
                attempts = []
            attempt_count = record.get("attempt_count", len(attempts))
            if type(attempt_count) is not int or attempt_count < 0:
                attempt_count = len(attempts)
            row = {
                "id": stage_id,
                "kind": stage["kind"],
                "status": status,
                "attempts": attempt_count,
            }
            output_path = record.get("output_path")
            if isinstance(output_path, str) and output_path:
                row["output_path"] = output_path
            error = record.get("error")
            if isinstance(error, str) and error:
                row["error"] = error[:240]
            rows.append(row)
            if status in STAGE_READY_STATUSES:
                completed.append(stage_id)
            elif status in {"running", "retrying"}:
                active.append(stage_id)
            elif status in STAGE_HOLD_STATUSES:
                held.append(stage_id)
            elif status == "blocked":
                blocked.append(stage_id)
            else:
                pending.append(stage_id)
        if stop_reason is None:
            if self._deadline_exhausted():
                stop_reason = "hard_deadline"
            else:
                active_blockers = self._active_blockers()
            if stop_reason is None and self.status == "paused" and any(
                    isinstance(item, dict)
                    and item.get("reason") == "required_stage_window_does_not_fit_remaining_deadline"
                    for item in active_blockers):
                stop_reason = "required_stage_window_does_not_fit_remaining_deadline"
            elif stop_reason is None and self.status == "paused" and any(
                    isinstance(item, dict)
                    and item.get("reason") == "provider_cooldown"
                    for item in active_blockers):
                stop_reason = "provider_cooldown"
            if stop_reason is None:
                stop_reason = self.status
        organization = self.organization_snapshot if isinstance(self.organization_snapshot, dict) else {}
        open_orders = organization.get("open_work_orders", [])
        if not isinstance(open_orders, list):
            open_orders = []
        orders = []
        for item in open_orders[:8]:
            if not isinstance(item, dict):
                continue
            orders.append({key: item[key] for key in (
                "task_id", "department", "state", "kind", "objective") if key in item})
        blockers = []
        for item in self.blockers[-3:]:
            if isinstance(item, dict):
                blockers.append({key: item[key] for key in (
                    "stage_id", "reason", "provider_error", "retry_after_seconds",
                    "retry_after_epoch", "rate_limit", "attempts", "usage",
                    "diagnostics", "candidate_attempt_trace", "maturity_review_history",
                    "rejected_topic_history") if key in item})
            else:
                blockers.append({"reason": str(item)[:240]})
        active_blockers = self._active_blockers()
        report = {
            "schema_version": "composer-interim-report-1",
            "workflow_id": self.workflow["id"],
            "run_id": self.run_id,
            "status": self.status,
            "stop_reason": stop_reason,
            "last_phase": self._progress_snapshot.get("phase", self.status),
            "elapsed_seconds": max(0.0, now - self.started),
            "remaining_seconds": max(0.0, remaining),
            "deadline_seconds": self.workflow["time_policy"]["hard_seconds"],
            "started_at_epoch": self.started_epoch,
            "deadline_at_epoch": self.deadline_epoch,
            "completed_stage_ids": completed,
            "active_stage_ids": active,
            "pending_stage_ids": pending,
            "held_stage_ids": held,
            "blocked_stage_ids": blocked,
            "stages": rows,
            "pending_work_orders": orders,
            "blockers": blockers,
            "active_blockers": deepcopy(active_blockers),
            "blocker_counts": {
                "active": len(active_blockers),
                "historical": len(self.blockers),
            },
            "deadline_decisions": deepcopy(self.deadline_decisions),
            "deadline_extensions": deepcopy(self.deadline_extensions),
            "next_actions": [
                "Extend the deadline and resume the same workflow."
                if stop_reason in {"hard_deadline", "required_stage_window_does_not_fit_remaining_deadline"}
                else "Inspect the blocker and resume the same workflow after the cause is recoverable.",
                "Resume reconciles interrupted attempts before dispatching a fresh isolated attempt.",
            ],
            "resume_hint": (
                "python -m scisaurus.cli run-composer --workflow "
                "<path-to-the-same-workflow.json> --resume --extend-deadline-seconds <N>"
            ),
        }
        if persist:
            output = self.root / "output"
            output.mkdir(parents=True, exist_ok=True)
            artifact_ref = None
            artifact_error = None
            if self.control is not None:
                try:
                    artifact = self._publish(
                        "command/composer/interim-report", "report", report, "command.composer")
                    artifact_ref = artifact["artifact_ref"]
                except Exception as exc:
                    artifact_error = f"{type(exc).__name__}: {exc}"
            persisted = {**report, "artifact_ref": artifact_ref,
                         "path": str((output / "interim_report.json").resolve())}
            if artifact_error:
                persisted["artifact_error"] = artifact_error
            temporary = output / f"interim-report-{uuid.uuid4().hex}.tmp"
            temporary.write_bytes(canonical_bytes(persisted))
            temporary.replace(output / "interim_report.json")
            report = persisted
        return report

    def _is_superseded_stale_task_blocker(self, blocker):
        """Release stale task blockers only when durable history proves they are obsolete.

        A terminal task cannot be resumed under its old identity. A
        ``result_unknown`` attempt remains conservatively accounted, but it
        need not gate today's frontier when a later successful stage attempt
        for the current topic has superseded it.
        """
        reason = str(blocker.get("reason", "")) if isinstance(blocker, dict) else ""
        completed_match = re.search(
            r"task (?P<task_id>[A-Za-z0-9_.:-]*?(?P<stage_id>topic|survey|experiment|interpretation|argument|paper)"
            r"-continuation-(?P<cycle>[1-9][0-9]*)) not dispatchable \(state=stale\)",
            reason,
        )
        match = re.search(
            r"task (?P<task_id>[A-Za-z0-9_.:-]+-continuation-(?P<cycle>[1-9][0-9]*)) "
            r"already has unresolved attempt (?P<attempt_id>[A-Za-z0-9_.:-]+) "
            r"\(state=(?P<observed_state>[^)]*)\)",
            reason,
        )
        if completed_match:
            cycle = int(completed_match.group("cycle"))
            if cycle >= self.continuation_cycles:
                return False
            try:
                task = self.tasks.get(completed_match.group("task_id"))
                attempts = self.tasks.attempts_for_task(task["task_id"])
            except NotFoundError:
                return False
            task_payload = task.get("payload")
            task_payload = task_payload if isinstance(task_payload, dict) else {}
            stage_id = task_payload.get("stage_id") or completed_match.group("stage_id")
            if (task.get("state") != "stale"
                    or stage_id != completed_match.group("stage_id")
                    or not attempts):
                return False
            stage_record = self.stage_records.get(stage_id)
            history = stage_record.get("attempts", []) if isinstance(stage_record, dict) else []
            if not isinstance(history, list):
                return False
            current_topic = self._current_topic_identity()
            later_results = []
            unresolved_count = 0
            for attempt in attempts:
                if attempt.get("task_id") != task["task_id"]:
                    return False
                payload = attempt.get("payload")
                payload = payload if isinstance(payload, dict) else {}
                attempt_number = payload.get("attempt_number")
                if ((payload.get("stage_id") or stage_id) != stage_id
                        or type(attempt_number) is not int):
                    return False
                source = next((item for item in history
                               if isinstance(item, dict)
                               and type(item.get("attempt_number")) is int
                               and item["attempt_number"] == attempt_number
                               and type(item.get("cycle")) is int
                               and item["cycle"] == cycle), None)
                if source is None:
                    return False

                state = attempt.get("state")
                if state in {"started", "result_unknown"}:
                    unresolved_count += 1
                    if (source.get("state") not in {"unknown", "result_unknown", "started"}
                            or not isinstance(current_topic, dict)
                            or not isinstance(current_topic.get("topic_id"), str)
                            or not current_topic["topic_id"]
                            or type(current_topic.get("topic_cycle")) is not int
                            or not isinstance(source.get("topic_id"), str)
                            or not source["topic_id"]
                            or type(source.get("topic_cycle")) is not int
                            or source["topic_cycle"] < 1):
                        return False
                    eligible = [
                        item for item in history
                        if isinstance(item, dict)
                        and type(item.get("attempt_number")) is int
                        and item["attempt_number"] > attempt_number
                        and type(item.get("cycle")) is int
                        and item["cycle"] >= cycle
                        and item.get("state") in {"succeeded", "completed"}
                        and item.get("topic_id") == current_topic["topic_id"]
                        and type(item.get("topic_cycle")) is int
                        and item["topic_cycle"] == current_topic["topic_cycle"]
                    ]
                    if not eligible:
                        return False
                    later_results.extend(eligible)
                    continue

                if state in {"succeeded", "completed"}:
                    if source.get("state") not in {"succeeded", "completed"}:
                        return False
                    later_results.append(source)
                    continue
                if state not in {"failed", "cancelled"} or source.get("state") != state:
                    return False
                eligible = [
                    item for item in history
                    if isinstance(item, dict)
                    and type(item.get("attempt_number")) is int
                    and item["attempt_number"] > attempt_number
                    and type(item.get("cycle")) is int
                    and item["cycle"] >= cycle
                    and item.get("state") in {"succeeded", "completed"}
                ]
                if not eligible:
                    return False
                later_results.extend(eligible)

            if not later_results:
                return False
            latest = max(later_results, key=lambda item: item["attempt_number"])
            blocker.update({
                "gating": False,
                "release_blocking": False,
                "recovery": ("historical_stale_task_unknown_outcome_superseded"
                             if unresolved_count else
                             "historical_stale_task_superseded_by_later_stage_result"),
                "task_id": task["task_id"],
                "task_state": task["state"],
                "task_attempt_states": [attempt.get("state") for attempt in attempts],
                "superseded_by_stage_attempt_number": latest["attempt_number"],
                "superseded_by_cycle": latest["cycle"],
                "unknown_attempt_accounting": [
                    attempt.get("usage", {}).get("accounting")
                    for attempt in attempts
                    if attempt.get("state") in {"started", "result_unknown"}
                    and isinstance(attempt.get("usage"), dict)
                ],
            })
            return True
        if not match or int(match.group("cycle")) >= self.continuation_cycles:
            return False
        try:
            task = self.tasks.get(match.group("task_id"))
            attempt = self.tasks.get_attempt(match.group("attempt_id"))
        except NotFoundError:
            return False
        if (task.get("state") != "stale"
                or attempt.get("task_id") != task.get("task_id")
                or attempt.get("state") not in {
                    "result_unknown", "succeeded", "failed", "cancelled",
                }):
            return False
        task_payload = task.get("payload")
        attempt_payload = attempt.get("payload")
        task_payload = task_payload if isinstance(task_payload, dict) else {}
        attempt_payload = attempt_payload if isinstance(attempt_payload, dict) else {}
        stage_id = attempt_payload.get("stage_id") or task_payload.get("stage_id")
        attempt_number = attempt_payload.get("attempt_number")
        stage_record = self.stage_records.get(stage_id)
        history = stage_record.get("attempts", []) if isinstance(stage_record, dict) else []
        cycle = int(match.group("cycle"))
        topic = self._current_topic_identity()
        if (type(attempt_number) is not int or not isinstance(history, list)
                or not isinstance(topic, dict)
                or not isinstance(topic.get("topic_id"), str)
                or not topic["topic_id"]
                or type(topic.get("topic_cycle")) is not int):
            return False
        source = next((item for item in history
                       if isinstance(item, dict)
                       and type(item.get("attempt_number")) is int
                       and item.get("attempt_number") == attempt_number
                       and type(item.get("cycle")) is int
                       and item.get("cycle") == cycle
                       and item.get("state") in {"unknown", "result_unknown", "started"}), None)
        if (source is None
                or not isinstance(source.get("topic_id"), str)
                or not source.get("topic_id")
                or type(source.get("topic_cycle")) is not int
                or source.get("topic_cycle") < 1):
            return False
        newer = []
        for item in history:
            if (not isinstance(item, dict)
                    or type(item.get("attempt_number")) is not int
                    or item["attempt_number"] <= attempt_number
                    or type(item.get("cycle")) is not int
                    or item["cycle"] < cycle
                    or item.get("state") not in {"succeeded", "completed"}):
                continue
            if isinstance(topic, dict):
                item_topic_id = item.get("topic_id")
                item_topic_cycle = item.get("topic_cycle")
                if (type(item_topic_cycle) is not int
                        or item_topic_id != topic.get("topic_id")
                        or item_topic_cycle != topic.get("topic_cycle")):
                    continue
            newer.append(item)
        if not newer:
            return False
        latest = max(newer, key=lambda item: item["attempt_number"])
        attempt_usage = attempt.get("usage")
        same_topic_lineage = (
            source.get("topic_id") == topic["topic_id"]
            and source.get("topic_cycle") == topic["topic_cycle"]
        )
        blocker.update({
            "gating": False,
            "release_blocking": False,
            "recovery": (
                "historical_stale_task_unknown_outcome_superseded_by_current_topic_result"
                if not same_topic_lineage else
                "historical_stale_task_superseded_by_later_result"
            ),
            "task_id": task.get("task_id"),
            "task_state": task.get("state"),
            "attempt_id": attempt.get("attempt_id"),
            "attempt_state": attempt.get("state"),
            "attempt_accounting": attempt_usage.get("accounting")
            if isinstance(attempt_usage, dict) else None,
            "superseded_by_stage_id": stage_id,
            "superseded_by_attempt_number": latest["attempt_number"],
            "superseded_by_topic_id": topic["topic_id"],
            "superseded_by_topic_cycle": topic["topic_cycle"],
        })
        return True

    def _active_blockers(self):
        """Return blockers that still constrain the current Composer frontier.

        ``blockers`` is an append-only audit trail.  Treating its length as a
        live health signal made every recovered scientific failure look like
        a current stop, even after the Composer admitted a new continuation.
        A blocker is live only while its owning stage remains held/blocked or
        the mission itself is paused/blocked. Forwarded findings and scoped
        recoveries stay in the audit trail but do not gate the next action.
        """
        held_statuses = STAGE_HOLD_STATUSES | {
            "blocked", "paused", "candidate_needs_review",
        }
        stage_status = {
            stage_id: record.get("status")
            for stage_id, record in self.stage_records.items()
            if isinstance(record, dict)
        }
        mission_held = self.status in held_statuses
        stages = {item.get("id"): item for item in self.workflow.get("stages", [])
                  if isinstance(item, dict) and isinstance(item.get("id"), str)}
        active = []
        for item in self.blockers:
            if not isinstance(item, dict):
                if mission_held:
                    active.append({"reason": str(item)[:240]})
                continue
            if item.get("stage_id") is None:
                if self._is_superseded_stale_task_blocker(item):
                    continue
            if (item.get("gating") is False
                    or item.get("release_blocking") is False
                    or item.get("recovery") in {
                        "cycle_admitted",
                        "superseded_by_current_stage_state",
                    }
                    or item.get("disposition") == "forwarded_with_findings"):
                continue
            stage_id = item.get("stage_id")
            blocker_attempt = item.get("attempt_number")
            if type(blocker_attempt) is not int:
                dossier_ref = item.get("failure_dossier_ref")
                match = (re.search(r"/attempt-([1-9][0-9]*)@", dossier_ref)
                         if isinstance(dossier_ref, str) else None)
                blocker_attempt = int(match.group(1)) if match else None
            stage_record = self.stage_records.get(stage_id, {})
            if (blocker_attempt is None
                    and item.get("reason") == "provider_cooldown"
                    and type(item.get("attempts")) is int
                    and item["attempts"] > 0):
                # Older cooldown blockers stored the owning attempt count in
                # ``attempts`` but omitted ``attempt_number``.  That count is
                # written from len(attempt_history) when the blocker is
                # created, so it can be reconciled against durable stage
                # history without guessing from timestamps or error text.
                blocker_attempt = item["attempts"]
            if (item.get("reason") == "provider_cooldown"
                    and type(blocker_attempt) is int and blocker_attempt > 0):
                retry_epoch = item.get("retry_after_epoch")
                retry_expired = (
                    type(retry_epoch) in (int, float)
                    and math.isfinite(retry_epoch)
                    and retry_epoch <= time.time()
                )
                later_success = any(
                    isinstance(attempt, dict)
                    and type(attempt.get("attempt_number")) is int
                    and attempt["attempt_number"] > blocker_attempt
                    and attempt.get("state") in {"succeeded", "completed"}
                    for attempt in stage_record.get("attempts", [])
                ) if isinstance(stage_record.get("attempts", []), list) else False
                if retry_expired and later_success:
                    continue
            current_attempt = stage_record.get(
                "attempt_number", stage_record.get("attempt_count"))
            if (type(blocker_attempt) is int and type(current_attempt) is int
                    and blocker_attempt < current_attempt
                    and item.get("reason") != "provider_cooldown"):
                continue
            if (item.get("stop_reason") == "operator_stage_boundary"
                    and self.status == "paused" and stage_id == "workflow"
                    and item.get("boundary_stage_id") == self.stop_after_stage):
                active.append(deepcopy(item))
                continue
            if (item.get("stop_reason") == "process_interrupted"
                    and self.status == "paused" and stage_id == "workflow"):
                active.append(deepcopy(item))
                continue
            if (item.get("reason") == "required_stage_window_does_not_fit_remaining_deadline"
                    and self.status == "paused"):
                required = item.get("required_stage_seconds")
                remaining = self.deadline - self.clock()
                if isinstance(self.deadline_epoch, (int, float)) and math.isfinite(self.deadline_epoch):
                    remaining = min(remaining, self.deadline_epoch - time.time())
                if (type(required) in (int, float) and math.isfinite(required)
                        and remaining < required):
                    active.append(deepcopy(item))
                continue
            if item.get("stop_reason") == "missing_stage_input" and stage_id in stages:
                # Blockers are an append-only audit trail. A binding that was
                # absent on an earlier continuation must not keep stopping a
                # later run after the producer has emitted the artifact.
                if not self._stage_dependency_gaps(stages[stage_id]):
                    continue
            if stage_id is None:
                if mission_held:
                    active.append(deepcopy(item))
                continue
            if stage_status.get(stage_id) in held_statuses:
                active.append(deepcopy(item))
        return active

    def _retry_policy(self):
        """Return the Composer retry policy for this immutable run.

        ``until_deadline`` deliberately has no attempt-count stop condition.
        The hard wall and dependency admission remain the termination
        conditions; a residual stage may be admitted until the small
        control-plane margin, but it can never extend the mission wall.
        """
        configured = self.workflow.get("retry_policy") or {}
        policy = {**DEFAULT_RETRY_POLICY, **configured}
        # Before ``mode`` was introduced, the presence of ``max_attempts``
        # meant a bounded policy.  Preserve that unambiguous legacy contract
        # while an omitted policy gets the autonomous deadline-governed mode.
        if "mode" not in configured and "max_attempts" in configured:
            policy["mode"] = "bounded"
        if self._forward_first():
            # A forward-first mission never inherits an unbounded retry loop
            # from a legacy/template workflow. Even an explicit larger bounded
            # value is clamped: one blocker may not monopolize the provider
            # budget before the rest of the graph gets a turn.
            bounded = dict(FORWARD_FIRST_RETRY_POLICY)
            if isinstance(configured, dict) and type(configured.get("max_attempts")) is int:
                bounded["max_attempts"] = min(
                    FORWARD_FIRST_RETRY_POLICY["max_attempts"],
                    max(1, configured["max_attempts"]),
                )
            if isinstance(configured, dict) and type(configured.get("backoff_seconds")) in (int, float):
                bounded["backoff_seconds"] = max(0.0, float(configured["backoff_seconds"]))
            policy = bounded
        return policy

    def _continuation_policy(self):
        """Return the research-continuation policy for this immutable run."""
        configured = self.workflow.get("continuation_policy") or {}
        policy = {**DEFAULT_CONTINUATION_POLICY, **configured}
        # Preserve the pre-mode meaning of an explicitly supplied cycle count.
        if "mode" not in configured and "max_cycles" in configured:
            policy["mode"] = "bounded"
        if self._forward_first() and policy["mode"] != "until_deadline":
            bounded = dict(FORWARD_FIRST_CONTINUATION_POLICY)
            if isinstance(configured, dict) and type(configured.get("max_cycles")) is int:
                bounded["max_cycles"] = min(
                    FORWARD_FIRST_CONTINUATION_POLICY["max_cycles"],
                    max(0, configured["max_cycles"]),
                )
            policy = bounded
        return policy

    def _forward_first(self):
        """Whether this mission prioritizes a truthful next move over a hard stop.

        This is deliberately a Composer policy, not a relaxation of a stage's
        scientific claims. Release gates remain strict; the policy only
        decides what to do when the current attempt cannot produce an accepted
        artifact.
        """
        return self.workflow.get("progression_policy") == FORWARD_FIRST_POLICY

    def _allows_provisional_progress(self):
        """Whether the mission may carry an honest provisional draft."""
        return self.workflow.get("progression_policy") in {
            "full_pass", FORWARD_FIRST_POLICY,
        }

    def _agenda_policy(self):
        """Return how Composer chooses among dependency-ready research work.

        A workflow declaration remains a DAG of hard artifact dependencies.
        It is not interpreted as a preferred linear itinerary in adaptive
        mode. Workflows without an agenda declaration retain legacy ordered
        semantics; newly generated autonomous missions opt into adaptive mode.
        """
        configured = self.workflow.get("agenda_policy")
        if configured is not None:
            return {**DEFAULT_AGENDA_POLICY, **configured}
        if isinstance(self._restored_agenda_policy, dict):
            return deepcopy(self._restored_agenda_policy)
        if self._forward_first():
            return {"mode": "adaptive"}
        return deepcopy(DEFAULT_AGENDA_POLICY)

    @staticmethod
    def _autonomous_recovery_request_id(stage_id, cycle):
        base = re.sub(r"[^a-z0-9_.-]+", "-", str(stage_id).casefold()).strip("-")
        base = base[:24] or "stage"
        return f"auto-{base}-recovery-{cycle}"

    def _autonomous_recovery_request(self, stage_id, context):
        """Synthesize a new scoped move when a scientific hold gives no order.

        A stage-level ``hold`` is a result of the current attempt, not an
        instruction for a person to decide what happens next.  Reviewers and
        legacy runners do not always emit a typed research request, so the
        control plane derives one from the stage kind and the recorded
        blocker.  The cycle-specific strategy changes the work itself and
        gives the next attempt a reason to diverge instead of replaying the
        same prompt.  Environmental failures are deliberately excluded: they
        are handled by the provider cooldown, quota, and deadline fences.
        """
        if not isinstance(context, dict):
            return None
        stage_record = self.stage_records.get(stage_id, {})
        stage_kind = context.get("kind") or stage_record.get("kind")
        if stage_kind not in {"topic_discovery", "survey", "experiment",
                              "interpretation", "argument", "paper"}:
            return None
        if context.get("status") not in STAGE_HOLD_STATUSES:
            return None

        cycle = self.continuation_cycles + 1
        strategies = {
            "topic_discovery": (
                "abandon the rejected framing or frontier seed when necessary and pivot to an orthogonal mechanism, boundary, or observable",
                "change the evidence mode and comparison while preserving only the supported scientific core",
                "reframe the question around a discriminating prediction and a declared analytic or computational limit",
                "search a neighboring phenomenon with a different measurement and an explicit falsification test",
            ),
            "survey": (
                "expand exact terminology and citation chaining from primary studies",
                "search contradictory findings and neighboring terminology, then capture full-text evidence",
                "trace methods and results spans from the most relevant papers instead of adding abstract-only records",
                "run a boundary-focused counter-search across an adjacent field and reconcile identities before admission",
            ),
            "experiment": (
                "run a discriminating control or null-model comparison",
                "sweep the declared boundary and test whether the effect survives the relevant regimes",
                "perform an analytic-limit and sensitivity check with an independent recalculation",
                "change the measurement or baseline so the competing explanations make different predictions",
            ),
            "interpretation": (
                "construct the strongest alternative mechanism and identify its discriminating observable",
                "separate observation from mechanism across the declared parameter regimes",
                "recalculate the interpretation at the analytic limit and state the boundary of inference",
                "relink every material claim to evidence and downgrade any explanation the data cannot distinguish",
            ),
            "argument": (
                "rebuild the claim-evidence graph around the strongest supported result",
                "reorder the narrative around the decisive comparison and expose the main limitation",
                "remove unsupported causal steps and add the missing mechanism-to-observation bridge",
                "write a competing explanation and show exactly which evidence favors or fails to favor it",
            ),
            "paper": (
                "recompose the manuscript around the accepted evidence and the unresolved reviewer findings",
                "repair the weakest claim-evidence links and make all scope boundaries explicit",
                "rebuild the results and discussion transitions so observations are not presented as mechanisms",
                "perform a publication-level rejection pass, then revise every retained blocking finding",
            ),
        }
        strategy = strategies[stage_kind][(cycle - 1) % len(strategies[stage_kind])]

        evidence = []
        verifier = context.get("specialist_verifier")
        response = verifier.get("response") if isinstance(verifier, dict) else None
        if not isinstance(response, dict):
            response = {}
        for key in ("repair_scope", "critical_findings", "required_changes"):
            value = response.get(key)
            if isinstance(value, list):
                evidence.extend(str(item).strip() for item in value if str(item).strip())
        for key in ("rationale", "error", "gap_state", "topic_admission", "review_status"):
            value = response.get(key) if key in response else context.get(key)
            if isinstance(value, str) and value.strip():
                evidence.append(value.strip())
        evidence_text = "; ".join(dict.fromkeys(evidence))
        if not evidence_text:
            evidence_text = "the current stage returned a scientific hold without a typed repair request"
        evidence_text = evidence_text[:1800]

        request_id = self._autonomous_recovery_request_id(stage_id, cycle)
        if stage_kind == "topic_discovery":
            return {
                "id": request_id,
                "kind": "topic_refinement",
                "owner": "research.intelligence",
                "objective": (
                    "Preserve the parent's scientific phenomenon and independently refine the failed "
                    f"mechanism, observable, comparison, or scope: {strategy}."
                ),
                "why": (
                    "The topic stage produced a scientific hold without a complete typed repair order. "
                    f"Recovery cycle {cycle} must address the recorded evidence, not abandon the line or merely reword it."
                ),
                "success_condition": (
                    "A source-grounded refinement preserves the parent's phenomenon unless evidence directly refutes it or proves infeasible, addresses the blocker, survives maturity and adversarial review, and enters survey."
                ),
                "evidence_needed": evidence_text,
                "salvage_policy": "bounded_salvage_before_structural_pivot",
                "salvage_branch_limit": 3,
                "source_stage_id": stage_id,
            }
        if stage_kind == "survey":
            quota_recovery = isinstance(context.get("quota_recovery"), dict)
            return {
                "id": request_id,
                "kind": "literature_expansion",
                "owner": "research.intelligence",
                "objective": (
                    (
                        f"Resume the literature stage from accepted checkpoints with a narrower decisive gate: {strategy}. "
                        "Do not replay the exhausted catalog or repeat already accepted source work. "
                        "Spend the fresh allocation only on the missing gap decision."
                        if quota_recovery else
                        f"Re-run the literature stage with a changed retrieval strategy: {strategy}. "
                        "Update the gap assessment from identity-reconciled primary and full-text evidence."
                    )
                ),
                "why": (
                    f"The survey exhausted its local stage allocation before the decisive gate. Recorded blocker: {evidence_text}"
                    if quota_recovery else
                    f"The survey hold was not accompanied by an executable repair order. Recorded blocker: {evidence_text}"
                ),
                "success_condition": (
                    "The refreshed survey either establishes an experiment-worthy gap or emits evidence for a substantive topic redesign."
                ),
                "evidence_needed": "Primary-study records, citation-chain results, full-text spans, contradiction checks, and a refreshed gap assessment.",
                "source_stage_id": stage_id,
            }
        if stage_kind == "experiment":
            return {
                "id": request_id,
                "kind": "additional_experiment",
                "owner": "methods.validation",
                "objective": (
                    f"Run a fresh discriminating analysis or experiment: {strategy}. Preserve raw observations and independently recalculate the primary estimand."
                ),
                "why": f"The methods stage returned a scientific hold without a complete typed repair order. Recorded blocker: {evidence_text}",
                "success_condition": "The new declared control, boundary, or sensitivity result separates the retained explanations or records why it cannot.",
                "evidence_needed": "Versioned raw output, prespecified control or baseline, primary estimand, independent recalculation, and limitations.",
                "source_stage_id": stage_id,
            }
        if stage_kind in {"interpretation", "argument"}:
            request = {
                "id": request_id,
                "kind": "interpretation_expansion",
                "owner": "strategy.interpretation",
                "objective": (
                    f"Rebuild the scientific interpretation and downstream argument: {strategy}. Keep unsupported mechanisms provisional."
                ),
                "why": f"The strategy stage returned a scientific hold without a complete typed repair order. Recorded blocker: {evidence_text}",
                "success_condition": "Every material claim is linked to an observation or source, alternatives are separated, and the independent reviewer accepts the revised argument.",
                "evidence_needed": "Claim-evidence graph, competing explanations, boundary conditions, recalculated results, and explicit uncertainty language.",
                "source_stage_id": stage_id,
            }
            # Strategy owns the repair brief, but the stage that produced the
            # rejected packet owns execution.  In particular, an argument
            # review must reopen argument before an unrelated survey order;
            # the department kind alone cannot express that distinction.
            request.update({
                "target_stage_id": stage_id,
                "target_stage_kind": stage_kind,
                "repair_priority": "immediate",
            })
            return request
        return {
            "id": request_id,
            "kind": "manuscript_revision",
            "owner": "editorial.composer",
            "objective": (
                f"Recompose and re-review the manuscript after the scientific hold: {strategy}. Preserve accepted results and repair the evidence chain."
            ),
            "why": f"The paper stage returned a hold without a complete typed repair order. Recorded blocker: {evidence_text}",
            "success_condition": "The independent reviewer and editor accept the revised manuscript with no unresolved blocking finding or research request.",
            "evidence_needed": "Current manuscript, reviewer findings, accepted evidence map, revision ledger, and a fresh rendered PDF check.",
            "source_stage_id": stage_id,
        }

    def _continuation_requests(self):
        """Collect validated research requests that can reopen a scoped stage.

        A request is a scientific work order, not a prose edit.  The specialist
        runners validate its shape before it reaches this method; the Composer
        copies only the stable public fields into its control plan.  A malformed
        request is a durable rejection, not a reason to abort an otherwise
        recoverable run.
        """
        requests = []
        seen = set()
        suppressed_request_sources = set()
        for stage_id, context in self.context.items():
            if not isinstance(context, dict):
                continue
            if not self._request_context_matches_current_topic(stage_id, context):
                lineage = context.get("topic_lineage")
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "drop_superseded_topic_work_orders",
                    "stage_id": stage_id,
                    "superseded_topic_id": context.get("superseded_topic_id")
                    or (lineage.get("topic_id") if isinstance(lineage, dict) else None),
                })
                continue
            containers = []
            for label in (
                    "research_expansion_requests", "research_requests",
                    "deferred_research_requests"):
                if label not in context or context[label] is None:
                    continue
                value = context[label]
                containers.append((label, value))
            for label, candidates in containers:
                if not isinstance(candidates, list):
                    rejection = self.departments.reject_request(
                        candidates, source_stage_id=stage_id,
                        reason=f"{label} must be a list when supplied",
                    )
                    self.department_activity.append({
                        "action": "reject_work_order", "stage_id": stage_id,
                        "request_id": rejection["request_id"], "rejection": rejection,
                    })
                    continue
                for request in candidates:
                    raw_request = request
                    if label == "deferred_research_requests":
                        request = self._forward_debt_work_order(stage_id, request)
                        if request is None:
                            rejection = self.departments.reject_request(
                                raw_request, source_stage_id=stage_id,
                                reason="deferred failure debt could not be mapped to a stage work order",
                            )
                            self.department_activity.append({
                                "action": "reject_work_order", "stage_id": stage_id,
                                "request_id": rejection["request_id"], "rejection": rejection,
                            })
                            continue
                    if not isinstance(request, dict):
                        rejection = self.departments.reject_request(
                            request, source_stage_id=stage_id,
                            reason="work-order request must be an object",
                        )
                        self.department_activity.append({
                            "action": "reject_work_order", "stage_id": stage_id,
                            "request_id": rejection["request_id"], "rejection": rejection,
                        })
                        continue
                    item = {key: deepcopy(request.get(key)) for key in (
                        "id", "kind", "owner", "objective", "why", "success_condition", "evidence_needed")}
                    item["schema_version"] = "department-work-order-1"
                    try:
                        self.departments.validate_request(item)
                        if "resume_scopes" in request:
                            self._validate_survey_revalidation_scopes(request)
                    except ValidationError as exc:
                        rejection = self.departments.reject_request(
                            request, source_stage_id=stage_id,
                            reason=f"{type(exc).__name__}: {exc}",
                        )
                        self.department_activity.append({
                            "action": "reject_work_order", "stage_id": stage_id,
                            "request_id": rejection["request_id"], "rejection": rejection,
                        })
                        continue
                    request_id = item["id"]
                    if request_id in seen:
                        continue
                    item.pop("schema_version", None)
                    # These fields are controller metadata rather than part
                    # of the public department proposal schema. Keep them on
                    # the Composer work order so the next specialist sees the
                    # exact dossier and executable repair commands, while the
                    # department still validates the stable v1 proposal.
                    for key in (
                            "failure_dossier_ref", "failure_input_sha256",
                            "repair_commands", "acceptance_checks", "review_directives",
                            "model_diagnostics", "recovery_mode", "target_stage_id",
                            "target_stage_kind", "repair_priority", "repair_policy_revision",
                            "recovery_generation", "resume_scopes",
                            "source_survey_ref", "source_assessment_ref",
                            "experiment_repair_plan",
                            "repair_strategy", "attempt_lineage"):
                        if key in request:
                            item[key] = deepcopy(request[key])
                    item["source_stage_id"] = stage_id
                    topic_identity = self._current_topic_identity()
                    if topic_identity is not None:
                        item["topic_id"] = topic_identity["topic_id"]
                        item["topic_cycle"] = topic_identity["topic_cycle"]
                    if self._research_request_signature(item) in self._attempted_request_signatures:
                        suppressed_request_sources.add(stage_id)
                        continue
                    requests.append(item)
                    seen.add(request_id)
            if context.get("status") in STAGE_HOLD_STATUSES:
                # A hold with a valid request is routed as emitted.  If the
                # request was malformed, empty, or already attempted, create
                # a cycle-specific strategy so the lab still has a concrete
                # next move instead of escalating an ordinary scientific
                # judgment to a person.
                stage_requests = [
                    item for item in requests
                    if isinstance(item, dict) and item.get("source_stage_id") == stage_id
                ]
                if not stage_requests and stage_id not in suppressed_request_sources:
                    item = self._autonomous_recovery_request(stage_id, context)
                    if (isinstance(item, dict)
                            and item.get("id") not in seen
                            and self._research_request_signature(item)
                            not in self._attempted_request_signatures):
                        requests.append(item)
                        seen.add(item["id"])
        # A topic refinement replaces the downstream closure. Do not carry a
        # survey/experiment repair order from the superseded frontier into the
        # new topic; the next survey and experiment must be derived from the
        # newly admitted question. A same-stage response-contract recovery is
        # different: it repairs the failed pivot dispatch and must travel with
        # that pivot instead of being discarded here.
        topic_requests = [
            item for item in requests
            if self._is_topic_pivot_request(item)
        ]
        topic_stage_ids = {
            stage.get("id") for stage in self.workflow.get("stages", [])
            if isinstance(stage, dict) and stage.get("kind") == "topic_discovery"
        }
        topic_contract_repairs = [
            item for item in requests
            if isinstance(item, dict)
            and item.get("kind") == "recovery"
            and item.get("target_stage_id") in topic_stage_ids
            and item.get("source_stage_id") == item.get("target_stage_id")
        ]
        topic_refinement_requests = [
            item for item in requests
            if isinstance(item, dict) and item.get("kind") == "topic_refinement"
        ]
        if topic_contract_repairs and topic_refinement_requests:
            # Do not ask one call to repair a response schema and redesign the
            # science simultaneously.  The scoped refinement remains in its
            # source context and is admitted after the contract repair.
            return topic_contract_repairs
        if not topic_requests:
            pending_pivot_recoveries = [
                item for item in topic_contract_repairs
                if isinstance(self.context.get(item["target_stage_id"]), dict)
                and isinstance(
                    self.context[item["target_stage_id"]].get("topic_pivot"), dict)
                and self.context[item["target_stage_id"]]["topic_pivot"].get("status") == "required"
            ]
            if pending_pivot_recoveries:
                return pending_pivot_recoveries
            return requests
        topic_stage_ids = {
            item.get("source_stage_id") for item in topic_requests
            if isinstance(item.get("source_stage_id"), str)
        }
        topic_contract_repairs = [
            item for item in topic_contract_repairs
            if item.get("target_stage_id") in topic_stage_ids
        ]
        return topic_requests + topic_contract_repairs

    @staticmethod
    def _continuation_targets(requests, by_id):
        """Map research work orders to the smallest stage closure that can answer them."""
        target_kinds = set()
        target_ids = set()
        for request in requests:
            explicit_stage_id = request.get("target_stage_id") if isinstance(request, dict) else None
            if isinstance(explicit_stage_id, str) and explicit_stage_id in by_id:
                target_ids.add(explicit_stage_id)
                continue
            kind = request.get("kind")
            owner = request.get("owner")
            if kind == "topic_refinement":
                target_kinds.add("topic_discovery")
            elif kind in {"literature_expansion", "full_text_retrieval"} or owner == "research.intelligence":
                target_kinds.add("survey")
            elif kind in {"additional_experiment", "analysis_display", "analysis_repair"} \
                    or owner == "methods.validation":
                target_kinds.add("experiment")
            elif kind == "interpretation_expansion" or owner == "strategy.interpretation":
                target_kinds.add("interpretation")
            elif kind == "manuscript_revision" or owner == "editorial.composer":
                target_kinds.add("paper")
        targets = set(target_ids)
        targets.update(
            stage_id for stage_id, stage in by_id.items()
            if stage["kind"] in target_kinds and stage_id not in targets
        )
        if not targets:
            return set()
        # Rerun every downstream consumer because its bound packet may have
        # changed.  The closure is deterministic and keeps unrelated branches
        # intact.
        changed = True
        while changed:
            changed = False
            for stage_id, stage in by_id.items():
                if stage_id in targets:
                    continue
                if set(stage["depends_on"]) & targets:
                    targets.add(stage_id)
                    changed = True
        return targets

    def _record_continuation(self, requests, reopened_stage_ids, *,
                             budget_override=False, budget_override_kind=None):
        """Persist one continuation decision and route its work orders."""
        cycle = self.continuation_cycles
        owners = {item.get("owner") for item in requests}
        if len(owners) == 1 and next(iter(owners)):
            recipient = self._address_for_role(next(iter(owners)))
        else:
            recipient = COMMAND_ADDRESSES["arbiter"]
        feedback = {
            "event_id": f"composer-continuation-{cycle}-{uuid.uuid4().hex}",
            "stage_id": "workflow",
            "role": "executive-command",
            "from": COMMAND_ADDRESSES["progress"],
            "to": recipient,
            "status": "continuing",
            "action": "continue_research",
            "cycle": cycle,
            "max_cycles": self._continuation_policy()["max_cycles"],
            "budget_baseline": self._continuation_budget_baseline,
            "budget_used": self._continuation_budget_used(),
            "cycle_budget_override": (
                budget_override_kind or "autonomous_experiment_repair"
                if budget_override else None
            ),
            "research_requests": deepcopy(requests),
            "reopened_stage_ids": sorted(reopened_stage_ids),
            "next_condition": "complete each scoped work order, rerun downstream interpretation and review, and re-evaluate the release gate",
            "message_id": f"composer-continuation-{cycle}-{uuid.uuid4().hex}",
            "message_disposition": "scheduled",
        }
        self.feedback.append(feedback)
        note = self._publish(
            f"command/composer/continuation/{cycle}", "decision_note", feedback, "command.composer")
        self._route_feedback(feedback, note)

    def _continuation_budget_used(self):
        """Return continuation cycles consumed by the current process lease."""
        return max(0, int(self.continuation_cycles or 0)
                   - int(self._continuation_budget_baseline or 0))

    def _begin_continuation(self, completed, by_id):
        """Reopen the affected closure after a research or review request."""
        # A continuation is new scientific work.  Check the immutable mission
        # wall before publishing its decision or activating any work order.
        self._remaining()
        previous_cycle = self.continuation_cycles
        requests = self._continuation_requests()
        if not any(self._is_topic_pivot_request(item) for item in requests):
            def scope(item):
                return (item.get("source_stage_id"),
                        item.get("target_stage_id") or self._request_target_kind(item))

            revised_scopes = {scope(item) for item in requests}
            request_ids = {item.get("id") for item in requests}
            for item in self._scope_active_research_requests(self.active_research_requests):
                if item.get("id") in request_ids or scope(item) in revised_scopes:
                    continue
                signature = self._research_request_signature(item)
                if not self._research_request_was_admitted(item):
                    continue
                targets = [stage_id for stage_id, stage in by_id.items()
                           if (item.get("target_stage_id") == stage_id
                               if isinstance(item.get("target_stage_id"), str)
                               else self._request_target_kind(item) == stage.get("kind"))]
                fulfilled = (
                    signature in self._attempted_request_signatures
                    and bool(targets)
                    and all(
                        self._survey_acquisition_frontier_for_topic(
                            stage_id, item.get("topic_id"), item.get("topic_cycle"), item) is not None
                        if item.get("kind") == "literature_expansion" else
                        self.stage_records.get(stage_id, {}).get("status") in {"completed", "accepted"}
                        and not self.context.get(stage_id, {}).get("preserve_work_orders")
                        for stage_id in targets)
                )
                if not fulfilled:
                    requests.append(deepcopy(item))
                    request_ids.add(item.get("id"))
        experiment_repair_override = (
            self._forward_first()
            and any(self._is_experiment_repair_request(item) for item in requests)
        )
        same_topic_budget_override = any(
            isinstance(item, dict)
            and item.get("recovery_mode") == "continue_same_topic_after_local_budget"
            for item in requests
        )
        topic_pivot_override = (
            self._forward_first()
            and any(self._is_topic_pivot_request(item) for item in requests)
        )
        evidence_refinement_override = any(
            isinstance(item, dict)
            and item.get("recovery_mode") == "refine_topic_to_available_evidence"
            for item in requests
        )
        format_recovery_stage_ids = {
            item.get("target_stage_id") for item in requests
            if isinstance(item, dict)
            and item.get("kind") == "recovery"
            and item.get("recovery_mode") == "format_repair_then_rerun"
            and isinstance(item.get("target_stage_id"), str)
        }
        format_recovery_override = any(
            isinstance(self.context.get(stage_id), dict)
            and self.context[stage_id].get("format_recovery") is True
            and self.context[stage_id].get("format_recovery_dispatched") is not True
            for stage_id in format_recovery_stage_ids
        )
        continuation_budget_override = (
            experiment_repair_override or topic_pivot_override
            or same_topic_budget_override or format_recovery_override
            or evidence_refinement_override
        )
        policy = self._continuation_policy()
        if (policy.get("mode", "bounded") == "bounded"
                and self._continuation_budget_used() >= policy["max_cycles"]
                and not continuation_budget_override):
            return False
        targets = self._continuation_targets(requests, by_id)
        if not requests or not targets:
            return False
        topic_stage_ids = {
            stage_id for stage_id in targets
            if by_id.get(stage_id, {}).get("kind") == "topic_discovery"
        }
        if topic_stage_ids and any(
                self._is_topic_pivot_request(item)
                for item in requests):
            self._retire_superseded_topic_contexts(
                targets, topic_stage_ids, by_id,
                pivot_cycle=self.continuation_cycles + 1,
            )
        retired_work_orders = self.departments.retire_superseded_work_orders(
            {item.get("id") for item in requests if isinstance(item, dict)},
            reason="superseded by the current scoped continuation",
        )
        self.continuation_cycles += 1
        self.active_research_requests = requests
        for stage_id in format_recovery_stage_ids & targets:
            context = self.context.get(stage_id)
            if isinstance(context, dict) and context.get("format_recovery") is True:
                context["format_recovery_dispatched"] = True
                signature = context.get("format_recovery_signature")
                entry = self.format_recovery_ledger.get(signature)
                if isinstance(entry, dict) and entry.get("status") == "pending":
                    entry.update({
                        "status": "dispatched",
                        "dispatched_cycle": self.continuation_cycles,
                        "request_ids": [item.get("id") for item in requests
                                        if item.get("target_stage_id") == stage_id],
                    })
        self.reopened_stage_ids = set(targets)
        self.continuation_pending_stage_ids = set(targets)
        # A continuation is a new dispatch boundary.  A prior child may have
        # been interrupted after its last stage checkpoint, leaving the old
        # aggregate record marked ``running`` even though no provider call is
        # alive.  Clear that live projection before the new agenda is
        # published; the next actual admission installs a fresh assignment.
        for target_id in targets:
            record = self.stage_records.get(target_id)
            if not isinstance(record, dict):
                continue
            was_running = record.get("status") == "running"
            record["status"] = "retrying"
            if was_running:
                active_attempt_id = record.get("attempt_id")
                if isinstance(active_attempt_id, str):
                    self._archive_stage_attempt(
                        record, cycle=previous_cycle,
                        error=("A continuation superseded an incomplete stage attempt; "
                               "its final stage result was not observed."),
                    )
                    record["last_attempt_id"] = record.pop("attempt_id")
                if record.get("task_id"):
                    record["last_task_id"] = record.pop("task_id")
            retired = self._retire_stage_assignment(record)
            record.update(retired)
            self.stage_records[target_id] = record
        completed.difference_update(targets)
        retired_stage_tasks = self._retire_superseded_stage_tasks(
            targets,
            reason="superseded by a newly admitted continuation",
        )
        self._record_continuation(
            requests, targets, budget_override=continuation_budget_override,
            budget_override_kind=(
                "autonomous_experiment_repair" if experiment_repair_override
                else "same_topic_local_budget_recovery" if same_topic_budget_override
                else "adaptive_topic_pivot" if topic_pivot_override
                else "bounded_model_contract_recovery" if format_recovery_override
                else None
            ))
        if experiment_repair_override:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "extend_experiment_repair_lease",
                "reason": "a generated capability has not produced an observation; continue only within mission and stage fences",
                "work_order_ids": [item.get("id") for item in requests
                                   if self._is_experiment_repair_request(item)],
                "continuation_policy": deepcopy(policy),
            })
        if topic_pivot_override:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "extend_topic_pivot_lease",
                "reason": "a new research direction changes the frontier; keep searching within mission and stage fences",
                "work_order_ids": [item.get("id") for item in requests
                                   if self._is_topic_pivot_request(item)],
                "continuation_policy": deepcopy(policy),
            })
        if same_topic_budget_override:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "continue_same_topic_after_local_budget",
                "reason": "local topic capacity reset; resume the current evidence lineage without inferring scientific failure",
                "work_order_ids": [item.get("id") for item in requests
                                   if isinstance(item, dict)
                                   and item.get("recovery_mode") == "continue_same_topic_after_local_budget"],
                "continuation_policy": deepcopy(policy),
            })
        if format_recovery_override:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "admit_bounded_model_contract_recovery",
                "reason": "one pending same-stage format repair may reopen its owning stage after the research-cycle budget",
                "stage_ids": sorted(format_recovery_stage_ids),
                "continuation_policy": deepcopy(policy),
            })
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "activate_work_orders",
            "work_orders": self.departments.activate_work_orders(requests),
        })
        if retired_work_orders:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "retire_superseded_work_orders",
                "work_orders": retired_work_orders,
            })
        if retired_stage_tasks:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "retire_superseded_stage_tasks",
                "stage_tasks": retired_stage_tasks,
            })
        self._checkpoint(f"continuation:{self.continuation_cycles}:admitted", force=True)
        return True

    def _retire_superseded_topic_contexts(self, targets, topic_stage_ids, by_id, *, pivot_cycle):
        """Fence downstream projections when a new topic lineage is admitted.

        Old attempt directories and immutable artifacts remain available for
        audit.  The live checkpoint keeps only a transition reference so a
        later stage cannot accidentally treat another topic's result or
        deferred work order as current evidence.
        """
        topic_identity = self._current_topic_identity() or {}
        previous_topic_id = topic_identity.get("topic_id")
        checkpoint = self.store.head("command/composer/run")
        checkpoint_ref = checkpoint.get("artifact_ref") if isinstance(checkpoint, dict) else None
        retired = []
        for stage_id in sorted(targets):
            stage = by_id.get(stage_id)
            if not isinstance(stage, dict) or stage.get("kind") == "topic_discovery":
                continue
            context = self.context.get(stage_id)
            record = self.stage_records.get(stage_id)
            if not isinstance(context, dict):
                context = {}
            if not isinstance(record, dict):
                record = {}
            context_digest = hashlib.sha256(canonical_bytes(context)).hexdigest()
            prior_attempts = record.get("attempts", [])
            if not isinstance(prior_attempts, list):
                prior_attempts = []
            artifact_refs = []
            stack = [context]
            while stack and len(artifact_refs) < 48:
                value = stack.pop()
                if isinstance(value, dict):
                    for key, item in value.items():
                        if (isinstance(key, str) and key.endswith("_ref")
                                and isinstance(item, str) and item.startswith("artifact:")):
                            artifact_refs.append(item)
                        elif isinstance(item, (dict, list)):
                            stack.append(item)
                elif isinstance(value, list):
                    stack.extend(value)
            transition = {
                "schema_version": "composer-lineage-transition-1",
                "stage_id": stage_id,
                "stage_kind": stage.get("kind"),
                "pivot_cycle": pivot_cycle,
                "previous_topic_id": previous_topic_id,
                "next_topic_stage_ids": sorted(topic_stage_ids),
                "prior_context_sha256": context_digest,
                "prior_stage_status": record.get("status"),
                "prior_attempt_count": record.get("attempt_count", len(prior_attempts)),
                "prior_attempts": [{key: attempt.get(key) for key in (
                    "attempt_number", "attempt_id", "state", "project_dir",
                    "failure_class", "failure_dossier_ref") if key in attempt}
                    for attempt in prior_attempts[-12:] if isinstance(attempt, dict)],
                "prior_artifact_refs": list(dict.fromkeys(artifact_refs)),
                "source_checkpoint_ref": checkpoint_ref,
            }
            subjects = [checkpoint_ref] if isinstance(checkpoint_ref, str) else []
            transition_record = self._publish(
                f"command/composer/topic-lineages/cycle-{pivot_cycle}/retired/{stage_id}",
                "note", transition, "command.composer", subjects=subjects,
            )
            next_context = {
                "kind": stage.get("kind"),
                "status": "topic_pivot_pending",
                "superseded_topic_id": previous_topic_id,
                "topic_pivot_cycle": pivot_cycle,
                "lineage_transition_ref": transition_record["artifact_ref"],
                "research_requests": [],
                "research_expansion_requests": [],
                **({"pivoted_to_topic": next(iter(sorted(topic_stage_ids)))}
                   if stage.get("kind") == "experiment" else {}),
            }
            for key in ("quota_recovery", "superseded_scope_failure"):
                if isinstance(context.get(key), dict):
                    next_context[key] = deepcopy(context[key])
            self.context[stage_id] = next_context
            self.stage_records[stage_id] = {
                "kind": stage.get("kind"),
                "status": "retrying",
                "attempt_count": record.get("attempt_count", len(prior_attempts)),
                "attempts": deepcopy(prior_attempts),
                "superseded_topic_id": previous_topic_id,
                "lineage_state": "awaiting_topic_admission",
                "lineage_transition_ref": transition_record["artifact_ref"],
                "active_agents": [],
            }
            retired.append({
                "stage_id": stage_id,
                "previous_topic_id": previous_topic_id,
                "transition_ref": transition_record["artifact_ref"],
                "prior_context_sha256": context_digest,
            })
        if retired:
            self.department_activity.append({
                "cycle": pivot_cycle,
                "action": "retire_superseded_topic_contexts",
                "previous_topic_id": previous_topic_id,
                "stages": retired,
                "next_action": "rebuild every downstream input from the newly admitted topic",
            })

    @staticmethod
    def _survey_checkpoint(project_dir):
        """Return the durable survey milestone recorded in one workspace."""
        if not isinstance(project_dir, (str, Path)):
            return None
        root = Path(project_dir).resolve()
        if not (root / "state" / "control.sqlite").is_file():
            return None
        output = root / "output" / "run.json"
        if not output.is_file():
            return None
        try:
            payload = json.loads(output.read_text())
        except (OSError, TypeError, ValueError):
            return None
        if not isinstance(payload, dict):
            return None
        if payload.get("survey_current") is not True or not payload.get("survey_ref"):
            return None
        # A current survey without a current assessment is an honest
        # resumable frontier.  A fully assessed survey is a released upstream
        # dependency and should be left alone when another continuation is
        # admitted for a downstream scope.
        if payload.get("assessment_current") is True and payload.get("assessment_ref"):
            if not (payload.get("status") in {"blocked", "paused"}
                    and payload.get("work_orders") and not payload.get("follow_up_result")):
                return None
        return payload

    @staticmethod
    def _is_survey_aggregate_review_failure(value):
        message = str(value or "").casefold()
        return any(marker in message for marker in (
            "survey review did not pass every required check",
            "deterministic aggregate survey review failed",
        ))

    @staticmethod
    def _survey_review_repair_checkpoint(project_dir):
        """Return a failed aggregate-review workspace that can be resumed in place."""
        if not isinstance(project_dir, (str, Path)):
            return None
        root = Path(project_dir).resolve()
        if not (root / "state" / "control.sqlite").is_file():
            return None
        output = root / "output" / "run.json"
        if not output.is_file():
            return None
        try:
            payload = json.loads(output.read_text())
        except (OSError, TypeError, ValueError):
            return None
        if (not isinstance(payload, dict)
                or payload.get("status") not in {"blocked", "paused"}
                or not isinstance(payload.get("survey_ref"), str)
                or payload.get("assessment_current") is True
                or not ComposerRunner._is_survey_aggregate_review_failure(payload.get("error"))):
            return None
        return payload

    def _latest_resumable_survey_project(self, stage):
        """Find the newest accepted survey checkpoint before making a cycle.

        Reopened survey stages are not ordinary stateless workers.  The
        survey runner owns a source catalogue, identity ledger, and accepted
        map; creating a fresh cycle directory after a gap-assessment failure
        discards all of that work and silently turns a scoped repair into a
        full literature restart.  Prefer the checkpoint named by the live
        context, then walk the immutable Composer attempt ledger newest-first.
        """
        if not isinstance(stage, dict) or stage.get("kind") != "survey":
            return None
        topic_identity = self._current_topic_identity()
        candidates = []
        context = self.context.get(stage.get("id"), {})
        revalidation = bool(self._survey_revalidation_scopes(stage))
        aggregate_review_repair = (
            isinstance(context, dict)
            and context.get("review_status") == "survey_integrity_repair"
            and context.get("resume_scope") == "integrated_review"
        )
        if isinstance(context, dict):
            lineage = context.get("topic_lineage")
            lineage = lineage if isinstance(lineage, dict) else {}
            candidates.append((
                context.get("project_dir"),
                context.get("topic_id") or lineage.get("topic_id"),
                context.get("topic_cycle") or lineage.get("topic_cycle"),
                None,
            ))
        record = self.stage_records.get(stage.get("id"), {})
        attempts = record.get("attempts", []) if isinstance(record, dict) else []
        if isinstance(attempts, list):
            candidates.extend(
                (attempt.get("project_dir"), attempt.get("topic_id"),
                 attempt.get("topic_cycle"), attempt)
                for attempt in reversed(attempts)
                if isinstance(attempt, dict)
            )
        candidates.append((stage.get("project_dir"), None, None, None))
        seen = set()
        partials = []
        for candidate, candidate_topic_id, candidate_topic_cycle, owned_attempt in candidates:
            if not isinstance(candidate, str):
                continue
            resolved = str(Path(candidate).resolve())
            if resolved in seen:
                continue
            seen.add(resolved)
            if owned_attempt is None and isinstance(attempts, list):
                owned_attempt = next((item for item in reversed(attempts)
                    if isinstance(item, dict) and item.get("project_dir") == resolved
                    and isinstance(item.get("attempt_id"), str)), None)
                if owned_attempt is not None:
                    candidate_topic_id = owned_attempt.get("topic_id")
                    candidate_topic_cycle = owned_attempt.get("topic_cycle")
            if isinstance(topic_identity, dict):
                if (isinstance(candidate_topic_id, str)
                        and candidate_topic_id != topic_identity["topic_id"]):
                    continue
                if (type(candidate_topic_cycle) is int
                        and candidate_topic_cycle != topic_identity["topic_cycle"]):
                    continue
            checkpoint = self._survey_checkpoint(resolved)
            if checkpoint is None and revalidation:
                output = Path(resolved) / "output/run.json"
                durable = self._durable_stage_config(resolved)
                try:
                    retained = json.loads(output.read_text())
                except (OSError, TypeError, ValueError):
                    retained = None
                if isinstance(retained, dict) and isinstance(durable, dict):
                    checkpoint = {**retained, "nomination": durable.get("survey", {}).get("proposed_gap")}
            if checkpoint is None and aggregate_review_repair:
                checkpoint = self._survey_review_repair_checkpoint(resolved)
            partial = checkpoint is None
            if partial:
                checkpoint = self._survey_partial_checkpoint(resolved)
            if checkpoint is None:
                continue
            if (isinstance(topic_identity, dict)
                    and not self._survey_checkpoint_matches_topic(checkpoint, topic_identity)):
                bound_partial = False
                if (partial and self._survey_checkpoint_topic_id(checkpoint) is None
                        and isinstance(owned_attempt, dict) and isinstance(owned_attempt.get("attempt_id"), str)
                        and candidate_topic_id == topic_identity["topic_id"]
                        and type(candidate_topic_cycle) is int and candidate_topic_cycle == topic_identity["topic_cycle"]):
                    attempt = self.tasks.get_attempt(owned_attempt["attempt_id"])
                    payload = attempt.get("payload") or {}
                    topic = next((self.context.get(item["id"], {}).get("topic", {})
                                  for item in self.workflow["stages"] if item.get("kind") == "topic_discovery"), {})
                    bound_partial = (payload.get("stage_id") == stage["id"]
                        and payload.get("project_dir") == resolved
                        and isinstance(checkpoint.get("question"), str)
                        and checkpoint["question"] == topic.get("research_question"))
                if bound_partial:
                    coverage = checkpoint.get("coverage", {})
                    partials.append(((coverage.get("map_entry_count", 0), coverage.get("verified_full_texts", 0),
                                      coverage.get("unique_works", 0)), Path(resolved)))
                    continue
                already_recorded = any(
                    isinstance(item, dict)
                    and item.get("action") == "skip_survey_checkpoint_other_topic"
                    and item.get("stage_id") == stage.get("id")
                    and item.get("project_dir") == resolved
                    and item.get("current_topic_id") == topic_identity["topic_id"]
                    for item in self.department_activity
                )
                if not already_recorded:
                    nomination = checkpoint.get("nomination")
                    self.department_activity.append({
                        "cycle": self.continuation_cycles,
                        "action": "skip_survey_checkpoint_other_topic",
                        "stage_id": stage.get("id"),
                        "project_dir": resolved,
                        "checkpoint_topic_id": self._survey_checkpoint_topic_id(checkpoint),
                        "current_topic_id": topic_identity["topic_id"],
                        "nomination_id": nomination.get("id")
                        if isinstance(nomination, dict) else None,
                        "reason": "a resumable literature map is reusable only for the exact admitted topic lineage",
                    })
                continue
            if not partial:
                return Path(resolved)
            coverage = checkpoint.get("coverage", {})
            partials.append(((coverage.get("map_entry_count", 0),
                              coverage.get("verified_full_texts", 0),
                              coverage.get("unique_works", 0)), Path(resolved)))
        return max(partials, key=lambda item: item[0])[1] if partials else None

    @classmethod
    def _survey_partial_checkpoint(cls, project_dir):
        """Retain captured sources and checked work before aggregate acceptance."""
        root = Path(project_dir)
        output = root / "output" / "run.json"
        if not output.is_file():
            return None
        try:
            payload = json.loads(output.read_text())
        except (OSError, ValueError):
            return None
        if (not isinstance(payload, dict)
                or payload.get("status") not in {"blocked", "paused", "running"}
                or payload.get("survey_ref")):
            return None
        config = cls._durable_stage_config(root)
        if not isinstance(config, dict):
            return None
        return {**payload, "nomination": config.get("survey", {}).get("proposed_gap"),
                "question": config.get("survey", {}).get("question")}

    @staticmethod
    def _survey_checkpoint_topic_id(checkpoint):
        if not isinstance(checkpoint, dict):
            return None
        for key in ("topic_id", "selected_topic_id"):
            value = checkpoint.get(key)
            if isinstance(value, str) and value:
                return value
        for key in ("topic_lineage", "topic_admission"):
            lineage = checkpoint.get(key)
            if isinstance(lineage, dict):
                value = lineage.get("topic_id") or lineage.get("id")
                if isinstance(value, str) and value:
                    return value
        nomination = checkpoint.get("nomination")
        nomination_id = nomination.get("id") if isinstance(nomination, dict) else None
        if isinstance(nomination_id, str) and nomination_id.startswith("topic-"):
            return nomination_id[len("topic-"):]
        return None

    @classmethod
    def _survey_checkpoint_matches_topic(cls, checkpoint, topic_identity):
        """Require positive topic identity evidence before resuming a survey."""
        topic_id = cls._survey_checkpoint_topic_id(checkpoint)
        if not isinstance(topic_id, str) or topic_id != topic_identity.get("topic_id"):
            return False
        checkpoint_cycle = checkpoint.get("topic_cycle")
        return (type(checkpoint_cycle) is not int
                or checkpoint_cycle == topic_identity.get("topic_cycle"))

    def _stage_for_cycle(self, stage):
        """Route reopened work without discarding a resumable survey ledger."""
        if stage["id"] not in self.reopened_stage_ids:
            return stage
        candidate = deepcopy(stage)
        if stage.get("kind") == "survey":
            record = self.stage_records.get(stage.get("id"), {})
            topic_identity = self._current_topic_identity()
            superseded = (
                isinstance(record, dict)
                and (record.get("lineage_state") == "awaiting_topic_admission"
                     or isinstance(record.get("superseded_topic_id"), str)
                     or (isinstance(record.get("topic_id"), str)
                         and isinstance(topic_identity, dict)
                         and record["topic_id"] != topic_identity["topic_id"]))
            )
            resumable = (None if superseded
                         else self._latest_resumable_survey_project(stage))
            if resumable is not None:
                candidate["project_dir"] = str(resumable)
                candidate["reuse_completed"] = False
                candidate["reuse_output_path"] = None
                return candidate
        base = Path(stage["project_dir"]).resolve()
        candidate["project_dir"] = str(
            base / "continuations" / f"cycle-{self.continuation_cycles}")
        candidate["reuse_completed"] = False
        candidate["reuse_output_path"] = None
        return candidate

    @staticmethod
    def _recover_interrupted_topic_result(stage, record):
        """Reuse a completed topic producer artifact when only outer review was interrupted."""
        if (not isinstance(stage, dict) or stage.get("kind") != "topic_discovery"
                or not isinstance(record, dict)
                or record.get("status") not in {"running", "retrying"}
                or not isinstance(record.get("project_dir"), str)):
            return None
        root = Path(record["project_dir"]).resolve()
        candidates = (root / "topic-discovery.json",
                      root / "output" / "topic-discovery.json")
        for path in candidates:
            if not path.is_file():
                continue
            try:
                payload = json.loads(path.read_text())
                topic = payload.get("topic") if isinstance(payload, dict) else None
                evolution = payload.get("topic_evolution") if isinstance(payload, dict) else None
                if (not isinstance(payload, dict)
                        or payload.get("schema_version") != "topic-discovery-1"
                        or payload.get("status") != "completed"
                        or payload.get("admission_state") not in {
                            "admitted", "provisional_for_survey"}
                        or not isinstance(topic, dict)
                        or not isinstance(topic.get("id"), str)
                        or payload.get("selected_id") != topic.get("id")
                        or not isinstance(evolution, dict)
                        or type(evolution.get("cycle")) is not int
                        or not isinstance(payload.get("candidates"), list)
                        or not any(isinstance(item, dict)
                                   and item.get("id") == topic["id"]
                                   for item in payload["candidates"])):
                    continue
                from scisaurus.runtime.research_program import build_research_program
                rebuilt = build_research_program(payload)
                if payload.get("research_program") != rebuilt:
                    continue
                body = path.read_bytes()
            except (OSError, TypeError, ValueError, ValidationError):
                continue
            program_path = path.parent / "research-program.json"
            result = deepcopy(payload)
            if program_path.is_file():
                try:
                    if json.loads(program_path.read_text()) == rebuilt:
                        result["research_program_path"] = str(program_path.resolve())
                except (OSError, TypeError, ValueError):
                    pass
            return {
                "result": result,
                "output_path": str(path.resolve()),
                "output_sha256": hashlib.sha256(body).hexdigest(),
                "source_attempt_number": record.get("attempt_number"),
                "source_project_dir": str(root),
            }
        return None

    def _runtime_context(self, model):
        """Expose safe, actionable execution capabilities to topic selection.

        This is intentionally a capability inventory rather than a dump of the
        process environment: credentials, tokens, and unrelated host variables
        never enter a model prompt.  The selected topic is therefore judged
        against the tools that the actual Composer can call.
        """
        executable_names = ("python3", "git", "tectonic", "pdflatex", "latexmk",
                            "node", "npm", "Rscript", "julia")
        package_names = ("numpy", "scipy", "pandas", "sklearn", "matplotlib",
                         "statsmodels", "sympy", "torch", "tensorflow")
        try:
            from importlib.util import find_spec
            packages = {name: find_spec(name) is not None for name in package_names}
        except (ImportError, ModuleNotFoundError, ValueError):
            packages = {name: False for name in package_names}
        project_files = []
        ignored_roots = {".git", ".venv", "__pycache__", ".mypy_cache", ".pytest_cache", "node_modules"}
        inventory_roots = [(self.root, "composer")]
        for stage in self.workflow["stages"]:
            inventory_roots.append((Path(stage["project_dir"]).resolve(), f"stage:{stage['id']}"))
        seen_files = set()
        for stage in self.workflow["stages"]:
            descriptor = Path(stage["config_path"]).resolve()
            if descriptor.is_file() and str(descriptor) not in seen_files:
                seen_files.add(str(descriptor))
                project_files.append(f"config:{stage['id']}/{descriptor.name}")
                if len(project_files) >= 100:
                    break
        try:
            for base, label in inventory_roots:
                if not base.exists():
                    continue
                for path in sorted(base.rglob("*")):
                    if not path.is_file():
                        continue
                    relative = path.relative_to(base)
                    if relative.parts and (relative.parts[0] in {"state", "objects"}
                                           or relative.parts[0] in ignored_roots
                                           or any(part in ignored_roots for part in relative.parts)):
                        continue
                    identity = str(path.resolve())
                    if identity in seen_files:
                        continue
                    seen_files.add(identity)
                    project_files.append(f"{label}/{relative}")
                    if len(project_files) >= 100:
                        break
                if len(project_files) >= 100:
                    break
        except OSError:
            project_files = []
        experiment_contract = None
        experiment_catalog = []
        catalog = self.workflow.get("experiment_catalog") or []
        for entry in catalog:
            try:
                configured = json.loads(Path(entry["config_path"]).read_text())
            except (OSError, ValueError) as exc:
                raise ValidationError(
                    f"experiment capability template is unreadable: {entry['config_path']}") from exc
            experiment = configured.get("experiment") if isinstance(configured, dict) else None
            if not isinstance(experiment, dict):
                raise ValidationError("experiment capability template must contain an experiment object")
            experiment_catalog.append({
                "id": entry["id"],
                "study_type": experiment.get("study_type"),
                "domain": experiment.get("domain"),
                "research_question": experiment.get("research_question"),
                "method": experiment.get("method"),
                "stopping_rule": experiment.get("stopping_rule"),
                "primary_outcomes": [
                    {key: outcome.get(key) for key in ("id", "definition", "unit")}
                    for outcome in experiment.get("primary_outcomes", [])
                    if isinstance(outcome, dict)
                ],
                "required_asset_roles": [
                    {key: asset.get(key) for key in ("role", "media_types", "min_count")}
                    for asset in experiment.get("required_assets", [])
                    if isinstance(asset, dict)
                ],
                "execution_adapter": (experiment.get("execution") or {}).get("adapter"),
                "design_driven": bool((experiment.get("parameters") or {}).get("design_driven")),
                "design_template": (
                    (experiment.get("execution") or {}).get("input") or {}).get("design"),
            })
        experiment_stages = [stage for stage in self.workflow["stages"] if stage["kind"] == "experiment"]
        if experiment_stages and not catalog:
            try:
                configured = json.loads(Path(experiment_stages[0]["config_path"]).read_text())
                experiment = configured.get("experiment") if isinstance(configured, dict) else None
                if isinstance(experiment, dict):
                    experiment_contract = {
                        "study_type": experiment.get("study_type"),
                        "research_question": experiment.get("research_question"),
                        "method": experiment.get("method"),
                        "stopping_rule": experiment.get("stopping_rule"),
                        "primary_outcomes": [
                            {key: outcome.get(key) for key in ("id", "definition", "unit")}
                            for outcome in experiment.get("primary_outcomes", [])
                            if isinstance(outcome, dict)
                        ],
                        "required_asset_roles": [
                            {key: asset.get(key) for key in ("role", "media_types", "min_count")}
                            for asset in experiment.get("required_assets", [])
                            if isinstance(asset, dict)
                        ],
                        "execution_adapter": (experiment.get("execution") or {}).get("adapter"),
                    }
            except (OSError, ValueError, TypeError):
                experiment_contract = None
        foundry_enabled = bool(self.workflow.get("capability_foundry_config_path"))
        foundry_runtime_packages = []
        foundry_max_attempts = None
        foundry_timeout_seconds = None
        if foundry_enabled:
            try:
                foundry_config = json.loads(
                    Path(self.workflow["capability_foundry_config_path"]).read_text())
                foundry_max_attempts = foundry_config.get("max_attempts")
                foundry_timeout_seconds = foundry_config.get("timeout_seconds")
                foundry_runtime_packages = [
                    {"name": item["name"], "version": item["version"]}
                    for item in foundry_config.get("runtime_packages", [])
                    if isinstance(item, dict)
                    and isinstance(item.get("name"), str)
                    and isinstance(item.get("version"), str)
                ]
            except (OSError, ValueError, TypeError, KeyError) as exc:
                raise ValidationError(
                    "capability foundry runtime package inventory is unreadable") from exc
            # These packages are installed in the isolated foundry runtime,
            # which is the execution boundary for the generated program. The
            # host interpreter may intentionally not have the same packages.
            for item in foundry_runtime_packages:
                packages[item["name"]] = True
        stage_deadlines_seconds = {
            stage["id"]: float(stage["deadline_seconds"])
            for stage in self.workflow["stages"]
        }
        experiment_deadlines = [
            stage["deadline_seconds"] for stage in self.workflow["stages"]
            if stage["kind"] == "experiment"
        ]
        survey_sources = {
            "metadata": False, "full_text": False, "max_api_requests": None,
        }
        for stage in self.workflow["stages"]:
            if stage["kind"] != "survey":
                continue
            try:
                descriptor = json.loads(Path(stage["config_path"]).read_text())
                survey = descriptor.get("survey", {}) if isinstance(descriptor, dict) else {}
                if not isinstance(survey, dict):
                    survey = {}
                search = survey.get("search", {}) if isinstance(survey, dict) else {}
                survey_sources.update({
                    "metadata": isinstance(survey.get("bibliography"), dict),
                    "full_text": isinstance(survey.get("full_text"), dict),
                    "max_api_requests": search.get("max_api_calls")
                    if type(search.get("max_api_calls")) is int else None,
                })
            except (OSError, ValueError, TypeError):
                # The stage validator remains authoritative for unreadable
                # descriptors; topic context should not expose a partial path
                # dump or turn an inventory failure into a scientific claim.
                pass
            break
        if foundry_enabled:
            feasibility_boundary = {
                "execution_modes": ["foundry"],
                "allowed_input_kinds": ["analytical_parameters", "synthetic"],
                "allowed_data_access": ["closed_world"],
                "network_access": False,
                "undeclared_data": False,
                "max_external_requests": 0,
                "max_model_calls": 0,
            }
        else:
            feasibility_boundary = {
                "execution_modes": ["configured_program", "project_runner"],
                "allowed_input_kinds": ["project_artifact", "synthetic"],
                "allowed_data_access": ["closed_world", "project_local"],
                "network_access": False,
                "undeclared_data": False,
                # Literature-provider capacity is not experiment capacity. The
                # current project-runner boundary is closed-world and cannot
                # smuggle a network/API dependency through the topic plan.
                "max_external_requests": 0,
                "max_model_calls": 0,
            }
        feasibility_boundary.update({
            "schema_version": "research-feasibility-1",
            "allowed_evidence_modes": (
                ["analytical_derivation", "synthetic_simulation"]
                if foundry_enabled else list(EVIDENCE_MODE_VALUES)
            ),
            "available_executables": sorted(
                name for name in executable_names if shutil.which(name) is not None
            ),
            "available_packages": sorted(
                name for name, present in packages.items() if present
            ),
            "stage_deadlines_seconds": stage_deadlines_seconds,
            "max_experiment_seconds": min(
                [*experiment_deadlines, *([foundry_timeout_seconds]
                 if foundry_enabled and isinstance(foundry_timeout_seconds, (int, float))
                 else [])]
            ) if experiment_deadlines or foundry_timeout_seconds is not None else None,
            "survey_sources": survey_sources,
        })
        return {
            "operating_system": platform.system(),
            "platform": platform.machine(),
            "python_version": sys.version.split()[0],
            "current_date": time.strftime("%Y-%m-%d", time.gmtime()),
            "executables": {name: shutil.which(name) is not None for name in executable_names},
            "python_packages": packages,
            "model_protocol": model.get("protocol") if isinstance(model, dict) else None,
            "model_name": model.get("model") if isinstance(model, dict) else None,
            "configured_stage_kinds": [stage["kind"] for stage in self.workflow["stages"]],
            "experiment_contract": experiment_contract,
            # A foundry-backed mission defines the scientific question before
            # execution design. Frozen templates remain an auditable fallback
            # inventory but cannot seed or constrain topic generation.
            "experiment_catalog": [] if foundry_enabled else experiment_catalog,
            "fallback_experiment_catalog": experiment_catalog if foundry_enabled else [],
            "capability_foundry": ({
                "enabled": True,
                "execution_boundary": "deterministic seeded Python with no network or subprocess access",
                "runtime_packages": foundry_runtime_packages,
                "max_attempts": foundry_max_attempts,
                "timeout_seconds": foundry_timeout_seconds,
                "allowed_evidence_modes": ["analytical_derivation", "synthetic_simulation"],
                "admission_gates": [
                    "static scan", "sandbox execution", "deterministic replay",
                    "test-vector digest", "independent recalculation", "adversarial review",
                ],
            } if foundry_enabled else {"enabled": False}),
            "topic_exclusions": self._effective_topic_exclusions(),
            "topic_history": self._topic_history_context(),
            "topic_preferences": deepcopy(self.workflow.get("topic_preferences") or {}),
            "project_files": project_files,
            "project_scoped_execution": True,
            # A declared foundry remains the execution boundary when the
            # workflow stops at literature survey. Free-topic surveys without
            # an execution configuration retain the legacy topic contract.
            "research_feasibility": (
                feasibility_boundary if experiment_stages or foundry_enabled else None),
        }

    def _topic_sampling_seed(self, *, attempt_number=0):
        """Derive a stable but attempt-diverse topic sampling seed.

        Resume keeps the mission seed, while each isolated topic intake gets
        its own deterministic branch. Without the attempt component, a
        provider that honors the seed can replay the same rejected direction
        indefinitely even after the Composer has persisted its reason.
        """
        material = (
            f"{self.exploration_seed}:topic:{self.continuation_cycles}:"
            f"attempt:{attempt_number}"
        ).encode("utf-8")
        # The digest is intentionally wide for entropy, then reduced to the
        # signed-int64 range accepted by the configured model endpoint.
        from scisaurus.runtime.models import MAX_PROVIDER_SEED
        return int(hashlib.sha256(material).hexdigest()[:16], 16) % MAX_PROVIDER_SEED

    def _resolve_topic_history_path(self):
        """Resolve the durable history shared by a family of Composer runs.

        A Composer project is intentionally immutable and each fresh mission
        gets its own project directory.  Topic memory therefore lives beside
        that directory, rather than inside a mutable stage checkpoint.  A
        workflow may pin an explicit path; otherwise the parent of the run
        family receives a hidden, project-local history file.
        """
        configured = self.workflow.get("topic_history_path")
        if isinstance(configured, str) and configured.strip():
            return Path(configured).expanduser().resolve()
        family_root = self.root.parent.parent
        # Avoid turning a shallow project path such as ``/tmp/composer`` into
        # a write to the filesystem root.  Normal run families (for example
        # ``project/.runs/run/composer``) still share the stable ``.runs``
        # parent; a shallow project keeps history beside its composer root.
        if family_root == Path(self.root.anchor or "/"):
            family_root = self.root.parent
        if family_root == Path(self.root.anchor or "/"):
            family_root = Path.cwd()
        return (family_root / ".scisaurus-topic-history.json").resolve()

    def _topic_history_scope_key(self):
        """Keep topic memory stable across harmless objective/catalog edits."""
        material = {
            "workflow_id": self.workflow["id"],
            "stage_graph": [{"id": item["id"], "kind": item["kind"],
                             "depends_on": sorted(item.get("depends_on", []))}
                            for item in self.workflow["stages"]],
        }
        return hashlib.sha256(canonical_bytes(material)).hexdigest()

    @staticmethod
    def _validate_topic_history_document(document):
        """Validate the small append-only topic-history envelope."""
        if not isinstance(document, dict) or document.get("schema_version") != "topic-history-1":
            raise ValidationError("topic history has an unsupported schema")
        scopes = document.get("scopes")
        if not isinstance(scopes, dict):
            raise ValidationError("topic history scopes must be an object")
        for scope_key, scope in scopes.items():
            if not isinstance(scope_key, str) or not isinstance(scope, dict):
                raise ValidationError("topic history contains an invalid scope")
            entries = scope.get("entries", [])
            if not isinstance(entries, list):
                raise ValidationError("topic history entries must be a list")
            for entry in entries:
                if not isinstance(entry, dict):
                    raise ValidationError("topic history entry must be an object")
                if not isinstance(entry.get("topic_id"), str) or not entry["topic_id"].strip():
                    raise ValidationError("topic history entry requires topic_id")
                for key in ("title", "research_question", "domain"):
                    if key in entry and entry[key] is not None and not isinstance(entry[key], str):
                        raise ValidationError(f"topic history entry {key} must be a string")
        return document

    def _load_topic_history(self):
        """Load the current objective's topic memory, or an empty scope."""
        empty = {"schema_version": "topic-history-1", "scope_key": self.topic_history_scope,
                 "entries": [], "capability_counts": {}}
        path = self.topic_history_path
        if not path.is_file():
            return empty
        try:
            document = json.loads(path.read_text())
        except (OSError, ValueError) as exc:
            raise ValidationError(f"topic history is unreadable: {path}") from exc
        self._validate_topic_history_document(document)
        if self.workflow.get("topic_history_path"):
            # An explicit history path is itself the mission-family boundary.
            # Preserve prior directions across harmless objective wording or
            # capability-inventory revisions instead of silently reopening
            # already explored topics under a new hash scope.
            entries = [deepcopy(entry)
                       for scope in document["scopes"].values()
                       for entry in scope.get("entries", [])]
        else:
            scope = document["scopes"].get(self.topic_history_scope, {})
            if not isinstance(scope, dict):
                raise ValidationError("topic history scope is invalid")
            entries = deepcopy(scope.get("entries", []))
            if not isinstance(entries, list):
                raise ValidationError("topic history scope entries must be a list")
        # Keep the durable file complete.  Prompt projections are bounded in
        # `_topic_history_context`, but an old attempt remains available for
        # deterministic repeat checks and audit.
        counts = {}
        for entry in entries:
            capability = entry.get("experiment_capability_id")
            if isinstance(capability, str) and capability:
                counts[capability] = counts.get(capability, 0) + 1
        return {"schema_version": "topic-history-1", "scope_key": self.topic_history_scope,
                "entries": entries, "capability_counts": counts}

    def _load_runtime_environment(self):
        """Load the workflow's owner-local environment before any model call."""
        configured = list(self.workflow.get("runtime_env_files", []))
        repository = Path(__file__).resolve().parents[2]
        project_root = Path(self.workflow["project_id"]).resolve()
        local_private = repository / "local-private"
        owner_local_project = project_root == local_private or local_private in project_root.parents
        # ``runtime_env_files`` was added after several long-lived missions
        # had already been generated.  Load the repository-owned credentials
        # as a compatibility path so a resume cannot silently downgrade an
        # authenticated OpenAlex run to ``auth_required`` merely because its
        # descriptor is old.
        if owner_local_project:
            for path in default_runtime_environment_files(repository):
                if path not in configured:
                    configured.append(path)
        load_runtime_environment_files(configured)
        # Topic and survey descriptors intentionally retain their stable,
        # stage-local paths for auditability. The actual provider budget is
        # account-wide, so a Composer run also exposes one shared ledger and
        # one reusable topic cache to all of its child runners. Test and
        # projectless temporary workflows stay isolated unless they live under
        # this checkout's owner-local mission area.
        if owner_local_project:
            os.environ.setdefault(
                "SCISAURUS_OPENALEX_SHARED_RATE_STATE_PATH",
                str(default_openalex_shared_state_path(repository)),
            )
            os.environ.setdefault(
                "SCISAURUS_OPENALEX_SHARED_TOPIC_CACHE_PATH",
                str(default_openalex_shared_topic_cache_path(repository)),
            )

    def _migrate_legacy_topic_history(self):
        """Remove contract failures from the pre-typed rejection memory.

        Older Composer runs recorded every intake ``ValidationError`` as a
        rejection.  That mixed provider/contract failures with scientific
        novelty and maturity decisions, so a malformed response could become
        a durable exclusion and distort later topic selection.  Semantic
        entries are retained under their typed rejection kind; non-semantic
        legacy entries are removed because they are not evidence against a
        research direction.
        """
        path = self.topic_history_path
        if not path.is_file():
            return
        lock_path = Path(str(path) + ".lock")
        lock = lock_path.open("a+")
        flock = None
        temporary = None
        try:
            try:
                import fcntl
                flock = fcntl
                flock.flock(lock.fileno(), flock.LOCK_EX)
            except ImportError as exc:
                raise ValidationError(
                    "topic history requires an interprocess file lock") from exc
            try:
                document = json.loads(path.read_text())
            except (OSError, ValueError) as exc:
                raise ValidationError(f"topic history is unreadable: {path}") from exc
            self._validate_topic_history_document(document)
            from scisaurus.runtime.topic_discovery import (
                _TOPIC_SEMANTIC_REJECTION_TYPES,
                _topic_validation_rejection_type,
            )
            changed = False
            for scope in document["scopes"].values():
                migrated_entries = []
                for entry in scope.get("entries", []):
                    if entry.get("rejection_type") != "intake_validation":
                        migrated_entries.append(entry)
                        continue
                    rejection_type = _topic_validation_rejection_type(
                        entry.get("rejection_reason"))
                    if rejection_type not in _TOPIC_SEMANTIC_REJECTION_TYPES:
                        changed = True
                        continue
                    if rejection_type != entry.get("rejection_type"):
                        entry = deepcopy(entry)
                        entry["rejection_type"] = rejection_type
                        changed = True
                    migrated_entries.append(entry)
                scope["entries"] = migrated_entries
            if not changed:
                return
            temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
            temporary.write_bytes(canonical_bytes(document))
            os.replace(temporary, path)
            temporary = None
        finally:
            if temporary is not None:
                try:
                    temporary.unlink(missing_ok=True)
                except OSError:
                    pass
            if flock is not None:
                try:
                    flock.flock(lock.fileno(), flock.LOCK_UN)
                except OSError:
                    pass
            lock.close()

    def _effective_topic_exclusions(self):
        """Merge configured exclusions with automatic recent-direction memory."""
        configured = self.workflow.get("topic_exclusions") or {}
        capability_ids = list(configured.get("capability_ids", [])) if isinstance(configured, dict) else []
        topic_ids = list(configured.get("topic_ids", [])) if isinstance(configured, dict) else []
        entries = self.topic_history.get("entries", [])
        # A model-generated portfolio slot is not a durable scientific
        # identity.  Keep it in the bounded history projection for semantic
        # repeat checks, but do not turn its subject-shaped label into an
        # exact-match exclusion.  Explicit workflow exclusions remain exact.
        from scisaurus.runtime.topic_discovery import _is_generated_slot_topic_id
        for entry in entries:
            topic_id = entry.get("topic_id") if isinstance(entry, dict) else None
            if (isinstance(topic_id, str) and topic_id
                    and not _is_generated_slot_topic_id(topic_id)
                    and topic_id not in topic_ids):
                topic_ids.append(topic_id)
        catalog_ids = [
            item.get("id") for item in self.workflow.get("experiment_catalog", [])
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        ]
        # Rotate the most recently attempted capability while another
        # capability remains eligible.  Once the portfolio has been covered,
        # the next direction may return to the least-recent capability.
        if len(catalog_ids) > 1:
            explicit = set(capability_ids)
            available = [item for item in catalog_ids if item not in explicit]
            recent_capability = next(
                (entry.get("experiment_capability_id") for entry in reversed(entries)
                 if isinstance(entry, dict) and isinstance(entry.get("experiment_capability_id"), str)),
                None,
            )
            if (recent_capability in available
                    and any(item != recent_capability for item in available)
                    and recent_capability not in capability_ids):
                capability_ids.append(recent_capability)
        return {"capability_ids": list(dict.fromkeys(capability_ids)),
                "topic_ids": list(dict.fromkeys(topic_ids))}

    def _topic_history_context(self):
        """Return bounded history summaries suitable for the intake prompt."""
        all_entries = [entry for entry in self.topic_history.get("entries", [])
                       if isinstance(entry, dict)]
        entries = []
        for entry in all_entries[-24:]:
            if not isinstance(entry, dict):
                continue
            entries.append({key: entry.get(key) for key in (
                "topic_id", "title", "domain", "research_question", "experiment_capability_id",
                "research_form", "evidence_mode", "comparison_type",
                "parent_topic_id", "refinement_cycle", "changed_dimensions",
                "history_status", "rejection_type", "rejection_reason")})
        structure_fingerprints = set()
        from scisaurus.runtime.topic_discovery import topic_signature
        for entry in all_entries:
            signature = entry.get("signature")
            if not isinstance(signature, dict):
                signature = topic_signature(entry)
            fingerprint = signature.get("structure_fingerprint")
            if isinstance(fingerprint, str) and fingerprint:
                structure_fingerprints.add(fingerprint)
        return {
            "schema_version": "topic-history-1",
            "scope_key": self.topic_history_scope,
            "entries": entries,
            "history_summary": {
                "total_entries": len(all_entries),
                "distinct_structure_fingerprints": len(structure_fingerprints),
            },
            "capability_counts": deepcopy(self.topic_history.get("capability_counts", {})),
        }

    def _append_topic_history_entries(self, entries):
        """Append topic outcomes to the project-family memory atomically."""
        entries = [deepcopy(item) for item in (entries or [])
                   if isinstance(item, dict)
                   and isinstance(item.get("topic_id"), str)
                   and item["topic_id"].strip()]
        if not entries:
            return
        path = self.topic_history_path
        path.parent.mkdir(parents=True, exist_ok=True)
        lock_path = Path(str(path) + ".lock")
        lock = lock_path.open("a+")
        flock = None
        try:
            try:
                import fcntl
                flock = fcntl
                flock.flock(lock.fileno(), flock.LOCK_EX)
            except ImportError as exc:
                raise ValidationError(
                    "topic history requires an interprocess file lock") from exc
            if path.is_file():
                try:
                    document = json.loads(path.read_text())
                except (OSError, ValueError) as exc:
                    raise ValidationError(f"topic history is unreadable: {path}") from exc
                self._validate_topic_history_document(document)
            else:
                document = {"schema_version": "topic-history-1", "scopes": {}}
            scope = document["scopes"].setdefault(self.topic_history_scope, {"entries": []})
            stored_entries = scope.setdefault("entries", [])
            comparison_entries = (
                [item for stored_scope in document["scopes"].values()
                 for item in stored_scope.get("entries", [])]
                if self.workflow.get("topic_history_path") else list(stored_entries)
            )
            new_entries = []
            for entry in entries:
                fingerprint = ((entry.get("signature") or {}).get("fingerprint")
                               if isinstance(entry.get("signature"), dict) else None)
                duplicate = any(
                    isinstance(item, dict)
                    and (
                        fingerprint
                        and ((item.get("signature") or {}).get("fingerprint") == fingerprint)
                        or not fingerprint
                        and item.get("topic_id") == entry.get("topic_id")
                        and item.get("research_question") == entry.get("research_question")
                    )
                    for item in comparison_entries
                )
                if duplicate:
                    continue
                stored_entries.append(entry)
                comparison_entries.append(entry)
                new_entries.append(entry)
            scope["entries"] = stored_entries
            temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
            temporary.write_bytes(canonical_bytes(document))
            os.replace(temporary, path)
            self.topic_history = self._load_topic_history()
            if self.control is not None:
                for entry in new_entries:
                    self._publish(
                        f"command/composer/topic-history/{entry['topic_id']}",
                        "note",
                        {"schema_version": "topic-history-entry-1",
                         "scope_key": self.topic_history_scope, "entry": entry},
                        "command.composer",
                    )
        finally:
            if flock is not None:
                try:
                    flock.flock(lock.fileno(), flock.LOCK_UN)
                except OSError:
                    pass
            lock.close()

    def _record_topic_history(self, context):
        """Append an accepted topic selection to the project-family memory."""
        topic = context.get("topic") if isinstance(context, dict) else None
        if not isinstance(topic, dict) or not isinstance(topic.get("id"), str):
            return
        from scisaurus.runtime.topic_discovery import topic_signature
        signature = topic_signature(topic)
        entry = {
            "topic_id": topic["id"],
            "title": topic.get("title"),
            "domain": topic.get("domain"),
            "research_question": topic.get("research_question"),
            "experiment_capability_id": topic.get("experiment_capability_id"),
            "research_form": topic.get("research_form"),
            "evidence_mode": topic.get("evidence_mode"),
            "comparison_type": topic.get("comparison_type"),
            "signature": signature,
            "run_id": self.run_id,
            "recorded_at": now_iso(),
        }
        evolution = context.get("topic_evolution") if isinstance(context, dict) else None
        if isinstance(evolution, dict) and evolution.get("mode") in {
                "refinement", "feasibility_revalidation"}:
            entry["parent_topic_id"] = evolution.get("parent_topic_id")
            entry["refinement_cycle"] = evolution.get("cycle")
            entry["refinement_reason"] = evolution.get("reason")
            entry["changed_dimensions"] = list(evolution.get("changed_dimensions", []))
            if evolution.get("mode") == "feasibility_revalidation":
                entry["event_type"] = "same_topic_runtime_feasibility_revalidation"
        self._append_topic_history_entries([entry])

    def _record_topic_rejection_history(self, rejected_entries):
        """Persist bounded topic directions rejected before survey admission."""
        from scisaurus.runtime.topic_discovery import topic_signature

        entries = []
        for rejected in rejected_entries or []:
            if not isinstance(rejected, dict):
                continue
            topic_id = rejected.get("topic_id")
            if not isinstance(topic_id, str) or not topic_id.strip():
                continue
            entry = deepcopy(rejected)
            topic = {
                key: entry.get(key) for key in (
                    "id", "title", "domain", "research_question", "research_form",
                    "evidence_mode", "comparison_type")
            }
            topic["id"] = topic_id
            entry.setdefault("signature", topic_signature(topic))
            entry["history_status"] = "rejected"
            entry["run_id"] = self.run_id
            entry["recorded_at"] = now_iso()
            entries.append(entry)
        self._append_topic_history_entries(entries)

    def _current_topic_identity(self):
        """Return the admitted topic frontier identity for work-order fencing."""
        topic_stage = next(
            (item for item in self.workflow.get("stages", [])
             if isinstance(item, dict) and item.get("kind") == "topic_discovery"),
            None,
        )
        if not isinstance(topic_stage, dict):
            return None
        context = self.context.get(topic_stage.get("id"))
        if not isinstance(context, dict) or not isinstance(context.get("topic"), dict):
            return None
        topic_id = context["topic"].get("id")
        if not isinstance(topic_id, str) or not topic_id:
            return None
        evolution = context.get("topic_evolution")
        topic_cycle = context.get("topic_cycle")
        if type(topic_cycle) is not int or topic_cycle < 0:
            topic_cycle = evolution.get("cycle") if isinstance(evolution, dict) else None
        if type(topic_cycle) is not int or topic_cycle < 0:
            topic_cycle = 0
        return {"topic_id": topic_id, "topic_cycle": topic_cycle}

    def _refresh_stage_topic_lineage(self, stage_id, context, *, attempt_id,
                                     topic_identity):
        """Stamp a freshly completed stage result with its admitted topic.

        A topic pivot deliberately replaces downstream contexts with a
        ``superseded_topic_id`` tombstone.  Some stage runners merge that
        context into their new result, so the tombstone must only be cleared
        after the exact attempt admitted under the current topic has returned.
        """
        if (not isinstance(context, dict)
                or not isinstance(topic_identity, dict)
                or not isinstance(topic_identity.get("topic_id"), str)
                or type(topic_identity.get("topic_cycle")) is not int):
            return False
        current = self._current_topic_identity()
        if current != topic_identity:
            return False
        record = self.stage_records.get(stage_id)
        if (not isinstance(record, dict)
                or record.get("topic_id") != topic_identity["topic_id"]
                or record.get("topic_cycle") != topic_identity["topic_cycle"]):
            return False
        active_attempt = record.get("attempt_id") == attempt_id
        restored_attempt = False
        if not active_attempt:
            recovery = context.get("failure_recovery")
            recovery = recovery if isinstance(recovery, dict) else {}
            context_dossier_ref = context.get("failure_dossier_ref")
            if (record.get("status") not in {"running", "retrying", "paused"}
                    and isinstance(context_dossier_ref, str)
                    and type(recovery.get("attempt_number")) is int
                    and context.get("stage_id") == stage_id):
                attempts = record.get("attempts", [])
                restored_attempt = any(
                    isinstance(item, dict)
                    and item.get("attempt_id") == attempt_id
                    and item.get("attempt_number") == recovery["attempt_number"]
                    and item.get("state") == "failed"
                    and item.get("repair_order_issued") is True
                    and item.get("failure_dossier_ref") == context_dossier_ref
                    and item.get("topic_id") == topic_identity["topic_id"]
                    and item.get("topic_cycle") == topic_identity["topic_cycle"]
                    for item in attempts
                ) if isinstance(attempts, list) else False
        if not active_attempt and not restored_attempt:
            return False

        prior_transition_ref = context.get("lineage_transition_ref")
        for key in (
                "superseded_topic_id", "lineage_state", "lineage_transition_ref",
                "topic_pivot_cycle", "pivoted_to_topic"):
            context.pop(key, None)
        context["topic_id"] = topic_identity["topic_id"]
        context["topic_cycle"] = topic_identity["topic_cycle"]
        context["topic_lineage"] = deepcopy(topic_identity)
        context["topic_lineage_attempt_id"] = attempt_id
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "refresh_stage_topic_lineage",
            "stage_id": stage_id,
            "attempt_id": attempt_id,
            "topic_id": topic_identity["topic_id"],
            "topic_cycle": topic_identity["topic_cycle"],
            "cleared_transition_ref": prior_transition_ref,
            "reason": "fresh stage result completed under the currently admitted topic",
        })
        return True

    def _reconcile_restored_stage_topic_lineage(self):
        """Migrate only repair packets tied to a failed current-topic attempt."""
        topic_identity = self._current_topic_identity()
        if not isinstance(topic_identity, dict):
            return []
        refreshed = []
        for stage_id, context in self.context.items():
            if not isinstance(context, dict) or not (
                    context.get("lineage_state") == "awaiting_topic_admission"
                    or isinstance(context.get("superseded_topic_id"), str)):
                continue
            record = self.stage_records.get(stage_id)
            if not isinstance(record, dict):
                continue
            recovery = context.get("failure_recovery")
            recovery = recovery if isinstance(recovery, dict) else {}
            dossier_ref = context.get("failure_dossier_ref")
            attempt_number = recovery.get("attempt_number")
            if not isinstance(dossier_ref, str) or type(attempt_number) is not int:
                continue
            attempts = record.get("attempts", [])
            attempt = next((item for item in reversed(attempts)
                            if isinstance(item, dict)
                            and item.get("attempt_number") == attempt_number
                            and item.get("state") == "failed"
                            and item.get("repair_order_issued") is True
                            and item.get("failure_dossier_ref") == dossier_ref
                            and item.get("topic_id") == topic_identity["topic_id"]
                            and item.get("topic_cycle") == topic_identity["topic_cycle"]), None) \
                if isinstance(attempts, list) else None
            if (isinstance(attempt, dict)
                    and self._refresh_stage_topic_lineage(
                        stage_id, context, attempt_id=attempt.get("attempt_id"),
                        topic_identity=topic_identity)):
                refreshed.append(stage_id)
        return refreshed

    def _reconcile_restored_argument_review_pairs(self):
        """Restore a review only when checkpoint feedback binds it to the exact candidate."""
        reconciled = []
        for stage_id, context in self.context.items():
            if not isinstance(context, dict):
                continue
            argument = context.get("research_argument")
            feedback = context.get("research_feedback")
            if not isinstance(argument, dict) or not isinstance(feedback, dict):
                continue
            if feedback.get("previous_response") != argument:
                continue
            review = feedback.get("adjudication")
            if not isinstance(review, dict):
                continue

            argument_sha256 = hashlib.sha256(canonical_bytes(argument)).hexdigest()
            prior_review = context.get("research_review")
            pairing_changed = (
                prior_review != review
                or context.get("research_review_argument_sha256") != argument_sha256
            )
            if not pairing_changed:
                continue

            prior_review_sha256 = (
                hashlib.sha256(canonical_bytes(prior_review)).hexdigest()
                if isinstance(prior_review, dict) else None
            )
            review_sha256 = hashlib.sha256(canonical_bytes(review)).hexdigest()
            context["research_review"] = deepcopy(review)
            context["research_review_argument_sha256"] = argument_sha256
            if "review" in context and context["review"] == prior_review:
                context["review"] = deepcopy(review)
            package = context.get("argument_package")
            if (isinstance(package, dict)
                    and package.get("argument") == argument):
                package["review"] = deepcopy(review)
                package["argument_sha256"] = argument_sha256
                package["review_sha256"] = review_sha256
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "reconcile_argument_review_pairing",
                "stage_id": stage_id,
                "attempt_id": context.get("attempt_id"),
                "argument_sha256": argument_sha256,
                "prior_review_sha256": prior_review_sha256,
                "review_sha256": review_sha256,
                "reason": "restored adjudication feedback names the exact saved argument",
            })
            reconciled.append(stage_id)
        return reconciled

    def _request_context_matches_current_topic(self, stage_id, context):
        """Reject work orders emitted by a known superseded topic context."""
        topic_stage = next(
            (item for item in self.workflow.get("stages", [])
             if isinstance(item, dict) and item.get("kind") == "topic_discovery"),
            None,
        )
        if isinstance(topic_stage, dict) and stage_id == topic_stage.get("id"):
            return True
        identity = self._current_topic_identity()
        if identity is None or not isinstance(context, dict):
            return True
        if (context.get("lineage_state") == "awaiting_topic_admission"
                or isinstance(context.get("superseded_topic_id"), str)):
            return False
        lineage = context.get("topic_lineage")
        if isinstance(lineage, dict) and isinstance(lineage.get("topic_id"), str):
            if lineage.get("topic_id") != identity["topic_id"]:
                return False
            recorded_cycles = [value for value in (
                lineage.get("topic_cycle"), context.get("topic_cycle"),
            ) if type(value) is int and value >= 0]
            if recorded_cycles:
                return all(value == identity["topic_cycle"] for value in recorded_cycles)
            return identity["topic_cycle"] == 0
        record = self.stage_records.get(stage_id, {})
        if isinstance(record, dict):
            if (record.get("lineage_state") == "awaiting_topic_admission"
                    or isinstance(record.get("superseded_topic_id"), str)):
                return False
            if isinstance(record.get("topic_id"), str):
                if record.get("topic_id") != identity["topic_id"]:
                    return False
                record_cycle = record.get("topic_cycle")
                if type(record_cycle) is int and record_cycle >= 0:
                    return record_cycle == identity["topic_cycle"]
                return identity["topic_cycle"] == 0
        return True

    def _scope_active_research_requests(self, requests):
        """Drop legacy work orders that predate the currently selected topic."""
        if not isinstance(requests, list):
            return []
        identity = self._current_topic_identity()
        if identity is None:
            return [deepcopy(item) for item in requests if isinstance(item, dict)]
        topic_stage_id = next(
            (item.get("id") for item in self.workflow.get("stages", [])
             if isinstance(item, dict) and item.get("kind") == "topic_discovery"),
            None,
        )
        topic_record = self.stage_records.get(topic_stage_id, {})
        topic_context = self.context.get(topic_stage_id, {})
        if not isinstance(topic_record, dict):
            topic_record = {}
        if not isinstance(topic_context, dict):
            topic_context = {}
        refinement_completed = (
            isinstance(topic_context.get("topic_evolution"), dict)
            and topic_context["topic_evolution"].get("mode") in {
                "refinement", "feasibility_revalidation",
            }
            and topic_record.get("status") in STAGE_READY_STATUSES
        )
        scoped = []
        for item in requests:
            if not isinstance(item, dict):
                continue
            if (item.get("topic_id") == identity["topic_id"]
                    and item.get("topic_cycle") == identity["topic_cycle"]):
                scoped.append(deepcopy(item))
            elif not refinement_completed:
                scoped.append(deepcopy(item))
        return scoped

    def _retire_requests_after_topic_change(self, previous_context, current_context):
        """Fence all prior-frontier work orders after a new topic is admitted."""
        previous_topic = (previous_context.get("topic", {})
                          if isinstance(previous_context, dict) else {})
        current_topic = (current_context.get("topic", {})
                         if isinstance(current_context, dict) else {})
        previous_id = previous_topic.get("id") if isinstance(previous_topic, dict) else None
        current_id = current_topic.get("id") if isinstance(current_topic, dict) else None
        if not isinstance(current_id, str) or current_id == previous_id:
            return
        stale = [deepcopy(item) for item in self.active_research_requests
                 if isinstance(item, dict)]
        retired = self.departments.retire_superseded_work_orders(
            set(), reason="superseded by a newly admitted topic frontier")
        if stale or retired:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "retire_work_orders_after_topic_change",
                "previous_topic_id": previous_id,
                "topic_id": current_id,
                "work_orders": retired or [
                    {"request_id": item.get("id"), "state": "stale"}
                    for item in stale
                ],
            })
        self.active_research_requests = []
        for stage_id, context in self.context.items():
            if stage_id == next(
                    (item.get("id") for item in self.workflow.get("stages", [])
                     if isinstance(item, dict) and item.get("kind") == "topic_discovery"),
                    None):
                continue
            if not isinstance(context, dict):
                continue
            carried = []
            for key in ("research_expansion_requests", "research_requests",
                        "deferred_research_requests"):
                value = context.get(key)
                if isinstance(value, list):
                    carried.extend(deepcopy(value))
                    context[key] = []
            if carried:
                context.setdefault("superseded_research_requests", []).extend(carried[-24:])

    def _retire_superseded_stage_tasks(self, stage_ids, *, reason, keep_task_ids=()):
        """Fence aggregate Composer tasks from an older reopened stage.

        A stopped process can leave a stage aggregate task in ``running`` even
        after its durable project checkpoint is paused.  Work-order retirement
        does not cover those aggregate rows because they are not department
        work orders.  Reopening the closure must reconcile any started call and
        stale the old aggregate so the ledger cannot advertise a second live
        execution of the same stage.
        """
        stage_ids = {item for item in (stage_ids or []) if isinstance(item, str) and item}
        if not stage_ids:
            return []
        keep_task_ids = {item for item in (keep_task_ids or [])
                         if isinstance(item, str) and item}
        prefix = f"composer-{self.workflow['id']}-"
        terminal = {"completed", "failed", "cancelled", "stale", "rejected"}
        rows = self.tasks.control._conn.execute(
            "SELECT task_id, state, payload_json FROM tasks ORDER BY task_id"
        ).fetchall()
        retired = []
        for row in rows:
            task_id = row["task_id"]
            if (row["state"] in terminal or task_id in keep_task_ids
                    or not task_id.startswith(prefix)):
                continue
            try:
                payload = json.loads(row["payload_json"])
            except (TypeError, ValueError):
                continue
            if payload.get("stage_id") not in stage_ids:
                continue
            # Specialist assignments have their own lifecycle and are fenced
            # by the department ledger. This helper owns only the aggregate
            # Composer stage task created by _stage_task().
            if payload.get("assignment_id") or payload.get("assignment_logical_id"):
                continue
            active_attempts = self.tasks.control._conn.execute(
                "SELECT attempt_id FROM attempts WHERE task_id = ? AND state = 'started'",
                (task_id,),
            ).fetchall()
            for attempt in active_attempts:
                try:
                    self.tasks.reconcile_unknown(attempt["attempt_id"], "command.composer")
                except (NotFoundError, StateError):
                    continue
            try:
                task = self.tasks.get(task_id)
                if task["state"] not in terminal:
                    task = self.tasks.transition(task_id, "stale", "command.composer", reason=reason)
            except (NotFoundError, StateError):
                continue
            retired.append({
                "task_id": task_id,
                "stage_id": payload.get("stage_id"),
                "state": task["state"],
            })
        return retired

    @staticmethod
    def _request_target_kind(request):
        """Return the stage kind that owns a research work order.

        ``source_stage_id`` records where a request was emitted, not where it
        is executed.  Routing by that provenance field made a survey hold
        disappear from topic refinement and made legacy unscoped requests
        unusable.  The request kind/owner is the stable execution contract.
        """
        if not isinstance(request, dict):
            return None
        explicit_kind = request.get("target_stage_kind")
        if explicit_kind in STAGE_KINDS:
            return explicit_kind
        kind = request.get("kind")
        owner = request.get("owner")
        if kind == "topic_refinement":
            return "topic_discovery"
        if kind in {"literature_expansion", "full_text_retrieval"} or owner == "research.intelligence":
            return "survey"
        if kind in {"additional_experiment", "analysis_display", "analysis_repair"} \
                or owner == "methods.validation":
            return "experiment"
        if kind == "interpretation_expansion" or owner == "strategy.interpretation":
            return "interpretation"
        if kind == "manuscript_revision" or owner == "editorial.composer":
            return "paper"
        return None

    def _requests_for_stage(self, stage_or_id):
        # A continuation may reopen a downstream closure because its input
        # changed, but that does not make every active work order an input to
        # every reopened stage.  Route by the request's execution contract,
        # not its emission provenance.  Interpretation work is also projected
        # to the paper consumer because the manuscript must receive the
        # revised scientific meaning; topic, survey, and experiment repairs
        # are consumed only by their owning stage.
        stage_id = (stage_or_id.get("id") if isinstance(stage_or_id, dict)
                    else stage_or_id)
        stage = stage_or_id if isinstance(stage_or_id, dict) else next(
            (item for item in self.workflow.get("stages", [])
             if isinstance(item, dict) and item.get("id") == stage_id), None)
        stage_kind = stage.get("kind") if isinstance(stage, dict) else None
        requests = []
        for item in self.active_research_requests:
            if not isinstance(item, dict):
                continue
            target_stage_id = item.get("target_stage_id")
            if isinstance(target_stage_id, str):
                if target_stage_id == stage_id:
                    requests.append(deepcopy(item))
                # An explicitly addressed order must never be projected into
                # a sibling stage merely because its department owner is
                # shared.  Legacy orders without this address retain the
                # routing below.
                continue
            target_kind = self._request_target_kind(item)
            if target_kind == stage_kind or (
                    target_kind == "interpretation" and stage_kind == "paper") or (
                    stage_kind is None and target_kind == stage_id):
                requests.append(deepcopy(item))
        if stage_kind == "survey":
            obligation = self._topic_review_obligation(stage)
            if obligation is not None and all(item.get("id") != obligation["id"] for item in requests):
                requests.append(obligation)
        for item in self._topic_deferred_obligations(stage):
            if all(existing.get("id") != item["id"] for existing in requests):
                requests.append(item)
        return requests

    def _owned_topic_review(self, topic_stage):
        context = self.context.get(topic_stage["id"], {})
        verifier = context.get("specialist_verifier") if isinstance(context, dict) else None
        ref = verifier.get("artifact_ref") if isinstance(verifier, dict) else None
        if not isinstance(ref, str):
            if context.get("deferred_review_findings"):
                raise StateError("carried topic review has no immutable verifier execution")
            return None
        record = self.stage_records.get(topic_stage["id"], {})
        plan_ref = verifier.get("assignment_plan_ref") or record.get("assignment_plan_ref")
        if not isinstance(plan_ref, str) or self._stage_specialist_payment_proof(topic_stage, plan_ref, ref) is None:
            raise StateError("carried topic review has no owned specialist assignment")
        manifest, digest, body = self._read_verified_artifact_json(ref)
        report = body.get("report", {})
        response = report.get("response", {})
        if response.get("decision") == "accept" and any(response.get(key) for key in ("blocking_findings", "required_revisions", "critical_findings")):
            raise StateError("accepted topic review retains blocking admission obligations")
        if (body.get("schema_version") != "specialist-verifier-execution-1"
                or body.get("stage_kind") != "topic_discovery"
                or body.get("chief_result", {}).get("topic") != context.get("topic")
                or report.get("status") != "succeeded"):
            raise StateError("carried topic review changes its owned scientific input")
        return context, plan_ref, ref, digest, response

    def _topic_review_obligation(self, survey_stage):
        """Bind a carried topic review to its exact scientific input and execution."""
        topic_stage = self._topic_stage_for_survey(survey_stage)
        if topic_stage is None:
            return None
        owned = self._owned_topic_review(topic_stage)
        if owned is None:
            return None
        context, plan_ref, ref, digest, response = owned
        if response.get("decision") == "accept":
            return None
        if response.get("decision") != "hold":
            raise StateError("carried topic review has no explicit independent decision")
        findings, revisions = (response.get(key, []) for key in ("blocking_findings", "required_revisions"))
        if any(not isinstance(values, list) or any(not isinstance(item, str) or not item.strip() for item in values)
               for values in (findings, revisions)):
            raise StateError("carried topic review has malformed admission obligations")
        if not findings and not revisions:
            raise ModelWorkBlocked("independent topic review remains held without an actionable admission obligation")
        origin = {"verifier_execution_ref": ref, "verifier_execution_sha256": digest,
                  "assignment_plan_ref": plan_ref, "topic_stage_id": topic_stage["id"],
                  "topic_sha256": hashlib.sha256(canonical_bytes(context["topic"])).hexdigest(),
                  "research_question": context["topic"]["research_question"],
                  "blocking_findings": deepcopy(findings), "required_revisions": deepcopy(revisions)}
        identity = hashlib.sha256(canonical_bytes(origin)).hexdigest()
        return {"id": "topic-review-" + identity[:32], "kind": "literature_expansion",
                "owner": "research.intelligence", "target_stage_id": survey_stage["id"],
                "target_stage_kind": "survey",
                "objective": "Independently adjudicate the carried topic admission obligations: "
                    + json.dumps({"blocking_findings": findings, "required_revisions": revisions}, ensure_ascii=False),
                "why": "An independent topic review remains held; its findings are hypotheses to test, not assumed facts.",
                "success_condition": "Every material obligation is independently resolved with authoritative evidence showing it is satisfied, refuted, or outside the declared topic acceptance scope. A literature answer cannot claim that a later-stage file, calculation, or experiment was produced. Unmet requirements and uncertain or limited dispositions remain open.",
                "evidence_needed": "Exact current captured source spans and query receipts, with explicit evidence-linked adjudication of the original findings and revisions.",
                "attempt_lineage": origin}

    def _topic_deferred_obligations(self, target_stage):
        """Route agent-declared future requirements by the exact workflow owner."""
        if not isinstance(target_stage, dict):
            return []
        requests = []
        kinds = {"topic_discovery": "topic_refinement", "survey": "literature_expansion", "experiment": "additional_experiment",
                 "interpretation": "interpretation_expansion", "argument": "interpretation_expansion",
                 "paper": "manuscript_revision"}
        for topic_stage in self.workflow["stages"]:
            if topic_stage["kind"] != "topic_discovery":
                continue
            contract = self._stage_acceptance_contract(topic_stage)
            if target_stage["id"] not in contract["downstream_stage_ids"]:
                continue
            owned = self._owned_topic_review(topic_stage)
            if owned is None:
                continue
            context, plan_ref, ref, digest, response = owned
            normalized = _normalise_verdict(response, current_stage_id=topic_stage["id"],
                valid_target_stage_ids=contract["downstream_stage_ids"])
            for obligation in normalized.get("deferred_obligations", []):
                if obligation["target_stage_id"] != target_stage["id"]:
                    continue
                origin = {"verifier_execution_ref": ref, "verifier_execution_sha256": digest,
                    "assignment_plan_ref": plan_ref, "topic_stage_id": topic_stage["id"],
                    "topic_sha256": hashlib.sha256(canonical_bytes(context["topic"])).hexdigest(),
                    "research_question": context["topic"]["research_question"],
                    "deferred_obligation": deepcopy(obligation)}
                requests.append({"id": "topic-deferred-" + hashlib.sha256(canonical_bytes(origin)).hexdigest()[:32],
                    "kind": kinds[target_stage["kind"]], "owner": STAGE_ROLES[target_stage["kind"]],
                    "source_stage_id": topic_stage["id"], "target_stage_id": target_stage["id"],
                    "target_stage_kind": target_stage["kind"], "objective": obligation["requirement"],
                    "why": "An independent topic review assigns this requirement to its declared downstream owner.",
                    "success_condition": obligation["completion_check"],
                    "evidence_needed": (obligation["evidence_needed"] if isinstance(obligation["evidence_needed"], str)
                        else json.dumps(obligation["evidence_needed"], ensure_ascii=False)), "attempt_lineage": origin})
        return requests

    def _topic_review_obligation_is_closed(self, stage, result, obligation, *, require_independent=False):
        """A limited search is retained evidence, not closure of an admission debt."""
        rows = (result.get("follow_up_result") or {}).get("orders", [])
        project = self.stage_records.get(stage["id"], {}).get("project_dir") or result.get("project_dir") or stage["project_dir"]
        record = self.stage_records.get(stage["id"], {})
        return ((not require_independent or self._survey_attempt_was_accepted(stage["id"], record, result))
                and any(isinstance(row, dict) and row.get("id") == obligation["id"]
                    and row.get("status") == "resolved" for row in rows)
                and self._survey_work_order_was_fulfilled(project, result, obligation))

    def _topic_review_revalidation_input(self, stage):
        """Replay owned production and peer evidence for a changed verifier contract."""
        context = self.context.get(stage["id"], {})
        verifier = context.get("specialist_verifier") or {}
        ref = verifier.get("artifact_ref")
        if not isinstance(ref, str):
            return None
        manifest, digest, execution = self._read_verified_artifact_json(ref)
        if execution.get("initial_review_input", {}).get("system") == VERIFIER_SYSTEM:
            return None
        record = self.stage_records.get(stage["id"], {})
        plan_ref = verifier.get("assignment_plan_ref") or record.get("assignment_plan_ref")
        if (execution.get("schema_version") != "specialist-verifier-execution-1"
                or execution.get("stage_kind") != "topic_discovery"
                or execution.get("chief_result", {}).get("topic") != context.get("topic")
                or not isinstance(plan_ref, str)
                or self._stage_specialist_payment_proof(stage, plan_ref, ref) is None):
            raise StateError("topic review revalidation has no exact owned verifier input")
        output = Path(context["output_path"]).resolve()
        output_hash = hashlib.sha256(output.read_bytes()).hexdigest()
        candidates = []
        cache = ModelWorkCache(self.store, self._publish)
        for cached in cache.entries():
            result = cached.get("result") or {}
            if (cached.get("status") != "succeeded" or result.get("stage_id") != stage["id"]
                    or result.get("kind") != "topic_discovery" or result.get("status") != "completed"
                    or result.get("output_path") != str(output)
                    or cached.get("output_sha256") != output_hash
                    or result.get("topic") != context.get("topic")):
                continue
            producer_record, producer_digest, _ = self._read_verified_artifact_json(cached["cache_ref"])
            if producer_record.get("author") != "command.controller":
                raise StateError("topic review revalidation producer cache is not controller owned")
            candidates.append((cached, producer_digest))
        if not candidates or any(item[0]["result"] != candidates[0][0]["result"] for item in candidates):
            raise StateError("topic review revalidation has no unique immutable completed producer")
        cached, producer_digest = candidates[0]
        peers = deepcopy(execution.get("specialist_reports"))
        if not isinstance(peers, list) or not peers:
            raise StateError("topic review revalidation has no retained independent peer reports")
        for peer in peers:
            peer_ref = peer.get("artifact_ref")
            if not isinstance(peer_ref, str) or self._stage_specialist_payment_proof(stage, plan_ref, peer_ref) is None:
                raise StateError("topic review revalidation peer is not assignment owned")
            _, _, peer_execution = self._read_verified_artifact_json(peer_ref)
            retained = peer_execution.get("report", {})
            if (peer_execution.get("schema_version") != "specialist-execution-1"
                    or any(peer.get(key) != retained.get(key) for key in ("status", "role_id", "assigned_role", "response", "usage"))):
                raise StateError("topic review revalidation changes retained peer evidence")
            assignment = next(item for item in self.departments._assignment_task_rows(
                stage_id=stage["id"], attempt_number=peer_execution["attempt_number"])
                if item["task_id"] == peer_execution["task_id"])
            peer["input_scope"] = {"declared_fields": deepcopy(assignment.get("input_projection", [])),
                                   "assignment_phase": assignment.get("assignment_phase"),
                                   "assignment_plan_ref": plan_ref,
                                   "execution_ref": peer_ref, "contract_state": "retained_original"}
        return {"producer_cache_ref": cached["cache_ref"], "producer_cache_sha256": producer_digest,
                "output_path": str(output), "output_sha256": output_hash,
                "result": deepcopy(cached["result"]), "peer_reports": deepcopy(peers),
                "prior_verifier_execution_ref": ref, "prior_verifier_execution_sha256": digest,
                "prior_assignment_plan_ref": plan_ref}

    def revalidate_topic_review(self, stage_id):
        """Re-review exact paid topic production when the verifier contract changes."""
        stage = next((item for item in self.workflow["stages"] if item["id"] == stage_id), None)
        if stage is None or stage.get("kind") != "topic_discovery":
            raise StateError("review revalidation requires a topic stage")
        retained = self._topic_review_revalidation_input(stage)
        if retained is None:
            return None
        if self._execution_started:
            raise StateError("topic review revalidation must precede workflow execution")
        _, stopped = self._stopped_execution_checkpoint()
        for producer in self.workflow["stages"]:
            record = stopped.get("stages", {}).get(producer["id"], {})
            if record.get("status") not in {"running", "retrying"} or producer["id"] == stage_id:
                continue
            project = record.get("project_dir") or producer["project_dir"]
            progress = self._read_json_object(Path(project) / "output/progress.json") or {}
            if (self._producer_checkpoint_evidence(project, progress) is None
                    or progress.get("phase") not in {"calls_settled", "paused"}
                    or progress.get("active_tasks") or progress.get("active_operations")):
                raise StateError("topic review revalidation requires idle captured downstream production")
        self.context[stage_id]["specialist_verifier"]["assignment_plan_ref"] = retained["prior_assignment_plan_ref"]
        self._reconcile_interrupted_stage_attempts()
        remaining = min(float(stage["deadline_seconds"]), self._remaining())
        attempt_deadline = min(self.deadline_epoch, time.time() + remaining)
        prior = deepcopy(self.stage_records[stage_id])
        history = self._archive_stage_attempt(prior, cycle=self.continuation_cycles,
                                               default_project_dir=stage["project_dir"])
        number = max(prior.get("attempt_count", 0), prior.get("attempt_number", 0)) + 1
        identity = hashlib.sha256(canonical_bytes({"input": retained,
            "verifier_system": VERIFIER_SYSTEM, "cycle": self.continuation_cycles})).hexdigest()
        admission = self._publish(f"command/composer/topic-review-revalidations/{identity}", "decision_note", {
            "schema_version": "topic-review-revalidation-1", "stage_id": stage_id,
            "cycle": self.continuation_cycles, "producer": retained,
            "verifier_system_sha256": hashlib.sha256(VERIFIER_SYSTEM.encode()).hexdigest(),
        }, "command.composer", subjects=[retained["producer_cache_ref"], retained["prior_verifier_execution_ref"],
            *[peer["artifact_ref"] for peer in retained["peer_reports"]]])
        task_id = "topic-review-revalidation-" + identity[:24] + "-" + str(number)
        task = self.tasks.create(task_id, "review", {"stage_id": stage_id, "admission_ref": admission["artifact_ref"]}, "command.composer")
        if task["state"] not in {"proposed", "queued"}:
            raise StateError("topic review revalidation requires reconciliation of its existing attempt")
        if task["state"] == "proposed":
            self.tasks.transition(task_id, "queued", "command.composer")
        attempt_id = task_id + "-" + uuid.uuid4().hex
        self.tasks.start_attempt(task_id, attempt_id, owner="command.composer", lease_ttl_seconds=remaining,
            payload={"stage_id": stage_id, "kind": "topic_discovery", "attempt_number": number,
                     "model_budget_cycle": self.continuation_cycles if stage_id in self.reopened_stage_ids else 0,
                     "project_dir": stage["project_dir"], "admission_ref": admission["artifact_ref"],
                     "attempt_deadline_at_epoch": attempt_deadline})
        plan = self.departments.begin_stage(stage_id, "topic_discovery", attempt_number=number,
            input_ref={"kind": "composer_stage_task", "ref": task_id, "digest": identity},
            deadline_seconds=remaining, active_role_ids=[])
        self.stage_records[stage_id] = {**prior, "status": "running", "task_id": task_id,
            "attempt_id": attempt_id, "attempt_number": number, "attempt_count": number,
            "attempts": history, "project_dir": stage["project_dir"],
            "attempt_deadline_at_epoch": attempt_deadline,
            "review_revalidation_admission_ref": admission["artifact_ref"], **self._stage_assignment_fields(plan)}
        self._checkpoint(f"{stage_id}:review_revalidation_admitted", force=True)
        descriptor = json.loads(Path(stage["config_path"]).read_text())
        chief = deepcopy(retained["result"])
        bundle = {"reports": retained["peer_reports"], "usage": {}, "model_enabled": True}
        try:
            report = self._run_specialist_verifier(stage, plan, descriptor, bundle, chief, stage_result=chief)
            if not isinstance(report, dict) or report.get("status") != "succeeded":
                if isinstance(report, dict) and isinstance(report.get("failure"), dict):
                    raise ModelCallError.from_failure(report.get("error") or "topic verifier request failed", report["failure"])
                raise ModelWorkBlocked("topic review revalidation did not produce a complete independent decision")
            response = report.get("response", {})
            if (response.get("decision") not in {"accept", "hold"}
                    or (response["decision"] == "accept" and any(response.get(key) for key in ("blocking_findings", "required_revisions", "critical_findings")))):
                raise ModelWorkBlocked("topic review revalidation has contradictory admission obligations", failure_class="model_contract")
        except Exception as error:
            usage = self._specialist_usage([report]) if "report" in locals() and isinstance(report, dict) else deepcopy(getattr(error, "usage", {}))
            failed = self.departments.finish_stage(stage_id, "topic_discovery", attempt_number=number,
                outcome="failed", output_ref=chief["output_path"], usage=usage, error=str(error),
                verifier_result=report if "report" in locals() and isinstance(report, dict) else None)
            self.tasks.finish_attempt(attempt_id, "failed", usage=usage)
            self.tasks.transition(task_id, "blocked", "command.composer")
            self.stage_records[stage_id].update(status="review_revalidation_failed", error=str(error),
                                               **self._stage_assignment_fields(plan, failed))
            self.status = "paused"
            self._checkpoint(f"{stage_id}:review_revalidation_failed", force=True)
            raise
        response = report.get("response", {})
        outcome = "completed" if response.get("decision") == "accept" else "candidate_needs_review"
        finished = self.departments.finish_stage(stage_id, "topic_discovery", attempt_number=number,
            outcome=outcome, output_ref=chief["output_path"], usage=report.get("usage", {}), verifier_result=report)
        self.tasks.finish_attempt(attempt_id, "succeeded", usage=report.get("usage", {}))
        self.tasks.transition(task_id, "awaiting_review", "command.composer")
        self.tasks.transition(task_id, "completed", "command.composer")
        context = deepcopy(self.context[stage_id])
        context.update(status=outcome, specialist_verifier=deepcopy(report),
            review_revalidation={"admission_ref": admission["artifact_ref"], "producer_calls_replayed": 0,
                                "peer_calls_replayed": 0, "prior_verifier_execution_ref": retained["prior_verifier_execution_ref"]})
        if response.get("decision") == "accept":
            context.pop("deferred_review_findings", None)
        else:
            context["deferred_review_findings"] = deepcopy(response)
        self.context[stage_id] = context
        self.stage_records[stage_id].update(status=outcome, **self._stage_assignment_fields(plan, finished))
        self.stage_records[stage_id]["usage"] = deepcopy(report.get("usage", {}))
        self.stage_records[stage_id].pop("error", None)
        self._archive_stage_attempt(self.stage_records[stage_id], cycle=self.continuation_cycles,
                                    default_project_dir=stage["project_dir"])
        self._checkpoint(f"{stage_id}:review_revalidation_completed", force=True)
        return deepcopy(context)

    @staticmethod
    def _normalize_research_request_value(value):
        """Remove volatile execution identity while retaining scientific intent."""
        if isinstance(value, str):
            normalized = value.strip()
            normalized = re.sub(
                r"artifact:[A-Za-z0-9._/-]+@[1-9][0-9]*", "artifact:<version>", normalized)
            normalized = re.sub(
                r"/Users/[^\s\"'<>]+|/private/[^\s\"'<>]+|/tmp/[^\s\"'<>]+",
                "<path>", normalized)
            normalized = re.sub(
                r"\b(attempt|cycle|continuation)[-_ ]\d+\b",
                lambda match: match.group(1).casefold() + "-<n>",
                normalized, flags=re.IGNORECASE)
            normalized = re.sub(r"\b[0-9a-f]{32,64}\b", "<digest>", normalized,
                                flags=re.IGNORECASE)
            return normalized
        if isinstance(value, list):
            return [ComposerRunner._normalize_research_request_value(item)
                    for item in value]
        if isinstance(value, dict):
            return {
                key: (deepcopy(item) if isinstance(key, str) and key.endswith("_sha256")
                      else ComposerRunner._normalize_research_request_value(item))
                for key, item in sorted(value.items())
                if key not in ({"id", "created_at", "updated_at", "timestamp"}
                               | RESEARCH_REQUEST_EXECUTION_METADATA_KEYS)
            }
        return value

    @staticmethod
    def _research_request_signature(request):
        """Identify a substantive order independently of its artifact/path wrapper."""
        stable = {
            key: ComposerRunner._normalize_research_request_value(request.get(key))
            for key in (
                "kind", "owner", "objective", "success_condition", "evidence_needed",
                "source_stage_id", "target_stage_id", "target_stage_kind",
                "topic_id", "topic_cycle", "source_survey_ref", "source_assessment_ref",
                "failure_input_sha256",
                "recovery_mode", "repair_policy_revision", "resume_scopes", "repair_commands", "acceptance_checks",
                "review_directives", "experiment_repair_plan", "repair_strategy",
            )
            if key in request
        }
        for key in ("source_survey_ref", "source_assessment_ref"):
            if key in request:
                stable[key] = deepcopy(request[key])
        return hashlib.sha256(canonical_bytes(stable)).hexdigest()

    def _research_request_was_admitted(self, request, *, failure_dossier_ref=None):
        signature = self._research_request_signature(request)
        return any(
            isinstance(decision, dict) and decision.get("action") == "continue_research"
            and isinstance(decision.get("research_requests"), list)
            and any(isinstance(item, dict)
                    and (failure_dossier_ref is None or item.get("failure_dossier_ref") == failure_dossier_ref)
                    and self._research_request_signature(item) == signature
                    for item in decision["research_requests"])
            for decision in self.feedback)

    def _recovery_input_matches(self, stage, request, context, current_input):
        declared = request.get("failure_input_sha256")
        if declared == current_input:
            return True
        if (request.get("kind") != "recovery"
                or request.get("recovery_mode") != "format_repair_then_rerun"
                or not isinstance(declared, str) or re.fullmatch(r"[0-9a-f]{16}", declared) is None
                or not isinstance(current_input, str) or re.fullmatch(r"[0-9a-f]{64}", current_input) is None):
            return False
        recovery = context.get("failure_recovery") or {}
        ref = context.get("failure_dossier_ref") or recovery.get("dossier_ref")
        if (not isinstance(ref, str) or request.get("failure_dossier_ref") != ref
                or not self._research_request_was_admitted(request, failure_dossier_ref=ref)):
            return False
        try:
            manifest, _, dossier = self._read_verified_artifact_json(ref)
        except (NotFoundError, KeyError, OSError, TypeError, ValueError, ValidationError):
            return False
        if (manifest.get("author") != "command.composer"
                or dossier.get("schema_version") != "composer-failure-recovery-1"):
            return False
        evidence = self._failure_dossier_evidence(ref, expected_stage_id=stage["id"])
        if (not isinstance(evidence, dict) or evidence.get("available") is not True
                or evidence.get("input_sha256") != current_input):
            return False
        return declared == current_input[:16]

    def _has_pending_admitted_recovery(self, stage, by_id):
        identity = self._current_topic_identity()
        context = self.context.get(stage["id"], {})
        recovery = context.get("failure_recovery")
        current_input = context.get("failure_input_sha256") or (
            recovery.get("input_sha256") if isinstance(recovery, dict) else None)
        for request in self.active_research_requests:
            if not isinstance(request, dict) or request.get("source_stage_id") != stage["id"]:
                continue
            if identity is not None and any(request.get(key) != identity[key]
                                            for key in ("topic_id", "topic_cycle")):
                continue
            if (current_input and request.get("failure_input_sha256")
                    and not self._recovery_input_matches(stage, request, context, current_input)):
                continue
            target_id = request.get("target_stage_id")
            if (not isinstance(target_id, str) or target_id not in by_id
                    or self._request_target_kind(request) != by_id[target_id].get("kind")
                    or not self._research_request_was_admitted(request)):
                continue
            closure = self._continuation_targets([request], by_id)
            if stage["id"] not in closure or not closure <= self.continuation_pending_stage_ids:
                continue
            target_context = self.context.get(target_id, {})
            if (self.stage_records.get(target_id, {}).get("status") not in {"completed", "accepted"}
                    or target_context.get("preserve_work_orders")
                    or request.get("kind") == "literature_expansion"
                    and not self._survey_request_was_fulfilled(
                        target_context.get("project_dir") or by_id[target_id]["project_dir"],
                        target_context, request)):
                return True
        return False

    def _restore_attempted_research_request_signatures(self, checkpoint):
        """Restore persisted work-order fences and migrate completed legacy cycles."""
        checkpoint = checkpoint if isinstance(checkpoint, dict) else {}
        restored = checkpoint.get("attempted_request_signatures", [])
        if isinstance(restored, list):
            self._attempted_request_signatures.update(
                item for item in restored
                if isinstance(item, str) and re.fullmatch(r"[0-9a-f]{64}", item))

        stages = {
            stage.get("id"): stage for stage in self.workflow.get("stages", [])
            if isinstance(stage, dict) and isinstance(stage.get("id"), str)
        }
        feedback = checkpoint.get("feedback", [])
        if not isinstance(feedback, list):
            return
        terminal = {"succeeded", "completed", "failed", "blocked", "cancelled"}
        for decision in feedback:
            if (not isinstance(decision, dict)
                    or decision.get("action") != "continue_research"
                    or type(decision.get("cycle")) is not int):
                continue
            cycle = decision["cycle"]
            for request in decision.get("research_requests", []):
                if not isinstance(request, dict):
                    continue
                target_id = request.get("target_stage_id")
                if isinstance(target_id, str):
                    target_stages = [stages[target_id]] if target_id in stages else []
                else:
                    target_kind = self._request_target_kind(request)
                    target_stages = [stage for stage in stages.values()
                                     if stage.get("kind") == target_kind]
                attempted = False
                for stage in target_stages:
                    record = self.stage_records.get(stage["id"], {})
                    attempts = record.get("attempts", []) if isinstance(record, dict) else []
                    if any(
                            isinstance(attempt, dict)
                            and attempt.get("cycle") == cycle
                            and attempt.get("state") in terminal
                            and not re.search(
                                r"\b(?:429|quota[_ -]?exhausted|rate[_ -]?limit)\b",
                                str(attempt.get("error", "")), re.IGNORECASE)
                            for attempt in attempts if isinstance(attempt, dict)):
                        attempted = True
                        break
                if attempted:
                    self._attempted_request_signatures.add(
                        self._research_request_signature(request))

    @staticmethod
    def _is_topic_pivot_request(request):
        return (
            isinstance(request, dict)
            and request.get("kind") == "topic_refinement"
            and request.get("recovery_mode") not in {
                "continue_same_topic_after_local_budget",
                "runtime_feasibility_revalidation_same_question",
            }
        )

    def _mark_research_requests_attempted(self, stage):
        """Fence echoed work orders after their owning stage has returned.

        A scientific hold remains visible as an open departmental order, but
        the same request must not reopen the identical stage closure in a hot
        loop.  A changed request body receives a different signature and can
        trigger a new continuation in this invocation.
        """
        from scisaurus.runtime.departments import REQUEST_STAGE_KINDS

        deferred = set()
        if stage.get("kind") == "survey":
            record = self.stage_records.get(stage["id"], {})
            project = record.get("project_dir") or self.context.get(stage["id"], {}).get("project_dir") or stage["project_dir"]
            recovery = self._survey_revalidation_recovery({**stage, "project_dir": project})
            if recovery is not None:
                deferred = {self._research_request_signature(item)
                            for item in recovery["deferred_research_requests"]}
        for request in self.active_research_requests:
            if not isinstance(request, dict):
                continue
            if self._research_request_signature(request) in deferred:
                continue
            target_stage_id = request.get("target_stage_id")
            if isinstance(target_stage_id, str):
                if target_stage_id == stage.get("id"):
                    self._attempted_request_signatures.add(
                        self._research_request_signature(request))
                continue
            target_kind = REQUEST_STAGE_KINDS.get(request.get("kind"))
            # Legacy argument repair was represented as an
            # ``interpretation_expansion`` order because the claim-evidence
            # graph is owned by Strategy.  Keep that fallback for old
            # checkpoints; new orders carry an explicit target stage above.
            argument_scoped = (
                stage.get("kind") == "argument"
                and request.get("source_stage_id") == stage.get("id")
                and target_kind == "interpretation"
            )
            if target_kind != stage.get("kind") and not argument_scoped:
                continue
            self._attempted_request_signatures.add(self._research_request_signature(request))

    @staticmethod
    def _forward_debt_work_order(stage_id, debt):
        """Turn deferred failure debt into one deterministic backfill order."""
        if not isinstance(debt, dict):
            return None
        stage_kind = debt.get("kind")
        mapping = {
            "topic_discovery": (
                "topic_refinement", "research.intelligence",
                "Return to the failed topic envelope and strengthen the same phenomenon using the source-grounded repair evidence.",
            ),
            "survey": (
                "literature_expansion", "research.intelligence",
                "Backfill the survey evidence debt with identity-reconciled primary and full-text support.",
            ),
            "experiment": (
                "additional_experiment", "methods.validation",
                "Backfill the methods debt with a discriminating control, sensitivity check, or independent recalculation.",
            ),
            "interpretation": (
                "interpretation_expansion", "strategy.interpretation",
                "Backfill the interpretation debt by separating competing mechanisms and relinking claims to observations.",
            ),
            "argument": (
                "interpretation_expansion", "strategy.interpretation",
                "Backfill the argument debt by repairing the claim-evidence graph and unsupported inferential steps.",
            ),
            "paper": (
                "manuscript_revision", "editorial.composer",
                "Backfill the manuscript debt with a fresh evidence-linked revision and rendered review pass.",
            ),
        }
        mapped = mapping.get(stage_kind)
        if mapped is None:
            return None
        kind, owner, default_objective = mapped
        stable = {
            "stage_id": stage_id,
            "kind": kind,
            "failure_class": debt.get("failure_class"),
            "error": debt.get("error"),
            "attempts": debt.get("attempts"),
        }
        request_id = "forward-" + hashlib.sha256(canonical_bytes(stable)).hexdigest()[:20]
        error = str(debt.get("error") or "the previous assignment did not produce an accepted artifact")[:1800]
        return {
            "id": request_id,
            "kind": kind,
            "owner": owner,
            "objective": default_objective,
            "why": f"The Composer carried an unresolved provisional result for {stage_id}. Failure debt: {error}",
            "success_condition": "Produce the missing evidence or analysis, rerun the affected acceptance checks, and preserve the prior candidate if the debt remains unresolved.",
            "evidence_needed": "The prior candidate artifact, failure debt, exact input identity, and a fresh independently checked result.",
            "source_stage_id": stage_id,
            "target_stage_id": stage_id,
            "target_stage_kind": stage_kind,
            "repair_priority": "immediate",
        }

    def _free_topic_stage(self):
        """Return a topic stage that feeds a scholarly survey.

        A free-topic mission is defined by its dependency graph, not by the
        presence of a particular executable capability catalog.  Catalogs are
        useful for selecting pinned experiment adapters, while a topic→survey
        edge is the actual boundary at which literature evidence must be able
        to send the question back for redesign.
        """
        stages = self.workflow.get("stages", [])
        for topic in stages:
            if topic.get("kind") != "topic_discovery":
                continue
            pending = [topic.get("id")]
            seen = set()
            while pending:
                current = pending.pop()
                if current in seen:
                    continue
                seen.add(current)
                for stage in stages:
                    if current not in stage.get("depends_on", []):
                        continue
                    if stage.get("kind") == "survey":
                        return topic
                    pending.append(stage.get("id"))
        return None

    def _topic_stage_for_survey(self, survey_stage=None):
        """Find the topic ancestor for one survey stage, if any."""
        if survey_stage is None:
            return self._free_topic_stage()
        by_id = {item.get("id"): item for item in self.workflow.get("stages", [])
                 if isinstance(item, dict)}
        pending = list(survey_stage.get("depends_on", []))
        seen = set()
        while pending:
            current = pending.pop()
            if current in seen:
                continue
            seen.add(current)
            candidate = by_id.get(current)
            if not isinstance(candidate, dict):
                continue
            if candidate.get("kind") == "topic_discovery":
                return candidate
            pending.extend(candidate.get("depends_on", []))
        return None

    def _survey_context_for_topic(self, topic_stage):
        """Return the latest survey context downstream of a topic stage."""
        stages = self.workflow.get("stages", [])
        by_id = {item.get("id"): item for item in stages if isinstance(item, dict)}
        pending = [topic_stage.get("id")]
        seen = set()
        survey_ids = []
        while pending:
            current = pending.pop(0)
            if current in seen:
                continue
            seen.add(current)
            for stage in stages:
                if current not in stage.get("depends_on", []):
                    continue
                if stage.get("kind") == "survey":
                    survey_ids.append(stage.get("id"))
                pending.append(stage.get("id"))
        for survey_id in survey_ids:
            context = self.context.get(survey_id)
            if isinstance(context, dict):
                return context
        return next((value for value in self.context.values()
                     if isinstance(value, dict) and value.get("kind") == "survey"), {})

    def _topic_refinement_context(self, stage):
        """Build the evidence handoff for a substantive topic revision."""
        if stage.get("kind") != "topic_discovery":
            return None
        stage_requests = self._requests_for_stage(stage)
        requests = [item for item in stage_requests
                    if self._is_topic_pivot_request(item)]
        feasibility_repairs = [
            item for item in stage_requests
            if isinstance(item, dict)
            and item.get("kind") == "topic_refinement"
            and item.get("recovery_mode")
            == "runtime_feasibility_revalidation_same_question"
        ]
        contract_repairs = [
            item for item in stage_requests
            if item.get("kind") == "recovery"
            and item.get("recovery_mode") == "format_repair_then_rerun"
            and item.get("target_stage_id") == stage.get("id")
        ]
        parent_context = self.context.get(stage["id"], {})
        parent_context = parent_context if isinstance(parent_context, dict) else {}
        parent = parent_context.get("topic")
        pending_pivot = parent_context.get("topic_pivot")
        if (not requests and not contract_repairs and isinstance(parent, dict)
                and isinstance(pending_pivot, dict)
                and pending_pivot.get("status") == "required"):
            source_stage_id = pending_pivot.get("source_stage_id")
            source_context = self.context.get(source_stage_id, {})
            source_context = source_context if isinstance(source_context, dict) else {}
            source_failure = source_context.get("superseded_scope_failure")
            if not isinstance(source_failure, dict):
                source_failure = source_context.get("failure_recovery")
            source_failure = source_failure if isinstance(source_failure, dict) else {}
            evidence = [
                "The retained topic pivot is still pending; a local allocation reset is not a scientific decision.",
                "Pivot reason: " + str(pending_pivot.get("reason") or "unspecified")[:1200],
            ]
            if isinstance(source_stage_id, str) and source_stage_id:
                evidence.append("Source stage: " + source_stage_id)
            for value in (
                    source_context.get("error"), source_failure.get("failure_dossier_ref"),
                    source_failure.get("reason")):
                if isinstance(value, str) and value.strip():
                    evidence.append(value.strip()[:1600])
            pivot_cycle = pending_pivot.get("cycle")
            if type(pivot_cycle) is not int or pivot_cycle < 0:
                pivot_cycle = self.continuation_cycles
            requests = [{
                "id": f"auto-topic-pivot-resume-{pivot_cycle}",
                "kind": "topic_refinement",
                "owner": "research.intelligence",
                "objective": (
                    "Resume the already-decided topic refinement. Preserve the parent's scientific "
                    "phenomenon and strongest supported mechanism; repair the recorded blocker by "
                    "narrowing or strengthening its question, comparison, observable, or evidence "
                    "boundary. Do not restart unrelated topic discovery."
                ),
                "why": (
                    "The checkpoint contains an unresolved topic-pivot decision. The local topic "
                    "budget only controls resources; it does not erase the parent's evidence or "
                    "authorize an unrelated replacement."
                ),
                "success_condition": (
                    "A source-grounded adjacent refinement preserves the parent's phenomenon unless "
                    "independent evidence directly refutes it or establishes infeasibility, addresses "
                    "the recorded blocker, and enters the existing literature-survey path."
                ),
                "evidence_needed": " ".join(evidence),
                "source_stage_id": stage["id"],
            }]
        if not requests and not contract_repairs and not feasibility_repairs:
            return None
        if not isinstance(parent, dict):
            return None
        if feasibility_repairs:
            request = feasibility_repairs[-1]
            retained_fields = (
                "admission_state", "maturity_open_requirements",
                "maturity_requirement_dispositions", "maturity_reviews",
                "maturity_review_history", "maturity_score", "next_evidence_action",
                "source_challenge", "candidate_prior_work", "candidate_sampling_trace",
                "rejected_topic_history", "topic_history",
            )
            parent_evidence = {
                "frontier_seed_plan": deepcopy(parent_context.get("frontier_seed_plan")),
                "recent_papers": [
                    deepcopy(item) for item in parent_context.get("recent_papers", [])
                    if isinstance(item, dict)
                ][:16],
                "candidate_prior_work": [
                    deepcopy(item) for item in parent_context.get("candidate_prior_work", [])
                    if isinstance(item, dict)
                ][:16],
                "source_challenge": deepcopy(parent_context.get("source_challenge")),
                "retained_admission": {
                    key: deepcopy(parent_context[key])
                    for key in retained_fields if key in parent_context
                },
            }
            return {
                "mode": "runtime_feasibility_revalidation",
                "cycle": self.continuation_cycles,
                "objective": request.get("objective"),
                "parent_topic_id": parent.get("id"),
                "parent_topic": deepcopy(parent),
                "parent_evidence": parent_evidence,
                "reason": str(
                    (parent_context.get("runtime_feasibility_revalidation") or {}).get(
                        "reason") or request.get("why") or "")[:1200],
                "work_orders": [{key: request.get(key) for key in (
                    "id", "kind", "objective", "why", "success_condition",
                    "evidence_needed")}],
                "changed_dimensions": [],
                "salvage_plan": None,
            }
        survey = self._survey_context_for_topic(stage)
        survey_evidence = {}
        survey_dir = survey.get("project_dir") if isinstance(survey, dict) else None
        if isinstance(survey_dir, str):
            survey_root = Path(survey_dir).resolve() / "output"
            for filename in ("gap-assessment.json", "coverage.json"):
                path = survey_root / filename
                if not path.is_file():
                    continue
                try:
                    value = json.loads(path.read_text())
                except (OSError, ValueError, TypeError):
                    continue
                # Keep the handoff bounded; source spans and work IDs are
                # enough to direct the next search without copying a whole
                # literature database into the topic model prompt.
                encoded = json.dumps(value, ensure_ascii=False, sort_keys=True)
                if len(encoded) > 20000:
                    encoded = encoded[:20000]
                survey_evidence[filename] = encoded
        feedback = {
            "gap_state": survey.get("gap_state") if isinstance(survey, dict) else None,
            "nomination": deepcopy(survey.get("nomination")) if isinstance(survey, dict) else None,
            "assessment_ref": survey.get("assessment_ref") if isinstance(survey, dict) else None,
            "evidence": survey_evidence,
            "requests": [{key: item.get(key) for key in (
                "id", "kind", "objective", "why", "success_condition", "evidence_needed",
                "salvage_policy", "salvage_branch_limit")}
                         for item in requests],
        }
        response_contract_repair = None
        if contract_repairs:
            validation_error = None
            diagnostic_sources = [
                parent_context.get("model_diagnostics"),
                (parent_context.get("failure_recovery") or {}).get("model_diagnostics")
                if isinstance(parent_context.get("failure_recovery"), dict) else None,
            ]
            for diagnostics in diagnostic_sources:
                if not isinstance(diagnostics, dict):
                    continue
                response_repair = diagnostics.get("topic_response_repair")
                if isinstance(response_repair, dict):
                    validation_error = response_repair.get("previous_validation_error")
                    if isinstance(validation_error, str) and validation_error.strip():
                        break
            if not isinstance(validation_error, str) or not validation_error.strip():
                trace = parent_context.get("candidate_attempt_trace")
                for record in reversed(trace if isinstance(trace, list) else []):
                    if not isinstance(record, dict):
                        continue
                    validation_error = record.get("previous_validation_error")
                    if isinstance(validation_error, str) and validation_error.strip():
                        break
                    detail = record.get("error")
                    if isinstance(detail, str) and detail.strip():
                        marker = "previous validation failure:"
                        if marker in detail:
                            validation_error = detail.split(marker, 1)[1].strip()
                            break
                        if record.get("status") == "rejected":
                            validation_error = detail
                            break
            if not isinstance(validation_error, str) or not validation_error.strip():
                validation_error = parent_context.get("error")
            if isinstance(validation_error, str) and validation_error.strip():
                response_contract_repair = {
                    "validation_error": validation_error[:2048],
                }
        if contract_repairs:
            if response_contract_repair is None:
                response_contract_repair = {
                    "validation_error": str(parent_context.get("error") or
                                             "The prior topic package failed deterministic validation")[:2048],
                }
            return {
                "mode": "response_contract_repair",
                "cycle": self.continuation_cycles,
                "parent_topic_id": parent.get("id"),
                "parent_topic": deepcopy(parent),
                "response_contract_repair": response_contract_repair,
            }
        if not requests:
            return None
        rejected_directions = []
        rejected_questions = set()

        def remember_rejection(candidate, reason=None, status=None):
            if not isinstance(candidate, dict) or candidate.get("id") != parent.get("id"):
                return
            if status not in {"rejected", "refinement_rejected", "maturity_rejected"} and not reason:
                return
            question = candidate.get("research_question")
            if not isinstance(question, str) or not question.strip():
                return
            key = " ".join(question.casefold().split())
            if key in rejected_questions:
                return
            rejected_questions.add(key)
            item = {
                "title": str(candidate.get("title") or "")[:220],
                "research_question": question[:520],
            }
            if isinstance(reason, str) and reason.strip():
                item["rejection_reason"] = reason.strip()[:520]
            rejected_directions.append(item)

        topic_record = self.stage_records.get(stage.get("id"), {})
        prior_attempts = topic_record.get("attempts", [])
        for prior_attempt in reversed(prior_attempts[-24:]
                                      if isinstance(prior_attempts, list) else []):
            trace = prior_attempt.get("candidate_attempt_trace", [])
            for rejected in reversed(trace if isinstance(trace, list) else []):
                if isinstance(rejected, dict):
                    remember_rejection(
                        rejected.get("selected_topic"),
                        rejected.get("rejection_reason") or rejected.get("error"),
                        rejected.get("status"),
                    )
        history_entries = self._topic_history_context().get("entries", [])
        for entry in reversed(history_entries if isinstance(history_entries, list) else []):
            candidate = dict(entry)
            candidate.setdefault("id", entry.get("topic_id"))
            remember_rejection(candidate, entry.get("rejection_reason"),
                               entry.get("history_status"))
        rejected_directions = rejected_directions[:8]
        specialist_feedback = []
        prior_reports = parent_context.get("specialist_reports") if isinstance(parent_context, dict) else None
        if isinstance(prior_reports, list):
            for report in prior_reports[:16]:
                if not isinstance(report, dict):
                    continue
                response = report.get("response") if isinstance(report.get("response"), dict) else {}
                specialist_feedback.append({
                    "assigned_role": report.get("assigned_role"),
                    "role_id": report.get("role_id"),
                    "decision": response.get("decision", report.get("decision")),
                    "summary": str(response.get("summary", report.get("summary", "")))[:2000],
                    "findings": [str(item)[:1200] for item in (response.get("findings", []) or [])[:8]],
                    "evidence_gaps": [str(item)[:1200] for item in (response.get("evidence_gaps", []) or [])[:8]],
                    "requested_actions": [str(item)[:1200] for item in (response.get("requested_actions", []) or [])[:8]],
                })
        verifier = parent_context.get("specialist_verifier") if isinstance(parent_context, dict) else None
        verifier_response = verifier.get("response") if isinstance(verifier, dict) else None
        if not isinstance(verifier_response, dict):
            verifier_response = {}
        verifier_repair = [str(item)[:1600] for item in (
            verifier_response.get("repair_scope") or verifier_response.get("critical_findings") or []
        )[:12] if str(item).strip()]
        refinement_feedback = None
        if verifier_repair or verifier_response.get("decision") == "hold":
            refinement_feedback = {
                "review_type": "specialist_verifier",
                "decision": verifier_response.get("decision"),
                "rationale": str(verifier_response.get("rationale", ""))[:4000],
                "required_changes": verifier_repair,
                "critical_findings": [str(item)[:1600] for item in (
                    verifier_response.get("critical_findings", []) or [])[:12]],
            }
        parent_evolution = (
            parent_context.get("topic_evolution")
            if isinstance(parent_context, dict) else None
        )
        parent_salvage = (
            parent_evolution.get("salvage")
            if isinstance(parent_evolution, dict) else None
        )
        # A structural pivot starts a new lineage. A successful salvage branch
        # carries its attempted IDs forward so the next continuation selects a
        # different repair axis instead of replaying the same one.
        attempted_salvage = []
        if (isinstance(parent_salvage, dict)
                and parent_salvage.get("mode") in {"salvage", "structural_pivot"}):
            attempted_salvage = list(parent_salvage.get("attempted_branch_ids", []))
        source_challenge = (
            parent_context.get("source_challenge")
            if isinstance(parent_context, dict) else None
        )
        feasibility_revalidation = (
            parent_context.get("runtime_feasibility_revalidation")
            if isinstance(parent_context, dict) else None
        )
        force_structural_pivot = (
            any(
                isinstance(item, dict)
                and item.get("require_frontier_seed_pivot") is True
                for item in requests
            )
            or verifier_response.get("require_frontier_seed_pivot") is True
            or (
                isinstance(source_challenge, dict)
                and source_challenge.get("prior_work_risk") == "high"
            )
            or (
                isinstance(feasibility_revalidation, dict)
                and feasibility_revalidation.get("status") == "required"
            )
        )
        salvage_plan = topic_salvage_plan(
            attempted_salvage,
            force_structural_pivot=force_structural_pivot,
        )
        focused_objective = next((
            item.get("objective") for item in requests
            if isinstance(item.get("objective"), str) and item["objective"].strip()
        ), None)
        parent_evidence = {
            "frontier_seed_plan": deepcopy(parent_context.get("frontier_seed_plan")),
            "recent_papers": [
                deepcopy(item) for item in parent_context.get("recent_papers", [])
                if isinstance(item, dict)
            ][:16],
            "candidate_prior_work": [
                deepcopy(item) for item in parent_context.get("candidate_prior_work", [])
                if isinstance(item, dict)
            ][:16],
        }
        return {
            "mode": "refinement",
            "cycle": self.continuation_cycles,
            "objective": focused_objective,
            "parent_topic_id": parent.get("id"),
            "parent_topic": deepcopy(parent),
            "parent_evidence": parent_evidence,
            "reason": "The literature and admission review did not support the current question as a sufficient journal study.",
            "work_orders": [{key: item.get(key) for key in (
                "id", "kind", "objective", "why", "success_condition", "evidence_needed")}
                            for item in requests],
            "rejected_directions": rejected_directions,
            "changed_dimensions": list((
                "mechanism", "data_regime", "comparison", "measurement", "theory",
                "research_form", "evidence_mode", "comparison_type",
            )),
            "survey_feedback": feedback,
            "specialist_feedback": specialist_feedback,
            "refinement_feedback": refinement_feedback,
            **({"response_contract_repair": response_contract_repair}
               if response_contract_repair is not None else {}),
            "salvage_plan": salvage_plan,
        }

    @staticmethod
    def _retain_topic_for_contract_repair(incumbent, refinement_context,
                                          specialist_reports=None):
        """Reuse an admitted topic when only its response envelope needs repair."""
        from scisaurus.runtime.research_program import build_research_program

        if not isinstance(incumbent, dict) or not isinstance(refinement_context, dict):
            raise ValidationError(
                "topic response-contract recovery requires an admitted incumbent")
        selected = incumbent.get("topic")
        parent = refinement_context.get("parent_topic")
        if not isinstance(selected, dict) or not isinstance(parent, dict):
            raise ValidationError(
                "topic response-contract recovery is missing the selected parent")
        if (selected.get("id") != parent.get("id")
                or selected.get("research_question") != parent.get("research_question")):
            raise ValidationError(
                "topic response-contract recovery cannot change the admitted research question")

        # Re-run deterministic admission on the incumbent before reusing it;
        # the failed model response is never treated as a scientific proposal.
        program = build_research_program(incumbent)
        retained = deepcopy(incumbent)
        incumbent_usage = retained.get("usage")
        incumbent_usage = deepcopy(incumbent_usage) if isinstance(incumbent_usage, dict) else {}
        retained["status"] = "completed"
        retained["research_program"] = program
        retained["usage"] = {
            "model_calls": 0,
            "input_tokens": 0,
            "output_tokens": 0,
            "cache_read_tokens": 0,
            "openalex_requests": 0,
            "retrieval_calls": 0,
        }
        retained["response_contract_recovery"] = {
            "mode": "retained_admitted_incumbent",
            "topic_id": selected["id"],
            "research_question": selected["research_question"],
            "validation_error": str(
                (refinement_context.get("response_contract_repair") or {}).get(
                    "validation_error", "")
            )[:2048],
            "incumbent_usage": incumbent_usage,
            "recovery_model_calls": 0,
        }
        if isinstance(specialist_reports, list):
            retained["specialist_reports"] = deepcopy(specialist_reports)
        return retained

    @staticmethod
    def _validate_refined_topic_result(result, refinement_context):
        """Keep a model-generated refinement inside its admitted phenomenon."""
        if not isinstance(refinement_context, dict):
            return
        parent = refinement_context.get("parent_topic")
        candidate = result.get("topic") if isinstance(result, dict) else None
        if not isinstance(parent, dict) or not isinstance(candidate, dict):
            return
        if refinement_context.get("mode") == "runtime_feasibility_revalidation":
            mutable_execution_fields = {
                "feasibility", "feasibility_plan", "resource_plan",
                "capability_requirements", "experiment_capability_id",
                "experiment_design",
            }
            scientific_parent = {
                key: value for key, value in parent.items()
                if key not in mutable_execution_fields
            }
            scientific_candidate = {
                key: value for key, value in candidate.items()
                if key not in mutable_execution_fields
            }
            if scientific_candidate != scientific_parent:
                changed = sorted(
                    key for key in set(scientific_candidate) | set(scientific_parent)
                    if scientific_candidate.get(key) != scientific_parent.get(key)
                )
                error = ValidationError(
                    "runtime-feasibility repair may update execution feasibility fields only; "
                    "it cannot change admitted research identity fields: "
                    + ", ".join(changed))
                error.failure_class = "model_contract"
                raise error
        salvage_plan = refinement_context.get("salvage_plan")
        try:
            validate_topic_refinement(
                parent, candidate,
                salvage_plan=salvage_plan if isinstance(salvage_plan, dict) else None,
                salvage_anchor=parent,
            )
        except ValidationError as exc:
            reason = f"Composer rejected off-lineage topic refinement: {exc}"
            error = ValidationError(reason)
            error.topic_intake_recoverable = True
            error.topic_retry_reason = "parent_identity_violation"
            trace = result.get("candidate_attempt_trace") if isinstance(result, dict) else None
            error.candidate_attempt_trace = (
                deepcopy(trace[-8:]) if isinstance(trace, list) else []
            )
            error.rejected_topic_history = [{
                "topic_id": candidate.get("id"),
                "title": candidate.get("title"),
                "domain": candidate.get("domain"),
                "research_question": candidate.get("research_question"),
                "rejection_type": "refinement",
                "rejection_reason": reason[:2048],
            }]
            raise error from exc

    def _carry_provisional_verifier_challenge(self, context, verifier_result):
        """Route a survey-stage challenge forward without declaring it solved.

        A provisional topic has already passed deterministic schema, source,
        feasibility, and minimum-substance checks. The next action exists to
        investigate unresolved novelty, provenance, comparator, threshold,
        and mechanism questions. An adversary's hold on those questions is
        therefore evidence for the survey brief, not a reason to demand the
        survey's result before the survey can start. Experiment admission
        remains independently blocked by the later literature verdict.
        """
        if (not isinstance(context, dict)
                or context.get("admission_state") != "provisional_for_survey"
                or not isinstance(verifier_result, dict)):
            return False
        response = verifier_result.get("response")
        if not isinstance(response, dict) or response.get("decision") != "hold":
            return False
        existing = [str(item).strip() for item in context.get(
            "maturity_open_requirements", []) if str(item).strip()]
        requested = response.get("repair_scope")
        if not isinstance(requested, list) or not requested:
            requested = response.get("critical_findings", [])
        merged = []
        seen = set()
        for item in [*existing, *(requested if isinstance(requested, list) else [])]:
            text = str(item).strip()
            key = text.casefold()
            if not text or key in seen:
                continue
            seen.add(key)
            merged.append(text[:1600])
            if len(merged) >= 16:
                break
        requirement_scope = self._topic_maturity_requirement_scope(
            context.get("topic"), {**context, "maturity_open_requirements": merged})
        context["maturity_open_requirements"] = requirement_scope["active"]
        if requirement_scope["out_of_scope"]:
            context["maturity_requirement_dispositions"] = [
                {
                    "requirement": item,
                    "disposition": "empirical_validation_limit",
                    "reason": (
                        "The refined self-contained estimand does not consume observed rows; "
                        "report this as an empirical validation boundary."
                    ),
                }
                for item in requirement_scope["out_of_scope"][:8]
            ]
        response["control_disposition"] = "carried_to_literature_survey"
        verifier_result["response"] = response
        verifier_result["gate_disposition"] = "carried_to_literature_survey"
        context["provisional_adversarial_challenge"] = {
            "decision": "hold",
            "control_disposition": "carried_to_literature_survey",
            "rationale": str(response.get("rationale", ""))[:4000],
            "critical_findings": [str(item)[:1600] for item in (
                response.get("critical_findings", []) or [])[:12]],
            "repair_scope": [str(item)[:1600] for item in (
                response.get("repair_scope", []) or [])[:12]],
        }
        context["specialist_verifier"] = deepcopy(verifier_result)
        return True

    def _gate_survey_work_orders(self, stage, result):
        if (stage.get("kind") != "survey" or not isinstance(result, dict)
                or result.get("status") not in {"completed", "accepted"}):
            return result
        outstanding = [request for request in self._requests_for_stage(stage)
                       if request.get("kind") == "literature_expansion"
                       and not self._survey_request_was_fulfilled(stage["project_dir"], result, request)]
        if outstanding:
            result = deepcopy(result)
            result.update({"status": "research_expansion_required", "preserve_work_orders": True,
                           "review_status": "survey_follow_up_unresolved",
                           "research_requests": deepcopy(outstanding),
                           "research_expansion_requests": deepcopy(outstanding)})
        return result

    def _gate_free_topic_survey(self, result, *, stage=None):
        """Hold a free-topic mission until its question survives literature review.

        A bounded survey can be faithful while still failing to establish an
        experiment-worthy distinction.  Treat that outcome as a scientific
        redesign request instead of allowing the Composer to pass a thin
        question directly to the executable experiment.
        """
        topic_stage = self._topic_stage_for_survey(stage)
        if topic_stage is None or not isinstance(result, dict):
            return result
        if result.get("status") not in {"completed", "accepted"}:
            return result
        if stage is not None:
            obligation = self._topic_review_obligation(stage)
            if obligation is not None and not self._topic_review_obligation_is_closed(stage, result, obligation):
                held = deepcopy(result)
                held.update(status="research_expansion_required", review_status="topic_review_obligations_unresolved",
                            preserve_work_orders=True, topic_review_obligation=deepcopy(obligation))
                for key in ("research_requests", "research_expansion_requests"):
                    held[key] = [*deepcopy([item for item in result.get(key, [])
                                           if item.get("id") != obligation["id"]]), deepcopy(obligation)]
                return held
        state = result.get("gap_state")
        if state == "eligible_for_experiment":
            topic_context = self.context.get(topic_stage["id"], {})
            if (isinstance(topic_context, dict)
                    and topic_context.get("admission_state") == "provisional_for_survey"):
                requirement_scope = self._topic_maturity_requirement_scope(
                    topic_context.get("topic"), topic_context)
                supported = deepcopy(result)
                supported["topic_admission"] = "provisional_supported_for_experiment"
                supported["carried_maturity_requirements"] = deepcopy(
                    requirement_scope["active"])
                supported["empirical_validation_limits"] = deepcopy(
                    requirement_scope["out_of_scope"])
                return supported
            return result
        if state not in {"refuted_by_prior_work", "insufficient_evidence"}:
            return result
        if (self._allows_provisional_progress()
                and state == "insufficient_evidence"
                and result.get("survey_current") is True
                and result.get("assessment_current") is True):
            pilot = deepcopy(result)
            pilot["topic_admission"] = "exploratory_pilot"
            topic_context = self.context.get(topic_stage["id"], {})
            requirement_scope = self._topic_maturity_requirement_scope(
                topic_context.get("topic") if isinstance(topic_context, dict) else None,
                topic_context,
            )
            pilot["carried_maturity_requirements"] = deepcopy(
                requirement_scope["active"])
            pilot["empirical_validation_limits"] = deepcopy(
                requirement_scope["out_of_scope"])
            pilot["carried_maturity_requirements"].append(
                "Literature novelty remains unresolved; exploratory results cannot establish an original contribution.")
            return pilot
        gated = deepcopy(result)
        requests = [deepcopy(item) for item in result.get("research_expansion_requests", [])
                    if isinstance(item, dict)]
        known = {item.get("id") for item in requests if isinstance(item.get("id"), str)}

        def add(item):
            if item["id"] not in known:
                requests.append(item)
                known.add(item["id"])

        if state == "insufficient_evidence":
            # The first insufficient survey is an evidence problem, not a
            # scientific-direction problem.  Give the survey one scoped
            # expansion pass before asking the topic stage to pivot.  The
            # previous Composer result is durable context, so a resumed or
            # continued run can distinguish that first pass from a repeated
            # failure without relying on an in-memory counter.
            prior_survey = self._survey_context_for_topic(
                topic_stage)
            expanded_before = (
                isinstance(prior_survey, dict)
                and prior_survey.get("gap_state") == "insufficient_evidence"
                and prior_survey.get("topic_admission") in {
                    "expand_literature_before_refine", "refine_before_experiment"
                })
            add({
                "id": "topic-literature-expansion",
                "kind": "literature_expansion",
                "owner": "research.intelligence",
                "objective": "Expand the scholarly search with exact terminology, citation chaining, and verified full text for the selected question before making an admission decision.",
                "why": "The recorded survey does not yet provide enough comparable evidence to judge whether the question distinguishes unresolved work.",
                "success_condition": "A current survey and gap assessment answers the selected question or identifies the exact unresolved boundary, comparator, observable, or claim scope that needs refinement, while retaining the parent phenomenon.",
                "evidence_needed": "Relevant primary studies, identity reconciliation, full-text source spans, and a current gap assessment.",
            })
            if expanded_before:
                add({
                    "id": f"topic-refinement-{state}",
                    "kind": "topic_refinement",
                    "owner": "research.intelligence",
                    "objective": "Keep the parent phenomenon and refine only the unsupported edge: sharpen the mechanism, comparator, observable, data regime, or claim boundary using the expanded survey. Do not replace the subject with an unrelated topic.",
                    "why": "The expanded survey remains inconclusive about one part of the current question; repair that boundary before deciding what the evidence can support.",
                    "success_condition": "The refined question preserves the parent phenomenon, makes a falsifiable comparison or narrower claim, and is re-surveyed with terms that directly test that boundary.",
                    "evidence_needed": "The parent question and phenomenon, expanded survey map, exact source spans, gap assessment, counter-search findings, and the specific changed comparison, measurement, or claim scope.",
                })
        elif state == "refuted_by_prior_work":
            add({
                "id": f"topic-refinement-{state}",
                "kind": "topic_refinement",
                "owner": "research.intelligence",
                "objective": "Preserve the parent phenomenon and use the refuting studies to narrow or strengthen the question around an unresolved regime, comparator, observable, or boundary. Do not pivot to an unrelated subject.",
                "why": "The cited literature answers the current formulation; it does not by itself establish that every adjacent boundary of the parent phenomenon is settled.",
                "success_condition": "The revised question retains the parent phenomenon, distinguishes its unresolved boundary from the established result, and survives a targeted counter-search; if no distinct claim remains, record that limit instead of inventing novelty.",
                "evidence_needed": "The parent phenomenon and question, exact refuting source spans, the boundary they establish, the remaining comparison or measurement, survey map, and counter-search findings.",
            })
        gated["status"] = "research_expansion_required"
        gated["topic_admission"] = (
            "refine_before_experiment"
            if any(self._is_topic_pivot_request(item) for item in requests)
            else "expand_literature_before_refine"
        )
        gated["research_expansion_requests"] = requests
        return gated

    def _address_for_role(self, role):
        """Resolve a role through the live project charter.

        The functional role identifies the owning department; the live charter
        supplies the concrete chief appointment.  Command roles are the only
        addresses outside a project department.
        """
        if isinstance(role, str):
            department = role.split(".", 1)[0]
            if department in self.departments.charters:
                try:
                    assignment = self.departments.resolve_address(role)
                    return {"dept": assignment["department"], "agent": assignment["agent"]}
                except ValidationError:
                    return deepcopy(COMMAND_ADDRESSES["arbiter"])
            assignment = self.departments.role_for_internal_role(role)
            if assignment is not None:
                return {"dept": assignment["department"], "agent": assignment["agent"]}
        return deepcopy(COMMAND_ADDRESSES.get(role, COMMAND_ADDRESSES["arbiter"]))

    @staticmethod
    def _topic_program(topic_context):
        """Return the validated program attached to a topic context, if any."""
        if not isinstance(topic_context, dict):
            return None
        program = topic_context.get("research_program")
        if not isinstance(program, dict):
            return None
        from scisaurus.runtime.research_program import validate_research_program
        validate_research_program(program)
        return program

    @classmethod
    def _topic_program_projection(cls, topic_context, *, max_alternatives=8):
        program = cls._topic_program(topic_context)
        if program is None:
            return None
        from scisaurus.runtime.research_program import project_research_program
        return project_research_program(program, max_alternatives=max_alternatives)

    def _attach_topic_program(self, packet):
        """Attach the full, validated program to a scientific packet in memory."""
        if not isinstance(packet, dict):
            return packet
        topic_context = next((value for value in self.context.values()
                              if isinstance(value, dict)
                              and value.get("kind") == "topic_discovery"
                              and isinstance(value.get("topic"), dict)), None)
        program = self._topic_program(topic_context)
        if program is not None:
            packet["research_program"] = deepcopy(program)
        return packet

    @staticmethod
    def _prior_stage_project(stage_id, context):
        value = context.get(stage_id, {}) if isinstance(context, dict) else {}
        path = value.get("project_dir") if isinstance(value, dict) else None
        return Path(path).resolve() if isinstance(path, str) and Path(path).is_absolute() else None

    def _augment_full_text_routes(self, config, source_project):
        """Add OA locations from the incumbent survey for a full-text continuation."""
        if not source_project:
            return
        works_path = source_project / "output" / "works.json"
        try:
            works = json.loads(works_path.read_text())
        except (OSError, ValueError):
            return
        failed_ids = set()
        coverage_path = source_project / "output" / "coverage.json"
        try:
            coverage = json.loads(coverage_path.read_text())
            failed_ids = {
                item.get("work_id") for item in coverage.get("access_and_limit_gaps", [])
                if isinstance(item, dict) and item.get("kind") == "full_text_failure"
            }
        except (OSError, ValueError, AttributeError):
            pass
        survey = config.get("survey") if isinstance(config, dict) else None
        if not isinstance(survey, dict) or not isinstance(survey.get("full_text_sources"), list):
            return
        existing = {item.get("work_id") for item in survey["full_text_sources"] if isinstance(item, dict)}
        for work in works:
            if (not isinstance(work, dict) or work.get("work_id") in existing
                    or work.get("work_id") in failed_ids):
                continue
            url = preferred_full_text_url(work.get("locations"))
            if not url:
                url = work.get("source_url")
            if not url:
                doi = work.get("doi")
                url = "https://doi.org/" + doi if isinstance(doi, str) and doi.strip() else None
            if not url:
                continue
            survey["full_text_sources"].append({
                "work_id": work["work_id"], "title": work["title"], "url": url,
                "section_markers": ["Introduction"], "route_policy": "auto",
            })
            existing.add(work["work_id"])

    def _apply_topic_to_survey_config(self, stage, config):
        """Project the selected free-topic question into its survey intake.

        A free-topic workflow should be runnable without hand-written binding
        entries for the common question/query fields.  Explicit bindings still
        run afterward and therefore remain authoritative for deliberate
        overrides.
        """
        topic_stage_ids = {item["id"] for item in self.workflow["stages"]
                           if item["kind"] == "topic_discovery"}
        pending = list(stage.get("depends_on", []))
        upstream = set()
        by_id = {item["id"]: item for item in self.workflow["stages"]}
        while pending:
            dependency = pending.pop()
            if dependency in upstream:
                continue
            upstream.add(dependency)
            pending.extend(by_id.get(dependency, {}).get("depends_on", []))
        if not (upstream & topic_stage_ids):
            return config
        topic_context = next((value for value in self.context.values()
                              if isinstance(value, dict)
                              and value.get("kind") == "topic_discovery"
                              and isinstance(value.get("topic"), dict)), None)
        if topic_context is None:
            return config
        survey = config.get("survey") if isinstance(config, dict) else None
        topic = topic_context["topic"]
        if not isinstance(survey, dict):
            return config
        # Composer owns adaptive source resolution for free-topic surveys.
        # Keep explicit exact routes pinned, while upgrading legacy template
        # routes to the policy needed to resolve registered open-access PDFs.
        for source in survey.get("full_text_sources", []):
            if isinstance(source, dict):
                source.setdefault("route_policy", "auto")
        # A free-topic novelty decision requires citation-graph evidence.  A
        # Composer-admitted provider recovery is the one explicit exception:
        # it keeps the degraded Crossref route visible in the survey result
        # instead of letting the topic binding silently switch it back off.
        provider_fallback = self.context.get(stage["id"], {}).get("provider_fallback")
        if (isinstance(provider_fallback, dict)
                and provider_fallback.get("mode") == "crossref_metadata"):
            survey["bibliography_fallback"] = "crossref_metadata"
        else:
            survey["bibliography_fallback"] = "disabled"
        # A catalog-backed stage is a new project identity.  Reusing the
        # template's project or capability IDs would leak the previous
        # experiment into the survey ledger and can collide with its reserved
        # verification capacity.  Preserve the descriptor's worker setting;
        # the configured capacity must still leave one independent verification
        # slot required by the survey contract.
        config["project_id"] = str(Path(stage["project_dir"]).resolve())
        limits = config.setdefault("limits", {})
        if type(limits.get("concurrent_calls")) is int and limits["concurrent_calls"] < 2:
            limits["concurrent_calls"] = 2
        if "worker_concurrency" not in limits and type(limits.get("concurrent_calls")) is int:
            limits["worker_concurrency"] = limits["concurrent_calls"] - 1
        if isinstance(topic.get("id"), str):
            topic_key = re.sub(r"[^a-z0-9_-]+", "-", topic["id"].casefold()).strip("-")[:48]
            if topic_key:
                survey["id"] = f"topic-{topic_key}-literature"[:64]
                for capability_key in ("bibliography", "identity", "full_text"):
                    capability = survey.get(capability_key)
                    if isinstance(capability, dict) and isinstance(capability.get("id"), str):
                        capability["id"] = f"topic-{topic_key}-{capability_key}"[:64]
        # A configured hypothesis belongs to its declared question. Topic
        # motivation is not a nomination; new questions are nominated from
        # the accepted literature map by the gap-proposer.
        if survey.get("question") != topic["research_question"]:
            survey["proposed_gap"] = None
        survey["question"] = topic["research_question"]
        # The discovery sampler is intentionally broad: it gives the topic
        # selector a current landscape, but those records are not evidence
        # for the selected question.  Carrying their IDs into the survey
        # would silently mix unrelated papers into the new study.  A
        # catalog-backed mission therefore starts from the selected queries;
        # the survey provider, planner, and expansion rounds build the seed
        # set from question-relevant records.  Legacy non-catalog workflows
        # retain their explicit seed IDs.
        if self.workflow.get("experiment_catalog"):
            survey["seed_work_ids"] = []
        else:
            recent = topic_context.get("recent_papers", [])
            seed_work_ids = [item.get("work_id") for item in recent
                             if isinstance(item, dict) and re.fullmatch(r"W\d+", str(item.get("work_id", "")))]
            survey["seed_work_ids"] = list(dict.fromkeys(seed_work_ids))[:max(0, survey.get("search", {}).get("max_works", 0) - survey.get("search", {}).get("challenge_reserve", 0))]
        if self.workflow.get("experiment_catalog"):
            # Explicit full-text routes are part of a fixed study template.
            # Let the current survey discover open locations for the selected
            # question instead of fetching the previous topic's URLs.
            survey["full_text_sources"] = []
        queries = topic.get("search_queries")
        if isinstance(queries, list) and queries:
            unique_queries = self._topic_search_queries(topic)
            # The survey's configured planner width is the explicit intake
            # budget.  A topic may propose more discovery terms, but silently
            # dispatching all of them would defeat provider-aware quotas.
            width = (survey.get("search", {}) or {}).get("queries_per_role")
            if type(width) is int and width > 0:
                unique_queries = unique_queries[:width]
            survey["seed_queries"] = unique_queries
        # Provider readiness is an operational check, but its representative
        # workload is still part of the live survey input.  A free-topic
        # stage must not probe a descriptor's historical paper (the template
        # used to probe an Attention paper even when the selected question
        # concerned another field).  Use the selected question's first search
        # family so a successful probe also proves that the actual route can
        # serve this mission.
        probe_query = next(
            (item for item in survey.get("seed_queries", [])
             if isinstance(item, str) and item.strip()),
            topic.get("research_question", "scholarly research"),
        )
        bibliography = survey.get("bibliography")
        if isinstance(bibliography, dict) and bibliography.get("adapter") == "openalex":
            bibliography["representative"] = {
                "operation": "search", "query": str(probe_query)[:2048],
                "work_id": None, "limit": 1, "cursor": None,
            }
        identity = survey.get("identity")
        if isinstance(identity, dict) and identity.get("adapter") == "crossref":
            identity["representative"] = {"query": str(probe_query)[:2048], "limit": 1}
        if isinstance(config.get("objective"), str):
            config["objective"] = (
                f"Investigate the selected question with a bounded scholarly survey: "
                f"{topic['research_question']}")
        if isinstance(config.get("supplied_context"), str):
            program_projection = self._topic_program_projection(topic_context, max_alternatives=8)
            program_context = (
                "\nResearch program (provisional; conditional outcomes are decision rules, not results):\n"
                + json.dumps(program_projection, ensure_ascii=False, sort_keys=True)
                if program_projection is not None else ""
            )
            config["supplied_context"] = (
                "A catalog-backed free-topic intake selected this direction. "
                "Rebuild the literature map around the current question and preserve only evidence "
                "that is relevant to the selected study.\n" + topic["research_question"]
                + program_context)
            obligation = self._topic_review_obligation(stage)
            if obligation is not None:
                config["supplied_context"] += "\nOwned independent topic review obligations:\n" + json.dumps(
                    obligation["attempt_lineage"], ensure_ascii=False, sort_keys=True)
        return config

    @staticmethod
    def _topic_search_queries(topic):
        """Return the selected topic's bounded search families unchanged.

        Search planning already supplies independent terminology families.
        Earlier code manufactured an exact query by splitting a hyphenated
        word from the research question (for example ``friction-triggered``
        became ``"friction triggered"``).  That synthetic query was not a
        declared search family and regularly admitted unrelated records before
        the substantive queries ran.  Exact phrases remain available when a
        planner explicitly declares them.
        """
        raw = [item.strip() for item in topic.get("search_queries", [])
               if isinstance(item, str) and item.strip()]
        return list(dict.fromkeys(raw))

    @staticmethod
    def _continuation_capability_id(topic, cycle):
        """Derive a new registry identity for a substantive experiment pass."""
        base = topic.get("id") if isinstance(topic, dict) else None
        base = re.sub(r"[^a-z0-9_-]+", "-", str(base or "topic").casefold()).strip("-")
        if not base or not re.match(r"[a-z]", base):
            base = f"topic-{base}" if base else "topic"
        suffix = f"-cycle-{cycle}"
        return f"{base[:64 - len(suffix)]}{suffix}"

    @staticmethod
    def _capability_repair_projection(value, *, depth=0, max_depth=6,
                                      max_keys=48, max_items=16, max_text=2600):
        """Bound repair evidence before it enters a specialist or author prompt."""
        if depth >= max_depth and isinstance(value, (dict, list)):
            return "[truncated]"
        if isinstance(value, dict):
            output = {}
            for index, (key, item) in enumerate(value.items()):
                if index >= max_keys:
                    output["[truncated_keys]"] = True
                    break
                lowered = str(key).casefold()
                if any(part in lowered for part in (
                        "api_key", "apikey", "authorization", "password", "secret", "token")):
                    output[str(key)] = "[redacted]"
                    continue
                if str(key) == "source_chunks" and isinstance(item, list):
                    output[str(key)] = [
                        redact_sensitive_text(chunk)
                        for chunk in item[:max_items]
                        if isinstance(chunk, str) and len(chunk) <= 7000
                    ]
                    if len(item) > max_items:
                        output["[truncated_items]"] = True
                    continue
                output[str(key)] = ComposerRunner._capability_repair_projection(
                    item, depth=depth + 1, max_depth=max_depth,
                    max_keys=max_keys, max_items=max_items, max_text=max_text)
            return output
        if isinstance(value, list):
            output = [ComposerRunner._capability_repair_projection(
                item, depth=depth + 1, max_depth=max_depth,
                max_keys=max_keys, max_items=max_items, max_text=max_text)
                      for item in value[:max_items]]
            if len(value) > max_items:
                output.append("[truncated_items]")
            return output
        if isinstance(value, str):
            value = redact_sensitive_text(value)
            return value if len(value) <= max_text else value[:max_text] + "...[truncated]"
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        return redact_sensitive_text(str(value))[:max_text]

    @staticmethod
    def _capability_authoring_repair_projection(value):
        """Keep the source-level repair evidence without replaying the whole panel.

        The methods panel stores a durable packet for auditability.  Passing that
        packet wholesale to the program author duplicated the failure dossier,
        program snapshot, prior foundry response, and every specialist report in
        one prompt.  This projection retains one exact source pair and the
        decision-bearing findings while dropping duplicated transport envelopes.
        """
        context = value if isinstance(value, dict) else {}
        packet = context.get("packet") if isinstance(context.get("packet"), dict) else {}
        prior_work = packet.get("prior_foundry_work")
        prior_work = prior_work if isinstance(prior_work, dict) else {}
        last_attempt = prior_work.get("last_attempt")
        last_attempt = last_attempt if isinstance(last_attempt, dict) else {}
        snapshot = packet.get("program_snapshot")
        snapshot = snapshot if isinstance(snapshot, list) else []
        prompt_source_integrity = {}

        def clip(item, limit):
            if not isinstance(item, str):
                return item
            return item if len(item) <= limit else item[:limit] + "...[truncated]"

        def compact_list(items, limit, text_limit=1200):
            if not isinstance(items, list):
                return []
            output = []
            for item in items[:limit]:
                if isinstance(item, dict):
                    output.append({str(key): clip(item.get(key), text_limit)
                                   for key in item if key in {
                                       "id", "kind", "source", "role", "role_id",
                                       "assigned_role", "operation", "target",
                                       "instruction", "acceptance_check", "text",
                                       "failure_dossier_ref", "failure_input_sha256",
                                       "recovery_mode", "repair_priority",
                                   }})
                else:
                    output.append(clip(item, text_limit))
            if len(items) > limit:
                output.append("[truncated_items]")
            return output

        def source_from_snapshot(name):
            for item in snapshot:
                if not isinstance(item, dict):
                    continue
                path = str(item.get("path", "")).casefold()
                if path.endswith(f"/{name}.py") or path.endswith(f"\\{name}.py"):
                    return item.get("source")
            return None

        def source(name):
            candidate = last_attempt.get(f"{name}_source")
            if not isinstance(candidate, str) or not candidate:
                candidate = source_from_snapshot(name)
            if not isinstance(candidate, str):
                return None
            safe_source = redact_sensitive_text(candidate)
            bounded_source = clip(safe_source, CAPABILITY_REPAIR_SOURCE_CHARS)
            integrity = last_attempt.get("source_integrity")
            record = integrity.get(name) if isinstance(integrity, dict) else None
            record = record if isinstance(record, dict) else {}
            file_records = last_attempt.get("source_files")
            file_record = (file_records.get(name)
                           if isinstance(file_records, dict) else None)
            file_record = file_record if isinstance(file_record, dict) else {}
            expected_sha256 = record.get("sha256")
            prompt_sha256 = hashlib.sha256(bounded_source.encode("utf-8")).hexdigest()
            prompt_source_integrity[name] = {
                "expected_source_sha256": expected_sha256,
                "prompt_source_sha256": prompt_sha256,
                "matches_expected": (
                    prompt_sha256 == expected_sha256
                    if isinstance(expected_sha256, str) else None
                ),
                "redaction_applied": (
                    safe_source != candidate or file_record.get("redaction_applied") is True
                ),
                "source_truncated": (
                    len(candidate) > CAPABILITY_REPAIR_SOURCE_CHARS
                    or record.get("truncated") is True
                ),
            }
            return bounded_source

        recovery = packet.get("failure_recovery")
        recovery = recovery if isinstance(recovery, dict) else {}
        recovery_projection = {
            "failure_class": recovery.get("failure_class"),
            "recovery_mode": recovery.get("recovery_mode"),
            "requires_capability_repair": recovery.get("requires_capability_repair"),
            "dossier_ref": recovery.get("dossier_ref"),
            "input_sha256": recovery.get("input_sha256"),
            "acceptance_checks": compact_list(recovery.get("acceptance_checks"), 8, 900),
            "repair_commands": compact_list(recovery.get("repair_commands"), 8, 1100),
            "review_directives": compact_list(recovery.get("review_directives"), 12, 1100),
        }
        selected_plan = context.get("repair_plan")
        has_adjudicated_plan = (
            context.get("schema_version") in CAPABILITY_REPAIR_PLAN_SCHEMA_VERSIONS
            and context.get("decision") == "repair"
            and isinstance(selected_plan, dict)
        )
        panel_reports = context.get("reports")
        if not isinstance(panel_reports, list):
            panel_reports = packet.get("prior_specialist_reviews")
        panel_reports = panel_reports if isinstance(panel_reports, list) else []
        reports = []
        for report in panel_reports[:8]:
            if not isinstance(report, dict):
                continue
            reports.append({
                key: clip(report.get(key), 1400) for key in (
                    "role_id", "assigned_role", "status", "decision", "summary",
                    "artifact_ref") if key in report
            } | {
                "findings": compact_list(report.get("findings"), 4, 900),
                "requested_actions": compact_list(report.get("requested_actions"), 4, 900),
            })

        return {
            "schema_version": context.get("schema_version") or "capability-repair-panel-1",
            "input_sha256": context.get("input_sha256") or packet.get("input_sha256"),
            "review_input_sha256": context.get("review_input_sha256"),
            "evidence_priority": (
                "Immutable observations, source, and deterministic validation are the evidence of "
                "record. Methods-panel findings and requested changes are hypotheses to test, not "
                "verified causes or mandatory edits; reconcile them against the deterministic failure."
            ),
            "topic": ComposerRunner._capability_repair_projection(
                packet.get("topic"), max_depth=4, max_keys=24, max_items=8, max_text=1600),
            "failure": ComposerRunner._capability_repair_projection(
                packet.get("failure"), max_depth=4, max_keys=20, max_items=8, max_text=1600),
            "failure_recovery": recovery_projection,
            "failure_lineage": deepcopy(packet.get("failure_lineage", {})),
            "repair_subject_lineage": deepcopy(packet.get(
                "repair_subject_lineage", packet.get("failure_lineage", {}))),
            "plan_review_failure": ComposerRunner._capability_repair_projection(
                packet.get("plan_review_failure", {}), max_depth=3,
                max_keys=12, max_items=8, max_text=1400),
            "failed_program": {
                "source_manifest": [{key: item.get(key) for key in (
                    "path", "sha256", "size_bytes", "source_truncated") if key in item}
                                    for item in snapshot[:8] if isinstance(item, dict)],
                "executor_source": source("executor"),
                "validator_source": source("validator"),
                "source_integrity": deepcopy(last_attempt.get("source_integrity", {})),
                "prompt_source_integrity": prompt_source_integrity,
                "historical_execution_sources": ComposerRunner._capability_repair_projection(
                    packet.get("unresolved_attempt_sources", []), max_depth=4,
                    max_keys=24, max_items=16, max_text=7000),
            },
            "prior_foundry_work": {
                "status": prior_work.get("status"),
                "attempts": prior_work.get("attempts"),
                "cache_ref": prior_work.get("cache_ref"),
                "repair_gate_counts": prior_work.get("repair_gate_counts"),
                "feedback": clip(prior_work.get("feedback"), 7000),
                "validation_context": ComposerRunner._capability_repair_projection(
                    prior_work.get("validation_context"), max_depth=4, max_keys=20,
                    max_items=8, max_text=1400),
                "validation_feedback": ComposerRunner._capability_repair_projection(
                    prior_work.get("validation_feedback"), max_depth=4, max_keys=20,
                    max_items=8, max_text=1600),
                "experiment_intent": ComposerRunner._capability_repair_projection(
                    last_attempt.get("experiment_intent"), max_depth=4, max_keys=24,
                    max_items=8, max_text=1600),
            },
            "observed_result": ComposerRunner._capability_repair_projection(
                packet.get("observed_result"), max_depth=4, max_keys=24, max_items=8, max_text=1600),
            "failure_observed_result": ComposerRunner._capability_repair_projection(
                packet.get("failure_observed_result"), max_depth=4, max_keys=24, max_items=8, max_text=1600),
            "prior_specialist_reviews": reports,
            "prior_verifier": ComposerRunner._capability_repair_projection(
                packet.get("prior_verifier"), max_depth=4, max_keys=20, max_items=8, max_text=1400),
            "decision": context.get("decision"),
            "repair_plan": _preserve_response_value(selected_plan)
            if has_adjudicated_plan else None,
            "repair_plan_sha256": hashlib.sha256(canonical_bytes(
                _preserve_response_value(selected_plan))).hexdigest()
            if has_adjudicated_plan else None,
            "diagnostic_hypotheses": compact_list(
                [] if has_adjudicated_plan
                else context.get("diagnostic_hypotheses") or context.get("root_causes"), 12, 1400),
            "proposed_changes": compact_list(
                [] if has_adjudicated_plan else
                context.get("proposed_changes") or context.get("required_changes"), 12, 1400),
            "acceptance_checks": compact_list(
                [] if has_adjudicated_plan
                else context.get("acceptance_checks"), 8, 900),
            "repair_commands": compact_list(context.get("repair_commands"), 8, 1100),
            "verifier": ComposerRunner._capability_repair_projection(
                context.get("verifier"), max_depth=4, max_keys=20, max_items=8, max_text=1400),
            "repair_contract": ComposerRunner._capability_repair_projection(
                packet.get("repair_contract"), max_depth=4, max_keys=20, max_items=8, max_text=1400),
        }

    @staticmethod
    def _capability_authoring_follow_up_projection(requests, *, repair_context=None):
        """Project repair requests while keeping reviewer hypotheses distinct from facts."""
        repair_context = repair_context if isinstance(repair_context, dict) else {}
        adjudicated_plan = repair_context.get("repair_plan")
        adjudicated = (
            repair_context.get("schema_version") in CAPABILITY_REPAIR_PLAN_SCHEMA_VERSIONS
            and repair_context.get("decision") == "repair"
            and isinstance(adjudicated_plan, dict)
        )
        if (repair_context.get("schema_version") in CAPABILITY_REPAIR_PLAN_SCHEMA_VERSIONS
                and not adjudicated):
            return [{
                key: deepcopy(item.get(key)) for key in (
                    "id", "kind", "target_stage_id", "target_stage_kind", "attempt_lineage",
                ) if key in item
            } | {
                "objective": (
                    "Do not generate or execute a replacement capability: the Methods lead's "
                    "pre-execution repair plan was not independently admitted. Preserve the current "
                    "topic and failure dossier, and route the exact verifier objection or missing "
                    "evidence to a scoped Methods or Literature task."
                ),
                "repair_panel_decision": repair_context.get("decision"),
                "repair_panel_reason": str(repair_context.get("plan_validation_error") or "")[:1400],
            } for item in requests if isinstance(item, dict)]

        repair_hypotheses = repair_context.get("diagnostic_hypotheses")
        if adjudicated:
            root = adjudicated_plan.get("root_cause")
            root = root if isinstance(root, dict) else {}
            repair_hypotheses = [root.get("statement", "")]
        if not isinstance(repair_hypotheses, list):
            repair_hypotheses = repair_context.get("root_causes", [])
        repair_hypotheses = [item[:1400] for item in repair_hypotheses[:8]
                             if isinstance(item, str) and item.strip()] \
            if isinstance(repair_hypotheses, list) else []
        proposed_changes = (adjudicated_plan.get("required_changes", [])
                            if adjudicated else repair_context.get("proposed_changes"))
        if not isinstance(proposed_changes, list):
            proposed_changes = repair_context.get("required_changes", [])
        proposed_changes = [item[:1400] for item in proposed_changes[:8]
                            if isinstance(item, str) and item.strip()] \
            if isinstance(proposed_changes, list) else []
        review_evidence = list(dict.fromkeys([
            *(f"Adjudicated Methods root cause: {item}" if adjudicated
              else f"Unverified diagnosis hypothesis: {item}"
              for item in repair_hypotheses),
            *(
                f"Adjudicated Methods change: {item.get('target')}: {item.get('instruction')} "
                f"(basis: {item.get('scientific_basis')})"
                if adjudicated and isinstance(item, dict)
                else f"Unverified proposed change: {item}"
                for item in proposed_changes
            ),
        ]))[:12]
        output = []
        for item in requests if isinstance(requests, list) else []:
            if not isinstance(item, dict):
                continue
            if isinstance(item.get("attempt_lineage"), dict) and isinstance(item["attempt_lineage"].get("deferred_obligation"), dict):
                output.append(_preserve_response_value(item))
                continue
            entry = {
                key: (item.get(key)[:2400] if isinstance(item.get(key), str)
                      else item.get(key)) for key in (
                    "kind", "objective", "why", "success_condition", "evidence_needed",
                    "failure_dossier_ref", "failure_input_sha256", "recovery_mode",
                    "repair_policy_revision",
                    "target_stage_id", "target_stage_kind", "repair_priority",
                    "experiment_repair_plan", "repair_strategy", "attempt_lineage",
                ) if key in item
            }
            for key, limit, count in (
                    ("repair_commands", 1100, 8),
                    ("acceptance_checks", 900, 8),
                    ("review_directives", 1100, 12)):
                if key in item:
                    value = item.get(key)
                    if isinstance(value, list):
                        if key == "acceptance_checks":
                            entry[key] = _preserve_response_value(value)
                            continue
                        compacted = []
                        for child in value[:count]:
                            if isinstance(child, dict):
                                compacted.append({str(name): (
                                    child.get(name) if not isinstance(child.get(name), str)
                                    else child.get(name)[:limit]) for name in child
                                    if name in {"id", "kind", "source", "operation", "target",
                                                "instruction", "acceptance_check", "text"}})
                            elif isinstance(child, str):
                                compacted.append(child[:limit])
                        entry[key] = compacted
            if isinstance(item.get("model_diagnostics"), dict):
                entry["model_diagnostics"] = ComposerRunner._capability_repair_projection(
                    item["model_diagnostics"], max_depth=3, max_keys=12, max_items=4, max_text=800)
            if (review_evidence
                    and (item.get("target_stage_kind") == "experiment"
                         or item.get("kind") == "additional_experiment")):
                if adjudicated:
                    entry["objective"] = (
                        "Implement only the complete plan in methods_adjudication against the immutable failure. "
                        "Do not add competing reviewer proposals, change the admitted question, tune an "
                        "outcome threshold, or substitute values for censored observations. Preserve the "
                        "plan's uncertainty and phase ownership: plan checks concern the proposed design; "
                        "execution checks require source tests, a fresh execution, and independent "
                        "recalculation before result admission. Plan acceptance does not certify execution checks."
                    )
                    entry["repair_strategy"] = "methods_adjudicated"
                    entry["methods_adjudication"] = _preserve_response_value(adjudicated_plan)
                    entry["methods_adjudication_sha256"] = hashlib.sha256(
                        canonical_bytes(entry["methods_adjudication"])).hexdigest()
                    entry["experiment_repair_plan"] = {
                        "schema_version": "experiment-repair-plan-3",
                        "mode": "diagnose_patch_execute_recalculate",
                        "design_axis": "methods_adjudicated",
                        "failure_lineage": deepcopy(adjudicated_plan.get("failure_lineage")),
                        "root_causes": [deepcopy(adjudicated_plan.get("root_cause"))],
                        "required_changes": deepcopy(adjudicated_plan.get("required_changes", [])),
                        "acceptance_checks": deepcopy(adjudicated_plan.get("acceptance_checks", [])),
                        "dissent_resolution": deepcopy(adjudicated_plan.get("dissent_resolution", [])),
                        "residual_uncertainties": deepcopy(adjudicated_plan.get("residual_uncertainties", [])),
                        "must_verify": deepcopy(adjudicated_plan.get("acceptance_checks", [])),
                    }
                else:
                    entry["objective"] = (
                        "Test the latest Methods-panel diagnosis hypotheses against the immutable failure, "
                        "source, raw observations, and deterministic validation. Reviewer judgments are "
                        "not confirmation: repair only defects reproduced from those records; if a claim is "
                        "contradicted, document the evidence and retain the valid result; if unresolved, "
                        "state a bounded limitation. Preserve the admitted question and do not force a "
                        "source change just to satisfy a reviewer. Review input: "
                        + " | ".join(review_evidence[:5])
                    )[:2400]
                    entry["repair_strategy"] = "review_directed"
                    entry["review_hypotheses"] = review_evidence
                    entry["experiment_repair_plan"] = {
                        "schema_version": "experiment-repair-plan-1",
                        "mode": "diagnose_patch_execute_recalculate",
                        "design_axis": "review_directed",
                        "root_causes": [],
                        "required_changes": [],
                        "diagnostic_hypotheses": repair_hypotheses,
                        "proposed_changes": proposed_changes,
                        "must_verify": review_evidence[:8],
                        "must_change": [],
                    }
            output.append(entry)
        return output

    @staticmethod
    def _capability_authoring_review_contract(requests):
        """Require observable dispositions for review findings in capability repairs."""
        directive_ids = []
        for request in requests if isinstance(requests, list) else []:
            if not isinstance(request, dict):
                continue
            if (request.get("kind") != "additional_experiment"
                    and request.get("target_stage_kind") != "experiment"):
                continue
            directives = request.get("review_directives")
            if not isinstance(directives, list):
                continue
            directive_ids.extend(
                item["id"] for item in directives
                if isinstance(item, dict)
                and isinstance(item.get("id"), str)
                and item["id"].strip()
            )
        directive_ids = list(dict.fromkeys(directive_ids))[:16]
        if not directive_ids:
            return None
        return {
            "required_directive_ids": directive_ids,
            "proof": (
                "Independently adjudicate every review directive against source, raw observations, and "
                "deterministic validation. For a confirmed defect, repair it; for a contradicted review "
                "claim, cite the result path that falsifies it; for unresolved uncertainty, state a bounded "
                "limitation. Do not implement a reviewer proposal without evidence that the change is needed."
            ),
            "not_sufficient": [
                "comments without changed behavior or a new check",
                "unchanged results relabeled as a repair",
                "editing result JSON or observations to satisfy a review",
                "blindly implementing a reviewer proposal without verifying the alleged defect",
            ],
            "verification": [
                "execute in a fresh attempt namespace",
                "replay and independently recalculate the primary outcomes",
                "retain unresolved directives as explicit limitations rather than claiming they passed",
            ],
        }

    @staticmethod
    def _capability_repair_provenance(repair_context):
        """Normalize legacy repair-panel payloads before foundry admission."""
        if not isinstance(repair_context, dict):
            return None
        ledger = repair_context.get("ledger")
        ledger = ledger if isinstance(ledger, dict) else {}

        def records(primary, fallback):
            value = repair_context.get(primary)
            if not isinstance(value, list):
                value = repair_context.get(fallback)
            return deepcopy(value[:12]) if isinstance(value, list) else []

        return {
            "kind": "independent_repair",
            "origin": "composer_model_panel",
            "panel_stage_id": ledger.get("panel_stage_id"),
            "panel_input_sha256": repair_context.get("input_sha256"),
            "panel_verdict_artifact_ref": ledger.get("verifier_artifact_ref"),
            "diagnostic_hypotheses": records("diagnostic_hypotheses", "root_causes"),
            "proposed_changes": records("proposed_changes", "required_changes"),
        }

    def _latest_foundry_failure_projection(self, question, domain):
        """Find the latest failed authoring state for this exact scientific intent."""
        cache = ModelWorkCache(self.store, self._publish, namespace="command/foundry-work")
        try:
            entries = cache.entries()
        except (OSError, ValueError, TypeError):
            return {}
        # A long-running Composer can have more than a few hundred immutable
        # foundry records. Do not lose the matching failed experiment merely
        # because unrelated newer authoring records pushed it past a scan cap.
        for candidate_entry in entries:
            assignment = (candidate_entry.get("assignment")
                          if isinstance(candidate_entry, dict) else None)
            required = (assignment.get("required_intent_fields")
                        if isinstance(assignment, dict) else None)
            if (not isinstance(required, dict)
                    or required.get("research_question") != question
                    or required.get("domain") != domain):
                continue
            cache_ref = candidate_entry.get("cache_ref")
            try:
                cache_manifest = self.store.get(cache_ref)
                cache_body = self.store.read_body(cache_manifest["body_hash"])
                cache_body_hash = hashlib.sha256(cache_body).hexdigest()
                if cache_body_hash != cache_manifest.get("body_hash"):
                    continue
                entry = json.loads(cache_body)
            except (NotFoundError, KeyError, OSError, TypeError, ValueError,
                    ValidationError):
                continue
            if not isinstance(entry, dict):
                continue
            verified_assignment = entry.get("assignment")
            verified_required = (verified_assignment.get("required_intent_fields")
                                 if isinstance(verified_assignment, dict) else None)
            if (not isinstance(verified_required, dict)
                    or verified_required.get("research_question") != question
                    or verified_required.get("domain") != domain):
                continue
            # The latest admission supersedes older rejected candidates for
            # this intent; its retained repair feedback is historical evidence.
            if entry.get("status") == "succeeded":
                return {}
            last_attempt = entry.get("last_attempt")
            source_files = {}
            if isinstance(last_attempt, dict):
                projected_attempt = {
                    "experiment_intent": deepcopy(last_attempt.get("experiment_intent")),
                }
                source_integrity = {}
                for source_name in ("executor", "validator"):
                    source = last_attempt.get(f"{source_name}_source")
                    if not isinstance(source, str):
                        continue
                    source_bytes = source.encode("utf-8")
                    source_integrity[source_name] = {
                        "characters": len(source),
                        "size_bytes": len(source_bytes),
                        "sha256": hashlib.sha256(source_bytes).hexdigest(),
                        "truncated": len(source) > CAPABILITY_REPAIR_SOURCE_CHARS,
                    }
                    bounded_source = source[:CAPABILITY_REPAIR_SOURCE_CHARS]
                    safe_source = redact_sensitive_text(bounded_source)
                    source_files[source_name] = {
                        "available": len(source) <= CAPABILITY_REPAIR_SOURCE_CHARS,
                        "source_sha256": source_integrity[source_name]["sha256"],
                        "source_characters": len(source),
                        "source_truncated": source_integrity[source_name]["truncated"],
                        "cache_body_sha256": cache_body_hash,
                        "cache_body_verified": True,
                        "integrity_verified": len(source) <= CAPABILITY_REPAIR_SOURCE_CHARS,
                        "prompt_source_sha256": hashlib.sha256(
                            safe_source.encode("utf-8")).hexdigest(),
                        "prompt_source_characters": len(safe_source),
                        "redaction_applied": safe_source != bounded_source,
                        "source_chunks": (
                            [safe_source[offset:offset + 7000]
                             for offset in range(0, len(safe_source), 7000)]
                            if len(source) <= CAPABILITY_REPAIR_SOURCE_CHARS else []
                        ),
                    }
                    projected_attempt[f"{source_name}_source"] = bounded_source
                projected_attempt["source_integrity"] = source_integrity
                projected_attempt["source_files"] = source_files
                last_attempt = projected_attempt
            else:
                last_attempt = None
            return self._capability_repair_projection({
                "status": entry.get("status"),
                "attempts": entry.get("attempts"),
                "feedback": entry.get("feedback") or entry.get("error"),
                "validation_context": entry.get("validation_context"),
                "validation_feedback": entry.get("validation_feedback"),
                "repair_gate_counts": entry.get("repair_gate_counts"),
                "last_attempt": last_attempt,
                "cache_ref": cache_ref,
                "cache_body_sha256": cache_body_hash,
                "cache_body_verified": True,
            }, max_text=CAPABILITY_REPAIR_SOURCE_CHARS)
        return {}

    def _stage_ancestor_ids(self, stage):
        """Return the dependency closure for one workflow stage."""
        if not isinstance(stage, dict):
            return set()
        by_id = {
            item.get("id"): item for item in self.workflow.get("stages", [])
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        }
        pending = list(stage.get("depends_on", []))
        ancestors = set()
        while pending:
            current = pending.pop()
            if current in ancestors or current not in by_id:
                continue
            ancestors.add(current)
            pending.extend(by_id[current].get("depends_on", []))
        return ancestors

    def _topic_context_for_stage(self, stage, *, ancestor_ids=None):
        """Resolve the unique topic governing a stage, without cross-branch leakage."""
        if not isinstance(stage, dict):
            return None
        ancestor_ids = (self._stage_ancestor_ids(stage) if ancestor_ids is None
                        else ancestor_ids)
        topic_stages = [
            item for item in self.workflow.get("stages", [])
            if isinstance(item, dict) and item.get("kind") == "topic_discovery"
            and item.get("id") in ancestor_ids
        ]
        if len(topic_stages) > 1:
            raise ValidationError(
                f"stage {stage.get('id')} has multiple topic ancestors; "
                "each research branch requires its own topic stage")
        if topic_stages:
            topic_stage_id = topic_stages[0]["id"]
            value = self.context.get(topic_stage_id)
            if (not isinstance(value, dict) or value.get("kind") != "topic_discovery"
                    or not isinstance(value.get("topic"), dict)):
                raise ValidationError(
                    f"stage {stage.get('id')} is missing its topic ancestor context")
            return topic_stage_id, value

        # Old workflows without topic stages may inject a single topic packet
        # into a standalone stage. Never borrow one from another branch in a
        # workflow that declares topic discovery stages.
        if any(isinstance(item, dict) and item.get("kind") == "topic_discovery"
               for item in self.workflow.get("stages", [])):
            return None
        matches = [
            (stage_id, value) for stage_id, value in self.context.items()
            if isinstance(value, dict) and value.get("kind") == "topic_discovery"
            and isinstance(value.get("topic"), dict)
        ]
        return matches[0] if len(matches) == 1 else None

    def _failed_foundry_work_for_stage(self, stage):
        """Attach exact unregistered authoring evidence to an experiment dossier."""
        if not isinstance(stage, dict) or stage.get("kind") != "experiment":
            return {}
        try:
            topic_match = self._topic_context_for_stage(stage)
        except ValidationError:
            return {}
        if not topic_match:
            return {}
        topic = topic_match[1].get("topic")
        if not isinstance(topic, dict):
            return {}
        question, domain = topic.get("research_question"), topic.get("domain")
        if not isinstance(question, str) or not isinstance(domain, str):
            return {}
        failed = self._latest_foundry_failure_projection(question, domain)
        if not isinstance(failed, dict) or failed.get("status") in (None, "succeeded"):
            return {}
        return {
            "topic_id": topic.get("id"),
            "research_question": question,
            "domain": domain,
            **failed,
        }

    def _prior_attempt_result_evidence(self, stage, prior_context, *, selected_topic=None):
        """Resolve a rejected experiment result only inside its own attempt namespace."""
        unavailable = {
            "available": False,
            "identity_verified": False,
            "admissible_as_verified_claims": False,
        }
        if not isinstance(stage, dict) or stage.get("kind") != "experiment":
            return {**unavailable, "reason": "not_an_experiment_stage"}
        prior_context = prior_context if isinstance(prior_context, dict) else {}
        stage_id = stage.get("id")
        attempt_number = prior_context.get("attempt_number")
        project_dir = prior_context.get("project_dir")
        if (prior_context.get("stage_id") != stage_id
                or type(attempt_number) is not int or attempt_number < 1
                or not isinstance(project_dir, str)):
            return {**unavailable, "reason": "prior_attempt_identity_incomplete"}
        try:
            stage_root = Path(stage["project_dir"]).resolve()
            if (stage_root.name.startswith("attempt-")
                    and stage_root.parent.name == "attempts"):
                # Stage runners receive an attempt-scoped descriptor. Prior
                # evidence lives beside that attempt, under the stable stage
                # project root, so using the current attempt directory as the
                # containment root incorrectly hides every prior result.
                stage_root = next((parent for parent in stage_root.parents
                                   if (parent / "continuations").is_dir()), None)
                if stage_root is None:
                    return {**unavailable,
                            "reason": "prior_attempt_stage_root_unresolvable"}
            attempt_root = Path(project_dir).resolve()
            attempt_root.relative_to(stage_root)
            if (attempt_root == stage_root
                    or attempt_root.name != f"attempt-{attempt_number}"
                    or attempt_root.parent.name != "attempts"):
                return {**unavailable, "reason": "prior_attempt_namespace_mismatch"}

            def bound_file(value):
                if not isinstance(value, str) or not value:
                    return None
                candidate = Path(value)
                if not candidate.is_absolute():
                    candidate = attempt_root / candidate
                candidate = candidate.resolve()
                candidate.relative_to(attempt_root)
                if (not candidate.is_file()
                        or candidate.stat().st_size > MAX_EXPERIMENT_RESULT_PACKAGE_BYTES):
                    return None
                return candidate

            run_path = bound_file(prior_context.get("output_path"))
            package_path = bound_file(prior_context.get("results_package"))
            if run_path is None:
                return {**unavailable, "reason": "prior_attempt_output_missing_or_out_of_scope"}
            run_record = _read_experiment_result_payload(
                str(run_path), base_dir=attempt_root)
            if package_path is None:
                return self._executed_candidate_evidence(
                    prior_context, run_record, run_path, attempt_root,
                    bound_file, selected_topic=selected_topic)
            package = _read_experiment_result_payload(
                str(package_path), base_dir=attempt_root)
            if not isinstance(run_record, dict) or not isinstance(package, dict):
                return {**unavailable, "reason": "prior_attempt_output_not_a_json_object"}
            expected_question = (selected_topic.get("research_question")
                                 if isinstance(selected_topic, dict) else None)
            if (isinstance(expected_question, str)
                    and package.get("question") != expected_question):
                return {**unavailable, "reason": "prior_attempt_research_question_mismatch"}
            if run_record.get("status") in {
                    "queued", "pending", "running", "in_progress", "starting"}:
                return {**unavailable, "reason": "prior_attempt_is_still_running"}
            recorded_package_path = run_record.get("results_package")
            if isinstance(recorded_package_path, str):
                recorded_package_path = bound_file(recorded_package_path)
                if recorded_package_path != package_path:
                    return {**unavailable, "reason": "prior_attempt_results_package_path_mismatch"}

            context_refs = prior_context.get("execution_refs")
            run_refs = run_record.get("execution_refs")
            provenance = package.get("provenance")
            package_refs = provenance.get("execution_refs") if isinstance(provenance, dict) else None
            if (not isinstance(context_refs, list) or not context_refs
                    or not all(isinstance(ref, str) and ref for ref in context_refs)
                    or run_refs != context_refs or package_refs != context_refs):
                return {**unavailable, "reason": "prior_attempt_execution_refs_do_not_match"}
            for key in ("project_id", "study_id", "assessment_ref"):
                context_value = prior_context.get(key)
                run_value = run_record.get(key)
                if (isinstance(context_value, str) and context_value
                        and isinstance(run_value, str) and run_value
                        and context_value != run_value):
                    return {**unavailable, "reason": f"prior_attempt_{key}_mismatch"}
            package_assessment_ref = (
                package.get("validation", {}).get("assessment_ref")
                if isinstance(package.get("validation"), dict) else None
            )
            if (isinstance(package_assessment_ref, str)
                    and isinstance(run_record.get("assessment_ref"), str)
                    and package_assessment_ref != run_record["assessment_ref"]):
                return {**unavailable, "reason": "prior_attempt_assessment_ref_mismatch"}

            review_evidence = []
            validation = package.get("validation")
            review_refs = (validation.get("model_review_refs", [])
                           if isinstance(validation, dict) else [])
            if isinstance(review_refs, list):
                for review_ref in review_refs[:8]:
                    match = (re.fullmatch(
                        r"artifact:methods/experiment-reviews/([a-z][a-z0-9_-]{0,63})@([1-9][0-9]*)",
                        review_ref,
                    ) if isinstance(review_ref, str) else None)
                    if not match:
                        continue
                    reviewer_id = match.group(1)
                    candidates = [
                        path for path in (attempt_root / "runs").glob(
                            f"experiment-{reviewer_id}-*/result.json")
                        if re.fullmatch(
                            rf"experiment-{re.escape(reviewer_id)}-[1-9][0-9]*",
                            path.parent.name,
                        ) and path.is_file()
                        and path.stat().st_size <= MAX_EXPERIMENT_RESULT_PACKAGE_BYTES
                    ]
                    for review_path in sorted(
                            candidates, key=lambda path: path.stat().st_mtime_ns,
                            reverse=True):
                        try:
                            review_bytes = review_path.read_bytes()
                            envelope = json.loads(review_bytes)
                            result = envelope.get("result") if isinstance(envelope, dict) else None
                            response_text = result.get("text") if isinstance(result, dict) else None
                            response = (json.loads(response_text)
                                        if isinstance(response_text, str) else result)
                        except (OSError, ValueError, TypeError):
                            continue
                        if (not isinstance(response, dict)
                                or response.get("reviewer_id") != reviewer_id):
                            continue
                        checks = response.get("checks")
                        adverse_checks = [
                            {
                                "check_id": item.get("check_id"),
                                "outcome": item.get("outcome"),
                                "evidence": str(item.get("evidence", ""))[:1600],
                            }
                            for item in checks if isinstance(item, dict)
                            and item.get("outcome") != "passed"
                        ][:8] if isinstance(checks, list) else []
                        findings = response.get("finding_assessments")
                        adverse_findings = [
                            {
                                "finding_id": item.get("finding_id"),
                                "outcome": item.get("outcome"),
                                "rationale": str(item.get("rationale", ""))[:1200],
                            }
                            for item in findings if isinstance(item, dict)
                            and item.get("outcome") not in {"supported", "consistent"}
                        ][:8] if isinstance(findings, list) else []
                        limitations = response.get("limitations")
                        review_evidence.append({
                            "reviewer_id": reviewer_id,
                            "declared_ref": review_ref,
                            "attempt_local_path": review_path.relative_to(
                                attempt_root).as_posix(),
                            "sha256": hashlib.sha256(review_bytes).hexdigest(),
                            "decision": response.get("decision"),
                            "adverse_checks": adverse_checks,
                            "adverse_findings": adverse_findings,
                            "limitations": [str(item)[:1000]
                                            for item in limitations[:6]
                                            if isinstance(item, str)]
                            if isinstance(limitations, list) else [],
                            "attempt_identity_verified": True,
                        })
                        break

            package_bytes = package_path.read_bytes()
            run_bytes = run_path.read_bytes()
            assets = package.get("assets")
            assets = assets if isinstance(assets, list) else []
            raw_asset = next((asset for asset in assets
                              if isinstance(asset, dict)
                              and (asset.get("role") == "raw_data"
                                   or asset.get("id") == "raw_data")), None)
            raw_payload = None
            raw_path = None
            raw_bytes = None
            if isinstance(raw_asset, dict) and isinstance(raw_asset.get("path"), str):
                raw_path = (package_path.parent / raw_asset["path"]).resolve()
                raw_path.relative_to(attempt_root)
                if (raw_path.is_file()
                        and raw_path.stat().st_size <= MAX_EXPERIMENT_RESULT_PACKAGE_BYTES):
                    raw_bytes = raw_path.read_bytes()
                    declared_hash = raw_asset.get("sha256")
                    actual_hash = hashlib.sha256(raw_bytes).hexdigest()
                    if isinstance(declared_hash, str) and declared_hash != actual_hash:
                        return {**unavailable, "reason": "prior_attempt_raw_data_hash_mismatch"}
                    raw_payload = json.loads(raw_bytes)
                    if not isinstance(raw_payload, (dict, list)):
                        return {**unavailable, "reason": "prior_attempt_raw_data_invalid"}

            observations = (
                raw_payload.get("observations")
                if isinstance(raw_payload, dict) else raw_payload
            )
            if not isinstance(observations, list):
                observations = package.get("observations")
            if not isinstance(observations, list):
                observations = []
            sample_size = min(24, len(observations))
            sample_indices = sorted({
                round(index * (len(observations) - 1) / max(1, sample_size - 1))
                for index in range(sample_size)
            })
            sample_rows = [observations[index] for index in sample_indices]
            columns = sorted({
                str(key) for row in sample_rows if isinstance(row, dict)
                for key in row
            })[:48]

            science_fields = (
                "question", "hypothesis", "study_type", "procedures", "metrics",
                "analysis", "findings", "limitations", "validation",
                "quality_contract", "quality_admission",
            )

            def without_provenance(value):
                if isinstance(value, dict):
                    return {
                        key: without_provenance(item)
                        for key, item in value.items()
                        if (key not in {"provenance", "assets"}
                            and not key.casefold().endswith(("_ref", "_refs")))
                    }
                if isinstance(value, list):
                    return [without_provenance(item) for item in value]
                return value

            scientific_payload = {
                key: without_provenance(package[key])
                for key in science_fields if key in package
            }
            if isinstance(raw_payload, dict):
                scientific_observations = raw_payload.get("observations", [])
            else:
                scientific_observations = raw_payload or observations

            def normalize_fingerprint_numbers(value):
                if isinstance(value, float):
                    return float(format(value, ".10g"))
                if isinstance(value, dict):
                    return {key: normalize_fingerprint_numbers(item)
                            for key, item in value.items()}
                if isinstance(value, list):
                    return [normalize_fingerprint_numbers(item) for item in value]
                return value

            scientific_sha256 = hashlib.sha256(canonical_bytes({
                "results": normalize_fingerprint_numbers(scientific_payload),
                "observations": normalize_fingerprint_numbers(scientific_observations),
                "review_evidence": [{
                    "reviewer_id": item.get("reviewer_id"),
                    "decision": item.get("decision"),
                    "adverse_checks": [{
                        "check_id": check.get("check_id"),
                        "outcome": check.get("outcome"),
                    } for check in item.get("adverse_checks", [])],
                    "adverse_findings": [{
                        "finding_id": finding.get("finding_id"),
                        "outcome": finding.get("outcome"),
                    } for finding in item.get("adverse_findings", [])],
                } for item in review_evidence],
            })).hexdigest()
            measurement_sha256 = hashlib.sha256(canonical_bytes({
                "observations": normalize_fingerprint_numbers(scientific_observations),
                "metrics": normalize_fingerprint_numbers(package.get("metrics", [])),
            })).hexdigest()

            derived = {key: package[key] for key in (
                "metrics", "analysis", "findings", "limitations", "validation",
            ) if key in package}
            figures = []
            for asset in assets:
                if (not isinstance(asset, dict)
                        or not (asset.get("role") == "figure"
                                or str(asset.get("media_type", "")).casefold().startswith("image/"))):
                    continue
                figure = {
                    key: asset.get(key) for key in ("id", "caption", "media_type", "sha256")
                    if asset.get(key) is not None
                }
                figure_path = None
                if isinstance(asset.get("path"), str):
                    figure_path = (package_path.parent / asset["path"]).resolve()
                    figure_path.relative_to(attempt_root)
                figure["file_verified"] = bool(
                    figure_path and figure_path.is_file()
                    and figure_path.stat().st_size <= MAX_EXPERIMENT_RESULT_PACKAGE_BYTES
                    and isinstance(asset.get("sha256"), str)
                    and hashlib.sha256(figure_path.read_bytes()).hexdigest() == asset["sha256"]
                )
                figures.append(figure)

            relative = lambda path: path.relative_to(attempt_root).as_posix()
            raw_record = {
                "available": raw_payload is not None,
                "path": relative(raw_path) if raw_path is not None else None,
                "sha256": hashlib.sha256(raw_bytes).hexdigest() if raw_bytes is not None else None,
                "observation_count": len(observations),
                "columns": columns,
                "sample_indices": sample_indices,
                "sample_rows": _bounded_experiment_result_projection(sample_rows),
            }
            result_record = {
                **unavailable,
                "available": True,
                "identity_verified": True,
                "stage_id": stage_id,
                "attempt_number": attempt_number,
                "run_status": run_record.get("status"),
                "prior_status": prior_context.get("status"),
                "validation_decision": (package.get("validation", {}).get("decision")
                                         if isinstance(package.get("validation"), dict)
                                         else None),
                "assessment_ref": run_record.get("assessment_ref"),
                "execution_refs": context_refs,
                "admissible_as_verified_claims": False,
                "scientific_sha256": scientific_sha256,
                "measurement_sha256": measurement_sha256,
                "files": {
                    "run_record": {"path": relative(run_path),
                                   "sha256": hashlib.sha256(run_bytes).hexdigest()},
                    "results_package": {"path": relative(package_path),
                                        "sha256": hashlib.sha256(package_bytes).hexdigest()},
                    "raw_data": raw_record,
                },
                "results_package": _bounded_experiment_result_projection(scientific_payload),
                "derived_results": _bounded_experiment_result_projection(derived),
                "review_evidence": _bounded_experiment_result_projection(review_evidence),
                "figures": _bounded_experiment_result_projection(figures),
            }
            return result_record
        except (OSError, RuntimeError, TypeError, ValueError, KeyError, sqlite3.Error):
            return {**unavailable, "reason": "prior_attempt_evidence_failed_scope_or_integrity_check"}

    @staticmethod
    def _executed_candidate_evidence(context, run, run_path, attempt_root,
                                     bound_file, *, selected_topic=None):
        """Bind unreviewed observations to immutable execution bodies."""
        unavailable = {"available": False, "identity_verified": False,
                       "admissible_as_verified_claims": False}
        if not isinstance(run, dict) or run.get("status") in {
                "queued", "pending", "running", "in_progress", "starting"}:
            return {**unavailable, "reason": "prior_attempt_is_still_running"}
        raw_path = bound_file(run.get("raw_results"))
        refs = run.get("execution_refs")
        if (raw_path is None or refs != context.get("execution_refs")
                or not isinstance(refs, list) or len(refs) < 2
                or not all(isinstance(ref, str) for ref in refs)
                or len(set(refs)) != len(refs)):
            return {**unavailable, "reason": "executed_candidate_lineage_incomplete"}
        expected_question = (selected_topic.get("research_question")
                             if isinstance(selected_topic, dict) else None)
        if expected_question is not None and run.get("research_question") != expected_question:
            return {**unavailable, "reason": "prior_attempt_research_question_mismatch"}
        raw_bytes = raw_path.read_bytes()
        digest = hashlib.sha256(raw_bytes).hexdigest()
        candidate = json.loads(raw_bytes)
        if (digest != run.get("raw_results_sha256") or not isinstance(candidate, dict)
                or candidate.get("study_id") != run.get("study_id")):
            return {**unavailable, "reason": "executed_candidate_identity_mismatch"}
        for key in ("project_id", "study_id", "attempt_number"):
            if context.get(key) is not None and run.get(key) is not None and context[key] != run[key]:
                return {**unavailable, "reason": f"prior_attempt_{key}_mismatch"}
        database = attempt_root / "state" / "control.sqlite"
        if not database.is_file():
            return {**unavailable, "reason": "executed_candidate_ledger_missing"}
        with closing(sqlite3.connect(f"{database.as_uri()}?mode=ro", uri=True)) as connection:
            for ref in refs:
                row = connection.execute(
                    "SELECT body_hash FROM artifacts WHERE artifact_ref=?", (ref,)).fetchone()
                if row is None or not re.fullmatch(r"[0-9a-f]{64}", row[0] or ""):
                    return {**unavailable, "reason": "executed_candidate_execution_missing"}
                body_path = attempt_root / "objects" / "sha256" / row[0]
                if body_path.stat().st_size > MAX_EXPERIMENT_RESULT_PACKAGE_BYTES:
                    return {**unavailable, "reason": "executed_candidate_execution_oversized"}
                body = body_path.read_bytes()
                execution = json.loads(body)
                if (hashlib.sha256(body).hexdigest() != row[0]
                        or execution.get("outcome") != "ok"
                        or canonical_bytes(execution.get("document")) != canonical_bytes(candidate)):
                    return {**unavailable, "reason": "executed_candidate_execution_mismatch"}
        observations = candidate.get("observations", [])
        observations = observations if isinstance(observations, list) else []
        size = min(24, len(observations))
        indices = sorted({round(index * (len(observations) - 1) / max(1, size - 1))
                          for index in range(size)})
        derived = {key: candidate[key] for key in (
            "metrics", "analysis", "findings", "limitations") if key in candidate}
        return {
            **unavailable, "available": True, "identity_verified": True,
            "evidence_kind": "executed_unreviewed_candidate",
            "stage_id": context.get("stage_id"), "attempt_number": context.get("attempt_number"),
            "run_status": run.get("status"), "prior_status": context.get("status"),
            "execution_refs": refs, "scientific_sha256": digest,
            "measurement_sha256": hashlib.sha256(canonical_bytes({
                "observations": observations, "metrics": candidate.get("metrics", [])})).hexdigest(),
            "files": {
                "run_record": {"path": run_path.relative_to(attempt_root).as_posix(),
                               "sha256": hashlib.sha256(run_path.read_bytes()).hexdigest()},
                "raw_data": {"available": True,
                             "path": raw_path.relative_to(attempt_root).as_posix(),
                             "sha256": digest, "observation_count": len(observations),
                             "sample_indices": indices,
                             "sample_rows": _bounded_experiment_result_projection(
                                 [observations[index] for index in indices])}},
            "executed_candidate": _bounded_experiment_result_projection(candidate),
            "derived_results": _bounded_experiment_result_projection(derived),
            "review_evidence": [], "figures": [],
        }

    def _unresolved_prior_attempt_evidence(self, stage, attempts, *, selected_topic=None):
        """Project durable evidence for unresolved attempts without promoting results.

        A worker's result file is not the same thing as an acknowledged stage
        result. Keep both ledgers visible so a repair panel can reconcile a
        completed subprocess, an interrupted run, and a missing result before
        it orders any equivalent execution.
        """
        attempts = attempts if isinstance(attempts, list) else []
        summary = {
            "attempt_count": 0,
            "inspected_count": 0,
            "missing_directory_count": 0,
            "records": {},
            "worker_results": {},
            "generated_sources": [],
            "generated_source_selection_policy": (
                "Include at most the two most recent distinct generated program sources "
                "whose exact path is bound to a complete successful local-program result. "
                "These remain diagnostic and are never admitted as research results."
            ),
            "admission_rule": (
                "Unresolved worker output is diagnostic evidence only. It is not a released claim. "
                "Reconcile the stage record and nested task/attempt ledger before an equivalent "
                "operation; a fresh run requires a material source/design change."
            ),
        }
        if not isinstance(stage, dict) or stage.get("kind") != "experiment":
            return summary
        unresolved = sorted(
            (item for item in attempts
             if isinstance(item, dict)
             and item.get("state") in {"started", "unknown", "result_unknown"}),
            key=lambda item: (
                item.get("attempt_number") if type(item.get("attempt_number")) is int else -1,
                item.get("cycle") if type(item.get("cycle")) is int else -1,
            ), reverse=True,
        )
        summary["attempt_count"] = len(unresolved)
        try:
            stage_root = Path(stage["project_dir"]).resolve()
            if stage_root.name.startswith("attempt-") and stage_root.parent.name == "attempts":
                stage_root = next((parent for parent in stage_root.parents
                                   if (parent / "continuations").is_dir()), None)
            if stage_root is None:
                raise ValueError("experiment stage root is unavailable")
        except (KeyError, OSError, RuntimeError, TypeError, ValueError):
            summary["evidence_status"] = "stage_root_unavailable"
            return summary

        def read_json(path, attempt_root):
            try:
                resolved = path.resolve()
                resolved.relative_to(attempt_root)
                if (not resolved.is_file()
                        or resolved.stat().st_size > MAX_EXPERIMENT_RESULT_PACKAGE_BYTES):
                    return None, None
                raw = resolved.read_bytes()
                value = json.loads(raw)
            except (OSError, RuntimeError, TypeError, ValueError):
                return None, None
            return (value if isinstance(value, dict) else None,
                    hashlib.sha256(raw).hexdigest())

        def nested_task_ledger(attempt_root, task_id):
            database = attempt_root / "state" / "control.sqlite"
            if not database.is_file() or not isinstance(task_id, str):
                return {"available": False}
            connection = None
            try:
                connection = sqlite3.connect(
                    f"{database.resolve().as_uri()}?mode=ro", uri=True, timeout=0.5)
                connection.row_factory = sqlite3.Row
                tables = {row[0] for row in connection.execute(
                    "SELECT name FROM sqlite_master WHERE type='table'")}
                if not {"tasks", "attempts"}.issubset(tables):
                    return {"available": False, "reason": "ledger_schema_unavailable"}
                task = connection.execute(
                    "SELECT state FROM tasks WHERE task_id=?", (task_id,)
                ).fetchone()
                rows = connection.execute(
                    "SELECT state,lease_expiry,external_ref FROM attempts "
                    "WHERE task_id=? ORDER BY created_at DESC LIMIT 4", (task_id,)
                ).fetchall()
                now = time.time()
                return {
                    "available": True,
                    "task_state": task["state"] if task else "missing",
                    "attempt_count": len(rows),
                    "attempt_states": "; ".join(
                        f"{row['state']} (lease_expired="
                        f"{type(row['lease_expiry']) in (int, float) and row['lease_expiry'] <= now}; "
                        f"external_ref_recorded={bool(row['external_ref'])})"
                        for row in rows),
                }
            except (OSError, sqlite3.Error, TypeError, ValueError):
                return {"available": False, "reason": "ledger_read_failed"}
            finally:
                if connection is not None:
                    connection.close()

        def nested_operation_ledger(attempt_root):
            """Read unresolved external operations without promoting their outputs."""
            database = attempt_root / "state" / "control.sqlite"
            if not database.is_file():
                return {"available": False, "operation_count": 0, "operations": []}
            connection = None
            try:
                resolved_database = database.resolve()
                resolved_database.relative_to(attempt_root.resolve())
                connection = sqlite3.connect(
                    f"{resolved_database.as_uri()}?mode=ro", uri=True, timeout=0.5)
                connection.row_factory = sqlite3.Row
                tables = {row[0] for row in connection.execute(
                    "SELECT name FROM sqlite_master WHERE type='table'")}
                if not {"tasks", "attempts"}.issubset(tables):
                    return {"available": False, "reason": "ledger_schema_unavailable",
                            "operation_count": 0, "operations": []}
                operations = []
                task_rows = connection.execute(
                    "SELECT task_id,kind,state,payload_json FROM tasks "
                    "ORDER BY updated_at DESC LIMIT 128").fetchall()
                for task in task_rows:
                    try:
                        payload = json.loads(task["payload_json"])
                    except (TypeError, ValueError):
                        payload = None
                    operation = payload.get("operation") if isinstance(payload, dict) else None
                    if not isinstance(operation, str) or not operation:
                        continue
                    attempt_rows = connection.execute(
                        "SELECT state,external_ref,usage_json FROM attempts "
                        "WHERE task_id=? ORDER BY created_at DESC LIMIT 4",
                        (task["task_id"],),
                    ).fetchall()
                    nested_attempts = []
                    for nested_attempt in attempt_rows:
                        try:
                            usage = json.loads(nested_attempt["usage_json"])
                        except (TypeError, ValueError):
                            usage = None
                        accounting = usage.get("accounting") if isinstance(usage, dict) else None
                        nested_attempts.append({
                            "state": nested_attempt["state"],
                            "external_ref_recorded": bool(nested_attempt["external_ref"]),
                            "outcome_unknown": nested_attempt["state"] in {
                                "started", "unknown", "result_unknown",
                            },
                            "accounting": accounting if accounting in {
                                "conservative_pending_reconciliation", "settled",
                            } else None,
                        })
                    operations.append({
                        "task_id": str(task["task_id"])[:120],
                        "kind": str(task["kind"])[:80],
                        "task_state": str(task["state"])[:80],
                        "operation": operation[:80],
                        "attempts": nested_attempts,
                    })
                    if len(operations) == 8:
                        break
                return {
                    "available": True,
                    "operation_count": len(operations),
                    "operations": operations,
                    "truncated": len(task_rows) == 128,
                }
            except (OSError, sqlite3.Error, TypeError, ValueError):
                return {"available": False, "reason": "ledger_read_failed",
                        "operation_count": 0, "operations": []}
            finally:
                if connection is not None:
                    connection.close()

        def compact_items(value, limit):
            if not isinstance(value, list):
                return []
            output = []
            for item in value[:limit]:
                projected = _bounded_experiment_result_projection(item)
                text = (projected if isinstance(projected, str)
                        else json.dumps(projected, ensure_ascii=False, sort_keys=True))
                output.append(redact_sensitive_text(text)[:700])
            return output

        for item in unresolved:
            attempt_number, cycle = item.get("attempt_number"), item.get("cycle")
            if (type(attempt_number) is not int or attempt_number < 1
                    or type(cycle) is not int or cycle < 1
                    or not isinstance(item.get("project_dir"), str)):
                continue
            key = f"cycle-{cycle}-attempt-{attempt_number}"
            record = {
                "attempt_number": attempt_number,
                "cycle": cycle,
                "attempt_state": item.get("state"),
                "external_ref_recorded": bool(item.get("external_ref")),
                "admissible_as_verified_claims": False,
                "worker_results": [],
            }
            summary["records"][key] = record
            try:
                attempt_root = Path(item["project_dir"]).resolve()
                attempt_root.relative_to(stage_root)
                if (attempt_root == stage_root
                        or attempt_root.name != f"attempt-{attempt_number}"
                        or attempt_root.parent.name != "attempts"):
                    record["classification"] = "attempt_namespace_mismatch"
                    continue
            except (OSError, RuntimeError, TypeError, ValueError):
                record["classification"] = "attempt_namespace_mismatch"
                continue
            if not attempt_root.is_dir():
                record["classification"] = "attempt_directory_missing"
                summary["missing_directory_count"] += 1
                continue

            record["nested_operation_ledger"] = nested_operation_ledger(attempt_root)

            run_record, run_sha256 = read_json(attempt_root / "output" / "run.json", attempt_root)
            progress, progress_sha256 = read_json(
                attempt_root / "output" / "progress.json", attempt_root)
            if run_record is not None:
                record["stage_run"] = {
                    "status": run_record.get("status"),
                    "error": redact_sensitive_text(str(run_record.get("error") or ""))[:500],
                    "results_package_present": bool(run_record.get("results_package")),
                    "execution_ref_count": len(run_record.get("execution_refs", []))
                    if isinstance(run_record.get("execution_refs"), list) else 0,
                    "sha256": run_sha256,
                }
            if progress is not None:
                active_tasks = progress.get("active_tasks")
                record["stage_progress"] = {
                    "phase": progress.get("phase"),
                    "status": progress.get("status"),
                    "active_task_ids": [str(value)[:120] for value in active_tasks[:8]
                                        if isinstance(value, str)]
                    if isinstance(active_tasks, list) else [],
                    "sha256": progress_sha256,
                }

            operation_sources = []
            operations_dir = attempt_root / "workspace" / "operations"
            if operations_dir.is_dir():
                for pattern in (
                        "*/generated_executor/execution.py",
                        "*/generated_validator/validation.py",
                        "*/generated_validator/execution.py"):
                    try:
                        source_paths = sorted(operations_dir.glob(pattern))[:8]
                    except OSError:
                        source_paths = []
                    for source_path in source_paths:
                        try:
                            if source_path.is_symlink():
                                continue
                            resolved = source_path.resolve(strict=True)
                            relative_path = resolved.relative_to(attempt_root).as_posix()
                            source_bytes = resolved.read_bytes()
                        except (OSError, RuntimeError, ValueError):
                            continue
                        if len(source_bytes) <= CAPABILITY_REPAIR_SOURCE_CHARS * 4:
                            operation_sources.append({
                                "path": relative_path,
                                "resolved_path": resolved,
                                "sha256": hashlib.sha256(source_bytes).hexdigest(),
                                "size_bytes": len(source_bytes),
                                "source_bytes": source_bytes,
                                "worker_result_refs": [],
                            })

            def command_binds_source(metadata, source_path):
                if (not isinstance(metadata, dict)
                        or metadata.get("provider") != "local-program"
                        or metadata.get("process_returncode") != 0
                        or metadata.get("capture_truncated") is not False
                        or metadata.get("capture_incomplete") is not False):
                    return False
                command = metadata.get("command")
                if not isinstance(command, list) or not command:
                    return False
                cwd_value = metadata.get("cwd")
                try:
                    cwd = Path(cwd_value).resolve(strict=True) if isinstance(
                        cwd_value, str) and cwd_value else None
                except (OSError, RuntimeError, ValueError):
                    cwd = None
                for argument in command:
                    if not isinstance(argument, str) or not argument:
                        continue
                    candidate = Path(argument)
                    if not candidate.is_absolute():
                        if cwd is None:
                            continue
                        candidate = cwd / candidate
                    try:
                        resolved = candidate.resolve(strict=True)
                        resolved.relative_to(attempt_root)
                    except (OSError, RuntimeError, ValueError):
                        continue
                    if resolved == source_path:
                        return True
                return False

            runs_dir = attempt_root / "runs"
            result_paths = []
            if runs_dir.is_dir():
                try:
                    result_paths = sorted(
                        (path for path in runs_dir.glob("*/result.json")
                         if path.is_file() and not path.is_symlink()),
                        key=lambda path: path.stat().st_mtime_ns, reverse=True,
                    )[:16]
                except OSError:
                    result_paths = []
            for result_path in result_paths:
                envelope, result_sha256 = read_json(result_path, attempt_root)
                if not isinstance(envelope, dict):
                    continue
                result = envelope.get("result")
                result = result if isinstance(result, dict) else {}
                metadata = result.get("metadata")
                metadata = metadata if isinstance(metadata, dict) else {}
                document = result.get("document")
                if not isinstance(document, dict) and isinstance(result.get("text"), str):
                    try:
                        parsed_text = json.loads(result["text"])
                        document = parsed_text if isinstance(parsed_text, dict) else None
                    except (TypeError, ValueError):
                        document = None
                document = document if isinstance(document, dict) else {}
                observations = document.get("observations")
                metrics = document.get("metrics")
                findings = document.get("findings")
                limitations = document.get("limitations")
                worker_record = {
                    "task_id": result_path.parent.name[:120],
                    "result_sha256": result_sha256,
                    "ok": envelope.get("ok") is True,
                    "operation_outcome": result.get("outcome"),
                    "provider": metadata.get("provider"),
                    "transport": metadata.get("transport"),
                    "process_returncode": metadata.get("process_returncode"),
                    "capture_truncated": metadata.get("capture_truncated") is True,
                    "capture_incomplete": metadata.get("capture_incomplete") is True,
                    "schema_version": document.get("schema_version"),
                    "study_id": document.get("study_id"),
                    "observation_count": len(observations)
                    if isinstance(observations, list) else None,
                    "metric_count": len(metrics) if isinstance(metrics, list) else None,
                    "metrics": compact_items(metrics, 8),
                    "findings": compact_items(findings, 4),
                    "limitations": compact_items(limitations, 4),
                    "admissible_as_verified_claims": False,
                }
                worker_record["task_ledger"] = nested_task_ledger(
                    attempt_root, worker_record["task_id"])
                record["worker_results"].append(worker_record)
                if worker_record["ok"] is not True:
                    continue
                for source in operation_sources:
                    if not command_binds_source(metadata, source["resolved_path"]):
                        continue
                    source_ref = {
                        "attempt_number": attempt_number,
                        "cycle": cycle,
                        "task_id": worker_record["task_id"],
                        "worker_result_sha256": result_sha256,
                        "source_path": source["path"],
                    }
                    source["worker_result_refs"].append(source_ref)
                    existing = next((candidate for candidate in summary["generated_sources"]
                                     if candidate.get("source_sha256") == source["sha256"]), None)
                    if existing is None:
                        if len(summary["generated_sources"]) >= \
                                CAPABILITY_REPAIR_UNRESOLVED_SOURCE_FILES:
                            source["source_evidence_omission_reason"] = (
                                "The repair evidence packet includes the two most recent "
                                "distinct linked program sources."
                            )
                            continue
                        try:
                            source_text = source["source_bytes"].decode("utf-8")
                        except UnicodeDecodeError:
                            source_text = None
                        safe_source = (redact_sensitive_text(source_text)
                                       if isinstance(source_text, str) else None)
                        source_available = (
                            isinstance(safe_source, str)
                            and len(safe_source) <= CAPABILITY_REPAIR_SOURCE_CHARS
                        )
                        prompt_sha256 = (
                            hashlib.sha256(safe_source.encode("utf-8")).hexdigest()
                            if source_available else None
                        )
                        existing = {
                            "source_path": source["path"],
                            "source_sha256": source["sha256"],
                            "source_bytes": source["size_bytes"],
                            "source_characters": len(source_text)
                            if isinstance(source_text, str) else None,
                            "prompt_source_sha256": prompt_sha256,
                            "prompt_source_characters": len(safe_source)
                            if source_available else None,
                            "redaction_applied": (
                                safe_source != source_text
                                if isinstance(source_text, str) else False
                            ),
                            "source_available": source_available,
                            "execution_link_verified": True,
                            "source_chunks": (
                                [safe_source[index:index + 7000]
                                 for index in range(0, len(safe_source), 7000)]
                                if source_available else []
                            ),
                            "omission_reason": (
                                None if source_available else
                                "source exceeds the repair evidence bound or is not UTF-8"
                            ),
                            "source_question_binding": (
                                "The attempt's research-question identity is not verified against "
                                "the current admitted question. Diagnostic source only."
                            ),
                            "admissible_as_verified_claims": False,
                            "execution_refs": [],
                        }
                        summary["generated_sources"].append(existing)
                    if source_ref not in existing["execution_refs"]:
                        existing["execution_refs"].append(source_ref)

            if operation_sources:
                record["generated_programs"] = [{
                    "path": source["path"],
                    "sha256": source["sha256"],
                    "size_bytes": source["size_bytes"],
                    "execution_link_verified": bool(source["worker_result_refs"]),
                    "worker_result_refs": source["worker_result_refs"][:8],
                } for source in operation_sources[:8]]
            if record["worker_results"]:
                summary["worker_results"][key] = record["worker_results"]
                record["worker_result_count"] = len(record["worker_results"])
                record.pop("worker_results", None)

            stage_status = run_record.get("status") if isinstance(run_record, dict) else None
            has_successful_worker = any(
                worker.get("ok") is True
                and worker.get("process_returncode") == 0
                and worker.get("capture_truncated") is False
                and worker.get("capture_incomplete") is False
                for worker in summary["worker_results"].get(key, [])
            )
            if stage_status in {"completed", "accepted"} and run_record.get("results_package"):
                candidate = {
                    "stage_id": stage.get("id"),
                    "attempt_number": attempt_number,
                    "project_dir": str(attempt_root),
                    "output_path": str(attempt_root / "output" / "run.json"),
                    "results_package": run_record.get("results_package"),
                    "execution_refs": run_record.get("execution_refs"),
                    "project_id": run_record.get("project_id"),
                    "study_id": run_record.get("study_id"),
                    "assessment_ref": run_record.get("assessment_ref"),
                    "status": item.get("state"),
                }
                checked = self._prior_attempt_result_evidence(
                    stage, candidate, selected_topic=selected_topic)
                record["stage_result_check"] = {
                    "available": checked.get("available") is True,
                    "reason": checked.get("reason"),
                    "scientific_sha256": checked.get("scientific_sha256"),
                    "measurement_sha256": checked.get("measurement_sha256"),
                    "observation_count": checked.get("files", {}).get(
                        "raw_data", {}).get("observation_count")
                    if isinstance(checked.get("files"), dict) else None,
                }
                record["classification"] = (
                    "final_stage_artifacts_need_current_identity_and_validation"
                    if checked.get("available") is True
                    else "stage_run_present_but_result_not_reconciled"
                )
            elif has_successful_worker:
                record["classification"] = "worker_result_durable_stage_result_unacknowledged"
            elif any(
                    attempt.get("outcome_unknown") is True
                    for operation in record.get("nested_operation_ledger", {}).get(
                        "operations", [])
                    for attempt in operation.get("attempts", [])):
                record["classification"] = "nested_operation_outcome_unknown"
            elif stage_status in {"paused", "failed", "interrupted"}:
                record["classification"] = "interrupted_without_final_stage_result"
            elif record.get("worker_result_count", 0):
                record["classification"] = "worker_result_requires_reconciliation"
            else:
                record["classification"] = "no_durable_result_found"
            summary["inspected_count"] += 1

        return summary

    def _prior_attempt_result_history(self, stage, *, selected_topic=None, limit=24):
        """Find recent materialized results without letting empty attempts hide them."""
        if not isinstance(stage, dict) or stage.get("kind") != "experiment":
            return {"available_attempts": 0, "same_measurement_repeated": False,
                    "measurements": [], "related_results": [],
                    "materialized_attempts_scanned": 0,
                    "non_materialized_attempts_skipped": 0}
        stage_record = self.stage_records.get(stage.get("id"), {})
        attempts = stage_record.get("attempts", []) if isinstance(stage_record, dict) else []
        if not isinstance(attempts, list):
            attempts = []
        evidence_records = []
        related_results = []
        non_materialized_attempts_skipped = 0
        materialized_attempts_scanned = 0
        terminal = {"succeeded", "completed", "failed", "blocked"}
        result_limit = max(1, int(limit))
        current_question = (selected_topic.get("research_question")
                            if isinstance(selected_topic, dict) else None)
        current_topic_id = (selected_topic.get("id")
                            if isinstance(selected_topic, dict) else None)
        try:
            stage_root = Path(stage["project_dir"]).resolve()
            if stage_root.name.startswith("attempt-") and stage_root.parent.name == "attempts":
                stage_root = next((parent for parent in stage_root.parents
                                   if (parent / "continuations").is_dir()), None)
            if stage_root is None:
                raise ValueError("experiment stage root is unavailable")
        except (KeyError, OSError, RuntimeError, TypeError, ValueError):
            return {"available_attempts": 0, "same_measurement_repeated": False,
                    "measurements": [], "related_results": [],
                    "materialized_attempts_scanned": 0,
                    "non_materialized_attempts_skipped": 0,
                    "evidence_status": "stage_root_unavailable"}
        for attempt in reversed(attempts):
            if not isinstance(attempt, dict) or attempt.get("state") not in terminal:
                continue
            attempt_number = attempt.get("attempt_number")
            project_dir = attempt.get("project_dir")
            if type(attempt_number) is not int or not isinstance(project_dir, str):
                continue
            attempt_root = Path(project_dir).resolve()
            if (attempt_root.name != f"attempt-{attempt_number}"
                    or attempt_root.parent.name != "attempts"):
                continue
            try:
                attempt_root.relative_to(stage_root)
            except ValueError:
                continue
            run_path = attempt_root / "output" / "run.json"
            if run_path.is_symlink() or not run_path.is_file():
                non_materialized_attempts_skipped += 1
                continue
            materialized_attempts_scanned += 1
            run_record = _read_experiment_result_payload(
                str(run_path), base_dir=attempt_root)
            if not isinstance(run_record, dict):
                continue
            package_path = run_record.get("results_package")
            if not isinstance(package_path, str):
                continue
            package_metadata = _read_experiment_result_payload(
                package_path, base_dir=attempt_root)
            if not isinstance(package_metadata, dict):
                continue
            result_question = package_metadata.get("question")
            run_study_id = run_record.get("study_id")
            study_topic_id = (run_study_id.split("-cycle-", 1)[0]
                              if isinstance(run_study_id, str)
                              and "-cycle-" in run_study_id else None)
            attempt_topic_id = attempt.get("topic_id")
            same_topic = (
                isinstance(current_topic_id, str)
                and (attempt_topic_id == current_topic_id
                     or (attempt_topic_id is None
                         and study_topic_id == current_topic_id))
            )
            same_question = (
                isinstance(current_question, str) and result_question == current_question)
            if not same_question and not same_topic:
                continue
            if same_question and len(evidence_records) >= result_limit:
                continue
            context = {
                "stage_id": stage.get("id"),
                "attempt_number": attempt_number,
                "project_dir": str(attempt_root),
                "output_path": str(run_path),
                "results_package": package_path,
                "execution_refs": run_record.get("execution_refs"),
                "project_id": run_record.get("project_id"),
                "study_id": run_record.get("study_id"),
                "assessment_ref": run_record.get("assessment_ref"),
                "status": attempt.get("state"),
            }
            evidence = self._prior_attempt_result_evidence(
                stage, context)
            if evidence.get("available") is True:
                if same_question:
                    evidence_records.append(evidence)
                    continue
                if same_topic and isinstance(result_question, str):
                    package = evidence.get("results_package", {})
                    derived = evidence.get("derived_results", {})
                    related_results.append({
                        "attempt_number": attempt_number,
                        "study_id": run_record.get("study_id"),
                        "question": result_question,
                        "validation_decision": evidence.get("validation_decision"),
                        "observation_count": evidence.get("files", {}).get(
                            "raw_data", {}).get("observation_count"),
                        "measurement_sha256": evidence.get("measurement_sha256"),
                        "metrics": _bounded_experiment_result_projection(
                            derived.get("metrics", [])[:8]
                            if isinstance(derived.get("metrics"), list) else []),
                        "findings": _bounded_experiment_result_projection(
                            package.get("findings", [])[:4]
                            if isinstance(package.get("findings"), list) else []),
                        "limitations": _bounded_experiment_result_projection(
                            package.get("limitations", [])[:6]
                            if isinstance(package.get("limitations"), list) else []),
                        "admissible_as_current_claims": False,
                        "exclusion_reason": "research_question_mismatch",
                    })

        grouped = {}
        for evidence in evidence_records:
            fingerprint = evidence.get("measurement_sha256")
            if not isinstance(fingerprint, str):
                continue
            group = grouped.get(fingerprint)
            if group is None:
                group = {
                    "measurement_sha256": fingerprint,
                    "repeat_count": 0,
                    "attempt_numbers": [],
                    "observation_count": evidence.get("files", {}).get(
                        "raw_data", {}).get("observation_count"),
                    "metrics": evidence.get("derived_results", {}).get("metrics", []),
                    "findings": evidence.get("results_package", {}).get("findings", []),
                    "limitations": evidence.get("results_package", {}).get("limitations", []),
                    "validation_decision": evidence.get("validation_decision"),
                    "review_evidence": evidence.get("review_evidence", []),
                    "execution_refs": evidence.get("execution_refs", []),
                }
                grouped[fingerprint] = group
            group["repeat_count"] += 1
            attempt_number = evidence.get("attempt_number")
            if type(attempt_number) is int and len(group["attempt_numbers"]) < 8:
                group["attempt_numbers"].append(attempt_number)

        measurements = list(grouped.values())[:8]
        for measurement in measurements:
            measurement["identical_measurement_repeated"] = (
                measurement["repeat_count"] > 1)
        related_results.sort(key=lambda item: (
            item.get("validation_decision") not in {"accepted", "accepted_with_limitations"},
            -item["attempt_number"],
        ))
        return {
            "available_attempts": len(evidence_records),
            "same_measurement_repeated": any(
                item["repeat_count"] > 1 for item in measurements),
            "measurements": measurements,
            "related_results": related_results[:8],
            "materialized_attempts_scanned": materialized_attempts_scanned,
            "non_materialized_attempts_skipped": non_materialized_attempts_skipped,
        }

    def _build_capability_repair_packet(self, stage, topic_result, prior_context, error):
        """Assemble bounded evidence for the model-led methods repair panel."""
        selected = topic_result.get("topic") if isinstance(topic_result, dict) else {}
        selected = selected if isinstance(selected, dict) else {}
        prior_context = prior_context if isinstance(prior_context, dict) else {}
        failure_recovery_context = prior_context.get("failure_recovery")
        failure_recovery_context = (failure_recovery_context
                                    if isinstance(failure_recovery_context, dict) else {})
        failure_dossier_ref = (
            prior_context.get("failure_dossier_ref")
            or failure_recovery_context.get("dossier_ref")
        )
        expected_attempt_number = failure_recovery_context.get("attempt_number")
        if type(expected_attempt_number) is not int:
            expected_attempt_number = prior_context.get("attempt_number")
        if type(expected_attempt_number) is not int:
            expected_attempt_number = None
        dossier_evidence = None
        if isinstance(failure_dossier_ref, str):
            dossier_evidence = self._failure_dossier_evidence(
                failure_dossier_ref, expected_stage_id=stage.get("id"),
                expected_attempt_number=expected_attempt_number)
        verified_dossier = (
            dossier_evidence if isinstance(dossier_evidence, dict)
            and dossier_evidence.get("available") is True else None
        )
        subject_lineage = verified_dossier.get("repair_subject_lineage") if verified_dossier else None
        if isinstance(subject_lineage, dict):
            subject_topic = verified_dossier.get("topic_identity")
            if (not isinstance(subject_topic, dict)
                    or subject_topic.get("topic_id") != selected.get("id")
                    or subject_topic.get("research_question") != selected.get("research_question")
                    or subject_topic.get("domain") != selected.get("domain")):
                raise ValidationError("Methods repair subject belongs to a different topic")
        failure_input_sha256 = (
            verified_dossier.get("input_sha256") if verified_dossier else None
        )
        failure_attempt_number = (
            verified_dossier.get("attempt_number") if verified_dossier else None
        )
        prior_attempt_result = self._prior_attempt_result_evidence(
            stage, prior_context, selected_topic=selected)
        prior_attempt_history = self._prior_attempt_result_history(
            stage, selected_topic=selected)
        unresolved_attempt_evidence = self._unresolved_prior_attempt_evidence(
            stage, prior_context.get("unresolved_prior_attempts"),
            selected_topic=selected)
        unresolved_attempt_sources = unresolved_attempt_evidence.pop(
            "generated_sources", [])

        def is_bound_to_failure(value):
            if not verified_dossier or not isinstance(value, dict):
                return False
            lineage = value.get("failure_lineage")
            lineage = lineage if isinstance(lineage, dict) else {}
            recovery = value.get("failure_recovery")
            recovery = recovery if isinstance(recovery, dict) else {}
            dossier_ref = (
                lineage.get("failure_dossier_ref")
                or value.get("failure_dossier_ref")
                or recovery.get("dossier_ref")
            )
            attempt_number = (
                lineage.get("stage_attempt_number")
                or lineage.get("attempt_number")
                or value.get("failure_attempt_number")
                or value.get("stage_attempt_number")
                or recovery.get("attempt_number")
            )
            input_sha256 = (
                lineage.get("failure_input_sha256")
                or lineage.get("input_sha256")
                or value.get("failure_input_sha256")
                or recovery.get("failure_input_sha256")
                or recovery.get("input_sha256")
            )
            return (
                dossier_ref == failure_dossier_ref
                and type(attempt_number) is int
                and attempt_number == failure_attempt_number
                and input_sha256 == failure_input_sha256
            )

        def has_conflicting_content(value):
            if not verified_dossier:
                return False
            return failure_evidence_lineage_conflicts(
                value,
                attempt_number=failure_attempt_number,
                input_sha256=failure_input_sha256,
                dossier_ref=failure_dossier_ref,
                stage_id=stage.get("id"),
            )["conflicts"]

        failure_history = prior_context.get("specialist_reports")
        if not isinstance(failure_history, list):
            failure_history = []
        prior_reports = []
        unbound_report_count = 0
        conflicting_report_count = 0
        for report in failure_history[-8:]:
            if not is_bound_to_failure(report):
                unbound_report_count += 1
                continue
            if has_conflicting_content(report):
                conflicting_report_count += 1
                continue
            response = report.get("response") if isinstance(report.get("response"), dict) else {}
            prior_reports.append({
                "role_id": report.get("role_id"),
                "assigned_role": report.get("assigned_role"),
                "status": report.get("status"),
                "decision": response.get("decision", report.get("decision")),
                "summary": str(response.get("summary", report.get("summary", "")))[:1800],
                "findings": [str(item)[:1200] for item in response.get("findings", [])[:8]]
                if isinstance(response.get("findings"), list) else [],
                "requested_actions": [str(item)[:1200] for item in response.get("requested_actions", [])[:8]]
                if isinstance(response.get("requested_actions"), list) else [],
            })
        verifier = prior_context.get("specialist_verifier")
        verifier_present = verifier is not None
        verifier_identity_bound = is_bound_to_failure(verifier)
        verifier_content_conflicts = (
            verifier_identity_bound and has_conflicting_content(verifier))
        verifier_is_bound = verifier_identity_bound and not verifier_content_conflicts
        if not verifier_is_bound:
            verifier = None
        verifier_response = verifier.get("response") if isinstance(verifier, dict) else {}
        if not isinstance(verifier_response, dict):
            verifier_response = {}
        foundry_failure = {}
        if verified_dossier:
            source_files = verified_dossier.get("source_files")
            source_files = source_files if isinstance(source_files, dict) else {}
            last_attempt = {
                "experiment_intent": verified_dossier.get("experiment_intent"),
                "source_files": deepcopy(source_files),
            }
            source_integrity = {}
            for source_name in ("executor", "validator"):
                source_record = source_files.get(source_name)
                source_record = source_record if isinstance(source_record, dict) else {}
                source_key = f"{source_name}_source"
                source_chunks = source_record.get("source_chunks")
                if source_record.get("available") is True and isinstance(source_chunks, list):
                    last_attempt[source_key] = "".join(
                        chunk for chunk in source_chunks if isinstance(chunk, str))
                source_integrity[source_name] = {
                    "sha256": (source_record.get("expected_sha256")
                               or source_record.get("source_sha256")),
                    "characters": source_record.get("source_characters"),
                    "truncated": source_record.get("available") is not True,
                }
            last_attempt["source_integrity"] = source_integrity
            foundry_failure = {
                "status": verified_dossier.get("foundry_status") or "failed",
                "attempts": verified_dossier.get("foundry_work_attempts"),
                "feedback": verified_dossier.get("prior_foundry_feedback"),
                "validation_context": verified_dossier.get("validation_context"),
                "validation_feedback": verified_dossier.get("validation_feedback"),
                "repair_gate_counts": verified_dossier.get("repair_gate_counts"),
                "last_attempt": last_attempt,
                "cache_ref": verified_dossier.get("foundry_work_artifact_ref"),
                "cache_body_sha256": verified_dossier.get("foundry_work_body_sha256"),
                "cache_body_verified": verified_dossier.get("foundry_work_body_verified"),
                "cache_identity_verified": verified_dossier.get(
                    "foundry_work_identity_verified"),
                "failure_dossier_ref": failure_dossier_ref,
                "failure_dossier_sha256": verified_dossier.get("artifact_body_sha256"),
                "attempt_identity_verified": True,
            }
        else:
            foundry_failure = {
                "status": "unavailable",
                "failure_dossier_ref": failure_dossier_ref,
                "attempt_identity_verified": False,
                "evidence_unavailable_reason": (
                    dossier_evidence.get("reason")
                    if isinstance(dossier_evidence, dict) else
                    "The exact failure dossier could not be resolved."
                ),
            }
        repair_history = prior_context.get("experiment_repair_history")
        if not isinstance(repair_history, list):
            repair_history = []
        bound_repair_history = [
            item for item in repair_history
            if is_bound_to_failure(item) and not has_conflicting_content(item)
        ]
        unbound_repair_history_count = sum(
            1 for item in repair_history if not is_bound_to_failure(item))
        conflicting_repair_history_count = sum(
            1 for item in repair_history
            if is_bound_to_failure(item) and has_conflicting_content(item)
        )
        repair_plan = prior_context.get("experiment_repair_plan")
        repair_plan_is_bound = is_bound_to_failure(repair_plan)
        repair_plan_content_conflicts = (
            repair_plan_is_bound and has_conflicting_content(repair_plan))
        if not repair_plan_is_bound or repair_plan_content_conflicts:
            repair_plan = None
        program_snapshot = (
            deepcopy(verified_dossier.get("program_snapshot", []))
            if verified_dossier else
            self._failure_program_snapshot(stage, topic_context=topic_result)
        )
        for source in program_snapshot:
            if not isinstance(source, dict):
                continue
            if isinstance(source.get("path"), str):
                source["path"] = Path(source["path"]).name
            if isinstance(source.get("source"), str):
                source["source"] = redact_sensitive_text(source["source"])
            source.setdefault(
                "source_linkage",
                "topic_capability_source_snapshot; exact execution-source linkage is unverified",
            )
        foundry_attempt = foundry_failure.get("last_attempt")
        foundry_attempt = foundry_attempt if isinstance(foundry_attempt, dict) else {}
        candidate_source_files = foundry_attempt.get("source_files")
        candidate_source_files = (
            candidate_source_files if isinstance(candidate_source_files, dict) else {})
        exact_observed = (verified_dossier.get("scientific_observed_result",
                                             verified_dossier.get("observed_result"))
                          if verified_dossier else None)
        executed_refs = (exact_observed.get("execution_refs")
                         if isinstance(exact_observed, dict) else None)
        snapshot_hashes = {item.get("sha256") for item in program_snapshot
                           if isinstance(item, dict) and item.get("sha256")}
        source_applicability = None
        if isinstance(executed_refs, list) and executed_refs and candidate_source_files:
            source_applicability = all(
                isinstance(candidate_source_files.get(name), dict)
                and candidate_source_files[name].get("expected_sha256") in snapshot_hashes
                for name in ("executor", "validator"))
            if not source_applicability:
                # An internally valid authoring failure can precede a later
                # admitted program. Its source is not this execution's source.
                candidate_source_files = {}
                foundry_failure = {}
        exact_candidate_sources = {}
        for source_name in ("executor", "validator"):
            source_record = candidate_source_files.get(source_name)
            source_record = source_record if isinstance(source_record, dict) else {}
            chunks = source_record.get("source_chunks")
            chunks = chunks if isinstance(chunks, list) else []
            chunks = [chunk for chunk in chunks if isinstance(chunk, str)]
            reconstructed = "".join(chunks)
            prompt_sha256 = source_record.get("prompt_source_sha256")
            prompt_characters = source_record.get("prompt_source_characters")
            chunks_complete = (
                source_record.get("available") is True
                and source_record.get("integrity_verified") is True
                and source_record.get("matches_expected") is True
                and source_record.get("source_truncated") is False
                and len(chunks) == len(source_record.get("source_chunks", []))
                and len(chunks) <= 16
                and all(len(chunk) <= 7000 for chunk in chunks)
                and type(prompt_characters) is int
                and len(reconstructed) == prompt_characters
                and isinstance(prompt_sha256, str)
                and hashlib.sha256(reconstructed.encode("utf-8")).hexdigest()
                == prompt_sha256
            )
            exact_candidate_sources[source_name] = {
                "available": chunks_complete,
                "source_sha256": source_record.get("expected_sha256"),
                "source_characters": source_record.get("source_characters"),
                "prompt_source_sha256": prompt_sha256,
                "prompt_source_characters": prompt_characters,
                "redaction_applied": source_record.get("redaction_applied") is True,
                "source_chunks": chunks if chunks_complete else [],
                "omission_reason": None if chunks_complete else (
                    source_record.get("omission_reason")
                    or "The source chunks are unavailable or fail integrity verification."
                ),
            }
        failure_lineage = {
            "stage_id": stage.get("id"),
            "failure_dossier_ref": failure_dossier_ref,
            "attempt_number": failure_attempt_number,
            "failure_input_sha256": failure_input_sha256,
            "failure_dossier_body_sha256": (
                verified_dossier.get("artifact_body_sha256") if verified_dossier else None
            ),
            "identity_verified": verified_dossier is not None,
        }
        failure_recovery = {
            "dossier_ref": failure_dossier_ref,
            "attempt_number": failure_attempt_number,
            "input_sha256": failure_input_sha256,
            "identity_verified": verified_dossier is not None,
        }
        packet = {
            "schema_version": "capability-repair-packet-1",
            "stage_id": stage.get("id"),
            "continuation_cycle": self.continuation_cycles,
            "failure_lineage": failure_lineage,
            "topic": {key: selected.get(key) for key in (
                "id", "title", "domain", "research_question", "scope",
                "comparison", "measurement", "disconfirmation_test", "resource_plan",
            )},
            "failure": {
                "error": (verified_dossier.get("scientific_failure_error",
                                               verified_dossier.get("error")) if verified_dossier
                          else str(error)[:4096]),
                "prior_status": (exact_observed.get("status")
                                 if isinstance(exact_observed, dict)
                                 else prior_context.get("status")
                                 if prior_attempt_result.get("available") is True else None),
            },
            "failure_recovery": failure_recovery,
            "program_snapshot": self._capability_repair_projection(
                program_snapshot, max_text=18000),
            "observed_result": self._capability_repair_projection({
                "failure_dossier_result": exact_observed,
            } if exact_observed is not None else {}, max_text=7000),
            "failure_observed_result": self._capability_repair_projection(
                exact_observed, max_text=9000),
            "prior_attempt_result_evidence": prior_attempt_result,
            "prior_attempt_result_history": prior_attempt_history,
            "unresolved_attempt_evidence": unresolved_attempt_evidence,
            "unresolved_attempt_sources": unresolved_attempt_sources,
            "prior_foundry_work": foundry_failure,
            "foundry_source_applicable_to_execution": source_applicability,
            "exact_candidate_sources": exact_candidate_sources,
            "experiment_repair_plan": self._capability_repair_projection(
                repair_plan, max_text=4200),
            "experiment_repair_history": self._capability_repair_projection(
                bound_repair_history, max_depth=4,
                max_items=4, max_text=1800),
            "prior_specialist_reviews": prior_reports,
            "prior_verifier": {
                "available": verifier_is_bound,
                "status": verifier.get("status") if verifier_is_bound else None,
                "decision": verifier_response.get("decision"),
                "critical_findings": [str(item)[:1400]
                                       for item in verifier_response.get("critical_findings", [])[:8]]
                if isinstance(verifier_response.get("critical_findings"), list) else [],
                "repair_scope": [str(item)[:1400]
                                 for item in verifier_response.get("repair_scope", [])[:8]]
                if isinstance(verifier_response.get("repair_scope"), list) else [],
            },
            "provenance_exclusions": {
                "unbound_specialist_report_count": unbound_report_count,
                "unbound_verifier_excluded": verifier_present and not verifier_identity_bound,
                "unbound_repair_plan_excluded": (
                    prior_context.get("experiment_repair_plan") is not None
                    and not repair_plan_is_bound
                ),
                "unbound_repair_history_count": unbound_repair_history_count,
                "content_conflicting_specialist_report_count": conflicting_report_count,
                "content_conflicting_verifier_excluded": verifier_content_conflicts,
                "content_conflicting_repair_plan_excluded": repair_plan_content_conflicts,
                "content_conflicting_repair_history_count": (
                    conflicting_repair_history_count
                ),
                "policy": (
                    "Plan-review evidence is bound to failure_lineage. Candidate sources, intent, "
                    "and measurements are bound to repair_subject_lineage when present, otherwise "
                    "to failure_lineage. These identities must remain distinct; prior result packages "
                    "are separately bound to their exact "
                    "attempt directory and execution refs, remain explicitly unadmitted, and "
                    "excluded history remains in the ledger."
                ),
            },
            "repair_contract": {
                "check_phase_protocol": "repair-check-phases-1",
                "must_preserve": [
                    "the admitted topic domain", "the exact research question",
                    "the admitted primary outcome and comparison, unless a scientifically justified "
                    "change explicitly preserves the same question",
                    "valid zero, negative, and statistically inconclusive results as evidence",
                ],
                "must_change": [
                    "the mechanism or estimand responsible for the recorded failure",
                    "the validator and acceptance checks when the prior validator accepted invalid evidence",
                    "the declared design axis in experiment_repair_plan when the prior capability lineage is exhausted",
                ],
                "must_prove": [
                    "finite non-degenerate observations",
                    "an independent validator that recalculates every primary outcome",
                    "correct handling of the declared intervention, established by independent "
                    "controls rather than a required nonzero primary effect",
                ],
                "prohibited": [
                    "repeating the same executor with a renamed threshold",
                    "endpoint or NaN fallback for undefined crossings",
                    "claiming an unobserved mechanism from an analytic comparator",
                    "requiring a preferred sign, nonzero effect, statistical significance, or "
                    "null rejection to admit valid observations",
                ],
            },
        }
        if isinstance(subject_lineage, dict):
            packet["repair_subject_lineage"] = deepcopy(subject_lineage)
            packet["plan_review_failure"] = {
                "error": verified_dossier.get("error"),
                "failure_lineage": deepcopy(failure_lineage),
                "source_authority": "The current plan review failed; the candidate evidence belongs to repair_subject_lineage.",
            }
        intent = foundry_failure.get("last_attempt")
        intent = intent.get("experiment_intent") if isinstance(intent, dict) else None
        prior_measurements = [{
            "measurement_sha256": item.get("measurement_sha256"),
            "validation_decision": item.get("validation_decision"),
            "review_evidence": [{
                "reviewer_id": review.get("reviewer_id"),
                "decision": review.get("decision"),
                "adverse_checks": [{
                    "check_id": check.get("check_id"),
                    "outcome": check.get("outcome"),
                    "evidence": self._normalize_research_request_value(
                        check.get("evidence", "")),
                } for check in review.get("adverse_checks", [])
                  if isinstance(check, dict)],
                "adverse_findings": [{
                    "finding_id": finding.get("finding_id"),
                    "outcome": finding.get("outcome"),
                    "rationale": self._normalize_research_request_value(
                        finding.get("rationale", "")),
                } for finding in review.get("adverse_findings", [])
                  if isinstance(finding, dict)],
            } for review in item.get("review_evidence", [])
              if isinstance(review, dict)],
        } for item in prior_attempt_history.get("measurements", [])
          if isinstance(item, dict)]
        prior_measurements.sort(key=canonical_bytes)
        survey_refs = {
            key: prior_context.get(key)
            for key in ("survey_ref", "assessment_ref", "survey_evidence_ref",
                        "gap_assessment_ref", "source_survey_ref")
            if isinstance(prior_context.get(key), str)
        }
        unresolved_identity = []
        unresolved_records = unresolved_attempt_evidence.get("records", {})
        unresolved_records = unresolved_records if isinstance(unresolved_records, dict) else {}
        unresolved_workers = unresolved_attempt_evidence.get("worker_results", {})
        unresolved_workers = unresolved_workers if isinstance(unresolved_workers, dict) else {}
        for key, record in sorted(unresolved_records.items()):
            if not isinstance(record, dict):
                continue
            if record.get("classification") == "attempt_directory_missing":
                continue
            run = record.get("stage_run")
            run = run if isinstance(run, dict) else {}
            stage_check = record.get("stage_result_check")
            stage_check = stage_check if isinstance(stage_check, dict) else {}
            operation_ledger = record.get("nested_operation_ledger")
            operation_ledger = operation_ledger if isinstance(operation_ledger, dict) else {}
            operations = operation_ledger.get("operations", [])
            operations = operations if isinstance(operations, list) else []
            worker_summary = []
            worker_records = unresolved_workers.get(key, [])
            worker_records = worker_records if isinstance(worker_records, list) else []
            for worker in worker_records[:8]:
                if not isinstance(worker, dict):
                    continue
                ledger = worker.get("task_ledger")
                ledger = ledger if isinstance(ledger, dict) else {}
                summary = {name: worker.get(name) for name in (
                    "task_id", "result_sha256", "ok", "operation_outcome", "study_id",
                    "process_returncode", "capture_truncated", "capture_incomplete",
                    "observation_count", "metric_count")}
                summary["task_state"] = ledger.get("task_state")
                summary["attempt_states"] = ledger.get("attempt_states")
                worker_summary.append(summary)
            unresolved_identity.append({
                "attempt_number": record.get("attempt_number"),
                "cycle": record.get("cycle"),
                "attempt_state": record.get("attempt_state"),
                "classification": record.get("classification"),
                "external_ref_recorded": record.get("external_ref_recorded"),
                "stage_run": {name: run.get(name) for name in (
                    "status", "results_package_present", "execution_ref_count")},
                "stage_result_check": {name: stage_check.get(name) for name in (
                    "available", "reason", "scientific_sha256", "measurement_sha256",
                    "observation_count")},
                "nested_operations": [{
                    "task_id": operation.get("task_id"),
                    "operation": operation.get("operation"),
                    "task_state": operation.get("task_state"),
                    "attempts": operation.get("attempts", []),
                } for operation in operations if isinstance(operation, dict)],
                "generated_program_hashes": [
                    program.get("sha256") for program in record.get(
                        "generated_programs", [])
                    if isinstance(program, dict) and isinstance(program.get("sha256"), str)
                ],
                "workers": worker_summary,
            })
        unresolved_identity.sort(key=lambda item: (
            item.get("attempt_number") if type(item.get("attempt_number")) is int else -1,
            item.get("cycle") if type(item.get("cycle")) is int else -1,
        ))
        unresolved_source_identity = [{name: source.get(name) for name in (
            "source_sha256", "prompt_source_sha256", "source_available",
            "execution_link_verified",
        ) if name in source}
            for source in unresolved_attempt_sources if isinstance(source, dict)]
        packet["experiment_intent"] = deepcopy(intent)
        packet["survey_evidence_refs"] = deepcopy(survey_refs)
        packet["prior_measurements"] = deepcopy(prior_measurements)
        packet["review_input_sha256"] = self._capability_repair_review_input_sha256(packet)
        packet["science_input_sha256"] = hashlib.sha256(canonical_bytes({
            "stage_id": stage.get("id"),
            "topic": packet.get("topic"),
            "experiment_intent": intent,
            "candidate_sources": {
                name: {
                    "available": record.get("available") is True,
                    "source_sha256": record.get("source_sha256"),
                    "prompt_source_sha256": record.get("prompt_source_sha256"),
                }
                for name, record in exact_candidate_sources.items()
            },
            "program_snapshot": [{
                "sha256": item.get("sha256"),
                "size_bytes": item.get("size_bytes"),
            } for item in program_snapshot if isinstance(item, dict)],
            "survey_refs": survey_refs,
            "failure": {
                "observed_status": packet.get("failure", {}).get("prior_status"),
                "recovery_mode": failure_recovery_context.get("recovery_mode"),
                "failure_class": failure_recovery_context.get("failure_class"),
            },
            "current_result": {
                "available": prior_attempt_result.get("available") is True,
                "scientific_sha256": prior_attempt_result.get("scientific_sha256"),
                "validation_decision": prior_attempt_result.get("validation_decision"),
            },
            "prior_measurements": prior_measurements,
            "review_evidence": prior_reports,
            "repair_plan": self._normalize_research_request_value(
                packet.get("experiment_repair_plan", {})),
            "repair_history": self._normalize_research_request_value(
                packet.get("experiment_repair_history", [])),
            "prior_verifier": self._normalize_research_request_value(
                packet.get("prior_verifier", {})),
            "validation_feedback": self._normalize_research_request_value(
                foundry_failure.get("validation_feedback", {})),
            "unresolved_execution_evidence": unresolved_identity,
            "unresolved_execution_sources": unresolved_source_identity,
        })).hexdigest()
        packet = self._capability_repair_projection(
            packet, max_depth=9, max_text=CAPABILITY_REPAIR_SOURCE_CHARS)
        semantic_packet = deepcopy(packet)
        semantic_packet["repair_prompt_revision"] = CAPABILITY_REPAIR_PANEL_PROMPT_REVISION
        semantic_packet.pop("continuation_cycle", None)
        semantic_packet["failure_lineage"] = {
            "stage_id": stage.get("id"),
            "identity_verified": bool(verified_dossier),
        }
        semantic_packet["failure_recovery"] = {
            "identity_verified": bool(verified_dossier),
        }
        semantic_packet["provenance_exclusions"] = {}
        semantic_packet["prior_attempt_result_evidence"] = {
            "available": prior_attempt_result.get("available") is True,
            "scientific_sha256": prior_attempt_result.get("scientific_sha256"),
            "admissible_as_verified_claims": False,
        }
        semantic_packet["prior_attempt_result_history"] = {
            "same_measurement_repeated": prior_attempt_history.get(
                "same_measurement_repeated") is True,
            "measurements": [{
                "measurement_sha256": item.get("measurement_sha256"),
                "validation_decision": item.get("validation_decision"),
                "review_evidence": [{
                    "reviewer_id": review.get("reviewer_id"),
                    "decision": review.get("decision"),
                    "adverse_checks": [{
                        "check_id": check.get("check_id"),
                        "outcome": check.get("outcome"),
                        "evidence": self._normalize_research_request_value(
                            check.get("evidence", "")),
                    } for check in review.get("adverse_checks", [])
                      if isinstance(check, dict)],
                    "adverse_findings": [{
                        "finding_id": finding.get("finding_id"),
                        "outcome": finding.get("outcome"),
                        "rationale": self._normalize_research_request_value(
                            finding.get("rationale", "")),
                    } for finding in review.get("adverse_findings", [])
                      if isinstance(finding, dict)],
                } for review in item.get("review_evidence", [])
                  if isinstance(review, dict)],
            } for item in prior_attempt_history.get("measurements", [])
              if isinstance(item, dict)],
            "related_results": [{
                "attempt_number": item.get("attempt_number"),
                "question": item.get("question"),
                "validation_decision": item.get("validation_decision"),
                "measurement_sha256": item.get("measurement_sha256"),
                "admissible_as_current_claims": False,
            } for item in prior_attempt_history.get("related_results", [])
              if isinstance(item, dict)],
        }
        semantic_packet["unresolved_attempt_evidence"] = unresolved_identity
        semantic_packet["program_snapshot"] = [
            {key: source.get(key) for key in ("sha256", "size_bytes", "source")
             if key in source}
            for source in program_snapshot if isinstance(source, dict)
        ]
        packet["input_sha256"] = hashlib.sha256(
            canonical_bytes(semantic_packet)).hexdigest()
        return packet

    @staticmethod
    def _validated_capability_repair_plan(report, packet):
        """Accept one lineage-bound methods plan, never a bundle of suggestions."""
        if not isinstance(report, dict):
            return None, "the methods lead report is unavailable"
        response = report.get("response") if isinstance(report, dict) else None
        response = response if isinstance(response, dict) else {}
        raw = response.get("raw") if isinstance(response.get("raw"), dict) else {}
        plan = raw.get("repair_plan")
        if report.get("status") != "succeeded" or response.get("decision") != "repair":
            if report.get("status") != "succeeded" and report.get("error"):
                return None, f"the methods lead could not produce a plan: {report['error']}"
            return None, "the methods lead did not issue a repair decision"
        if not isinstance(plan, dict):
            return None, "the methods lead did not provide a substantive repair plan"
        expected_lineage = packet.get("failure_lineage")
        expected_lineage = expected_lineage if isinstance(expected_lineage, dict) else {}
        required_lineage = (
            "stage_id", "failure_dossier_ref", "attempt_number", "failure_input_sha256")
        expected_hash = expected_lineage.get("failure_input_sha256")
        if (expected_lineage.get("identity_verified") is not True
                or not isinstance(expected_lineage.get("stage_id"), str)
                or not isinstance(expected_lineage.get("failure_dossier_ref"), str)
                or type(expected_lineage.get("attempt_number")) is not int
                or not isinstance(expected_hash, str) or len(expected_hash) != 64
                or any(character not in "0123456789abcdef" for character in expected_hash)):
            return None, "the current failure dossier identity is not verified"
        topic = packet.get("topic") if isinstance(packet.get("topic"), dict) else {}
        if not isinstance(topic.get("id"), str) or not topic["id"].strip():
            return None, "the admitted topic identity is not verified"
        if "topic_id" in plan and plan.get("topic_id") != topic["id"]:
            return None, "the repair plan changes or omits the admitted topic identity"
        if plan.get("disposition") != "repair":
            return None, "the methods lead requested evidence or declined a repair"
        root_cause = plan.get("root_cause")
        if not isinstance(root_cause, dict):
            return None, "the repair plan has no evidence-bound root cause"
        statement = root_cause.get("statement")
        evidence = root_cause.get("evidence")
        if (not isinstance(statement, str) or not statement.strip()
                or not isinstance(evidence, list)
                or not evidence
                or any(not isinstance(item, str) or not item.strip() for item in evidence)):
            return None, "the root cause is missing a concrete evidence link"
        if len(evidence) > 8:
            return None, "the repair plan has more than 8 root-cause evidence links"
        changes = plan.get("required_changes")
        if not isinstance(changes, list) or not changes:
            return None, "the repair plan has no selected source or design change"
        if len(changes) > 6:
            return None, "the repair plan has more than 6 selected changes"
        normalized_changes = []
        for change in changes:
            if not isinstance(change, dict):
                return None, "a selected repair change is not a structured instruction"
            fields = {key: change.get(key) for key in (
                "target", "instruction", "scientific_basis", "source_refs")}
            if any(not isinstance(fields[key], str) or not fields[key].strip()
                   for key in ("target", "instruction", "scientific_basis")):
                return None, "a selected repair change lacks its target, instruction, or scientific basis"
            if "source_refs" not in change:
                fields["source_refs"] = []
            if not isinstance(fields["source_refs"], list) or len(fields["source_refs"]) > 6 or any(
                    not isinstance(item, str) for item in fields["source_refs"]):
                return None, "a selected repair change has invalid source references"
            normalized_changes.append(deepcopy(fields))
        checks = plan.get("acceptance_checks", [])
        if not isinstance(checks, list):
            return None, "the repair plan has invalid acceptance checks"
        if any(key in plan for key in ("plan_acceptance_checks", "execution_acceptance_checks", "deferred_gates")):
            return None, "repair checks must use acceptance_checks entries with explicit phase and check"
        repair_contract = packet.get("repair_contract")
        repair_contract = repair_contract if isinstance(repair_contract, dict) else {}
        if ("check_phase_protocol" in repair_contract
                and repair_contract["check_phase_protocol"] != "repair-check-phases-1"):
            return None, "the repair contract has an unsupported check phase protocol"
        mandatory_checks = repair_contract.get("must_prove", [])
        if not isinstance(mandatory_checks, list):
            return None, "the repair contract has an invalid must_prove list"
        normalized_checks = []
        explicit_phases = repair_contract.get("check_phase_protocol") == "repair-check-phases-1"
        if any(isinstance(value, dict) for value in checks) and any(isinstance(value, str) for value in checks):
            return None, "the repair plan mixes legacy and phase-owned acceptance checks"
        for value in checks:
            if isinstance(value, str) and not explicit_phases and value.strip():
                normalized = {"phase": "execution", "check": value}
            elif (isinstance(value, dict) and set(value) == {"phase", "check"}
                  and value.get("phase") in ("plan", "execution")
                  and isinstance(value.get("check"), str) and value["check"].strip()):
                normalized = deepcopy(value)
            else:
                return None, "the repair plan has an invalid phase-owned acceptance check"
            if any(item["check"] == normalized["check"] and item["phase"] != normalized["phase"]
                   for item in normalized_checks):
                return None, "an acceptance check has conflicting phase ownership"
            if normalized not in normalized_checks:
                normalized_checks.append(normalized)
        for value in mandatory_checks:
            if not isinstance(value, str) or not value.strip():
                return None, "the repair contract has an invalid must_prove check"
            normalized = {"phase": "execution", "check": value}
            if any(item["check"] == value and item["phase"] != "execution" for item in normalized_checks):
                return None, "a mandatory execution check has conflicting phase ownership"
            if normalized not in normalized_checks:
                normalized_checks.append(normalized)
        if not normalized_checks:
            return None, "the repair plan has no falsifiable acceptance checks"
        if len(normalized_checks) > 16:
            return None, "the bounded repair contract has more than 16 acceptance checks"
        uncertainties = plan.get("residual_uncertainties", [])
        if (not isinstance(uncertainties, list) or len(uncertainties) > 8
                or any(not isinstance(item, str) for item in uncertainties)):
            return None, "the repair plan has invalid residual uncertainties"
        return {
            "schema_version": "experiment-repair-adjudication-2",
            "topic_id": topic.get("id"),
            "failure_lineage": {key: expected_lineage.get(key)
                                for key in required_lineage},
            "disposition": "repair",
            "root_cause": {
                "statement": statement,
                "evidence": deepcopy(evidence),
            },
            "required_changes": normalized_changes,
            "acceptance_checks": normalized_checks,
            # Reviewer reports and cited evidence are the audit trail. Free-form
            # attribution prose is not an admission field: an inaccurate paraphrase
            # must not veto an otherwise evidence-bound experimental design.
            "dissent_resolution": [],
            "residual_uncertainties": deepcopy(uncertainties),
        }, None

    @staticmethod
    def _capability_repair_verdict(repair_plan, verifier):
        """Require independent acceptance before any replacement code can run.

        A pre-execution hold is feedback for revising the plan, not an uncertainty
        that can be deferred until after the proposed design has already run.
        """
        if not isinstance(repair_plan, dict) or not isinstance(verifier, dict):
            return "hold", []
        response = verifier.get("response")
        response = response if isinstance(response, dict) else {}
        if verifier.get("status") != "succeeded":
            return "hold", []
        decision = response.get("decision")
        blocking = response.get("blocking_findings")
        if not isinstance(blocking, list):
            blocking = response.get("critical_findings")
        blocking = blocking if isinstance(blocking, list) else []
        required_revisions = response.get("required_revisions")
        required_revisions = required_revisions if isinstance(required_revisions, list) else []
        concerns = list(dict.fromkeys(
            str(item).strip()[:1600] for item in [*blocking, *required_revisions]
            if isinstance(item, str) and item.strip()
        ))
        if decision == "accept" and not concerns:
            return "repair", []
        if not concerns:
            rationale = response.get("rationale")
            if isinstance(rationale, str) and rationale.strip():
                concerns.append(rationale.strip()[:1600])
        return "hold", concerns[:8]

    @staticmethod
    def _capability_repair_verifier_unavailable_reason(verifier):
        """Keep transport/format failures distinct from an actual scientific hold."""
        if isinstance(verifier, dict) and verifier.get("status") == "succeeded":
            return None
        if not isinstance(verifier, dict):
            return "independent verifier produced no usable verdict"
        error = verifier.get("error")
        if isinstance(error, str) and error.strip():
            return f"independent verifier produced no usable verdict: {error.strip()[:1000]}"
        status = verifier.get("status")
        return (f"independent verifier produced no usable verdict (status={status})"
                if status else "independent verifier produced no usable verdict")

    @staticmethod
    def _capability_repair_lead_input_digest(packet, reports, prior_plan_review=None):
        """Invalidate cached lead output when a verifier requires plan revision."""
        return hashlib.sha256(canonical_bytes({
            "prompt_revision": CAPABILITY_REPAIR_PANEL_PROMPT_REVISION,
            "packet_input_sha256": packet.get("input_sha256"),
            "prior_plan_review": prior_plan_review,
            "reviewer_reports": [{
                "role_id": item.get("role_id"),
                "status": item.get("status"),
                "response": item.get("response"),
            } for item in reports if isinstance(item, dict)],
        })).hexdigest()

    @classmethod
    def _repair_plan_from_reconciled_reports(cls, reports, packet):
        """Normalize an explicit Methods repair decision without adding claims.

        Older checkpoints stored the lead's decision and actions under the
        generic specialist response schema, which prohibited the nested
        ``repair_plan`` key.  This adapter preserves the lead's selected
        action and reviewer evidence, then binds it to the current failure
        dossier.  The independent verifier still has to accept the plan.
        """
        if not isinstance(reports, list) or not isinstance(packet, dict):
            return None
        contract = packet.get("repair_contract")
        if isinstance(contract, dict) and "check_phase_protocol" in contract:
            return None
        normalized_reports = []
        for report in reports:
            if not isinstance(report, dict) or report.get("status") != "succeeded":
                continue
            response = report.get("response")
            response = response if isinstance(response, dict) else {}
            raw = response.get("raw")
            raw = raw if isinstance(raw, dict) else {}
            normalized_reports.append({
                **report,
                "response": {
                    **response,
                    "decision": response.get("decision", report.get("decision")),
                    "summary": response.get("summary", report.get("summary", "")),
                    "findings": response.get("findings", report.get("findings", [])),
                    "requested_actions": response.get(
                        "requested_actions", report.get("requested_actions", [])),
                    "raw": raw,
                },
            })
        lead = next((item for item in reversed(normalized_reports)
                     if item.get("role_id") == "methodologist"), None)
        if lead is None or lead["response"].get("decision") != "repair":
            return None
        corroborating = [item for item in normalized_reports
                         if item.get("role_id") not in {
                             "methodologist", "adversarial-reviewer",
                         }
                         and item["response"].get("decision") == "repair"
                         and item["response"].get("findings")]
        if len(corroborating) < 2:
            return None

        lead_response = lead["response"]
        if "repair_plan" in lead_response or "repair_plan" in lead_response.get("raw", {}):
            return None
        summary = lead_response.get("summary")
        summary = summary.strip() if isinstance(summary, str) else ""
        if not summary:
            return None
        raw_actions = lead_response.get("raw", {}).get("requested_actions")
        if not isinstance(raw_actions, list):
            raw_actions = lead_response.get("requested_actions")
        if not isinstance(raw_actions, list):
            return None

        changes = []
        explicit_checks = []
        for value in raw_actions[:3]:
            action = value if isinstance(value, dict) else None
            if action is None and isinstance(value, str):
                try:
                    parsed = ast.literal_eval(value)
                except (SyntaxError, ValueError):
                    parsed = None
                action = parsed if isinstance(parsed, dict) else None
            if isinstance(action, dict):
                instruction = action.get("instruction", action.get("action"))
                check = action.get("check", action.get("completion_check"))
                target = action.get("target", "experiment design")
                scientific_basis = action.get("scientific_basis", summary)
                source_refs = action.get("source_refs", [])
            else:
                instruction = value
                check = None
                target = "experiment design"
                scientific_basis = summary
                source_refs = []
            if not isinstance(instruction, str) or not instruction.strip():
                continue
            if not isinstance(target, str) or not target.strip():
                target = "experiment design"
            if not isinstance(scientific_basis, str) or not scientific_basis.strip():
                scientific_basis = summary
            if not isinstance(source_refs, list):
                source_refs = []
            source_refs = [str(item)[:300] for item in source_refs[:6]
                           if isinstance(item, str) and item.strip()]
            if not source_refs:
                exact_sources = packet.get("exact_candidate_sources")
                exact_sources = exact_sources if isinstance(exact_sources, dict) else {}
                source_refs = [
                    f"{name}:{record['source_sha256']}"
                    for name, record in exact_sources.items()
                    if name in {"executor", "validator"}
                    and isinstance(record, dict)
                    and isinstance(record.get("source_sha256"), str)
                ]
            changes.append({
                "target": target[:300],
                "instruction": instruction.strip()[:1600],
                "scientific_basis": scientific_basis.strip()[:1600],
                "source_refs": source_refs,
            })
            if isinstance(check, str) and check.strip():
                explicit_checks.append(check.strip()[:1200])
        if not changes:
            return None

        repair_contract = packet.get("repair_contract")
        repair_contract = repair_contract if isinstance(repair_contract, dict) else {}
        mandatory_checks = repair_contract.get("must_prove", [])
        if not isinstance(mandatory_checks, list):
            return None
        checks = []
        for item in [*explicit_checks[:3], *mandatory_checks]:
            if isinstance(item, str) and item.strip() and item.strip() not in checks:
                checks.append(item.strip()[:1200])
        if not checks:
            return None

        evidence = []
        for item in (lead, *corroborating):
            response = item["response"]
            findings = response.get("findings")
            if not isinstance(findings, list):
                continue
            for finding in findings:
                if isinstance(finding, str) and finding.strip() and finding not in evidence:
                    evidence.append(finding.strip()[:1400])
                if len(evidence) == 6:
                    break
            if len(evidence) == 6:
                break
        if not evidence:
            return None

        topic = packet.get("topic") if isinstance(packet.get("topic"), dict) else {}
        lineage = packet.get("failure_lineage")
        lineage = lineage if isinstance(lineage, dict) else {}
        candidate = {
            "schema_version": "experiment-repair-adjudication-1",
            "topic_id": topic.get("id"),
            "failure_lineage": {
                key: lineage.get(key) for key in (
                    "stage_id", "failure_dossier_ref", "attempt_number",
                    "failure_input_sha256",
                )
            },
            "disposition": "repair",
            "root_cause": {"statement": summary[:1800], "evidence": evidence[:6]},
            "required_changes": changes[:3],
            "acceptance_checks": [{"phase": "execution", "check": value} for value in checks],
        }
        adapted_report = {
            "status": "succeeded",
            "response": {"decision": "repair", "raw": {"repair_plan": candidate}},
        }
        plan, _error = cls._validated_capability_repair_plan(adapted_report, packet)
        return plan

    @classmethod
    def _capability_repair_plan_admitted(cls, panel):
        """Only cache a repair panel as complete when its plan passed review."""
        if (not isinstance(panel, dict) or panel.get("status") != "completed"
                or panel.get("decision") != "repair"
                or not isinstance(panel.get("repair_plan"), dict)):
            return False
        packet = panel.get("packet")
        if (not isinstance(packet, dict)
                or packet.get("input_sha256") != panel.get("input_sha256")):
            return False
        validated, error = cls._validated_capability_repair_plan({
            "status": "succeeded",
            "response": {
                "decision": "repair",
                "raw": {"repair_plan": panel["repair_plan"]},
            },
        }, packet)
        if error is not None or validated is None:
            return False
        verifier = panel.get("verifier")
        blocking = (verifier.get("blocking_findings")
                    if isinstance(verifier, dict) else None)
        if not isinstance(blocking, list):
            blocking = verifier.get("critical_findings", []) \
                if isinstance(verifier, dict) else []
        required_revisions = (verifier.get("required_revisions", [])
                              if isinstance(verifier, dict) else [])
        return (
            isinstance(verifier, dict)
            and verifier.get("status") == "succeeded"
            and verifier.get("decision") == "accept"
            and not blocking
            and not required_revisions
        )

    @classmethod
    def _capability_repair_review_input_sha256(cls, packet):
        """Fingerprint only question-bound scientific evidence for reviewer reuse.

        Failure dossier IDs, continuation counters, repair plans, reviewer prose, and
        task-state transitions are administrative/adjudication state. They must not
        invalidate independent reviews when no research evidence changed.
        """
        if not isinstance(packet, dict):
            return None
        topic = packet.get("topic")
        topic = topic if isinstance(topic, dict) else {}
        foundry = packet.get("prior_foundry_work")
        foundry = foundry if isinstance(foundry, dict) else {}
        last_attempt = foundry.get("last_attempt")
        last_attempt = last_attempt if isinstance(last_attempt, dict) else {}
        intent = packet.get("experiment_intent")
        if intent is None:
            intent = last_attempt.get("experiment_intent")

        sources = packet.get("exact_candidate_sources")
        sources = sources if isinstance(sources, dict) else {}
        source_identity = {
            str(name): {
                "available": record.get("available") is True,
                "source_sha256": record.get("source_sha256"),
                "prompt_source_sha256": record.get("prompt_source_sha256"),
            }
            for name, record in sources.items() if isinstance(record, dict)
        }
        programs = packet.get("program_snapshot")
        programs = programs if isinstance(programs, list) else []
        program_identity = [
            {key: item.get(key) for key in ("sha256", "size_bytes") if key in item}
            for item in programs if isinstance(item, dict)
        ]

        result = packet.get("prior_attempt_result_evidence")
        result = result if isinstance(result, dict) else {}
        result_identity = {key: result.get(key) for key in (
            "available", "scientific_sha256", "measurement_sha256",
            "observation_count",
        ) if key in result}

        history = packet.get("prior_attempt_result_history")
        history = history if isinstance(history, dict) else {}
        measurements = packet.get("prior_measurements")
        if not isinstance(measurements, list):
            measurements = history.get("measurements")
        measurements = measurements if isinstance(measurements, list) else []
        measurement_identity = [{"measurement_sha256": item.get("measurement_sha256")}
                                for item in measurements
                                if isinstance(item, dict)
                                and isinstance(item.get("measurement_sha256"), str)]
        related = history.get("related_results")
        related = related if isinstance(related, list) else []
        related_identity = [{key: item.get(key) for key in (
            "question", "measurement_sha256",
        ) if key in item} for item in related if isinstance(item, dict)]

        unresolved = packet.get("unresolved_attempt_evidence")
        unresolved = unresolved if isinstance(unresolved, dict) else {}
        unresolved_sources = packet.get("unresolved_attempt_sources")
        unresolved_sources = unresolved_sources if isinstance(unresolved_sources, list) else []
        records = unresolved.get("records")
        records = records if isinstance(records, dict) else {}
        worker_results = unresolved.get("worker_results")
        worker_results = worker_results if isinstance(worker_results, dict) else {}
        material_attempts = []
        for key, record in records.items():
            if not isinstance(record, dict):
                continue
            if record.get("classification") == "attempt_directory_missing":
                continue
            check = record.get("stage_result_check")
            check = check if isinstance(check, dict) else {}
            stage_result = ({name: check.get(name) for name in (
                "scientific_sha256", "measurement_sha256", "observation_count",
            ) if name in check} if check.get("available") is True else None)
            run = record.get("stage_run")
            run = run if isinstance(run, dict) else {}
            run_result = ({name: run.get(name) for name in (
                "results_package_present", "execution_ref_count",
            ) if name in run} if run.get("results_package_present")
                          or run.get("execution_ref_count", 0) else None)

            nested = record.get("nested_operation_ledger")
            nested = nested if isinstance(nested, dict) else {}
            operations = nested.get("operations")
            operations = operations if isinstance(operations, list) else []
            operation_identity = []
            for operation in operations:
                if not isinstance(operation, dict):
                    continue
                attempts = operation.get("attempts")
                attempts = attempts if isinstance(attempts, list) else []
                attempt_identity = [{name: item.get(name) for name in (
                    "outcome_unknown", "external_ref_recorded", "accounting",
                ) if name in item} for item in attempts if isinstance(item, dict)]
                operation_identity.append({
                    "operation": operation.get("operation"),
                    "attempts": attempt_identity,
                })
            operation_identity.sort(key=canonical_bytes)

            workers = worker_results.get(key)
            if not isinstance(workers, list):
                workers = record.get("worker_results")
            workers = workers if isinstance(workers, list) else []
            worker_identity = [{name: worker.get(name) for name in (
                "result_sha256", "ok", "operation_outcome", "process_returncode",
                "capture_truncated", "capture_incomplete", "observation_count",
                "metric_count",
            ) if name in worker} for worker in workers if isinstance(worker, dict)]
            worker_identity.sort(key=canonical_bytes)
            generated = record.get("generated_program_hashes")
            if not isinstance(generated, list):
                generated = record.get("generated_programs")
                generated = [item.get("sha256") for item in generated
                             if isinstance(item, dict)] if isinstance(generated, list) else []
            generated = sorted(item for item in generated if isinstance(item, str))
            if (stage_result or run_result or operation_identity or worker_identity
                    or generated):
                material_attempts.append({
                    "external_ref_recorded": record.get("external_ref_recorded") is True,
                    "stage_result": stage_result,
                    "run_result": run_result,
                    "operations": operation_identity,
                    "workers": worker_identity,
                    "generated_program_hashes": generated,
                })
        material_attempts.sort(key=canonical_bytes)
        deduplicated_attempts = []
        seen_attempts = set()
        for item in material_attempts:
            encoded = canonical_bytes(item)
            if encoded not in seen_attempts:
                seen_attempts.add(encoded)
                deduplicated_attempts.append(item)

        survey_refs = packet.get("survey_evidence_refs")
        if not isinstance(survey_refs, dict):
            survey_refs = packet.get("survey_refs")
        survey_refs = survey_refs if isinstance(survey_refs, dict) else {}
        evidence = {
            "contract_revision": CAPABILITY_REPAIR_REVIEW_EVIDENCE_REVISION,
            "topic": {key: topic.get(key) for key in (
                "id", "title", "domain", "research_question", "scope",
                "comparison", "measurement", "disconfirmation_test", "resource_plan",
            )},
            "experiment_intent": intent,
            "candidate_sources": source_identity,
            "program_snapshot": program_identity,
            "survey_refs": survey_refs,
            "current_result": result_identity,
            "prior_measurements": measurement_identity,
            "related_results": related_identity,
            "unresolved_material_evidence": deduplicated_attempts,
            "unresolved_execution_sources": [{name: source.get(name) for name in (
                "source_sha256", "prompt_source_sha256", "source_available",
                "execution_link_verified",
            ) if name in source}
                for source in unresolved_sources if isinstance(source, dict)],
        }
        return hashlib.sha256(canonical_bytes(evidence)).hexdigest()

    @staticmethod
    def _capability_repair_reports_reusable(panel):
        """Check whether any independent, evidence-bound reviewer report can be reused."""
        if not isinstance(panel, dict):
            return False
        reports = panel.get("reports")
        if not isinstance(reports, list):
            return False
        completed_roles = {
            item.get("role_id") for item in reports
            if isinstance(item, dict)
            and item.get("role_id") in {
                "statistical-reviewer", "reproducibility-reviewer", "analysis-reviewer",
            }
            and item.get("status") == "succeeded"
            and isinstance(item.get("summary"), str)
            and item.get("summary").strip()
        }
        return bool(completed_roles)

    @staticmethod
    def _capability_repair_cached_reports(panel):
        reports = panel.get("reports") if isinstance(panel, dict) else None
        if not isinstance(reports, list):
            return {}
        reusable_roles = {
            "statistical-reviewer", "reproducibility-reviewer", "analysis-reviewer",
        }
        cached = {}
        for item in reports:
            if (not isinstance(item, dict)
                    or item.get("role_id") not in reusable_roles
                    or item.get("status") != "succeeded"
                    or not isinstance(item.get("summary"), str)
                    or not item["summary"].strip()):
                continue
            cached[item["role_id"]] = deepcopy(item)
        return cached

    def _owned_repair_evidence_execution(self, ref, plan_ref, *, verifier=False):
        manifest, digest, body = self._read_verified_artifact_json(ref)
        _, _, plan = self._read_verified_artifact_json(plan_ref)
        task = self.tasks.get(body.get("task_id"))
        payload = task.get("payload", {})
        row = next((item for item in plan.get("assignments", [])
                    if item.get("task_id") == body.get("task_id")), None)
        schema = "specialist-verifier-execution-1" if verifier else "specialist-execution-1"
        if (body.get("schema_version") != schema or not isinstance(row, dict)
                or body.get("project_id") != self.workflow["project_id"]
                or plan.get("schema_version") != "department-stage-assignment-1"
                or plan.get("project_id") != self.workflow["project_id"]
                or manifest.get("author") != body.get("assigned_role")
                or body.get("stage_id") != plan.get("stage_id")
                or body.get("attempt_number") != plan.get("attempt_number")
                or any(row.get(key) != body.get(key) for key in ("assignment_id", "assigned_role", "task_id"))
                or any(payload.get(key) != body.get(key) for key in
                       ("assignment_id", "assigned_role", "stage_id", "attempt_number"))
                or payload.get("input_ref") != plan.get("input_ref")
                or (not verifier and body.get("input_ref") != plan.get("input_ref"))):
            raise ValidationError("Methods evidence execution has no exact owned assignment")
        attempts = self.tasks.attempts_for_task(body["task_id"])
        report = body.get("report", {})
        if report.get("status") == "succeeded" and not any(
                item.get("state") == "succeeded" or (item.get("state") == "cancelled"
                and report.get("provider_call_reused") is True) for item in attempts):
            raise ValidationError("Methods evidence execution has no observed successful attempt")
        return manifest, digest, body, plan, task

    def _retained_capability_evidence_actions(self, stage, packet):
        """Recover owned HOLD actions even when a later plan omitted them."""
        rows = self.control._conn.execute(
            "SELECT artifact_ref FROM artifacts WHERE artifact_type='progress_checkpoint' "
            "AND logical_id LIKE 'command/composer/checkpoints/%' ORDER BY created_at DESC,version DESC").fetchall()
        pending, seen = [], set()
        for row in rows:
            manifest, _, checkpoint = self._read_verified_artifact_json(row["artifact_ref"])
            if (manifest.get("author") != "command.composer"
                    or checkpoint.get("workflow_id") != self.workflow["id"]):
                continue
            context = checkpoint.get("context", {}).get(stage["id"], {})
            panel = context.get("capability_repair_panel") if isinstance(context, dict) else None
            if not isinstance(panel, dict) or panel.get("repair_plan") is not None:
                continue
            origin = panel.get("evidence_origin_packet", panel.get("packet", {}))
            if any((origin.get("topic") or {}).get(key) != (packet.get("topic") or {}).get(key)
                   for key in ("id", "domain", "research_question")):
                continue
            lead = next((item for item in panel.get("reports", []) if isinstance(item, dict)
                         and item.get("role_id") == "methodologist" and item.get("decision") == "hold"
                         and item.get("requested_actions")), None)
            if not isinstance(lead, dict):
                continue
            if lead.get("artifact_ref") in seen:
                continue
            seen.add(lead.get("artifact_ref"))
            _, _, execution, _, _ = self._owned_repair_evidence_execution(
                lead["artifact_ref"], panel.get("ledger", {}).get("assignment_plan_ref"))
            if (execution.get("report", {}).get("response", {}).get("requested_actions") != lead["requested_actions"]
                    or origin.get("failure_lineage", {}).get("stage_id") != stage["id"]):
                raise ValidationError("retained Methods evidence action changes its owned scope")
            self._verify_repair_evidence_origin(execution, origin)
            selected = deepcopy(panel)
            selected["evidence_origin_packet"] = deepcopy(origin)
            pending.append(selected)
        return pending

    @staticmethod
    def _verify_repair_evidence_origin(execution, packet):
        inputs = execution.get("report", {}).get("request_inputs", [])
        original = json.loads(inputs[0]["input"]["prompt"]) if inputs else {}
        original = original.get("repair_adjudication_packet", {})
        supplied = original.get("candidate_program", {})
        expected = _repair_candidate_program(packet)
        if (any(supplied.get(key) != expected.get(key) for key in
                ("exact_execution_sources", "experiment_intent", "repair_subject_lineage"))
                or any(original.get("topic", {}).get(key) != packet.get("topic", {}).get(key)
                       for key in ("id", "research_question"))):
            raise ValidationError("Methods evidence action changes its immutable original source scope")

    def _run_capability_repair_evidence(self, stage, descriptor, packet, retained, prior_review):
        """Produce and independently review an immutable Methods evidence dependency."""
        lead = next((item for item in retained.get("reports", [])
                     if isinstance(item, dict) and item.get("role_id") == "methodologist"), None)
        if not isinstance(lead, dict) or lead.get("decision") != "hold":
            return None
        actions = lead.get("requested_actions")
        if not isinstance(actions, list) or not actions:
            return {"status": "blocked", "reason": "the retained Methods HOLD has no bounded evidence action"}
        if any(not isinstance(item, str) or not item.strip() for item in actions):
            raise ValidationError("Methods evidence action has an invalid objective")
        ref = lead.get("artifact_ref")
        plan_ref = retained.get("ledger", {}).get("assignment_plan_ref")
        _manifest, _digest, execution, origin_plan, task = self._owned_repair_evidence_execution(ref, plan_ref)
        report = execution.get("report", {})
        response = report.get("response", {})
        origin_packet = retained.get("evidence_origin_packet", retained.get("packet", {}))
        self._verify_repair_evidence_origin(execution, origin_packet)
        if (execution.get("schema_version") != "specialist-execution-1"
                or execution.get("project_id") != self.workflow["project_id"]
                or execution.get("assigned_role") != "methods.methodologist"
                or execution.get("stage_id") != origin_plan.get("stage_id")
                or execution.get("attempt_number") != origin_plan.get("attempt_number")
                or origin_plan.get("input_ref", {}).get("stage_id") != stage["id"]
                or task.get("payload", {}).get("stage_id") != execution.get("stage_id")
                or report.get("status") != "succeeded" or response.get("decision") != "hold"
                or response.get("requested_actions") != actions):
            raise ValidationError("Methods evidence action lacks its immutable owned HOLD execution")
        identity = {"requested_actions": actions, "topic": packet.get("topic"),
                    "review_input_sha256": packet.get("review_input_sha256"),
                    "science_input_sha256": packet.get("science_input_sha256"),
                    "lead_findings": response.get("findings", []),
                    "lead_evidence_gaps": response.get("evidence_gaps", []),
                    "origin_review_input_sha256": origin_packet.get("review_input_sha256"),
                    "origin_science_input_sha256": origin_packet.get("science_input_sha256"),
                    "origin_verifier_review": {key: deepcopy(retained.get("verifier", {}).get(key)) for key in
                        ("decision", "rationale", "blocking_findings", "required_revisions", "deferred_gates",
                         "critical_findings", "repair_scope", "open_concerns")}}
        digest = hashlib.sha256(canonical_bytes(identity)).hexdigest()
        logical = f"command/capability-repair-evidence/{digest}"
        request = {"schema_version": "capability-repair-evidence-request-1", **deepcopy(identity),
                   "source_execution_ref": ref, "source_execution_sha256": _digest,
                   "lead_review": deepcopy(response),
                   "origin_verifier_record": deepcopy(retained.get("verifier", {})),
                   "origin_candidate_program": _repair_candidate_program(origin_packet),
                   "origin_failure_lineage": deepcopy(origin_packet.get("failure_lineage")),
                   "origin_repair_subject_lineage": deepcopy(origin_packet.get("repair_subject_lineage")),
                   "origin_topic": deepcopy(origin_packet.get("topic")),
                   "current_scope_matches_origin": origin_packet.get("science_input_sha256") == packet.get("science_input_sha256"),
                   "failure_lineage": deepcopy(packet.get("failure_lineage")),
                   "repair_subject_lineage": deepcopy(packet.get("repair_subject_lineage")),
                   "source_ref_catalog": [item for item in ["candidate_program.executor", "candidate_program.validator",
                                          "origin_candidate_program.executor", "origin_candidate_program.validator",
                                          "experiment_intent", ref,
                                          packet.get("failure_lineage", {}).get("failure_dossier_ref")]
                                          if isinstance(item, str)]}
        request_record = self.store.head(f"{logical}/request")
        if request_record is None:
            request_record = self._publish(f"{logical}/request", "note", request, "command.composer", subjects=[ref])
        else:
            _, _, request = self._read_verified_artifact_json(request_record["artifact_ref"])
            if any(request.get(key) != value for key, value in identity.items()):
                raise ValidationError("Methods evidence dependency changes its admitted input")
        previous = self.store.head(f"{logical}/receipt")
        previous_review = None
        if previous is not None:
            _, _, receipt = self._read_verified_artifact_json(previous["artifact_ref"])
            if receipt.get("request_ref") != request_record["artifact_ref"]:
                raise ValidationError("Methods evidence receipt is bound to another request")
            _, note_sha, note = self._read_verified_artifact_json(receipt["note_ref"])
            _, _, producer_body = self._read_verified_artifact_json(receipt["producer_execution_ref"])
            verifier_body = (self._read_verified_artifact_json(receipt["verifier_execution_ref"])[2]
                             if isinstance(receipt.get("verifier_execution_ref"), str) else {})
            verifier_report = verifier_body.get("report", {})
            verdict = verifier_report.get("response", {})
            if (note_sha != receipt.get("note_sha256") or note.get("request_ref") != receipt["request_ref"]
                    or producer_body.get("report", {}).get("response", {}).get("evidence_note") != note.get("document")
                    or (verifier_body and verifier_body.get("chief_result", {}).get("repair_evidence_note") != note)):
                raise ValidationError("Methods evidence receipt loses its exact note/review dependency")
            if receipt.get("status") == "accepted" and (verifier_report.get("status") != "succeeded"
                    or verdict.get("decision") != "accept" or verdict.get("blocking_findings")
                    or verdict.get("critical_findings") or verdict.get("required_revisions")):
                raise ValidationError("Methods evidence receipt fabricates scientific admission")
            if (receipt.get("status") == "accepted" and verifier_report.get("status") == "succeeded"
                    and verdict.get("decision") == "accept" and not verdict.get("blocking_findings")
                    and not verdict.get("critical_findings") and not verdict.get("required_revisions")):
                if (producer_body.get("schema_version") != "specialist-execution-1"
                        or verifier_body.get("schema_version") != "specialist-verifier-execution-1"
                        or producer_body.get("project_id") != self.workflow["project_id"]
                        or verifier_body.get("project_id") != self.workflow["project_id"]
                        or producer_body.get("stage_id") != verifier_body.get("stage_id")
                        or producer_body.get("attempt_number") != verifier_body.get("attempt_number")
                        or producer_body.get("assigned_role") == verifier_body.get("assigned_role")
                        or producer_body.get("report", {}).get("status") != "succeeded"
                        or producer_body.get("report", {}).get("response", {}).get("decision") != "pass"):
                    raise ValidationError("Methods evidence receipt has no independent owned admission")
                evidence_plan_ref = receipt.get("ledger", {}).get("assignment_plan_ref")
                _, _, producer_body, plan, producer_task = self._owned_repair_evidence_execution(
                    receipt["producer_execution_ref"], evidence_plan_ref)
                _, _, verifier_body, _, verifier_task = self._owned_repair_evidence_execution(
                    receipt["verifier_execution_ref"], evidence_plan_ref, verifier=True)
                initial = producer_body.get("report", {}).get("request_inputs", [])
                prompt = json.loads(initial[0]["input"]["prompt"]) if initial else {}
                input_binding = plan.get("input_ref", {}).get("ref")
                bound_request = (self._read_verified_artifact_json(input_binding)[2].get("evidence_request_ref")
                                 if input_binding != request_record["artifact_ref"] else input_binding)
                if (bound_request != request_record["artifact_ref"]
                        or prompt.get("repair_evidence_request") != request
                        or producer_task.get("state") != "completed" or verifier_task.get("state") != "completed"
                        or verifier_body.get("chief_result", {}).get("repair_evidence_request") != request
                        or note.get("producer_execution_ref") != receipt["producer_execution_ref"]
                        or note.get("request_sha256") != request_record["body_hash"]
                        or receipt.get("review") != verdict):
                    raise ValidationError("Methods evidence receipt changes its exact admitted dependency")
                if (producer_body["report"].get("finish_reason") != "stop"
                        or verifier_report.get("finish_reason") != "stop"
                        or producer_body["report"].get("response", {}).get("raw", {}).get("evidence_note") != note.get("document")):
                    raise ValidationError("Methods evidence receipt lacks a completed literal model note")
                ledger = receipt["ledger"]
                _, _, chief = self._read_verified_artifact_json(ledger["chief_synthesis_ref"])
                _, _, admission = self._read_verified_artifact_json(ledger["verifier_artifact_ref"])
                if (chief.get("schema_version") != "department-chief-synthesis-1"
                        or admission.get("schema_version") != "department-adversarial-verdict-1"
                        or chief.get("project_id") != self.workflow["project_id"]
                        or admission.get("project_id") != self.workflow["project_id"]
                        or chief.get("stage_id") != plan.get("stage_id")
                        or admission.get("stage_id") != plan.get("stage_id")
                        or chief.get("attempt_number") != plan.get("attempt_number")
                        or admission.get("attempt_number") != plan.get("attempt_number")
                        or chief.get("outcome") != "completed" or chief.get("output_ref") != receipt["note_ref"]
                        or admission.get("verdict") != "accepted" or admission.get("attempt_state") != "succeeded"
                        or admission.get("independence_check") is not True
                        or admission.get("chief_synthesis_ref") != ledger["chief_synthesis_ref"]
                        or admission.get("verifier_execution_artifact_ref") != receipt["verifier_execution_ref"]
                        or admission.get("verifier_report") != verdict):
                    raise ValidationError("Methods evidence receipt lacks its exact departmental admission")
                return {**receipt, "artifact_ref": previous["artifact_ref"], "note": note, "request": request, "dispatch_usage": {}}
            previous_review = {"note": note, "review": verdict,
                               "producer": producer_body.get("report", {}).get("response", {})}
        panel_id = self._capability_repair_panel_stage_id(stage["id"], digest, self.continuation_cycles, 1)
        attempt = self._next_capability_repair_assignment_attempt(panel_id)
        evidence_stage = {**deepcopy(stage), "id": panel_id, "_model_budget_owner_stage_id": stage["id"],
                          "deadline_seconds": self._stage_remaining(stage)}
        owner = None
        input_ref = {"kind": "capability_repair_panel", "stage_id": stage["id"],
                     "digest": digest, "ref": request_record["artifact_ref"]}
        if isinstance(stage.get("quota"), dict):
            owner = {"scope": self._stage_model_config(stage, {})["model_call_budget_scopes"][0],
                     "attempt_id": self.stage_records.get(stage["id"], {}).get("attempt_id"),
                     "cycle": self.continuation_cycles if stage["id"] in self.reopened_stage_ids else 0}
            binding = {"schema_version": "capability-repair-budget-owner-1", "panel_stage_id": panel_id,
                       "assignment_attempt_number": attempt, "model_budget_owner": owner,
                       "evidence_request_ref": request_record["artifact_ref"]}
            binding_sha = hashlib.sha256(canonical_bytes(binding)).hexdigest()
            input_ref["ref"] = self._publish(f"command/capability-repair-budget/{binding_sha}",
                                            "note", binding, "command.composer")["artifact_ref"]
        assignment = self.departments.begin_stage(panel_id, "experiment", attempt_number=attempt,
            input_ref=input_ref, deadline_seconds=evidence_stage["deadline_seconds"], active_role_ids=["methodologist"])
        producer = next(item for item in assignment["assignments"] if item.get("assignment_phase") == "specialist")
        producer = {**deepcopy(producer), "_response_contract": "repair_evidence"}
        try:
            producer["_prompt"] = build_repair_evidence_prompt(producer, packet, request, prior_review=previous_review)
        except ValidationError as exc:
            produced_error = {"status": "failed", "assigned_role": producer["assigned_role"],
                              "role_id": producer["role_id"], "error": str(exc), "usage": {}}
        else:
            produced_error = None
        producer_assignment = {**deepcopy(assignment), "assignments": [producer]}
        stage_result = {"_repair_panel": True, "capability_repair_packet": packet,
                        "repair_verification_scope": "evidence_action"}
        bundle = (self._run_specialist_pool(evidence_stage, producer_assignment, descriptor,
            stage_result=stage_result, cache_input_digest=hashlib.sha256(producer["_prompt"].encode()).hexdigest())
                  if produced_error is None else {"model_enabled": True, "by_role": {"methodologist": produced_error}})
        if not bundle.get("model_enabled"):
            bundle = {"model_enabled": True, "by_role": {"methodologist": {
                "status": "failed", "assigned_role": producer["assigned_role"], "role_id": "methodologist",
                "error": "Methods evidence producer has no configured model route", "usage": {}}}}
        bundle = self._publish_specialist_reports(evidence_stage, producer_assignment, bundle)
        produced = bundle.get("by_role", {}).get("methodologist", {})
        produced_response = produced.get("response", {})
        document = produced_response.get("evidence_note")
        note = {"schema_version": "capability-repair-evidence-note-1", "request_ref": request_record["artifact_ref"],
                "request_sha256": request_record["body_hash"], "topic": deepcopy(packet.get("topic")),
                "producer_execution_ref": produced.get("artifact_ref"), "document": deepcopy(document)}
        note_record = self._publish(f"{producer['assignment_logical_id']}/evidence-note", "report", note,
            producer["assigned_role"], subjects=[request_record["artifact_ref"], produced["artifact_ref"]])
        chief = {"repair_evidence_request": request, "repair_evidence_note": note}
        verifier = None
        if produced.get("status") == "succeeded" and produced_response.get("decision") == "pass" and isinstance(document, dict):
            try:
                verifier = self._run_specialist_verifier(evidence_stage, assignment, descriptor, bundle, chief,
                                                        stage_result=stage_result)
            except ValidationError as exc:
                verifier = {"status": "failed", "error": str(exc), "usage": {}}
        usage = self._specialist_usage([*bundle.get("reports", []), *([verifier] if isinstance(verifier, dict) else [])])
        verdict = verifier.get("response", {}) if isinstance(verifier, dict) else {}
        accepted = (isinstance(document, dict) and produced.get("status") == "succeeded"
                    and isinstance(verifier, dict) and verifier.get("status") == "succeeded"
                    and verdict.get("decision") == "accept" and not verdict.get("blocking_findings")
                    and not verdict.get("critical_findings") and not verdict.get("required_revisions"))
        finished = self.departments.finish_stage(panel_id, "experiment", attempt_number=attempt,
            outcome="completed" if accepted else "blocked", output_ref=note_record["artifact_ref"], usage=usage,
            error=None if accepted else "Methods evidence dependency was not independently admitted",
            specialist_results=bundle.get("by_role", {}), verifier_result=verifier)
        ledger = {"panel_stage_id": panel_id, "assignment_attempt_number": attempt,
                  "assignment_plan_ref": assignment["plan_ref"],
                  "chief_synthesis_ref": finished.get("chief_synthesis_ref"),
                  "verifier_artifact_ref": finished.get("verifier_artifact_ref")}
        invoice = {"input_sha256": digest, "usage": usage, "ledger": ledger,
                   **({"model_budget_owner": owner} if owner else {})}
        self._record_capability_repair_panel_usage(stage, invoice)
        failures = [item for item in [produced, verifier] if isinstance(item, dict)
                    and item.get("status") != "succeeded" and isinstance(item.get("failure"), dict)]
        receipt = {"schema_version": "capability-repair-evidence-receipt-1",
                   "status": "accepted" if accepted else "blocked", "request_ref": request_record["artifact_ref"],
                   "note_ref": note_record["artifact_ref"], "note_sha256": note_record["body_hash"],
                   "producer_execution_ref": produced.get("artifact_ref"),
                   "verifier_execution_ref": verifier.get("artifact_ref") if isinstance(verifier, dict) else None,
                   "review": deepcopy(verdict), "ledger": ledger, "usage_invoice_ref": invoice["usage_invoice_ref"],
                   "dispatch_usage": deepcopy(usage), "model_failure": deepcopy(failures[0]) if failures else None}
        record = self._publish(f"{logical}/receipt", "note", receipt, "command.composer",
                               subjects=[request_record["artifact_ref"], note_record["artifact_ref"]])
        return {**receipt, "artifact_ref": record["artifact_ref"], "note": note, "request": request}

    def _run_pending_capability_evidence(self, stage, descriptor, packet):
        origins = self._retained_capability_evidence_actions(stage, packet)
        if not origins:
            return None
        catalog = [{"lead_review": deepcopy(next(item for item in origin["reports"] if item.get("role_id") == "methodologist")),
                    "verifier_review": deepcopy(origin.get("verifier")),
                    "failure_lineage": deepcopy(origin["evidence_origin_packet"].get("failure_lineage")),
                    "repair_subject_lineage": deepcopy(origin["evidence_origin_packet"].get("repair_subject_lineage")),
                    "origin_science_input_sha256": origin["evidence_origin_packet"].get("science_input_sha256"),
                    "current_science_input_sha256": packet.get("science_input_sha256")} for origin in origins]
        dependencies, usage, blocked_origin = [], {}, None
        for origin in origins:
            dependency = self._run_capability_repair_evidence(stage, descriptor, packet, origin, {})
            if dependency is None:
                continue
            dependencies.append(dependency)
            for key in ("model_calls", "input_tokens", "output_tokens"):
                usage[key] = usage.get(key, 0) + dependency.get("dispatch_usage", {}).get(key, 0)
            if dependency.get("status") != "accepted":
                blocked_origin = origin
                break
        frontier = {"schema_version": "capability-repair-evidence-frontier-1", "topic": packet.get("topic"),
                    "current_science_input_sha256": packet.get("science_input_sha256"),
                    "status": "blocked" if blocked_origin else "accepted",
                    "origin_actions": catalog, "receipt_refs": [item["artifact_ref"] for item in dependencies if item.get("artifact_ref")]}
        digest = hashlib.sha256(canonical_bytes(frontier)).hexdigest()
        record = self.store.head(f"command/capability-repair-evidence-frontiers/{digest}")
        if record is None:
            record = self._publish(f"command/capability-repair-evidence-frontiers/{digest}", "note", frontier,
                "command.composer", subjects=frontier["receipt_refs"])
        return {**frontier, "artifact_ref": record["artifact_ref"], "dependencies": dependencies,
                "dispatch_usage": usage, "blocked_origin": blocked_origin}

    def _require_capability_evidence_before_authoring(self, stage, topic_result, descriptor):
        for survey_stage in self.workflow.get("stages", []):
            if survey_stage.get("kind") != "survey":
                continue
            ancestor = self._topic_stage_for_survey(survey_stage)
            if ancestor is None or self.context.get(ancestor["id"], {}).get("topic") != topic_result.get("topic"):
                continue
            obligation = self._topic_review_obligation(survey_stage)
            if obligation is not None:
                survey = self._survey_context_for_topic(ancestor)
                project = survey.get("project_dir") or survey_stage["project_dir"]
                if not self._topic_review_obligation_is_closed({**survey_stage, "project_dir": project}, survey, obligation, require_independent=True):
                    raise ModelWorkBlocked("carried topic review obligations require independent evidence closure before source authoring")
        if not self._retained_capability_evidence_actions(stage, {"topic": topic_result.get("topic")}):
            return None
        prior = self.context.get(stage["id"], {})
        packet = self._build_capability_repair_packet(stage, topic_result, prior, prior.get("error") or "pending Methods evidence action")
        frontier = self._run_pending_capability_evidence(stage, descriptor, packet)
        self.context.setdefault(stage["id"], {})["repair_evidence_frontier"] = deepcopy(frontier)
        self._checkpoint(f"{stage['id']}:capability_repair_evidence", force=True)
        if frontier["status"] == "accepted":
            return frontier
        dependency = frontier["dependencies"][-1]
        failure = dependency.get("model_failure")
        if isinstance(failure, dict):
            error = ModelCallError.from_failure(failure.get("error") or "Methods evidence request unavailable",
                                               {**failure["failure"], "usage": {}})
        else:
            error = ModelWorkBlocked("Methods evidence action remains independently held; source authoring is not admitted")
        error.usage = deepcopy(frontier["dispatch_usage"])
        error.repair_panel_usage = deepcopy(frontier["dispatch_usage"])
        if packet.get("failure_lineage", {}).get("identity_verified") is True:
            error.repair_subject = deepcopy(packet.get("repair_subject_lineage", packet["failure_lineage"]))
        raise error

    @staticmethod
    def _capability_evidence_projection(frontier):
        if frontier is None:
            return None
        projected = deepcopy(frontier)
        projected.pop("dispatch_usage", None)
        projected.pop("blocked_origin", None)
        for dependency in projected.get("dependencies", []):
            dependency.pop("dispatch_usage", None)
        return _preserve_response_value(projected)

    def _run_capability_repair_panel(self, stage, descriptor, topic_result,
                                     prior_context, error):
        """Run upper-model methods roles before a capability redesign."""
        packet = self._build_capability_repair_packet(
            stage, topic_result, prior_context, error)
        prior_context = prior_context if isinstance(prior_context, dict) else {}
        retained = prior_context.get("capability_repair_panel")
        cached_review_reports = None
        prior_plan_review = None
        repair_evidence = None
        evidence_dispatch_usage = {}
        retained_packet = retained.get("packet") if isinstance(retained, dict) else None
        retained_lineage = (retained_packet.get("failure_lineage")
                            if isinstance(retained_packet, dict) else None)
        retained_lineage = retained_lineage if isinstance(retained_lineage, dict) else {}
        retained_review_digest = self._capability_repair_review_input_sha256(
            retained_packet)
        current_review_digest = (packet.get("review_input_sha256")
                                 or self._capability_repair_review_input_sha256(packet))
        retained_input_lineage = {
            key: retained_lineage.get(key) for key in (
                "stage_id", "failure_dossier_ref", "attempt_number", "failure_input_sha256",
            )
        }
        current_failure_lineage = packet.get("failure_lineage")
        current_failure_lineage = (current_failure_lineage
                                   if isinstance(current_failure_lineage, dict) else {})
        same_failure_identity = (
            retained_lineage.get("identity_verified") is True
            and current_failure_lineage.get("identity_verified") is True
            and retained_input_lineage == {
                key: current_failure_lineage.get(key) for key in retained_input_lineage
            }
        )
        if isinstance(retained, dict):
            retained_lead = next((item for item in retained.get("reports", [])
                                  if isinstance(item, dict) and item.get("role_id") == "methodologist"), None)
            if isinstance(retained_lead, dict):
                prior_plan_review = {
                    "prior_plan": deepcopy(retained.get("repair_plan")),
                    "lead_review": deepcopy(retained_lead),
                    "verifier_review": deepcopy(retained.get("verifier")),
                    "source_scope_matches": retained_review_digest == current_review_digest,
                    "instruction": "Preserve the recorded HOLD and its exact actions; reassess changed-source findings against the current bound candidate.",
                }
        repair_evidence = self._run_pending_capability_evidence(stage, descriptor, packet)
        if repair_evidence is not None:
            evidence_dispatch_usage = deepcopy(repair_evidence["dispatch_usage"])
            prior_plan_review = prior_plan_review or {}
            prior_plan_review["pending_origin_actions"] = deepcopy(repair_evidence["origin_actions"])
            prior_plan_review["evidence_dependencies"] = deepcopy(repair_evidence["dependencies"])
            if len(repair_evidence["dependencies"]) == 1:
                prior_plan_review["evidence_dependency"] = deepcopy(repair_evidence["dependencies"][0])
            if repair_evidence["status"] != "accepted":
                origin = repair_evidence["blocked_origin"]
                held = {**deepcopy(origin), "packet": packet, "input_sha256": packet.get("input_sha256"),
                        "evidence_origin_packet": deepcopy(origin["evidence_origin_packet"]),
                        "prompt_revision": CAPABILITY_REPAIR_PANEL_PROMPT_REVISION,
                        "repair_plan": None, "decision": "hold", "prior_plan_review": prior_plan_review,
                        "repair_evidence": repair_evidence, "dispatch_usage": evidence_dispatch_usage,
                        "plan_validation_error": "the requested Methods evidence dependency is not admitted"}
                failure = repair_evidence["dependencies"][-1].get("model_failure")
                if isinstance(failure, dict):
                    held.update({"status": "unavailable", "decision": "defer", "model_failure": {
                        "error": failure.get("error"), "failure": deepcopy(failure.get("failure"))}})
                self.context.setdefault(stage["id"], {})["capability_repair_panel"] = deepcopy(held)
                self._checkpoint(f"{stage['id']}:capability_repair_evidence", force=True)
                return held
        if (isinstance(retained, dict)
                and retained.get("schema_version") in CAPABILITY_REPAIR_PLAN_SCHEMA_VERSIONS
                and retained.get("prompt_revision") == CAPABILITY_REPAIR_PANEL_PROMPT_REVISION
                and retained.get("input_sha256") == packet.get("input_sha256")
                and same_failure_identity
                and retained_review_digest == current_review_digest
                and (repair_evidence is None or (retained.get("repair_evidence") or {}).get("artifact_ref") == repair_evidence.get("artifact_ref"))
                and self._capability_repair_plan_admitted(retained)):
            cached = deepcopy(retained)
            cached["dispatch_usage"] = {
                key: 0 for key in ("model_calls", "input_tokens", "output_tokens")
            }
            return cached
        if (isinstance(retained, dict)
                and retained.get("schema_version") in CAPABILITY_REPAIR_REPORT_REUSE_SCHEMA_VERSIONS
                and retained_lineage.get("identity_verified") is True
                and retained_review_digest == current_review_digest
                and packet.get("failure_lineage", {}).get("identity_verified") is True):
            retained_verifier = retained.get("verifier")
            retained_verifier = (retained_verifier
                                 if isinstance(retained_verifier, dict) else {})
            retained_blocking = retained_verifier.get("blocking_findings")
            if not isinstance(retained_blocking, list):
                retained_blocking = retained_verifier.get("critical_findings")
            retained_blocking = (retained_blocking
                                 if isinstance(retained_blocking, list) else [])
            retained_revisions = retained_verifier.get("required_revisions")
            retained_revisions = (retained_revisions
                                  if isinstance(retained_revisions, list) else [])
            verifier_rejected_plan = (
                isinstance(retained.get("repair_plan"), dict)
                and retained_verifier.get("status") == "succeeded"
                and (retained_verifier.get("decision") != "accept"
                     or bool(retained_blocking)
                     or bool(retained_revisions))
            )
            if verifier_rejected_plan:
                prior_plan_review = {**(prior_plan_review or {}),
                    "prior_plan": deepcopy(retained["repair_plan"]),
                    "verifier_decision": retained_verifier.get("decision"),
                    "verifier_rationale": str(retained_verifier.get("rationale") or ""),
                    "blocking_findings": [
                        str(item) for item in retained_blocking
                        if isinstance(item, str) and item.strip()
                    ],
                    "required_revisions": [
                        str(item) for item in retained_revisions
                        if isinstance(item, str) and item.strip()
                    ],
                    "deferred_gates": [
                        str(item) for item in retained_verifier.get(
                            "deferred_gates", [])
                        if isinstance(item, str) and item.strip()
                    ] if isinstance(retained_verifier.get("deferred_gates"), list) else [],
                    "repair_scope": [
                        str(item)
                        for item in retained_verifier.get("repair_scope", [])
                        if isinstance(item, str) and item.strip()
                    ] if isinstance(retained_verifier.get("repair_scope"), list) else [],
                    "open_concerns": [
                        str(item)
                        for item in retained_verifier.get("open_concerns", [])
                        if isinstance(item, str) and item.strip()
                    ] if isinstance(retained_verifier.get("open_concerns"), list) else [],
                    "instruction": (
                        "Revise the pre-execution plan. Resolve each blocking finding and required "
                        "revision through a concrete change or supplied-evidence rebuttal. Do not "
                        "defer a blocking design defect to post-execution uncertainty."
                    ),
                }
            required_role_ids = list(
                self.departments.stage_route("experiment").get("required_role_ids", []))
            reviewer_role_ids = [role_id for role_id in required_role_ids
                                 if role_id != "methodologist"]
            cached_review_by_role = self._capability_repair_cached_reports(retained)
            if cached_review_by_role:
                cached_review_reports = cached_review_by_role
                pending_cached_reviewer_roles = [
                    role_id for role_id in reviewer_role_ids
                    if role_id not in cached_review_by_role
                ]
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": ("reuse_capability_repair_reviews_for_revision"
                               if prior_plan_review else "reuse_capability_repair_reviews"),
                    "stage_id": stage.get("id"),
                    "panel_stage_id": (retained.get("ledger") or {}).get("panel_stage_id"),
                    "review_input_sha256": packet.get("review_input_sha256"),
                    "lead_reconciliation_required": True,
                    "cached_reviewer_roles": sorted(cached_review_by_role),
                    "pending_reviewer_roles": pending_cached_reviewer_roles,
                    "model_calls_dispatched_so_far": 0,
                    "reason": (
                        "reuse successful same-evidence independent reports; rerun only missing "
                        "review roles, have the Methods lead reconcile the current dossier, and "
                        "have the independent verifier assess the newly bound plan"
                        if prior_plan_review else
                        "reuse successful same-evidence independent reports; rerun only missing "
                        "review roles, then adjudicate the current-dossier plan and verifier"
                    ),
                })

        base = re.sub(r"[^a-z0-9-]+", "-", str(stage.get("id", "experiment")).casefold()).strip("-")
        attempt = prior_context.get("capability_repair_attempts", 1)
        if type(attempt) is not int or attempt < 1:
            attempt = 1
        panel_id = self._capability_repair_panel_stage_id(
            base or "experiment", packet.get("science_input_sha256"),
            self.continuation_cycles, attempt)
        assignment_attempt = self._next_capability_repair_assignment_attempt(panel_id)
        panel_stage = deepcopy(stage)
        panel_stage.update({
            "id": panel_id,
            "_model_budget_owner_stage_id": stage["id"],
            "kind": "experiment",
            "deadline_seconds": self._stage_remaining(stage),
            "attempt_deadline_at_epoch": (stage.get("attempt_deadline_at_epoch")
                or self.stage_records.get(stage["id"], {}).get("attempt_deadline_at_epoch")),
        })
        model_budget_owner = None
        if isinstance(stage.get("quota"), dict):
            owner_scope = self._stage_model_config(stage, {})["model_call_budget_scopes"][0]
            model_budget_owner = {
                "scope": owner_scope,
                "attempt_id": self.stage_records.get(stage["id"], {}).get("attempt_id"),
                "cycle": self.continuation_cycles if stage["id"] in self.reopened_stage_ids else 0,
            }
        prior_evidence = packet.get("prior_attempt_result_evidence", {})
        prior_evidence = prior_evidence if isinstance(prior_evidence, dict) else {}
        prior_raw_data = prior_evidence.get("files", {}).get("raw_data", {})
        prior_raw_data = prior_raw_data if isinstance(prior_raw_data, dict) else {}
        prior_context_summary = {
            "available": prior_evidence.get("available") is True,
            "run_status": prior_evidence.get("run_status"),
            "validation_decision": prior_evidence.get("validation_decision"),
            "scientific_sha256": prior_evidence.get("scientific_sha256"),
            "admissible_as_verified_claims": False,
        }
        prior_result_package = prior_evidence.get("results_package")
        prior_result_package = (prior_result_package
                                if isinstance(prior_result_package, dict) else {})
        prior_foundry_intent = self._capability_repair_prior_intent(packet)
        prior_review_summary = {
            "question": prior_result_package.get("question"),
            "hypothesis": prior_result_package.get("hypothesis"),
            "metrics": prior_result_package.get("metrics", []),
            "analysis": prior_result_package.get("analysis", {}),
            "findings": prior_result_package.get("findings", []),
            "limitations": prior_result_package.get("limitations", []),
            "validation_decision": prior_evidence.get("validation_decision"),
            "review_evidence": prior_evidence.get("review_evidence", []),
            "raw_data": {
                "sha256": prior_raw_data.get("sha256"),
                "observation_count": prior_raw_data.get("observation_count"),
                "columns": prior_raw_data.get("columns", []),
                "sample_indices": prior_raw_data.get("sample_indices", []),
                "sample_rows": prior_raw_data.get("sample_rows", []),
            },
            "figures": prior_evidence.get("figures", []),
            "admissible_as_verified_claims": False,
        } if prior_evidence.get("available") is True else None
        model_packet = deepcopy(packet)
        model_packet.pop("continuation_cycle", None)
        current_lineage = packet.get("failure_lineage")
        current_lineage = current_lineage if isinstance(current_lineage, dict) else {}
        model_packet["failure_lineage"] = {
            "stage_id": stage.get("id"),
            "identity_verified": current_lineage.get("identity_verified") is True,
            "failure_dossier_ref": current_lineage.get("failure_dossier_ref"),
            "attempt_number": current_lineage.get("attempt_number"),
            "failure_input_sha256": current_lineage.get("failure_input_sha256"),
            "failure_dossier_body_sha256": current_lineage.get(
                "failure_dossier_body_sha256"),
            "adjudication_packet_input_sha256": packet.get("input_sha256"),
        }
        recovery_packet = model_packet.get("failure_recovery")
        recovery_packet = recovery_packet if isinstance(recovery_packet, dict) else {}
        model_packet["failure_recovery"] = {
            key: recovery_packet.get(key)
            for key in ("recovery_mode", "failure_class")
            if recovery_packet.get(key) is not None
        }
        panel_result = {
            "_repair_panel": True,
            "capability_repair_packet": model_packet,
            "research_question": packet["topic"].get("research_question"),
            "hypotheses": (prior_result_package.get("hypothesis")
                           if prior_result_package
                           else prior_foundry_intent.get("hypothesis")),
            "design": {
                "procedures": prior_result_package.get("procedures", []),
                "prior_foundry_intent": deepcopy(prior_foundry_intent),
            },
            "analysis_plan": {
                "state": "prior_attempt_results_require_methods_repair"
                if prior_evidence.get("available") is True else "pre_execution_repair_panel",
                "failure": packet["failure"],
                "repair_contract": packet["repair_contract"],
                "prior_attempt_evidence": prior_context_summary,
            },
            "claims": {
                "status": "prior_attempt_result_rejected_not_verified"
                if prior_evidence.get("available") is True
                else "failed_capability_requires_model_repair",
                "admissible_as_verified_claims": False,
                "validation_decision": prior_evidence.get("validation_decision"),
            },
            "raw_results": {
                "observation_count": prior_raw_data.get("observation_count"),
                "columns": prior_raw_data.get("columns", []),
                "sample_indices": prior_raw_data.get("sample_indices", []),
                "sample_rows": prior_raw_data.get("sample_rows", []),
                "raw_data_sha256": prior_raw_data.get("sha256"),
            } if prior_evidence.get("available") is True else prior_context.get("raw_results"),
            "derived_results": prior_evidence.get(
                "derived_results", prior_context.get("derived_results", {})),
            "figures": prior_evidence.get("figures", prior_context.get("figures", [])),
            "execution_manifest": {
                "state": "prior_attempt_result_identity_verified"
                if prior_evidence.get("available") is True else "no_prior_result_bound",
                **prior_context_summary,
                "execution_refs": prior_evidence.get("execution_refs", []),
                "files": prior_evidence.get("files", {}),
            },
            "analysis_code": {
                "state": "topic_capability_source_snapshot_not_execution_verified"
                if packet.get("program_snapshot") else "source_snapshot_not_available",
                "files": packet.get("program_snapshot", []),
                "execution_refs": prior_evidence.get("execution_refs", []),
            },
            "failure_evidence": {
                **prior_context_summary,
            "prior_attempt_result": prior_review_summary,
        },
        }
        input_ref = {
            "kind": "capability_repair_panel",
            "stage_id": stage.get("id"),
            "panel_id": panel_id,
            "digest": packet["input_sha256"],
        }
        if isinstance(repair_evidence, dict) and repair_evidence.get("status") == "accepted":
            input_ref["ref"] = repair_evidence["artifact_ref"]
        if model_budget_owner is not None:
            owner_binding = {"schema_version": "capability-repair-budget-owner-1",
                             "panel_stage_id": panel_id,
                             "assignment_attempt_number": assignment_attempt,
                             "model_budget_owner": deepcopy(model_budget_owner)}
            if isinstance(repair_evidence, dict) and repair_evidence.get("status") == "accepted":
                owner_binding["evidence_dependency_ref"] = repair_evidence["artifact_ref"]
            owner_digest = hashlib.sha256(canonical_bytes(owner_binding)).hexdigest()
            binding = self._publish(f"command/capability-repair-budget/{owner_digest}",
                                    "note", owner_binding, "command.composer")
            input_ref["ref"] = binding["artifact_ref"]
        active_roles = (["methodologist", *[
            role_id for role_id in reviewer_role_ids
            if role_id not in (cached_review_reports or {})
        ]] if cached_review_reports is not None else None)
        assignment = self.departments.begin_stage(
            panel_id, "experiment", attempt_number=assignment_attempt, input_ref=input_ref,
            deadline_seconds=panel_stage["deadline_seconds"], active_role_ids=active_roles,
        )
        assignments = [item for item in assignment.get("assignments", [])
                       if isinstance(item, dict)
                       and item.get("assignment_phase") == "specialist"]
        lead = next((item for item in assignments
                     if item.get("assigned_role") == "methods.methodologist"), None)
        reviewers = [item for item in assignments if item is not lead]
        reviewer_assignment = {**deepcopy(assignment), "assignments": reviewers}
        if cached_review_reports is not None:
            retained_reports = []
            reports_by_role = {}
            for role_id in reviewer_role_ids:
                item = cached_review_reports.get(role_id)
                if not isinstance(item, dict):
                    continue
                response = {
                    key: deepcopy(item.get(key))
                    for key in ("decision", "summary", "findings", "evidence_gaps",
                                "requested_actions", "normalization_warnings")
                    if key in item
                }
                report = {**deepcopy(item), "response": response, "usage": {}}
                retained_reports.append(report)
                reports_by_role[report["role_id"]] = report
            missing_assignments = [
                item for item in reviewer_assignment.get("assignments", [])
                if isinstance(item, dict)
                and item.get("role_id") not in reports_by_role
            ]
            fresh_bundle = ({"reports": [], "by_role": {}, "usage": {},
                             "model_enabled": True}
                            if not missing_assignments else self._run_specialist_pool(
                                panel_stage,
                                {**deepcopy(reviewer_assignment),
                                 "assignments": missing_assignments},
                                descriptor, stage_result=panel_result,
                                cache_input_digest=packet.get("science_input_sha256")))
            if missing_assignments:
                fresh_bundle = self._publish_specialist_reports(
                    panel_stage,
                    {**deepcopy(reviewer_assignment),
                     "assignments": missing_assignments},
                    fresh_bundle)
            for report in fresh_bundle.get("reports", []):
                role_id = report.get("role_id")
                if isinstance(role_id, str):
                    reports_by_role[role_id] = report
            reviewer_bundle = {
                "reports": [reports_by_role[role_id] for role_id in reviewer_role_ids
                            if role_id in reports_by_role],
                "by_role": reports_by_role,
                "usage": self._specialist_usage(fresh_bundle.get("reports", [])),
                "model_enabled": fresh_bundle.get("model_enabled") is True,
            }
        else:
            reviewer_bundle = self._run_specialist_pool(
                panel_stage, reviewer_assignment, descriptor, stage_result=panel_result,
                cache_input_digest=packet.get("science_input_sha256"))
            reviewer_bundle = self._publish_specialist_reports(
                panel_stage, reviewer_assignment, reviewer_bundle)

        lead_bundle = {"reports": [], "by_role": {}, "usage": {},
                       "model_enabled": reviewer_bundle.get("model_enabled") is True}
        plan_validation_error = "methods lead assignment is unavailable"
        repair_plan = None
        repair_plan_source = None
        lead_report = None
        def model_failure_report(reports):
            return next((report for report in reports if isinstance(report, dict)
                         and report.get("status") != "succeeded"
                         and isinstance(report.get("failure"), dict)
                         and report["failure"].get("kind") == "model_call"), None)
        reviewer_failure = model_failure_report(reviewer_bundle.get("reports", []))
        if reviewer_failure is not None:
            plan_validation_error = str(reviewer_failure.get("error") or "required Methods role is unavailable")
        if (isinstance(lead, dict) and reviewer_bundle.get("model_enabled") is True
                and reviewer_failure is None):
            lead_assignment_row = deepcopy(lead)
            lead_assignment_row["_response_contract"] = "repair_adjudication"
            lead_assignment_row["_prompt"] = build_repair_adjudication_prompt(
                lead_assignment_row, packet, reviewer_bundle.get("reports", []),
                prior_plan_review=prior_plan_review)
            lead_assignment = {**deepcopy(assignment),
                               "assignments": [lead_assignment_row]}
            lead_result = {
                **panel_result,
                "repair_adjudication": {
                    "stage": ("pre_execution_plan_revision" if prior_plan_review
                              else "pre_execution_plan"),
                    "reviewer_reports": deepcopy(reviewer_bundle.get("reports", [])),
                    "prior_plan_review": deepcopy(prior_plan_review),
                },
            }
            lead_input_digest = self._capability_repair_lead_input_digest(
                packet, reviewer_bundle.get("reports", []), prior_plan_review)
            lead_bundle = self._run_specialist_pool(
                panel_stage, lead_assignment, descriptor, stage_result=lead_result,
                cache_input_digest=lead_input_digest)
            lead_bundle = self._publish_specialist_reports(
                panel_stage, lead_assignment, lead_bundle)
            lead_report = lead_bundle.get("by_role", {}).get(lead.get("role_id"))
            repair_plan, plan_validation_error = self._validated_capability_repair_plan(
                lead_report, packet)
            if repair_plan is not None:
                repair_plan_source = "methods_lead_response"
            if repair_plan is None:
                repair_plan = self._repair_plan_from_reconciled_reports(
                    [*reviewer_bundle.get("reports", []),
                     *lead_bundle.get("reports", [])], packet)
                if repair_plan is not None:
                    plan_validation_error = None
                    repair_plan_source = "validated_report_reconciliation"

        reports_by_role = {
            **reviewer_bundle.get("by_role", {}),
            **lead_bundle.get("by_role", {}),
        }
        reports = [reports_by_role[item.get("role_id")]
                   for item in assignments if item.get("role_id") in reports_by_role]
        known_report_ids = {item.get("role_id") for item in reports}
        reports.extend(report for report in (
            *reviewer_bundle.get("reports", []), *lead_bundle.get("reports", []))
            if isinstance(report, dict) and report.get("role_id") not in known_report_ids)
        bundle = {
            "reports": reports,
            "by_role": reports_by_role,
            "packet": lead_bundle.get("packet") or reviewer_bundle.get("packet", {}),
            "model_enabled": reviewer_bundle.get("model_enabled") is True,
        }
        chief_result = {
            "status": "pre_execution_repair_plan",
            "decision": "repair" if repair_plan else "hold",
            "prior_plan_review": deepcopy(prior_plan_review),
            "repair_adjudication": repair_plan or {
                "status": "invalid_or_unavailable",
                "reason": plan_validation_error,
                "failure_lineage": deepcopy(packet.get("failure_lineage", {})),
            },
        }
        verification_result = {
            **panel_result,
            "repair_verification_scope": "pre_execution_plan",
            "prior_plan_review": deepcopy(prior_plan_review),
            "repair_adjudication": deepcopy(chief_result["repair_adjudication"]),
        }
        verifier = (None if model_failure_report(bundle.get("reports", [])) is not None
                    else self._run_specialist_verifier(
                        panel_stage, assignment, descriptor, bundle, chief_result,
                        stage_result=verification_result))
        panel_usage = self._specialist_usage(bundle.get("reports", []))
        if isinstance(verifier, dict):
            verifier_usage = self._specialist_usage([verifier])
            for key in ("model_calls", "input_tokens", "output_tokens"):
                panel_usage[key] = panel_usage.get(key, 0) + verifier_usage.get(key, 0)
        model_enabled = bundle.get("model_enabled") is True
        failed_reports = [report for report in [*bundle.get("reports", []), verifier]
                          if isinstance(report, dict) and report.get("status") != "succeeded"]
        panel_error = (str(failed_reports[0].get("error") or "required Methods role is unavailable")
                       if failed_reports else None)
        if panel_error is None and lead_report is None:
            panel_error = "methods lead assignment is unavailable"
        if panel_error is None:
            panel_error = self._capability_repair_verifier_unavailable_reason(verifier)
        if not model_enabled:
            panel_error = "capability repair panel has no configured model route"
        panel_outcome = "blocked" if panel_error else "completed"
        failed_model_report = model_failure_report(failed_reports)
        model_failure = ({"error": failed_model_report.get("error"),
                          "failure": deepcopy(failed_model_report["failure"])}
                         if failed_model_report is not None else None)
        assignment_result = self.departments.finish_stage(
            panel_id, "experiment", attempt_number=assignment_attempt, outcome=panel_outcome,
            output_ref=None, usage=panel_usage, error=panel_error,
            actor="command.composer", specialist_results=bundle.get("by_role", {}),
            verifier_result=verifier, failure_scope="stage" if panel_error else None,
        )
        reports = []
        for report in bundle.get("reports", []):
            response = report.get("response") if isinstance(report.get("response"), dict) else {}
            reports.append({
                "role_id": report.get("role_id"),
                "assigned_role": report.get("assigned_role"),
                "status": report.get("status"),
                "error": report.get("error"),
                "budget_admission": deepcopy(report.get("budget_admission")),
                "failure": deepcopy(report.get("failure")),
                "status_code": report.get("status_code"),
                "retry_after_seconds": report.get("retry_after_seconds"),
                "decision": response.get("decision", report.get("decision")),
                "summary": str(response.get("summary", report.get("summary", ""))),
                "findings": [str(item) for item in response.get("findings", [])]
                if isinstance(response.get("findings"), list) else [],
                "evidence_gaps": [str(item) for item in response.get("evidence_gaps", [])]
                if isinstance(response.get("evidence_gaps"), list) else [],
                "requested_actions": [str(item) for item in response.get("requested_actions", [])]
                if isinstance(response.get("requested_actions"), list) else [],
                "artifact_ref": report.get("artifact_ref"),
            })
        panel_decision, open_verifier_concerns = self._capability_repair_verdict(
            repair_plan, verifier)
        verifier_response = verifier.get("response") if isinstance(verifier, dict) else {}
        verifier_response = verifier_response if isinstance(verifier_response, dict) else {}
        diagnostic_hypotheses = (
            [repair_plan["root_cause"]["statement"]] if repair_plan else
            [finding for report in reports for finding in report.get("findings", [])]
        )
        proposed_changes = (
            [change["instruction"] for change in repair_plan["required_changes"]]
            if repair_plan else []
        )
        panel = {
            "schema_version": CAPABILITY_REPAIR_PANEL_SCHEMA_VERSION,
            "prompt_revision": CAPABILITY_REPAIR_PANEL_PROMPT_REVISION,
            "status": "unavailable" if panel_error else "completed",
            "decision": "defer" if panel_error else panel_decision,
            "model_failure": model_failure,
            "repair_plan_source": repair_plan_source,
            "input_sha256": packet["input_sha256"],
            "science_input_sha256": packet.get("science_input_sha256"),
            "review_input_sha256": current_review_digest,
            "packet": packet,
            "repair_plan": repair_plan,
            "prior_plan_review": prior_plan_review,
            "repair_evidence": deepcopy(repair_evidence),
            "plan_validation_error": plan_validation_error if not repair_plan else None,
            "diagnostic_hypotheses": list(dict.fromkeys(diagnostic_hypotheses))[:8],
            "proposed_changes": list(dict.fromkeys(proposed_changes))[:6],
            "acceptance_checks": deepcopy(
                repair_plan["acceptance_checks"] if repair_plan
                else [{"phase": "execution", "check": value}
                      for value in packet["repair_contract"]["must_prove"]]),
            "repair_commands": deepcopy(
                prior_context.get("repair_commands", [])
                if isinstance(prior_context.get("repair_commands"), list) else []
            ),
            "reports": reports,
            "verifier": {
                "status": verifier.get("status") if isinstance(verifier, dict) else None,
                "error": (str(verifier.get("error", ""))[:1200]
                          if isinstance(verifier, dict)
                          and verifier.get("status") != "succeeded" else None),
                "decision": verifier_response.get("decision"),
                "rationale": str(verifier_response.get("rationale", "")),
                "blocking_findings": [str(item) for item in
                                      verifier_response.get("blocking_findings", [])]
                if isinstance(verifier_response.get("blocking_findings"), list) else [],
                "required_revisions": [str(item) for item in
                                       verifier_response.get("required_revisions", [])]
                if isinstance(verifier_response.get("required_revisions"), list) else [],
                "deferred_gates": [str(item) for item in
                                   verifier_response.get("deferred_gates", [])]
                if isinstance(verifier_response.get("deferred_gates"), list) else [],
                "critical_findings": [str(item) for item in verifier_response.get("critical_findings", [])]
                if isinstance(verifier_response.get("critical_findings"), list) else [],
                "repair_scope": [str(item) for item in verifier_response.get("repair_scope", [])]
                if isinstance(verifier_response.get("repair_scope"), list) else [],
                "open_concerns": open_verifier_concerns,
                "artifact_ref": verifier.get("artifact_ref") if isinstance(verifier, dict) else None,
            },
            "ledger": {
                "panel_stage_id": panel_id,
                "assignment_attempt_number": assignment_attempt,
                "assignment_plan_ref": assignment.get("plan_ref"),
                "chief_synthesis_ref": assignment_result.get("chief_synthesis_ref"),
                "verifier_artifact_ref": assignment_result.get("verifier_artifact_ref"),
                "active_agents": deepcopy(assignment.get("active_agents", [])),
                "verifier_agent": assignment.get("verifier_agent"),
            },
            "usage": panel_usage,
            "dispatch_usage": {**deepcopy(panel_usage), **{
                key: panel_usage.get(key, 0) + evidence_dispatch_usage.get(key, 0)
                for key in ("model_calls", "input_tokens", "output_tokens")}},
            **({"model_budget_owner": model_budget_owner} if model_budget_owner else {}),
            "error": panel_error,
        }
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "capability_repair_panel",
            "stage_id": stage.get("id"),
            "panel_stage_id": panel_id,
            "decision": panel["decision"],
            "plan_validation_error": panel.get("plan_validation_error"),
            "active_agents": deepcopy(assignment.get("active_agents", [])),
            "verifier_agent": assignment.get("verifier_agent"),
            "chief_synthesis_ref": assignment_result.get("chief_synthesis_ref"),
            "verifier_artifact_ref": assignment_result.get("verifier_artifact_ref"),
            "input_sha256": packet["input_sha256"],
        })
        self._record_capability_repair_panel_usage(stage, panel)
        self.context.setdefault(stage["id"], {})["capability_repair_panel"] = deepcopy(panel)
        self._checkpoint(f"{stage.get('id')}:capability_repair_panel", force=True)
        return panel

    def _next_capability_repair_assignment_attempt(self, panel_id):
        """Resume a clean panel attempt; supersede only calls known to be unknown."""
        rows = self.departments.stage_assignment_states(panel_id)
        if not rows:
            return 1
        attempt_numbers = [item["attempt_number"] for item in rows
                           if type(item.get("attempt_number")) is int]
        if not attempt_numbers:
            return 1
        latest_attempt = max(attempt_numbers)
        latest_rows = [item for item in rows
                       if item.get("attempt_number") == latest_attempt]
        progress_stages = self._progress_snapshot.get("stages", {})
        progress_stages = progress_stages if isinstance(progress_stages, dict) else {}
        stage_progress = progress_stages.get(panel_id, {})
        stage_progress = stage_progress if isinstance(stage_progress, dict) else {}
        live_by_role = stage_progress.get("specialist_live", {})
        live_by_role = live_by_role if isinstance(live_by_role, dict) else {}
        for item in latest_rows:
            if (item.get("assignment_phase") != "verifier"
                    or item.get("task_state") != "queued"
                    or item.get("attempt_state") is not None):
                continue
            live = live_by_role.get(item.get("assigned_role"), {})
            if (isinstance(live, dict)
                    and live.get("event") == "dispatched"
                    and live.get("task_id") == item.get("task_id")
                    and live.get("stage_id") == panel_id):
                self.departments.reconcile_dispatched_verifier_unknown(
                    panel_id, "experiment", latest_attempt,
                    dispatch_event=live,
                )
                rows = self.departments.stage_assignment_states(panel_id)
                latest_rows = [row for row in rows
                               if row.get("attempt_number") == latest_attempt]
                break
        # A completed verifier is bound to the exact packet it reviewed. Start
        # a new assignment generation on panel re-entry; the durable model-work
        # cache still reuses an identical prompt without another provider call.
        if any(item.get("assignment_phase") == "verifier"
               and item.get("attempt_state") == "succeeded" for item in latest_rows):
            return latest_attempt + 1
        if any(item.get("attempt_state") in {"failed", "result_unknown"}
               for item in latest_rows):
            return latest_attempt + 1
        return latest_attempt

    @staticmethod
    def _capability_repair_prior_intent(packet):
        """Normalize nullable legacy foundry fields before reviewer projection."""
        packet = packet if isinstance(packet, dict) else {}
        foundry_work = packet.get("prior_foundry_work")
        foundry_work = foundry_work if isinstance(foundry_work, dict) else {}
        last_attempt = foundry_work.get("last_attempt")
        last_attempt = last_attempt if isinstance(last_attempt, dict) else {}
        intent = last_attempt.get("experiment_intent")
        return intent if isinstance(intent, dict) else {}

    def _materialize_topic_capability(self, result, *, force_regenerate=False,
                                      continuation_requests=(), continuation_revision=None,
                                      stage_id=None, study_type=None,
                                      stage_seconds=None,
                                      quality_contract=None,
                                      model_call_budget=None, repair_context=None):
        """Generate and admit a pinned program for one science-first topic.

        A substantive methods continuation must not silently execute the same
        generated capability again.  Forced generations receive a new
        deterministic study identity and the red-team work orders in their
        authoring brief, while the original question and domain stay pinned.
        An independently registered repair artifact is the exception: it is
        already a new immutable capability and can be selected before another
        authoring call burns the same scope.
        """
        configured_path = self.workflow.get("capability_foundry_config_path")
        if not configured_path:
            return result
        from scisaurus.runtime.capability_foundry import (
            CapabilityFoundry, CapabilityModelBudgetExceeded,
            validate_foundry_config, validate_program_review,
        )
        from scisaurus.runtime.capability_registry import load_registry

        configured = validate_foundry_config(json.loads(Path(configured_path).read_text()))
        selected = result.get("topic") if isinstance(result, dict) else None
        if not isinstance(selected, dict):
            raise ValidationError("capability foundry requires a selected topic")
        topic_context = result if isinstance(result, dict) else {}
        requirement_scope = self._topic_maturity_requirement_scope(
            selected, topic_context)
        requires_source_data = self._topic_requires_source_data(selected, topic_context)
        source_data_manifest = (
            self._verified_source_data_manifest(stage_id)
            if requires_source_data else None
        )
        if requires_source_data and source_data_manifest is None:
            from scisaurus.runtime.capability_foundry import SourceDataUnavailable
            raise SourceDataUnavailable(
                "empirical experiment requires current controller-verified source rows; "
                "do not reuse or generate a capability without its evidence input")
        question = selected.get("research_question")
        domain = selected.get("domain")
        if not isinstance(question, str) or not isinstance(domain, str):
            raise ValidationError("capability foundry requires topic domain and research question")

        foundry_stage = next((item for item in self.workflow["stages"] if item["id"] == stage_id), None)
        evidence_frontier = None
        if foundry_stage is not None and foundry_stage["kind"] == "experiment":
            descriptor = json.loads(Path(foundry_stage["config_path"]).read_text())
            evidence_frontier = self._require_capability_evidence_before_authoring(foundry_stage, result, descriptor)
            if (evidence_frontier is not None and isinstance(repair_context, dict)
                    and repair_context.get("schema_version") in CAPABILITY_REPAIR_PLAN_SCHEMA_VERSIONS
                    and (repair_context.get("repair_evidence") or {}).get("artifact_ref") != evidence_frontier["artifact_ref"]):
                error = ModelWorkBlocked("Methods repair plan has not reviewed the admitted evidence frontier")
                error.usage = deepcopy(evidence_frontier["dispatch_usage"])
                error.repair_panel_usage = deepcopy(evidence_frontier["dispatch_usage"])
                raise error

        registry_root = Path(configured["registry_root"])
        evidence_binding = ({
            "artifact_ref": evidence_frontier["artifact_ref"],
            "sha256": self._read_verified_artifact_json(evidence_frontier["artifact_ref"])[1],
        } if evidence_frontier is not None else None)
        existing = None
        superseded = None
        prior_capability = deepcopy(result.get("generated_capability"))
        for entry in reversed(load_registry(registry_root).get("capabilities", [])):
            try:
                path = Path(entry["path"])
                descriptor = json.loads(path.read_text())
                experiment = descriptor.get("experiment", {})
            except (KeyError, OSError, ValueError, TypeError):
                continue
            if (experiment.get("research_question") == question
                    and experiment.get("domain") == domain):
                admission = json.loads((path.parent / "admission.json").read_text())
                review = admission.get("adversarial_review") or {}
                repair = admission.get("repair_provenance") or {}
                if (evidence_binding is not None
                        and (not isinstance(repair, dict)
                             or repair.get("repair_evidence_frontier") != evidence_binding)):
                    continue
                if force_regenerate:
                    if (not isinstance(repair, dict)
                            or repair.get("kind") != "independent_repair"
                            or repair.get("origin") != "composer_model_panel"):
                        continue
                    # A pre-execution repair is already a materially different,
                    # independently admitted program. Reuse it even when the
                    # checkpoint points at the same capability; otherwise a
                    # recovery resume needlessly re-enters model authoring and
                    # can starve the experiment. Once observations exist, the
                    # same identity is no longer a fresh continuation.
                    has_observed_capability = self._has_executed_experiment_result(
                        self.context.get(stage_id, {}), experiment.get("id"))
                    if (has_observed_capability and isinstance(prior_capability, dict)
                            and experiment.get("id") == prior_capability.get("capability_id")):
                        continue
                try:
                    valid_verdict = validate_program_review({
                        name: review.get(name) for name in ("status", "checks", "findings")})["status"] == "admitted"
                except ValidationError:
                    valid_verdict = False
                if (not valid_verdict or review.get("role") != "review.methods"
                        or review.get("review_method") != "independent_model"
                        or review.get("candidate_sha256") != entry["candidate_record_sha256"]
                        or (study_type is not None and experiment.get("study_type") != study_type)):
                    if superseded is None or experiment["revision"] > superseded["revision"]:
                        superseded = {"id": experiment["id"], "revision": experiment["revision"]}
                    continue
                existing = {
                    "capability_id": descriptor.get("capability_id"),
                    "descriptor_path": str(path.resolve()), "reused": True,
                    "registry_entry": deepcopy(entry),
                }
                if isinstance(repair, dict) and repair:
                    existing["repair_provenance"] = deepcopy(repair)
                break

        if existing is None:
            model = json.loads(Path(configured["model_config_path"]).read_text())
            if evidence_frontier is not None:
                available = self._foundry_model_call_budget(foundry_stage, repair_panel_usage={})
                model_call_budget = available if model_call_budget is None else min(model_call_budget, available)
            model = self._stage_model_config(foundry_stage, model)
            # The foundry sandbox limit bounds generated code execution. Model
            # calls follow the configured route timeout and are additionally
            # bounded by this mission and any explicit foundry call limit.
            remaining = self._remaining()
            if remaining <= 0.2:
                raise ValidationError("capability foundry model has no safe request window remaining")
            if (type(model.get("timeout_seconds")) not in (int, float)
                    or not math.isfinite(model["timeout_seconds"])
                    or model["timeout_seconds"] <= 0):
                raise ValidationError("capability foundry model timeout_seconds must be finite and positive")
            timeout_bounds = [remaining]
            configured_model_timeout = configured.get("model_timeout_seconds")
            if configured_model_timeout is not None:
                timeout_bounds.append(configured_model_timeout)
            model["timeout_seconds"] = effective_model_timeout(
                model["timeout_seconds"], *timeout_bounds)
            if model_call_budget is not None and model_call_budget < 1:
                raise CapabilityModelBudgetExceeded(
                    "capability foundry has no model-call budget left in the experiment stage",
                    limit=0, observed=0, usage={})
            foundry_usage_before = deepcopy(self.foundry_usage)
            foundry = CapabilityFoundry(
                model,
                runtime_python=configured["runtime_python"],
                workspace_root=configured["workspace_root"],
                registry_root=configured["registry_root"],
                repo_root=configured["repo_root"],
                requirements_file=configured["requirements_file"],
                runtime_packages=[(item["name"], item["version"])
                                  for item in configured["runtime_packages"]],
                max_attempts=configured["max_attempts"],
                timeout_seconds=configured["timeout_seconds"],
                model_timeout_seconds=configured_model_timeout,
            )
            foundry_input = {}
            executable_work_orders = project_executable_work_orders(
                continuation_requests)
            if executable_work_orders:
                foundry_input["work_orders"] = executable_work_orders
            if source_data_manifest is not None:
                foundry_input["source_data_manifest"] = source_data_manifest
            evidence_projection = self._capability_evidence_projection(evidence_frontier)
            brief = {
                "topic": {key: selected.get(key) for key in (
                    "id", "title", "domain", "research_question", "scope",
                    "disconfirmation_test", "resource_plan", "data_regime",
                    "research_form", "evidence_mode", "comparison_type",
                    "feasibility_plan")},
                "repair_evidence_frontier": evidence_projection,
                "repair_evidence_frontier_sha256": hashlib.sha256(canonical_bytes(evidence_projection)).hexdigest()
                    if evidence_projection is not None else None,
                "evidence_policy": {
                    "requires_source_data_manifest": requires_source_data,
                    "source_data_status": (
                        "verified_current_manifest_available"
                        if source_data_manifest is not None else "unavailable"),
                    "open_requirements": requirement_scope["active"][:8],
                    "empirical_validation_limits": [
                        {
                            "requirement": item,
                            "disposition": "not_an_input_to_current_analytic_estimand",
                        }
                        for item in requirement_scope["out_of_scope"][:8]
                    ],
                    "rule": (
                        "Published, public-dataset, measured, or digitized observations must be "
                        "supplied as exact rows bound to immutable source artifacts. Without them, "
                        "do not invent values or claim empirical fit; return control to Research to "
                        "reformulate the evidence boundary."
                    ),
                },
                "source_challenge": result.get("source_challenge"),
                "continuation": {
                    "cycle": self.continuation_cycles if continuation_requests else None,
                    "prior_capability_id": (
                        prior_capability.get("capability_id")
                        if isinstance(prior_capability, dict) else None
                    ),
                    "requests": self._capability_authoring_follow_up_projection(
                        continuation_requests, repair_context=repair_context)
                    if continuation_requests else [],
                },
                "closest_prior_work": [{key: item.get(key) for key in (
                    "work_id", "title", "year", "abstract", "source_url")}
                    for item in result.get("candidate_prior_work", [])[:8]
                    if isinstance(item, dict)],
                "required_properties": [
                    "bounded reproducible experiment",
                    "raw observations sufficient for independent recalculation",
                    "at least three scientifically informative figures",
                    "no network access or undeclared data",
                ],
            }
            review_contract = self._capability_authoring_review_contract(
                brief["continuation"]["requests"])
            topic_obligations = []
            for survey_stage in self.workflow["stages"]:
                if survey_stage.get("kind") != "survey":
                    continue
                topic_stage = self._topic_stage_for_survey(survey_stage)
                if topic_stage is None or self.context.get(topic_stage["id"], {}).get("topic") != result.get("topic"):
                    continue
                obligation = self._topic_review_obligation(survey_stage)
                if obligation is not None:
                    topic_obligations.append({"obligation": obligation,
                        "reviewed_closure": deepcopy(self.context.get(survey_stage["id"], {}).get("follow_up_result"))})
            if topic_obligations:
                brief["topic_review_obligations"] = _preserve_response_value(topic_obligations)
            if review_contract is not None:
                brief["review_directive_contract"] = review_contract
            program_projection = self._topic_program_projection(result, max_alternatives=8)
            if program_projection is not None:
                brief["research_program"] = program_projection
            if isinstance(repair_context, dict):
                brief["capability_repair"] = self._capability_authoring_repair_projection(
                    repair_context)
                brief["repair_execution_contract"] = {
                    "evidence_priority": (
                        "The immutable failure, raw observations, source, and deterministic checks are "
                        "authoritative. Methods-panel diagnosis hypotheses and proposed changes must "
                        "be independently verified against them; do not edit code merely to satisfy a "
                        "reviewer or to make a failed verdict appear resolved."
                    ),
                    "sequence": [
                    "inspect the exact failure dossier, observed result, executor source, and validator source",
                    "use linked historical execution sources only as diagnostics, never as current-topic evidence",
                        "identify the first invalid mechanism or acceptance assumption",
                        "make a source-level repair that changes that mechanism rather than relabelling a threshold",
                        "run an independent sensitivity/recalculation check before registration",
                    ],
                    "required": [
                        "preserve the admitted research question and domain",
                        "retain the failed result as diagnostic evidence",
                        "return a fresh capability revision with exact provenance",
                        "pass replay, digest, independent recalculation, and methods review gates",
                    ],
                    "prohibited": [
                        "editing result JSON instead of the program",
                        "using NaN, endpoint, or constant fallback to hide an undefined estimand",
                        "claiming a resolved mechanism when the new run remains diagnostic",
                    ],
                }
            required_intent = {
                "domain": domain,
                "research_question": question,
            }
            if isinstance(stage_seconds, dict):
                required_intent["stage_seconds"] = deepcopy(stage_seconds)
            if study_type is not None:
                required_intent["study_type"] = study_type
            if isinstance(quality_contract, dict):
                required_intent["quality_contract"] = deepcopy(quality_contract)
            if superseded is not None:
                required_intent.update(id=superseded["id"], revision=superseded["revision"] + 1)
            if force_regenerate:
                revision = continuation_revision
                if type(revision) is not int or revision < 1:
                    revision = max(1, self.continuation_cycles + 1)
                required_intent.update({
                    "id": self._continuation_capability_id(selected, self.continuation_cycles),
                    "revision": revision,
                })
            try:
                repair_provenance = self._capability_repair_provenance(repair_context)
                if evidence_binding is not None:
                    repair_provenance = {**(repair_provenance or {}),
                                         "repair_evidence_frontier": evidence_binding}
                outcome = foundry.generate(
                    json.dumps(brief, ensure_ascii=False, sort_keys=True),
                    test_input=foundry_input or None,
                    required_intent=required_intent,
                    work_cache=ModelWorkCache(self.store, self._publish, namespace="command/foundry-work"),
                    on_progress=lambda phase, state: self._foundry_progress(stage_id or selected["id"], phase, state),
                    deadline=time.monotonic() + (
                        self._stage_remaining(stage_id)
                        if stage_id is not None else self._remaining()),
                    model_call_budget=model_call_budget,
                    repair_provenance=repair_provenance,
                )
            except Exception as exc:
                self._sync_foundry_usage()
                setattr(exc, "foundry_usage", self._usage_delta(
                    self.foundry_usage, foundry_usage_before))
                exc.usage = deepcopy(exc.foundry_usage)
                exc.usage_includes_foundry = True
                exc.usage_is_snapshot = False
                raise
            self._sync_foundry_usage()
            existing = {
                "capability_id": outcome["registration"]["capability_id"],
                "descriptor_path": outcome["registration"]["descriptor_path"],
                "reused": False, "attempts": outcome["attempts"],
                "admission": outcome["admission"],
                "foundry_usage": self._usage_delta(self.foundry_usage, foundry_usage_before),
            }
            if isinstance(outcome.get("admission", {}).get("repair_provenance"), dict):
                existing["repair_provenance"] = deepcopy(
                    outcome["admission"]["repair_provenance"])
            if force_regenerate:
                existing["continuation_cycle"] = self.continuation_cycles
        if not isinstance(existing.get("capability_id"), str):
            raise ValidationError("capability foundry did not return a capability identity")
        result["generated_capability"] = existing
        selected["experiment_capability_id"] = existing["capability_id"]
        for candidate in result.get("candidates", []):
            if isinstance(candidate, dict) and candidate.get("id") == selected.get("id"):
                candidate["experiment_capability_id"] = existing["capability_id"]
        return result

    def _apply_topic_to_experiment_config(self, stage, config, *, model_call_budget=None):
        """Select the admitted generated program or a pinned catalog capability.

        A foundry-backed topic becomes actionable only after its generated
        program and independent validator pass the complete admission gate.
        Legacy workflows may still select an explicitly configured template.
        In both cases, the current run supplies the accepted literature gate
        and project-local paths; model output never becomes a command directly.
        """
        by_id = {item["id"]: item for item in self.workflow["stages"]}
        ancestor_ids = self._stage_ancestor_ids(stage)
        topic_match = self._topic_context_for_stage(stage, ancestor_ids=ancestor_ids)
        if topic_match is None:
            return config
        current = config.get("experiment")
        if not isinstance(current, dict):
            raise ValidationError("experiment stage config must contain an experiment object")
        topic_stage_id, topic_context = topic_match
        pilot_survey = next((self.context[ancestor_id] for ancestor_id in ancestor_ids
            if self._allows_provisional_progress()
            and by_id[ancestor_id]["kind"] == "survey"
            and self.context.get(ancestor_id, {}).get("topic_admission") == "exploratory_pilot"
            and self.context[ancestor_id].get("gap_state") == "insufficient_evidence"
            and self.context[ancestor_id].get("survey_current") is True
            and self.context[ancestor_id].get("assessment_current") is True), None)
        if topic_context.get("admission_state") == "provisional_for_survey":
            eligible_surveys = []
            for ancestor_id in ancestor_ids:
                ancestor = by_id[ancestor_id]
                if ancestor.get("kind") != "survey":
                    continue
                survey_topic = self._topic_stage_for_survey(ancestor)
                if not isinstance(survey_topic, dict) or survey_topic.get("id") != topic_stage_id:
                    continue
                survey_context = self.context.get(ancestor_id)
                if (isinstance(survey_context, dict) and (
                        (survey_context.get("gap_state") == "eligible_for_experiment"
                         and survey_context.get("topic_admission") == "provisional_supported_for_experiment")
                        or (self._allows_provisional_progress()
                            and survey_context.get("topic_admission") == "exploratory_pilot"
                            and survey_context.get("gap_state") == "insufficient_evidence"
                            and survey_context.get("survey_current") is True
                            and survey_context.get("assessment_current") is True))):
                    eligible_surveys.append(ancestor_id)
                    if survey_context.get("topic_admission") == "exploratory_pilot":
                        pilot_survey = survey_context
            if not eligible_surveys:
                raise ValidationError(EXPERIMENT_SURVEY_ADMISSION_ERROR)
        selected = topic_context["topic"]
        generated = topic_context.get("generated_capability")
        continuation_requests = self._requests_for_stage(stage)
        prior_experiment = self.context.get(stage["id"])
        expected_capability_id = (
            generated.get("capability_id") if isinstance(generated, dict)
            else selected.get("experiment_capability_id")
        )
        # This decision is about the prior experiment context, not the new
        # attempt namespace in ``stage``. Keep its own project_dir as the
        # evidence boundary so a repair cannot silently reuse the old program.
        has_observed_experiment = self._has_executed_experiment_result(
            prior_experiment, expected_capability_id)
        pre_execution_capability_blocked = (
            isinstance(prior_experiment, dict)
            and prior_experiment.get("review_status") == "scientific_assignment_blocked"
            and (
                "capability foundry" in str(prior_experiment.get("error", "")).casefold()
                or isinstance(prior_experiment.get("failure_recovery"), dict)
                and prior_experiment["failure_recovery"].get("requires_capability_repair") is True
            )
            and not has_observed_experiment
        )
        capability_repair_attempts = self._pre_execution_repair_count(stage)
        # A pre-execution program rejection is materially different from an
        # additional experiment after observed data. Reopen a fresh capability
        # revision after each explicit Methods repair; mission-wide resource
        # fences and changed-artifact checks bound the work without abandoning
        # the research question after an arbitrary number of edits.
        fresh_pre_execution_repair = (
            pre_execution_capability_blocked
        )
        observed_experiment_repair = (
            has_observed_experiment
            and bool(self.continuation_cycles)
            and any(item.get("kind") in EXPERIMENT_WORK_ORDER_KINDS
                    for item in continuation_requests)
            and (
                (isinstance(prior_experiment, dict)
                 and prior_experiment.get("status") in STAGE_HOLD_STATUSES)
                or (isinstance(prior_experiment, dict)
                    and prior_experiment.get("review_status") == "scientific_assignment_blocked")
                or (isinstance(prior_experiment, dict)
                    and isinstance(prior_experiment.get("failure_debt"), dict))
                or (isinstance(prior_experiment, dict)
                    and prior_experiment.get("backfill_required") is True)
            )
        )
        needs_fresh_capability = (
            bool(self.continuation_cycles and continuation_requests)
            and any(item.get("kind") in EXPERIMENT_WORK_ORDER_KINDS
                    for item in continuation_requests)
                    and has_observed_experiment
        ) or fresh_pre_execution_repair
        if needs_fresh_capability and not self.workflow.get("capability_foundry_config_path"):
            raise ValidationError(
                "a substantive experiment continuation requires capability_foundry_config_path; "
                "a pinned catalog cannot silently repeat the prior experiment")
        repair_context = None
        repair_panel_required = fresh_pre_execution_repair or observed_experiment_repair
        if repair_panel_required and isinstance(prior_experiment, dict):
            # A failed capability or an observed scientific hold is a design
            # failure, not merely a malformed transport response. Ask the
            # methods pool to inspect the evidence before the foundry receives
            # another authoring call.
            repair_context = self._run_capability_repair_panel(
                stage, config, topic_context, prior_experiment,
                prior_experiment.get("error") or (
                    "observed experiment result requires a model-led methods repair"
                    if observed_experiment_repair
                    else "pre-execution capability authoring failed"
                ),
            )
            prior_experiment["capability_repair_panel"] = deepcopy(repair_context)
            # Keep the canonical blocker status while a fresh capability is
            # being authored. The recovery scheduler uses this status to
            # distinguish a real repair lineage from an ordinary observed
            # experiment continuation.
            if fresh_pre_execution_repair:
                prior_experiment["review_status"] = "scientific_assignment_blocked"
            self.context[stage["id"]] = prior_experiment
            panel_usage_delta = self._record_capability_repair_panel_usage(stage, repair_context)
            prior_experiment["capability_repair_panel"] = deepcopy(repair_context)
            if any(panel_usage_delta.values()):
                self._checkpoint(f"{stage['id']}:capability_repair_usage_charged", force=True)
            model_failure = repair_context.get("model_failure")
            if isinstance(model_failure, dict):
                fenced = ModelCallError.from_failure(
                    model_failure.get("error") or "Methods panel model request unavailable",
                    {**model_failure["failure"], "usage": {}})
                fenced.capability_repair_panel_attempted = True
                reviewed_packet = repair_context.get("packet")
                if (isinstance(reviewed_packet, dict)
                        and reviewed_packet.get("failure_lineage", {}).get("identity_verified") is True):
                    fenced.repair_subject = deepcopy(reviewed_packet.get(
                        "repair_subject_lineage", reviewed_packet.get("failure_lineage")))
                raise fenced
            if (repair_context.get("schema_version") in CAPABILITY_REPAIR_PLAN_SCHEMA_VERSIONS
                    and not self._capability_repair_plan_admitted(repair_context)):
                reason = repair_context.get("plan_validation_error")
                if not reason:
                    verifier = repair_context.get("verifier")
                    verifier = verifier if isinstance(verifier, dict) else {}
                    reason = self._capability_repair_verifier_unavailable_reason(verifier)
                    if reason is None:
                        open_concerns = verifier.get("open_concerns")
                        open_concerns = (open_concerns
                                         if isinstance(open_concerns, list) else [])
                        reason = (
                            "independent reviewer requires a revised plan: "
                            f"{str(open_concerns[0])[:1200]}" if open_concerns else
                            "independent reviewer did not accept the selected plan"
                        )
                blocked = ModelWorkBlocked(
                    "replacement capability withheld because the pre-execution Methods repair "
                    f"plan was not admitted: {reason}"
                )
                blocked.capability_repair_panel_attempted = True
                reviewed_packet = repair_context.get("packet")
                if (isinstance(reviewed_packet, dict)
                        and reviewed_packet.get("failure_lineage", {}).get("identity_verified") is True):
                    blocked.repair_subject = deepcopy(reviewed_packet.get(
                        "repair_subject_lineage", reviewed_packet.get("failure_lineage")))
                self._merge_incremental_error_usage(
                    blocked, repair_context.get("dispatch_usage"))
                blocked.repair_panel_usage = deepcopy(repair_context.get("dispatch_usage", {}))
                raise blocked
        if needs_fresh_capability and self.workflow.get("capability_foundry_config_path"):
            if repair_panel_required and isinstance(prior_experiment, dict):
                prior_experiment["capability_repair_attempts"] = capability_repair_attempts + 1
                self.context[stage["id"]] = prior_experiment
            foundry_model_call_budget = model_call_budget
            if repair_panel_required:
                foundry_model_call_budget = self._foundry_model_call_budget(
                    stage, repair_panel_usage=repair_context.get("dispatch_usage"))
            try:
                self._materialize_topic_capability(
                    topic_context, force_regenerate=True,
                    continuation_requests=continuation_requests,
                    continuation_revision=int((config.get("experiment") or {}).get("revision", 1)),
                    stage_id=stage["id"], study_type="exploratory" if pilot_survey else None,
                    stage_seconds=(config.get("experiment") or {}).get("stage_seconds"),
                    quality_contract=(current.get("quality_contract")
                                      if isinstance(current.get("quality_contract"), dict) else None),
                    model_call_budget=foundry_model_call_budget,
                    repair_context=repair_context)
            except Exception as exc:
                if self._capability_repair_panel_completed(repair_context):
                    exc.capability_repair_panel_completed = True
                self._merge_incremental_error_usage(
                    exc, repair_context.get("dispatch_usage"))
                exc.repair_panel_usage = deepcopy(repair_context.get("dispatch_usage", {}))
                raise
            generated = topic_context.get("generated_capability")
        elif self.workflow.get("capability_foundry_config_path"):
            # Capability authoring is downstream of the accepted literature
            # gate.  Do not spend the topic-stage wall generating an executable
            # program before the survey has tested whether the question is
            # actually worth executing.
            self._materialize_topic_capability(
                topic_context,
                continuation_requests=continuation_requests,
                continuation_revision=int((config.get("experiment") or {}).get("revision", 1)),
                stage_id=stage["id"],
                study_type="exploratory" if pilot_survey else None,
                stage_seconds=(config.get("experiment") or {}).get("stage_seconds"),
                quality_contract=(current.get("quality_contract")
                                  if isinstance(current.get("quality_contract"), dict)
                                  else None),
                model_call_budget=model_call_budget)
            generated = topic_context.get("generated_capability")
        if isinstance(generated, dict):
            capability_id = generated.get("capability_id")
            entry = {"id": capability_id, "config_path": generated.get("descriptor_path")}
        else:
            catalog = self.workflow.get("experiment_catalog") or []
            capability_id = selected.get("experiment_capability_id")
            entry = next((item for item in catalog if item["id"] == capability_id), None)
        if entry is None:
            if self.workflow.get("capability_foundry_config_path"):
                raise ValidationError("experiment stage could not materialize its generated experiment capability")
            if not self.workflow.get("experiment_catalog"):
                if pilot_survey is None:
                    return config
                template = deepcopy(config)
            else:
                raise ValidationError(
                    "topic selection must name one configured experiment capability")
        else:
            try:
                template = json.loads(Path(entry["config_path"]).read_text())
            except (OSError, ValueError) as exc:
                raise ValidationError(
                    f"experiment capability template is unreadable: {entry['config_path']}") from exc
        experiment = template.get("experiment") if isinstance(template, dict) else None
        if not isinstance(experiment, dict):
            raise ValidationError("experiment capability template must contain an experiment object")
        selected_experiment = deepcopy(experiment)
        if isinstance(current.get("quality_contract"), dict):
            selected_experiment["quality_contract"] = deepcopy(current["quality_contract"])
        # The template is a pinned capability, while the live literature gate
        # belongs to this mission and is supplied by Composer bindings below.
        selected_experiment["literature_gate"] = deepcopy(current.get("literature_gate"))
        if pilot_survey is not None:
            selected_experiment["study_type"] = "exploratory"
            selected_experiment["literature_gate"]["required_state"] = "insufficient_evidence"
            # Maturity requirements are deferred scientific obligations, not
            # part of the generated program's frozen execution contract.  The
            # foundry program was admitted against its own experiment_intent
            # limitations; appending survey requirements here changes that
            # intent after admission and makes an otherwise identical replay
            # fail with "output omits a frozen design limitation".  Keep the
            # requirements in supplied_context (and the downstream review
            # ledger) where they can constrain interpretation without
            # mutating the executable capability.
        selected_experiment["revision"] = int(current.get("revision", selected_experiment.get("revision", 1)))
        # A design-driven capability executes a bounded declarative design that
        # the topic stage proposed.  The program, estimators and data-process
        # families stay pinned; only the declared design and the scientific
        # identity of this mission are projected in.
        design_driven = bool((selected_experiment.get("parameters") or {}).get("design_driven"))
        design = selected.get("experiment_design")
        if design_driven:
            from scisaurus.runtime.topic_discovery import validate_experiment_design
            if not isinstance(design, dict):
                raise ValidationError(
                    "design-driven experiment capability requires a proposed experiment_design")
            design = validate_experiment_design(design)
            selected_experiment.setdefault("execution", {}).setdefault("input", {})["design"] = design
            parameters = dict(selected_experiment.get("parameters") or {})
            parameters["default_design"] = deepcopy(design)
            selected_experiment["parameters"] = parameters
            selected_experiment["seed"] = int(design["seed"])
            for key in ("domain", "research_question"):
                value = selected.get(key)
                if isinstance(value, str) and value.strip():
                    selected_experiment[key] = value.strip()
        elif isinstance(design, dict):
            raise ValidationError("fixed experiment capability cannot accept a proposed experiment_design")
        config["experiment"] = selected_experiment
        config["project_id"] = str(Path(stage["project_dir"]).resolve())
        for branch in ("execution", "validation"):
            client = config["experiment"][branch].get("client")
            if isinstance(client, dict):
                client["cwd"] = str(Path(stage["project_dir"]).resolve())
        context = config.get("supplied_context", "")
        config["supplied_context"] = (
            f"{context}\nSelected executable capability: {capability_id}.\n"
            f"Selected research question: {selected.get('research_question', '')}"
        )
        requirement_scope = self._topic_maturity_requirement_scope(
            selected, topic_context)
        maturity_requirements = requirement_scope["active"]
        if (topic_context.get("admission_state") == "provisional_for_survey"
                and isinstance(maturity_requirements, list) and maturity_requirements):
            config["supplied_context"] += (
                "\nThe topic entered evidence gathering provisionally. The experiment design, "
                "analysis, and interpretation must address these still-open intake requirements; "
                "the literature gap decision does not by itself resolve them:\n- "
                + "\n- ".join(str(item) for item in maturity_requirements[:8])
            )
        if requirement_scope["out_of_scope"]:
            config["supplied_context"] += (
                "\nEmpirical validation limits from the broader or prior evidence scope:\n- "
                + "\n- ".join(requirement_scope["out_of_scope"][:8])
                + "\nThe current estimand is self-contained analytical/synthetic work. Do not "
                "claim that it fits or validates measured observations; state this boundary in "
                "the interpretation and manuscript."
            )
        program_projection = self._topic_program_projection(topic_context, max_alternatives=8)
        if program_projection is not None:
            config["supplied_context"] += (
                "\nResearch program (provisional; use the selected branch's kill condition and conditional outcomes):\n"
                + json.dumps(program_projection, ensure_ascii=False, sort_keys=True)
            )
        return config

    @staticmethod
    def _synchronize_research_packet_identity(packet):
        """Replace stale template identity after a current result is bound."""
        if not isinstance(packet, dict):
            return packet
        results = packet.get("results_package")
        if not isinstance(results, dict):
            return packet
        question = results.get("question")
        if isinstance(question, str) and question.strip():
            packet["study_question"] = question
        procedure = next((item.get("description") for item in results.get("procedures", [])
                          if isinstance(item, dict) and isinstance(item.get("description"), str)
                          and item.get("description").strip()), None)
        if isinstance(procedure, str) and procedure.strip():
            packet["scope_statement"] = procedure
        # A packet prepared for another experiment must not retain its old
        # evidence IDs or literature prose.  The current survey projection is
        # added by the paper synchronizer; result IDs remain authoritative for
        # the interpretation and argument stages.
        result_ids = []
        for key in ("procedures", "metrics", "findings"):
            result_ids.extend(item.get("id") for item in results.get(key, [])
                              if isinstance(item, dict) and isinstance(item.get("id"), str))
        result_ids.extend(f"limitation-{index}" for index, _ in enumerate(results.get("limitations", [])))
        packet["evidence_ids"] = list(dict.fromkeys(result_ids))
        packet["literature_evidence"] = []
        packet["reference_cards"] = []
        packet.pop("survey_assessment", None)
        packet.pop("survey_lineage", None)
        return packet

    def _attach_stage_survey_evidence(self, packet, stage):
        """Use current accepted literature from this stage's dependency branch."""
        from scisaurus.runtime.paper import load_paper_survey
        from scisaurus.runtime.evidence import survey_evidence_projection
        ancestors = self._stage_ancestor_ids(stage)
        contexts = []
        for candidate in self.workflow.get("stages", []):
            if candidate["id"] not in ancestors or candidate.get("kind") != "survey":
                continue
            context = self.context.get(candidate["id"], {})
            if not context.get("survey_ref") or not context.get("assessment_ref"):
                continue
            contexts.append(context)
        if len(contexts) > 1:
            raise StateError("scientific evidence input has ambiguous accepted survey ancestors")
        for context in contexts:
            survey = load_paper_survey({"survey_project_dir": context["project_dir"],
                                       "survey_ref": context["survey_ref"],
                                       "assessment_ref": context["assessment_ref"],
                                       "document_type": "research_paper"}, require_eligible=False)
            packet.update(survey_evidence_projection(survey))
        return packet

    def _downstream_paper_stage(self, stage_id):
        """Find the paper consumer whose publication contract governs a stage."""
        by_id = {item["id"]: item for item in self.workflow["stages"]}
        pending = [item["id"] for item in self.workflow["stages"]
                   if item["kind"] == "paper" and stage_id in item.get("depends_on", [])]
        seen = set()
        while pending:
            candidate = pending.pop(0)
            if candidate in seen:
                continue
            seen.add(candidate)
            stage = by_id.get(candidate)
            if stage is None:
                continue
            if stage["kind"] == "paper":
                return stage
            pending.extend(next_stage["id"] for next_stage in by_id.values()
                           if candidate in next_stage.get("depends_on", []))
        # The direct-dependency walk above is sufficient for the ordinary
        # Composer graph.  Keep a transitive fallback for a branched workflow.
        for stage in by_id.values():
            if stage["kind"] != "paper":
                continue
            pending = list(stage.get("depends_on", []))
            visited = set()
            while pending:
                current = pending.pop()
                if current in visited:
                    continue
                visited.add(current)
                if current == stage_id:
                    return stage
                pending.extend(by_id.get(current, {}).get("depends_on", []))
        return None

    def _paper_depth_profile(self, stage_id):
        paper_stage = self._downstream_paper_stage(stage_id)
        if paper_stage is None:
            return None
        try:
            descriptor_path = Path(paper_stage["config_path"])
            descriptor = json.loads(descriptor_path.read_text())
            # Composer paper stages normally point at a small descriptor whose
            # ``paper_config_path`` names the independently versioned release
            # contract.  Read that nested contract before deciding whether an
            # upstream experiment/survey must satisfy journal-grade floors.
            nested_path = descriptor.get("paper_config_path")
            if isinstance(nested_path, str):
                candidate = Path(nested_path)
                if not candidate.is_absolute():
                    candidate = descriptor_path.parent / candidate
                if candidate.is_file():
                    descriptor = json.loads(candidate.read_text())
        except (OSError, ValueError, TypeError):
            return None
        if (descriptor.get("schema_version") == "paper-release-score-3"
                or descriptor.get("document_type") == "research_paper" and "depth_profile" in descriptor):
            try:
                from scisaurus.runtime.scholarly_depth import PROFILES, profile_for_paper
                return descriptor.get("depth_profile"), PROFILES[profile_for_paper(descriptor)]
            except (KeyError, ValidationError):
                return None
        return None

    def _ensure_journal_quality_contract(self, stage, config):
        """Bind a substantive analysis floor to experiments feeding a paper."""
        profile = self._paper_depth_profile(stage["id"])
        if self._allows_provisional_progress() and not self._requests_for_stage(stage):
            return config
        if profile is None or stage["kind"] != "experiment":
            return config
        experiment = config.get("experiment")
        if not isinstance(experiment, dict):
            return config
        from scisaurus.runtime.research_quality import ensure_minimum_quality_contract
        # The downstream journal floor is monotone: retain stricter local
        # requirements, but never let an older weak contract turn a research
        # paper into a thin validation note.
        experiment["quality_contract"] = ensure_minimum_quality_contract(
            experiment.get("quality_contract"), study_type=experiment.get("study_type"))
        return config

    def _argument_minimums(self, stage_id, config):
        """Keep the argument's scientific display floor independent of admission policy."""
        minimums = {"figures": 2, "tables": 1, "experiments": 2}
        profile = self._paper_depth_profile(stage_id)
        if profile is not None:
            _, floor = profile
            minimums["figures"] = max(minimums["figures"], int(floor.get("min_figures", 0)))
            minimums["tables"] = max(minimums["tables"], int(floor.get("min_tables", 0)))
        return minimums

    @staticmethod
    def _packet_unit_ids(packet):
        contract = packet.get("writer_contract", {}) if isinstance(packet, dict) else {}
        order = contract.get("section_order", []) if isinstance(contract, dict) else []
        ids = []
        for section in order:
            if not isinstance(section, dict):
                continue
            for unit_id in section.get("unit_ids", []):
                if isinstance(unit_id, str) and unit_id not in ids:
                    ids.append(unit_id)
        return ids

    def _synchronize_paper_figure_arguments(self, paper_config, packet, argument_package):
        """Carry every accepted result figure into the release bindings."""
        if paper_config.get("schema_version") != "paper-release-score-3":
            return paper_config
        results = packet.get("results_package") if isinstance(packet, dict) else None
        assets = [asset for asset in (results or {}).get("assets", [])
                  if isinstance(asset, dict) and asset.get("role") == "figure"]
        if not assets:
            return paper_config
        asset_ids = {asset.get("id") for asset in assets if isinstance(asset.get("id"), str)}
        # A paper descriptor can have been prepared against an earlier result
        # package.  Stale figure bindings are removed as one explicit
        # reconciliation step; carrying them forward would make the release
        # claim an asset that is no longer part of the accepted evidence.
        arguments = [item for item in paper_config.get("figure_arguments", [])
                     if isinstance(item, dict) and item.get("asset_id") in asset_ids]
        paper_config["figure_arguments"] = arguments
        known = {item.get("asset_id") for item in arguments}
        plan = {}
        argument = argument_package.get("argument") if isinstance(argument_package, dict) else None
        for item in (argument or {}).get("figure_plan", []):
            if isinstance(item, dict) and item.get("kind") == "figure" and isinstance(item.get("asset_id"), str):
                plan[item["asset_id"]] = item
        unit_ids = self._packet_unit_ids(packet)
        used_units = {item.get("unit_id") for item in arguments if isinstance(item, dict)}
        preferred = [unit_id for unit_id in unit_ids
                     if unit_id.startswith(("results_", "interpretation_"))]
        for asset in assets:
            asset_id = asset.get("id")
            if not isinstance(asset_id, str) or asset_id in known:
                continue
            planned = plan.get(asset_id, {})
            unit_id = next((item for item in preferred if item not in used_units), None)
            if unit_id is None:
                unit_id = next((item for item in preferred), None)
            if unit_id is None:
                # Let the normal release validator report an unbindable asset;
                # inventing a manuscript address would violate surgical edits.
                continue
            observation = planned.get("readout") or asset.get("caption")
            why = planned.get("purpose") or "This display exposes a result pattern needed by the argument."
            if not isinstance(observation, str) or not observation.strip():
                continue
            arguments.append({"asset_id": asset_id, "observation": observation,
                              "unit_id": unit_id, "why": why})
            known.add(asset_id)
            used_units.add(unit_id)
            contract = packet.get("writer_contract")
            if isinstance(contract, dict):
                readings = contract.setdefault("figure_readings", [])
                if not isinstance(readings, list):
                    readings = []
                    contract["figure_readings"] = readings
                readings[:] = [item for item in readings
                               if isinstance(item, dict) and item.get("asset_id") in asset_ids]
                if not any(isinstance(item, dict) and item.get("asset_id") == asset_id for item in readings):
                    readings.append({"asset_id": asset_id, "observation": observation,
                                     "unit_id": unit_id, "why": why})
        return paper_config

    def _synchronize_catalog_paper_inputs(self, paper_config, packet, argument_package):
        """Rebuild topic-dependent paper contracts from the accepted run.

        Free-topic stages begin with reusable descriptors so the Composer can
        validate a workflow before any provider call.  Those descriptors are
        structural templates, not scientific content.  Once a capability has
        produced a result, carrying the old claims, storyline, or figure jobs
        forward would make a new experiment wear the previous paper's skin.
        This projection keeps the section tree stable while replacing every
        content-bearing edge with the current result and accepted argument.
        """
        if not self.workflow.get("experiment_catalog"):
            return paper_config, packet
        if not isinstance(packet, dict):
            return paper_config, packet
        results = packet.get("results_package")
        if not isinstance(results, dict):
            return paper_config, packet

        argument = argument_package.get("argument") if isinstance(argument_package, dict) else None
        if isinstance(argument, dict):
            packet["research_argument"] = deepcopy(argument)
            if isinstance(argument_package.get("review"), dict):
                packet["research_argument_review"] = deepcopy(argument_package["review"])
            if isinstance(argument_package.get("argument_defense"), dict):
                packet["argument_defense"] = deepcopy(argument_package["argument_defense"])

        self._attach_topic_program(packet)

        question = results.get("question") or packet.get("study_question")
        if not isinstance(question, str) or not question.strip():
            question = "What mechanism explains the observed difference under the declared study conditions?"
        procedure = next((item.get("description") for item in results.get("procedures", [])
                           if isinstance(item, dict) and isinstance(item.get("description"), str)
                           and item["description"].strip()), None)
        scope = procedure or packet.get("scope_statement") or question
        if not isinstance(scope, str) or not scope.strip():
            scope = question
        packet["study_question"] = question
        packet["scope_statement"] = scope
        packet["composition_goal"] = (
            "Write a complete scientific paper for the selected study. Preserve the observed results, "
            "explain competing mechanisms, connect each figure to an argument, and keep the conclusion "
            "inside the declared data and design boundary."
        )

        # The packet is the writer's literature-facing context.  It is rebuilt
        # from the current accepted survey so background prose cannot inherit a
        # prior experiment's source cards.
        survey = None
        if "survey" in self.context:
            from scisaurus.runtime.paper import load_paper_survey
            # An accepted survey is a hard dependency of a research-paper
            # stage.  Let a broken or stale survey identity reach the normal
            # Composer retry path instead of silently falling back to an old
            # packet with no literature basis.
            survey = load_paper_survey(paper_config,
                require_eligible=not self._allows_provisional_progress())
        if isinstance(survey, dict):
            from scisaurus.runtime.evidence import survey_evidence_projection
            packet.update(survey_evidence_projection(survey))

        unit_ids = self._packet_unit_ids(packet)
        if not unit_ids:
            return paper_config, packet

        def unit_for(*prefixes):
            return next((item for item in unit_ids
                         if item.startswith(prefixes)), unit_ids[0])

        def first_text(items, key):
            return next((item.get(key) for item in items
                         if isinstance(item, dict) and isinstance(item.get(key), str)
                         and item[key].strip()), None)

        procedures = [item for item in results.get("procedures", []) if isinstance(item, dict)]
        metrics = [item for item in results.get("metrics", []) if isinstance(item, dict)]
        findings = [item for item in results.get("findings", []) if isinstance(item, dict)]
        raw_limitations = [item for item in results.get("limitations", []) if isinstance(item, str) and item.strip()]
        evidence, evidence_by_kind = [], {key: [] for key in ("procedure", "result", "finding", "limitation")}
        evidence_ids = set()

        def add_evidence(kind, locator, quote, relation="support"):
            if not isinstance(locator, str) or not locator.strip() or not isinstance(quote, str) or not quote.strip():
                return None
            prefix = {"procedure": "procedure", "result": "result", "finding": "finding",
                      "limitation": "limitation"}[kind]
            base = f"{prefix}-{locator.replace('/', '-') }".replace(" ", "-")
            base = re.sub(r"[^a-zA-Z0-9_-]", "-", base).strip("-").casefold()
            if not base or not base[0].isalpha():
                base = f"evidence-{prefix}"
            evidence_id = base[:64]
            suffix = 2
            while evidence_id in evidence_ids:
                stem = base[: max(1, 63 - len(str(suffix)))]
                evidence_id = f"{stem}-{suffix}"
                suffix += 1
            item = {"id": evidence_id, "kind": kind, "locator": locator,
                    "quote": quote, "relation": relation}
            evidence.append(item)
            evidence_ids.add(evidence_id)
            evidence_by_kind[kind].append(evidence_id)
            return evidence_id

        for item in procedures:
            add_evidence("procedure", item.get("id"), item.get("description"))
        for item in metrics:
            add_evidence("result", item.get("id"), item.get("presentation"))
        for item in findings:
            add_evidence("finding", item.get("id"), item.get("statement"))
        for index, limitation in enumerate(raw_limitations):
            add_evidence("limitation", f"limitation/{index}", limitation, "qualify")

        fallback_evidence = next((items for items in evidence_by_kind.values() if items), [])
        if not fallback_evidence:
            return paper_config, packet

        thesis = None
        if isinstance(argument, dict):
            primary = argument.get("primary_argument")
            if isinstance(primary, dict) and isinstance(primary.get("thesis"), str) and primary["thesis"].strip():
                thesis = primary["thesis"].strip()
        thesis = thesis or (findings[0].get("statement") if findings else question)
        result_proposition = first_text(findings, "statement") or first_text(metrics, "presentation") or question
        limitation_proposition = raw_limitations[0] if raw_limitations else (
            "The interpretation is limited to the declared data, model, and parameter range.")
        method_proposition = procedure or "The study follows the declared reproducible comparison protocol."
        beats = [
            {"id": "motivation", "role": "motivation",
             "proposition": f"The study examines {question.rstrip('?')} under a defined empirical boundary."},
            {"id": "question", "role": "question", "proposition": question},
            {"id": "method", "role": "method", "proposition": method_proposition},
            {"id": "result", "role": "result", "proposition": result_proposition},
            {"id": "interpretation", "role": "interpretation", "proposition": thesis},
            {"id": "limitation", "role": "limitation", "proposition": limitation_proposition},
            {"id": "conclusion", "role": "conclusion", "proposition": thesis},
        ]
        beat_evidence = {
            "motivation": evidence_by_kind["procedure"] or evidence_by_kind["result"] or fallback_evidence,
            "question": evidence_by_kind["procedure"] or evidence_by_kind["result"] or fallback_evidence,
            "method": evidence_by_kind["procedure"] or fallback_evidence,
            "result": evidence_by_kind["finding"] or evidence_by_kind["result"] or fallback_evidence,
            "interpretation": evidence_by_kind["finding"] or evidence_by_kind["result"] or fallback_evidence,
            "limitation": evidence_by_kind["limitation"] or fallback_evidence,
            "conclusion": evidence_by_kind["finding"] or evidence_by_kind["result"] or fallback_evidence,
        }
        beat_units = {
            "motivation": [unit_for("intro_")], "question": [unit_for("question_")],
            "method": [unit_for("methods_")], "result": [unit_for("results_")],
            "interpretation": [unit_for("interpretation_", "discussion_")],
            "limitation": [unit_for("limitations_")], "conclusion": [unit_for("conclusion_")],
        }

        if paper_config.get("schema_version") in {"paper-release-score-2", "paper-release-score-3"}:
            paper_config["storyline"] = {
                "id": str(paper_config.get("storyline", {}).get("id", "study-storyline")),
                "revision": int(paper_config.get("storyline", {}).get("revision", 1)) + 1,
                "thesis": thesis, "beats": beats,
            }
            paper_config["evidence"] = evidence
            paper_config["claims"] = [{
                "id": f"claim-{beat['id']}", "statement": beat["proposition"],
                "unit_ids": beat_units[beat["id"]],
                "evidence_ids": list(dict.fromkeys(beat_evidence[beat["id"]])),
                "storyline_id": beat["id"],
            } for beat in beats]
            topic = next((value.get("topic") for value in self.context.values()
                          if isinstance(value, dict) and value.get("kind") == "topic_discovery"
                          and isinstance(value.get("topic"), dict)), None)
            if isinstance(topic, dict) and isinstance(topic.get("title"), str) and topic["title"].strip():
                paper_config["title"] = topic["title"].strip()
            elif isinstance(results.get("id"), str):
                paper_config["title"] = results["id"].replace("_", " ").replace("-", " ").title()

        contract = packet.get("writer_contract") if isinstance(packet.get("writer_contract"), dict) else {}
        exact = []
        if procedure:
            exact.append({"text": procedure, "unit_id": unit_for("methods_")})
        for item in findings[:4]:
            exact.append({"text": item["statement"], "unit_id": unit_for("results_")})
        for item in raw_limitations[:2]:
            exact.append({"text": item, "unit_id": unit_for("limitations_")})
        exact.extend([
            {"text": question, "unit_id": unit_for("question_")},
            {"text": thesis, "unit_id": unit_for("interpretation_", "discussion_")},
        ])
        contract["required_exact_content"] = exact
        contract["required_citation_markers"] = [
            f"[[cite:{reference['key']}]]" for reference in paper_config.get("references", [])
            if isinstance(reference, dict) and isinstance(reference.get("key"), str)
        ]
        contract["figure_readings"] = [
            {"asset_id": item["asset_id"], "observation": item["observation"],
             "unit_id": item["unit_id"], "why": item["why"]}
            for item in paper_config.get("figure_arguments", [])
            if isinstance(item, dict)
        ]
        contract["surface_rules"] = [
            "Write for a scientific reader and keep execution bookkeeping out of the manuscript.",
            "Results report observations; interpretation and Discussion explain mechanisms and distinguish possibilities from established findings.",
            "Use each numeric result where it advances the argument and avoid repeating the same fact across sections.",
            "Limitations must state how the declared design boundary changes the interpretation.",
        ]
        packet["writer_contract"] = contract
        return paper_config, packet

    @staticmethod
    def _extend_paper_images(config, packet, paper_config):
        images = list(config.get("images", []))
        result_path = paper_config.get("results_package")
        base = Path(result_path).resolve().parent if isinstance(result_path, str) else None
        for asset in (packet.get("results_package", {}) or {}).get("assets", []):
            if not isinstance(asset, dict) or asset.get("role") != "figure" or base is None:
                continue
            candidate = (base / asset.get("path", "")).resolve()
            if candidate.is_file() and str(candidate) not in images:
                images.append(str(candidate))
        config["images"] = images
        return config

    def _adapt_continuation_config(self, stage, config):
        """Derive a fresh stage configuration from explicit research work orders."""
        kind = stage["kind"]
        stage_context = self.context.get(stage["id"], {})
        provider_fallback = stage_context.get("provider_fallback")
        provider_fallback = (
            provider_fallback if isinstance(provider_fallback, dict)
            and provider_fallback.get("mode") == "crossref_metadata" else None
        )
        requests = self._requests_for_stage(stage)
        if kind == "survey" and provider_fallback is not None:
            config["project_id"] = str(Path(stage["project_dir"]).resolve())
            survey = config.get("survey", {})
            search = survey.get("search", {})
            # Crossref supplies bounded bibliographic metadata, not an
            # OpenAlex citation graph. Keep this recovery deliberately small
            # and preserve the degraded provenance in the survey output;
            # OpenAlex can backfill the missing graph after its reset.
            survey["bibliography_fallback"] = "crossref_metadata"
            seed_count = len(survey.get("seed_work_ids", []))
            reserve = min(2, max(0, int(search.get("challenge_reserve", 0))))
            current_works = max(1, int(search.get("max_works", 20)))
            search["max_works"] = max(seed_count + reserve + 1, min(current_works, 20))
            search["challenge_reserve"] = min(reserve, search["max_works"] - 1)
            search["queries_per_role"] = max(1, min(int(search.get("queries_per_role", 2)), 2))
            search["results_per_query"] = max(1, min(int(search.get("results_per_query", 10)), 10))
            search["max_api_calls"] = max(1, min(int(search.get("max_api_calls", 32)), 32))
            search["max_full_texts"] = max(1, min(int(search.get("max_full_texts", 6)), 6))
            search["expansion_rounds"] = 0
            search["expansion_seed_count"] = 1
            search["saturation_rounds"] = 1
            if "max_analyzed_works" in search:
                search["max_analyzed_works"] = max(
                    reserve + 1,
                    min(int(search["max_analyzed_works"]), search["max_works"], 12),
                )
            survey["revision"] = int(survey.get("revision", 1)) + self.continuation_cycles
            self._augment_full_text_routes(config, self._prior_stage_project("survey", self.context))
        if not requests:
            return config
        quota_recovery = stage_context.get("quota_recovery")
        quota_recovery = quota_recovery if isinstance(quota_recovery, dict) else None
        if kind == "survey":
            config["project_id"] = str(Path(stage["project_dir"]).resolve())
            config["work_orders"] = self._follow_up_projection(requests)
            survey = config.get("survey", {})
            search = survey.get("search", {})
            if quota_recovery is not None:
                # A local allocation failure is not repaired by widening the
                # catalog. Reopen the durable checkpoint with one focused gate
                # pass and a smaller retrieval envelope.
                limits = config.setdefault("limits", {})
                current_rounds = limits.get("max_rounds")
                limits["max_rounds"] = (
                    1 if type(current_rounds) is not int else max(1, min(current_rounds, 1))
                )
                reserve = min(3, max(0, int(search.get("challenge_reserve", 0))))
                seed_count = len(survey.get("seed_work_ids", []))
                current_works = max(1, int(search.get("max_works", 40)))
                search["max_works"] = max(seed_count + reserve + 1, min(current_works, 40))
                reserve = min(reserve, search["max_works"] - 1)
                search["challenge_reserve"] = reserve
                search["max_full_texts"] = max(1, min(int(search.get("max_full_texts", 8)), 8))
                search["max_api_calls"] = max(1, min(int(search.get("max_api_calls", 48)), 48))
                search["expansion_rounds"] = 0
                search["saturation_rounds"] = 1
                search["expansion_seed_count"] = 1
                if "max_analyzed_works" in search:
                    search["max_analyzed_works"] = max(
                        reserve + 1,
                        min(int(search["max_analyzed_works"]), search["max_works"], 24),
                    )
            else:
                # Expansion is deliberate and bounded. It increases
                # discovery, full-text, and citation capacity together so the
                # next gate does not simply see more abstracts while
                # remaining evidence-poor.
                journal_profile = self._paper_depth_profile(stage["id"])
                if journal_profile is not None:
                    # A journal continuation must widen the search graph and
                    # the full-text frontier together. Increasing only the
                    # abstract limit creates a larger bibliography without
                    # improving the evidence needed for methods and
                    # related-work claims.
                    search["queries_per_role"] = min(8, max(search.get("queries_per_role", 1) + 1, 4))
                    search["results_per_query"] = min(100, max(search.get("results_per_query", 1) + 10, 50))
                    search["max_works"] = min(1000, max(search.get("max_works", 1) + 50, 120))
                    search["max_full_texts"] = min(100, max(search.get("max_full_texts", 1) + 10, 20))
                    search["max_api_calls"] = min(1000, max(search.get("max_api_calls", 1) + 60, 100))
                    search["challenge_reserve"] = min(20, max(search.get("challenge_reserve", 0), 5))
                    search["saturation_rounds"] = min(8, max(search.get("saturation_rounds", 1), 3))
                    search["expansion_seed_count"] = min(20, max(search.get("expansion_seed_count", 1), 4))
                else:
                    search["max_works"] = min(1000, max(search.get("max_works", 1) + 10, 20))
                    search["max_full_texts"] = min(100, max(search.get("max_full_texts", 1) + 5, 5))
                    search["max_api_calls"] = min(1000, max(search.get("max_api_calls", 1) + 20, 40))
            search["expansion_rounds"] = min(8, search.get("expansion_rounds", 0) + 1)
            if "max_analyzed_works" in search:
                # A continuation may widen discovery, but it must not turn a
                # repair request into a wholesale remap of the catalog.  Keep
                # the substantive-analysis increment small and independent of
                # the provider page size; citation and full-text work are
                # selected separately by the survey funnel.
                increment = max(1, min(5, search.get("results_per_query", 1) // 10 or 1))
                search["max_analyzed_works"] = min(
                    search["max_works"], search["max_analyzed_works"] + increment)
            survey["revision"] = int(survey.get("revision", 1)) + self.continuation_cycles
            self._augment_full_text_routes(config, self._prior_stage_project("survey", self.context))
        elif kind == "experiment":
            config["project_id"] = str(Path(stage["project_dir"]).resolve())
            experiment = config.get("experiment", {})
            experiment["revision"] = int(experiment.get("revision", 1)) + self.continuation_cycles
            config["work_orders"] = project_executable_work_orders(requests)
            context = config.get("supplied_context", "")
            config["supplied_context"] = (
                f"{context}\nStructured continuation work orders are supplied to the experiment executor "
                "and must be resolved with result-linked evidence or an explicit limitation.")
            if quota_recovery is not None:
                limits = config.setdefault("limits", {})
                current_rounds = limits.get("max_rounds")
                limits["max_rounds"] = (
                    1 if type(current_rounds) is not int else max(1, min(current_rounds, 1))
                )
                config["supplied_context"] += (
                    "\nBudget-recovery instruction: change the executable or measurement path, "
                    "preserve every prior failure as evidence, and stop after the first decisive "
                    "admission result. Do not regenerate the same program unchanged."
                )
        elif kind in {"interpretation", "paper"}:
            if kind == "paper" and config.get("schema_version") == "review-article-config-1":
                config["work_orders"] = self._follow_up_projection(requests)
                return config
            # These descriptors are intentionally strict.  Materialize an
            # immutable, cycle-specific packet instead of smuggling control
            # fields into the descriptor or rerunning with unchanged input.
            packet_key = "input_path" if kind == "interpretation" else "packet_path"
            self._materialize_follow_up_packet(stage, config, requests, packet_key)
        return config

    @staticmethod
    def _follow_up_projection(requests):
        return [{
            "id": item.get("id"),
            "kind": item["kind"],
            "owner": item.get("owner"),
            "objective": item["objective"],
            "why": item["why"],
            "success_condition": item["success_condition"],
            "evidence_needed": item["evidence_needed"],
            **({key: deepcopy(item[key]) for key in (
                "failure_dossier_ref", "failure_input_sha256", "repair_commands",
                "acceptance_checks", "review_directives", "model_diagnostics",
                "recovery_mode", "repair_policy_revision",
                "target_stage_id", "target_stage_kind",
                "repair_priority", "experiment_repair_plan", "repair_strategy",
                "attempt_lineage") if key in item}),
        } for item in requests]

    def _materialize_follow_up_packet(self, stage, config, requests, packet_key):
        source_value = config.get(packet_key)
        if not isinstance(source_value, str) or not Path(source_value).is_file():
            raise ValidationError(f"continuation {stage['kind']} packet is unreadable: {source_value}")
        try:
            packet = json.loads(Path(source_value).read_text())
        except (OSError, ValueError) as exc:
            raise ValidationError(f"continuation {stage['kind']} packet is not valid JSON: {source_value}") from exc
        if not isinstance(packet, dict):
            raise ValidationError(f"continuation {stage['kind']} packet must be a JSON object")
        packet = deepcopy(packet)
        packet["scientific_follow_up"] = self._follow_up_projection(requests)
        packet["follow_up_instruction"] = (
            "Address every supplied scientific follow-up by incorporating its evidence or analysis into this fresh pass. "
            "Keep unresolved explanations provisional and do not claim completion when the requested evidence is absent."
        )
        target = (Path(stage["project_dir"]).resolve() / "inputs"
                  / f"{stage['kind']}-follow-up-cycle-{self.continuation_cycles}.json")
        target.parent.mkdir(parents=True, exist_ok=True)
        body = canonical_bytes(packet)
        if target.exists() and target.read_bytes() != body:
            raise ValidationError(f"continuation packet was modified: {target}")
        if not target.exists():
            target.write_bytes(body)
        config[packet_key] = str(target)

    def _project_continuation_requests(self, packet, stage):
        """Give reopened interpretation and composition stages an explicit task.

        Their descriptors intentionally remain strict and immutable.  The
        scoped work order therefore travels with the fresh evidence packet,
        where the specialist can act on its objective and success condition
        without allowing Composer control vocabulary into the manuscript.
        """
        requests = self._requests_for_stage(stage)
        if not requests:
            return packet
        packet["scientific_follow_up"] = self._follow_up_projection(requests)
        packet["follow_up_instruction"] = (
            "Address every supplied scientific follow-up by incorporating its evidence or analysis into this fresh pass. "
            "Keep unresolved explanations provisional and do not claim completion when the requested evidence is absent."
        )
        return packet

    @staticmethod
    def _attempt_stage(stage, attempt_number):
        """Choose a retry workspace without discarding resumable stage state.

        SurveyRunner owns a durable work register and source checkpoint.  A
        provider failure should therefore reopen that same survey namespace;
        putting every retry in a new directory turns a recoverable role failure
        into a full literature restart.  Older runs created isolated survey
        attempts, so select the newest such directory when the base namespace
        has not yet been migrated.  Other stage kinds retain isolated retries.
        """
        candidate = deepcopy(stage)
        base = Path(stage["project_dir"]).resolve()
        if stage.get("kind") == "survey":
            durable_project = base
            if not (base / "state" / "control.sqlite").is_file():
                prior_attempts = []
                attempts_root = base / "attempts"
                if attempts_root.is_dir():
                    for path in attempts_root.iterdir():
                        if not path.is_dir() or not (path / "state" / "control.sqlite").is_file():
                            continue
                        try:
                            number = int(path.name.removeprefix("attempt-"))
                        except ValueError:
                            continue
                        if path.name == f"attempt-{number}":
                            prior_attempts.append((number, path))
                if prior_attempts:
                    durable_project = max(prior_attempts, key=lambda item: item[0])[1]
            candidate["project_dir"] = str(durable_project)
            candidate["reuse_completed"] = False
            candidate["reuse_output_path"] = None
            return candidate
        if attempt_number <= 1:
            return candidate
        candidate["project_dir"] = str(base / "attempts" / f"attempt-{attempt_number}")
        # A failed attempt is never a reusable checkpoint.  Successful stages
        # are skipped by the Composer before this helper is reached.
        candidate["reuse_completed"] = False
        candidate["reuse_output_path"] = None
        return candidate

    @staticmethod
    def _validate_survey_revalidation_scopes(request):
        from scisaurus.runtime.resume import RESUME_SCOPES
        scopes = request.get("resume_scopes")
        allowed = RESUME_SCOPES & {
            "mapping", "focused_review", "integrated_review", "gap_assessment", "follow_up"}
        if (request.get("kind") != "literature_expansion"
                or not isinstance(request.get("target_stage_id"), str)
                or request.get("target_stage_kind") != "survey"
                or not isinstance(scopes, list) or not scopes
                or any(not isinstance(scope, str) or scope not in allowed for scope in scopes)
                or len(scopes) != len(set(scopes))):
            raise ValidationError("survey revalidation requires an addressed literature order and unique analysis/review resume_scopes")
        return scopes

    def _survey_revalidation_recovery(self, stage, decision=None):
        """Read the immutable authorization for a same-owner review recovery."""
        if decision is None:
            head = self.store.head(f"command/composer/continuation/{self.continuation_cycles}")
            if head is None:
                return None
            _, _, decision = self._read_verified_artifact_json(head["artifact_ref"])
        ref = decision.get("revalidation_admission_ref")
        if ref is None:
            return None
        manifest, _, body = self._read_verified_artifact_json(ref)
        original, _, admission = self._read_verified_artifact_json(body["original_continuation_ref"])
        prior, _, previous = self._read_verified_artifact_json(body["prior_continuation_ref"])
        operator, _, instruction = self._read_verified_artifact_json(body["operator_request_ref"])
        request = body.get("request") or {}
        if (manifest.get("author") != "command.composer"
                or manifest["body_hash"] != decision.get("revalidation_admission_sha256")
                or body.get("schema_version") != "composer-survey-revalidation-admission-1"
                or body.get("cycle") != decision.get("cycle")
                or body.get("stage_id") != stage["id"]
                or body.get("project_dir") != str(Path(stage["project_dir"]).resolve())
                or original.get("author") != "command.composer"
                or original["body_hash"] != body.get("original_continuation_sha256")
                or prior.get("author") != "command.composer"
                or prior["body_hash"] != body.get("prior_continuation_sha256")
                or admission.get("action") != "continue_research"
                or previous.get("action") != "continue_research"
                or previous.get("cycle") != body["cycle"]
                or type(admission.get("cycle")) is not int
                or not admission["cycle"] < body["cycle"]
                or stage["id"] not in admission.get("reopened_stage_ids", [])
                or stage["id"] not in previous.get("reopened_stage_ids", [])
                or operator.get("author") != "command.operator"
                or operator["body_hash"] != body.get("operator_request_sha256")
                or instruction.get("action") != "resume_survey_reviews"
                or any(instruction.get(key) != body.get(key) for key in (
                    "stage_id", "cycle", "original_continuation_ref", "request_id",
                    "checkpoint_ref", "quota_failure_ref", "superseded_request_id"))
                or request.get("id") != body.get("request_id")
                or not any(canonical_bytes(item) == canonical_bytes(request)
                           for item in admission.get("research_requests", []))
                or not any(canonical_bytes(item) == canonical_bytes(request)
                           for item in decision.get("research_requests", []))):
            raise StateError("survey review recovery does not match its immutable operator admission")
        self._validate_survey_revalidation_scopes(request)
        dependency = body.get("dependency_replay")
        if dependency is not None and (
                not isinstance(dependency, dict)
                or instruction.get("dependency_failure_ref") != dependency.get("failure_ref")
                or instruction.get("resume_scopes") != dependency.get("resume_scopes")
                or instruction.get("plan_ref") != dependency.get("plan_ref")
                or canonical_bytes(instruction.get("review_obligations")) != canonical_bytes([
                    {key: value for key, value in item.items() if key not in {"receipt_ref", "receipt_body_sha256"}}
                    for item in dependency.get("review_obligations", [])])):
            raise StateError("survey dependency replay differs from its immutable operator admission")
        return body

    def _survey_review_recovery_evidence(self, current_stage, instruction, operator_request_ref):
        """Validate the retained request, milestone and technical failure without writes."""
        stage = next(item for item in self.workflow["stages"] if item["id"] == current_stage["id"])
        project = current_stage["project_dir"]
        head = self.store.head(f"command/composer/continuation/{self.continuation_cycles}")
        _, _, previous = self._read_verified_artifact_json(head["artifact_ref"])
        operator, _, _ = self._read_verified_artifact_json(operator_request_ref)
        original, _, admission = self._read_verified_artifact_json(instruction["original_continuation_ref"])
        checkpoint, _, state = self._read_verified_artifact_json(instruction["checkpoint_ref"])
        request = next((item for item in admission.get("research_requests", [])
                        if item.get("id") == instruction.get("request_id")), None)
        original_record = state.get("stages", state.get("stage_records", {})).get(stage["id"], {})
        milestone = original_record.get("completed_mapping")
        if (original.get("author") != "command.composer" or checkpoint.get("author") != "command.composer"
                or admission.get("action") != "continue_research"
                or type(admission.get("cycle")) is not int
                or not admission["cycle"] < self.continuation_cycles
                or state.get("continuation_cycles") != admission["cycle"]
                or stage["id"] not in admission.get("reopened_stage_ids", [])
                or previous.get("action") != "continue_research"
                or previous.get("cycle") != self.continuation_cycles
                or request is None or not isinstance(milestone, dict)
                or request.get("target_stage_id") != stage["id"]
                or self._scope_active_research_requests([request]) != [request]):
            raise StateError("survey review recovery has no exact original admission and completed mapping")
        declared = self._validate_survey_revalidation_scopes(request)
        previous_record, previous_cycle = self.stage_records.get(stage["id"]), self.continuation_cycles
        try:
            self.stage_records[stage["id"]] = {"completed_mapping": deepcopy(milestone)}
            self.continuation_cycles = admission["cycle"]
            scopes, verified_mapping = self._survey_revalidation_resume_plan(current_stage, declared)
        finally:
            self.stage_records[stage["id"]] = previous_record
            self.continuation_cycles = previous_cycle
        if verified_mapping is None or scopes != [scope for scope in declared if scope != "mapping"]:
            raise StateError("survey review recovery mapping milestone failed immutable owner replay")
        owned_orders = [*previous.get("research_requests", []),
                        *self.context.get(stage["id"], {}).get("research_requests", [])]
        superseded = next((item for item in owned_orders
                           if item.get("id") == instruction.get("superseded_request_id")), None)
        if (superseded is None or superseded.get("target_stage_id") != stage["id"]
                or superseded.get("kind") != "literature_expansion" or "resume_scopes" in superseded
                or not isinstance(superseded.get("failure_dossier_ref"), str)
                or not isinstance(superseded.get("failure_input_sha256"), str)):
            raise StateError("survey review recovery does not own the superseded order")
        dossier_manifest, _, dossier = self._read_verified_artifact_json(superseded["failure_dossier_ref"])
        with closing(sqlite3.connect((Path(project)/"state/control.sqlite").resolve().as_uri() + "?mode=ro", uri=True)) as connection:
            connection.row_factory = sqlite3.Row
            connection.execute("PRAGMA query_only=ON")
            store = ArtifactStore(SimpleNamespace(dir=str(Path(project).resolve()), _conn=connection))
            dependency = None
            if "dependency_failure_ref" in instruction:
                from scisaurus.runtime.survey import countersearch_lineage
                failure_record = store.get(instruction["dependency_failure_ref"])
                raw = store.read_body(failure_record["body_hash"])
                failure = json.loads(raw)
                observed = dossier.get("observed_result") or {}
                history = self.stage_records.get(stage["id"], {}).get("attempts", [])
                attempts = [item for item in history if item.get("failure_dossier_ref") == dossier_manifest["artifact_ref"]]
                if len(attempts) != 1:
                    raise StateError("dependency recovery has no unique owned failed attempt")
                attempt = self.tasks.get_attempt(attempts[0]["attempt_id"])
                payload = attempt.get("payload") or {}
                if (failure_record.get("author") != "command.controller"
                        or hashlib.sha256(raw).hexdigest() != failure_record["body_hash"]
                        or failure.get("project_id") != str(Path(project).resolve())
                        or failure.get("status") != "blocked" or failure.get("assessment_ref") is not None
                        or (failure.get("failure") or {}).get("kind") not in {None, "operational_state"}
                        or any(observed.get(key) != failure.get(key) for key in (
                            "status", "run_id", "survey_ref", "nomination_ref", "error", "assessment_ref"))
                        or dossier_manifest.get("author") != "command.composer"
                        or dossier.get("schema_version") != "composer-failure-recovery-1"
                        or dossier.get("stage_id") != stage["id"]
                        or dossier.get("project_dir") != str(Path(project).resolve())
                        or dossier.get("input_sha256") != superseded.get("failure_input_sha256")
                        or dossier.get("attempt_number") != payload.get("attempt_number")
                        or payload.get("stage_id") != stage["id"]
                        or payload.get("project_dir") != str(Path(project).resolve())
                        or type(payload.get("model_budget_cycle")) is not int
                        or not payload["model_budget_cycle"] < self.continuation_cycles
                        or not attempt["created_at"] <= failure_record["created_at"] <= dossier_manifest["created_at"] < head["created_at"]
                        or instruction.get("resume_scopes") != ["focused_review", "integrated_review", "gap_assessment"]):
                    raise StateError("dependency recovery does not own its failed producer and replay scope")
                configured = json.loads(store.read_body(milestone["config_sha256"]))
                lineage = countersearch_lineage(store.control, store, score_ref=failure["score_ref"],
                    question=configured["survey"]["question"], nomination_ref=failure["nomination_ref"],
                    plan_ref=instruction["plan_ref"], survey_ref=failure["survey_ref"])
                if lineage.get("complete") is not True:
                    raise StateError("dependency recovery lacks completed owned counter-search evidence")
                if ((failure.get("failure") or {}).get("kind") is None
                        and (failure.get("error") != "ValidationError: counter-search completion could not be bound to the accepted survey"
                             or not isinstance(lineage.get("origin_survey_ref"), str)
                             or not isinstance(lineage.get("planning_survey_ref"), str)
                             or lineage["origin_survey_ref"] == lineage["planning_survey_ref"])):
                    raise StateError("legacy dependency recovery has no reproduced nomination/planning mismatch and binding failure")
                from scisaurus.core.surveys import SurveyGate
                from scisaurus.runtime.survey import SurveyRunner
                obligations = instruction.get("review_obligations")
                if not isinstance(obligations, list) or any(not isinstance(item, dict) for item in obligations):
                    raise StateError("dependency recovery requires an explicit bounded review obligation list")
                review_validator = object.__new__(SurveyRunner)
                review_validator.gate = SurveyGate(store.control, store)
                review_validator.score = configured["survey"]
                checked_obligations = review_validator._validate_review_obligations([
                    {**deepcopy(item), "receipt_ref": operator_request_ref, "receipt_body_sha256": operator["body_hash"]}
                    for item in obligations])
                dependency = {"failure_ref": failure_record["artifact_ref"], "failure_sha256": failure_record["body_hash"],
                              "dossier_ref": dossier_manifest["artifact_ref"], "dossier_sha256": dossier_manifest["body_hash"],
                              "plan_ref": instruction["plan_ref"], "lineage": lineage, "resume_scopes": instruction["resume_scopes"],
                              "review_obligations": checked_obligations}
            else:
                failure_record = store.get(instruction["quota_failure_ref"])
                raw = store.read_body(failure_record["body_hash"])
                failure = json.loads(raw)
                quota = failure.get("budget_admission") or {}
                ModelCallError.from_failure(failure.get("error") or "quota rejection", failure)
                contexts = [item["ref"] for item in failure_record.get("inputs", []) if item.get("purpose") == "subject"]
                if len(contexts) != 1:
                    raise StateError("quota rejection has no unique request context")
                context_record = store.get(contexts[0]); context_raw = store.read_body(context_record["body_hash"])
                context = json.loads(context_raw)
                expected_scope = {"model_call_budget_path": str((self.root/"state/stage-model-call-budget.sqlite").resolve()),
                                  "model_call_budget_key": f"stage:{stage['id']}:cycle:{admission['cycle']}",
                                  "model_call_budget_limit": (stage.get("quota") or {}).get("max_model_calls")}
                registered = (context.get("client") or {}).get("model_call_budget_scopes", [])
                if (hashlib.sha256(raw).hexdigest() != failure_record["body_hash"]
                        or hashlib.sha256(context_raw).hexdigest() != context_record["body_hash"]
                        or failure.get("error_type") != "ModelBudgetExceededError"
                        or failure.get("outcome_known") is not True
                        or failure.get("attempts") != 0 or failure.get("usage") != {}
                        or quota.get("requested") != 1 or quota.get("reserved") != 0
                        or not isinstance(failure.get("error"), str) or not failure["error"]
                        or context.get("role") != failure_record.get("author")
                        or quota.get("dimension") != "model_calls"
                        or quota.get("path") != expected_scope["model_call_budget_path"]
                        or quota.get("key") != expected_scope["model_call_budget_key"]
                        or quota.get("limit") != expected_scope["model_call_budget_limit"]
                        or quota.get("observed") != quota.get("limit")
                        or not any(all(item.get(key) == value for key, value in expected_scope.items()) for item in registered)
                        or dossier_manifest.get("author") != "command.composer"
                        or dossier.get("schema_version") != "composer-failure-recovery-1"
                        or dossier.get("stage_id") != stage["id"]
                        or dossier.get("project_dir") != str(Path(project).resolve())
                        or dossier.get("input_sha256") != superseded.get("failure_input_sha256")
                        or failure["error"] not in dossier.get("error", "")
                        or not failure_record["created_at"] <= dossier_manifest["created_at"] < head["created_at"]):
                    raise StateError("superseded survey order is not proven to originate from this typed quota rejection")
            current_map = store.head("kb/literature-map")
            if current_map is None:
                raise StateError("survey review recovery has no retained current map")
            map_raw = store.read_body(current_map["body_hash"])
            configured = json.loads(store.read_body(milestone["config_sha256"]))
            if (hashlib.sha256(map_raw).hexdigest() != current_map["body_hash"]
                    or json.loads(map_raw).get("question") != configured.get("survey", {}).get("question")):
                raise StateError("survey review recovery current map does not match the declared question")
        deferred = [deepcopy(item) for item in previous.get("research_requests", [])
                    if item.get("id") != superseded["id"] and item.get("target_stage_id") == stage["id"]
                    and "resume_scopes" not in item]
        body = {"schema_version": "composer-survey-revalidation-admission-1", "stage_id": stage["id"],
                "cycle": self.continuation_cycles, "project_dir": str(Path(project).resolve()),
                "operator_request_ref": operator_request_ref, "operator_request_sha256": operator["body_hash"],
                "original_continuation_ref": original["artifact_ref"], "original_continuation_sha256": original["body_hash"],
                "prior_continuation_ref": head["artifact_ref"], "prior_continuation_sha256": head["body_hash"],
                "checkpoint_ref": checkpoint["artifact_ref"], "checkpoint_sha256": checkpoint["body_hash"],
                "request_id": request["id"], "request": deepcopy(request), "completed_mapping": verified_mapping,
                "current_map_ref": current_map["artifact_ref"], "current_map_sha256": current_map["body_hash"],
                "quota_failure_ref": failure_record["artifact_ref"], "quota_failure_sha256": failure_record["body_hash"],
                "superseded_request_id": superseded["id"], "superseded_request": deepcopy(superseded),
                "deferred_research_requests": deferred}
        if dependency is not None:
            body.pop("quota_failure_ref", None)
            body.pop("quota_failure_sha256", None)
            body["dependency_replay"] = dependency
        return body

    def admit_survey_review_recovery(self, *, operator_request_ref):
        """Restore a declared review under the already admitted stage allocation.

        Only replayed immutable failure provenance can retire a technically
        misclassified order. Other scientific orders remain pending while
        the explicitly requested review runs.
        """
        operator, _, instruction = self._read_verified_artifact_json(operator_request_ref)
        stage = next((item for item in self.workflow["stages"]
                      if item["id"] == instruction.get("stage_id")), None)
        common_fields = {"action", "stage_id", "cycle", "original_continuation_ref", "request_id",
                         "checkpoint_ref", "superseded_request_id"}
        quota_fields = common_fields | {"quota_failure_ref"}
        dependency_fields = common_fields | {"dependency_failure_ref", "plan_ref", "resume_scopes", "review_obligations"}
        if (operator.get("author") != "command.operator"
                or set(instruction) not in (quota_fields, dependency_fields)
                or instruction.get("action") != "resume_survey_reviews"
                or type(instruction.get("cycle")) is not int
                or instruction.get("cycle") != self.continuation_cycles
                or self._execution_started or self._remaining() <= 0
                or stage is None or stage.get("kind") != "survey"
                or stage["id"] not in self.continuation_pending_stage_ids
                or stage["id"] not in self.reopened_stage_ids):
            raise StateError("survey review recovery requires an explicit paused current-cycle operator request")
        head = self.store.head(f"command/composer/continuation/{self.continuation_cycles}")
        if head is None:
            raise StateError("survey review recovery has no current continuation")
        _, _, previous = self._read_verified_artifact_json(head["artifact_ref"])
        record = self.stage_records.get(stage["id"], {})
        project = record.get("project_dir") or self.context.get(stage["id"], {}).get("project_dir")
        if not isinstance(project, str):
            raise StateError("survey review recovery has no retained producer owner")
        current_stage = {**stage, "project_dir": str(Path(project).resolve())}
        self._survey_review_recovery_idle_frontier(current_stage)
        existing = self._survey_revalidation_recovery(current_stage, previous)
        if existing is not None:
            if existing["operator_request_ref"] != operator_request_ref:
                raise ConflictError("another operator review recovery already owns this cycle")
            return deepcopy(existing)
        body = self._survey_review_recovery_evidence(current_stage, instruction, operator_request_ref)
        request = body["request"]
        superseded = body["superseded_request"]
        verified_mapping = body["completed_mapping"]
        scopes = (body["dependency_replay"]["resume_scopes"] if "dependency_replay" in body
                  else [scope for scope in request["resume_scopes"] if scope != "mapping"])
        _, _, admission = self._read_verified_artifact_json(body["original_continuation_ref"])
        receipt = self._publish(f"command/composer/revalidation-admissions/{stage['id']}/{self.continuation_cycles}",
                                "decision_note", body, "command.composer")
        replacement = deepcopy(previous)
        replacement["research_requests"] = [deepcopy(item) for item in previous.get("research_requests", [])
                                             if item.get("id") != superseded["id"] and item.get("id") != request["id"]] + [deepcopy(request)]
        included = {item.get("id") for item in replacement["research_requests"]}
        replacement["research_requests"].extend(deepcopy(item) for item in admission.get("research_requests", [])
            if item.get("target_stage_id") != stage["id"] and item.get("id") not in included)
        replacement.update(revalidation_admission_ref=receipt["artifact_ref"], revalidation_admission_sha256=receipt["body_hash"])
        self._publish(f"command/composer/continuation/{self.continuation_cycles}", "decision_note", replacement, "command.composer")
        self.feedback.append(deepcopy(replacement))
        retained = [item for item in self.active_research_requests if item.get("id") not in {superseded["id"], request["id"]}]
        retained_ids = {item.get("id") for item in retained}
        retained.extend(deepcopy(item) for item in replacement["research_requests"] if item.get("id") not in retained_ids and item.get("id") != request["id"])
        self.active_research_requests = [*retained, deepcopy(request)]
        self.stage_records[stage["id"]]["completed_mapping"] = deepcopy(verified_mapping)
        stage_context = self.context.setdefault(stage["id"], {})
        for name in ("research_requests", "research_expansion_requests", "work_orders"):
            values = stage_context.get(name)
            if isinstance(values, list):
                stage_context[name] = [item for item in values if item.get("id") != superseded["id"]]
        stage_context.update(review_status="survey_revalidation", resume_scopes=scopes,
                             revalidation_admission_ref=receipt["artifact_ref"])
        self.status = "paused"
        self.department_activity.append({"action": "admit_same_cycle_survey_revalidation", "stage_id": stage["id"],
                                         "cycle": self.continuation_cycles, "admission_ref": receipt["artifact_ref"]})
        self._checkpoint(f"{stage['id']}:review_recovery_admitted", force=True)
        return deepcopy(body)

    @staticmethod
    def _interrupted_checkpoint_identity(body):
        """Exclude supervisor observations while retaining admitted execution state."""
        value = deepcopy(body)
        for key in ("status", "phase", "stop_reason", "updated_at_epoch", "elapsed_seconds",
                    "remaining_seconds", "observed_usage"):
            value.pop(key, None)
        blockers = value.get("blockers")
        if isinstance(blockers, list):
            value["blockers"] = [item for item in blockers if item != {
                "stage_id": "workflow", "reason": "KeyboardInterrupt: termination requested",
                "stop_reason": "process_interrupted"}]
        for record in value.get("stages", {}).values():
            if isinstance(record, dict):
                record.pop("child_progress", None)
                record.pop("specialist_live", None)
        return hashlib.sha256(canonical_bytes(value)).hexdigest()

    def _stopped_execution_checkpoint(self):
        """Replay the immutable owner of a stopped supervisor projection."""
        restored = self._restored_execution_frontier
        if (not isinstance(restored, dict) or restored.get("cycle") != self.continuation_cycles
                or restored.get("status") not in {"paused", "blocked"}):
            raise StateError("survey review recovery requires a restored stopped execution frontier")
        row = self.control._conn.execute(
            "SELECT artifact_ref FROM artifacts WHERE body_hash=? ORDER BY created_at DESC LIMIT 1",
            (restored["body_sha256"],)).fetchone()
        if row is None:
            if (restored.get("status") != "paused" or restored.get("stop_reason") != "process_interrupted"
                    or type(restored.get("state_revision")) is not int):
                raise StateError("restored survey frontier has no immutable checkpoint")
            candidates = self.control._conn.execute(
                "SELECT artifact_ref FROM artifacts WHERE artifact_ref LIKE "
                "'artifact:command/composer/checkpoints/%' ORDER BY created_at DESC LIMIT 16").fetchall()
            matches = []
            for candidate in candidates:
                candidate_manifest, _, candidate_body = self._read_verified_artifact_json(candidate["artifact_ref"])
                if (candidate_manifest.get("author") == "command.composer"
                        and candidate_body.get("status") == "running"
                        and candidate_body.get("state_revision") == restored["state_revision"]
                        and self._interrupted_checkpoint_identity(candidate_body) == restored.get("execution_sha256")):
                    matches.append((candidate_manifest, candidate_body))
            if len(matches) != 1:
                raise StateError("interrupted survey projection has no exact immutable execution owner")
            manifest, body = matches[0]
        else:
            manifest, _, body = self._read_verified_artifact_json(row["artifact_ref"])
        if (manifest.get("author") != "command.composer"
                or body.get("workflow_id") != self.workflow["id"]
                or body.get("continuation_cycles") != self.continuation_cycles):
            raise StateError("restored checkpoint does not own this workflow cycle")
        return manifest, body

    def _survey_review_recovery_idle_frontier(self, stage):
        """Require a durable stopped owner and an idle captured producer."""
        manifest, body = self._stopped_execution_checkpoint()
        record = body.get("stages", {}).get(stage["id"], {})
        if (stage["id"] not in body.get("continuation_pending_stage_ids", [])
                or stage["id"] not in body.get("reopened_stage_ids", [])
                or record.get("project_dir") != str(Path(stage["project_dir"]).resolve())):
            raise StateError("restored survey checkpoint does not own this pending producer")
        observed = self._read_json_object(Path(stage["project_dir"]) / "output/progress.json") or {}
        evidence = self._producer_checkpoint_evidence(stage["project_dir"], observed)
        if (evidence is None or observed.get("phase") not in {"calls_settled", "paused"}
                or observed.get("active_tasks") or observed.get("active_operations")):
            raise StateError("survey review recovery has no idle captured producer checkpoint")
        with closing(sqlite3.connect((Path(stage["project_dir"])/"state/control.sqlite").resolve().as_uri() + "?mode=ro", uri=True)) as connection:
            active = connection.execute("SELECT 1 FROM tasks WHERE state IN ('running','awaiting_review') LIMIT 1").fetchone()
            if active is not None:
                raise StateError("survey review recovery cannot replace an active producer")
        return {"checkpoint_ref": manifest["artifact_ref"], "checkpoint_sha256": manifest["body_hash"],
                "producer_checkpoint": evidence}

    def _survey_revalidation_scopes(self, stage):
        requests = [request for request in self._requests_for_stage(stage)
                    if "resume_scopes" in request]
        if not requests:
            return []
        if (stage.get("kind") != "survey" or stage["id"] not in self.reopened_stage_ids
                or stage["id"] not in self.continuation_pending_stage_ids):
            raise StateError("survey revalidation is not a pending admitted stage")
        head = self.store.head(f"command/composer/continuation/{self.continuation_cycles}")
        if head is None:
            raise StateError("survey revalidation has no immutable continuation admission")
        manifest, _, decision = self._read_verified_artifact_json(head["artifact_ref"])
        if (manifest.get("author") != "command.composer"
                or decision.get("action") != "continue_research"
                or decision.get("cycle") != self.continuation_cycles
                or stage["id"] not in decision.get("reopened_stage_ids", [])):
            raise StateError("survey revalidation continuation admission is not owned by its current cycle")
        scoped = self._scope_active_research_requests(requests)
        if len(scoped) != len(requests):
            raise StateError("survey revalidation request belongs to another topic")
        record = self.stage_records.get(stage["id"], {})
        retained_project = record.get("project_dir") or self.context.get(stage["id"], {}).get("project_dir") or stage["project_dir"]
        self._survey_revalidation_recovery({**stage, "project_dir": retained_project}, decision)
        scopes = []
        for request in requests:
            declared = self._validate_survey_revalidation_scopes(request)
            signature = self._research_request_signature(request)
            if not self._research_request_was_admitted(request) or not any(
                    isinstance(item, dict) and item.get("id") == request.get("id")
                    and self._research_request_signature(item) == signature
                    and item.get("resume_scopes") == declared
                    for item in decision.get("research_requests", [])):
                raise StateError("survey revalidation request does not match its immutable admission")
            scopes.extend(scope for scope in declared if scope not in scopes)
        return scopes

    def _survey_mapping_owner_cycle(self, stage, milestone, decision=None):
        recovery = self._survey_revalidation_recovery(stage, decision)
        if recovery is None:
            return self.continuation_cycles
        if canonical_bytes(milestone) != canonical_bytes(recovery.get("completed_mapping")):
            raise StateError("survey mapping differs from its explicitly retained admission")
        _, _, original = self._read_verified_artifact_json(recovery["original_continuation_ref"])
        return original["cycle"]

    def _survey_review_obligations(self, stage):
        recovery = self._survey_revalidation_recovery(stage)
        return deepcopy((recovery or {}).get("dependency_replay", {}).get("review_obligations", []))

    def _survey_producer_work_orders(self, stage):
        requests = self._requests_for_stage(stage)
        if self._survey_revalidation_recovery(stage) is not None:
            return []
        return self._follow_up_projection([item for item in requests if "resume_scopes" not in item])

    @staticmethod
    def _survey_resume_scope(prior, *, stage_context=None):
        """Resume from the last accepted milestone, subject to fresh gate checks."""
        context = stage_context if isinstance(stage_context, dict) else {}
        if (context.get("review_status") == "survey_integrity_repair"
                and context.get("resume_scope") == "integrated_review"):
            return "integrated_review"
        if (prior.get("survey_current") is True and prior.get("assessment_current") is True
                and prior.get("work_orders") and not prior.get("follow_up_result")):
            return "follow_up"
        if prior.get("survey_current") is True and prior.get("survey_ref"):
            return "gap_assessment"
        if isinstance(prior.get("coverage"), dict) and prior["coverage"].get("map_entry_count", 0) > 0:
            return "operations"
        return "focused_review"

    @staticmethod
    def _durable_stage_config(project_dir):
        """Read the immutable runner input from an existing stage workspace.

        Composer descriptors are templates.  Once a stage has been admitted,
        topic bindings, project identity, provider routes, and deadline
        projections are captured in the runner's ``inputs/run-config``
        artifact.  A legacy survey retry must resume that exact input rather
        than rebuilding it from today's template and accidentally turning a
        checkpoint migration into a different study.
        """
        project_dir = Path(project_dir)
        if not (project_dir / "state" / "control.sqlite").is_file():
            return None
        control = ControlStore(project_dir)
        try:
            store = ArtifactStore(control)
            head = store.head("inputs/run-config")
            if head is None:
                return None
            body = json.loads(store.read_body(head["body_hash"]))
            return body if isinstance(body, dict) else None
        except (OSError, TypeError, ValueError, KeyError):
            return None
        finally:
            control.close()

    def _record_retry_feedback(self, stage, *, attempt_number, retry_index, error, delay_seconds):
        """Record a retry decision before dispatching the next isolated attempt."""
        policy = self._retry_policy()
        event_id = f"composer-retry-{stage['id']}-{attempt_number}"
        topic_retry_reason = getattr(error, "topic_retry_reason", None)
        topic_retry = bool(getattr(error, "retryable_topic_intake", False))
        topic_pivot = (
            topic_retry_reason == "scientific_candidate_rejected"
            or bool(getattr(error, "rejected_topic_history", []))
        )
        feedback = {
            "event_id": event_id,
            "stage_id": stage["id"],
            "role": STAGE_ROLES[stage["kind"]],
            "from": COMMAND_ADDRESSES["progress"],
            "to": COMMAND_ADDRESSES["progress"],
            "status": "retrying",
            "action": "retry_stage",
            "attempt_number": attempt_number,
            "retry_index": retry_index,
            "retry_mode": policy.get("mode", "bounded"),
            "max_attempts": policy.get("max_attempts") if policy.get("mode", "bounded") == "bounded" else None,
            "delay_seconds": delay_seconds,
            "error": f"{type(error).__name__}: {error}",
            "retry_reason": (topic_retry_reason if topic_retry
                              else "transient_stage_failure"),
            "next_condition": (
                "abandon the rejected direction and sample a fresh topic portfolio within the remaining mission budget"
                if topic_pivot else
                "repair the topic intake contract and dispatch a fresh isolated proposal within the remaining mission budget"
                if topic_retry else
                "dispatch a fresh isolated stage attempt within the Composer hard deadline"
            ),
            "stage_deadline_seconds": stage["deadline_seconds"],
            "dependencies": list(stage["depends_on"]),
            "message_id": event_id,
            "message_disposition": "scheduled",
        }
        self.feedback.append(feedback)
        note = self._publish(
            f"command/composer/retry/{stage['id']}-{attempt_number}",
            "decision_note", feedback, "command.composer")
        self._route_feedback(feedback, note)

    def _retry_delay_seconds(self, error, retry_index):
        """Return the bounded backoff for one failed attempt."""
        policy = self._retry_policy()
        base_delay = float(policy["backoff_seconds"])
        if policy.get("mode", "bounded") == "until_deadline":
            base_delay = max(0.25, base_delay)
        rate_limit = getattr(error, "rate_limit", None)
        if (isinstance(rate_limit, dict)
                and rate_limit.get("provider") == "model"
                and rate_limit.get("retry_after_known") is not True):
            cooldown_index = getattr(error, "cooldown_retry_index", retry_index)
            cooldown_index = max(1, int(cooldown_index))
            delay = max(base_delay, DEFAULT_MODEL_RATE_LIMIT_COOLDOWN_SECONDS)
            delay *= 2 ** min(cooldown_index - 1, 16)
            return min(float(MAX_MODEL_RATE_LIMIT_COOLDOWN_SECONDS), delay)
        delay = min(60.0, base_delay * (2 ** min(max(0, retry_index - 1), 6)))
        provider_delay = getattr(error, "retry_after_seconds", None)
        if (type(provider_delay) in (int, float) and math.isfinite(provider_delay)
                and provider_delay > 0):
            delay = max(delay, float(provider_delay))
        return delay

    def _retry_fits(self, stage, *, delay, downstream_seconds):
        policy = self._retry_policy()
        remaining = self._remaining()
        if policy.get("mode", "bounded") == "until_deadline":
            required_window = self._deadline_dispatch_floor()
        else:
            required_window = min(float(stage["estimate_seconds"]), downstream_seconds)
        return remaining > delay + max(0.2, required_window)

    def _schedule_adaptive_retry(self, stage, *, attempt_number, error,
                                 downstream_seconds):
        """Defer a failed stage and return control to the global agenda.

        The retry remains deadline-bounded, but it no longer monopolizes the
        stage loop. Other dependency-ready work can run during its backoff and
        the Composer re-evaluates the complete frontier before the next call.
        """
        retry_index = max(1, attempt_number)
        delay = self._retry_delay_seconds(error, retry_index)
        if not self._retry_fits(stage, delay=delay, downstream_seconds=downstream_seconds):
            return False
        next_attempt = attempt_number + 1
        self._record_retry_feedback(
            stage, attempt_number=next_attempt, retry_index=retry_index,
            error=error, delay_seconds=delay)
        self.retry_schedule[stage["id"]] = {
            "not_before_epoch": time.time() + delay,
            "delay_seconds": delay,
            "failed_attempt_number": attempt_number,
            "next_attempt_number": next_attempt,
            "error": f"{type(error).__name__}: {error}",
        }
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "yield_retry_to_agenda",
            "stage_id": stage["id"],
            "failed_attempt_number": attempt_number,
            "next_attempt_number": next_attempt,
            "not_before_epoch": self.retry_schedule[stage["id"]]["not_before_epoch"],
        })
        return True

    def _wait_before_retry(self, stage, *, attempt_number, retry_index, error, downstream_seconds):
        """Pace a retry without sleeping past the hard deadline."""
        delay = self._retry_delay_seconds(error, retry_index)
        if not self._retry_fits(stage, delay=delay, downstream_seconds=downstream_seconds):
            return False
        self._record_retry_feedback(stage, attempt_number=attempt_number, retry_index=retry_index,
                                    error=error,
                                    delay_seconds=delay)
        wait_until = self.clock() + delay
        while True:
            left = wait_until - self.clock()
            if left <= 0:
                return True
            self._remaining()
            self._checkpoint(f"{stage['id']}:retry_wait")
            time.sleep(min(5.0, left))

    def _research_state(self):
        """Project the current research frontier for checkpoints and dashboards."""
        completed = {
            stage_id for stage_id, record in self.stage_records.items()
            if isinstance(record, dict) and record.get("status") in STAGE_READY_STATUSES
        }
        if self.continuation_pending_stage_ids:
            completed.difference_update(self.continuation_pending_stage_ids)
        ready = [
            stage["id"] for stage in self.workflow["stages"]
            if stage["id"] not in completed
            and set(stage["depends_on"]).issubset(completed)
        ]
        active = [
            stage_id for stage_id, record in self.stage_records.items()
            if isinstance(record, dict)
            and record.get("status") in {"running", "retrying", "paused"}
        ]
        topic_context = next((
            value for value in self.context.values()
            if isinstance(value, dict) and value.get("kind") == "topic_discovery"
            and isinstance(value.get("topic"), dict)
        ), None)
        topic = topic_context.get("topic", {}) if topic_context else {}
        program = topic_context.get("research_program", {}) if topic_context else {}
        if self.active_research_requests or self.reopened_stage_ids:
            phase = "repair_and_revalidation"
        elif any(self.stage_records.get(stage["id"], {}).get("status") in STAGE_READY_STATUSES
                 for stage in self.workflow["stages"] if stage["kind"] == "paper"):
            phase = "release_candidate"
        elif ready:
            kinds = {stage["id"]: stage["kind"] for stage in self.workflow["stages"]}
            phase = {
                "topic_discovery": "topic_exploration",
                "survey": "evidence_mapping",
                "experiment": "empirical_probe",
                "interpretation": "mechanism_interpretation",
                "argument": "claim_construction",
                "paper": "manuscript_and_review",
            }.get(kinds.get(ready[0]), "research")
        else:
            phase = "waiting_for_frontier"
        return {
            "mode": self._agenda_policy()["mode"],
            "phase": phase,
            "frontier_stage_ids": ready,
            "active_stage_ids": active,
            "completed_stage_ids": sorted(completed),
            "reopened_stage_ids": sorted(self.reopened_stage_ids),
            "active_work_order_ids": [
                item.get("id") for item in self.active_research_requests
                if isinstance(item, dict) and isinstance(item.get("id"), str)
            ],
            "deferred_retry_stage_ids": sorted(self.retry_schedule),
            "topic": ({
                "id": topic.get("id"),
                "title": topic.get("title"),
                "research_question": topic.get("research_question"),
                "admission_state": topic_context.get("admission_state"),
            } if topic else None),
            "retained_branch_count": (
                len(program.get("branches", []))
                if isinstance(program, dict) and isinstance(program.get("branches"), list)
                else 0
            ),
            "last_agenda_decision": (
                deepcopy(self.agenda_decisions[-1]) if self.agenda_decisions else None),
        }

    def _agenda_order(self, ready_stages, *, completed, by_id):
        """Rank dependency-ready stages by current expected information value."""
        ready_stages = list(ready_stages)
        if not ready_stages:
            return []
        policy = self._agenda_policy()
        if policy["mode"] == "ordered":
            ordered = ready_stages
            candidates = [{
                "stage_id": stage["id"], "kind": stage["kind"],
                "score": float(len(ready_stages) - index),
                "factors": ["workflow_declaration_order"],
            } for index, stage in enumerate(ready_stages)]
        else:
            from scisaurus.runtime.departments import REQUEST_STAGE_KINDS

            information_value = {
                "topic_discovery": 5.0,
                "survey": 6.0,
                "experiment": 6.0,
                "interpretation": 4.0,
                "argument": 2.5,
                "paper": 1.0,
            }
            request_kinds = {
                REQUEST_STAGE_KINDS.get(item.get("kind"))
                for item in self.active_research_requests if isinstance(item, dict)
            }
            decision_index = len(self.agenda_decisions) + 1
            candidates = []
            for declaration_index, stage in enumerate(ready_stages):
                stage_id = stage["id"]
                score = information_value.get(stage["kind"], 0.0)
                factors = [f"information_value={score:.2f}"]
                if stage["kind"] in request_kinds:
                    score += 8.0
                    factors.append("active_work_order=+8.00")
                if stage_id in self.reopened_stage_ids:
                    score += 4.0
                    factors.append("reopened_scope=+4.00")
                immediate_repairs = [
                    item for item in self.active_research_requests
                    if isinstance(item, dict)
                    and item.get("repair_priority") == "immediate"
                    and item.get("target_stage_id") == stage_id
                ]
                if immediate_repairs:
                    score += 16.0
                    factors.append("immediate_repair_order=+16.00")
                if stage_id in self.workflow["completion"]["required_stage_ids"]:
                    score += 0.5
                    factors.append("required_output=+0.50")
                unlocks = sum(
                    1 for candidate in by_id.values()
                    if stage_id in candidate["depends_on"]
                    and candidate["id"] not in completed
                )
                if unlocks:
                    score += min(1.5, unlocks * 0.4)
                    factors.append(f"unlocks={unlocks}")
                attempts = self.stage_records.get(stage_id, {}).get("attempt_count", 0)
                if type(attempts) is int and attempts > 0:
                    penalty = min(0.75, attempts * 0.05)
                    score -= penalty
                    factors.append(f"retry_cost=-{penalty:.2f}")
                # Seeded jitter changes only close decisions.  It provides
                # controlled exploration without allowing a writing stage to
                # outrank a ready evidence-producing stage by chance alone.
                material = (
                    f"{self.exploration_seed}:agenda:{self.continuation_cycles}:"
                    f"{decision_index}:{stage_id}"
                ).encode("utf-8")
                jitter = int(hashlib.sha256(material).hexdigest()[:8], 16) / 0xFFFFFFFF * 0.45
                score += jitter
                factors.append(f"seeded_exploration=+{jitter:.2f}")
                candidates.append({
                    "stage_id": stage_id,
                    "kind": stage["kind"],
                    "score": round(score, 6),
                    "factors": factors,
                    "declaration_index": declaration_index,
                })
            ranked = sorted(
                candidates,
                key=lambda item: (-item["score"], item["declaration_index"], item["stage_id"]),
            )
            rank = {item["stage_id"]: index for index, item in enumerate(ranked)}
            ordered = sorted(ready_stages, key=lambda stage: rank[stage["id"]])
            candidates = ranked
        decision = {
            "schema_version": "composer-agenda-decision-1",
            "decision_id": f"agenda-{len(self.agenda_decisions) + 1}",
            "created_at": now_iso(),
            "cycle": self.continuation_cycles,
            "mode": policy["mode"],
            "completed_stage_ids": sorted(completed),
            "candidate_stages": [{key: deepcopy(item[key]) for key in (
                "stage_id", "kind", "score", "factors")}
                for item in candidates],
            "selected_stage_id": ordered[0]["id"],
            "reason": (
                "selected the dependency-ready work with the highest expected information value, "
                "scoped work-order urgency, and downstream unlock value"
                if policy["mode"] == "adaptive"
                else "selected the first dependency-ready stage in workflow declaration order"
            ),
        }
        artifact = self._publish(
            f"command/composer/agenda/{len(self.agenda_decisions) + 1}",
            "decision_note", decision, "command.composer")
        decision["artifact_ref"] = artifact["artifact_ref"]
        self.agenda_decisions.append(decision)
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "select_agenda_stage",
            "selected_stage_id": decision["selected_stage_id"],
            "candidate_stage_ids": [item["stage_id"] for item in decision["candidate_stages"]],
            "agenda_decision_ref": artifact["artifact_ref"],
        })
        return ordered

    def _checkpoint(self, phase, *, force=False):
        now = self.clock()
        if not force and now < self.next_checkpoint:
            return
        # Refresh the organization only on the Composer thread.  The live
        # ticker consumes the cached plain-data projection below.
        self.organization_snapshot = deepcopy(self.departments.snapshot())
        remaining_snapshot = self.deadline - now
        if isinstance(self.deadline_epoch, (int, float)) and math.isfinite(self.deadline_epoch):
            remaining_snapshot = min(remaining_snapshot, self.deadline_epoch - time.time())
        self.state_revision += 1
        # Specialist callbacks publish a live card between stage-boundary
        # checkpoints.  Rebuilding ``stages`` from the durable stage records
        # used to erase those cards on the next ordinary checkpoint, leaving
        # the dashboard unable to distinguish an admitted role from an actual
        # provider call.  Carry only cards belonging to the current stage
        # assignment; completed/retired attempts must not look live.
        with self._progress_lock:
            previous_stages = deepcopy(self._progress_snapshot.get("stages", {}))
        checkpoint_stages = deepcopy(self.stage_records)
        for stage_id, record in checkpoint_stages.items():
            if not isinstance(record, dict) or record.get("status") != "running":
                continue
            previous = previous_stages.get(stage_id, {})
            live = previous.get("specialist_live") if isinstance(previous, dict) else None
            if not isinstance(live, dict):
                continue
            allowed_tasks = {
                item for item in record.get("assignment_task_ids", [])
                if isinstance(item, str)
            }
            if allowed_tasks:
                live = {
                    role: event for role, event in live.items()
                    if isinstance(event, dict) and event.get("task_id") in allowed_tasks
                }
            if live:
                record["specialist_live"] = live
                record["active_agents"] = self._active_specialist_roles(live)
        active_blockers = self._active_blockers()
        blocker_projection = {
            "active_blockers": active_blockers,
            "blocker_counts": {
                "active": len(active_blockers),
                "historical": len(self.blockers),
            },
        }
        state = {
            "schema_version": "composer-checkpoint-1", "workflow_id": self.workflow["id"],
            "run_id": self.run_id,
            "status": self.status, "phase": phase,
            "elapsed_seconds": max(0.0, now - self.started),
            "remaining_seconds": max(0.0, remaining_snapshot),
            "started_at_epoch": self.started_epoch, "deadline_at_epoch": self.deadline_epoch,
            "retry_policy": self._retry_policy(),
            "continuation_policy": self._continuation_policy(),
            "agenda_policy": self._agenda_policy(),
            "agenda_decisions": deepcopy(self.agenda_decisions),
            "retry_schedule": deepcopy(self.retry_schedule),
            "state_revision": self.state_revision,
            "research_state": self._research_state(),
            "exploration_seed": self.exploration_seed,
            "continuation_cycles": self.continuation_cycles,
            "continuation_budget_baseline": self._continuation_budget_baseline,
            "continuation_budget_used": self._continuation_budget_used(),
            "reopened_stage_ids": sorted(self.reopened_stage_ids),
            "continuation_pending_stage_ids": sorted(self.continuation_pending_stage_ids),
            "active_research_requests": deepcopy(self.active_research_requests),
            "attempted_request_signatures": sorted(self._attempted_request_signatures),
            "format_recovery_ledger": deepcopy(self.format_recovery_ledger),
            "department_activity": deepcopy(self.department_activity),
            "deadline_extensions": deepcopy(self.deadline_extensions),
            "stages": checkpoint_stages, "context": deepcopy(self.context),
            "feedback": deepcopy(self.feedback),
            "blockers": deepcopy(self.blockers), **blocker_projection,
            "usage": deepcopy(self.usage),
            "stage_usage_totals": deepcopy(self.stage_usage_totals),
            "pending_stage_usage": deepcopy(self.pending_stage_usage),
            "foundry_usage": deepcopy(self.foundry_usage),
            "deadline_decisions": deepcopy(self.deadline_decisions),
            "organization": deepcopy(self.organization_snapshot),
            "topic_history_path": str(self.topic_history_path),
            "topic_history_scope": self.topic_history_scope,
            "topic_history_entries": len(self.topic_history.get("entries", [])),
        }
        with self._progress_lock:
            self._overlay_child_progress(state)
            self._progress_snapshot = deepcopy(state)
        self._publish(f"command/composer/checkpoints/{len(self.feedback) + len(self.stage_records) + 1}",
                      "progress_checkpoint", state, "command.composer")
        with self._progress_lock:
            output = self.root / "output"
            output.mkdir(parents=True, exist_ok=True)
            _atomic_write_bytes(output / "progress.json", canonical_bytes(state))
        self.next_checkpoint = now + float(self.workflow["time_policy"]["checkpoint_seconds"])
        self.on_progress({"phase": state["phase"], "elapsed_seconds": round(state["elapsed_seconds"], 2),
                          "remaining_seconds": round(state["remaining_seconds"], 2),
                          "stages": deepcopy(state.get("stages", {})),
                          "blockers": deepcopy(state.get("active_blockers", [])),
                          "active_blockers": deepcopy(state.get("active_blockers", [])),
                          "blocker_counts": deepcopy(state.get("blocker_counts", {})),
                          "usage": deepcopy(state.get("usage", {})),
                          "observed_usage": deepcopy(state.get("observed_usage", state.get("usage", {}))),
                          "foundry_usage": deepcopy(state.get("foundry_usage", {})),
                          "organization": deepcopy(state["organization"])})

    def _live_progress(self, phase, *, epoch=None):
        """Publish a non-ledger progress tick while a provider call is active.

        A long model request may not emit a semantic event until it returns.
        The tick deliberately writes only the live checkpoint projection; it
        does not create a decision or alter task state. Durable control events
        continue to be written by ``_checkpoint`` at stage boundaries.
        """
        now = self.clock()
        remaining_snapshot = self.deadline - now
        if isinstance(self.deadline_epoch, (int, float)) and math.isfinite(self.deadline_epoch):
            remaining_snapshot = min(remaining_snapshot, self.deadline_epoch - time.time())
        # The ticker must not read mutable Composer state while a specialist
        # callback is updating it.  It consumes the last complete checkpoint
        # and changes only the heartbeat fields for this atomic write.
        with self._progress_lock:
            if epoch is not None and epoch != self._live_progress_epoch:
                return
            state = deepcopy(self._progress_snapshot)
            state["usage"] = deepcopy(self.usage)
            state.setdefault("organization", deepcopy(self.organization_snapshot))
            state.update({
                "schema_version": "composer-checkpoint-1", "workflow_id": self.workflow["id"],
                "run_id": self.run_id,
                "phase": (state.get("phase") if phase.endswith(":running")
                          and state.get("phase") == phase.split(":", 1)[0] + ":specialists" else phase),
                "elapsed_seconds": max(0.0, now - self.started),
                "remaining_seconds": max(0.0, remaining_snapshot),
                "started_at_epoch": self.started_epoch, "deadline_at_epoch": self.deadline_epoch,
            })
            self._overlay_child_progress(state)
            output = self.root / "output"
            output.mkdir(parents=True, exist_ok=True)
            _atomic_write_bytes(output / "progress.json", canonical_bytes(state))
            # Keep the heartbeat fields and specialist cards in the in-memory
            # base as well. The next specialist event must build on the latest
            # live state instead of restoring the last stage-boundary snapshot.
            self._progress_snapshot = deepcopy(state)
        self.on_progress({"phase": state["phase"], "elapsed_seconds": round(state["elapsed_seconds"], 2),
                          "remaining_seconds": round(state["remaining_seconds"], 2),
                          "stages": deepcopy(state.get("stages", {})),
                          "blockers": deepcopy(state.get("active_blockers", [])),
                          "active_blockers": deepcopy(state.get("active_blockers", [])),
                          "blocker_counts": deepcopy(state.get("blocker_counts", {})),
                          "usage": deepcopy(state.get("usage", {})),
                          "observed_usage": deepcopy(state.get("observed_usage", state.get("usage", {}))),
                          "foundry_usage": deepcopy(state.get("foundry_usage", {})),
                          "organization": deepcopy(state["organization"])})

    def _start_live_progress(self, stage):
        """Start a bounded ticker for one admitted stage."""
        # Durable checkpoint cadence may be deliberately coarse for large
        # artifacts, but the supervisor and dashboard need a much tighter
        # liveness signal while a provider/worker is active.
        interval = max(0.5, min(
            15.0, float(self.workflow["time_policy"]["checkpoint_seconds"])))
        stop = threading.Event()
        with self._progress_lock:
            self._live_progress_epoch += 1
            epoch = self._live_progress_epoch

        def tick():
            while not stop.wait(interval):
                try:
                    self._live_progress(f"{stage['id']}:running", epoch=epoch)
                except Exception:
                    # A live status tick must never hide the stage's real
                    # result or turn a completed provider call into a failure.
                    return

        thread = threading.Thread(target=tick, name=f"composer-progress-{stage['id']}", daemon=True)
        thread.start()

        def finish():
            with self._progress_lock:
                self._live_progress_epoch += 1
            stop.set()
            thread.join(timeout=min(interval, 2.0))

        return finish

    @staticmethod
    def _ready_stage_ids(state):
        stages = state.get("stages", {}) if isinstance(state, dict) else {}
        if not isinstance(stages, dict):
            return set()
        return {
            stage_id for stage_id, record in stages.items()
            if isinstance(record, dict) and record.get("status") in STAGE_READY_STATUSES
        }

    @classmethod
    def _checkpoint_advances_terminal_state(cls, checkpoint, terminal):
        """Recognize an in-flight checkpoint that supersedes a stale final report."""
        if (not isinstance(checkpoint, dict)
                or not (checkpoint.get("status") == "running"
                        or checkpoint.get("status") == "paused"
                        and cls._is_process_interruption_state(checkpoint))):
            return False
        if not isinstance(terminal, dict):
            return True
        checkpoint_revision = checkpoint.get("state_revision", 0)
        terminal_revision = terminal.get("state_revision", 0)
        if (type(checkpoint_revision) is int and checkpoint_revision >= 0
                and type(terminal_revision) is int and terminal_revision >= 0):
            if checkpoint_revision > terminal_revision:
                return True
            if checkpoint_revision < terminal_revision:
                return False
        checkpoint_ready = cls._ready_stage_ids(checkpoint)
        terminal_ready = cls._ready_stage_ids(terminal)
        if checkpoint_ready > terminal_ready:
            return True
        if checkpoint_ready != terminal_ready:
            return False

        # A retrying stage can make durable progress without changing the set
        # of ready dependencies.  Compare its attempt frontier as well, or a
        # stale terminal report can hide the only checkpoint that tells resume
        # which isolated attempt directory is safe to create next.
        def attempt_counts(state):
            stages = state.get("stages", {})
            if not isinstance(stages, dict):
                return {}
            counts = {}
            for stage_id, record in stages.items():
                if not isinstance(record, dict):
                    continue
                value = record.get("attempt_count", record.get("attempt_number", 0))
                if type(value) is int and value >= 0:
                    counts[stage_id] = value
            return counts

        checkpoint_counts = attempt_counts(checkpoint)
        terminal_counts = attempt_counts(terminal)
        if any(
            checkpoint_counts.get(stage_id, 0) > terminal_counts.get(stage_id, 0)
            for stage_id in checkpoint_counts
        ):
            return True
        checkpoint_agenda = checkpoint.get("agenda_decisions", [])
        terminal_agenda = terminal.get("agenda_decisions", [])
        return (isinstance(checkpoint_agenda, list)
                and isinstance(terminal_agenda, list)
                and len(checkpoint_agenda) > len(terminal_agenda))

    @staticmethod
    def _is_process_interruption_state(state):
        """Identify a checkpoint or report produced by a process-level stop."""
        if not isinstance(state, dict):
            return False
        if state.get("phase") == "paused_process_interruption":
            return True
        if state.get("stop_reason") == "process_interrupted":
            return True
        blockers = state.get("blockers")
        if isinstance(blockers, list) and any(
                isinstance(item, dict)
                and item.get("stage_id") == "workflow"
                and item.get("stop_reason") == "process_interrupted"
                for item in blockers):
            return True
        interim = state.get("interim_report")
        return (isinstance(interim, dict)
                and interim.get("stop_reason") == "process_interrupted")

    @staticmethod
    def _checkpoint_topic_frontier(checkpoint, topic_stage_id):
        if not isinstance(checkpoint, dict):
            return None, None, None
        contexts = checkpoint.get("context")
        context = contexts.get(topic_stage_id) if isinstance(contexts, dict) else None
        if not isinstance(context, dict):
            return None, None, None
        topic = context.get("topic")
        evolution = context.get("topic_evolution")
        return (
            topic if isinstance(topic, dict) else None,
            evolution if isinstance(evolution, dict) else None,
            context,
        )

    @classmethod
    def _unjustified_topic_refinement_error(cls, newer, older, topic_stage_id):
        """Detect a cross-phenomenon topic change mislabeled as refinement."""
        if not isinstance(newer, dict) or not isinstance(older, dict):
            return None
        newer_revision = newer.get("state_revision")
        older_revision = older.get("state_revision")
        if (type(newer_revision) is not int or type(older_revision) is not int
                or newer_revision <= older_revision):
            return None
        candidate, evolution, _ = cls._checkpoint_topic_frontier(
            newer, topic_stage_id)
        parent, _, _ = cls._checkpoint_topic_frontier(older, topic_stage_id)
        if (not isinstance(candidate, dict) or not isinstance(parent, dict)
                or evolution is None or evolution.get("mode") != "refinement"
                or not isinstance(evolution.get("parent_topic_id"), str)):
            return None
        try:
            validate_topic_refinement(parent, candidate, salvage_anchor=parent)
        except ValidationError as exc:
            return str(exc)
        return None

    @staticmethod
    def _merge_cumulative_usage(older, newer):
        """Keep the largest observed counters when restoring a prior lineage."""
        if isinstance(older, dict) and isinstance(newer, dict):
            merged = deepcopy(older)
            for key, value in newer.items():
                if key not in merged:
                    merged[key] = deepcopy(value)
                else:
                    merged[key] = ComposerRunner._merge_cumulative_usage(
                        merged[key], value)
            return merged
        if isinstance(older, list) and isinstance(newer, list):
            merged = deepcopy(older)
            for item in newer:
                if item not in merged:
                    merged.append(deepcopy(item))
            return merged
        if (type(older) in (int, float) and type(newer) in (int, float)
                and math.isfinite(older) and math.isfinite(newer)):
            return max(older, newer)
        return deepcopy(older)

    @staticmethod
    def _attempt_history_key(attempt):
        if not isinstance(attempt, dict):
            return None
        attempt_id = attempt.get("attempt_id")
        if isinstance(attempt_id, str) and attempt_id:
            return ("attempt_id", attempt_id)
        project_dir = attempt.get("project_dir")
        attempt_number = attempt.get("attempt_number")
        if isinstance(project_dir, str) and type(attempt_number) is int:
            return ("project_dir", project_dir, attempt_number)
        return None

    def _restore_topic_lineage_checkpoint(self, newer, older, topic_stage_id, reason):
        """Restore the prior topic frontier while retaining newer work as audit."""
        restored = deepcopy(older)
        topic, evolution, topic_context = self._checkpoint_topic_frontier(
            newer, topic_stage_id)
        restored_stages = restored.get("stages")
        newer_stages = newer.get("stages")
        if not isinstance(restored_stages, dict):
            restored_stages = {}
            restored["stages"] = restored_stages
        if not isinstance(newer_stages, dict):
            newer_stages = {}

        quarantined = []
        for stage_id, newer_record in newer_stages.items():
            if not isinstance(newer_record, dict):
                continue
            record = restored_stages.get(stage_id)
            if not isinstance(record, dict):
                record = {"kind": newer_record.get("kind"), "status": "retrying"}
                restored_stages[stage_id] = record

            older_attempts = record.get("attempts")
            older_attempts = list(older_attempts) if isinstance(older_attempts, list) else []
            known = {key for key in (self._attempt_history_key(item)
                                     for item in older_attempts) if key is not None}
            newer_attempts = newer_record.get("attempts")
            for attempt in newer_attempts if isinstance(newer_attempts, list) else []:
                key = self._attempt_history_key(attempt)
                if not isinstance(attempt, dict) or key is None or key in known:
                    continue
                compact = {
                    field: deepcopy(attempt[field])
                    for field in (
                        "attempt_id", "attempt_number", "cycle", "topic_id", "topic_cycle",
                        "project_dir", "failure_class", "failure_dossier_ref",
                        "repair_order_issued", "usage",
                    ) if field in attempt
                }
                source_state = attempt.get("state") or attempt.get("status")
                compact.update({
                    "state": "lineage_quarantined",
                    "source_state": source_state,
                    "lineage_reconciliation": "unjustified_topic_refinement",
                })
                error = attempt.get("error")
                if isinstance(error, str) and error:
                    compact["error"] = error[:2048]
                older_attempts.append(compact)
                known.add(key)
                quarantined.append({
                    "stage_id": stage_id,
                    "attempt_id": attempt.get("attempt_id"),
                    "attempt_number": attempt.get("attempt_number"),
                    "source_state": source_state,
                })
            record["attempts"] = older_attempts
            record["attempt_count"] = max(
                int(record.get("attempt_count", 0) or 0),
                int(newer_record.get("attempt_count", 0) or 0),
            )
            if isinstance(newer_record.get("usage"), dict):
                record["usage"] = self._merge_cumulative_usage(
                    record.get("usage", {}), newer_record["usage"])

            active_attempt_id = newer_record.get("attempt_id")
            if (newer_record.get("status") == "running"
                    and isinstance(active_attempt_id, str)):
                for field in (
                    "attempt_id", "attempt_number", "task_id", "project_dir",
                    "started_at_epoch", "lease_expiry",
                ):
                    if field in newer_record:
                        record[field] = deepcopy(newer_record[field])
                record["status"] = "running"

        # Resource accounting and the mission wall are cumulative even when a
        # bad topic branch is quarantined. Never refund real provider usage or
        # extend a deadline by restoring an older snapshot.
        for field in (
            "usage", "stage_usage_totals",
            "foundry_usage", "deadline_at_epoch", "deadline_seconds",
            "started_at_epoch", "elapsed_seconds", "remaining_seconds",
            "deadline_extensions", "deadline_decisions", "continuation_cycles",
            "continuation_budget_baseline", "continuation_budget_used",
            "state_revision", "topic_history_path", "topic_history_scope",
            "topic_history_entries",
        ):
            if field in newer:
                restored[field] = self._merge_cumulative_usage(
                    restored.get(field), newer[field])
        if "pending_stage_usage" in newer:
            restored["pending_stage_usage"] = deepcopy(newer["pending_stage_usage"])
        restored["status"] = "running"
        restored["phase"] = "resume:unjustified_topic_refinement_rejected"
        if (type(older.get("remaining_seconds")) in (int, float)
                and type(newer.get("remaining_seconds")) in (int, float)):
            restored["remaining_seconds"] = min(
                older["remaining_seconds"], newer["remaining_seconds"])

        audit = {
            "cycle": restored.get("continuation_cycles", 0),
            "action": "reject_unjustified_topic_refinement_checkpoint",
            "stage_id": topic_stage_id,
            "retained_topic_id": (
                self._checkpoint_topic_frontier(older, topic_stage_id)[0] or {}
            ).get("id"),
            "rejected_topic_id": topic.get("id") if isinstance(topic, dict) else None,
            "declared_parent_topic_id": (
                evolution.get("parent_topic_id") if isinstance(evolution, dict) else None
            ),
            "rejected_topic_title": topic.get("title") if isinstance(topic, dict) else None,
            "rejected_topic_phenomenon": (
                topic.get("phenomenon") if isinstance(topic, dict) else None
            ),
            "checkpoint_revision": newer.get("state_revision"),
            "restored_revision": older.get("state_revision"),
            "reason": reason[:2048],
            "quarantined_attempts": quarantined,
            "model_usage_preserved": deepcopy(newer.get("usage", {})),
            "topic_project_dir": (
                topic_context.get("project_dir") if isinstance(topic_context, dict) else None
            ),
        }
        return restored, audit

    def _latest_inflight_checkpoint(self, terminal=None):
        """Read the newest durable running checkpoint when output was finalized stale."""
        # One Composer checkpoint contains the full research context and can
        # be tens of megabytes.  The previous unbounded scan reparsed every
        # historical checkpoint during resume, making a normal restart look
        # hung after a long run.  Check only a small newest window: checkpoints
        # are append-only and the newest valid body is the only candidate that
        # can advance the terminal report.
        rows = self.control._conn.execute(
            "SELECT manifest_json FROM artifacts "
            "WHERE logical_id LIKE 'command/composer/checkpoints/%' "
            "ORDER BY created_at DESC LIMIT 8"
        ).fetchall()
        for row in rows:
            try:
                manifest = json.loads(row["manifest_json"])
                if manifest.get("artifact_type") != "progress_checkpoint":
                    continue
                checkpoint = json.loads(self.store.read_body(manifest["body_hash"]))
            except (KeyError, OSError, TypeError, ValueError):
                continue
            if (isinstance(checkpoint, dict)
                    and checkpoint.get("workflow_id") == self.workflow["id"]
                    and checkpoint.get("status") == "running"):
                if terminal is not None and not self._checkpoint_advances_terminal_state(checkpoint, terminal):
                    continue
                return checkpoint
        return None

    def _restore(self):
        timing_state = None
        # The run input is the earliest durable record and carries the seed
        # even when a process exits before its first stage checkpoint.
        run_input = self.store.head("inputs/composer-run")
        if run_input is not None:
            try:
                input_body = json.loads(self.store.read_body(run_input["body_hash"]))
            except (OSError, TypeError, ValueError):
                input_body = None
            if (isinstance(input_body, dict) and type(input_body.get("exploration_seed")) is int
                    and input_body["exploration_seed"] >= 0):
                self.exploration_seed = input_body["exploration_seed"]
            input_agenda = input_body.get("agenda_policy") if isinstance(input_body, dict) else None
            if ("agenda_policy" not in self.workflow
                    and isinstance(input_agenda, dict)
                    and input_agenda.get("mode") in {"adaptive", "ordered"}):
                self._restored_agenda_policy = {"mode": input_agenda["mode"]}
        head = self.store.head("command/composer/run")
        head_status = None
        head_body = None
        if head is not None:
            body = json.loads(self.store.read_body(head["body_hash"]))
            head_body = body
            self.status = body.get("status", "running")
            head_status = self.status
            self.stage_records = body.get("stages", {})
            self.context = body.get("context", {})
            self.feedback = body.get("feedback", [])
            self.blockers = body.get("blockers", [])
            self.usage = body.get("usage", self.usage)
            self.stage_usage_totals = body.get("stage_usage_totals", {})
            self.pending_stage_usage = body.get("pending_stage_usage", {})
            self.foundry_usage = body.get("foundry_usage", {})
            self.deadline_decisions = body.get("deadline_decisions", [])
            self.agenda_decisions = body.get("agenda_decisions", [])
            self.retry_schedule = body.get("retry_schedule", {})
            if not isinstance(self.retry_schedule, dict):
                self.retry_schedule = {}
            revision = body.get("state_revision", 0)
            if type(revision) is int and revision >= 0:
                self.state_revision = revision
            restored_agenda = body.get("agenda_policy")
            if ("agenda_policy" not in self.workflow
                    and isinstance(restored_agenda, dict)
                    and restored_agenda.get("mode") in {"adaptive", "ordered"}):
                self._restored_agenda_policy = {"mode": restored_agenda["mode"]}
            self.continuation_cycles = body.get("continuation_cycles", 0)
            self.reopened_stage_ids = set(body.get("reopened_stage_ids", []))
            self.continuation_pending_stage_ids = set(body.get("continuation_pending_stage_ids", []))
            self.active_research_requests = body.get("active_research_requests", [])
            ledger = body.get("format_recovery_ledger")
            if isinstance(ledger, dict):
                self.format_recovery_ledger = deepcopy(ledger)
            self.department_activity = body.get("department_activity", [])
            self.deadline_extensions = body.get("deadline_extensions", [])
            if (type(body.get("exploration_seed")) is int
                    and body["exploration_seed"] >= 0):
                self.exploration_seed = body["exploration_seed"]
            if (isinstance(body.get("organization"), dict)
                    and body["organization"].get("schema_version") == self.departments.organization["schema_version"]):
                self.organization_snapshot = deepcopy(body["organization"])
            self._progress_snapshot = deepcopy(body)
            timing_state = body
        progress_path = self.root / "output" / "progress.json"
        # A process can die after a checkpoint but before publishing the final
        # run report.  Restore that checkpoint as the authoritative in-flight
        # state so the next Composer invocation can mark an interrupted
        # attempt unknown and dispatch a fresh one.  If cleanup did publish a
        # stale terminal report afterward, recover the newest durable running
        # checkpoint only when it contains strictly more admitted stages.
        checkpoint = None
        if progress_path.is_file():
            try:
                checkpoint = json.loads(progress_path.read_text())
            except (OSError, ValueError):
                checkpoint = None
        interrupted_pause = self._is_process_interruption_state(head_body)
        if head is None or head_status == "running":
            live_checkpoint = checkpoint if isinstance(checkpoint, dict) else self._latest_inflight_checkpoint()
        elif interrupted_pause and isinstance(checkpoint, dict):
            # SIGINT/KeyboardInterrupt publishes a paused final report after
            # the same attempt-boundary checkpoint.  That checkpoint is the
            # authoritative frontier even when its revision and attempt
            # count are equal to the final report; requiring a strictly
            # larger frontier would discard the only record that marks the
            # in-flight attempt for result-unknown reconciliation.
            live_checkpoint = checkpoint
        elif self._checkpoint_advances_terminal_state(checkpoint, head_body):
            live_checkpoint = checkpoint
        else:
            # The newest running checkpoint may belong to a failed resume and
            # may have fewer attempts than an older checkpoint from the
            # interrupted process.  Scan until an actually advancing one is
            # found instead of returning the first stale candidate.
            live_checkpoint = self._latest_inflight_checkpoint(head_body)
        topic_stage = next((item for item in self.workflow.get("stages", [])
                            if isinstance(item, dict)
                            and item.get("kind") == "topic_discovery"), None)
        if isinstance(topic_stage, dict):
            lineage_error = self._unjustified_topic_refinement_error(
                live_checkpoint, head_body, topic_stage["id"])
            if lineage_error:
                live_checkpoint, reconciliation = self._restore_topic_lineage_checkpoint(
                    live_checkpoint, head_body, topic_stage["id"], lineage_error)
                self._restored_topic_lineage_reconciliation = reconciliation
        selected_state = live_checkpoint if isinstance(live_checkpoint, dict) else timing_state
        if isinstance(selected_state, dict):
            self._restored_execution_frontier = {
                "cycle": selected_state.get("continuation_cycles"), "status": selected_state.get("status"),
                "body_sha256": hashlib.sha256(canonical_bytes(selected_state)).hexdigest(),
                "execution_sha256": self._interrupted_checkpoint_identity(selected_state),
                "state_revision": selected_state.get("state_revision"),
                "stop_reason": selected_state.get("stop_reason"),
            }
        if isinstance(live_checkpoint, dict):
            timing_state = live_checkpoint
            self.stage_records = live_checkpoint.get("stages", self.stage_records)
            if "context" in live_checkpoint:
                self.context = live_checkpoint.get("context", self.context)
            self.feedback = live_checkpoint.get("feedback", self.feedback)
            self.blockers = live_checkpoint.get("blockers", self.blockers)
            self.usage = live_checkpoint.get("usage", self.usage)
            self.stage_usage_totals = live_checkpoint.get("stage_usage_totals", {})
            self.pending_stage_usage = live_checkpoint.get("pending_stage_usage", {})
            self.foundry_usage = live_checkpoint.get("foundry_usage", {})
            self.deadline_decisions = live_checkpoint.get("deadline_decisions", self.deadline_decisions)
            self.agenda_decisions = live_checkpoint.get(
                "agenda_decisions", self.agenda_decisions)
            retry_schedule = live_checkpoint.get("retry_schedule", self.retry_schedule)
            if isinstance(retry_schedule, dict):
                self.retry_schedule = retry_schedule
            revision = live_checkpoint.get("state_revision", self.state_revision)
            if type(revision) is int and revision >= 0:
                self.state_revision = revision
            restored_agenda = live_checkpoint.get("agenda_policy")
            if ("agenda_policy" not in self.workflow
                    and isinstance(restored_agenda, dict)
                    and restored_agenda.get("mode") in {"adaptive", "ordered"}):
                self._restored_agenda_policy = {"mode": restored_agenda["mode"]}
            self.continuation_cycles = live_checkpoint.get("continuation_cycles", self.continuation_cycles)
            self.reopened_stage_ids = set(live_checkpoint.get("reopened_stage_ids", self.reopened_stage_ids))
            self.continuation_pending_stage_ids = set(live_checkpoint.get(
                "continuation_pending_stage_ids", self.continuation_pending_stage_ids))
            self.active_research_requests = live_checkpoint.get(
                "active_research_requests", self.active_research_requests)
            ledger = live_checkpoint.get("format_recovery_ledger")
            if isinstance(ledger, dict):
                self.format_recovery_ledger = deepcopy(ledger)
            self._restore_attempted_research_request_signatures(live_checkpoint)
            self.department_activity = live_checkpoint.get("department_activity", self.department_activity)
            self.deadline_extensions = live_checkpoint.get("deadline_extensions", self.deadline_extensions)
            if (type(live_checkpoint.get("exploration_seed")) is int
                    and live_checkpoint["exploration_seed"] >= 0):
                self.exploration_seed = live_checkpoint["exploration_seed"]
            if (isinstance(live_checkpoint.get("organization"), dict)
                    and live_checkpoint["organization"].get("schema_version") == self.departments.organization["schema_version"]):
                self.organization_snapshot = deepcopy(live_checkpoint["organization"])
            self._progress_snapshot = deepcopy(live_checkpoint)
        self._restore_context_from_stage_records()
        self._hydrate_provisional_handoffs()
        # Older Composer reports did not carry an epoch fence.  They retain
        # their historical restart behavior; every new run persists the
        # fields above so future resumes remain inside one mission wall.
        if isinstance(timing_state, dict):
            started_epoch = timing_state.get("started_at_epoch")
            deadline_epoch = timing_state.get("deadline_at_epoch")
            if (type(started_epoch) in (int, float) and math.isfinite(started_epoch)
                    and type(deadline_epoch) in (int, float) and math.isfinite(deadline_epoch)
                    and deadline_epoch >= started_epoch):
                self.started_epoch = float(started_epoch)
                self.deadline_epoch = float(deadline_epoch)
                elapsed_hint = timing_state.get("elapsed_seconds", 0.0)
                if type(elapsed_hint) not in (int, float) or not math.isfinite(elapsed_hint) or elapsed_hint < 0:
                    elapsed_hint = 0.0
                wall_elapsed = max(0.0, time.time() - self.started_epoch)
                elapsed = max(float(elapsed_hint), wall_elapsed)
                self.started = self.clock() - elapsed
                # Rebuild the live monotonic fence from the persisted wall
                # fence, including any explicit extensions.  Reapplying only
                # the original workflow duration would silently discard a
                # previously recorded extension on the next resume.
                wall_remaining = self.deadline_epoch - time.time()
                self.deadline = self.clock() + wall_remaining
        self._reconcile_repair_panel_invoices()
        self._settle_pending_stage_usage()
        if self.status in {"completed", "candidate_needs_review", "research_expansion_required", "review_rejected",
                           "blocked", "paused"}:
            # A resumed workflow must explicitly continue from a non-terminal
            # checkpoint; completed output remains inspectable and immutable.
            self.status = "running"

    def _restore_context_from_stage_records(self):
        """Rehydrate completed stage packets when resuming an older checkpoint.

        Early Composer checkpoints persisted stage records but not the in-memory
        context.  A resume must still be able to bind accepted survey,
        experiment, interpretation, and argument outputs without replaying
        expensive upstream work or admitting a consumer against no packet.
        New checkpoints carry ``context`` directly; this reconstruction is a
        compatibility path for those already on disk.
        """
        by_id = {stage["id"]: stage for stage in self.workflow["stages"]}
        for stage_id, record in self.stage_records.items():
            if stage_id in self.context or not isinstance(record, dict):
                continue
            stage = by_id.get(stage_id)
            if stage is None:
                continue
            candidates = [record.get("output_path")]
            project_dir = record.get("project_dir") or stage.get("project_dir")
            if isinstance(project_dir, str):
                candidates.append(str(Path(project_dir) / "output" / "run.json"))
            output_path = next((Path(item) for item in candidates
                                if isinstance(item, str) and Path(item).is_file()), None)
            if output_path is None:
                continue
            try:
                payload = json.loads(output_path.read_text())
            except (OSError, ValueError, TypeError):
                continue
            if not isinstance(payload, dict):
                continue
            context = {**payload, "stage_id": stage_id, "kind": stage["kind"],
                       "project_dir": str(Path(stage.get("project_dir", project_dir)).resolve()),
                       "output_path": str(output_path.resolve())}
            if stage["kind"] == "experiment":
                context["results_package"] = payload.get("results_package")
            if stage["kind"] == "interpretation" and "interpretation" not in context:
                provisional = payload.get("provisional_interpretation")
                if isinstance(provisional, dict):
                    context["interpretation"] = provisional
                    context["binding_output_path"] = payload.get(
                        "provisional_interpretation_path")
                else:
                    context["interpretation"] = payload
            if stage["kind"] == "argument":
                context["argument_package_path"] = str(output_path.resolve())
            if (stage["kind"] == "topic_discovery" and "research_program" not in context
                    and isinstance(context.get("candidates"), list)
                    and isinstance(context.get("selected_id"), str)):
                from scisaurus.runtime.research_program import build_research_program
                context["research_program"] = build_research_program(context)
            self.context[stage_id] = context

    def _hydrate_provisional_handoffs(self):
        """Restore typed incumbent inputs for forward-first checkpoints.

        Older provisional checkpoints persisted the Composer decision and the
        forward-progress path, but not the incumbent package needed by a
        downstream binding.  Hydrate that adapter from the immutable attempt
        ledger before dependency admission; never turn the provisional status
        into an accepted scientific result.
        """
        by_id = {stage["id"]: stage for stage in self.workflow.get("stages", [])
                 if isinstance(stage, dict) and isinstance(stage.get("id"), str)}
        for stage_id, record in self.stage_records.items():
            stage = by_id.get(stage_id)
            context = self.context.get(stage_id)
            if (stage is None or not isinstance(record, dict)
                    or not isinstance(context, dict)
                    or record.get("composer_decision") != "advance_with_findings"):
                continue
            prior_artifact = self._prior_stage_artifact(
                stage, record.get("attempts", []))
            if stage.get("kind") == "interpretation" and prior_artifact is not None:
                package = self._interpretation_package_from_artifact(prior_artifact)
                if package is not None and not isinstance(context.get("interpretation"), dict):
                    context["interpretation"] = package
                    context["binding_output_path"] = prior_artifact["path"]
                    context["incumbent_interpretation_path"] = prior_artifact["path"]
            elif stage.get("kind") == "argument" and prior_artifact is not None:
                context.setdefault("binding_output_path", prior_artifact["path"])
                context.setdefault("incumbent_argument_path", prior_artifact["path"])
            self.context[stage_id] = context

            # SurveyRunner records the useful survey packet before a late
            # gap-assessment failure.  Older Composer checkpoints retained
            # only the forward-progress projection, which dropped the
            # survey/assessment refs and made the next experiment look like a
            # missing-input failure.  Rehydrate only the typed handoff fields
            # from the newest immutable attempt result; this does not turn the
            # failed survey into an accepted stage.
            if stage.get("kind") != "survey":
                continue
            needs_handoff = any(
                context.get(key) in (None, "")
                for key in ("project_dir", "survey_ref", "assessment_ref", "nomination_ref")
            )
            if not needs_handoff:
                continue
            payload = None
            payload_project = None
            attempts = record.get("attempts", [])
            for attempt in reversed(attempts if isinstance(attempts, list) else []):
                if not isinstance(attempt, dict):
                    continue
                project_dir = attempt.get("project_dir")
                if not isinstance(project_dir, str):
                    continue
                root = Path(project_dir)
                candidates = [root / "output" / "run.json"]
                if root.name.startswith("attempt-"):
                    candidates.append(root.parent.parent / "output" / "run.json")
                for candidate_path in candidates:
                    if not candidate_path.is_file():
                        continue
                    try:
                        candidate_payload = json.loads(candidate_path.read_text())
                    except (OSError, TypeError, ValueError):
                        continue
                    if isinstance(candidate_payload, dict):
                        payload = candidate_payload
                        payload_project = root
                        break
                if payload is not None:
                    break
            if not isinstance(payload, dict):
                continue
            for key in (
                    "survey_ref", "assessment_ref", "nomination_ref", "survey_current",
                    "assessment_current", "gap_state", "topic_admission"):
                if key in payload and context.get(key) in (None, ""):
                    context[key] = deepcopy(payload[key])
            if context.get("project_dir") in (None, "") and payload_project is not None:
                context["project_dir"] = str(payload_project.resolve())
            context["handoff_rehydrated_from_failed_attempt"] = True
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "hydrate_failed_survey_handoff",
                "stage_id": stage_id,
                "project_dir": context.get("project_dir"),
                "survey_ref": context.get("survey_ref"),
                "assessment_ref": context.get("assessment_ref"),
                "assessment_current": context.get("assessment_current"),
            })
            self.context[stage_id] = context

    def _reconcile_stale_forward_handoffs(self, by_id):
        """Reopen legacy provisional nodes that were released without input.

        Older forward-first checkpoints could mark a stage as dependency-ready
        immediately after issuing a scientific repair order. On resume that
        record looked like an ordinary ``advance_with_findings`` candidate, so
        the scheduler admitted a consumer even when the experiment had never
        produced a result. Reconstruct the typed repair order from the durable
        recovery ledger before dependency admission and put the node back
        behind its owning stage.
        """
        reconciled = []
        for stage_id, record in self.stage_records.items():
            stage = by_id.get(stage_id)
            context = self.context.get(stage_id)
            if (not isinstance(stage, dict) or not isinstance(record, dict)
                    or not isinstance(context, dict)
                    or record.get("composer_decision") != "advance_with_findings"):
                continue
            recovery = context.get("failure_recovery")
            recovery = recovery if isinstance(recovery, dict) else {}
            error_text = str(context.get("error") or "")
            legacy_author_contract = (
                stage.get("kind") == "experiment"
                and context.get("results_status") == "not_executed"
                and "program author did not finish normally" in error_text.casefold()
            )
            legacy_program_failure = (
                stage.get("kind") == "experiment"
                and context.get("results_status") == "not_executed"
                and not legacy_author_contract
                and recovery.get("failure_class") == "model_contract"
                and classify_failure(
                    stage.get("kind"), context.get("error"), context
                ) == "experiment_failure"
            )
            actionable_recovery = (
                recovery.get("recovery_mode") in {
                    "repair_then_rerun", "format_repair_then_rerun",
                }
                and (
                    isinstance(context.get("failure_dossier_ref"), str)
                    or isinstance(recovery.get("dossier_ref"), str)
                    or isinstance(context.get("repair_commands"), list)
                )
            )
            unexecuted_experiment = (
                stage.get("kind") == "experiment"
                and context.get("results_status") == "not_executed"
            )
            existing_requests = [
                item for key in ("research_expansion_requests", "research_requests")
                for item in (context.get(key) if isinstance(context.get(key), list) else [])
                if isinstance(item, dict)
            ]
            if not actionable_recovery and not unexecuted_experiment and not existing_requests:
                continue

            requests = list(existing_requests)
            if legacy_author_contract:
                # Older checkpoints recorded the model author's truncated
                # response as a scientific program failure.  Repair only the
                # response contract on resume; do not open a Methods code
                # repair order for a program that never existed.
                format_commands = build_repair_commands(
                    "experiment", "model_contract", error_text=error_text)
                recovery = deepcopy(recovery)
                recovery.update({
                    "failure_class": "model_contract",
                    "recovery_mode": "format_repair_then_rerun",
                    "requires_capability_repair": False,
                    "repair_commands": deepcopy(format_commands),
                    "acceptance_checks": [
                        item.get("acceptance_check") for item in format_commands
                        if isinstance(item, dict) and item.get("acceptance_check")
                    ],
                })
                context["failure_recovery"] = recovery
                context["format_recovery"] = True
                context["review_status"] = "model_contract_repair"
                context["repair_commands"] = deepcopy(format_commands)
                context["acceptance_checks"] = deepcopy(recovery["acceptance_checks"])
                request = self._format_contract_recovery_request(stage, context)
                requests = [request] if isinstance(request, dict) else []
            elif legacy_program_failure:
                # Migrate checkpoints written before program-author failures
                # were distinguished from malformed provider envelopes.  The
                # old packet may contain a schema-only order, but an
                # unexecuted generated program needs a Methods repair order so
                # the next attempt edits the executable source and replays it.
                error_text = context.get("error") or "legacy experiment program failure"
                commands = build_repair_commands(
                    "experiment", "experiment_failure",
                    stage_result=context,
                    error_text=error_text,
                    review_directives=(context.get("review_directives")
                                       if isinstance(context.get("review_directives"), list)
                                       else recovery.get("review_directives", [])),
                )
                dossier = {
                    "stage_kind": "experiment",
                    "failure_class": "experiment_failure",
                    "error": error_text,
                    "input_sha256": recovery.get("input_sha256")
                    or context.get("failure_input_sha256") or "",
                    "repair_commands": commands,
                    "acceptance_checks": [
                        item.get("acceptance_check") for item in commands
                        if isinstance(item, dict) and item.get("acceptance_check")
                    ],
                    "review_directives": deepcopy(
                        context.get("review_directives")
                        if isinstance(context.get("review_directives"), list)
                        else recovery.get("review_directives", [])
                    ),
                }
                request = build_repair_request(dossier, stage_id=stage_id)
                request["failure_dossier_ref"] = (
                    context.get("failure_dossier_ref")
                    or recovery.get("dossier_ref"))
                requests = [request]
                recovery = deepcopy(recovery)
                recovery.update({
                    "failure_class": "experiment_failure",
                    "recovery_mode": "repair_then_rerun",
                    "requires_capability_repair": True,
                    "repair_commands": deepcopy(commands),
                    "acceptance_checks": deepcopy(dossier["acceptance_checks"]),
                })
                context["failure_recovery"] = recovery
                context["format_recovery"] = False
                context["review_status"] = "scientific_assignment_blocked"
            if not requests:
                if recovery.get("recovery_mode") == "format_repair_then_rerun":
                    request = self._format_contract_recovery_request(stage, context)
                    if isinstance(request, dict):
                        requests = [request]
                elif actionable_recovery:
                    dossier = {
                        "stage_kind": stage.get("kind"),
                        "failure_class": recovery.get("failure_class") or "scientific_hold",
                        "error": context.get("error") or "stale provisional handoff",
                        "input_sha256": recovery.get("input_sha256")
                        or context.get("failure_input_sha256", ""),
                        "repair_commands": context.get("repair_commands")
                        or recovery.get("repair_commands", []),
                        "acceptance_checks": context.get("acceptance_checks")
                        or recovery.get("acceptance_checks", []),
                        "review_directives": context.get("review_directives")
                        or recovery.get("review_directives", []),
                    }
                    request = build_repair_request(dossier, stage_id=stage_id)
                    request["failure_dossier_ref"] = (
                        context.get("failure_dossier_ref")
                        or recovery.get("dossier_ref"))
                    requests = [request]
                else:
                    debt = context.get("failure_debt")
                    if not isinstance(debt, dict):
                        debt = {
                            "stage_id": stage_id,
                            "kind": stage.get("kind"),
                            "failure_class": "scientific_hold",
                            "error": context.get("error") or "experiment produced no result",
                            "attempts": record.get("attempt_count", 0),
                        }
                    request = self._forward_debt_work_order(stage_id, debt)
                    if isinstance(request, dict):
                        requests = [request]
            if not requests:
                # A malformed legacy packet must not be released merely because
                # it carries the old Composer decision. Leave it visible for
                # the normal terminal recovery path instead.
                continue

            deduplicated_requests = {}
            for request in requests:
                if isinstance(request.get("id"), str):
                    deduplicated_requests[request["id"]] = request
            requests = list(deduplicated_requests.values())
            context.update({
                "status": "research_expansion_required",
                "review_status": "scientific_assignment_blocked",
                "composer_decision": "repair_required",
                "progression_state": "repair_required",
                "release_blocking": True,
                "research_requests": deepcopy(requests),
                "research_expansion_requests": [],
                "deferred_research_requests": [],
                "preserve_work_orders": True,
                "stale_forward_handoff_reconciled": True,
            })
            record.update({
                "status": "retrying",
                "composer_decision": "repair_required",
                "progression_state": "repair_required",
                "release_blocking": True,
                "results_status": context.get("results_status"),
                "recovery_admitted": True,
            })
            self.context[stage_id] = context
            self.stage_records[stage_id] = record
            self.continuation_pending_stage_ids.add(stage_id)
            reconciled.append({
                "stage_id": stage_id,
                "kind": stage.get("kind"),
                "request_ids": [item.get("id") for item in requests
                                 if isinstance(item.get("id"), str)],
                "reason": "legacy forward-first handoff had an actionable repair order or no experiment result",
            })
        if reconciled:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "reconcile_stale_forward_handoffs",
                "stages": reconciled,
                "next_action": "execute the owning repair order before admitting downstream inputs",
            })
        return reconciled

    def _restored_topic_feasibility_failure(self, by_id):
        """Recheck a completed topic against the current execution boundary.

        A checkpoint can outlive the code that produced it. If a newer
        Composer adds a required feasibility contract, letting an older topic
        flow directly into survey or experiment would bypass the new gate.
        Missing empirical rows are handled as source acquisition downstream,
        not converted into a topic-feasibility rejection here.
        """
        if not any(stage.get("kind") == "experiment"
                   for stage in self.workflow.get("stages", [])):
            return None
        topic_stage = next(
            (stage for stage in self.workflow.get("stages", [])
             if stage.get("kind") == "topic_discovery"), None)
        if not isinstance(topic_stage, dict):
            return None
        record = self.stage_records.get(topic_stage.get("id"), {})
        if not isinstance(record, dict) or record.get("status") not in STAGE_READY_STATUSES:
            return None
        topic_context = self.context.get(topic_stage.get("id"))
        if not isinstance(topic_context, dict):
            return (topic_stage["id"],
                    "completed topic output is unavailable for current feasibility revalidation")
        try:
            from scisaurus.runtime.topic_discovery import (
                _materialize_foundry_capability_requirements,
                validate_topic_feasibility, validate_topic_stage_config,
            )
            descriptor = validate_topic_stage_config(
                json.loads(Path(topic_stage["config_path"]).read_text()))
            model = json.loads(Path(descriptor["model_config_path"]).read_text())
            runtime_context = self._runtime_context(model)
            package = _materialize_foundry_capability_requirements(
                deepcopy(topic_context), runtime_context)
            feasibility = validate_topic_feasibility(package, runtime_context)
            if (feasibility.get("status") == "legacy_unchecked"
                    and topic_context.get("admission_state") != "provisional_for_survey"):
                return (topic_stage["id"],
                        "completed topic output has no current capability admission record")
        except (KeyError, OSError, StopIteration, TypeError, ValueError, ValidationError) as exc:
            return topic_stage["id"], str(exc)
        return None

    def _queue_topic_feasibility_revalidation(self, stage_id, reason):
        """Repair a legacy execution plan without reopening the research question."""
        context = self.context.get(stage_id)
        if not isinstance(context, dict):
            context = {"kind": "topic_discovery", "status": "invalidated"}
        requests = context.get("research_requests")
        if not isinstance(requests, list):
            requests = []
        request_id = "topic-runtime-feasibility-revalidation"
        if not any(isinstance(item, dict) and item.get("id") == request_id
                   for item in requests):
            requests.append({
                "id": request_id,
                "kind": "topic_refinement",
                "owner": "research.intelligence",
                "objective": (
                    "Repair the selected study's machine-readable execution-feasibility plan while "
                    "preserving its admitted research question and scientific identity exactly."),
                "why": (
                    "The checkpoint lacks a current execution-feasibility record; that is an "
                    "admission-metadata gap, not evidence against the research question."),
                "success_condition": (
                    "The same topic identity and research question pass current runtime feasibility "
                    "checks with only feasibility, resource, or executable-capability fields repaired."),
                "evidence_needed": (
                    "The retained topic and research question; current runtime inventory; experiment "
                    "boundary; declared input availability; required packages and executables; provider, "
                    "model, and compute limits. Do not change the scientific question."),
                "recovery_mode": "runtime_feasibility_revalidation_same_question",
            })
        context["research_requests"] = requests
        context["runtime_feasibility_revalidation"] = {
            "status": "required", "reason": str(reason)[:2048],
        }
        context["status"] = "research_expansion_required"
        context["review_status"] = "runtime_feasibility_revalidation"
        self.context[stage_id] = context

    def _reconcile_interrupted_attempt(self, attempt_id):
        """Close an attempt left running before a process interruption.

        The stage record is only a summary.  The task ledger is authoritative
        about whether an external call is still started, already unknown, or
        has a settled outcome, so resumption reconciles that ledger before a
        fresh attempt is admitted.
        """
        try:
            attempt = self.tasks.get_attempt(attempt_id)
        except NotFoundError:
            # Older checkpoints may predate task-attempt persistence.
            return
        state = attempt.get("state")
        if state == "started":
            self.tasks.reconcile_unknown(attempt_id, "command.composer")
            return
        if state in {"result_unknown", "failed", "succeeded", "cancelled"}:
            return
        raise StateError(f"interrupted Composer attempt has unsupported state: {state}")

    def _reconcile_interrupted_stage_attempts(self):
        """Retire aggregate stage leases left live by an exited Composer.

        The stage runtime owns provider-call accounting and resumable outputs.
        The outer Composer attempt records only whether the aggregate result
        was observed; an unobserved result stays ``unknown`` and is retried
        under a new task identity while nested ledgers settle their own calls.
        """
        workspace_costs = self._reconcile_producer_workspace_costs()
        reconciled = []
        for stage_id, record in list(self.stage_records.items()):
            if (not isinstance(record, dict)
                    or record.get("status") not in {"running", "retrying"}
                    or not isinstance(record.get("attempt_id"), str)):
                continue
            attempt_id = record["attempt_id"]
            task_id = record.get("task_id")
            stage = next(item for item in self.workflow["stages"] if item["id"] == stage_id)
            if stage.get("kind") == "survey":
                scopes = self._survey_revalidation_scopes(stage)
                if scopes:
                    _, milestone = self._survey_revalidation_resume_plan(
                        {**stage, "project_dir": record.get("project_dir", stage["project_dir"])}, scopes)
                    if milestone is not None:
                        record["completed_mapping"] = milestone
            self._reconcile_interrupted_specialist_payments(stage, record)
            self._reconcile_interrupted_attempt(attempt_id)
            history = self._archive_stage_attempt(
                record,
                attempts=record.get("attempts", []),
                cycle=self.continuation_cycles,
                error=("Composer resumed without observing the aggregate stage result; "
                       "nested request ledgers retain their own outcomes."),
            )
            record["attempts"] = history
            record["last_attempt_id"] = attempt_id
            record.pop("attempt_id", None)
            if isinstance(task_id, str):
                record["last_task_id"] = task_id
                record.pop("task_id", None)
            record["status"] = "retrying"
            self.stage_records[stage_id] = self._retire_stage_assignment(record)
            try:
                outcome = self.tasks.get_attempt(attempt_id).get("state")
            except NotFoundError:
                outcome = "missing"
            reconciled.append({
                "stage_id": stage_id,
                "task_id": task_id,
                "attempt_id": attempt_id,
                "outcome": outcome,
                "next_action": "dispatch a fresh aggregate task while preserving nested run checkpoints",
            })
        if workspace_costs:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "settle_retained_producer_workspace_costs",
                "workspaces": workspace_costs,
            })
        if reconciled:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "reconcile_interrupted_stage_attempts",
                "attempts": reconciled,
                "model_calls": 0,
            })
            self._checkpoint("resume:reconcile_interrupted_stage_attempts", force=True)
        elif workspace_costs:
            self._checkpoint("resume:settle_producer_workspace_costs", force=True)
        return reconciled

    @staticmethod
    def _producer_checkpoint_evidence(project, snapshot):
        run_id, number = snapshot.get("run_id"), snapshot.get("checkpoint")
        if not isinstance(run_id, str) or type(number) is not int or number <= 0:
            return None
        try:
            with closing(sqlite3.connect((Path(project) / "state/control.sqlite").resolve().as_uri()
                                         + "?mode=ro", uri=True, timeout=2.0)) as connection:
                connection.row_factory = sqlite3.Row
                connection.execute("PRAGMA query_only=ON")
                store = ArtifactStore(SimpleNamespace(dir=str(Path(project).resolve()), _conn=connection))
                record = store.head(f"command/progress/{run_id}-{number}")
                if record is None:
                    return None
                raw = store.read_body(record["body_hash"])
                body = json.loads(raw)
                actual = body.get("cumulative_usage", {}).get("actual")
                if (record.get("author") != "command.controller" or record.get("artifact_type") != "progress_checkpoint"
                        or hashlib.sha256(raw).hexdigest() != record["body_hash"]
                        or actual != snapshot.get("cumulative_usage")
                        or body.get("next_action", {}).get("decision") != snapshot.get("phase")):
                    return None
                return {"ref": record["artifact_ref"], "body_sha256": record["body_hash"],
                        "created_at": record["created_at"], "run_id": run_id, "actual_usage": actual}
        except (sqlite3.Error, OSError, KeyError, TypeError, ValueError, NotFoundError):
            return None

    def _survey_revalidation_resume_plan(self, stage, declared_scopes):
        proof = None
        record = self.stage_records.get(stage["id"], {})
        retained_mapping = record.get("completed_mapping")
        observed = record.get("child_progress") or {}
        if isinstance(retained_mapping, dict):
            original = retained_mapping.get("producer_checkpoint") or {}
            try:
                with closing(sqlite3.connect((Path(stage["project_dir"]) / "state/control.sqlite").resolve().as_uri()
                                             + "?mode=ro", uri=True, timeout=2.0)) as connection:
                    connection.row_factory = sqlite3.Row
                    connection.execute("PRAGMA query_only=ON")
                    store = ArtifactStore(SimpleNamespace(dir=str(Path(stage["project_dir"]).resolve()), _conn=connection))
                    saved = store.get(original["ref"])
                    raw = store.read_body(saved["body_hash"])
                    match = re.fullmatch(r"artifact:command/progress/" + re.escape(original["run_id"]) + r"-([1-9][0-9]*)@[1-9][0-9]*", original["ref"])
                    if saved["body_hash"] != original["body_sha256"] or hashlib.sha256(raw).hexdigest() != saved["body_hash"] or match is None:
                        raise ValueError("retained mapping checkpoint is not exact")
                    value = json.loads(raw)
                    observed = {"run_id": original["run_id"], "checkpoint": int(match.group(1)),
                                "phase": value["next_action"]["decision"],
                                "cumulative_usage": value["cumulative_usage"]["actual"]}
            except (sqlite3.Error, NotFoundError, KeyError, TypeError, ValueError, OSError):
                return declared_scopes, None
        expected_run_id = observed.get("run_id") or (record.get("producer_checkpoint") or {}).get("run_id")
        if type(observed.get("checkpoint")) is not int and isinstance(expected_run_id, str):
            captured = self._read_json_object(Path(stage["project_dir"]) / "output/progress.json") or {}
            observed = captured if captured.get("run_id") == expected_run_id else {}
        if "mapping" not in declared_scopes or len(declared_scopes) < 2 or not observed:
            return declared_scopes, proof
        evidence = self._producer_checkpoint_evidence(stage["project_dir"], observed)
        if evidence is None:
            return declared_scopes, proof
        attempt_id = (retained_mapping.get("aggregate_attempt_id") if isinstance(retained_mapping, dict)
                      else record.get("attempt_id") or record.get("last_attempt_id"))
        try:
            attempt = self.tasks.get_attempt(attempt_id)
            payload = attempt.get("payload") or {}
            with closing(sqlite3.connect((Path(stage["project_dir"]) / "state/control.sqlite").resolve().as_uri()
                                         + "?mode=ro", uri=True, timeout=2.0)) as connection:
                connection.row_factory = sqlite3.Row
                connection.execute("PRAGMA query_only=ON")
                store = ArtifactStore(SimpleNamespace(dir=str(Path(stage["project_dir"]).resolve()), _conn=connection))
                config = store.head("inputs/run-config")
                row = connection.execute("SELECT artifact_ref FROM artifacts WHERE logical_id LIKE 'command/resume-sessions/%' "
                                         "AND created_at <= ? ORDER BY created_at DESC, rowid DESC LIMIT 1",
                                         (evidence["created_at"],)).fetchone()
                session = (store.get(retained_mapping["resume_ref"]) if isinstance(retained_mapping, dict)
                           else store.get(row["artifact_ref"]) if row else None)
                mapping = (store.get(retained_mapping["map_ref"]) if isinstance(retained_mapping, dict)
                           else store.head("kb/literature-map"))
                if isinstance(retained_mapping, dict) and (
                        config is None or session is None or mapping is None
                        or retained_mapping.get("config_ref") != config["artifact_ref"]
                        or retained_mapping.get("config_sha256") != config["body_hash"]
                        or retained_mapping.get("map_sha256") != mapping["body_hash"]
                        or retained_mapping.get("resume_sha256") != session["body_hash"]):
                    return declared_scopes, None
                owner_cycle = self._survey_mapping_owner_cycle(stage, retained_mapping) if isinstance(retained_mapping, dict) else self.continuation_cycles
                if (payload.get("stage_id") != stage["id"] or payload.get("model_budget_cycle") != owner_cycle
                        or payload.get("project_dir") != str(Path(stage["project_dir"]).resolve())
                        or config is None or session is None or mapping is None
                        or not attempt["created_at"] <= session["created_at"] <= mapping["created_at"] <= evidence["created_at"]
                        or mapping.get("author") != "research.literature-mapper"):
                    return declared_scopes, proof
                def body(item):
                    raw = store.read_body(item["body_hash"])
                    if hashlib.sha256(raw).hexdigest() != item["body_hash"]:
                        raise ValueError("milestone body hash mismatch")
                    return json.loads(raw)
                resumed, mapped, configured = body(session), body(mapping), body(config)
                if (resumed.get("config_ref") != config["artifact_ref"] or "mapping" not in resumed.get("reopened_scopes", [])
                        or mapped.get("question") != configured.get("survey", {}).get("question")
                        or not isinstance(mapped.get("entry_refs"), list) or not mapped["entry_refs"]):
                    return declared_scopes, proof
                for ref in [*mapped["entry_refs"], *mapped.get("relationship_refs", [])]:
                    item = store.get(ref)
                    body(item)
                proof = {"phase": "mapping", "map_ref": mapping["artifact_ref"], "map_sha256": mapping["body_hash"],
                         "resume_ref": session["artifact_ref"], "resume_sha256": session["body_hash"],
                         "config_ref": config["artifact_ref"], "config_sha256": config["body_hash"],
                         "producer_checkpoint": evidence, "aggregate_attempt_id": attempt_id}
                remaining = [scope for scope in declared_scopes if scope != "mapping"]
                recovery = self._survey_revalidation_recovery(stage)
                if recovery is not None and "dependency_replay" in recovery:
                    remaining = recovery["dependency_replay"]["resume_scopes"]
                return remaining, proof
        except (sqlite3.Error, NotFoundError, KeyError, TypeError, ValueError, OSError):
            return declared_scopes, proof

    def _reconcile_producer_workspace_costs(self):
        """Settle observed child costs before choosing another retained frontier."""
        reconciled, seen = [], set()
        for stage in self.workflow.get("stages", []):
            if stage.get("kind") not in {"survey", "experiment"}:
                continue
            record = self.stage_records.get(stage["id"], {})
            candidates = [record, *record.get("attempts", [])] if isinstance(record, dict) else []
            for candidate in candidates:
                if not isinstance(candidate, dict) or not isinstance(candidate.get("project_dir"), str):
                    continue
                project = Path(candidate["project_dir"]).resolve()
                if project in seen:
                    continue
                seen.add(project)
                totals = {}
                for filename in ("run.json", "progress.json"):
                    snapshot = self._read_json_object(project / "output" / filename)
                    if not isinstance(snapshot, dict):
                        continue
                    if filename == "progress.json":
                        evidence = self._producer_checkpoint_evidence(project, snapshot)
                        if evidence is None:
                            continue
                        usage = evidence["actual_usage"]
                        if candidate is record:
                            record["producer_checkpoint"] = evidence
                    else:
                        usage = (snapshot.get("usage") or {}).get("cumulative_usage")
                    if not isinstance(usage, dict):
                        continue
                    for key, amount in usage.items():
                        if type(amount) in (int, float) and math.isfinite(amount) and amount >= 0:
                            totals[key] = max(totals.get(key, 0), amount)
                if not totals:
                    continue
                _, baseline = self._stage_usage_baseline(project)
                if not any(totals.get(key, 0) > baseline.get(key, 0) for key in self.usage):
                    continue
                delta = self._incremental_stage_usage(
                    {"id": stage["id"], "project_dir": str(project)}, {"cumulative_usage": totals})
                self._settle_pending_stage_usage(stage["id"])
                reconciled.append({"stage_id": stage["id"], "project_dir": str(project),
                                   "observed_totals": totals, "settled_delta": delta})
        return reconciled

    def _reconcile_orphaned_duplicate_stage_attempts(self):
        """Settle expired aggregate attempts only when an identical durable run succeeded."""
        rows = self.control._conn.execute(
            "SELECT a.attempt_id, a.task_id, a.lease_expiry, a.external_ref, "
            "a.usage_json, a.payload_json, t.state AS task_state "
            "FROM attempts a JOIN tasks t USING(task_id) "
            "WHERE a.state='started' AND t.state='completed'"
        ).fetchall()
        stages = {
            item.get("id"): item for item in self.workflow.get("stages", [])
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        }
        reconciled = []
        for row in rows:
            if (row["external_ref"] is not None
                    or not isinstance(row["lease_expiry"], (int, float))
                    or row["lease_expiry"] > time.time()):
                continue
            try:
                payload = json.loads(row["payload_json"])
                usage = json.loads(row["usage_json"])
            except (TypeError, ValueError):
                continue
            if (not isinstance(payload, dict)
                    or payload.get("assignment_id")
                    or payload.get("assignment_logical_id")):
                continue
            stage = stages.get(payload.get("stage_id"))
            if (not isinstance(stage, dict)
                    or stage.get("kind") not in {"survey", "experiment"}
                    or payload.get("kind") != stage.get("kind")
                    or not isinstance(payload.get("project_dir"), str)):
                continue
            reserved = usage.get("reserved") if isinstance(usage, dict) else None
            if reserved not in (None, {}):
                continue
            try:
                project_dir = Path(payload["project_dir"]).resolve()
                project_dir.relative_to(Path(stage["project_dir"]).resolve())
                report_path = project_dir / "output" / "run.json"
                report = json.loads(report_path.read_text())
            except (OSError, TypeError, ValueError):
                continue
            if not isinstance(report, dict) or report.get("status") not in {"completed", "accepted"}:
                continue
            sibling = self.control._conn.execute(
                "SELECT attempt_id FROM attempts WHERE task_id=? AND state='succeeded' "
                "AND payload_json=? LIMIT 1",
                (row["task_id"], row["payload_json"]),
            ).fetchone()
            if sibling is None:
                continue
            accounting = "superseded_by_identical_durable_success"
            try:
                self.tasks.finish_attempt(
                    row["attempt_id"], "cancelled", accounting=accounting)
            except (NotFoundError, StateError):
                continue
            reconciled.append({
                "attempt_id": row["attempt_id"],
                "task_id": row["task_id"],
                "stage_id": stage["id"],
                "superseded_by_attempt_id": sibling["attempt_id"],
                "accounting": accounting,
            })
        return reconciled

    def _archive_stage_attempt(self, record, *, attempts=None, cycle=None,
                               default_project_dir=None, error=None):
        """Archive one live stage attempt from its authoritative task-ledger outcome.

        The checkpoint projection can lag the task ledger at either a process
        resume or a scientific continuation boundary.  Both paths use this
        routine so attempt numbering and known usage cannot diverge.
        """
        history = deepcopy(attempts if isinstance(attempts, list)
                           else record.get("attempts", []))
        if not isinstance(history, list):
            history = []
        attempt_id = record.get("attempt_id")
        if not isinstance(attempt_id, str) or not attempt_id:
            record["attempts"] = history
            return history

        try:
            prior_attempt = self.tasks.get_attempt(attempt_id)
        except NotFoundError:
            prior_attempt = None
        if isinstance(prior_attempt, dict) and prior_attempt.get("state") == "started":
            self._reconcile_interrupted_attempt(attempt_id)
            try:
                prior_attempt = self.tasks.get_attempt(attempt_id)
            except NotFoundError:
                prior_attempt = None

        outcome = prior_attempt.get("state") if isinstance(prior_attempt, dict) else None
        archived_state = {
            "succeeded": "succeeded",
            "failed": "failed",
            "cancelled": "failed",
            "result_unknown": "unknown",
            "started": "unknown",
        }.get(outcome, "unknown")
        usage = None
        if isinstance(prior_attempt, dict):
            usage_record = prior_attempt.get("usage")
            if isinstance(usage_record, dict) and isinstance(usage_record.get("actual"), dict):
                usage = deepcopy(usage_record["actual"])

        attempt_number = record.get("attempt_number")
        if type(attempt_number) is not int or attempt_number < 1:
            attempt_number = len(history) + 1
        existing = next((item for item in history
                         if isinstance(item, dict)
                         and item.get("attempt_id") == attempt_id), None)
        if existing is None:
            archived = {
                "attempt_number": attempt_number,
                "attempt_id": attempt_id,
                "cycle": self.continuation_cycles if cycle is None else cycle,
                "state": archived_state,
                "project_dir": record.get("project_dir", default_project_dir),
                **({"topic_id": record["topic_id"]}
                   if isinstance(record.get("topic_id"), str) else {}),
                **({"topic_cycle": record["topic_cycle"]}
                   if type(record.get("topic_cycle")) is int else {}),
            }
            if usage is not None:
                archived["usage"] = usage
            elif archived_state == "unknown":
                archived["error"] = error or (
                    "The stage attempt ended without a durable result."
                )
            history.append(archived)
        elif existing.get("state") == "unknown" and archived_state != "unknown":
            existing["state"] = archived_state
            existing.pop("error", None)
            if usage is not None:
                existing["usage"] = usage

        record["attempts"] = history
        prior_count = record.get("attempt_count")
        if type(prior_count) is not int or prior_count < 0:
            prior_count = 0
        record["attempt_count"] = max(prior_count, attempt_number, len(history))
        return history

    def _source_value(self, expression):
        parts = expression.split(".")
        if len(parts) < 2 or parts[0] not in self.context:
            raise ValidationError(f"binding source must name a completed stage: {expression}")
        context = self.context[parts[0]]
        path = ".".join(parts[1:])
        # A provisional stage keeps its forward-progress report as the public
        # output while exposing the last successful immutable artifact for a
        # downstream packet that needs a typed file path.  The debt and status
        # remain in the context, so this is a handoff adapter, not an approval.
        if path == "output_path" and isinstance(context, dict):
            binding_path = context.get("binding_output_path")
            if isinstance(binding_path, str) and binding_path:
                return binding_path
        return _get_path(context, path)

    @staticmethod
    def _walk_provider_descriptors(value):
        """Yield provider configuration fragments without exposing secrets."""
        if isinstance(value, dict):
            if isinstance(value.get("auth_env"), str) and value["auth_env"].strip():
                yield value
            for item in value.values():
                yield from ComposerRunner._walk_provider_descriptors(item)
        elif isinstance(value, list):
            for item in value:
                yield from ComposerRunner._walk_provider_descriptors(item)

    def _stage_provider_configuration_error(self, stage):
        """Preflight required credentials before specialists or models start."""
        try:
            descriptor = json.loads(Path(stage["config_path"]).read_text())
        except (OSError, ValueError, TypeError) as exc:
            return ProviderConfigurationError(
                f"stage {stage.get('id')} provider descriptor is unreadable: {exc}")
        for fragment in self._walk_provider_descriptors(descriptor):
            env_name = fragment["auth_env"]
            value = os.environ.get(env_name)
            if isinstance(value, str) and value and all(33 <= ord(char) <= 126 for char in value):
                continue
            endpoint = str(fragment.get("endpoint") or fragment.get("base_url") or "")
            provider = "openalex" if "openalex" in endpoint.casefold() else "model"
            return ProviderConfigurationError(
                f"stage {stage.get('id')} requires configured {provider} credential "
                f"{env_name}; load the owner-local runtime environment before dispatch",
                provider=provider, credential_env=env_name,
            )
        return None

    def _survey_provider_cooldown(self, stage, descriptor):
        """Read the shared OpenAlex fence before activating survey specialists.

        Survey specialists are useful only when the survey can admit a
        bibliographic route. Previously they were dispatched first, and the
        SurveyRunner discovered the same persistent OpenAlex fence afterward;
        every retry therefore spent specialist calls without adding evidence.
        This check is local and does not make an HTTP request.
        """
        if not isinstance(stage, dict) or stage.get("kind") != "survey":
            return None
        stage_context = self.context.get(stage.get("id"), {})
        if (isinstance(stage_context, dict)
                and isinstance(stage_context.get("provider_fallback"), dict)
                and stage_context["provider_fallback"].get("mode") == "crossref_metadata"):
            return None
        survey = descriptor.get("survey") if isinstance(descriptor, dict) else None
        bibliography = survey.get("bibliography") if isinstance(survey, dict) else None
        if (not isinstance(bibliography, dict)
                or bibliography.get("adapter") != "openalex"):
            return None
        client = bibliography.get("client")
        if not isinstance(client, dict):
            return None
        fields = {
            "timeout", "max_bytes", "endpoint", "auth_env", "max_retries",
            "retry_backoff_seconds", "min_interval_seconds", "rate_state_path",
            "allow_anonymous_fallback",
        }
        client_config = {key: deepcopy(value) for key, value in client.items()
                         if key in fields}
        preflight_client = OpenAlexClient(**client_config)
        representative = bibliography.get("representative")
        representative = representative if isinstance(representative, dict) else {}
        cooldown = preflight_client.preflight(
            operation=representative.get("operation", "search"),
            query=representative.get("query"),
            work_id=representative.get("work_id"),
            limit=representative.get("limit", 1),
            cursor=representative.get("cursor"),
        )
        if not isinstance(cooldown, dict):
            return None
        rate_limit = deepcopy(cooldown.get("rate_limit") or {})
        delay = cooldown.get("retry_after_seconds")
        if type(delay) not in (int, float) or not math.isfinite(delay) or delay <= 0:
            return None
        return ProviderCooldownError(
            "OpenAlex survey retrieval is paused before specialist admission "
            "because the shared provider budget is exhausted",
            retry_after_seconds=delay,
            rate_limit=rate_limit,
        )

    def _stage_dependency_gaps(self, stage):
        """Return missing bound values before a downstream worker is admitted."""
        gaps = []
        for binding in stage.get("bindings", []):
            source = binding.get("source")
            target = binding.get("target")
            try:
                value = self._source_value(source)
            except ValidationError as exc:
                gaps.append({"source": source, "target": target, "reason": str(exc)})
                continue
            if value is None or (isinstance(value, str) and not value.strip()):
                gaps.append({
                    "source": source, "target": target,
                    "reason": "bound value is null or empty",
                })
                continue
            if (isinstance(value, str) and target.endswith("results_package")
                    and not Path(value).is_file()):
                gaps.append({
                    "source": source, "target": target,
                    "reason": f"bound artifact is unavailable: {value}",
                })
        return gaps

    def _admit_upstream_dependency_recovery(self, stage, gaps, completed, by_id):
        """Route an unresolved provisional handoff back to its owning stage.

        A forward-first candidate may be visible to the agenda while still
        lacking the artifact needed by its consumer.  That is a scientific
        repair condition, not a generic wiring error: the Composer must reopen
        the upstream scope (with a changed work order) before it considers the
        consumer.  Returning the upstream stage id lets the caller distinguish
        an explicit scientific hold from an actually malformed workflow.
        """
        if not self._forward_first() or not isinstance(stage, dict):
            return None
        for gap in gaps if isinstance(gaps, list) else []:
            source = gap.get("source") if isinstance(gap, dict) else None
            if not isinstance(source, str) or "." not in source:
                continue
            upstream_id = source.split(".", 1)[0]
            upstream = by_id.get(upstream_id)
            context = self.context.get(upstream_id)
            if (not isinstance(upstream, dict)
                    or upstream.get("kind") != "survey"
                    or not isinstance(context, dict)):
                continue
            if context.get("assessment_current") is True and context.get("assessment_ref"):
                continue
            context = deepcopy(context)
            context["status"] = "research_expansion_required"
            context["review_status"] = "survey_handoff_incomplete"
            context["error"] = (
                "survey produced a provisional packet without a current gap assessment; "
                "the downstream experiment must wait for the scoped literature repair"
            )
            context["handoff_repair_required"] = True
            requests = context.get("research_requests")
            if not isinstance(requests, list):
                requests = []
            if not any(isinstance(item, dict) for item in requests):
                deferred = context.get("deferred_research_requests")
                if isinstance(deferred, list):
                    requests.extend(deepcopy(item) for item in deferred
                                    if isinstance(item, dict))
            if not any(isinstance(item, dict) for item in requests):
                request = self._autonomous_recovery_request(upstream_id, context)
                if isinstance(request, dict):
                    requests.append(request)
            context["research_requests"] = requests
            self.context[upstream_id] = context
            admitted = self._begin_continuation(completed, by_id)
            if admitted:
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "recover_upstream_dependency",
                    "upstream_stage_id": upstream_id,
                    "consumer_stage_id": stage.get("id"),
                    "reason": "provisional survey lacks a current assessment_ref",
                })
            return upstream_id, admitted
        return None

    def _stage_usage(self, stage_id):
        """Aggregate the active quota scope for one stage.

        Ordinary stages have one aggregate envelope. A continuation is an
        explicitly admitted new scientific work order with its own bounded
        stage budget. Counting every historical attempt against the newest
        repair cycle makes a valid recovery stop before it can execute the
        scoped work. Keep the mission-wide usage ledger unchanged while
        scoping every reopened stage fence to the current continuation cycle.
        """
        record = self.stage_records.get(stage_id, {})
        attempts = record.get("attempts", []) if isinstance(record, dict) else []
        stage_kind = next(
            (item.get("kind") for item in self.workflow.get("stages", [])
             if isinstance(item, dict) and item.get("id") == stage_id),
            None,
        )
        active_cycle = self.continuation_cycles
        if stage_id in self.reopened_stage_ids and active_cycle:
            attempts = [
                item for item in attempts
                if isinstance(item, dict) and item.get("cycle") == active_cycle
            ]
        elif stage_kind == "topic_discovery":
            # Initial topic intake has no continuation cycle.  Preserve the
            # legacy checkpoint convention where the cycle field may be
            # omitted, while excluding any later pivot history.
            attempts = [
                item for item in attempts
                if isinstance(item, dict) and item.get("cycle", 0) in (None, 0)
            ]
        totals = {"model_calls": 0, "input_tokens": 0,
                  "output_tokens": 0, "openalex_requests": 0}
        observed = False
        for attempt in attempts if isinstance(attempts, list) else []:
            usage = attempt.get("usage") if isinstance(attempt, dict) else None
            if not isinstance(usage, dict):
                continue
            observed = True
            for key in totals:
                value = usage.get(key, 0)
                if type(value) in (int, float) and math.isfinite(value) and value >= 0:
                    totals[key] += value
        unfinished_projects = {
            item["project_dir"] for item in attempts if isinstance(item, dict)
            and not isinstance(item.get("usage"), dict)
            and isinstance(item.get("project_dir"), str)
        } if isinstance(attempts, list) else set()
        for project_dir in unfinished_projects:
            progress_path = Path(project_dir) / "output" / "progress.json"
            if not progress_path.is_file():
                continue
            child = json.loads(progress_path.read_text())
            quantities = child.get("cumulative_usage")
            if not isinstance(quantities, dict) or child.get("project_dir") != str(Path(project_dir).resolve()):
                continue
            _, baseline = self._stage_usage_baseline(project_dir)
            for key in totals:
                quantity = quantities.get(key, 0)
                if type(quantity) in (int, float) and math.isfinite(quantity) and quantity >= 0:
                    totals[key] += max(0, quantity - baseline.get(key, 0))
            observed = True
        # A reopened stage has an isolated quota envelope for the admitted
        # continuation cycle.  Its top-level ``usage`` is the previous
        # attempt's snapshot; using it as a fallback before the new cycle has
        # an attempt recreates the exhausted quota and can spin continuations
        # without ever dispatching work.
        isolated_reopened_cycle = stage_id in self.reopened_stage_ids and active_cycle
        if (not observed and not isolated_reopened_cycle
                and isinstance(record, dict) and isinstance(record.get("usage"), dict)):
            for key in totals:
                value = record["usage"].get(key, 0)
                if type(value) in (int, float) and math.isfinite(value) and value >= 0:
                    totals[key] += value
        stage = next((item for item in self.workflow.get("stages", [])
                      if isinstance(item, dict) and item.get("id") == stage_id), {})
        quota = stage.get("quota")
        ledger = self.root / "state" / "stage-model-call-budget.sqlite"
        if isinstance(quota, dict) and ledger.is_file():
            cycle = active_cycle if stage_id in self.reopened_stage_ids else 0
            with closing(sqlite3.connect(ledger.resolve().as_uri() + "?mode=ro", uri=True)) as connection:
                row = connection.execute("SELECT max_calls, used_calls FROM model_call_budgets WHERE budget_key=?",
                    (f"stage:{stage_id}:cycle:{cycle}",)).fetchone()
            if row is not None:
                if row[0] != quota["max_model_calls"]:
                    raise ValidationError("persisted stage model-call limit changed")
                # Registered scopes already include legacy seed floors and every
                # physical dispatch. Lifetime settlement deltas can contain
                # other cycles and must not be promoted into this allowance.
                totals["model_calls"] = row[1]
            scope = {"model_call_budget_path": str(ledger.resolve()),
                     "model_call_budget_key": f"stage:{stage_id}:cycle:{cycle}",
                     "model_call_budget_limit": quota["max_model_calls"],
                     "model_token_budget_limits": {"input_tokens": quota["max_input_tokens"],
                                                   "output_tokens": quota["max_output_tokens"]}}
            for key, quantity in model_token_budget_usage(scope).items():
                totals[key] = quantity
            contributions = self._legacy_stage_model_invoices(stage_id, scope)
            if contributions:
                with closing(sqlite3.connect(ledger.resolve().as_uri() + "?mode=ro", uri=True)) as connection:
                    totals.update(self._legacy_stage_budget_projection(connection, scope, contributions))
        if stage_kind == "survey":
            from scisaurus.runtime.literature import openalex_request_usage
            projects = {item["project_dir"] for item in attempts if isinstance(item, dict)
                        and isinstance(item.get("project_dir"), str)}
            if isinstance(record.get("project_dir"), str):
                projects.add(record["project_dir"])
            provider_total, provider_observed = 0, False
            cycle = active_cycle if stage_id in self.reopened_stage_ids else 0
            for project_dir in projects:
                project = Path(project_dir)
                database = project / "state" / "control.sqlite"
                if not database.is_file():
                    continue
                with closing(sqlite3.connect(database.resolve().as_uri()+"?mode=ro", uri=True)) as connection:
                    usage = openalex_request_usage(connection,
                        lambda digest: (project / "objects" / "sha256" / digest).read_bytes(),
                        owner_key=f"stage:{stage_id}:cycle:{cycle}")
                if usage["owner_registered"]:
                    provider_observed = True
                    provider_total += usage["openalex_requests"]
            if provider_observed:
                totals["openalex_requests"] = provider_total
        return totals

    def _stage_token_limits(self, stage):
        quota = stage["quota"]
        cycle = self.continuation_cycles if stage["id"] in self.reopened_stage_ids else 0
        return model_token_budget_limits({
            "model_call_budget_path": str((self.root / "state/stage-model-call-budget.sqlite").resolve()),
            "model_call_budget_key": f"stage:{stage['id']}:cycle:{cycle}",
            "model_call_budget_limit": quota["max_model_calls"],
            "model_token_budget_limits": {"input_tokens": quota["max_input_tokens"],
                                           "output_tokens": quota["max_output_tokens"]}})

    def _stage_quota_error(self, stage):
        """Check an aggregate stage quota before admitting another attempt."""
        quota = stage.get("quota") if isinstance(stage, dict) else None
        if not isinstance(quota, dict):
            return None
        usage = self._stage_usage(stage["id"])
        tokens = self._stage_token_limits(stage)
        dimensions = {
            "max_model_calls": ("model_calls", quota["max_model_calls"]),
            "max_input_tokens": ("input_tokens", tokens["input_tokens"]),
            "max_output_tokens": ("output_tokens", tokens["output_tokens"]),
            "max_openalex_requests": ("openalex_requests", quota["max_openalex_requests"]),
        }
        for dimension, (usage_key, limit) in dimensions.items():
            if dimension in MODEL_COST_LIMITS and not enforce_model_cost_limits():
                continue
            if usage[usage_key] > limit or (limit > 0 and usage[usage_key] == limit):
                error = QuotaExceededError(
                    f"stage {stage['id']} quota exhausted: {usage_key}={usage[usage_key]} >= {limit}",
                    dimension=dimension, limit=limit, observed=usage[usage_key], usage=usage,
                )
                error.usage_is_snapshot = True
                return error
        return None

    def _admit_stage_quota_recovery(self, stage, quota_error, completed, by_id):
        """Turn a local stage-budget exhaustion into changed scoped work.

        A stage quota is an allocation boundary for one stage attempt, not a
        scientific conclusion and not a reason to park an otherwise live
        mission.  The old path converted this condition directly to
        ``paused``; the outer supervisor then deliberately refused to resume
        it, leaving a scheduled retry with no process to consume it.  Reopen
        the affected closure with a typed recovery marker so the next
        attempt can narrow its work rather than replaying the same packet.

        Provider/global quota errors do not enter this helper.  They remain
        resource fences because dispatching another call would be unsafe.
        """
        if not isinstance(stage, dict):
            return False
        if not isinstance(quota_error, QuotaExceededError):
            return False
        admission = getattr(quota_error, "budget_admission", None)
        if admission is not None:
            cycle = self.continuation_cycles if stage["id"] in self.reopened_stage_ids else 0
            quota = stage.get("quota") or {}
            limit = quota.get(quota_error.dimension)
            if quota_error.dimension in {"max_input_tokens", "max_output_tokens"}:
                token_limits = self._stage_token_limits(stage)
                limit = token_limits[quota_error.dimension.removeprefix("max_")]
            if (admission.get("path") != str((self.root/"state/stage-model-call-budget.sqlite").resolve())
                    or admission.get("key") != f"stage:{stage['id']}:cycle:{cycle}"
                    or limit != admission.get("limit")):
                return False
        if stage.get("kind") == "topic_discovery":
            # A combined topic stage can include specialist and verifier calls
            # in addition to the topic runner's own envelope. If that aggregate
            # fence is nevertheless reached, treat it as a spent local intake
            # and pivot to a fresh continuation rather than ending the mission.
            quota_error.topic_budget_scope = "continuation"
            return self._admit_scientific_blocker_recovery(
                stage, quota_error, completed, by_id)
        if self._remaining() <= self._deadline_dispatch_floor():
            return False
        stage_id = stage["id"]
        prior = self.context.get(stage_id)
        context = deepcopy(prior) if isinstance(prior, dict) else {
            "stage_id": stage_id, "kind": stage.get("kind"),
        }
        previous_cycle = self.continuation_cycles
        existing = context.get("quota_recovery")
        if (isinstance(existing, dict)
                and existing.get("previous_cycle") == previous_cycle):
            if (existing.get("status") != "required"
                    or context.get("review_status") != "stage_quota_exhausted"
                    or context.get("error") != str(quota_error)):
                return False
            pending_context = deepcopy(context)
            existing["status"] = "admitted"
            existing["admitted_cycle"] = previous_cycle + 1
            existing["request_id"] = existing.get("request_id") or (
                self._autonomous_recovery_request_id(stage_id, previous_cycle + 1)
            )
            context["quota_recovery"] = existing
            self.context[stage_id] = context
            if not self._begin_continuation(completed, by_id):
                self.context[stage_id] = pending_context
                return False
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "stage_quota_recovery_admitted",
                "stage_id": stage_id,
                "recovery_id": existing.get("recovery_id"),
                "previous_cycle": previous_cycle,
                "dimension": getattr(quota_error, "dimension", None),
                "limit": getattr(quota_error, "limit", None),
                "observed": getattr(quota_error, "observed", None),
                "repair_mode": "narrow_scope",
                "resumed_pending_admission": True,
            })
            return True
        prior_recoveries = 0
        topic_identity = self._current_topic_identity() or {}
        same_quota_scope = (
            isinstance(existing, dict)
            and existing.get("dimension") == getattr(quota_error, "dimension", None)
            and existing.get("limit") == getattr(quota_error, "limit", None)
            and existing.get("topic_id") in (None, topic_identity.get("topic_id"))
            and existing.get("topic_cycle") in (None, topic_identity.get("topic_cycle"))
        )
        if same_quota_scope and type(existing.get("recovery_count")) is int:
            prior_recoveries = max(0, existing["recovery_count"])
        recovery_count = prior_recoveries + 1
        if (stage.get("kind") == "survey" and prior_recoveries >= 1):
            # A local model-call ceiling is not scientific evidence against
            # the topic. Use retained sources for one gap-assessment-only
            # repair; if that exact workspace is unavailable, keep the same
            # topic blocked for an explicit decision instead of manufacturing
            # a topic pivot from quota arithmetic.
            if self._admit_scoped_survey_repair(
                    stage, context, completed, by_id, quota_error):
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "route_repeated_survey_quota_to_retained_evidence_repair",
                    "stage_id": stage_id,
                    "recovery_count": recovery_count,
                    "reason": "quota exhaustion does not adjudicate the topic",
                    "next_action": "complete_only_the_missing_survey_milestone_from_retained_evidence",
                })
                return True
            context.update({
                "stage_id": stage_id,
                "kind": stage.get("kind"),
                "status": "blocked",
                "error": str(quota_error)[:4096],
                "review_status": "survey_quota_recovery_exhausted",
                "quota_recovery": {
                    "status": "exhausted",
                    "mode": "retained_evidence_repair",
                    "previous_cycle": previous_cycle,
                    "recovery_count": recovery_count,
                    "dimension": getattr(quota_error, "dimension", None),
                    "limit": getattr(quota_error, "limit", None),
                    "observed": getattr(quota_error, "observed", None),
                    "reason": (
                        "retained-evidence repair could not be safely admitted; quota alone does not justify a topic pivot"
                    ),
                },
                "release_blocking": True,
                "research_expansion_requests": [],
                "research_requests": [],
            })
            self.context[stage_id] = context
            self.department_activity.append({
                "cycle": previous_cycle,
                "action": "hold_survey_quota_without_topic_pivot",
                "stage_id": stage_id,
                "recovery_count": recovery_count,
                "reason": "the retained evidence frontier was unavailable for a scoped repair",
                "next_action": "preserve_topic_and_request_a_concrete_scoped_evidence_plan",
            })
            return False
        if same_quota_scope and prior_recoveries >= 1:
            exhausted = deepcopy(existing)
            exhausted.update({
                "status": "exhausted",
                "exhausted_cycle": previous_cycle,
                "recovery_count": prior_recoveries,
                "dimension": getattr(quota_error, "dimension", None),
                "limit": getattr(quota_error, "limit", None),
                "observed": getattr(quota_error, "observed", None),
                "reason": (
                    "the original allocation and one narrowed recovery allocation both "
                    "exhausted the same stage quota"
                ),
            })
            context.update({
                "status": "blocked",
                "error": str(quota_error)[:4096],
                "review_status": "stage_quota_recovery_exhausted",
                "release_blocking": True,
                "quota_recovery": exhausted,
                "research_expansion_requests": [],
                "research_requests": [],
            })
            self.context[stage_id] = context
            self.department_activity.append({
                "cycle": previous_cycle,
                "action": "stage_quota_recovery_exhausted",
                "stage_id": stage_id,
                "dimension": getattr(quota_error, "dimension", None),
                "limit": getattr(quota_error, "limit", None),
                "observed": getattr(quota_error, "observed", None),
                "recovery_count": prior_recoveries,
                "next_action": "stop_dispatching_this_stage_until_its_workload_or_quota_changes",
            })
            return False
        context.update({
            "stage_id": stage_id,
            "kind": stage.get("kind"),
            "status": "research_expansion_required",
            "error": str(quota_error)[:4096],
            "review_status": "stage_quota_exhausted",
            "quota_recovery": {
                "status": "admitted",
                "recovery_id": f"quota-recovery-{stage_id}-{previous_cycle}-{uuid.uuid4().hex[:12]}",
                "mode": "narrow_scope",
                "previous_cycle": previous_cycle,
                "admitted_cycle": previous_cycle + 1,
                "request_id": self._autonomous_recovery_request_id(
                    stage_id, previous_cycle + 1),
                "recovery_count": recovery_count,
                "topic_id": topic_identity.get("topic_id"),
                "topic_cycle": topic_identity.get("topic_cycle"),
                "dimension": getattr(quota_error, "dimension", None),
                "limit": getattr(quota_error, "limit", None),
                "observed": getattr(quota_error, "observed", None),
                "reason": "the local stage allocation was consumed before the decisive gate completed",
                **({"budget_admission": deepcopy(admission)} if admission is not None else {}),
            },
            "research_expansion_requests": [],
            "research_requests": [],
        })
        pending_context = deepcopy(context)
        self.context[stage_id] = context
        if not self._begin_continuation(completed, by_id):
            self.context[stage_id] = pending_context
            self.context[stage_id]["quota_recovery"]["status"] = "required"
            self.context[stage_id]["quota_recovery"].pop("admitted_cycle", None)
            self.context[stage_id]["quota_recovery"].pop("request_id", None)
            return False
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "stage_quota_recovery_admitted",
            "stage_id": stage_id,
            "recovery_id": context["quota_recovery"]["recovery_id"],
            "previous_cycle": previous_cycle,
            "dimension": getattr(quota_error, "dimension", None),
            "limit": getattr(quota_error, "limit", None),
            "observed": getattr(quota_error, "observed", None),
            "repair_mode": "narrow_scope",
            "next_condition": (
                "resume from accepted checkpoints with a smaller decisive workload; "
                "do not replay the exhausted packet"
            ),
        })
        return True

    def _resume_stage_quota_recovery(self, completed, by_id):
        """Resume only the current stage's still-pending local-quota stop.

        ``blockers`` is an append-only history, not a queue. A blocker is
        actionable only while the stage's current context still records that
        exact quota failure as pending. This prevents a restart from replaying
        a stale quota stop after a later stage result has already superseded it.
        """
        reconciled = False
        for blocker in reversed(self.blockers):
            if not isinstance(blocker, dict):
                continue
            if blocker.get("stop_reason") != "stage_quota_exhausted":
                continue
            if blocker.get("recovery") in {
                    "cycle_admitted", "superseded_by_current_scientific_review"}:
                continue
            stage_id = blocker.get("stage_id")
            stage = by_id.get(stage_id)
            if not isinstance(stage, dict):
                continue
            context = self.context.get(stage_id)
            recovery = context.get("quota_recovery") if isinstance(context, dict) else None
            current_error = context.get("error") if isinstance(context, dict) else None
            record = self.stage_records.get(stage_id)
            attempts = record.get("attempts", []) if isinstance(record, dict) else []
            pending_cycle = recovery.get("previous_cycle") if isinstance(recovery, dict) else None
            later_attempt = (
                isinstance(pending_cycle, int)
                and isinstance(attempts, list)
                and any(
                    isinstance(attempt, dict)
                    and isinstance(attempt.get("cycle"), int)
                    and attempt["cycle"] > pending_cycle
                    for attempt in attempts
                )
            )
            quota_fields_match = isinstance(recovery, dict) and all(
                recovery.get(field) == blocker.get(field)
                for field in ("dimension", "limit", "observed")
                if field in blocker
            )
            recovery_ids_match = (
                not blocker.get("quota_recovery_id")
                or (
                    isinstance(recovery, dict)
                    and blocker.get("quota_recovery_id") == recovery.get("recovery_id")
                )
            )
            pending_is_current = (
                isinstance(context, dict)
                and context.get("status") == "research_expansion_required"
                and context.get("review_status") == "stage_quota_exhausted"
                and isinstance(recovery, dict)
                and recovery.get("status") == "required"
                and current_error == blocker.get("reason")
                and quota_fields_match
                and recovery_ids_match
                and not later_attempt
                and not (
                    isinstance(record, dict)
                    and record.get("status") == "running"
                    and isinstance(record.get("attempt_id"), str)
                )
            )
            if not pending_is_current:
                blocker["recovery"] = "superseded_by_current_stage_state"
                blocker["superseded_stage_status"] = (
                    record.get("status") if isinstance(record, dict) else None
                )
                blocker["superseded_by_attempt_cycle"] = max(
                    (attempt.get("cycle") for attempt in attempts
                     if isinstance(attempt, dict)
                     and isinstance(attempt.get("cycle"), int)),
                    default=None,
                )
                reconciled = True
                continue
            error = QuotaExceededError(
                blocker.get("reason") or f"stage {stage_id} quota exhausted",
                dimension=blocker.get("dimension"),
                limit=blocker.get("limit"),
                observed=blocker.get("observed"),
                usage=blocker.get("usage", {}),
            )
            error.usage_is_snapshot = True
            if self._admit_stage_quota_recovery(stage, error, completed, by_id):
                blocker["recovery"] = "cycle_admitted"
                recovery = self.context.get(stage_id, {}).get("quota_recovery", {})
                blocker["quota_recovery_id"] = recovery.get("recovery_id")
                record = self.stage_records.get(stage_id)
                if isinstance(record, dict):
                    record["status"] = "retrying"
                    record["recovery_admitted"] = True
                return True
        if reconciled:
            self._checkpoint("resume:stale_stage_quota_blockers_reconciled", force=True)
        return False

    def _survey_attempt_was_accepted(self, stage_id, attempt, run):
        rows = self.departments._assignment_task_rows(
            stage_id=stage_id, attempt_number=attempt.get("attempt_number"))
        verifier = next((item for item in rows if item.get("assignment_phase") == "verifier"), None)
        if verifier is None:
            return False
        try:
            verdict_record = self.store.head(verifier["assignment_logical_id"])
            verdict = json.loads(self.store.read_body(verdict_record["body_hash"]))
            chief_record = self.store.get(verdict["chief_synthesis_ref"])
            chief = json.loads(self.store.read_body(chief_record["body_hash"]))
            execution_record = self.store.get(verdict["verifier_execution_artifact_ref"])
            execution = json.loads(self.store.read_body(execution_record["body_hash"]))
            report = execution["report"]
            reviewed = execution["chief_result"]
            if (not all(isinstance(body, dict) for body in (chief, verdict, execution, report, reviewed))
                    or not isinstance(report.get("response"), dict)):
                return False
            identity = {"stage_id": stage_id, "stage_kind": "survey",
                        "attempt_number": attempt["attempt_number"]}
            return (
                all(all(body.get(key) == value for key, value in identity.items())
                    for body in (chief, verdict, execution))
                and chief.get("schema_version") == "department-chief-synthesis-1"
                and chief.get("outcome") in {"completed", "accepted"}
                and verdict.get("schema_version") == "department-adversarial-verdict-1"
                and verdict.get("verdict") == "accepted"
                and verdict.get("attempt_state") == "succeeded"
                and verdict.get("task_state") == "completed"
                and verdict.get("independence_check") is True
                and execution.get("schema_version") == "specialist-verifier-execution-1"
                and report.get("status") == "succeeded"
                and report.get("response", {}).get("decision") == "accept"
                and canonical_bytes(report.get("response")) == canonical_bytes(verdict.get("verifier_report"))
                and reviewed.get("survey_ref") == run["survey_ref"]
                and reviewed.get("assessment_ref") == run["assessment_ref"]
                and (self._survey_revalidation_reference(stage_id, run) is None
                     or reviewed.get("revalidation") == self._survey_revalidation_reference(stage_id, run))
                and (not isinstance(run.get("follow_up_result"), dict)
                     or reviewed.get("follow_up_result") == run["follow_up_result"])
            )
        except (KeyError, TypeError, ValueError, OSError, NotFoundError, ValidationError):
            return False

    def _survey_revalidation_reference(self, stage_id, run):
        if isinstance(run.get("revalidation"), dict):
            return run["revalidation"]
        run_id = run.get("run_id")
        if not isinstance(run_id, str):
            return None
        head = self.store.head(f"command/composer/survey-revalidations/{stage_id}/{run_id}")
        return {"ref": head["artifact_ref"], "body_sha256": head["body_hash"]} if head else None

    def _survey_request_was_fulfilled(self, project_dir, run, request):
        if "resume_scopes" not in request:
            return self._survey_work_order_was_fulfilled(project_dir, run, request)
        try:
            scopes = self._validate_survey_revalidation_scopes(request)
            receipt = self._survey_revalidation_reference(request["target_stage_id"], run) or {}
            record, _, body = self._read_verified_artifact_json(receipt["ref"])
            if (record.get("author") != "command.composer" or record["body_hash"] != receipt.get("body_sha256")
                    or body.get("schema_version") != "composer-survey-revalidation-1"
                    or body.get("project_dir") != str(Path(project_dir).resolve())
                    or body.get("stage_id") != request["target_stage_id"]
                    or request.get("id") not in body.get("request_ids", [])
                    or self._research_request_signature(request) not in body.get("request_signatures", [])
                    or not set(scopes).issubset(body.get("declared_scopes", body.get("reopened_scopes", [])))
                    or any(body.get(key) != run.get(key) for key in ("run_id", "survey_ref", "assessment_ref"))):
                return False
            admission, _, decision = self._read_verified_artifact_json(body["continuation_ref"])
            if (admission.get("author") != "command.composer"
                    or decision.get("action") != "continue_research"
                    or decision.get("cycle") != body.get("cycle")
                    or body["stage_id"] not in decision.get("reopened_stage_ids", [])
                    or not any(isinstance(item, dict) and item.get("id") == request.get("id")
                               and self._research_request_signature(item) == self._research_request_signature(request)
                               for item in decision.get("research_requests", []))):
                return False
            with closing(sqlite3.connect((Path(project_dir) / "state/control.sqlite").resolve().as_uri()
                                         + "?mode=ro", uri=True, timeout=2.0)) as connection:
                connection.row_factory = sqlite3.Row
                connection.execute("PRAGMA query_only=ON")
                store = ArtifactStore(SimpleNamespace(dir=str(Path(project_dir).resolve()), _conn=connection))
                for key, hash_key in (("config_ref", "config_sha256"), ("resume_ref", "resume_sha256"),
                                      ("result_ref", "result_sha256"), ("survey_ref", "survey_sha256"),
                                      ("assessment_ref", "assessment_sha256")):
                    artifact = store.get(body[key])
                    raw = store.read_body(artifact["body_hash"])
                    if hashlib.sha256(raw).hexdigest() != body[hash_key] or artifact["body_hash"] != body[hash_key]:
                        return False
                skipped = set(body.get("declared_scopes", body["reopened_scopes"])) - set(body["reopened_scopes"])
                if skipped:
                    milestone = body.get("completed_mapping") or {}
                    if skipped != {"mapping"} or milestone.get("phase") != "mapping":
                        return False
                    for key in ("map", "resume", "config"):
                        artifact = store.get(milestone[key + "_ref"])
                        raw = store.read_body(artifact["body_hash"])
                        if hashlib.sha256(raw).hexdigest() != milestone[key + "_sha256"]:
                            return False
                    if milestone["config_ref"] != body["config_ref"]:
                        return False
                    checkpoint = milestone.get("producer_checkpoint") or {}
                    artifact = store.get(checkpoint["ref"])
                    if artifact["body_hash"] != checkpoint.get("body_sha256"):
                        return False
                    owner = self.tasks.get_attempt(milestone["aggregate_attempt_id"])
                    mapped_record, original_session = store.get(milestone["map_ref"]), store.get(milestone["resume_ref"])
                    mapped = json.loads(store.read_body(milestone["map_sha256"]))
                    resumed_mapping = json.loads(store.read_body(milestone["resume_sha256"]))
                    configured = json.loads(store.read_body(milestone["config_sha256"]))
                    checkpoint_record = store.get(checkpoint["ref"])
                    checkpoint_raw = store.read_body(checkpoint_record["body_hash"])
                    if (hashlib.sha256(checkpoint_raw).hexdigest() != checkpoint["body_sha256"]
                            or json.loads(checkpoint_raw).get("cumulative_usage", {}).get("actual") != checkpoint.get("actual_usage")
                            or mapped_record.get("author") != "research.literature-mapper"
                            or mapped.get("question") != configured.get("survey", {}).get("question")
                            or resumed_mapping.get("config_ref") != body["config_ref"]
                            or "mapping" not in resumed_mapping.get("reopened_scopes", [])
                            or not owner["created_at"] <= original_session["created_at"] <= mapped_record["created_at"] <= checkpoint_record["created_at"]
                            or owner.get("payload", {}).get("project_dir") != body["project_dir"]
                            or owner.get("payload", {}).get("stage_id") != body["stage_id"]
                            or owner.get("payload", {}).get("model_budget_cycle") != self._survey_mapping_owner_cycle(
                                {"id": body["stage_id"], "project_dir": body["project_dir"]}, milestone, decision)):
                        return False
                final_record = store.get(body["result_ref"])
                resume_record = store.get(body["resume_ref"])
                if (final_record.get("author") != "command.controller"
                        or resume_record.get("author") != "command.controller"
                        or resume_record["created_at"] > final_record["created_at"]):
                    return False
                result = json.loads(store.read_body(body["result_sha256"]))
                resumed = json.loads(store.read_body(body["resume_sha256"]))
                if (result.get("status") not in {"completed", "accepted"}
                        or any(result.get(key) != body[key] for key in ("run_id", "survey_ref", "assessment_ref"))
                        or resumed.get("schema_version") != "resume-session-1"
                        or resumed.get("config_ref") != body["config_ref"]
                        or resumed.get("reopened_scopes") != body["reopened_scopes"]):
                    return False
            return self._survey_references_are_current(project_dir, run)
        except (KeyError, TypeError, ValueError, OSError, NotFoundError, ValidationError, sqlite3.Error):
            return False

    def _record_survey_revalidation(self, stage, result, scopes, prior_run_id, *, declared_scopes=None, mapping_milestone=None):
        if result.get("status") not in {"completed", "accepted"}:
            return
        if not isinstance(result.get("run_id"), str) or result["run_id"] == prior_run_id:
            raise StateError("survey revalidation did not produce a fresh owned run")
        project = Path(stage["project_dir"]).resolve()
        with closing(sqlite3.connect((project / "state/control.sqlite").as_uri() + "?mode=ro", uri=True)) as connection:
            connection.row_factory = sqlite3.Row
            connection.execute("PRAGMA query_only=ON")
            store = ArtifactStore(SimpleNamespace(dir=str(project), _conn=connection))
            row = connection.execute("SELECT artifact_ref FROM artifacts WHERE logical_id LIKE 'command/resume-sessions/%' "
                                     "ORDER BY created_at DESC, rowid DESC LIMIT 1").fetchone()
            artifacts = {"config": store.head("inputs/run-config"), "result": store.head("command/results/final"),
                         "resume": store.get(row["artifact_ref"]) if row else None,
                         "survey": store.get(result["survey_ref"]), "assessment": store.get(result["assessment_ref"])}
            if any(record is None for record in artifacts.values()):
                raise StateError("survey revalidation lacks immutable completion dependencies")
            requests = [item for item in self._requests_for_stage(stage) if "resume_scopes" in item]
            body = {"schema_version": "composer-survey-revalidation-1", "stage_id": stage["id"],
                    "cycle": self.continuation_cycles, "project_dir": str(project),
                    "run_id": result["run_id"], "reopened_scopes": scopes,
                    "declared_scopes": declared_scopes or scopes, "completed_mapping": mapping_milestone,
                    "request_ids": [item["id"] for item in requests],
                    "request_signatures": [self._research_request_signature(item) for item in requests],
                    "continuation_ref": self.store.head(f"command/composer/continuation/{self.continuation_cycles}")["artifact_ref"],
                    "retained_follow_up_ref": self.context.get(stage["id"], {}).get("follow_up_ref"),
                    "retained_follow_up_result": deepcopy(self.context.get(stage["id"], {}).get("follow_up_result"))}
            for key, record in artifacts.items():
                body[key + "_ref"] = record["artifact_ref"]
                body[key + "_sha256"] = record["body_hash"]
        record = self._publish(f"command/composer/survey-revalidations/{stage['id']}/{result['run_id']}",
                               "report", body, "command.composer")
        result["revalidation"] = {"ref": record["artifact_ref"], "body_sha256": record["body_hash"]}
        if not all(self._survey_request_was_fulfilled(project, result, item) for item in requests):
            raise StateError("survey revalidation completion failed immutable replay")

    @staticmethod
    def _survey_work_order_was_fulfilled(project_dir, run, request):
        from scisaurus.core.source_spans import bind as bind_spans, expand_evidence
        from scisaurus.core.surveys import SurveyGate
        from scisaurus.runtime.models import ModelResult
        from scisaurus.runtime.survey import acquisition_succeeded
        from scisaurus.runtime.survey_records import validate_follow_up_result
        result = run.get("follow_up_result")
        if (not isinstance(result, dict) or not isinstance(result.get("ref"), str)
                or any(not isinstance(run.get(key), str) for key in ("survey_ref", "assessment_ref"))):
            return False
        try:
            with closing(sqlite3.connect(
                    (Path(project_dir) / "state/control.sqlite").resolve().as_uri() + "?mode=ro",
                    uri=True, timeout=2.0)) as connection:
                connection.row_factory = sqlite3.Row
                connection.execute("PRAGMA query_only=ON")
                control = SimpleNamespace(dir=str(Path(project_dir).resolve()), _conn=connection)
                store = ArtifactStore(control)
                gate = SurveyGate(control, store)
                record, raw_result = gate._artifact(result["ref"])
                body = json.loads(raw_result)
                packet, raw_packet = gate._artifact(body["follow_up_ref"])
                packet_body = json.loads(raw_packet)
                orders = packet_body["work_orders"]
                if (packet_body.get("schema_version") != "survey-follow-up-1"
                        or packet.get("author") != "command.controller"
                        or record.get("author") != "methods.evidence-verifier"):
                    return False
                execution_refs = body.get("execution_refs", [body["execution_ref"]])
                if (not isinstance(execution_refs, list) or not execution_refs
                        or any(not isinstance(ref, str) for ref in execution_refs)
                        or len(set(execution_refs)) != len(execution_refs)
                        or body.get("execution_ref") != execution_refs[-1]):
                    return False
                _, survey = gate._note(run["survey_ref"])
                _, assessment = gate._note(run["assessment_ref"])
                if assessment.get("survey_ref") != run["survey_ref"]:
                    return False
                gate.require_current_assessment(run["assessment_ref"])
                works = {}
                for ref in survey["work_refs"]:
                    _, raw_work = gate._artifact(ref)
                    work = json.loads(raw_work)
                    works[work["work_id"]] = work
                checked = {}
                for execution_ref in execution_refs:
                    execution, _, execution_body, model_params = gate._recorded_execution(
                        execution_ref, "methods.evidence-verifier", operation="model", task_kinds={"review"})
                    assignment = json.loads(model_params["prompt"])
                    assigned = assignment.get("work_orders")
                    if (execution.get("author") != "methods.evidence-verifier"
                            or execution_ref not in {item["ref"] for item in record["inputs"]}
                            or assignment.get("phase") != "survey_follow_up"
                            or assignment.get("follow_up_ref") != body["follow_up_ref"]
                            or not isinstance(assigned, list) or not assigned
                            or any(order not in orders for order in assigned)
                            or assignment.get("survey_ref") != run["survey_ref"]
                            or assignment.get("assessment_ref") != run["assessment_ref"]):
                        return False
                    windows = {source["source_ref"]: source["window"] for source in assignment["sources"]}
                    sources = {ref: json.loads(store.read_body(store.get(ref)["body_hash"])) for ref in windows}
                    query_refs = []
                    for ref in assignment["query_refs"]:
                        query = json.loads(store.read_body(store.get(ref)["body_hash"]))
                        plan = json.loads(store.read_body(store.get(query["plan_ref"])["body_hash"]))
                        if (query.get("request", {}).get("operation") == "search" and acquisition_succeeded(query)
                                and plan.get("follow_up_ref") == body["follow_up_ref"]):
                            query_refs.append(ref)
                    if execution_body.get("finish_reason", "stop") not in {"stop", "length"}:
                        return False
                    response = ModelResult(text=execution_body["text"], model="retained", usage={},
                                           elapsed_seconds=0, finish_reason=execution_body.get("finish_reason", "stop")).json_object(
                                               allow_missing_closers=True)
                    response = expand_evidence(response, assignment.get("evidence_catalog", []), sources, windows=windows)
                    response = bind_spans(response, sources, windows=windows)
                    validate_follow_up_result(response, assigned, sources, query_refs, windows=windows)
                    for row in response["orders"]:
                        if row["id"] in checked:
                            return False
                        gate._evidence(row["evidence"], works, survey, required=row["status"] == "resolved")
                        for query_ref in row["query_refs"]:
                            gate.require_successful_follow_up_search(query_ref, survey, body["follow_up_ref"])
                        checked[row["id"]] = row
                if (set(checked) != {order["id"] for order in orders}
                        or [checked[order["id"]] for order in orders] != body.get("orders")):
                    return False
                projected = ComposerRunner._follow_up_projection([request])[0]
                return (body.get("schema_version") == "survey-follow-up-result-1"
                        and body.get("survey_ref") == run["survey_ref"]
                        and body.get("assessment_ref") == run["assessment_ref"]
                        and body.get("orders") == result.get("orders")
                        and any(isinstance(order, dict)
                                and ComposerRunner._follow_up_projection([order])[0] == projected for order in orders)
                        and any(isinstance(row, dict) and row.get("id") == request.get("id")
                                and row.get("status") in {"resolved", "limited"}
                                for row in body["orders"]))
        except (sqlite3.Error, IndexError, KeyError, TypeError, ValueError, OSError, NotFoundError, ValidationError, ConflictError):
            return False

    @staticmethod
    def _survey_references_are_current(project_dir, run):
        from scisaurus.core.surveys import SurveyGate
        try:
            with closing(sqlite3.connect(
                    (Path(project_dir) / "state/control.sqlite").resolve().as_uri() + "?mode=ro",
                    uri=True, timeout=2.0)) as connection:
                connection.row_factory = sqlite3.Row
                connection.execute("PRAGMA query_only=ON")
                control = SimpleNamespace(dir=str(Path(project_dir).resolve()), _conn=connection)
                gate = SurveyGate(control, ArtifactStore(control))
                _, assessment = gate._note(run["assessment_ref"])
                if assessment.get("survey_ref") != run["survey_ref"]:
                    return False
                gate.require_current_assessment(run["assessment_ref"])
                return True
        except (sqlite3.Error, KeyError, TypeError, ValueError, OSError, NotFoundError, ValidationError, ConflictError):
            return False

    def _survey_acquisition_frontier_for_topic(self, stage_id, topic_id, topic_cycle, request):
        """Find the current immutable disposition for one exact acquisition scope."""
        if topic_id is None or topic_cycle is None:
            identity = self._current_topic_identity()
            if (not isinstance(identity, dict)
                    or topic_id is not None and topic_id != identity["topic_id"]
                    or topic_cycle is not None and topic_cycle != identity["topic_cycle"]
                    or not self._research_request_was_admitted(request)):
                return None
            topic_id, topic_cycle = identity["topic_id"], identity["topic_cycle"]
        if (request.get("topic_id") not in (None, topic_id)
                or request.get("topic_cycle") not in (None, topic_cycle)
                or request.get("topic_cycle") is not None and type(request["topic_cycle"]) is not int):
            return None
        record = self.stage_records.get(stage_id, {})
        attempts = record.get("attempts", []) if isinstance(record, dict) else []
        seen = set()
        for attempt in reversed(attempts if isinstance(attempts, list) else []):
            if (not isinstance(attempt, dict)
                    or attempt.get("state") not in {"succeeded", "completed"}
                    or attempt.get("topic_id") != topic_id
                    or attempt.get("topic_cycle") != topic_cycle
                    or not isinstance(attempt.get("project_dir"), str)):
                continue
            project = Path(attempt["project_dir"]).resolve()
            if project in seen:
                continue
            seen.add(project)
            run = self._read_json_object(project / "output" / "run.json")
            if (not isinstance(run, dict) or run.get("status") != "completed"
                    or run.get("survey_current") is not True
                    or run.get("assessment_current") is not True
                    or not self._survey_request_was_fulfilled(project, run, request)):
                continue
            gated = self._read_json_object(project / "output" / "composer-gated-run.json")
            return attempt, project, run, gated or run
        return None

    def _restore_interrupted_completed_survey_acquisition(self, completed, by_id):
        """Resume downstream work when an interrupted replay has no new acquisition scope."""
        identity = self._current_topic_identity()
        if not isinstance(identity, dict):
            return False
        restored = False
        for stage_id in list(self.continuation_pending_stage_ids):
            stage = by_id.get(stage_id, {})
            record = self.stage_records.get(stage_id, {})
            attempts = record.get("attempts", [])
            latest = next((item for item in reversed(attempts)
                           if isinstance(item, dict)), None) if isinstance(attempts, list) else None
            if (stage.get("kind") != "survey" or record.get("status") != "retrying"
                    or not isinstance(latest, dict) or latest.get("state") != "unknown"
                    or latest.get("attempt_id") != record.get("last_attempt_id")):
                continue
            orders = [item for item in self.active_research_requests
                      if isinstance(item, dict)
                      and (item.get("target_stage_id") == stage_id
                           or not item.get("target_stage_id") and self._request_target_kind(item) == "survey")]
            if not orders or any(item.get("kind") != "literature_expansion" for item in orders):
                continue
            frontiers = [self._survey_acquisition_frontier_for_topic(
                stage_id, identity["topic_id"], identity["topic_cycle"], order) for order in orders]
            if any(frontier is None for frontier in frontiers):
                continue
            _, project, run, result = frontiers[0]
            incumbent = self.context.get(stage_id, {})
            if (any(item[1] != project for item in frontiers)
                    or result.get("status") not in {"completed", "accepted", "candidate_needs_review"}
                    or incumbent.get("status") != "candidate_needs_review"
                    or not self._stage_releases_dependencies(incumbent, stage_kind="survey")
                    or incumbent.get("survey_ref") != run.get("survey_ref")
                    or incumbent.get("assessment_ref") != run.get("assessment_ref")
                    or result.get("survey_ref") != run.get("survey_ref")
                    or result.get("assessment_ref") != run.get("assessment_ref")):
                continue
            context = deepcopy(incumbent)
            context.update(stage_id=stage_id, kind="survey", project_dir=str(project))
            self.context[stage_id] = context
            record.update(status=context["status"], project_dir=str(project), recovery_admitted=False)
            self.stage_records[stage_id] = record
            self.continuation_pending_stage_ids.discard(stage_id)
            completed.add(stage_id)
            self.department_activity.append({
                "cycle": self.continuation_cycles, "action": "reuse_completed_survey_acquisition",
                "stage_id": stage_id, "request_ids": [item["id"] for item in orders],
                "survey_ref": run["survey_ref"], "assessment_ref": run["assessment_ref"],
                "scientific_status": context["status"], "model_calls": 0,
            })
            restored = True
        return restored

    def _completed_survey_frontier_for_topic(self, stage_id, topic_id, topic_cycle):
        """Find a completed, durable survey/assessment pair for one topic."""
        record = self.stage_records.get(stage_id)
        attempts = record.get("attempts", []) if isinstance(record, dict) else []
        if not isinstance(attempts, list):
            return None
        for attempt in reversed(attempts):
            if (not isinstance(attempt, dict)
                    or attempt.get("state") not in {"succeeded", "completed"}
                    or attempt.get("topic_id") != topic_id
                    or attempt.get("topic_cycle") != topic_cycle
                    or not isinstance(attempt.get("project_dir"), str)):
                continue
            project_dir = Path(attempt["project_dir"]).resolve()
            run = self._read_json_object(project_dir / "output" / "run.json")
            gated = self._read_json_object(
                project_dir / "output" / "composer-gated-run.json")
            result = gated or run
            if (not isinstance(run, dict) or not isinstance(result, dict)
                    or result.get("status") not in {"completed", "accepted"}
                    or result.get("topic_admission") not in {
                        "provisional_supported_for_experiment", "exploratory_pilot"}
                    or run.get("survey_current") is not True
                    or run.get("assessment_current") is not True
                    or not isinstance(run.get("survey_ref"), str)
                    or not isinstance(run.get("assessment_ref"), str)
                    or result.get("survey_ref") != run["survey_ref"]
                    or result.get("assessment_ref") != run["assessment_ref"]):
                continue
            if (result.get("gap_state") == "insufficient_evidence"
                    and result.get("topic_admission") != "exploratory_pilot"):
                continue
            references = [run["survey_ref"], run["assessment_ref"]]
            if (not self._survey_references_are_durable(project_dir, references)
                    or not self._survey_attempt_was_accepted(stage_id, attempt, run)
                    or not self._survey_references_are_current(project_dir, run)):
                continue
            return attempt, project_dir, run, result
        return None

    def _restore_completed_survey_after_quota_recovery(self, completed, by_id):
        """Reuse a current exploratory survey instead of buying another catalog pass.

        A quota recovery request is not a scientific finding. If its exact
        topic lineage already has a durable, admitted exploratory survey and
        current gap assessment, preserve that result and defer further
        literature expansion until the experiment identifies a concrete need.
        """
        stage = next((item for item in self.workflow.get("stages", [])
                      if item.get("kind") == "survey"), None)
        if not isinstance(stage, dict) or stage["id"] not in by_id:
            return False
        stage_id = stage["id"]
        context = self.context.get(stage_id)
        if not isinstance(context, dict):
            return False
        record = self.stage_records.get(stage_id)
        recovery = context.get("quota_recovery")
        recoverable_quota_state = (
            context.get("status") == "research_expansion_required"
            and context.get("review_status") == "stage_quota_exhausted"
            and isinstance(recovery, dict)
            and recovery.get("status") in {"required", "admitted"}
        ) or (
            context.get("status") == "blocked"
            and context.get("review_status") == "survey_quota_recovery_exhausted"
            and isinstance(recovery, dict)
            and recovery.get("status") == "exhausted"
        )
        if not recoverable_quota_state:
            return False
        topic = self._current_topic_identity()
        topic_id = topic.get("topic_id") if isinstance(topic, dict) else None
        topic_cycle = topic.get("topic_cycle") if isinstance(topic, dict) else None
        if not isinstance(topic_id, str) or type(topic_cycle) is not int:
            return False
        retained = self._completed_survey_frontier_for_topic(
            stage_id, topic_id, topic_cycle)
        if retained is None:
            return False

        attempt, project_dir, run, result = retained
        recovery_cycle = recovery.get("admitted_cycle")
        if type(recovery_cycle) is not int:
            previous_cycle = recovery.get("previous_cycle")
            recovery_cycle = previous_cycle + 1 if type(previous_cycle) is int else None
        request_id = recovery.get("request_id")
        if not isinstance(request_id, str) and type(recovery_cycle) is int:
            request_id = self._autonomous_recovery_request_id(stage_id, recovery_cycle)
        if any(item.get("id") != request_id
               for item in self._requests_for_stage(stage)):
            return False
        deferred = []
        active = []
        for request in self.active_research_requests:
            if (isinstance(request, dict)
                    and request.get("id") == request_id
                    and request.get("kind") == "literature_expansion"
                    and request.get("owner") == "research.intelligence"):
                deferred.append({
                    **deepcopy(request),
                    "deferred_reason": (
                        "The retained current survey already authorizes an explicitly exploratory "
                        "experiment. Reopen literature acquisition only for a concrete evidence need "
                        "identified from the experiment."
                    ),
                })
            else:
                active.append(request)
        self.active_research_requests = active

        restored = deepcopy(context)
        restored.update({
            "stage_id": stage_id,
            "kind": "survey",
            "status": "completed",
            "review_status": "exploratory_pilot_retained",
            "topic_id": topic_id,
            "topic_cycle": topic_cycle,
            "topic_lineage": {"topic_id": topic_id, "topic_cycle": topic_cycle},
            "project_dir": str(project_dir),
            "survey_ref": run["survey_ref"],
            "assessment_ref": run["assessment_ref"],
            "survey_current": True,
            "assessment_current": True,
            "gap_state": result.get("gap_state"),
            "topic_admission": result["topic_admission"],
            "quota_recovery": {
                **deepcopy(recovery),
                "status": "superseded_by_current_survey_result",
                "superseded_by_survey_ref": run["survey_ref"],
            },
        })
        restored.pop("error", None)
        if deferred:
            previous = restored.get("deferred_research_requests")
            previous = previous if isinstance(previous, list) else []
            restored["deferred_research_requests"] = [*previous, *deferred]
        self.context[stage_id] = restored

        updated_record = deepcopy(record) if isinstance(record, dict) else {"kind": "survey"}
        updated_record.update({
            "kind": "survey",
            "status": "completed",
            "topic_id": topic_id,
            "topic_cycle": topic_cycle,
            "project_dir": str(project_dir),
            "survey_ref": run["survey_ref"],
            "assessment_ref": run["assessment_ref"],
            "gap_state": result.get("gap_state"),
            "results_status": "completed",
            "restored_frontier": {
                "source_attempt": attempt.get("attempt_number"),
                "survey_ref": run["survey_ref"],
                "assessment_ref": run["assessment_ref"],
                "reason": "current exploratory survey result supersedes a cumulative quota retry",
            },
        })
        updated_record.pop("error", None)
        updated_record["recovery_admitted"] = False
        self.stage_records[stage_id] = updated_record
        self.continuation_pending_stage_ids.discard(stage_id)
        completed.add(stage_id)
        for blocker in self.blockers:
            if (isinstance(blocker, dict)
                    and blocker.get("stage_id") == stage_id
                    and blocker.get("stop_reason") == "stage_quota_exhausted"
                    and (not blocker.get("quota_recovery_id")
                         or blocker.get("quota_recovery_id") == recovery.get("recovery_id"))):
                blocker.update({
                    "recovery": "superseded_by_current_stage_state",
                    "superseded_stage_status": "completed",
                    "superseded_by_survey_ref": run["survey_ref"],
                })
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "reuse_completed_exploratory_survey_after_quota_recovery",
            "stage_id": stage_id,
            "topic_id": topic_id,
            "topic_cycle": topic_cycle,
            "source_attempt": attempt.get("attempt_number"),
            "survey_ref": run["survey_ref"],
            "assessment_ref": run["assessment_ref"],
            "deferred_request_ids": [item.get("id") for item in deferred],
            "next_action": "continue to experiment; reopen literature only for a concrete evidence need",
        })
        return True

    @staticmethod
    def _is_openalex_provider_cooldown(value):
        """Recognize an OpenAlex quota fence without matching model failures."""
        if isinstance(value, dict):
            rate_limit = value.get("rate_limit")
            if (isinstance(rate_limit, dict)
                    and rate_limit.get("provider") == "openalex"
                    and rate_limit.get("status_code") == 429):
                return True
            return any(ComposerRunner._is_openalex_provider_cooldown(value.get(key))
                       for key in ("reason", "error", "message", "provider_error", "failure"))
        text = str(value or "").casefold()
        return (
            "openalex" in text
            and any(token in text for token in ("quota", "rate", "cooldown", "paused", "reset"))
        )

    @staticmethod
    def _survey_has_crossref_identity(stage):
        """Check the immutable survey descriptor for a safe metadata fallback."""
        if not isinstance(stage, dict) or stage.get("kind") != "survey":
            return False
        try:
            descriptor = json.loads(Path(stage["config_path"]).read_text())
        except (OSError, TypeError, ValueError, KeyError):
            return False
        survey = descriptor.get("survey") if isinstance(descriptor, dict) else None
        identity = survey.get("identity") if isinstance(survey, dict) else None
        return (
            isinstance(survey, dict)
            and survey.get("bibliography_fallback", "crossref_metadata") == "disabled"
            and isinstance(identity, dict)
            and identity.get("adapter") == "crossref"
        )

    def _admit_survey_provider_fallback(self, stage, error=None):
        """Open a bounded Crossref continuation for an exhausted OpenAlex quota."""
        if not self._survey_has_crossref_identity(stage):
            return False
        stage_id = stage["id"]
        record = self.stage_records.get(stage_id, {})
        schedule = self.retry_schedule.get(stage_id, {})
        if self._stage_releases_dependencies(record, stage_kind=stage.get("kind")):
            return False
        candidates = [error, record.get("error"), schedule.get("error")]
        if not any(self._is_openalex_provider_cooldown(item) for item in candidates):
            return False
        context = deepcopy(self.context.get(stage_id, {}))
        previous = context.get("provider_fallback")
        if (isinstance(previous, dict)
                and previous.get("mode") == "crossref_metadata"):
            # The next attempt must prove that the admitted route actually
            # changed the runner input.  Re-admitting the same fallback on a
            # second OpenAlex error would turn a miswired recovery into a hot
            # retry loop instead of exposing the failed route transition.
            return False
        context["provider_fallback"] = {
            "status": "admitted",
            "mode": "crossref_metadata",
            "source_provider": "openalex",
            "reason": "OpenAlex daily quota/cooldown would otherwise park the survey until reset",
            "cycle": self.continuation_cycles,
            "preserve_openalex_evidence": True,
        }
        self.context[stage_id] = context
        self.retry_schedule.pop(stage_id, None)
        record = deepcopy(record) if isinstance(record, dict) else {"kind": "survey"}
        record["status"] = "retrying"
        record["provider_fallback"] = "crossref_metadata"
        self.stage_records[stage_id] = record
        if not (isinstance(previous, dict) and previous.get("mode") == "crossref_metadata"):
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "provider_fallback_admitted",
                "stage_id": stage_id,
                "from": "openalex",
                "to": "crossref_metadata",
                "scope": "bounded survey recovery; OpenAlex captures remain authoritative when available",
                "next_condition": "complete the narrow metadata survey and retain degraded evidence gaps",
            })
        return True

    def _resume_survey_provider_fallback(self, by_id):
        """Reopen a paused survey immediately when its cooldown has a safe fallback."""
        for stage in self.workflow.get("stages", []):
            if stage.get("kind") != "survey":
                continue
            if self._admit_survey_provider_fallback(stage):
                return True
        return False

    def _invalidate_legacy_provider_retry_schedules(self, by_id):
        """Re-evaluate route-agnostic specialist cooldowns after a resume.

        Older Composer checkpoints encoded a generic ``specialist provider is
        cooling down`` error as a stage retry with a potentially day-long
        ``not_before_epoch``.  That representation predates route-scoped
        cooldowns and can preserve a stale pool-wide fence even when another
        model route is available.  Remove only that unscoped specialist
        schedule; the next attempt will load the current route cooldown
        records and either select a healthy route or create a fresh, bounded
        schedule from the current provider state.
        """
        invalidated = []
        for stage_id, schedule in list(self.retry_schedule.items()):
            if not isinstance(schedule, dict):
                continue
            error_text = str(schedule.get("error") or "").casefold()
            if "specialist provider is cooling down" not in error_text:
                continue
            if any(isinstance(schedule.get(key), str) and schedule[key].strip()
                   for key in ("route_id", "cooldown_key")):
                continue
            stage = by_id.get(stage_id)
            if not isinstance(stage, dict) or stage.get("kind") == "survey":
                # Survey/OpenAlex cooldowns have a separate fallback path and
                # must not be confused with specialist model routing.
                continue
            self.retry_schedule.pop(stage_id, None)
            record = self.stage_records.get(stage_id)
            if isinstance(record, dict) and record.get("status") == "paused":
                record["status"] = "retrying"
                record["recovery_admitted"] = True
                record["legacy_retry_schedule_invalidated"] = True
            invalidated.append({
                "stage_id": stage_id,
                "failed_attempt_number": schedule.get("failed_attempt_number"),
                "next_attempt_number": schedule.get("next_attempt_number"),
                "stale_delay_seconds": schedule.get("delay_seconds"),
                "reason": "legacy route-agnostic specialist cooldown schedule",
            })
        if invalidated:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "invalidate_legacy_provider_retry_schedules",
                "schedules": invalidated,
                "next_condition": (
                    "re-dispatch once through the current route-scoped cooldown map; "
                    "do not sleep on a legacy pool-wide fence"
                ),
            })
        return invalidated

    @staticmethod
    def _apply_stage_quota(config, stage):
        """Pass the declared model-call ceiling into ExecutionRuntime."""
        quota = stage.get("quota") if isinstance(stage, dict) else None
        if not isinstance(quota, dict) or not isinstance(config, dict) or "limits" not in config:
            return config
        limits = config.setdefault("limits", {})
        current = limits.get("max_model_calls")
        limits["max_model_calls"] = (
            min(current, quota["max_model_calls"])
            if type(current) is int else quota["max_model_calls"]
        )
        return config

    def _stage_model_config(self, stage, model):
        """Give every producer and reviewer the same durable stage allowance."""
        if not isinstance(model, dict) or not isinstance(stage, dict):
            return model
        owner_id = stage.get("_model_budget_owner_stage_id")
        if owner_id is not None:
            owner = next((item for item in self.workflow["stages"]
                          if item["id"] == owner_id), None)
            if owner is None or owner.get("quota") != stage.get("quota"):
                raise ValidationError("auxiliary stage has no matching admitted model-budget owner")
            return self._stage_model_config(owner, model)
        quota = stage.get("quota")
        if not isinstance(quota, dict):
            return model
        limit = quota["max_model_calls"]
        scope_cycle = (self.continuation_cycles
                       if stage["id"] in self.reopened_stage_ids else 0)
        key = f"stage:{stage['id']}:cycle:{scope_cycle}"
        path = self.root / "state" / "stage-model-call-budget.sqlite"
        scope = {"model_call_budget_path": str(path.resolve()),
                 "model_call_budget_key": key, "model_call_budget_limit": limit,
                 "model_token_budget_limits": {"input_tokens": quota["max_input_tokens"],
                                               "output_tokens": quota["max_output_tokens"]}}
        contributions = self._legacy_stage_model_invoices(stage["id"], scope)
        self._restore_legacy_stage_model_budget(scope, contributions)
        floor = math.ceil(self._stage_usage(stage["id"])["model_calls"])
        with closing(sqlite3.connect(path)) as connection:
            connection.execute("CREATE TABLE IF NOT EXISTS model_call_budgets "
                               "(budget_key TEXT PRIMARY KEY, max_calls INTEGER NOT NULL, "
                               "used_calls INTEGER NOT NULL)")
            row = connection.execute("SELECT max_calls FROM model_call_budgets WHERE budget_key=?",
                                     (key,)).fetchone()
            if row is not None and row[0] != limit:
                raise ValidationError("persisted stage model-call limit changed")
            connection.execute("INSERT INTO model_call_budgets VALUES (?, ?, ?) "
                               "ON CONFLICT(budget_key) DO UPDATE SET "
                               "used_calls=MAX(used_calls, excluded.used_calls)", (key, limit, floor))
            connection.commit()
        register_model_token_budget(scope, self._stage_usage(stage["id"]))
        configured = deepcopy(model)
        configured.setdefault("model_call_budget_scopes", []).append(scope)
        return configured

    def _stage_model_delegation(self, stage):
        if not isinstance(stage.get("quota"), dict):
            return None
        scope = self._stage_model_config(stage, {})["model_call_budget_scopes"][0]
        path = scope["model_call_budget_path"]
        key = scope["model_call_budget_key"]
        prefix = f"stage:{stage['id']}:cycle:"
        cycle = int(key.removeprefix(prefix))
        with closing(sqlite3.connect(Path(path).as_uri() + "?mode=ro", uri=True)) as connection:
            used = connection.execute("SELECT used_calls FROM model_call_budgets WHERE budget_key=?",
                                      (key,)).fetchone()[0]
            retired = [{**scope, "model_call_budget_key": prior_key}
                       for prior_key, limit in connection.execute(
                           "SELECT budget_key, max_calls FROM model_call_budgets")
                       if prior_key.startswith(prefix) and prior_key.removeprefix(prefix).isdigit()
                       and int(prior_key.removeprefix(prefix)) < cycle
                       and limit == scope["model_call_budget_limit"]]
        return {"scope": scope, "used_calls": used, "superseded_scopes": retired}

    @staticmethod
    def _stage_releases_dependencies(record, *, stage_kind=None):
        """Return whether a stage is safe to expose to dependent stages."""
        if not isinstance(record, dict):
            return False
        status = record.get("status")
        if status in {"completed", "accepted"}:
            return True
        if status != "candidate_needs_review":
            return False
        # A paper candidate is never a dependency release.  Exploratory
        # argument work may be useful before all scientific debt is cleared,
        # but publication must remain behind an explicit evidence closure.
        # This is deliberately independent of ``composer_decision`` so a
        # forward-first handoff cannot turn a draft into a release input.
        if stage_kind == "paper":
            return False
        # In the autonomous-lab policy, this is an explicit Composer handoff,
        # not a release approval by the deterministic harness.  The candidate
        # remains visibly provisional and repairable, but it is dependency-
        # releasable once the Composer has recorded this decision.
        if record.get("composer_decision") == "advance_with_findings":
            return True
        if record.get("release_blocking") is True:
            return False
        debt = record.get("failure_debt")
        return not (isinstance(debt, dict) and debt.get("release_blocking") is True)

    def _paper_release_blockers(self, paper_stage, by_id):
        """Return unresolved scientific ancestors that fence paper release.

        The scheduler may let an adaptive Composer inspect provisional work in
        ``argument``.  A paper is a different boundary: every ancestor must
        have an accepted/completed scientific packet with no active verifier,
        evidence, or backfill debt.  Keep this check on the Composer side so
        it applies equally to a fresh run and a restored checkpoint.
        """
        if not isinstance(paper_stage, dict) or paper_stage.get("kind") != "paper":
            return []
        pending = list(paper_stage.get("depends_on", []))
        ancestor_ids = set()
        while pending:
            stage_id = pending.pop()
            if stage_id in ancestor_ids or stage_id not in by_id:
                continue
            ancestor_ids.add(stage_id)
            pending.extend(by_id[stage_id].get("depends_on", []))

        blockers = []
        workflow_order = [
            stage.get("id") for stage in self.workflow.get("stages", [])
            if isinstance(stage, dict) and stage.get("id") in ancestor_ids
        ]
        survey_ancestors = [
            stage_id for stage_id in workflow_order
            if by_id[stage_id].get("kind") == "survey"
        ]
        for stage_id in workflow_order:
            stage = by_id[stage_id]
            record = self.stage_records.get(stage_id, {})
            context = self.context.get(stage_id, {})
            if not isinstance(record, dict):
                record = {}
            if not isinstance(context, dict):
                context = {}
            record_status = record.get("status")
            context_status = context.get("status")
            specialist_verifier = context.get("specialist_verifier")
            if not isinstance(specialist_verifier, dict):
                specialist_verifier = {}
            reasons = []

            if record_status in STAGE_HOLD_STATUSES or context_status in STAGE_HOLD_STATUSES:
                reasons.append("scientific_hold")
            if (record_status == "candidate_needs_review"
                    or context_status == "candidate_needs_review"):
                reasons.append("provisional_candidate")
            if (record.get("verifier_outcome") == "hold"
                    or context.get("verifier_outcome") == "hold"
                    or specialist_verifier.get("verdict") == "hold"
                    or specialist_verifier.get("decision") == "hold"):
                reasons.append("verifier_hold")
            if (record.get("release_blocking") is True
                    or context.get("release_blocking") is True):
                reasons.append("release_blocking")
            debt = record.get("failure_debt")
            context_debt = context.get("failure_debt")
            if (isinstance(debt, dict) and debt.get("release_blocking") is True
                    or isinstance(context_debt, dict)
                    and context_debt.get("release_blocking") is True):
                reasons.append("failure_debt")
            if (record.get("backfill_required") is True
                    or context.get("backfill_required") is True
                    or record.get("progression_state") in {"deferred", "advanced_with_findings"}
                    or context.get("progression_state") in {"deferred", "advanced_with_findings"}):
                reasons.append("backfill_required")

            kind = stage.get("kind")
            if kind == "topic_discovery" and (
                    context.get("admission_state") == "provisional_for_survey"
                    or record.get("admission_state") == "provisional_for_survey"):
                # A topic is intentionally provisional at the topic -> survey
                # boundary.  Once an ancestor survey has produced a current,
                # experiment-eligible assessment, that provisional label is
                # resolved for the paper branch; otherwise the survey (or the
                # missing survey) remains the repair target.
                # If a survey ancestor exists but has not resolved the topic,
                # its own evidence gate is the repair target.  Do not pivot
                # the topic merely because the first survey pass is thin.
                if not survey_ancestors:
                    reasons.append("provisional_topic")
            if kind == "survey":
                effective_status = context_status or record_status
                bounded_pilot = (
                    self._allows_provisional_progress()
                    and context.get("topic_admission") == "exploratory_pilot"
                    and context.get("gap_state") == "insufficient_evidence"
                    and context.get("survey_current") is True
                    and context.get("assessment_current") is True
                )
                if (context.get("topic_admission") in {
                        "exploratory_pilot", "expand_literature_before_refine",
                        "refine_before_experiment"} and not bounded_pilot):
                    reasons.append("survey_not_experiment_eligible")
                if (context.get("gap_state") in {"insufficient_evidence", "refuted_by_prior_work"}
                        and not bounded_pilot):
                    reasons.append("survey_gap_unresolved")
                if context.get("survey_current") is False or context.get("assessment_current") is False:
                    reasons.append("survey_assessment_not_current")
                if effective_status in {"completed", "accepted"}:
                    if context.get("gap_state") != "eligible_for_experiment" and not bounded_pilot:
                        reasons.append("survey_not_experiment_eligible")
                    if (context.get("survey_current") is not True
                            or context.get("assessment_current") is not True):
                        reasons.append("survey_assessment_not_current")
            if kind == "experiment" and context.get("results_status") == "not_executed":
                reasons.append("experiment_not_executed")

            if reasons:
                blockers.append({
                    "stage_id": stage_id,
                    "kind": kind,
                    "status": context_status or record_status or "pending",
                    "reasons": list(dict.fromkeys(reasons)),
                })
        requirements = self._active_maturity_requirements(paper_stage)
        resolved = set()
        assessment_stage = next((by_id[key] for key in reversed(workflow_order)
                                 if by_id[key].get("kind") == "interpretation"), None)
        for stage_id in workflow_order:
            context = self.context.get(stage_id, {})
            package = context.get("interpretation", {}) if isinstance(context, dict) else {}
            interpretation = package.get("interpretation", {}) if isinstance(package, dict) else {}
            assessments = interpretation.get("requirement_assessments", []) if isinstance(interpretation, dict) else []
            resolved.update(item.get("requirement_id") for item in assessments
                            if isinstance(item, dict) and item.get("disposition") == "resolved"
                            and item.get("evidence_ids"))
        if {item["id"] for item in requirements} - resolved:
            target = assessment_stage or by_id[workflow_order[-1]] if workflow_order else paper_stage
            existing = next((item for item in blockers if item["stage_id"] == target["id"]), None)
            if existing is None:
                blockers.append({"stage_id": target["id"], "kind": target["kind"],
                                 "status": self.context.get(target["id"], {}).get("status", "pending"),
                                 "reasons": ["maturity_requirements_unresolved"]})
            else:
                existing["reasons"].append("maturity_requirements_unresolved")
        return blockers

    def _active_maturity_requirements(self, target_stage):
        from scisaurus.runtime.evidence import maturity_requirement_id
        requirements = []
        by_id = {item["id"]: item for item in self.workflow.get("stages", [])}
        ancestors = set()
        pending = [target_stage["id"]]
        while pending:
            stage_id = pending.pop()
            if stage_id in ancestors or stage_id not in by_id:
                continue
            ancestors.add(stage_id)
            pending.extend(by_id[stage_id].get("depends_on", []))
        for stage in self.workflow.get("stages", []):
            if stage["id"] not in ancestors:
                continue
            context = self.context.get(stage["id"], {})
            if not isinstance(context, dict):
                continue
            if stage.get("kind") == "topic_discovery":
                scope = self._topic_maturity_requirement_scope(context.get("topic"), context)
                values = scope["active"]
            elif stage.get("kind") == "survey":
                values = context.get("carried_maturity_requirements", [])
            else:
                continue
            for item in values if isinstance(values, list) else []:
                if isinstance(item, str) and item.strip() and item not in requirements:
                    requirements.append(item)
        return [{"id": maturity_requirement_id(item), "requirement": item} for item in requirements]

    def _ensure_paper_gate_repair_requests(self, blockers, *, synthesize=True):
        """Create one scoped repair order without discarding the current branch."""
        repairs = []
        for blocker in blockers[:1]:
            stage_id = blocker.get("stage_id") if isinstance(blocker, dict) else None
            if not isinstance(stage_id, str):
                continue
            context = self.context.get(stage_id, {})
            if not isinstance(context, dict):
                context = {}
            existing = []
            for key in ("research_expansion_requests", "research_requests",
                        "deferred_research_requests"):
                value = context.get(key)
                if isinstance(value, list):
                    existing.extend(item for item in value if isinstance(item, dict))
            unattempted = [
                item for item in existing
                if self._research_request_signature(item)
                not in self._attempted_request_signatures
            ]
            if unattempted:
                repairs.extend(deepcopy(unattempted))
                continue
            if not synthesize:
                continue

            # Candidate packets do not always emit a typed work order.  Reuse
            # the stage's deterministic recovery strategy, but present the
            # candidate as a hold to that helper so a repair is generated.
            repair_context = deepcopy(context)
            repair_context["status"] = "research_expansion_required"
            request = self._autonomous_recovery_request(stage_id, repair_context)
            if not isinstance(request, dict):
                continue
            request["repair_policy"] = "preserve_branch_before_rejection"
            request["preserve_artifacts"] = True
            request["source_blocker"] = {
                "stage_id": stage_id,
                "reasons": deepcopy(blocker.get("reasons", [])),
            }
            context.setdefault("research_requests", []).append(request)
            context["repair_policy"] = "preserve_branch_before_rejection"
            context["repair_target_stage_id"] = stage_id
            self.context[stage_id] = context
            repairs.append(deepcopy(request))
        return repairs

    def _refresh_paper_release_gate(self, completed, by_id, release_blocked_stage_ids):
        """Allow provisional drafting while keeping unresolved science unreleasable."""
        changed = False
        self._paper_gate_repair_requests = []
        # A provisional manuscript is a work product for review, not scientific
        # release. An unresolved survey or reviewer hold should travel with the
        # draft as explicit debt; only a missing admitted question or an
        # unexecuted experiment makes an empirical draft unsupported at source.
        hard_draft_blockers = {"provisional_topic", "experiment_not_executed"}
        for paper_stage in self.workflow.get("stages", []):
            if paper_stage.get("kind") != "paper":
                continue
            paper_id = paper_stage["id"]
            # A paper only becomes schedulable after its direct dependencies
            # are complete.  Once that frontier is reached, evaluate the full
            # transitive scientific closure rather than only the last stage.
            if not set(paper_stage.get("depends_on", [])).issubset(completed):
                continue
            blockers = self._paper_release_blockers(paper_stage, by_id)
            record = deepcopy(self.stage_records.get(paper_id, {}))
            gate = record.get("release_gate") if isinstance(record, dict) else None
            gate_is_ours = isinstance(gate, dict) and gate.get("kind") == "upstream_scientific_hold"
            if blockers:
                hard_blocked = any(
                    hard_draft_blockers.intersection(item.get("reasons", []))
                    for item in blockers if isinstance(item, dict)
                )
                unstarted_paper = (
                    record.get("attempt_count", 0) == 0
                    and not record.get("attempts")
                    and not record.get("output_path")
                )
                if (not hard_blocked and self._allows_provisional_progress()
                        and unstarted_paper):
                    next_draft_gate = {
                        "kind": "upstream_scientific_candidate",
                        "release_blocking": True,
                        "blockers": blockers,
                    }
                    if (record.get("draft_gate") != next_draft_gate
                            or record.get("status") != "pending"
                            or record.get("release_blocking") is True):
                        record.update({
                            "kind": "paper",
                            "status": "pending",
                            "release_blocking": False,
                            "draft_gate": next_draft_gate,
                        })
                        if gate_is_ours:
                            record.pop("release_gate", None)
                            record.pop("error", None)
                        self.stage_records[paper_id] = record
                        self.department_activity.append({
                            "cycle": self.continuation_cycles,
                            "action": "paper_provisional_draft_admitted",
                            "stage_id": paper_id,
                            "blockers": blockers,
                            "next_action": (
                                "compose and review a provisional manuscript; retain all upstream "
                                "findings and block final release until their debt is resolved"
                            ),
                        })
                        changed = True
                    completed.discard(paper_id)
                    release_blocked_stage_ids.discard(paper_id)
                    continue

                repairs = self._ensure_paper_gate_repair_requests(
                    blockers, synthesize=hard_blocked)
                self._paper_gate_repair_requests.extend(repairs)
                completed.discard(paper_id)
                release_blocked_stage_ids.add(paper_id)
                prior_status = (
                    gate.get("paper_status_before_gate")
                    if gate_is_ours and isinstance(gate.get("paper_status_before_gate"), str)
                    else record.get("status", "pending")
                )
                next_gate = {
                    "kind": "upstream_scientific_hold",
                    "stage_id": paper_id,
                    "release_blocking": True,
                    "paper_status_before_gate": prior_status,
                    "blockers": blockers,
                    "repair_requests": repairs,
                }
                if (record.get("status") != "candidate_needs_review"
                        or record.get("release_blocking") is not True
                        or gate != next_gate):
                    record.update({
                        "kind": "paper",
                        "status": "candidate_needs_review",
                        "release_blocking": True,
                        "draft_gate": None,
                        "release_gate": next_gate,
                        "error": "paper release blocked by unresolved upstream scientific evidence",
                    })
                    self.stage_records[paper_id] = record
                    self.blockers.append({
                        "stage_id": paper_id,
                        "reason": "paper release blocked by unresolved upstream scientific evidence",
                        "stop_reason": "upstream_scientific_hold",
                        "gating": True,
                        "release_blocking": True,
                        "dependencies": blockers,
                        "repair_requests": repairs,
                    })
                    self.department_activity.append({
                        "cycle": self.continuation_cycles,
                        "action": "paper_release_gate",
                        "stage_id": paper_id,
                        "blockers": blockers,
                        "repair_requests": repairs,
                        "next_action": "resolve upstream scientific debt before dispatching paper",
                    })
                    changed = True
                continue

            # Remove only a gate created by this method.  A real paper attempt
            # or a separately produced editorial candidate must remain intact.
            release_blocked_stage_ids.discard(paper_id)
            if gate_is_ours:
                prior_status = gate.get("paper_status_before_gate")
                for key in ("release_gate", "error", "release_blocking"):
                    record.pop(key, None)
                if record.get("attempt_count", 0) == 0 and not record.get("attempts"):
                    record["status"] = "pending"
                elif prior_status in {"completed", "accepted", "candidate_needs_review"}:
                    record["status"] = prior_status
                record.pop("draft_gate", None)
                self.stage_records[paper_id] = record
                changed = True
        return changed

    def _can_migrate_forward_candidate(self, record, context=None):
        """Identify an old forward-first candidate eligible for handoff."""
        if not isinstance(record, dict):
            return False
        if not self._forward_first():
            return False
        if record.get("status") != "candidate_needs_review":
            return False
        if record.get("forward_progress") is not True:
            return False
        if self._has_scoped_research_work(context):
            return False
        failure_class = None
        debt = record.get("failure_debt")
        if isinstance(debt, dict):
            failure_class = debt.get("failure_class")
        if failure_class in {"resource_fence", "operational_recovery", "unknown_external_outcome",
                             "process_interruption"}:
            return False
        text = " ".join(str(record.get(key) or "") for key in ("error", "reason"))
        lowered = text.casefold()
        return not any(token in lowered for token in (
            "provider cooldown", "quota", "deadline", "result_unknown",
            "unknown external outcome", "authentication",
        ))

    def _release_blocked_format_retry_allowed(self, stage, record):
        """Allow one resume to consume a cached provider-format repair.

        A legacy or strict-policy candidate checkpoint may be release-blocking.  A bounded
        serialization failure is different: the scientific work may already
        be durable and the stage runner can resume its exact input-addressed
        cache without rediscovering the literature.  Permit only the known
        format/length classes and only while the workflow retry envelope has
        one attempt left; all scientific holds and environmental failures
        remain release-blocking.
        """
        if not isinstance(stage, dict) or not isinstance(record, dict):
            return False
        if record.get("status") != "candidate_needs_review" or record.get("release_blocking") is not True:
            return False
        attempts = record.get("attempt_count")
        max_attempts = self._retry_policy().get("max_attempts")
        if type(attempts) is not int or type(max_attempts) is not int:
            return False
        debt = record.get("failure_debt") if isinstance(record.get("failure_debt"), dict) else {}
        error = " ".join(str(value) for value in (record.get("error"), debt.get("error")) if value)
        lowered = error.casefold()
        aggregate_fallback = (
            stage.get("kind") == "survey"
            and (
                ("survey-review" in lowered and any(marker in lowered for marker in (
                    "valid json", "finish normally: length",
                )))
                or "review requires its reviewer's recorded model execution" in lowered
                or "deterministic survey review" in lowered
                or "attributeerror: 'bytes' object has no attribute 'get'" in lowered
            )
        )
        if attempts >= max_attempts and not aggregate_fallback:
            return False
        return any(marker in lowered for marker in (
            "model output must contain valid json",
            "model generation did not finish normally: length",
            "model response did not contain valid json",
            "review requires its reviewer's recorded model execution",
            "deterministic survey review",
            "attributeerror: 'bytes' object has no attribute 'get'",
        ))

    @staticmethod
    def _release_blocked_topic_contract_retry_allowed(stage, record):
        """Allow one resumed topic intake after a deterministic contract fix.

        A topic package that never crossed intake has no scientific artifact to
        release or reject.  When the durable debt identifies the known
        feasibility-input contract and the current runtime repairs that
        redundant label losslessly, the next resume may spend one fresh topic
        attempt.  This is intentionally narrower than a generic validation
        retry: external inputs are still rejected by the normal gate.
        """
        if not isinstance(stage, dict) or stage.get("kind") != "topic_discovery":
            return False
        if not isinstance(record, dict) or record.get("status") != "candidate_needs_review":
            return False
        if record.get("contract_recovery_admitted") is True:
            return False
        debt = record.get("failure_debt")
        if not isinstance(debt, dict) or debt.get("failure_class") != "mechanical_contract":
            return False
        error = " ".join(str(value) for value in (
            record.get("error"), debt.get("error"),
        ) if value).casefold()
        return "feasibility_plan.project_artifact must declare a project_artifact input" in error

    def _synchronize_paper_references(self, paper_config):
        """Project newly accepted survey sources into a continuation paper descriptor.

        A paper descriptor may have been prepared before the survey expanded.
        Keeping its original references is correct for an immutable first
        attempt, but it would make a continuation gate inspect stale coverage.
        This helper appends one reader-facing reference per newly captured
        source, preferring full text, while retaining every original key and
        evidence locator.  It never invents a DOI or authorship record.
        """
        try:
            from scisaurus.runtime.paper import load_paper_survey
            survey = load_paper_survey(paper_config,
                require_eligible=not self._allows_provisional_progress())
        except Exception:
            # The normal paper validator will report the precise dependency
            # problem.  Do not hide it behind a best-effort synchronization.
            raise
        control = ControlStore(paper_config["survey_project_dir"])
        try:
            store = ArtifactStore(control)
            works = {}
            rows = control._conn.execute(
                "SELECT logical_id, MAX(version) AS version FROM artifacts "
                "WHERE logical_id LIKE 'kb/works/%' GROUP BY logical_id"
            ).fetchall()
            for row in rows:
                record = store.get(f"artifact:{row['logical_id']}@{row['version']}")
                body = json.loads(store.read_body(record["body_hash"]))
                works[body.get("work_id")] = body
            identities = {}
            for ref, identity in survey.get("identities", {}).items():
                if isinstance(identity, dict) and identity.get("work_id"):
                    identities[identity["work_id"]] = identity
        finally:
            control.close()

        # Catalog-backed missions are a new scientific identity.  Their
        # references must be projected from the current survey rather than
        # appended to a descriptor inherited from a previous topic.
        if self.workflow.get("experiment_catalog"):
            paper_config["references"] = []
        existing_refs = paper_config.get("references", [])
        existing_source_refs = {item.get("source_ref") for item in existing_refs if isinstance(item, dict)}
        existing_keys = {item.get("key") for item in existing_refs if isinstance(item, dict)}
        # Keep the configured order stable while prioritizing full text for new
        # entries.  A bounded cap prevents a broad search from turning the
        # writer prompt into an accidental bibliography dump.
        sources = sorted(
            survey.get("sources", {}).items(),
            key=lambda pair: (pair[1].get("representation") != "full_text", pair[1].get("work_id", "")),
        )
        profile_floor = 0
        depth = paper_config.get("depth_profile")
        if isinstance(depth, dict):
            profile_floor = int(depth.get("min_references", 0))
        target = max(profile_floor, len(existing_refs))
        target = min(max(target, profile_floor + 10), 50) if profile_floor else min(max(target, 20), 50)
        for source_ref, source in sources:
            if len(paper_config["references"]) >= target and source.get("representation") != "full_text":
                break
            if source_ref in existing_source_refs:
                continue
            work_id = source.get("work_id")
            work = works.get(work_id, {})
            key = re.sub(r"[^a-z0-9_-]+", "-", f"oa_{str(work_id).casefold()}").strip("-")[:64]
            if not key or not key[0].isalpha():
                key = f"ref_{len(existing_keys)}"
            if key in existing_keys:
                key = f"oa_{str(work_id).casefold()}_{len(existing_keys)}"
            identity = identities.get(work_id, {})
            # DOI fields are only emitted when an independently reconciled
            # identity exists.  A catalog record alone remains a URL citation.
            doi = (identity.get("doi")
                   if identity.get("status") in {"verified", "verified_with_gaps"}
                   else None)
            authors = work.get("authors") or source.get("authors") or "Authors not supplied by OpenAlex"
            if isinstance(authors, list):
                authors = ", ".join(
                    item if isinstance(item, str) else str(item) for item in authors)
            paper_config["references"].append({
                "key": key,
                "title": work.get("title") or source.get("title") or f"OpenAlex work {work_id}",
                "authors": str(authors),
                "year": str(work.get("year") or "unknown"),
                "doi": doi,
                "url": source.get("url") or f"https://openalex.org/{work_id}",
                "source_ref": source_ref,
                **({"identity_ref": next((ref for ref, item in survey.get("identities", {}).items()
                                          if isinstance(item, dict) and item.get("work_id") == work_id), None)}
                   if doi else {}),
            })
            existing_source_refs.add(source_ref)
            existing_keys.add(key)
            if len(paper_config["references"]) >= target:
                # Continue only when the full-text floor still needs entries.
                full_text_count = sum(
                    survey.get("sources", {}).get(item.get("source_ref"), {}).get("representation") == "full_text"
                    for item in paper_config["references"]
                )
                full_text_floor = int(depth.get("min_full_text_references", 0)) if isinstance(depth, dict) else 0
                if full_text_count >= full_text_floor:
                    break
        return paper_config

    def _interpretation_binding_path(self, value):
        """Return a direct interpretation artifact for a bound package path.

        Stage outputs are often persisted as envelopes (status, usage, and the
        actual scientific interpretation).  The release validator consumes
        the inner interpretation object, so a path binding must project that
        shape explicitly instead of handing the envelope to the next stage.
        The projection is content-addressed and immutable within this
        Composer run.
        """
        if not isinstance(value, str):
            return value
        path = Path(value)
        if not path.is_absolute() or not path.is_file():
            return value
        try:
            payload = json.loads(path.read_text())
        except (OSError, ValueError) as exc:
            raise ValidationError(f"bound interpretation artifact is unreadable: {path}") from exc
        if isinstance(payload, dict) and isinstance(payload.get("interpretation"), dict):
            interpretation = payload["interpretation"]
            from scisaurus.runtime.scientific_interpretation import validate_interpretation
            validate_interpretation(interpretation)
            digest = hashlib.sha256(canonical_bytes(interpretation)).hexdigest()
            target = self.root / "output" / "bindings" / f"scientific-interpretation-{digest}.json"
            target.parent.mkdir(parents=True, exist_ok=True)
            if target.exists() and target.read_bytes() != canonical_bytes(interpretation):
                raise ValidationError("content-addressed interpretation binding was modified")
            if not target.exists():
                target.write_bytes(canonical_bytes(interpretation))
            return str(target.resolve())
        from scisaurus.runtime.scientific_interpretation import validate_interpretation
        validate_interpretation(payload)
        return value

    def _apply_bindings(self, payload, bindings):
        for binding in bindings:
            value = self._source_value(binding["source"])
            # A path reference to a JSON package is resolved to the package
            # body when it is bound into another stage's packet.
            if isinstance(value, str) and Path(value).is_file() and binding["target"].endswith("results_package"):
                try:
                    value = json.loads(Path(value).read_text())
                except (OSError, ValueError) as exc:
                    raise ValidationError(f"bound JSON package is unreadable: {value}") from exc
            _set_path(payload, binding["target"], value)
        return payload

    def _stage_task(self, stage):
        prior_record = self.stage_records.get(stage["id"], {})
        continuation_task = stage["id"] in self.reopened_stage_ids and self.continuation_cycles
        task_id = None if continuation_task else (
            prior_record.get("task_id") if isinstance(prior_record, dict) else None)
        if not isinstance(task_id, str) or not task_id:
            task_id = f"composer-{self.workflow['id']}-{stage['id']}"
            if continuation_task:
                task_id += f"-continuation-{self.continuation_cycles}"
        try:
            existing = self.tasks.get(task_id)
        except NotFoundError:
            existing = None
        if existing is not None:
            unresolved = self.control._conn.execute(
                "SELECT attempt_id, state FROM attempts WHERE task_id = ? "
                "AND state IN ('started', 'result_unknown') "
                "ORDER BY created_at DESC LIMIT 1",
                (task_id,),
            ).fetchone()
            if unresolved is not None:
                base_task_id = task_id
                seed = canonical_bytes({
                    "stage_id": stage["id"],
                    "cycle": self.continuation_cycles,
                    "prior_task_id": base_task_id,
                    "unresolved_attempt_id": unresolved["attempt_id"],
                    "unresolved_state": unresolved["state"],
                })
                recovery = hashlib.sha256(seed).hexdigest()[:12]
                generation = 0
                while True:
                    suffix = f"-recovery-{recovery}"
                    if generation:
                        suffix += f"-{generation}"
                    candidate_id = f"{base_task_id}{suffix}"
                    try:
                        candidate = self.tasks.get(candidate_id)
                    except NotFoundError:
                        task_id, existing = candidate_id, None
                        break
                    candidate_unresolved = self.control._conn.execute(
                        "SELECT 1 FROM attempts WHERE task_id = ? "
                        "AND state IN ('started', 'result_unknown') LIMIT 1",
                        (candidate_id,),
                    ).fetchone()
                    if (candidate_unresolved is None
                            and candidate["state"] in {"queued", "running", "blocked", "paused"}):
                        task_id, existing = candidate_id, candidate
                        break
                    generation += 1
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "recover_stage_task_with_unresolved_attempt",
                    "stage_id": stage["id"],
                    "prior_task_id": base_task_id,
                    "prior_attempt_id": unresolved["attempt_id"],
                    "prior_attempt_state": unresolved["state"],
                    "recovery_task_id": task_id,
                    "model_calls": 0,
                })
        if existing is not None:
            state = existing["state"]
            if state in {"blocked", "paused"}:
                try:
                    self.tasks.transition(
                        task_id, "queued", "command.composer", reason="scoped stage recovery"
                    )
                    return self.tasks.get(task_id)
                except StateError:
                    # A concurrent cleanup may have terminalized the task
                    # between the read and the transition. Fall through to a
                    # fresh generation rather than handing a stale row to
                    # start_attempt().
                    existing = self.tasks.get(task_id)
                    state = existing["state"]
            elif state in {"queued", "running"}:
                return self.tasks.get(task_id)
            else:
                # A continuation task is a new bounded work order. Its old
                # aggregate can legitimately be stale/failed/completed after
                # a watchdog kill or a crash at the stage boundary. Reusing
                # that row makes the next start_attempt fail with
                # "not dispatchable (state=stale)" and turns a recoverable
                # run into a terminal Composer blocker.
                seed = canonical_bytes({
                    "stage_id": stage["id"],
                    "cycle": self.continuation_cycles,
                    "prior_task_id": task_id,
                    "prior_state": state,
                    "attempt_id": prior_record.get("attempt_id")
                    if isinstance(prior_record, dict) else None,
                })
                recovery = hashlib.sha256(seed).hexdigest()[:12]
                base_task_id = task_id
                generation = 0
                while True:
                    suffix = f"-recovery-{recovery}"
                    if generation:
                        suffix += f"-{generation}"
                    candidate_id = f"{base_task_id}{suffix}"
                    try:
                        candidate = self.tasks.get(candidate_id)
                    except NotFoundError:
                        task_id, existing = candidate_id, None
                        break
                    if candidate["state"] in {"queued", "running"}:
                        task_id, existing = candidate_id, candidate
                        break
                    generation += 1
        if existing is not None:
            return self.tasks.get(task_id)
        route = self.departments.stage_route(stage["kind"])
        self.tasks.create(task_id, "production", {
            "stage_id": stage["id"], "kind": stage["kind"], "objective": self.workflow["objective"],
            "depends_on": stage["depends_on"], "config_path": stage["config_path"],
            "department": route["department"], "role": route["role"],
            "owner_agent": route["chief"], "adversary_agent": route["adversary"],
            "required_role_ids": route["required_role_ids"],
            "required_agents": route["required_agents"],
            "verifier_agent": route["verifier_agent"],
            "role_quotas": route["role_quotas"],
            "assignment_policy": "bounded_on_demand_role_isolated",
        }, "command.composer")
        return self.tasks.admit(task_id, "command.composer")

    @staticmethod
    def _stage_assignment_fields(plan, result=None):
        """Project role dispatch evidence into a compact stage checkpoint."""
        if not isinstance(plan, dict):
            return {}
        fields = {
            "required_agents": deepcopy(plan.get("required_agents", [])),
            "active_agents": deepcopy(plan.get("active_agents", [])),
            "verifier_agent": plan.get("verifier_agent"),
            "chief_agent": plan.get("chief_agent"),
            "role_quotas": deepcopy(plan.get("role_quotas", {})),
            "assignment_plan_ref": plan.get("plan_ref"),
            "assignment_ids": deepcopy(plan.get("assignment_ids", [])),
            "assignment_task_ids": deepcopy(plan.get("task_ids", [])),
            "assignment_deadline_seconds": plan.get("deadline_seconds"),
        }
        if isinstance(result, dict):
            fields.update({
                "chief_synthesis_ref": result.get("chief_synthesis_ref"),
                "verifier_artifact_ref": result.get("verifier_artifact_ref"),
                "verifier_outcome": result.get("verifier_outcome"),
                "specialist_failure_scope": result.get("failure_scope"),
                "specialist_assignments": deepcopy(result.get("assignments", [])),
            })
        return fields

    @staticmethod
    def _retire_stage_assignment(fields):
        """Separate the last dispatch from roles that are still executing.

        Assignment plans are durable evidence, but their ``active_agents``
        projection is live state.  Keeping the dispatch list after a stage
        returns makes a completed or retrying stage look like it still owns
        worker slots.  Preserve the list for auditability under
        ``last_active_agents`` and expose an empty live list until the next
        admission installs a fresh plan.
        """
        retired = deepcopy(fields) if isinstance(fields, dict) else {}
        active = retired.get("active_agents")
        if isinstance(active, list) and active:
            retired["last_active_agents"] = deepcopy(active)
        retired["active_agents"] = []
        return retired

    @staticmethod
    def _active_stage_role_ids(stage, *, stage_context=None):
        """Select the smallest useful preflight pool for the stage.

        The organization manifest describes the complete bounded capability
        pool, but every role is not a reason to make a model call.  Survey's
        production runner already owns search, cataloging, source capture,
        identity checks, and fact verification. Keep one search-planning
        specialist for acquisition work; a restored gap-assessment-only scope
        has no search work, so its runner and independent stage verifier are
        sufficient without a redundant planning call.
        """
        if not isinstance(stage, dict):
            return None
        if stage.get("kind") == "survey":
            context = stage_context if isinstance(stage_context, dict) else {}
            if (
                context.get("review_status") == "survey_revalidation"
                and isinstance(context.get("resume_scopes"), list)
                and set(context["resume_scopes"]) <= {"focused_review", "integrated_review", "gap_assessment"}
            ) or (
                context.get("review_status") == "gap_assessment_resume"
                and context.get("survey_current") is True
                and context.get("assessment_current") is False
                and context.get("resume_scope") == "gap_assessment"
            ) or (
                context.get("review_status") == "survey_integrity_repair"
                and context.get("survey_ref")
                and context.get("resume_scope") == "integrated_review"
            ):
                return []
            return ["search-strategist"]
        return None

    def _specialist_model_config(self, stage, descriptor):
        """Load the model config used by a stage, when one is declared."""
        if not isinstance(descriptor, dict):
            return None
        model = descriptor.get("model")
        if isinstance(model, dict):
            configured = with_runtime_cooldown_fallback(model)
            return self._stage_model_config(stage, configured) if configured.get("base_url") and configured.get("model") else None
        model_path = descriptor.get("model_config_path")
        if not isinstance(model_path, str) or not model_path:
            return None
        path = Path(model_path)
        if not path.is_file():
            return None
        try:
            model = json.loads(path.read_text())
        except (OSError, ValueError, TypeError):
            return None
        configured = with_runtime_cooldown_fallback(model)
        return (self._stage_model_config(stage, configured) if isinstance(configured, dict)
                and configured.get("base_url") and configured.get("model") else None)

    @staticmethod
    def _specialist_provider_pools(descriptor):
        limits = descriptor.get("limits") if isinstance(descriptor, dict) else None
        pools = limits.get("provider_pools") if isinstance(limits, dict) else None
        return deepcopy(pools) if isinstance(pools, dict) else None

    def _specialist_file_ref(self, artifact):
        """Return the dashboard-safe object path for a Composer artifact."""
        body_hash = artifact.get("body_hash") if isinstance(artifact, dict) else None
        if not isinstance(body_hash, str) or len(body_hash) != 64:
            return None
        return f"composer::objects/sha256/{body_hash}"

    def _specialist_ancestor_contexts(self, stage):
        """Return the current dependency closure in nearest-first order.

        Specialist prompts must be built from the current stage result and its
        actual scientific ancestors.  Looking only at ``stage_result`` leaves
        interpretation/argument roles without the experiment package, while
        forwarding the whole Composer context breaks role isolation.  This
        helper keeps the lookup deterministic and lets the named projections
        below select only the fields a role is allowed to see.
        """
        by_id = {item.get("id"): item for item in self.workflow.get("stages", [])
                 if isinstance(item, dict) and isinstance(item.get("id"), str)}
        pending = list(stage.get("depends_on", [])) if isinstance(stage, dict) else []
        seen = set()
        contexts = []
        while pending:
            stage_id = pending.pop(0)
            if stage_id in seen or stage_id not in by_id:
                continue
            seen.add(stage_id)
            context = self.context.get(stage_id)
            if isinstance(context, dict):
                contexts.append(context)
            pending.extend(by_id[stage_id].get("depends_on", []))
        return contexts

    @staticmethod
    def _specialist_json_value(value):
        """Load a local JSON artifact when a stage context stores a path."""
        if isinstance(value, dict):
            return deepcopy(value)
        if not isinstance(value, str):
            return value
        path = Path(value)
        if not path.is_file():
            return value
        try:
            loaded = json.loads(path.read_text())
        except (OSError, ValueError, TypeError):
            return value
        return deepcopy(loaded)

    @staticmethod
    def _specialist_result_spine(results):
        """Expose the reproducible result spine without raw execution bulk."""
        results = ComposerRunner._specialist_json_value(results)
        if not isinstance(results, dict):
            return results
        selected = {}
        for key in (
                "schema_version", "id", "revision", "study_type", "question",
                "hypothesis", "procedures", "metrics", "findings", "limitations",
                "assets", "validation"):
            if key in results:
                selected[key] = deepcopy(results[key])
        return selected or deepcopy(results)

    @staticmethod
    def _specialist_argument_seed(results, interpretation):
        """Build a provisional claim/evidence seed from completed research outputs."""
        results = results if isinstance(results, dict) else {}
        interpretation = interpretation if isinstance(interpretation, dict) else {}
        research_question = (interpretation.get("research_question")
                             or results.get("question"))
        patterns = interpretation.get("result_patterns")
        claims = []
        if isinstance(patterns, list):
            for pattern in patterns:
                if not isinstance(pattern, dict):
                    continue
                claim = deepcopy(pattern)
                evidence_ids = []
                for key in ("evidence_ids", "supporting_evidence",
                            "contradicting_evidence"):
                    refs = pattern.get(key)
                    if isinstance(refs, list):
                        evidence_ids.extend(
                            item for item in refs
                            if isinstance(item, str) and item not in evidence_ids
                        )
                result_ref = pattern.get("result_ref")
                if isinstance(result_ref, str) and result_ref not in evidence_ids:
                    evidence_ids.append(result_ref)
                claim["evidence_ids"] = evidence_ids
                claim["claim_status"] = "provisional"
                claims.append(claim)
        if not claims:
            findings = results.get("findings")
            if isinstance(findings, list):
                for finding in findings:
                    if not isinstance(finding, dict):
                        continue
                    claim = deepcopy(finding)
                    evidence_ids = [finding["id"]] if isinstance(
                        finding.get("id"), str) else []
                    metric_ids = finding.get("metric_ids")
                    if isinstance(metric_ids, list):
                        evidence_ids.extend(
                            item for item in metric_ids
                            if isinstance(item, str) and item not in evidence_ids
                        )
                    claim["evidence_ids"] = evidence_ids
                    claim["claim_status"] = "observed"
                    claims.append(claim)
        mechanisms = interpretation.get("competing_explanations")
        mechanisms = deepcopy(mechanisms) if isinstance(mechanisms, list) else []
        tests = interpretation.get("discriminating_experiments")
        tests = deepcopy(tests) if isinstance(tests, list) else []
        limitations = []
        for source in (results.get("limitations"), interpretation.get("limitations")):
            if not isinstance(source, list):
                continue
            for item in source:
                if item not in limitations:
                    limitations.append(deepcopy(item))
        evidence_gaps = interpretation.get("evidence_gaps")
        evidence_gaps = deepcopy(evidence_gaps) if isinstance(evidence_gaps, list) else []
        requested_actions = interpretation.get("requested_actions")
        requested_actions = (
            deepcopy(requested_actions) if isinstance(requested_actions, list) else [])
        assets = results.get("assets")
        assets = [deepcopy(item) for item in assets if isinstance(item, dict)] \
            if isinstance(assets, list) else []
        plan = {
            "schema_version": "argument-plan-seed-1",
            "status": "provisional_seed",
            "research_question": research_question,
            "candidate_claims": deepcopy(claims),
            "candidate_mechanisms": deepcopy(mechanisms),
            "discriminating_experiments": deepcopy(tests),
            "current_interpretation": deepcopy(interpretation.get("conclusion")),
            "limitations": deepcopy(limitations),
            "evidence_gaps": deepcopy(evidence_gaps),
            "requested_actions": deepcopy(requested_actions),
            "available_result_assets": assets,
        }
        return {
            "research_question": research_question,
            "claims": claims,
            "mechanism": mechanisms,
            "limitations": limitations,
            "argument_plan": plan,
        }

    @staticmethod
    def _specialist_interpretation_value(value):
        value = ComposerRunner._specialist_json_value(value)
        if not isinstance(value, dict):
            return value
        if isinstance(value.get("interpretation"), dict):
            value = value["interpretation"]
        return {
            key: deepcopy(value[key]) for key in (
                "schema_version", "research_question", "result_patterns",
                "competing_explanations", "prioritization", "conclusion",
                "discriminating_experiments", "limitations", "evidence_gaps",
                "requested_actions") if key in value
        }

    @staticmethod
    def _specialist_argument_value(value):
        value = ComposerRunner._specialist_json_value(value)
        if not isinstance(value, dict):
            return value
        if isinstance(value.get("argument_package"), dict):
            value = value["argument_package"]
        if isinstance(value.get("argument"), dict):
            value = value["argument"]
        return {
            key: deepcopy(value[key]) for key in (
                "schema_version", "research_question", "observed_patterns",
                "hypotheses", "primary_argument", "limitations",
                "discriminating_experiments", "figure_plan", "claims")
            if key in value
        }

    def _specialist_stage_result_projection(self, stage, stage_result):
        """Expose named scientific inputs from a completed stage result.

        Topic discovery is the graph frontier: it has no upstream context from
        which its seed plan, candidate portfolio, or source records could be
        projected.  Its specialists therefore review the generated result,
        while later stages retain the normal pre-execution planning packet.
        The aliases below keep role contracts stable without forwarding the
        whole result into any one prompt.
        """
        if not isinstance(stage_result, dict):
            return {}
        projected = deepcopy(stage_result)
        product = stage_result.get("review_product")
        if isinstance(product, dict):
            plan, draft = product["plan"], product["draft"]
            sources = product["sources"]
            journal = next(v for v in plan["venues"] if v["journal_id"] == plan["journal_id"])
            projected.update({
                "argument": {key: plan[key] for key in ("thesis", "insights", "outline", "benchmarks")},
                "evidence": sources, "evidence_map": product["unit_sources"],
                "paper_contract": {"article_type": "critical_review", "coverage_limits": plan["coverage_limits"], "venue": journal},
                "style_constraints": "Critical synthesis; distinguish reported findings, hypotheses, and uncertainty. No original experiments or systematic-coverage claim.",
                "draft": draft, "manuscript": draft, "manuscript_source": draft,
                "review_package": product["peer_reviews"], "journal_contract": journal,
                "source_coverage": product["coverage"], "claims": plan["insights"],
                "references": [s["work"] for s in sources if s["kind"] == "article"],
                "bibliography": [s["work"] for s in sources if s["kind"] == "article"],
                "citations": product["unit_sources"], "figure_manifest": product["render"],
            })
            return projected
        if stage.get("kind") == "interpretation":
            ancestors = self._specialist_ancestor_contexts(stage)
            experiment = next((item for item in ancestors
                               if item.get("kind") == "experiment"), {})
            results = self._specialist_result_spine(
                experiment.get("results_package") or stage_result.get("results_package"))
            interpretation = self._specialist_interpretation_value(
                stage_result.get("interpretation"))
            question = (interpretation.get("research_question")
                        if isinstance(interpretation, dict) else None)
            if not question and isinstance(results, dict):
                question = results.get("question")
            alternatives = (interpretation.get("competing_explanations", [])
                            if isinstance(interpretation, dict) else [])
            projected.update({
                "research_question": question,
                "results": results,
                "evidence": results,
                "interpretation": interpretation,
                "mechanism": deepcopy(alternatives),
                "alternative_hypotheses": deepcopy(alternatives),
                "limitations": deepcopy(results.get("limitations", [])
                                         if isinstance(results, dict) else []),
            })
            return projected

        if stage.get("kind") == "argument":
            ancestors = self._specialist_ancestor_contexts(stage)
            experiment = next((item for item in ancestors
                               if item.get("kind") == "experiment"), {})
            interpretation_context = next((item for item in ancestors
                                           if item.get("kind") == "interpretation"), {})
            results = self._specialist_result_spine(experiment.get("results_package"))
            interpretation = self._specialist_interpretation_value(
                interpretation_context.get("interpretation"))
            argument_package = stage_result.get("argument_package")
            if not isinstance(argument_package, dict):
                # A rejected adjudication is carried on the runner exception
                # rather than in a normal stage result.  The failure review
                # envelope preserves these fields; project them through the
                # same bounded path as a successful argument package.
                if isinstance(stage_result.get("research_argument"), dict):
                    argument_package = {
                        "argument": deepcopy(stage_result["research_argument"]),
                    }
                    if isinstance(stage_result.get("research_review"), dict):
                        argument_package["review"] = deepcopy(stage_result["research_review"])
            argument = self._specialist_argument_value(
                argument_package or stage_result.get("argument"))
            review = argument_package.get("review") if isinstance(argument_package, dict) else None
            if not isinstance(review, dict):
                review = stage_result.get("review")
            review = {
                key: deepcopy(review[key]) for key in (
                    "schema_version", "decision", "checks", "findings",
                    "required_repairs", "rationale") if isinstance(review, dict) and key in review
            }
            complete_argument_fields = {
                "research_question", "observed_patterns", "hypotheses",
                "primary_argument", "limitations", "discriminating_experiments",
                "figure_plan",
            }
            has_complete_argument = (
                isinstance(argument, dict)
                and complete_argument_fields.issubset(argument)
            )
            seed = self._specialist_argument_seed(results, interpretation)
            claims = []
            if has_complete_argument:
                claims.extend(deepcopy(argument.get("observed_patterns", [])))
                primary = argument.get("primary_argument")
                if isinstance(primary, dict):
                    claims.append(deepcopy(primary))
            else:
                claims = deepcopy(seed["claims"])
            evidence_records = []
            if isinstance(results, dict):
                for key in ("procedures", "metrics", "findings", "limitations", "assets"):
                    value = results.get(key)
                    if isinstance(value, list):
                        evidence_records.extend(deepcopy(value))
            if isinstance(interpretation, dict):
                evidence_records.extend(deepcopy(interpretation.get("result_patterns", [])))
            research_question = (
                argument.get("research_question") if has_complete_argument else None
            ) or seed["research_question"]
            argument_plan = argument if has_complete_argument else deepcopy(seed["argument_plan"])
            if isinstance(argument, dict) and not has_complete_argument:
                for key, value in argument.items():
                    if value not in (None, "", [], {}):
                        argument_plan.setdefault(key, deepcopy(value))
                argument_plan["partial_argument_candidate"] = deepcopy(argument)
            mechanisms = (argument.get("hypotheses", []) if has_complete_argument
                          else seed["mechanism"])
            limitations = (argument.get("limitations", []) if has_complete_argument
                           else seed["limitations"])
            projected.update({
                "research_question": research_question,
                "claims": claims,
                "results": results,
                "interpretation": interpretation,
                "review_findings": review,
                "argument_plan": argument_plan,
                "mechanism": deepcopy(mechanisms),
                "limitations": deepcopy(limitations),
                "evidence_records": evidence_records,
                "section_contract": {
                    "research_question": research_question,
                    "figure_plan": deepcopy(argument.get("figure_plan", [])
                                             if has_complete_argument else []),
                    "candidate_claim_ids": [
                        item.get("id") for item in claims
                        if isinstance(item, dict) and isinstance(item.get("id"), str)
                    ],
                    "available_result_assets": deepcopy(
                        argument_plan.get("available_result_assets", [])
                        if isinstance(argument_plan, dict) else []),
                    "status": ("accepted_argument" if has_complete_argument
                               else "provisional_seed"),
                },
                "style_constraints": (
                    "Report observations separately from mechanisms; keep unsupported explanations "
                    "provisional and bind every material claim to an evidence record."),
                "target_audience": "readers evaluating a bounded computational result",
            })
            return projected

        if stage.get("kind") == "paper":
            ancestors = self._specialist_ancestor_contexts(stage)
            argument_context = next((item for item in ancestors
                                     if item.get("kind") == "argument"), {})
            experiment = next((item for item in ancestors
                               if item.get("kind") == "experiment"), {})
            argument = self._specialist_argument_value(
                argument_context.get("argument_package") or argument_context.get("argument"))
            results = self._specialist_result_spine(experiment.get("results_package"))
            projected.update({
                "argument": argument,
                "claims": deepcopy(argument.get("observed_patterns", [])
                                     if isinstance(argument, dict) else []),
                "evidence": results,
                "paper_contract": {
                    "stage_id": stage.get("id"),
                    "release_status": stage_result.get("release_status"),
                    "output_path": stage_result.get("output_path"),
                },
                "style_constraints": (
                    "Preserve the accepted evidence boundary, distinguish results from discussion, "
                    "and expose unresolved reviewer findings."),
                "review_package": deepcopy(stage_result.get("review_package", {})),
                "draft": deepcopy(stage_result.get("draft")) if "draft" in stage_result else None,
                "manuscript": deepcopy(stage_result.get("manuscript"))
                    if "manuscript" in stage_result else None,
            })
            return projected

        if stage.get("kind") != "topic_discovery":
            return projected

        # Recovery metadata is not scientific evidence. Keep the producer's
        # original project directory for exact packet/cache identity, while
        # excluding only the new outer-recovery annotation.
        projected.pop("producer_recovery", None)

        frontier_plan = stage_result.get("frontier_seed_plan")
        seeds = (frontier_plan.get("seeds", [])
                 if isinstance(frontier_plan, dict) else [])
        recent_papers = stage_result.get("recent_papers")
        if not isinstance(recent_papers, list):
            recent_papers = []
        candidate_prior_work = stage_result.get("candidate_prior_work")
        if not isinstance(candidate_prior_work, list):
            candidate_prior_work = []
        topic = stage_result.get("topic")
        if not isinstance(topic, dict):
            topic = {}
        selected_seed_id = topic.get("frontier_seed_id")
        selected_domain = topic.get("domain")
        selected_seed_records = [
            deepcopy(item) for item in (candidate_prior_work or recent_papers)
            if isinstance(item, dict)
            and (
                selected_seed_id is None
                or item.get("frontier_seed_id") == selected_seed_id
                or (
                    item.get("frontier_seed_id") == "selected_direction"
                    and selected_domain
                    and item.get("frontier_domain") == selected_domain
                )
            )
        ]

        projected.update({
            "candidate_topics": deepcopy(stage_result.get("candidates", [])),
            "frontier_seeds": deepcopy(seeds),
            "scholarly_records": deepcopy(recent_papers),
            # The broad sample is useful for frontier scouting but is not
            # evidence for the selected direction. Keep both scopes named so
            # role projections and the verifier cannot mistake inspiration
            # records from other seeds for selected-topic support.
            "frontier_inspiration_records": deepcopy(recent_papers),
            "selected_seed_id": selected_seed_id,
            "selected_seed_records": selected_seed_records,
            "topic_history": self._topic_history_context(),
            "known_gaps": deepcopy(stage_result.get("proposed_gap", "")),
            "source_classes": sorted({
                item.get("source_class") for item in recent_papers
                if isinstance(item, dict) and isinstance(item.get("source_class"), str)
            }),
            "search_results": deepcopy(candidate_prior_work or selected_seed_records or recent_papers),
            "prior_work": deepcopy(candidate_prior_work or selected_seed_records or recent_papers),
            "experiment_feasibility": deepcopy(stage_result.get("feasibility_check", {})),
            "research_question": stage_result.get("question") or topic.get("research_question"),
            "search_terms": deepcopy(stage_result.get("search_queries", topic.get("search_queries", []))),
            "candidate_methods": deepcopy(topic.get("resource_plan", "")),
            "capability_inventory": deepcopy(stage_result.get("feasibility_check", {})),
        })
        return projected

    def _specialist_experiment_projection(self, stage, descriptor, stage_result=None):
        """Project an actionable brief before an experiment has observations.

        Methods specialists are admitted before the experiment runner. A
        continuation therefore cannot rely on ``stage_result`` containing
        raw observations yet, but it must still receive the question, declared
        design, feasibility boundary, and prior failure history. Keep this
        projection bounded instead of forwarding the full dependency graph.
        """
        if stage.get("kind") != "experiment":
            return {}

        try:
            topic_match = self._topic_context_for_stage(stage)
        except ValidationError:
            return {}
        if not topic_match:
            return {}
        _, topic_context = topic_match

        selected = topic_context["topic"]
        program = topic_context.get("research_program")
        selected_branch = None
        if isinstance(program, dict) and isinstance(program.get("branches"), list):
            selected_branch = next(
                (branch for branch in program["branches"]
                 if isinstance(branch, dict) and branch.get("id") == selected.get("id")),
                None,
            )
        selected_branch = selected_branch if isinstance(selected_branch, dict) else {}
        feasibility = topic_context.get("feasibility_check")
        feasibility = feasibility if isinstance(feasibility, dict) else {}
        feasibility_plan = feasibility.get("plan")
        feasibility_plan = feasibility_plan if isinstance(feasibility_plan, dict) else {}
        configured_experiment = descriptor.get("experiment") if isinstance(descriptor, dict) else None
        configured_experiment = configured_experiment if isinstance(configured_experiment, dict) else {}
        capability_source = "topic_only"
        generated = topic_context.get("generated_capability")
        generated_experiment = None
        if isinstance(generated, dict) and isinstance(generated.get("descriptor_path"), str):
            try:
                generated_descriptor = json.loads(Path(generated["descriptor_path"]).read_text())
                candidate_experiment = generated_descriptor.get("experiment")
                if isinstance(candidate_experiment, dict):
                    generated_experiment = candidate_experiment
            except (OSError, TypeError, ValueError):
                generated_experiment = None

        # Specialist admission happens before _run_stage materializes the
        # selected capability. The immutable stage descriptor can therefore
        # still contain a template from an older mission. A matching question
        # alone is not identity: require the selected capability ID (or its
        # explicitly mapped study ID) before admitting a stage-level template.
        selected_capability_id = selected.get("experiment_capability_id")
        expected_study_id = self._stage_experiment_study_id(stage)
        if isinstance(generated_experiment, dict):
            generated_question = generated_experiment.get("research_question")
            generated_id = generated.get("capability_id")
            generated_study_id = generated_experiment.get("id")
            if (generated_question == selected.get("research_question")
                    and isinstance(generated_id, str)
                    and (not isinstance(selected_capability_id, str)
                         or (generated_id == selected_capability_id
                             and (generated_study_id == expected_study_id
                                  if isinstance(expected_study_id, str)
                                  else generated_study_id == selected_capability_id)))):
                configured_experiment = generated_experiment
                capability_source = "admitted_topic_capability"
        if capability_source == "topic_only":
            descriptor_question = configured_experiment.get("research_question")
            descriptor_id = configured_experiment.get("id")
            descriptor_capability_id = configured_experiment.get("capability_id")
            root_capability_id = (
                descriptor.get("capability_id") if isinstance(descriptor, dict) else None
            )
            identity_matches = (
                isinstance(selected_capability_id, str)
                and (
                    descriptor_id == expected_study_id
                    if isinstance(expected_study_id, str)
                    else selected_capability_id in {
                        descriptor_id, descriptor_capability_id, root_capability_id,
                    }
                )
            )
            if (descriptor_question == selected.get("research_question")
                    and identity_matches):
                capability_source = "matching_stage_descriptor"
            else:
                configured_experiment = {}
        result = stage_result if isinstance(stage_result, dict) else {}

        question = topic_context.get("question") or selected.get("research_question")
        hypothesis = selected_branch.get("hypothesis") or selected.get("disconfirmation_test")
        method_constraints = {
            key: deepcopy(selected.get(key))
            for key in ("scope", "data_regime", "feasibility", "resource_plan",
                        "capability_requirements", "comparison", "measurement",
                        "disconfirmation_test", "research_form", "evidence_mode")
            if selected.get(key) is not None
        }
        maturity_scope = self._topic_maturity_requirement_scope(selected, topic_context)
        method_constraints["maturity_open_requirements"] = deepcopy(
            maturity_scope.get("active", []))
        method_constraints["maturity_out_of_scope_requirements"] = deepcopy(
            maturity_scope.get("out_of_scope", []))
        method_constraints["feasibility_plan"] = deepcopy(feasibility_plan)
        available_assets = {
            "prior_work_ids": deepcopy(selected.get("prior_work_ids", [])),
            "evidence_inputs": deepcopy(feasibility_plan.get("evidence_inputs", [])),
            "required_executables": deepcopy(feasibility_plan.get("required_executables", [])),
            "required_packages": deepcopy(feasibility_plan.get("required_packages", [])),
            "network_access": feasibility_plan.get("network_access"),
        }
        design = {
            key: deepcopy(configured_experiment[key])
            for key in ("study_type", "method", "parameters", "primary_outcomes",
                        "stopping_rule", "limitations")
            if key in configured_experiment
        }
        topic_design = selected.get("experiment_design")
        if isinstance(topic_design, dict):
            design["proposed_design"] = deepcopy(topic_design)
        raw_results_source = result.get("raw_results")
        package_source = result.get("results_package")
        result_root = result.get("project_dir") or stage.get("project_dir")
        raw_results_payload = _read_experiment_result_payload(
            raw_results_source, base_dir=result_root)
        package_payload = _read_experiment_result_payload(
            package_source, base_dir=result_root)
        result_payload_unavailable = (
            (isinstance(raw_results_source, str) and raw_results_payload is None)
            or (isinstance(package_source, str) and package_payload is None)
        )
        projected_raw_results = (
            _bounded_experiment_result_projection(raw_results_payload)
            if raw_results_payload is not None else raw_results_source
        )
        projected_package = (
            _bounded_experiment_result_projection(package_payload)
            if package_payload is not None else package_source
        )
        if raw_results_payload is not None and package_payload is not None:
            raw_results = {
                "raw_results": projected_raw_results,
                "results_package": projected_package,
            }
        elif package_payload is not None:
            raw_results = projected_package
        elif raw_results_payload is not None:
            raw_results = projected_raw_results
        else:
            raw_results = next((value for value in (package_source, raw_results_source)
                                if isinstance(value, (dict, list))), None)
        derived_results_source = {}
        for key in ("metrics", "findings", "analysis", "limitations"):
            current = result.get(key)
            packaged = package_payload.get(key) if isinstance(package_payload, dict) else None
            value = current if current not in (None, [], {}) else packaged
            if value is not None:
                derived_results_source[key] = deepcopy(value)
        derived_results = _bounded_experiment_result_projection(derived_results_source)
        asset_source = result.get("assets")
        if not isinstance(asset_source, list) or not asset_source:
            asset_source = (package_payload.get("assets", [])
                            if isinstance(package_payload, dict) else [])
        figures = _bounded_experiment_result_projection(
            [asset for asset in asset_source if isinstance(asset, dict)
             and (asset.get("role") == "figure"
                  or str(asset.get("media_type", "")).casefold().startswith("image/"))]
            if isinstance(asset_source, list) else [])

        def is_non_measurement_field(key):
            return (_is_experiment_result_metadata_field(key)
                    or (isinstance(key, str) and key.casefold() in {
                        "analysis", "metrics", "observations",
                        "raw_results", "results_package",
                    }))

        def has_observation_record(record):
            return (isinstance(record, dict) and any(
                not is_non_measurement_field(key)
                and _contains_numeric_experiment_measurement(item)
                for key, item in record.items()))

        def has_measurements(value):
            if isinstance(value, list):
                return any(has_observation_record(item) for item in value)
            if not isinstance(value, dict):
                return False
            if has_observation_record(value):
                return True
            observations = value.get("observations")
            if isinstance(observations, list) and any(
                    has_observation_record(item) for item in observations):
                return True
            metrics = value.get("metrics")
            if _has_numeric_experiment_metrics(metrics):
                return True
            for key in ("raw_results", "results_package"):
                if has_measurements(value.get(key)):
                    return True
            analysis = value.get("analysis")
            return (isinstance(analysis, dict) and any(
                _contains_numeric_experiment_measurement(analysis.get(key))
                for key in (
                    "comparisons", "uncertainty", "effect_sizes", "sensitivity",
                    "ablation", "raw_data")))

        has_observed_results = (has_measurements(raw_results_payload)
                                or has_measurements(package_payload) or has_measurements({
            "metrics": derived_results.get("metrics"),
            "analysis": derived_results.get("analysis"),
        }))
        result_status = result.get("status")
        execution_refs = result.get("execution_refs")
        execution_refs = ([item[:512] for item in execution_refs[:32]
                           if isinstance(item, str)]
                          if isinstance(execution_refs, list) else [])
        analysis_plan = {
            "research_question": question,
            "hypothesis": hypothesis,
            "comparison": selected.get("comparison"),
            "measurement": selected.get("measurement"),
            "disconfirmation_test": selected.get("disconfirmation_test"),
            "primary_outcomes": deepcopy(configured_experiment.get("primary_outcomes", [])),
            "stopping_rule": deepcopy(configured_experiment.get("stopping_rule")),
            "capability_source": capability_source,
            "state": (
                "stage_result_available" if has_observed_results
                else "result_payload_unavailable" if result_payload_unavailable
                else "pre_execution"
            ),
        }
        prior_stage_context = self.context.get(stage.get("id"), {})
        prior_stage_context = prior_stage_context if isinstance(prior_stage_context, dict) else {}
        failure_recovery = prior_stage_context.get("failure_recovery")
        failure_recovery = failure_recovery if isinstance(failure_recovery, dict) else None
        prior_repair_plan = prior_stage_context.get("experiment_repair_plan")
        prior_repair_plan = prior_repair_plan if isinstance(prior_repair_plan, dict) else {}
        blockers = [
            {key: deepcopy(item.get(key)) for key in ("stage_id", "reason", "diagnostics") if key in item}
            for item in self.blockers
            if isinstance(item, dict) and item.get("stage_id") == stage.get("id")
        ][-4:]
        if has_observed_results:
            for blocker in blockers:
                blocker["temporal_scope"] = "historical_prior_attempt"
                blocker["current_attempt_id"] = result.get("attempt_id")
        program_snapshot = self._failure_program_snapshot(
            stage, topic_context=topic_context)
        capability_repair_panel = prior_stage_context.get("capability_repair_panel")
        capability_repair_panel = (
            capability_repair_panel if isinstance(capability_repair_panel, dict) else {})
        panel_verifier = capability_repair_panel.get("verifier")
        panel_verifier = panel_verifier if isinstance(panel_verifier, dict) else {}
        recovery_directives = (
            failure_recovery.get("review_directives")
            if isinstance(failure_recovery, dict) else None
        )
        failure_dossier_ref = (
            prior_stage_context.get("failure_dossier_ref")
            or (failure_recovery.get("dossier_ref")
                if isinstance(failure_recovery, dict) else None)
        )
        current_failure_message = result.get("error")
        failure_message = (
            current_failure_message if isinstance(current_failure_message, str)
            else prior_stage_context.get("error")
            or (failure_recovery.get("error")
                if isinstance(failure_recovery, dict) else None)
        )
        current_capability_evidence = result.get("capability_failure_evidence")
        if not isinstance(current_capability_evidence, dict):
            current_capability_evidence = prior_stage_context.get(
                "capability_failure_evidence")
        failure_evidence = None
        if (failure_dossier_ref or failure_message or failure_recovery
                or capability_repair_panel or current_capability_evidence):
            failure_evidence = self._capability_repair_projection({
                "failure_class": result.get("failure_class") or (
                    failure_recovery.get("failure_class")
                    if isinstance(failure_recovery, dict) else None),
                "failure_dossier_ref": failure_dossier_ref,
                "failure_dossier": self._failure_dossier_evidence(
                    failure_dossier_ref,
                    expected_stage_id=stage.get("id"),
                    expected_attempt_number=(
                        failure_recovery.get("attempt_number")
                        if isinstance(failure_recovery, dict) else None
                    ),
                ),
                "failure_input_sha256": (
                    prior_stage_context.get("failure_input_sha256")
                    or (failure_recovery.get("input_sha256")
                        if isinstance(failure_recovery, dict) else None)
                ),
                "error": failure_message,
                "capability_failure_evidence": deepcopy(current_capability_evidence),
                "research_review": deepcopy(result.get("research_review")
                                              or prior_stage_context.get("research_review")),
                "review_directives": recovery_directives,
                "repair_plan": {
                    **{
                        key: deepcopy(prior_repair_plan.get(key))
                        for key in ("design_axis", "instruction", "required_evidence",
                                    "review_evidence")
                        if key in prior_repair_plan
                    },
                    "diagnostic_hypotheses": deepcopy(
                        prior_repair_plan.get("diagnostic_hypotheses")
                        or prior_repair_plan.get("root_causes", [])),
                    "proposed_changes": deepcopy(
                        prior_repair_plan.get("proposed_changes")
                        or prior_repair_plan.get("required_changes", [])),
                },
                "latest_methods_panel": {
                    "decision": capability_repair_panel.get("decision"),
                    "diagnostic_hypotheses": deepcopy(
                        capability_repair_panel.get("diagnostic_hypotheses")
                        or capability_repair_panel.get("root_causes", []))[:8],
                    "proposed_changes": deepcopy(
                        capability_repair_panel.get("proposed_changes")
                        or capability_repair_panel.get("required_changes", []))[:8],
                    "verifier": {
                        "decision": panel_verifier.get("decision"),
                        "critical_findings": deepcopy(
                            panel_verifier.get("critical_findings", []))[:6],
                        "repair_scope": deepcopy(panel_verifier.get("repair_scope", []))[:6],
                    },
                    "source_manifest": [
                        {key: item.get(key) for key in ("path", "sha256", "size_bytes")
                         if key in item}
                        for item in program_snapshot[:8] if isinstance(item, dict)
                    ],
                },
            }, max_depth=7, max_keys=40, max_items=12, max_text=20_000)
            if has_observed_results and isinstance(failure_evidence, dict):
                failure_evidence.update({
                    "temporal_scope": "historical_prior_attempts_only",
                    "current_attempt_id": result.get("attempt_id"),
                    "current_result_status": result_status,
                    "current_execution_refs": execution_refs,
                })
        failure_recovery_projection = deepcopy(failure_recovery)
        if has_observed_results and isinstance(failure_recovery_projection, dict):
            failure_recovery_projection.update({
                "temporal_scope": "historical_prior_attempt_only",
                "current_attempt_id": result.get("attempt_id"),
                "current_result_status": result_status,
                "current_execution_refs": execution_refs,
            })
        try:
            input_descriptor = descriptor
            if stage.get("kind") == "experiment" and capability_source != "matching_stage_descriptor":
                # Fingerprint only the experiment design admitted for this
                # research question. The workflow may retain an old pilot in
                # its immutable descriptor; hashing those scripts into the
                # specialist brief falsely presents them as current inputs.
                input_descriptor = deepcopy(descriptor or {})
                input_descriptor["experiment"] = (
                    deepcopy(generated_experiment)
                    if capability_source == "admitted_topic_capability"
                    and isinstance(generated_experiment, dict)
                    else {}
                )
            input_digests = self._stage_input_files(
                stage, input_descriptor, include_dependencies=False)
        except (OSError, TypeError, ValueError):
            input_digests = {}
        return {
            "research_question": question,
            "hypotheses": hypothesis,
            "method_constraints": method_constraints,
            "available_assets": available_assets,
            "design": design,
            "analysis_plan": analysis_plan,
            "claims": {
                "declared_hypothesis": hypothesis,
                "disconfirmation_test": selected.get("disconfirmation_test"),
                "status": (
                    "measurements_available" if has_observed_results
                    else "declared_not_observed"
                ),
                "hypothesis_status": "not_adjudicated",
                "execution_refs": execution_refs,
            },
            "execution_manifest": {
                "state": (
                    "observed_results" if has_observed_results
                    else "completed_without_observations"
                    if result_status in {"completed", "accepted", "candidate_needs_review"}
                    else "failed" if result_status in {"blocked", "failed", "error"}
                    else "planned"
                ),
                "result_status": result_status,
                "attempt_id": result.get("attempt_id"),
                "project_dir": result.get("project_dir"),
                "execution_refs": execution_refs,
                "capability_id": selected.get("experiment_capability_id"),
                "capability_source": capability_source,
                "execution_mode": feasibility_plan.get("execution_mode"),
                "required_executables": deepcopy(feasibility_plan.get("required_executables", [])),
                "required_packages": deepcopy(feasibility_plan.get("required_packages", [])),
                "network_access": feasibility_plan.get("network_access"),
            },
            "input_digests": input_digests,
            "raw_results": deepcopy(raw_results) if raw_results is not None else None,
            "analysis_code": (
                {
                    "state": "execution_source_unverified",
                    "files": program_snapshot,
                    "execution_refs": execution_refs,
                    "source_snapshot_scope": (
                        "workspace snapshot; it is not established as the exact source used by the linked execution"
                    ),
                }
                if has_observed_results else
                {"state": "failure_snapshot", "files": program_snapshot,
                 "failure_dossier_ref": prior_stage_context.get("failure_dossier_ref")}
                if program_snapshot or failure_recovery else
                {"state": "not_available_before_execution",
                 "reason": "The executable is generated and admitted after the methods brief."}
            ),
            "derived_results": derived_results,
            "figures": figures,
            "failure_history": blockers,
            **({"failure_evidence": failure_evidence}
               if isinstance(failure_evidence, dict) else {}),
            "failure_recovery": failure_recovery_projection,
        }

    def _stage_acceptance_contract(self, stage):
        descendants = set()
        frontier = {stage["id"]}
        while frontier:
            children = {item["id"] for item in self.workflow["stages"]
                        if frontier.intersection(item["depends_on"])} - descendants
            descendants.update(children)
            frontier = children
        requirements = {
            "topic_discovery": ["A structurally valid, bounded, searchable scientific question and a feasible literature-testing plan."],
            "survey": ["Current captured sources support the declared literature claims and comparison; unresolved evidence limits and assigned obligations remain explicit."],
            "experiment": ["The declared design, source-bound parameters and executable capability are independently reviewed; actual observations and primary outcomes have valid independent recalculation."],
            "interpretation": ["Interpretations follow the admitted evidence and outcomes without changing the question or promoting unsupported claims."],
            "argument": ["Every material scientific claim is supported by current evidence and the declared limitations."],
            "paper": ["The manuscript faithfully presents the admitted claims, results, evidence and limitations under its editorial acceptance contract."],
        }
        target = ("bounded admission to literature survey, not final journal maturity or experiment admission"
                  if stage["kind"] == "topic_discovery" else "independent acceptance of the declared " + stage["kind"] + " output")
        return {"current_stage_id": stage["id"],
            "scientific_input_recovery": scientific_input_recovery_contract(),
            "downstream_stage_ids": [item["id"] for item in self.workflow["stages"] if item["id"] in descendants],
            "acceptance_target": target, "current_requirements": deepcopy(requirements[stage["kind"]]),
            "downstream_requirements": [{"target_stage_id": item["id"], "stage_kind": item["kind"],
                "requirements": deepcopy(requirements[item["kind"]])}
                for item in self.workflow["stages"] if item["id"] in descendants]}

    def _specialist_stage_packet(self, stage, descriptor, *, stage_result=None):
        """Build a bounded, non-secret packet for specialist input projection."""
        packet = {
            "objective": self.workflow["objective"],
            "stage_id": stage["id"],
            "stage_kind": stage["kind"],
            "stage_acceptance_contract": self._stage_acceptance_contract(stage),
            "work_orders": self._follow_up_projection(self._requests_for_stage(stage)),
            "dependencies": deepcopy(self.context),
            "stage_result": self._specialist_stage_result_projection(
                stage, stage_result or {}),
            "configured_stage": {
                key: deepcopy(value) for key, value in (descriptor or {}).items()
                if key not in {"model", "model_config_path", "bibliography"}
            },
        }
        packet.update(self._specialist_experiment_projection(
            stage, descriptor, stage_result=stage_result))
        if (isinstance(stage_result, dict)
                and stage_result.get("_repair_panel") is True
                and isinstance(stage_result.get("capability_repair_packet"), dict)):
            packet["repair_panel"] = True
            packet["capability_repair_packet"] = deepcopy(
                stage_result["capability_repair_packet"])
        if stage["kind"] == "topic_discovery":
            model = self._specialist_model_config(stage, descriptor)
            if model is not None:
                packet["runtime_context"] = self._runtime_context(model)
        return packet

    @staticmethod
    def _active_specialist_roles(live):
        return [role for role, event in live.items() if isinstance(event, dict)
                and event.get("event") != "completed"
                and (event.get("event") == "dispatched"
                     or event.get("status") in {"running", "started", "dispatched"})]

    def _specialist_progress(self, stage_id, event, *, assignment=None):
        """Publish a thread-safe live projection without touching SQLite."""
        if not isinstance(event, dict):
            return
        role = event.get("role")
        if not isinstance(role, str):
            return
        if event.get("stage_id") is not None and event["stage_id"] != stage_id:
            return
        current = self.stage_records.get(stage_id)
        if isinstance(assignment, dict):
            if assignment.get("stage_id") != stage_id:
                return
            rows = assignment.get("assignments", [])
            matched = next((row for row in rows if isinstance(row, dict)
                            and row.get("task_id") == event.get("task_id")
                            and row.get("assigned_role") == role), None)
            if matched is None:
                return
            if not isinstance(current, dict):
                current = {"status": "running", "attempt_number": assignment.get("attempt_number"),
                           "assignment_task_ids": assignment.get("task_ids", [])}
            elif (current.get("attempt_number") is not None
                  and current["attempt_number"] != assignment.get("attempt_number")):
                return
        if not isinstance(current, dict) or current.get("status") != "running":
            return
        allowed_tasks = current.get("assignment_task_ids", [])
        if allowed_tasks and event.get("task_id") not in allowed_tasks:
            return
        if (event.get("assignment_attempt_number") is not None
                and current.get("attempt_number") is not None
                and event["assignment_attempt_number"] != current["attempt_number"]):
            return
        live = {key: deepcopy(event.get(key)) for key in (
            "event", "role", "role_id", "task_id", "stage_id", "model_role", "route_id",
            "provider_pool", "model", "base_url", "cache_prompt", "execution_mode", "status",
            "assignment_attempt_number",
            "context_window_tokens", "max_input_tokens",
            "decision", "elapsed_seconds", "error", "attempts", "usage", "artifact_ref",
            "response_ref", "continuation", "continuation_from_chars",
        ) if key in event}
        live["observed_at"] = now_iso()
        now = self.clock()
        remaining_snapshot = self.deadline - now
        if isinstance(self.deadline_epoch, (int, float)) and math.isfinite(self.deadline_epoch):
            remaining_snapshot = min(remaining_snapshot, self.deadline_epoch - time.time())
        self._end_child_activity(stage_id)
        with self._progress_lock:
            state = deepcopy(self._progress_snapshot)
            state.update({
                "phase": f"{stage_id}:specialists",
                "elapsed_seconds": max(0.0, now - self.started),
                "remaining_seconds": max(0.0, remaining_snapshot),
                "started_at_epoch": self.started_epoch,
                "deadline_at_epoch": self.deadline_epoch,
            })
            stage_record = state.setdefault("stages", {}).setdefault(stage_id, {})
            stage_record.update({key: deepcopy(current[key]) for key in (
                "status", "attempt_number", "assignment_task_ids") if key in current})
            previous = stage_record.setdefault("specialist_live", {}).get(role, {})
            if isinstance(previous, dict) and event.get("event") == "completed":
                live = {**previous, **live}
                live.setdefault("started_at", previous.get("observed_at"))
            if event.get("event") == "dispatched":
                live["started_at"] = live["observed_at"]
            live["updated_at"] = live["observed_at"]
            stage_record["specialist_live"][role] = live
            stage_record["active_agents"] = self._active_specialist_roles(
                stage_record["specialist_live"])
            self._progress_snapshot = deepcopy(state)
            output = self.root / "output"
            output.mkdir(parents=True, exist_ok=True)
            _atomic_write_bytes(output / "progress.json", canonical_bytes(state))

    def _dispatch_specialist_work(self, dispatcher, assignments, packet, *, verifier=False):
        """Persist each completed role before another role can fail or time out."""
        cache = ModelWorkCache(self.store, self._publish)
        pending, reports, keys = [], [], {}

        def reusable_cached_report(value):
            """Keep transport failures out of the scientific result cache."""
            if not isinstance(value, dict):
                return False
            if _report_has_model_call_failure(value):
                return False
            if value.get("status") == "result_unknown":
                return False
            if value.get("status_code") in {408, 425, 429, 500, 502, 503, 504}:
                return False
            error = str(value.get("error") or "").casefold()
            return not any(token in error for token in (
                "provider", "cooling down", "transport", "http request",
                "connection reset", "connection refused", "timeout",
            ))

        for assignment in assignments:
            prompt = assignment.get("_prompt") or build_specialist_prompt(assignment, packet)
            key = cache.key(scope=f"specialist:{assignment['stage_id']}:{verifier}",
                role=assignment.get("assigned_role"), system=specialist_system(assignment, verifier=verifier),
                prompt=prompt, model=dispatcher.model_config)
            keys[assignment["role_id"]] = key
            retained = cache.get(key)
            retained_report = retained.get("report") if isinstance(retained, dict) else None
            if (retained and retained.get("status") in {"succeeded", "blocked"}
                    and reusable_cached_report(retained_report)):
                report = deepcopy(retained["report"])
                report.update(usage={}, reused_from=retained["cache_ref"],
                              elapsed_seconds=0, request_attempts=0,
                              execution_mode="retained_model_result" if retained["status"] == "succeeded" else "retained_failure")
                reports.append(report)
                if hasattr(dispatcher, "on_progress"):
                    dispatcher.on_progress({
                        "event": "reused_model_result",
                        "role": assignment.get("assigned_role"),
                        "role_id": assignment.get("role_id"),
                        "task_id": assignment.get("task_id"),
                        "stage_id": assignment.get("stage_id"),
                        "model_role": assignment.get("model_role"),
                        "assignment_attempt_number": assignment.get("attempt_number"),
                        "status": report.get("status"),
                        "decision": report.get("decision"),
                        "execution_mode": report.get("execution_mode"),
                        "artifact_ref": retained.get("cache_ref"),
                        "usage": {},
                    })
            else:
                pending.append(assignment)
        # Cooldowns are route-scoped.  The capacity pool remains shared, but
        # a transient failure from one model must not fence every model served
        # by the same endpoint.  Legacy pool-scoped records are intentionally
        # not loaded here: they have no route provenance and were the source
        # of cross-model 24-hour stalls in resumed runs.
        cooldown_keys = (dispatcher.cooldown_keys()
                         if hasattr(dispatcher, "cooldown_keys") else [])
        for cooldown_key in cooldown_keys:
            component = safe_artifact_component(cooldown_key)
            record = self.store.head(f"command/provider-cooldowns/{component}")
            if record:
                body = json.loads(self.store.read_body(record["body_hash"]))
                remaining = body["not_before_epoch"] - time.time()
                if remaining > 0:
                    dispatcher.provider_cooldowns[cooldown_key] = time.monotonic() + remaining

        def retain(report):
            if report.get("status") == "succeeded":
                cache.put(keys[report["role_id"]], {"status": "succeeded", "report": report})
            elif reusable_cached_report(report):
                # Failed/unknown reports remain failures. Retaining the exact
                # assignment prevents a new outer stage attempt from silently
                # replenishing its specialist call allowance.
                cache.put(keys[report["role_id"]], {"status": "blocked", "report": report})
            for cooldown_key, until in list(dispatcher.provider_cooldowns.items()):
                component = safe_artifact_component(cooldown_key)
                self._publish(f"command/provider-cooldowns/{component}", "note", {
                    "cooldown_key": cooldown_key,
                    "not_before_epoch": time.time() + max(0, until - time.monotonic()),
                }, "command.controller")

        reports.extend(dispatcher.dispatch(pending, packet, verifier=verifier, on_result=retain))
        return reports

    def _run_specialist_pool(self, stage, stage_assignment, descriptor, *, stage_result=None,
                             cache_input_digest=None):
        """Run the admitted specialist assignments in a bounded provider pool."""
        model = self._specialist_model_config(stage, descriptor)
        if model is None or not isinstance(stage_assignment, dict):
            return {"reports": [], "by_role": {}, "usage": {}, "model_enabled": False}
        assignments = [item for item in stage_assignment.get("assignments", [])
                       if isinstance(item, dict) and item.get("assignment_phase") == "specialist"]
        if not assignments:
            return {"reports": [], "by_role": {}, "usage": {}, "model_enabled": False}
        limits = descriptor.get("limits") if isinstance(descriptor, dict) else {}
        max_parallel = limits.get("concurrent_calls") if isinstance(limits, dict) else None
        if type(max_parallel) is not int or max_parallel < 1:
            max_parallel = min(4, len(assignments))
        deadline = time.monotonic() + self._stage_remaining(stage)
        packet = self._specialist_stage_packet(
            stage, descriptor, stage_result=stage_result)
        packet_digest = (
            cache_input_digest if isinstance(cache_input_digest, str)
            and re.fullmatch(r"[0-9a-f]{64}", cache_input_digest)
            else hashlib.sha256(canonical_bytes(packet)).hexdigest()
        )
        assignment_number = stage_assignment.get("attempt_number")
        stage_record = self.stage_records.get(stage.get("id"), {})
        attempt_history = stage_record.get("attempts", []) if isinstance(stage_record, dict) else []
        unknown_parent_attempts = {
            item.get("attempt_number") for item in attempt_history
            if isinstance(item, dict) and item.get("state") == "unknown"
        }
        if (isinstance(stage_record, dict)
                and stage_record.get("status") == "running"
                and type(stage_record.get("attempt_number")) is int):
            unknown_parent_attempts.add(stage_record["attempt_number"])
        reports_by_role = {}
        pending_assignments = []
        for assignment in assignments:
            role_id = assignment.get("role_id")
            prior = None
            if isinstance(role_id, str) and type(assignment_number) is int:
                prior = self.departments.find_reusable_specialist_report(
                    stage["id"], role_id,
                    before_attempt_number=assignment_number,
                    input_digest=packet_digest,
                )
            if (isinstance(prior, dict)
                    and prior.get("attempt_number") in unknown_parent_attempts):
                report = deepcopy(prior["report"])
                prior_usage = report.get("usage")
                prior_usage = prior_usage if isinstance(prior_usage, dict) else {}
                report.update({
                    "provider_call_reused": True,
                    "reused_from_attempt_id": prior.get("attempt_id"),
                    "reused_from_artifact_ref": prior.get("artifact_ref"),
                    "artifact_ref": prior.get("artifact_ref"),
                    "reused_prior_usage": deepcopy(prior_usage),
                    "usage": {
                        key: 0 for key, value in prior_usage.items()
                        if type(value) in (int, float) and math.isfinite(value)
                        and value >= 0
                    },
                })
                reports_by_role[role_id] = report
                self._specialist_progress(stage["id"], {
                    "event": "reused_durable_result",
                    "role": assignment.get("assigned_role"),
                    "role_id": role_id,
                    "task_id": assignment.get("task_id"),
                    "stage_id": stage["id"],
                    "status": report.get("status"),
                    "artifact_ref": prior.get("artifact_ref"),
                    "reused_from_attempt_number": prior.get("attempt_number"),
                }, assignment=stage_assignment)
            else:
                pending_assignments.append(assignment)
        if pending_assignments:
            assignment_number = stage_assignment.get("attempt_number")
            dispatcher = SpecialistDispatcher(
                model, provider_pools=self._specialist_provider_pools(descriptor),
                max_parallel=min(max_parallel, len(pending_assignments)), deadline=deadline,
                on_progress=lambda event: self._specialist_progress(stage["id"], {
                    **event, "assignment_attempt_number": assignment_number,
                }, assignment=stage_assignment),
            )
            for report in self._dispatch_specialist_work(dispatcher, pending_assignments, packet):
                role_id = report.get("role_id")
                if isinstance(role_id, str):
                    reports_by_role[role_id] = report
        reports = [reports_by_role[row.get("role_id")] for row in assignments
                   if isinstance(row.get("role_id"), str)
                   and row.get("role_id") in reports_by_role]
        by_role = {}
        for report in reports:
            role_id = report.get("role_id")
            if isinstance(role_id, str):
                by_role[role_id] = report
        return {
            "reports": reports,
            "by_role": by_role,
            "packet": packet,
            "usage": self._specialist_usage(reports),
            "model_enabled": True,
        }

    @staticmethod
    def _failure_stage_result(stage, error):
        """Build the bounded packet given to reviewers after producer failure.

        Stage runners can return a durable observation package and then fail
        admission.  Older control flow discarded that package before the
        specialist pool ran, so a failure became a bare string and the
        assigned reviewers were cancelled without doing any work.  Preserve
        the runner's exact package when available and otherwise expose only a
        bounded failure envelope; this never invents scientific observations.
        """
        retained = getattr(error, "stage_result", None)
        result = deepcopy(retained) if isinstance(retained, dict) else {
            "status": "blocked",
            "error": str(error),
            "failure_scope": "stage",
        }
        result.setdefault("status", "blocked")
        result.setdefault("error", str(error))
        result.setdefault("failure_scope", "stage")
        result.setdefault("stage_id", stage.get("id"))
        result.setdefault("kind", stage.get("kind"))
        usage = getattr(error, "usage", None)
        if isinstance(usage, dict) and not isinstance(result.get("usage"), dict):
            result["usage"] = deepcopy(usage)
        failure_class = getattr(error, "failure_class", None)
        if isinstance(failure_class, str) and failure_class:
            result.setdefault("failure_class", failure_class)
        # Runner exceptions are the only durable carrier for a rejected
        # argument when adjudication fails after producing a valid candidate.
        # Preserve that candidate and verdict for the failure-specialist panel;
        # reducing it to ``{status, error}`` made every reviewer report that the
        # argument was empty and prevented a meaningful repair order.
        for attribute in ("research_argument", "research_review", "research_feedback",
                          "research_response", "research_review_argument_sha256",
                          "capability_failure_evidence", "model_diagnostics",
                          "repair_feedback"):
            value = getattr(error, attribute, None)
            if value is not None:
                result[attribute] = deepcopy(value)
        if getattr(error, "capability_repair_routed", False):
            result["capability_repair_routed"] = True
        if isinstance(result.get("research_argument"), dict):
            result.setdefault("argument", deepcopy(result["research_argument"]))
            package = result.get("argument_package")
            if not isinstance(package, dict):
                package = {}
            package.setdefault("argument", deepcopy(result["research_argument"]))
            if isinstance(result.get("research_review"), dict):
                package.setdefault("review", deepcopy(result["research_review"]))
            result["argument_package"] = package
        if isinstance(result.get("research_review"), dict):
            result.setdefault("review", deepcopy(result["research_review"]))
        return result

    def _run_failure_specialist_review(self, stage, stage_assignment, descriptor, error):
        """Give materialized failure evidence to specialists before recovery.

        This path is intentionally separate from ordinary producer success:
        it is only entered for a scientific/model-contract failure, never for
        provider cooldown, credential, deadline, or quota fences.  Reviewer
        calls therefore analyze the failed artifact or exact error once and
        can issue a scoped repair order without turning an operational outage
        into another expensive retry.
        """
        stage_result = self._failure_stage_result(stage, error)
        empty = {"reports": [], "by_role": {}, "usage": {},
                 "model_enabled": False, "packet": {}}
        try:
            bundle = self._run_specialist_pool(
                stage, stage_assignment, descriptor, stage_result=stage_result)
            bundle = self._publish_specialist_reports(
                stage, stage_assignment, bundle)
        except Exception as review_error:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "failure_specialist_review_error",
                "stage_id": stage["id"],
                "error": f"{type(review_error).__name__}: {review_error}",
                "producer_failure": str(error)[:2048],
            })
            return empty, None, stage_result

        reports = bundle.get("reports", []) if isinstance(bundle, dict) else []
        verifier = None
        # A verifier is useful only when at least one producer specialist
        # returned an actual response.  Calling it against an all-failed pool
        # would consume quota without adding an independent judgment.
        if any(isinstance(report, dict)
               and report.get("status") == "succeeded"
               for report in reports):
            try:
                verifier = self._run_specialist_verifier(
                    stage, stage_assignment, descriptor, bundle, stage_result,
                    stage_result=stage_result)
            except Exception as verifier_error:
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "failure_specialist_verifier_error",
                    "stage_id": stage["id"],
                    "error": f"{type(verifier_error).__name__}: {verifier_error}",
                    "producer_failure": str(error)[:2048],
                })
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "failure_specialist_review_completed",
            "stage_id": stage["id"],
            "producer_failure": str(error)[:2048],
            "specialist_count": len(reports),
            "successful_specialists": sum(
                1 for report in reports
                if isinstance(report, dict) and report.get("status") == "succeeded"),
            "verifier_dispatched": verifier is not None,
        })
        return bundle, verifier, stage_result

    @staticmethod
    def _capability_repair_panel_stage_id(stage_id, science_digest, cycle, attempt):
        """Keep one durable Methods assignment lineage for unchanged evidence."""
        base = re.sub(r"[^a-z0-9-]+", "-", str(stage_id).casefold()).strip("-")
        if isinstance(science_digest, str) and re.fullmatch(r"[0-9a-f]{64}", science_digest):
            suffix = f"-repair-panel-{science_digest[:12]}"
        else:
            suffix = f"-repair-panel-{cycle}-{attempt}"
        return f"{(base or 'experiment')[:64 - len(suffix)]}{suffix}"

    @staticmethod
    def _capability_repair_panel_completed(panel):
        """Whether a completed Methods panel already reviewed this failed design."""
        if not isinstance(panel, dict) or panel.get("status") != "completed":
            return False
        reports = panel.get("reports")
        if not isinstance(reports, list) or not any(
                isinstance(report, dict) and report.get("status") == "succeeded"
                for report in reports):
            return False
        verifier = panel.get("verifier")
        return isinstance(verifier, dict) and verifier.get("status") == "succeeded"

    @staticmethod
    def _failure_review_was_material(context, recovery=None):
        """Whether durable state contains a substantive prior specialist review."""
        context = context if isinstance(context, dict) else {}
        recovery = recovery if isinstance(recovery, dict) else {}
        reports = context.get("specialist_reports")
        reviewed_reports = isinstance(reports, list) and any(
            isinstance(report, dict) and report.get("status") == "succeeded"
            for report in reports)
        verifier = context.get("specialist_verifier")
        reviewed_verifier = (
            isinstance(verifier, dict) and verifier.get("status") == "succeeded")
        directives = context.get("review_directives") or recovery.get("review_directives")
        reviewed_directives = isinstance(directives, list) and any(
            (isinstance(item, dict) and isinstance(item.get("text"), str)
             and item["text"].strip())
            or (isinstance(item, str) and item.strip())
            for item in directives)
        return reviewed_reports or reviewed_verifier or reviewed_directives

    def _should_run_failure_specialist_review(self, error, stage=None):
        """Review scientific evidence, not transport or missing-input failures."""
        if self._is_operational_stage_failure(error):
            return False
        if (getattr(error, "capability_repair_panel_completed", False)
                or getattr(error, "capability_repair_panel_attempted", False)
                or getattr(error, "capability_repair_routed", False)):
            return False
        if (getattr(error, "failure_class", None) == "experiment_capability_repair"
                and getattr(error, "recovery_mode", None) == "repair_then_rerun"):
            # The Foundry verdict is consumed by the next-turn Methods panel;
            # another generic failure pool would repeat the same review work.
            return False
        from scisaurus.runtime.capability_foundry import CapabilityDeadlineError
        if isinstance(error, (
            ProviderCooldownError,
            *PROVIDER_OPERATOR_STOP_ERRORS,
            QuotaExceededError,
            ComposerLateStageResult,
            ComposerHardDeadlineExceeded,
            ComposerStageDeadlineExceeded,
            CapabilityDeadlineError,
                KeyboardInterrupt,
        )) or (isinstance(error, ModelCallError) and error.status_code == 429):
            return False
        if classify_failure(
                stage.get("kind") if isinstance(stage, dict) else None,
                error, getattr(error, "stage_result", None)) == "harness_bug":
            return False
        if not isinstance(stage, dict):
            return True
        return classify_failure(
            stage.get("kind"), error, getattr(error, "stage_result", None)
        ) not in {"model_contract", "evidence_input_unavailable"}

    @staticmethod
    def _specialist_usage(reports):
        totals = {"model_calls": 0, "input_tokens": 0, "output_tokens": 0}
        by_role = {}
        for report in reports if isinstance(reports, list) else []:
            if not isinstance(report, dict):
                continue
            role_id = report.get("role_id") or report.get("assigned_role")
            usage = report.get("usage") if isinstance(report.get("usage"), dict) else {}
            if isinstance(role_id, str):
                by_role[role_id] = (
                    {key: 0 for key in totals}
                    if report.get("provider_call_reused") is True
                    else deepcopy(usage)
                )
            if report.get("provider_call_reused") is True:
                continue
            for key in totals:
                value = usage.get(key, 0)
                if type(value) in (int, float) and math.isfinite(value) and value >= 0:
                    totals[key] += value
        totals["by_role"] = by_role
        return totals

    @staticmethod
    def _current_attempt_usage(context):
        """Exclude historical producer usage when a durable stage result is replayed."""
        usage = deepcopy(context.get("usage", {})) if isinstance(context, dict) else {}
        if not isinstance(usage, dict):
            return {}
        recovery = context.get("producer_recovery")
        source = recovery.get("source_usage") if isinstance(recovery, dict) else None
        if not isinstance(source, dict):
            return usage
        for key, amount in source.items():
            observed = usage.get(key, 0)
            if (type(amount) in (int, float) and math.isfinite(amount) and amount >= 0
                    and type(observed) in (int, float) and math.isfinite(observed)
                    and observed >= 0):
                usage[key] = max(0, observed - amount)
        return usage

    def _stage_specialist_payment_proof(self, stage, plan_ref, execution_ref):
        if not any(item.get("id") == stage["id"] and item.get("kind") == stage["kind"]
                   for item in self.workflow["stages"]):
            return {}
        plan_record, _, plan = self._read_verified_artifact_json(plan_ref)
        execution_record, _, execution = self._read_verified_artifact_json(execution_ref)
        if (plan_record.get("author") != "command.composer"
                or plan.get("schema_version") != "department-stage-assignment-1"
                or execution.get("schema_version") not in {"specialist-execution-1", "specialist-verifier-execution-1"}
                or any(plan.get(key) != execution.get(key) for key in ("project_id", "stage_id", "stage_kind", "attempt_number"))
                or plan.get("project_id") != self.workflow["project_id"]
                or plan.get("stage_id") != stage["id"] or plan.get("stage_kind") != stage["kind"]
                or execution_record.get("author") != execution.get("assigned_role")):
            raise StateError("specialist payment does not match its owned stage plan")
        rows = self.departments._assignment_task_rows(stage_id=stage["id"], attempt_number=plan["attempt_number"])
        row = next((row for row in rows if row.get("task_id") == execution.get("task_id")), None)
        if (row is None or execution_ref.split("@")[0] != "artifact:" + row["assignment_logical_id"] + "/execution"
                or any(row.get(key) != execution.get(key) for key in ("assignment_id", "assigned_role", "role_id"))
                or (execution.get("schema_version") == "specialist-execution-1"
                    and row.get("input_ref") != execution.get("input_ref"))):
            raise StateError("specialist payment execution is not its exact admitted assignment")
        report = execution.get("report") or {}
        usage = report.get("usage") or {}
        cost = {key: usage.get(key, 0) for key in self.usage}
        if any(type(value) not in (int, float) or not math.isfinite(value) or value < 0 for value in cost.values()):
            raise StateError("specialist payment has invalid actual usage")
        if not any(cost.values()):
            return cost
        namespace = hashlib.sha256(canonical_bytes({"specialist_execution_ref": execution_ref,
                                                    "body_sha256": execution_record["body_hash"]})).hexdigest()
        proof = {"schema_version": "composer-specialist-payment-1", "stage_id": stage["id"],
                 "plan_ref": plan_ref, "plan_sha256": plan_record["body_hash"],
                 "execution_ref": execution_ref, "execution_sha256": execution_record["body_hash"],
                 "usage": cost, "namespace": namespace}
        return proof

    def _settle_stage_specialist_payment(self, stage, plan_ref, execution_ref):
        proof = self._stage_specialist_payment_proof(stage, plan_ref, execution_ref)
        if not isinstance(proof, dict) or "usage" not in proof:
            return {}
        cost, namespace = proof["usage"], proof["namespace"]
        prior = self.stage_usage_totals.get(namespace, {})
        if prior and prior != cost:
            raise StateError("specialist payment conflicts with its settled immutable execution")
        self._publish(f"command/composer/specialist-payments/{namespace}", "report", proof, "command.composer")
        self.pending_stage_usage[namespace] = {"stage_id": stage["id"], "totals": cost,
                                               "delta": {key: max(0, value - prior.get(key, 0)) for key, value in cost.items()}}
        self._settle_pending_stage_usage(stage["id"], namespaces={namespace})
        self._checkpoint(f"{stage['id']}:specialist_payment_settled", force=True)
        return cost

    def _paid_stage_specialist_usage(self, reports):
        total = {key: 0 for key in self.usage}
        for report in reports:
            if not isinstance(report, dict) or not isinstance(report.get("artifact_ref"), str):
                continue
            record = self.store.get(report["artifact_ref"])
            namespace = hashlib.sha256(canonical_bytes({"specialist_execution_ref": report["artifact_ref"],
                                                        "body_sha256": record["body_hash"]})).hexdigest()
            paid = self.stage_usage_totals.get(namespace, {})
            for key in total:
                current = (report.get("usage") or {}).get(key, 0)
                if type(current) in (int, float) and math.isfinite(current) and current >= 0:
                    total[key] += min(paid.get(key, 0), current)
        return total

    def _reconcile_interrupted_specialist_payments(self, stage, record):
        if not isinstance(record.get("attempt_id"), str) or not isinstance(record.get("assignment_plan_ref"), str):
            return
        attempt = self.tasks.get_attempt(record["attempt_id"])
        if attempt.get("state") not in {"started", "result_unknown"}:
            return
        plan_record, _, plan = self._read_verified_artifact_json(record["assignment_plan_ref"])
        if plan.get("input_ref", {}).get("ref") != record.get("task_id"):
            raise StateError("interrupted specialist plan does not own the aggregate attempt")
        rows = self.departments._assignment_task_rows(stage_id=stage["id"], attempt_number=record.get("attempt_number"))
        for row in rows:
            head = self.store.head(row["assignment_logical_id"] + "/execution")
            if head is not None:
                self._settle_stage_specialist_payment(stage, record["assignment_plan_ref"], head["artifact_ref"])

    def _publish_specialist_reports(self, stage, stage_assignment, bundle):
        """Persist each specialist's independent response in its own namespace."""
        if not bundle.get("model_enabled"):
            return bundle
        packet = bundle.get("packet") if isinstance(bundle.get("packet"), dict) else {}
        packet_digest = hashlib.sha256(canonical_bytes(packet)).hexdigest()
        updated = {}
        rows = [item for item in stage_assignment.get("assignments", [])
                if isinstance(item, dict) and item.get("assignment_phase") == "specialist"]
        reports = bundle.get("by_role", {})
        for row in rows:
            report = deepcopy(reports.get(row.get("role_id")))
            if not isinstance(report, dict):
                report = {
                    "status": "failed", "execution_mode": "model",
                    "assigned_role": row.get("assigned_role"), "role_id": row.get("role_id"),
                    "error": "specialist dispatcher returned no report", "usage": {},
                }
            body = {
                "schema_version": "specialist-execution-1",
                "project_id": self.workflow["project_id"],
                "stage_id": stage["id"], "stage_kind": stage["kind"],
                "attempt_number": stage_assignment.get("attempt_number"),
                "assigned_role": row.get("assigned_role"), "role_id": row.get("role_id"),
                "model_role": row.get("model_role"),
                "assignment_id": row.get("assignment_id"),
                "task_id": row.get("task_id"),
                "input_ref": row.get("input_ref"), "input_digest": packet_digest,
                "report": report,
                "created_at": now_iso(),
            }
            artifact = self._publish(
                f"{row['assignment_logical_id']}/execution", "report", body,
                row["assigned_role"],
            )
            report["artifact_ref"] = artifact["artifact_ref"]
            self._settle_specialist_execution_attempt(row, report)
            self._settle_stage_specialist_payment(stage, stage_assignment["plan_ref"], artifact["artifact_ref"])
            self._specialist_progress(stage["id"], {
                "event": "completed", "role": row.get("assigned_role"),
                "role_id": row.get("role_id"), "task_id": row.get("task_id"),
                "stage_id": stage["id"], "execution_mode": report.get("execution_mode"),
                "status": report.get("status"), "decision": report.get("decision"),
                "usage": report.get("usage", {}), "elapsed_seconds": report.get("elapsed_seconds"),
                "artifact_ref": report.get("artifact_ref"),
                "response_ref": self._specialist_file_ref(artifact),
                "error": report.get("error"),
            }, assignment=stage_assignment)
            updated[row.get("role_id")] = report
        bundle["by_role"] = updated
        bundle["reports"] = list(updated.values())
        bundle["usage"] = self._specialist_usage(bundle["reports"])
        return bundle

    def _settle_specialist_execution_attempt(self, assignment, report):
        """Close the provider-call attempt once its immutable result is durable."""
        attempt_id = assignment.get("attempt_id")
        if not isinstance(attempt_id, str) or not attempt_id:
            return
        try:
            attempt = self.tasks.get_attempt(attempt_id)
        except NotFoundError:
            return
        if attempt.get("state") != "started":
            return
        if report.get("provider_call_reused") is True:
            outcome, usage = "cancelled", {}
        elif report.get("status") in {"succeeded", "failed"}:
            outcome = report["status"]
            usage = report.get("usage") if isinstance(report.get("usage"), dict) else {}
        elif report.get("status") == "result_unknown":
            try:
                self.tasks.reconcile_unknown(attempt_id, "command.composer")
            except (NotFoundError, StateError):
                pass
            return
        else:
            return
        try:
            self.tasks.finish_attempt(attempt_id, outcome, usage=usage)
        except (NotFoundError, StateError):
            # A concurrent reconciliation may settle the attempt after the
            # artifact commit. The durable report remains the authority.
            return

    def _run_specialist_verifier(self, stage, stage_assignment, descriptor, bundle, chief_result,
                                 *, stage_result=None):
        """Run the queued adversary after producer calls and chief output exist."""
        model = self._specialist_model_config(stage, descriptor)
        if model is None or not isinstance(stage_assignment, dict):
            return None
        verifier = next((item for item in stage_assignment.get("assignments", [])
                         if isinstance(item, dict) and item.get("assignment_phase") == "verifier"), None)
        if verifier is None:
            return None
        verifier = deepcopy(verifier)
        deadline = time.monotonic() + self._stage_remaining(stage)

        def on_progress(event):
            self._specialist_progress(stage["id"], {
                **event,
                "assignment_attempt_number": stage_assignment.get("attempt_number"),
            }, assignment=stage_assignment)

        dispatcher = SpecialistDispatcher(
            model, provider_pools=self._specialist_provider_pools(descriptor),
            max_parallel=1, deadline=deadline,
            on_progress=on_progress,
        )
        # The verifier must see the same concrete stage result that the
        # producer specialists reviewed. ``chief_result`` is the stage
        # outcome/ledger projection and may omit or rewrite scientific fields;
        # using it as the sole packet source made a valid frontier seed plan
        # appear empty to the adversary.
        packet_source = stage_result if isinstance(stage_result, dict) else chief_result
        packet = self._specialist_stage_packet(stage, descriptor, stage_result=packet_source)
        if isinstance(stage_result, dict) and stage_result.get("repair_verification_scope"):
            packet["repair_verification_scope"] = stage_result["repair_verification_scope"]
        packet["chief_result"] = deepcopy(chief_result)
        reports = deepcopy(bundle.get("reports", []))
        assigned_roles = {item.get("role_id"): item for item in stage_assignment.get("assignments", [])
                          if isinstance(item, dict)}
        for report in reports:
            role = assigned_roles.get(report.get("role_id"), {})
            if role:
                report["input_scope"] = {"declared_fields": deepcopy(role.get("input_projection", [])),
                                         "assignment_phase": role.get("assignment_phase")}
        packet["specialist_reports"] = reports
        if stage.get("kind") == "topic_discovery":
            topic = (stage_result.get("topic")
                     if isinstance(stage_result, dict) else None)
            evolution = (stage_result.get("topic_evolution")
                         if isinstance(stage_result, dict) else None)
            refinement = self._topic_refinement_context(stage)
            parent = (refinement.get("parent_topic")
                      if isinstance(refinement, dict) else None)
            if (isinstance(topic, dict) and isinstance(evolution, dict)
                    and isinstance(evolution.get("parent_topic_id"), str)
                    and isinstance(parent, dict)):
                packet["topic_refinement_parent"] = deepcopy(parent)
                packet["topic_refinement_review_scope"] = (
                    "This assignment repairs the admitted research direction; it is not permission "
                    "to select a different phenomenon. Compare the candidate directly with "
                    "topic_refinement_parent. A refinement must preserve its phenomenon and the "
                    "core scientific identity of its question while changing only a supported "
                    "mechanism, observable, comparator, evidence boundary, or claim scope. Treat "
                    "a different field/phenomenon as a lineage failure, not as successful novelty. "
                    "The parent work orders and their evidence are acceptance requirements. Missing "
                    "full text or unresolved novelty can remain an explicit survey obligation; that "
                    "alone is not a reason to repeat topic generation."
                )
            elif (isinstance(topic, dict) and isinstance(evolution, dict)
                  and evolution.get("mode") == "pivot"):
                packet["topic_refinement_review_scope"] = (
                    "A pivot is admissible only when the packet contains independent evidence that "
                    "directly refutes the parent phenomenon or establishes that its evidence boundary "
                    "is infeasible. A failed generated program, response format, or validator is not "
                    "scientific refutation. Without that evidence, require an adjacent, parent-preserving "
                    "repair and do not accept an unrelated replacement."
                )
        verifier_quota = verifier.get("quota") if isinstance(verifier.get("quota"), dict) else {}
        context_limit = dispatcher.input_limit_for_role(
            verifier.get("model_role"), verifier_quota.get("max_input_tokens"))
        verifier["_prompt"] = build_verifier_prompt(
            stage, packet, reports, chief_result,
            max_input_tokens=context_limit)
        model_identity = {
            key: value for key, value in model.items()
            if key not in {"api_key", "api_token", "auth_env", "headers", "timeout_seconds"}
        }
        input_digest = hashlib.sha256(canonical_bytes({
            "system": VERIFIER_SYSTEM,
            "model_role": verifier.get("model_role"),
            "model": model_identity,
            "prompt": verifier["_prompt"],
        })).hexdigest()
        retained = self.departments.find_durable_verifier_report(
            stage["id"], stage_assignment.get("attempt_number"),
            input_digest=input_digest)
        if isinstance(retained, dict):
            report = deepcopy(retained["report"])
            prior_usage = report.get("usage")
            prior_usage = prior_usage if isinstance(prior_usage, dict) else {}
            report.update({
                "provider_call_reused": True,
                "reused_prior_usage": deepcopy(prior_usage),
                "usage": {
                    key: 0 for key, value in prior_usage.items()
                    if type(value) in (int, float) and math.isfinite(value) and value >= 0
                },
                "artifact_ref": retained["artifact_ref"],
                "assignment_plan_ref": stage_assignment["plan_ref"],
            })
            self._specialist_progress(stage["id"], {
                "event": "reused_durable_result",
                "role": verifier.get("assigned_role"),
                "role_id": verifier.get("role_id"),
                "task_id": verifier.get("task_id"),
                "stage_id": stage["id"],
                "assignment_attempt_number": stage_assignment.get("attempt_number"),
                "status": report.get("status"),
                "artifact_ref": retained["artifact_ref"],
                "usage": {},
            }, assignment=stage_assignment)
            return report
        verifier["quota"] = {**verifier_quota, "max_input_tokens": context_limit}
        # Attempt bookkeeping uses the control-store connection owned by the
        # Composer thread. Start it here, before dispatch enters worker threads;
        # the live progress callback must remain file-only and thread-safe.
        self.departments.start_verifier_attempt(verifier)
        result = self._dispatch_specialist_work(dispatcher, [verifier], packet, verifier=True)
        report = result[0] if result else {
            "status": "failed", "error": "verifier dispatcher returned no report", "usage": {},
        }
        body = {
            "schema_version": "specialist-verifier-execution-1",
            "project_id": self.workflow["project_id"],
            "stage_id": stage["id"], "stage_kind": stage["kind"],
            "attempt_number": stage_assignment.get("attempt_number"),
            "input_digest": input_digest,
            "initial_review_input": {
                "system": VERIFIER_SYSTEM, "prompt": verifier["_prompt"],
                "prompt_sha256": hashlib.sha256(verifier["_prompt"].encode("utf-8")).hexdigest(),
            },
            "assigned_role": verifier.get("assigned_role"), "role_id": verifier.get("role_id"),
            "model_role": verifier.get("model_role"),
            "assignment_id": verifier.get("assignment_id"), "task_id": verifier.get("task_id"),
            "chief_result": chief_result, "specialist_reports": bundle.get("reports", []),
            "report": report, "created_at": now_iso(),
        }
        artifact = self._publish(
            f"{verifier['assignment_logical_id']}/execution", "report", body,
            verifier["assigned_role"],
        )
        report["artifact_ref"] = artifact["artifact_ref"]
        report["assignment_plan_ref"] = stage_assignment["plan_ref"]
        self._settle_stage_specialist_payment(stage, stage_assignment["plan_ref"], artifact["artifact_ref"])
        self._specialist_progress(stage["id"], {
            "event": "completed", "role": verifier.get("assigned_role"),
            "role_id": verifier.get("role_id"), "task_id": verifier.get("task_id"),
            "stage_id": stage["id"], "model_role": verifier.get("model_role"),
            "execution_mode": report.get("execution_mode"), "status": report.get("status"),
            "decision": (report.get("response") or {}).get("decision") if isinstance(report.get("response"), dict) else None,
            "usage": report.get("usage", {}), "elapsed_seconds": report.get("elapsed_seconds"),
            "artifact_ref": report.get("artifact_ref"),
            "response_ref": self._specialist_file_ref(artifact),
            "error": report.get("error"),
        }, assignment=stage_assignment)
        return report

    def _stage_input_files(self, stage, descriptor, *, include_dependencies=True):
        """Fingerprint declared input files, including images and bound packages."""
        files = {}
        def visit(value, key="", *, destinations=False, base=None):
            if isinstance(value, dict):
                for name, item in value.items():
                    visit(item, name, destinations=destinations, base=base)
            elif isinstance(value, list):
                for item in value:
                    visit(item, key, destinations=destinations, base=base)
            elif (isinstance(value, str)
                  and (key.endswith(("_path", "_file", "_files"))
                       or key in {"path", "images", "results_package"})
                  and not key.endswith("budget_path")
                  and not (destinations and key in {"output_path", "preflight_path"})):
                path = Path(value)
                if not path.is_absolute():
                    if base is None:
                        return
                    path = base / path
                path = path.resolve()
                if not path.is_file() or str(path) in files:
                    return
                body = path.read_bytes()
                files[str(path)] = hashlib.sha256(body).hexdigest()
                if path.suffix == ".json":
                    try:
                        nested = json.loads(body)
                    except (ValueError, UnicodeDecodeError):
                        return
                    visit(nested, destinations=True, base=path.parent)
        visit(descriptor, destinations=True)
        if include_dependencies:
            for dependency in stage["depends_on"]:
                visit(self.context.get(dependency))
        for binding in stage.get("bindings", []):
            visit(self._source_value(binding["source"]), binding["target"].rsplit(".", 1)[-1])
        return files

    @staticmethod
    def _stage_runtime_revision():
        """Bind stage admission to the implementation of its execution contract.

        Model-work caches retain their evidence/input identities separately;
        changing runtime validation must not discard successful source work.
        """
        root = Path(__file__).resolve().parent.parent
        digest = hashlib.sha256()
        for directory in ("core", "runtime"):
            for path in sorted((root / directory).rglob("*.py")):
                digest.update(str(path.relative_to(root)).encode())
                digest.update(hashlib.sha256(path.read_bytes()).digest())
        return digest.hexdigest()

    def _run_stage(self, stage, *, attempt_number=1, specialist_reports=None,
                   stage_assignment=None):
        """Reuse completed production when only an outer reviewer failed."""
        descriptor = json.loads(Path(stage["config_path"]).read_text())
        files = self._stage_input_files(stage, descriptor)
        packet = {
            "descriptor": descriptor, "files": files,
            "dependencies": {key: self.context.get(key) for key in stage["depends_on"]},
            "work_orders": self._requests_for_stage(stage),
            "specialists": [{key: report.get(key) for key in ("assigned_role", "status", "response")}
                            for report in specialist_reports or []],
            "progression_policy": self.workflow.get("progression_policy", "evidence_first"),
            "runtime_revision": self._stage_runtime_revision(),
        }
        if stage["kind"] == "survey" and self.context.get(stage["id"], {}).get("revalidation_admission_ref"):
            context = self.context[stage["id"]]
            retained_project = self.stage_records.get(stage["id"], {}).get("project_dir") or context.get("project_dir") or stage["project_dir"]
            recovery = self._survey_revalidation_recovery({**stage, "project_dir": retained_project})
            receipt = self.store.get(context["revalidation_admission_ref"])
            if recovery is None or receipt.get("author") != "command.composer":
                raise StateError("survey stage cache has no owned revalidation admission")
            packet["revalidation_admission"] = {"ref": receipt["artifact_ref"], "body_sha256": receipt["body_hash"]}
        if stage["kind"] == "topic_discovery":
            packet["topic_history"] = self._topic_history_context()
            # Topic intake is a sampling boundary, not a deterministic
            # transformation.  A bounded attempt can reject one portfolio
            # while the next attempt deliberately changes its seed and
            # candidate history.  If those attempts share the ordinary stage
            # cache key, a prior ``blocked`` projection can cancel the new
            # specialist review before the topic runner makes a call.
            packet["topic_exploration_boundary"] = {
                "continuation_cycle": self.continuation_cycles,
                "attempt_number": attempt_number,
            }
        elif stage["id"] in self.reopened_stage_ids and self.continuation_cycles:
            # A reopened assignment is a new Composer work boundary even when
            # it deliberately reuses an upstream durable store (notably the
            # survey ledger).  Include that boundary in the stage cache key so
            # a prior blocked envelope cannot short-circuit the scoped repair
            # before the runner gets a chance to use its retained evidence.
            packet["continuation_boundary"] = {
                "continuation_cycle": self.continuation_cycles,
                "attempt_number": attempt_number,
            }
        cache = ModelWorkCache(self.store, self._publish)
        key = cache.key(scope=f"stage:{stage['id']}", role=stage["kind"],
                        system="checked-stage-output-1", prompt=packet, model={})
        retained = cache.get(key)
        if _report_has_model_call_failure(retained):
            retained = None
        if retained and retained.get("status") == "blocked":
            # A scientific recovery cycle is a new execution boundary.  The
            # old stage cache records why the previous program was rejected,
            # but must not prevent `_execute_stage` from materializing the
            # cycle-specific repair requested by the Composer.  Without this
            # distinction the specialist pool can repeat forever while the
            # actual experiment runner is never reached.
            recovery_context = self.context.get(stage["id"])
            scientific_recovery = (
                stage["kind"] in {"survey", "experiment", "topic_discovery"}
                and stage["id"] in self.reopened_stage_ids
                and bool(self.continuation_cycles)
                and isinstance(recovery_context, dict)
                and (
                    recovery_context.get("review_status")
                    in {"scientific_assignment_blocked", "topic_budget_exhausted",
                        "survey_handoff_incomplete"}
                    or (stage["kind"] == "survey"
                        and recovery_context.get("status") in STAGE_HOLD_STATUSES
                        and (isinstance(recovery_context.get("failure_recovery"), dict)
                             or recovery_context.get("handoff_repair_required") is True
                             or recovery_context.get("research_requests")))
                    or stage["kind"] == "topic_discovery"
                )
            )
            format_recovery = (
                isinstance(recovery_context, dict)
                and recovery_context.get("format_recovery") is True
                and recovery_context.get("format_recovery_dispatched") is not True
            )
            if not scientific_recovery and not format_recovery:
                blocked = ModelWorkBlocked(retained["error"],
                                           failure_class=retained.get("failure_class"))
                if retained.get("failure_class") == "context_budget":
                    blocked.failure_class = "context_budget"
                    blocked.context_budget = deepcopy(retained.get("context_budget", {}))
                raise blocked
        if (retained and retained.get("status") == "succeeded"
                and Path(retained["result"]["output_path"]).is_file()
                and hashlib.sha256(Path(retained["result"]["output_path"]).read_bytes()).hexdigest()
                    == retained.get("output_sha256")):
            result = deepcopy(retained["result"])
            result.update(usage={}, reused_from=retained["cache_ref"])
            for name in ("foundry_usage", "repair_panel_usage"):
                if name in result:
                    result[name] = {}
            return result
        try:
            result = self._execute_stage(
                stage, attempt_number=attempt_number,
                specialist_reports=specialist_reports,
                stage_assignment=stage_assignment)
            self._raise_stage_failure(result)
        except Exception as exc:
            # A provider reset is a time boundary, not a failed scientific
            # revision. Scoped research holds likewise return work orders.
            from scisaurus.runtime.capability_foundry import CapabilityDeadlineError
            if self._is_operational_stage_failure(exc):
                raise
            if isinstance(exc, (ModelCallError, QuotaExceededError, *PROVIDER_OPERATOR_STOP_ERRORS, ProviderCooldownError, CapabilityDeadlineError,
                                ComposerHardDeadlineExceeded, ComposerStageDeadlineExceeded)) or (
                    isinstance(exc, ModelCallError) and exc.status_code == 429):
                raise
            if stage["kind"] == "topic_discovery":
                self._normalize_topic_intake_failure(exc, stage)
                # Topic intake is an exploration boundary. Its runner already
                # records candidate/rejection traces and the Composer owns
                # the typed pivot to a fresh direction. Treating a rejected
                # topic as unchanged model work creates a misleading
                # ``Unchanged topic input failed`` cache entry, strips the
                # retry metadata from the original error after one repair,
                # and can cancel a valid next intake before it starts.
                # Never cache a topic-stage failure as generic model work.
                raise
            if isinstance(exc, ModelContextBudgetError):
                failures = (retained or {}).get("failed_attempts", 0) + 1
                budget = {
                    key: deepcopy(getattr(exc, key, None)) for key in (
                        "model", "estimated_input_tokens", "allowed_input_tokens",
                        "context_window_tokens", "max_input_tokens",
                        "max_output_tokens", "image_count",
                    )
                }
                error = (
                    f"stage {stage['id']} input projection cannot fit the selected model: "
                    f"{exc}")
                cache.put(key, {
                    "status": "blocked", "failed_attempts": failures,
                    "failure_class": "context_budget", "context_budget": budget,
                    "error": error,
                })
                blocked = ModelWorkBlocked(error)
                blocked.failure_class = "context_budget"
                blocked.context_budget = budget
                self._copy_error_accounting(exc, blocked)
                if getattr(exc, "capability_repair_panel_completed", False):
                    blocked.capability_repair_panel_completed = True
                if getattr(exc, "capability_repair_panel_attempted", False):
                    blocked.capability_repair_panel_attempted = True
                raise blocked from exc
            failures = (retained or {}).get("failed_attempts", 0) + 1
            limit = ((descriptor.get("limits") or {}).get("max_rounds")
                     or self._retry_policy().get("max_attempts") or 3)
            exhausted = isinstance(exc, ModelWorkBlocked) or failures >= limit
            error = f"Unchanged {stage['id']} input failed {failures} time(s): {type(exc).__name__}: {exc}"
            cache.put(key, {"status": "blocked" if exhausted else "repairing",
                            "failed_attempts": failures, "error": error,
                            "failure_class": getattr(exc, "failure_class", None)})
            if exhausted:
                blocked = ModelWorkBlocked(error)
                for attribute in (
                        "failure_class", "recovery_mode", "repair_gate",
                        "repair_attempts", "repair_ledger", "repair_feedback",
                        "model_diagnostics", "capability_repair_panel_completed",
                        "capability_repair_panel_attempted", "repair_subject"):
                    if hasattr(exc, attribute):
                        setattr(blocked, attribute, deepcopy(getattr(exc, attribute)))
                for attribute in ("research_argument", "research_review", "research_feedback",
                                  "research_response", "research_review_argument_sha256"):
                    value = getattr(exc, attribute, None)
                    if value is not None:
                        setattr(blocked, attribute, deepcopy(value))
                self._copy_error_accounting(exc, blocked)
                stage_result = getattr(exc, "stage_result", None)
                if isinstance(stage_result, dict):
                    blocked.stage_result = deepcopy(stage_result)
                raise blocked from exc
            raise
        if result.get("status") in STAGE_READY_STATUSES:
            cache.put(key, {"status": "succeeded", "result": result,
                           "output_sha256": hashlib.sha256(Path(result["output_path"]).read_bytes()).hexdigest()})
        return result

    @staticmethod
    def _raise_stage_failure(result):
        """Preserve recoverability and resource accounting across runner boundaries."""
        failure = result.get("failure") or {}
        if failure.get("kind") == "provider_cooldown":
            error = ProviderCooldownError(result.get("error") or "stage provider is cooling down",
                retry_after_seconds=failure["retry_after_seconds"], rate_limit=failure.get("rate_limit"))
        elif failure.get("kind") == "provider_configuration":
            error = ProviderConfigurationError(
                result.get("error") or "stage provider configuration is unavailable",
                provider=failure.get("provider"),
                credential_env=failure.get("credential_env"),
            )
        elif failure.get("kind") == "provider_rate_limit":
            error = ProviderRateLimitError(
                result.get("error") or "stage provider rejected work with a rate limit",
                provider=failure.get("provider"), details=failure.get("details"),
            )
            error.stage_result = deepcopy(result)
        elif failure.get("kind") == "quota_exceeded":
            error = QuotaExceededError(
                result.get("error") or "stage execution quota exhausted",
                dimension=failure.get("dimension"), limit=failure.get("limit"),
                observed=failure.get("observed"), usage=result.get("usage"),
                diagnostics=failure.get("diagnostics"),
            )
            error.stage_result = deepcopy(result)
            if isinstance(failure.get("dispatch_failures"), list):
                error.dispatch_failures = deepcopy(failure["dispatch_failures"])
        elif failure.get("kind") == "model_call":
            error = ModelCallError.from_failure(
                result.get("error") or "stage model request failed", failure)
            error.stage_result = deepcopy(result)
        elif failure.get("kind") == "unchanged_assignment_exhausted":
            error = ModelWorkBlocked(result.get("error") or "unchanged stage assignment exhausted",
                                     failure_class=failure.get("failure_class"))
            # The runner still returned its complete scientific envelope.  Do
            # not reduce an exhausted model-contract retry to a bare string;
            # the Composer's failure panel needs the observed refs and gate
            # state to issue a useful repair order.
            error.stage_result = deepcopy(result)
            error.failure_scope = "stage"
        elif failure.get("kind") == "operational_state":
            error = StateError(result.get("error") or "stage lifecycle prerequisite failed")
            error.stage_result = deepcopy(result)
        elif failure.get("kind") == "process_interrupted":
            raise KeyboardInterrupt(result.get("error") or "stage process interrupted")
        else:
            status = result.get("status") if isinstance(result, dict) else None
            if status in STAGE_READY_STATUSES | STAGE_HOLD_STATUSES:
                return
            # Stage runners return their complete durable run record even when
            # the scientific output is unusable.  Raising a plain string here
            # discarded that record and made the Composer retry the same input
            # without first inspecting the observations, source, and checks.
            error = ValidationError(
                result.get("error") or f"stage returned non-admissible status: {status}")
            error.stage_result = deepcopy(result)
            error.failure_scope = "stage"
        usage = result.get("usage")
        error.usage = deepcopy(usage) if isinstance(usage, dict) else {}
        for name in ("foundry_usage", "repair_panel_usage"):
            owned_usage = result.get(name)
            if isinstance(owned_usage, dict):
                setattr(error, name, deepcopy(owned_usage))
        # Producer usage excludes the already settled Methods invoice. Failed
        # attempts retain its full cost while settlement subtracts its owner.
        for key, value in getattr(error, "repair_panel_usage", {}).items():
            error.usage[key] = error.usage.get(key, 0) + value
        error.usage_is_snapshot = result.get("usage_is_snapshot", False)
        raise error

    def _failure_program_snapshot(self, stage, *, topic_context=None):
        """Read only the generated program bound to the selected topic.

        The snapshot is evidence for the repair panel, not an executable
        instruction.  Capability descriptors pin both source files through
        ``environment_files``; only files from the selected topic's matching
        capability are copied into the bounded dossier.
        """
        if not isinstance(stage, dict) or stage.get("kind") != "experiment":
            return []
        if topic_context is None:
            try:
                topic_match = self._topic_context_for_stage(stage)
            except ValidationError:
                return []
            if not topic_match:
                return []
            _, topic_context = topic_match
        if not isinstance(topic_context, dict):
            return []
        selected = topic_context.get("topic")
        if not isinstance(selected, dict):
            return []
        selected_question = selected.get("research_question")
        selected_capability_id = selected.get("experiment_capability_id")
        if not isinstance(selected_question, str) or not selected_question.strip():
            return []
        generated = topic_context.get("generated_capability")
        if not isinstance(generated, dict):
            return []
        generated_id = generated.get("capability_id")
        descriptor_path = generated.get("descriptor_path")
        if not isinstance(descriptor_path, str):
            return []
        try:
            descriptor = json.loads(Path(descriptor_path).read_text())
        except (OSError, TypeError, ValueError):
            return []
        experiment = descriptor.get("experiment") if isinstance(descriptor, dict) else None
        expected_study_id = self._stage_experiment_study_id(stage)
        if (not isinstance(experiment, dict)
                or experiment.get("research_question") != selected_question
                or not isinstance(generated_id, str)
                or (isinstance(selected_capability_id, str)
                    and (generated_id != selected_capability_id
                         or experiment.get("id") != (
                             expected_study_id
                             if isinstance(expected_study_id, str)
                             else selected_capability_id)))):
            return []
        descriptors = [Path(descriptor_path)]
        paths = []
        for descriptor_path in descriptors:
            try:
                descriptor = json.loads(descriptor_path.read_text())
            except (OSError, ValueError, TypeError):
                continue
            experiment = descriptor.get("experiment") if isinstance(descriptor, dict) else None
            if not isinstance(experiment, dict):
                continue
            for capability_name in ("execution", "validation"):
                capability = experiment.get(capability_name)
                if not isinstance(capability, dict):
                    continue
                for value in capability.get("environment_files", []):
                    if isinstance(value, str):
                        paths.append(Path(value))
                command = capability.get("client", {}).get("command", [])
                if isinstance(command, list):
                    paths.extend(Path(value) for value in command[1:]
                                  if isinstance(value, str) and value.endswith(".py"))
        snapshots = []
        seen = set()
        for path in paths:
            try:
                resolved = path.resolve(strict=True)
            except (OSError, RuntimeError):
                continue
            if str(resolved) in seen or not resolved.is_file():
                continue
            seen.add(str(resolved))
            try:
                body = resolved.read_bytes()
            except OSError:
                continue
            limit = 30000
            snapshots.append({
                "path": str(resolved),
                "sha256": hashlib.sha256(body).hexdigest(),
                "size_bytes": len(body),
                "source": body[:limit].decode("utf-8", "replace"),
                "source_truncated": len(body) > limit,
            })
            if len(snapshots) >= 4:
                break
        return snapshots

    def _read_verified_artifact_json(self, ref):
        manifest = self.store.get(ref)
        body_hash = manifest.get("body_hash")
        body = self.store.read_body(body_hash)
        actual_hash = hashlib.sha256(body).hexdigest()
        if actual_hash != body_hash:
            raise ValueError("artifact body does not match its manifest hash")
        value = json.loads(body)
        if not isinstance(value, dict):
            raise ValueError("artifact body is not a JSON object")
        return manifest, actual_hash, value

    def _legacy_plan_repair_subject(self, stage_id, dossier_ref, dossier):
        """Recover a plan's input subject from its completed, owned Methods receipt."""
        observed = dossier.get("observed_result")
        if isinstance(observed, dict) and observed.get("execution_refs"):
            return None
        record = self.stage_records.get(stage_id, {})
        attempts = [*record.get("attempts", []), record]
        owners = {item.get("attempt_id") for item in attempts
                  if isinstance(item, dict) and item.get("failure_dossier_ref") == dossier_ref
                  and item.get("attempt_id")}
        if len(owners) != 1:
            return None
        owner = self.tasks.get_attempt(next(iter(owners)))
        start = datetime.fromisoformat(owner["created_at"]).timestamp()
        end = (datetime.fromisoformat(owner["finished_at"]).timestamp()
               if owner.get("finished_at") else None)
        if end is None:
            return None
        subjects = []
        verdict_rows = self.control._conn.execute(
            "SELECT artifact_ref,created_at FROM artifacts WHERE logical_id LIKE "
            "'command/departments/methods/assignments/%/verifier-adversarial-reviewer'").fetchall()
        for row in verdict_rows:
            completed = datetime.fromisoformat(row["created_at"]).timestamp()
            if not start <= completed <= end:
                continue
            _, _, verdict = self._read_verified_artifact_json(row["artifact_ref"])
            if (verdict.get("schema_version") != "department-adversarial-verdict-1"
                    or verdict.get("verdict") != "hold"
                    or verdict.get("attempt_state") != "succeeded"):
                continue
            namespace, logical_name, _ = parse_ref(row["artifact_ref"])
            plan_logical_id = namespace + "/" + logical_name.rsplit("/", 1)[0] + "/plan"
            plan_rows = self.control._conn.execute(
                "SELECT artifact_ref FROM artifacts WHERE logical_id=?", (plan_logical_id,)).fetchall()
            plans = []
            for plan_row in plan_rows:
                plan_manifest, _, plan = self._read_verified_artifact_json(plan_row["artifact_ref"])
                created = datetime.fromisoformat(plan_manifest["created_at"]).timestamp()
                input_ref = plan.get("input_ref")
                if (start <= created <= completed
                        and isinstance(input_ref, dict)
                        and input_ref.get("kind") == "capability_repair_panel"
                        and input_ref.get("stage_id") == stage_id):
                    plans.append(plan)
            if not plans:
                continue
            if len(plans) != 1:
                raise ValidationError("Methods repair subject has ambiguous plan ownership")
            plan = plans[0]
            input_ref = plan["input_ref"]
            chief_manifest, _, chief = self._read_verified_artifact_json(verdict["chief_synthesis_ref"])
            chief_created = datetime.fromisoformat(chief_manifest["created_at"]).timestamp()
            identity_keys = ("stage_id", "attempt_number", "department", "project_id")
            if (not start <= chief_created <= completed
                    or chief.get("schema_version") != "department-chief-synthesis-1"
                    or chief.get("outcome") != "completed"
                    or any(plan.get(key) != chief.get(key) or plan.get(key) != verdict.get(key)
                           for key in identity_keys)
                    or chief.get("assignment_refs") != verdict.get("assignment_refs")):
                raise ValidationError("Methods repair subject has inconsistent completion evidence")
            planned_assignments = {item.get("assignment_id"): item for item in plan.get("assignments", [])
                                   if isinstance(item, dict)}
            for assignment_ref in chief.get("assignment_refs", []):
                _, _, assignment = self._read_verified_artifact_json(assignment_ref)
                if assignment.get("role_id") != "methodologist":
                    continue
                planned = planned_assignments.get(assignment.get("assignment_id"))
                if (not isinstance(planned, dict) or planned.get("role_id") != "methodologist"
                        or planned.get("task_id") != assignment.get("task_id")
                        or assignment.get("input_ref") != input_ref
                        or assignment.get("attempt_state") != "succeeded"
                        or assignment.get("stage_id") != plan.get("stage_id")):
                    raise ValidationError("Methods repair subject has inconsistent assignment evidence")
                execution_manifest, _, execution = self._read_verified_artifact_json(assignment["execution_artifact_ref"])
                execution_created = datetime.fromisoformat(execution_manifest["created_at"]).timestamp()
                if (execution.get("schema_version") != "specialist-execution-1"
                        or execution.get("input_ref") != input_ref
                        or not isinstance(execution.get("input_digest"), str)
                        or not re.fullmatch(r"[0-9a-f]{64}", execution["input_digest"])
                        or not start <= execution_created <= chief_created
                        or any(execution.get(key) != assignment.get(key)
                               for key in ("assignment_id", "task_id", "role_id", "stage_id"))
                        or any(execution.get(key) != plan.get(key)
                               for key in ("attempt_number", "project_id"))):
                    raise ValidationError("Methods repair subject has inconsistent execution evidence")
                for request in execution.get("report", {}).get("request_inputs", []):
                    inputs = request.get("input") if isinstance(request, dict) else None
                    if not isinstance(inputs, dict) or not isinstance(inputs.get("prompt"), str):
                        continue
                    payload = json.loads(inputs["prompt"])
                    packet = payload.get("repair_adjudication_packet") if isinstance(payload, dict) else None
                    lineage = packet.get("failure_lineage") if isinstance(packet, dict) else None
                    if not isinstance(lineage, dict):
                        continue
                    if (lineage.get("stage_id") != stage_id
                            or lineage.get("identity_verified") is not True
                            or lineage.get("adjudication_packet_input_sha256") != input_ref["digest"]):
                        raise ValidationError("Methods repair subject has inconsistent input evidence")
                    subjects.append({
                        "stage_id": stage_id,
                        "failure_dossier_ref": lineage.get("failure_dossier_ref"),
                        "attempt_number": lineage.get("failed_stage_attempt_number"),
                        "failure_input_sha256": lineage.get("failed_stage_input_sha256"),
                        "failure_dossier_body_sha256": lineage.get("failure_dossier_body_sha256"),
                    })
        unique = {canonical_bytes(subject): subject for subject in subjects}
        if len(unique) > 1:
            raise ValidationError("Methods repair subject has ambiguous input evidence")
        return next(iter(unique.values()), None)

    def _failure_dossier_evidence(self, artifact_ref, *, expected_stage_id=None,
                                  expected_attempt_number=None, _visited=None):
        """Resolve a failed attempt's immutable evidence for bounded review.

        A reference alone is not review evidence: specialist workers cannot
        dereference the Composer artifact store. Verify artifact bodies and
        attempt identity before exposing their contents. Preserve complete,
        hash-checked executor and validator sources as bounded prompt chunks;
        ordinary prompt text limits otherwise silently remove the code needed
        to diagnose and repair the failure.
        """
        if not isinstance(artifact_ref, str) or not artifact_ref.strip():
            return None

        visited = set(_visited or ())
        if artifact_ref in visited:
            raise ValidationError("Methods repair subject contains a cyclic dossier reference")
        visited.add(artifact_ref)
        read_verified_json = self._read_verified_artifact_json

        try:
            manifest, dossier_body_hash, dossier = read_verified_json(artifact_ref)
        except (NotFoundError, KeyError, OSError, TypeError, ValueError, ValidationError):
            return {
                "artifact_ref": artifact_ref,
                "available": False,
                "reason": "The immutable failure dossier could not be resolved and hash-verified.",
            }

        dossier_stage_id = dossier.get("stage_id")
        dossier_attempt_number = dossier.get("attempt_number")
        stage_record = (self.stage_records.get(expected_stage_id)
                        if isinstance(expected_stage_id, str) else None)
        attempt_records = (stage_record.get("attempts", [])
                           if isinstance(stage_record, dict) else [])
        if not isinstance(attempt_records, list):
            attempt_records = []
        if isinstance(stage_record, dict):
            attempt_records = [*attempt_records, stage_record]
        authoritative_attempts = [
            item for item in attempt_records
            if isinstance(item, dict)
            and item.get("failure_dossier_ref") == artifact_ref
            and type(item.get("attempt_number")) is int
        ]
        authoritative_numbers = {
            item["attempt_number"] for item in authoritative_attempts
        }
        if (expected_stage_id is None or dossier_stage_id != expected_stage_id
                or len(authoritative_numbers) != 1):
            return {
                "artifact_ref": artifact_ref,
                "available": False,
                "reason": "The failure dossier is not bound to one authoritative stage attempt.",
                "observed_stage_id": dossier_stage_id,
                "observed_attempt_number": dossier_attempt_number,
            }
        authoritative_attempt_number = next(iter(authoritative_numbers))
        if (dossier_attempt_number != authoritative_attempt_number
                or (expected_attempt_number is not None
                    and expected_attempt_number != authoritative_attempt_number)):
            return {
                "artifact_ref": artifact_ref,
                "available": False,
                "reason": "The failure dossier identity does not match the failed stage attempt.",
                "observed_stage_id": dossier_stage_id,
                "observed_attempt_number": dossier_attempt_number,
                "authoritative_attempt_number": authoritative_attempt_number,
            }
        expected_attempt_number = authoritative_attempt_number

        foundry = dossier.get("foundry_work_snapshot")
        foundry = foundry if isinstance(foundry, dict) else {}
        dossier_attempt = foundry.get("last_attempt")
        dossier_attempt = dossier_attempt if isinstance(dossier_attempt, dict) else {}
        foundry_cache_ref = foundry.get("cache_ref")
        foundry_cache = {}
        foundry_cache_manifest = None
        foundry_cache_body_hash = None
        foundry_cache_error = None
        foundry_cache_identity_verified = False
        if isinstance(foundry_cache_ref, str) and foundry_cache_ref.strip():
            try:
                (foundry_cache_manifest, foundry_cache_body_hash,
                 foundry_cache) = read_verified_json(foundry_cache_ref)
            except (NotFoundError, KeyError, OSError, TypeError, ValueError, ValidationError):
                foundry_cache = {}
                foundry_cache_manifest = None
                foundry_cache_error = "The linked foundry-work artifact could not be resolved and hash-verified."
        cached_attempt = foundry_cache.get("last_attempt")
        if isinstance(foundry_cache_manifest, dict) and isinstance(cached_attempt, dict):
            dossier_intent = dossier_attempt.get("experiment_intent")
            cached_intent = cached_attempt.get("experiment_intent")
            dossier_integrity = dossier_attempt.get("source_integrity")
            dossier_integrity = dossier_integrity if isinstance(dossier_integrity, dict) else {}
            try:
                linked_sources_match = (
                    isinstance(dossier_intent, dict)
                    and isinstance(cached_intent, dict)
                    and canonical_bytes(dossier_intent) == canonical_bytes(cached_intent)
                )
            except (TypeError, ValueError):
                linked_sources_match = False
            for source_key, integrity_key in (
                    ("executor_source", "executor"), ("validator_source", "validator")):
                cache_source = cached_attempt.get(source_key)
                dossier_source = dossier_attempt.get(source_key)
                expected = dossier_integrity.get(integrity_key)
                expected = expected.get("sha256") if isinstance(expected, dict) else None
                if not isinstance(cache_source, str):
                    linked_sources_match = False
                    break
                if isinstance(expected, str):
                    source_matches = hashlib.sha256(
                        cache_source.encode("utf-8")).hexdigest() == expected
                else:
                    source_matches = (
                        isinstance(dossier_source, str) and cache_source == dossier_source
                    )
                if not source_matches:
                    linked_sources_match = False
                    break
            if linked_sources_match:
                foundry_cache_identity_verified = True
            else:
                foundry_cache = {}
                foundry_cache_manifest = None
                foundry_cache_body_hash = None
                cached_attempt = None
                foundry_cache_error = (
                    "The linked foundry-work artifact does not match the failed attempt's "
                    "experiment intent and executor/validator digests."
                )
        last_attempt = cached_attempt if isinstance(cached_attempt, dict) else dossier_attempt
        integrity = dossier_attempt.get("source_integrity")
        integrity = integrity if isinstance(integrity, dict) else {}
        source_files = {}
        for source_name in ("executor_source", "validator_source"):
            source = last_attempt.get(source_name)
            source_origin = "foundry_work_cache" if isinstance(cached_attempt, dict) else "failure_dossier"
            if not isinstance(source, str):
                source = dossier_attempt.get(source_name)
                source_origin = "failure_dossier"
            record = integrity.get(
                "executor" if source_name == "executor_source" else "validator")
            record = record if isinstance(record, dict) else {}
            expected_sha256 = record.get("sha256")
            source_entry = {
                "available": False,
                "source_origin": source_origin,
                "expected_sha256": expected_sha256,
                "matches_expected": None,
                "integrity_verified": False,
                "source_truncated": False,
                "source_chunks": [],
            }
            if isinstance(source, str):
                source_sha256 = hashlib.sha256(source.encode("utf-8")).hexdigest()
                source_truncated = len(source) > CAPABILITY_REPAIR_SOURCE_CHARS
                matches_expected = (
                    source_sha256 == expected_sha256
                    if isinstance(expected_sha256, str) else None
                )
                source_entry.update({
                    "source_sha256": source_sha256,
                    "source_characters": len(source),
                    "matches_expected": matches_expected,
                    "integrity_verified": matches_expected is True,
                    "source_truncated": source_truncated,
                })
                if matches_expected is False:
                    source_entry["omission_reason"] = (
                        "Stored source does not match the immutable source-integrity digest."
                    )
                elif source_truncated:
                    source_entry["omission_reason"] = (
                        "Stored source exceeds the bounded repair-prompt source size."
                    )
                else:
                    safe_source = redact_sensitive_text(source)
                    source_entry.update({
                        "available": True,
                        "prompt_source_sha256": hashlib.sha256(
                            safe_source.encode("utf-8")).hexdigest(),
                        "prompt_source_characters": len(safe_source),
                        "redaction_applied": safe_source != source,
                        "source_chunks": [
                            safe_source[offset:offset + 7000]
                            for offset in range(0, len(safe_source), 7000)
                        ],
                    })
            source_files[source_name.removesuffix("_source")] = source_entry

        observed = dossier.get("observed_result")
        if isinstance(observed, dict):
            observed = {key: observed.get(key) for key in (
                "status", "error", "usage", "raw_results", "derived_results",
                "execution_manifest", "input_digests", "execution_refs",
                "raw_results_sha256", "derived_results_sha256") if key in observed}

        response = foundry_cache.get("last_response")
        if isinstance(response, dict):
            response = {key: response.get(key) for key in (
                "model", "finish_reason", "request_attempts", "elapsed_seconds", "usage")
                        if key in response}
            response["text_characters"] = len(
                foundry_cache.get("last_response", {}).get("text", "")
                if isinstance(foundry_cache.get("last_response", {}).get("text"), str)
                else "")
        else:
            response = None

        dossier_input_sha256 = dossier.get("input_sha256")

        def belongs_to_failed_attempt(value):
            return not failure_evidence_lineage_conflicts(
                value,
                attempt_number=dossier_attempt_number,
                input_sha256=dossier_input_sha256,
                dossier_ref=artifact_ref,
                stage_id=dossier_stage_id,
            )["conflicts"]

        all_directives = dossier.get("review_directives", [])
        if not isinstance(all_directives, list):
            all_directives = []
        directives = [item for item in all_directives if belongs_to_failed_attempt(item)]
        omitted_directive_lineage_count = len(all_directives) - len(directives)
        compact_directives = []
        seen_directives = set()
        for directive in directives:
            text = directive.get("text") if isinstance(directive, dict) else directive
            if not isinstance(text, str):
                continue
            text = redact_sensitive_text(text.strip())
            if not text or text in seen_directives:
                continue
            seen_directives.add(text)
            compact_directives.append(text[:900] + ("...[truncated]" if len(text) > 900 else ""))
            if len(compact_directives) >= 8:
                break

        all_repair_commands = dossier.get("repair_commands", [])
        if not isinstance(all_repair_commands, list):
            all_repair_commands = []
        repair_commands = [
            item for item in all_repair_commands if belongs_to_failed_attempt(item)
        ]
        omitted_repair_command_lineage_count = (
            len(all_repair_commands) - len(repair_commands)
        )
        all_acceptance_checks = dossier.get("acceptance_checks", [])
        if not isinstance(all_acceptance_checks, list):
            all_acceptance_checks = []
        acceptance_checks = [
            item for item in all_acceptance_checks if belongs_to_failed_attempt(item)
        ]
        omitted_acceptance_check_lineage_count = (
            len(all_acceptance_checks) - len(acceptance_checks)
        )

        evidence = {
            "artifact_ref": artifact_ref,
            "artifact_body_sha256": dossier_body_hash,
            "available": True,
            "stage_id": dossier_stage_id,
            "attempt_number": dossier_attempt_number,
            "failure_class": dossier.get("failure_class"),
            "input_sha256": dossier.get("input_sha256"),
            "error": dossier.get("error"),
            "observed_result": observed,
            "acceptance_checks": acceptance_checks,
            "repair_commands": repair_commands,
            "review_directives": compact_directives,
            "review_directives_omitted_count": max(
                0, len(directives) - len(compact_directives)),
            "provenance_exclusions": {
                "review_directive_lineage_conflicts": omitted_directive_lineage_count,
                "repair_command_lineage_conflicts": omitted_repair_command_lineage_count,
                "acceptance_check_lineage_conflicts": omitted_acceptance_check_lineage_count,
            },
            "experiment_intent": last_attempt.get("experiment_intent"),
            "candidate_input_sha256": hashlib.sha256(canonical_bytes({
                key: last_attempt.get(key) for key in (
                    "experiment_intent", "runtime", "test_input", "source_integrity")})).hexdigest(),
            "validation_context_sha256": hashlib.sha256(canonical_bytes(
                foundry_cache.get("validation_context"))).hexdigest(),
            "topic_identity": {key: foundry.get(key) for key in (
                "topic_id", "research_question", "domain")},
            "source_integrity": integrity,
            "source_files": source_files,
            "runtime": last_attempt.get("runtime"),
            "test_input": last_attempt.get("test_input"),
            "program_snapshot": dossier.get("program_snapshot", []),
            "prior_foundry_feedback": foundry.get("feedback"),
            "foundry_work_artifact_ref": foundry_cache_ref,
            "foundry_work_body_sha256": foundry_cache_body_hash,
            "foundry_work_body_verified": isinstance(foundry_cache_manifest, dict),
            "foundry_work_identity_verified": foundry_cache_identity_verified,
            "foundry_work_unavailable_reason": foundry_cache_error,
            "foundry_status": foundry_cache.get("status"),
            "foundry_work_attempts": foundry_cache.get("attempts"),
            "repair_gate_counts": foundry_cache.get("repair_gate_counts"),
            "validation_feedback": foundry_cache.get("validation_feedback"),
            "validation_context": foundry_cache.get("validation_context"),
            "last_response": response,
            "repair_ledger": foundry_cache.get("repair_ledger", [])[-6:]
            if isinstance(foundry_cache.get("repair_ledger"), list) else [],
        }
        subject = dossier.get("repair_subject")
        if subject is None:
            subject = self._legacy_plan_repair_subject(
                dossier_stage_id, artifact_ref, dossier)
        if subject is not None:
            if (not isinstance(subject, dict) or subject.get("stage_id") != dossier_stage_id
                    or not isinstance(subject.get("failure_dossier_ref"), str)
                    or type(subject.get("attempt_number")) is not int
                    or subject["attempt_number"] >= dossier_attempt_number):
                raise ValidationError("Methods repair subject has invalid dossier identity")
            if dossier.get("repair_subject") is not None and (
                    dossier.get("repair_phase") != "pre_execution_plan_review"
                    or isinstance(observed, dict) and observed.get("execution_refs")
                    or bool(dossier_attempt)):
                raise ValidationError("Methods repair subject conflicts with newly produced candidate evidence")
            origin = self._failure_dossier_evidence(
                subject["failure_dossier_ref"], expected_stage_id=dossier_stage_id,
                expected_attempt_number=subject["attempt_number"], _visited=visited)
            if (not isinstance(origin, dict) or origin.get("available") is not True
                    or origin.get("input_sha256") != subject.get("failure_input_sha256")
                    or origin.get("artifact_body_sha256") != subject.get("failure_dossier_body_sha256")):
                raise ValidationError("Methods repair subject does not match its immutable dossier")
            if dossier.get("repair_subject") is None and any(
                    isinstance(last_attempt.get(name + "_source"), str)
                    for name in ("executor", "validator")):
                if (evidence["candidate_input_sha256"] != origin.get("candidate_input_sha256")
                        or foundry_cache_ref is not None and foundry_cache_ref != origin.get("foundry_work_artifact_ref")
                        or evidence.get("validation_context") is not None and (
                            evidence["validation_context_sha256"]
                            != origin.get("validation_context_sha256"))
                        or any(isinstance(last_attempt.get(name + "_source"), str) and (
                            item.get("available") is not True
                            or item.get("integrity_verified") is not True
                            or item.get("expected_sha256") != origin.get("source_files", {}).get(name, {}).get("expected_sha256")
                            or item.get("prompt_source_sha256") != origin.get("source_files", {}).get(name, {}).get("prompt_source_sha256"))
                            for name, item in source_files.items())):
                    raise ValidationError("Methods repair subject conflicts with newly produced candidate evidence")
            for key in ("experiment_intent", "candidate_input_sha256", "validation_context_sha256",
                        "topic_identity", "source_integrity", "source_files",
                        "runtime", "test_input", "program_snapshot", "prior_foundry_feedback",
                        "foundry_work_artifact_ref", "foundry_work_body_sha256",
                        "foundry_work_body_verified", "foundry_work_identity_verified",
                        "foundry_work_unavailable_reason", "foundry_status", "foundry_work_attempts",
                        "repair_gate_counts", "validation_feedback", "validation_context", "repair_ledger"):
                evidence[key] = deepcopy(origin.get(key))
            evidence["repair_subject_lineage"] = deepcopy(
                origin.get("repair_subject_lineage", subject))
            evidence["scientific_failure_error"] = origin.get("scientific_failure_error", origin.get("error"))
            evidence["scientific_observed_result"] = deepcopy(
                origin.get("scientific_observed_result", origin.get("observed_result")))
        return self._capability_repair_projection(
            evidence, max_depth=7, max_keys=40, max_items=12, max_text=20_000)

    def _experiment_ancestor_stage_id(self, stage):
        """Find the experiment scope that can produce evidence for a later repair."""
        if not isinstance(stage, dict):
            return None
        by_id = {
            item.get("id"): item for item in self.workflow.get("stages", [])
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        }
        pending = list(stage.get("depends_on", []))
        seen = set()
        while pending:
            stage_id = pending.pop()
            if stage_id in seen or stage_id not in by_id:
                continue
            seen.add(stage_id)
            candidate = by_id[stage_id]
            if candidate.get("kind") == "experiment":
                return stage_id
            pending.extend(candidate.get("depends_on", []))
        return None

    def _argument_experiment_repair_request(self, stage, dossier):
        """Route evidence-producing argument repairs back to Methods first.

        An argument adjudicator can identify a missing sensitivity sweep or
        independent recalculation, but Strategy cannot manufacture that
        observation from prose.  Keep the argument repair order and add one
        explicitly addressed Methods order so the existing experiment is
        repaired before the argument is adjudicated again.
        """
        if not isinstance(stage, dict) or stage.get("kind") != "argument":
            return None
        directives = dossier.get("review_directives", []) if isinstance(dossier, dict) else []
        texts = [
            item.get("text", "") for item in directives
            if isinstance(item, dict) and isinstance(item.get("text"), str)
        ]
        directive_text = " ".join(texts)
        lowered = directive_text.casefold()
        if not directive_text or not any(marker in lowered for marker in ARGUMENT_EXPERIMENT_REPAIR_MARKERS):
            return None
        experiment_stage_id = self._experiment_ancestor_stage_id(stage)
        if experiment_stage_id is None:
            return None
        digest = str(dossier.get("input_sha256") or "")[:16]
        commands = deepcopy(dossier.get("repair_commands", []))
        checks = deepcopy(dossier.get("acceptance_checks", []))
        return {
            "id": f"repair-{stage.get('id')}-experiment-{digest}",
            "kind": "additional_experiment",
            "owner": "methods.validation",
            "target_stage_id": experiment_stage_id,
            "target_stage_kind": "experiment",
            "repair_priority": "immediate",
            "objective": (
                "Execute the evidence-producing repairs required by the argument review before "
                "rebuilding the claim-evidence graph: " + directive_text
            )[:1800],
            "why": (
                "The argument reviewer identified observations or recalculations that cannot be "
                "resolved by wording alone; Methods must produce or explicitly bound them first."
            ),
            "success_condition": (
                "A fresh raw result, deterministic validation, and independent recalculation address "
                "each evidence-producing directive, or record an explicit bounded limitation."
            ),
            "evidence_needed": (
                "The prior experiment result, exact review directives, executable source and inputs, "
                "fresh raw output, deterministic validation, and independent recalculation."
            ),
            "source_stage_id": stage.get("id"),
            "failure_dossier_ref": dossier.get("artifact_ref"),
            "failure_input_sha256": dossier.get("input_sha256"),
            "repair_commands": commands,
            "acceptance_checks": checks,
            "review_directives": deepcopy(directives),
            "recovery_mode": "repair_then_rerun",
        }

    def _format_contract_recovery_request(self, stage, context, dossier=None):
        """Build a same-stage order for a malformed model response.

        This is intentionally a ``recovery`` order rather than an
        ``additional_experiment`` order.  It changes routing, output framing,
        or compaction only; it must not be interpreted as a new scientific
        result or trigger a capability-design panel.
        """
        if not isinstance(stage, dict) or stage.get("kind") not in STAGE_KINDS:
            return None
        context = context if isinstance(context, dict) else {}
        recovery = context.get("failure_recovery")
        recovery = recovery if isinstance(recovery, dict) else {}
        digest = (
            (dossier or {}).get("input_sha256")
            if isinstance(dossier, dict) else None
        ) or recovery.get("input_sha256") or context.get("failure_input_sha256") or ""
        digest = re.sub(r"[^a-z0-9]", "", str(digest).casefold()) or "undigested"
        safe_stage = re.sub(r"[^a-z0-9_.-]+", "-", str(stage["id"]).casefold()).strip("-")
        safe_stage = safe_stage[:24] or "stage"
        attempt = context.get("format_recovery_attempts", 1)
        if type(attempt) is not int or attempt < 1:
            attempt = 1
        try:
            owner = self.departments.stage_route(stage["kind"])["role"]
        except (AttributeError, KeyError, ValidationError):
            owner = STAGE_ROLES.get(stage["kind"], "executive-command.arbiter")
        policy_revision = self._format_recovery_policy_revision(stage)
        objective = (
        "Repair the model response contract for this exact stage: use the configured output "
        "ceiling for an initial candidate and compact, bounded exact edits for a repair; "
        "do not regenerate the full program or repeat an identical request. Validate the "
        "complete JSON object locally. "
        "Preserve the scientific assignment and do not invent or release a result."
    )
        if stage.get("kind") == "topic_discovery":
            objective = (
                "Repair the topic response under the current field contract. Preserve the proposed "
                "scientific questions and declared evidence; normalize redundant execution labels, "
                "then repair only missing fields or the selected malformed execution plan. "
                "Validate the complete portfolio and retain the ordinary feasibility, source, and "
                "maturity gates before admitting the topic to literature survey."
            )
        elif stage.get("kind") == "argument":
            objective = (
                "Re-run the scientific argument under the revised prose policy: preserve complete, "
                "evidence-grounded claims; enforce the JSON schema, item counts, evidence IDs, and "
                "configured output-token budget, without per-field character ceilings."
            )
        elif stage.get("kind") == "experiment":
            objective = (
                "Retry only the experiment program-author response under the revised output policy: "
                "use the configured author output-token ceiling for an initial candidate; for a repair, "
                "return one compact schema-valid JSON object containing only bounded exact source edits. "
                "Do not regenerate the full program or repeat an identical request. Use only the primary "
                "or non-premium format fallback. The prior program "
                "was never admitted or executed, so do not issue a scientific experiment/code-repair "
                "order or claim new observations."
            )
        request_digest = digest[:16]
        if policy_revision:
            request_digest = hashlib.sha256(
                f"{digest}:{policy_revision}".encode("utf-8")).hexdigest()[:16]
        request = {
            "id": f"recovery-{safe_stage}-format-{request_digest}-{attempt}"[:64],
            "kind": "recovery",
            "owner": owner,
            "objective": objective,
            "why": (
                "The previous provider response did not satisfy its stage contract; "
                "forwarding it would create an invalid downstream input."
            ),
            "success_condition": (
                "The same stage returns a complete schema-valid object, or the Composer records an "
                "explicit model-contract blocker without admitting any downstream consumer."
            ),
            "evidence_needed": (
                "The failed response contract, exact stage input digest, bounded error, and a fresh "
                "locally validated response."
            ),
            "target_stage_id": stage["id"],
            "target_stage_kind": stage["kind"],
            "repair_priority": "immediate",
            "recovery_mode": "format_repair_then_rerun",
            "failure_dossier_ref": context.get("failure_dossier_ref") or recovery.get("dossier_ref"),
            "failure_input_sha256": digest,
            "repair_commands": deepcopy(
                context.get("repair_commands") or recovery.get("repair_commands") or []),
            "acceptance_checks": deepcopy(
                context.get("acceptance_checks") or recovery.get("acceptance_checks") or []),
        }
        if policy_revision:
            request["repair_policy_revision"] = policy_revision
        return request

    @staticmethod
    def _format_recovery_policy_revision(stage):
        if isinstance(stage, dict) and stage.get("kind") == "survey":
            from scisaurus.runtime.survey_records import SURVEY_RESPONSE_CONTRACT_REVISION
            return SURVEY_RESPONSE_CONTRACT_REVISION
        if isinstance(stage, dict) and stage.get("kind") == "topic_discovery":
            return TOPIC_RESPONSE_CONTRACT_REVISION
        if isinstance(stage, dict) and stage.get("kind") == "argument":
            return ARGUMENT_RESPONSE_CONTRACT_REVISION
        if isinstance(stage, dict) and stage.get("kind") == "experiment":
            return EXPERIMENT_AUTHOR_RESPONSE_CONTRACT_REVISION
        return None

    @staticmethod
    def _persisted_blocking_foundry_feedback(context):
        """Return only complete, still-actionable scientific findings in a checkpoint."""
        recovery = context.get("failure_recovery") if isinstance(context, dict) else None
        if not isinstance(recovery, dict):
            return None
        diagnostics = recovery.get("model_diagnostics")
        if not isinstance(diagnostics, dict):
            return None
        candidates = []
        repair_feedback = diagnostics.get("repair_feedback")
        if isinstance(repair_feedback, dict):
            candidates.append(repair_feedback.get("validation_feedback"))
        ledger = diagnostics.get("repair_ledger")
        if isinstance(ledger, list):
            candidates.extend(
                item.get("validation_feedback")
                for item in reversed(ledger) if isinstance(item, dict)
            )
        for feedback in candidates:
            if not isinstance(feedback, dict) or feedback.get("decision") != "rejected":
                continue
            gate = feedback.get("gate")
            findings = feedback.get("findings")
            if (not isinstance(gate, str)
                    or gate not in {"adversarial_review", "independent_recalculation",
                                    "deterministic_replay", "validator_readiness", "static_scan"}
                    or not isinstance(findings, list)):
                continue
            complete_findings = [
                item for item in findings
                if isinstance(item, dict) and item.get("severity") in {"blocking", "warning"}
                and all(isinstance(item.get(key), str) and item[key].strip()
                        for key in ("finding", "evidence", "required_change"))
            ]
            if any(item.get("severity") == "blocking" for item in complete_findings):
                return {
                    "gate": gate,
                    "decision": "rejected",
                    "failed_checks": deepcopy(feedback.get("failed_checks", [])),
                    "findings": deepcopy(complete_findings),
                }
        return None

    def _reconcile_mixed_experiment_response_failure(self, by_id):
        """Restore a scientific program repair hidden by a later truncated patch response."""
        reconciled = []
        for stage_id, stage in by_id.items():
            if not isinstance(stage, dict) or stage.get("kind") != "experiment":
                continue
            context = self.context.get(stage_id)
            record = self.stage_records.get(stage_id)
            if not isinstance(context, dict) or not isinstance(record, dict):
                continue
            recovery = context.get("failure_recovery")
            if not isinstance(recovery, dict):
                continue
            dossier_ref = recovery.get("dossier_ref") or context.get("failure_dossier_ref")
            if not (
                    context.get("failure_class") == "model_contract"
                    and recovery.get("failure_class") == "model_contract"
                    and recovery.get("recovery_mode") == "format_repair_then_rerun"
                    and context.get("format_recovery_dispatched") is True
                    and context.get("results_status") in (None, "not_executed")
                    and isinstance(dossier_ref, str)
                    and dossier_ref.startswith(
                        "artifact:command/composer/failure-recovery/experiment/attempt-")
            ):
                continue
            feedback = self._persisted_blocking_foundry_feedback(context)
            if not isinstance(feedback, dict):
                continue
            error_text = str(context.get("error") or record.get("error") or "")
            lowered = error_text.casefold()
            if ("capability foundry did not admit a program" not in lowered
                    or "program author response was incomplete" not in lowered
                    or "finish_reason=length" not in lowered):
                continue
            attempts = record.get("attempts")
            attempts = attempts if isinstance(attempts, list) else []
            latest = attempts[-1] if attempts and isinstance(attempts[-1], dict) else {}
            if (latest.get("state") != "failed"
                    or latest.get("failure_class") != "model_contract"):
                continue
            unresolved_prior_attempts = [
                {
                    key: prior[key]
                    for key in ("attempt_id", "attempt_number", "cycle", "state",
                                "project_dir", "external_ref")
                    if key in prior
                }
                for prior in attempts[:-1]
                if isinstance(prior, dict)
                and prior.get("state") in {"started", "unknown", "result_unknown"}
            ]
            if self._has_executed_experiment_result(
                    context,
                    self._stage_experiment_capability_id(stage),
                    project_dir=latest.get("project_dir")):
                continue
            latest_attempt_number = latest.get("attempt_number")
            attempt_count = record.get("attempt_count")
            attempt_number = max((
                value for value in (latest_attempt_number, attempt_count,
                                    context.get("attempt_number"), recovery.get("attempt_number"))
                if type(value) is int and value >= 0
            ), default=0) + 1

            findings = feedback["findings"]
            error = ModelWorkBlocked(
                "capability foundry patch response was truncated while a blocking scientific "
                "program review remained unresolved"
            )
            error.failure_class = "experiment_capability_repair"
            error.recovery_mode = "repair_then_rerun"
            error.repair_gate = feedback["gate"]
            error.capability_repair_routed = True
            error.repair_feedback = {
                "gate": feedback["gate"],
                "feedback": "Persisted blocking findings remain unresolved; repair program source before replay.",
                "validation_feedback": deepcopy(feedback),
                "validation_context": deepcopy(
                    recovery.get("model_diagnostics", {}).get("repair_feedback", {}).get(
                        "validation_context", {})),
            }
            error.research_review = {
                "status": "rejected",
                "checks": deepcopy(feedback.get("failed_checks", [])),
                "required_repairs": [
                    {"repair": (
                        f"{item['finding']} Evidence: {item['evidence']} "
                        f"Required change: {item['required_change']}"
                    )[:1800]}
                    for item in findings
                ],
            }
            error.model_diagnostics = {
                "source_failure_dossier_ref": dossier_ref,
                "persisted_gate": feedback["gate"],
                "blocking_finding_count": len(findings),
                "unresolved_prior_attempts": deepcopy(unresolved_prior_attempts),
            }
            recovery_context = deepcopy(context)
            if isinstance(latest.get("project_dir"), str):
                recovery_context["project_dir"] = latest["project_dir"]
            if isinstance(latest.get("attempt_id"), str):
                recovery_context["attempt_id"] = latest["attempt_id"]
            if type(latest_attempt_number) is int:
                recovery_context["attempt_number"] = latest_attempt_number
            error.stage_result = deepcopy(recovery_context)
            error_attempt = dict(latest)
            error_attempt.setdefault("project_dir", recovery_context.get("project_dir"))
            self._record_failure_recovery(
                stage, error_attempt, error, recovery_context,
                {"reports": []}, None, attempt_number,
                attempt_id=latest.get("attempt_id"),
            )

            repaired_context = self.context.get(stage_id)
            if not isinstance(repaired_context, dict):
                continue
            for key in (
                    "format_recovery", "format_recovery_attempts",
                    "format_recovery_dispatched", "format_recovery_signature",
                    "format_recovery_policy_revision"):
                repaired_context.pop(key, None)
            repaired_context["failure_class"] = "experiment_failure"
            repaired_context["review_status"] = "scientific_assignment_blocked"
            repaired_context["release_blocking"] = True
            if unresolved_prior_attempts:
                repaired_context["unresolved_prior_attempts"] = deepcopy(
                    unresolved_prior_attempts)
                repaired_context.pop("results_status", None)
            else:
                repaired_context["results_status"] = "not_executed"
            repaired_context["research_expansion_requests"] = []
            repaired_context["deferred_research_requests"] = []
            self.context[stage_id] = repaired_context

            superseded = [
                item for item in self.active_research_requests
                if isinstance(item, dict)
                and item.get("target_stage_id") == stage_id
                and item.get("recovery_mode") == "format_repair_then_rerun"
            ]
            self.active_research_requests = [
                item for item in self.active_research_requests if item not in superseded
            ]
            retired = self.departments.retire_superseded_work_orders(
                {item.get("id") for item in self.active_research_requests
                 if isinstance(item, dict) and isinstance(item.get("id"), str)},
                reason="scientific review evidence superseded format-only experiment recovery",
            )
            if retired:
                self.organization_snapshot = deepcopy(self.departments.snapshot())

            record.update({
                "status": "research_expansion_required",
                "error": str(error),
                "failure_class": "experiment_failure",
                "failure_dossier_ref": repaired_context.get("failure_dossier_ref"),
                "repair_order_issued": True,
            })
            self.stage_records[stage_id] = record
            self.continuation_pending_stage_ids.add(stage_id)
            event = {
                "cycle": self.continuation_cycles,
                "action": "reconcile_scientific_experiment_failure_after_format_truncation",
                "stage_id": stage_id,
                "source_dossier_ref": dossier_ref,
                "recovery_dossier_ref": repaired_context.get("failure_dossier_ref"),
                "attempt_number": attempt_number,
                "gate": feedback["gate"],
                "blocking_finding_count": len(findings),
                "unresolved_prior_attempts": deepcopy(unresolved_prior_attempts),
                "retired_format_request_ids": [
                    item.get("id") for item in superseded
                    if isinstance(item.get("id"), str)
                ],
                "next_action": "resume_same_topic_with_source_level_methods_repair",
            }
            self.department_activity.append(event)
            reconciled.append(event)
        return reconciled

    def _reconcile_interrupted_foundry_rejection(self, by_id):
        """Restore current-topic Foundry evidence after an interrupted stage call."""
        reconciled = []
        allowed_gates = {
            "adversarial_review", "independent_recalculation",
            "deterministic_replay", "validator_readiness", "static_scan",
        }
        for stage_id, stage in by_id.items():
            if not isinstance(stage, dict) or stage.get("kind") != "experiment":
                continue
            record = self.stage_records.get(stage_id)
            attempts = record.get("attempts") if isinstance(record, dict) else None
            latest = attempts[-1] if isinstance(attempts, list) and attempts else None
            if (not isinstance(latest, dict)
                    or latest.get("state") not in {"unknown", "result_unknown"}):
                continue
            match = self._topic_context_for_stage(stage)
            if not isinstance(match, tuple) or len(match) != 2:
                continue
            topic_context = match[1]
            topic = topic_context.get("topic") if isinstance(topic_context, dict) else None
            if (not isinstance(topic, dict)
                    or topic.get("id") != latest.get("topic_id")
                    or not isinstance(topic.get("research_question"), str)
                    or not isinstance(topic.get("domain"), str)):
                continue
            foundry = self._latest_foundry_failure_projection(
                topic["research_question"], topic["domain"])
            if (not isinstance(foundry, dict)
                    or foundry.get("status") in (None, "succeeded")
                    or foundry.get("cache_body_verified") is not True
                    or not re.fullmatch(r"[0-9a-f]{64}",
                                        str(foundry.get("cache_body_sha256", "")))):
                continue
            feedback = foundry.get("validation_feedback")
            if (not isinstance(feedback, dict)
                    or feedback.get("decision") != "rejected"
                    or feedback.get("gate") not in allowed_gates):
                continue
            findings = [
                deepcopy(item) for item in feedback.get("findings", [])
                if isinstance(item, dict) and item.get("severity") == "blocking"
                and all(isinstance(item.get(key), str) and item[key].strip()
                        for key in ("finding", "evidence", "required_change"))
            ]
            if not findings:
                continue

            context = self.context.get(stage_id)
            context = context if isinstance(context, dict) else {}
            project_dir = latest.get("project_dir")
            if self._has_executed_experiment_result(
                    context, self._stage_experiment_capability_id(stage),
                    project_dir=project_dir):
                continue
            identity = hashlib.sha256(canonical_bytes({
                "stage_id": stage_id,
                "attempt_id": latest.get("attempt_id"),
                "topic_id": topic["id"],
                "research_question": topic["research_question"],
                "domain": topic["domain"],
                "foundry_cache_body_sha256": foundry["cache_body_sha256"],
            })).hexdigest()
            prior = context.get("foundry_rejection_reconciliation")
            if isinstance(prior, dict) and prior.get("identity") == identity:
                continue

            unresolved = [
                {key: deepcopy(item[key]) for key in (
                    "attempt_id", "attempt_number", "cycle", "state", "project_dir",
                    "external_ref", "topic_id", "topic_cycle") if key in item}
                for item in attempts
                if isinstance(item, dict)
                and item.get("state") in {"started", "unknown", "result_unknown"}
            ]
            evidence = {
                "source": "capability_foundry",
                "cache_ref": foundry.get("cache_ref"),
                "cache_body_sha256": foundry["cache_body_sha256"],
                "validation_feedback": deepcopy(feedback),
                "experiment_result_observed": False,
                "unresolved_attempts": deepcopy(unresolved),
            }
            error = ModelWorkBlocked(
                "current-topic capability Foundry review rejected the experiment program: "
                + str(foundry.get("feedback") or "blocking scientific findings remain")[:2000]
            )
            error.failure_class = "experiment_capability_repair"
            error.recovery_mode = "repair_then_rerun"
            error.repair_gate = feedback["gate"]
            error.repair_feedback = {
                "gate": feedback["gate"],
                "feedback": "Repair the candidate from its persisted scientific review evidence.",
                "validation_feedback": deepcopy(feedback),
            }
            error.capability_failure_evidence = deepcopy(evidence)
            error.research_review = {
                "status": "rejected",
                "checks": deepcopy(feedback.get("failed_checks", [])),
                "required_repairs": [{"repair": (
                    f"{item['finding']} Evidence: {item['evidence']} "
                    f"Required change: {item['required_change']} "
                    "Reconcile unresolved attempts in their durable operation ledger; do not "
                    "replay an unknown operation or change the admitted question."
                )[:2200]} for item in findings],
            }
            error.model_diagnostics = {
                "interrupted_attempt_id": latest.get("attempt_id"),
                "foundry_cache_ref": foundry.get("cache_ref"),
                "foundry_cache_body_sha256": foundry["cache_body_sha256"],
                "foundry_gate": feedback["gate"],
                "blocking_finding_count": len(findings),
                "unresolved_attempts": deepcopy(unresolved),
            }
            error.stage_result = {
                "status": "blocked", "error": str(error),
                "failure_scope": "pre_execution_capability_review",
                "stage_id": stage_id, "kind": "experiment",
                "attempt_id": latest.get("attempt_id"),
                "attempt_number": latest.get("attempt_number"),
                "project_dir": project_dir, "topic_id": topic["id"],
                "topic_cycle": latest.get("topic_cycle"),
                "execution_observation": "no_admitted_experiment_result_observed",
                "results_status": "not_observed", "execution_refs": [],
                "unresolved_prior_attempts": deepcopy(unresolved),
                "capability_failure_evidence": deepcopy(evidence),
                "capability_repair_routed": True,
                "research_review": deepcopy(error.research_review),
                "model_diagnostics": deepcopy(error.model_diagnostics),
            }
            attempt_number = max((value for value in (
                record.get("attempt_count"), latest.get("attempt_number"),
                context.get("attempt_number"))
                if type(value) is int and value >= 0), default=0) + 1
            dossier = self._record_failure_recovery(
                stage, dict(latest), error, error.stage_result,
                {"reports": []}, None, attempt_number,
                attempt_id=latest.get("attempt_id"))
            repaired = self.context.get(stage_id)
            if not isinstance(repaired, dict):
                continue
            repaired.update({
                "foundry_rejection_reconciliation": {
                    "identity": identity, "attempt_id": latest.get("attempt_id"),
                    "cache_body_sha256": foundry["cache_body_sha256"],
                    "dossier_ref": dossier.get("artifact_ref"),
                },
                "capability_failure_evidence": deepcopy(evidence),
                "unresolved_prior_attempts": deepcopy(unresolved),
                "capability_repair_routed": True,
                "failure_class": "experiment_failure",
                "review_status": "scientific_assignment_blocked",
                "release_blocking": True,
            })
            self.context[stage_id] = repaired
            superseded = [
                item for item in self.active_research_requests
                if isinstance(item, dict) and item.get("target_stage_id") == stage_id
                and item.get("recovery_mode") == "format_repair_then_rerun"
            ]
            self.active_research_requests = [
                item for item in self.active_research_requests if item not in superseded
            ]
            retired = self.departments.retire_superseded_work_orders(
                {item.get("id") for item in self.active_research_requests
                 if isinstance(item, dict) and isinstance(item.get("id"), str)},
                reason="current-topic scientific findings superseded format-only retry")
            if retired:
                self.organization_snapshot = deepcopy(self.departments.snapshot())
            record.update({
                "status": "research_expansion_required",
                "error": str(error), "failure_class": "experiment_failure",
                "failure_dossier_ref": repaired.get("failure_dossier_ref"),
                "repair_order_issued": True,
            })
            self.stage_records[stage_id] = record
            self.continuation_pending_stage_ids.add(stage_id)
            event = {
                "cycle": self.continuation_cycles,
                "action": "reconcile_interrupted_foundry_rejection",
                "stage_id": stage_id, "attempt_id": latest.get("attempt_id"),
                "topic_id": topic["id"], "topic_cycle": latest.get("topic_cycle"),
                "foundry_cache_ref": foundry.get("cache_ref"),
                "recovery_dossier_ref": repaired.get("failure_dossier_ref"),
                "gate": feedback["gate"], "blocking_finding_count": len(findings),
                "unresolved_attempts": deepcopy(unresolved),
                "retired_format_request_ids": [item.get("id") for item in superseded
                                                if isinstance(item.get("id"), str)],
                "model_calls": 0,
                "next_action": "run_methods_repair_before_same-topic_capability_regeneration",
            }
            self.department_activity.append(event)
            reconciled.append(event)
        return reconciled

    @staticmethod
    def _append_deferred_preexecution_review(context, record):
        """Retain every pre-execution review while keeping the legacy latest view."""
        archive = context.get("deferred_preexecution_reviews")
        archive = deepcopy(archive) if isinstance(archive, list) else []
        legacy = context.get("deferred_preexecution_review")
        if isinstance(legacy, dict) and not any(
                isinstance(item, dict) and canonical_bytes(item) == canonical_bytes(legacy)
                for item in archive):
            archive.append(deepcopy(legacy))
        if not any(
                isinstance(item, dict) and canonical_bytes(item) == canonical_bytes(record)
                for item in archive):
            archive.append(deepcopy(record))
        context["deferred_preexecution_reviews"] = archive
        context["deferred_preexecution_review"] = deepcopy(archive[-1])

    def _reconcile_experiment_author_output_policy(self, by_id):
        """Reopen an unexecuted author-contract failure under the current policy.

        Older checkpoints can misclassify malformed model-authored intent as a
        scientific experiment failure and dispatch reviewers before any
        program was admitted. Reopen only a ledger-backed, unexecuted contract
        failure; retain those reports for later reassessment against fresh
        executable evidence.
        """
        reconciled = []
        for stage_id, stage in by_id.items():
            if not isinstance(stage, dict) or stage.get("kind") != "experiment":
                continue
            context = self.context.get(stage_id)
            record = self.stage_records.get(stage_id)
            if not isinstance(context, dict) or not isinstance(record, dict):
                continue

            error_text = str(context.get("error") or record.get("error") or "")
            lowered = error_text.casefold()
            recovery = context.get("failure_recovery")
            recovery = recovery if isinstance(recovery, dict) else {}
            diagnostics = recovery.get("model_diagnostics")
            diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
            repair_ledger = diagnostics.get("repair_ledger")
            repair_ledger = repair_ledger if isinstance(repair_ledger, list) else []
            legacy_intent_contract_failure = (
                "capability foundry did not admit a program" in lowered
                and "stage_seconds requires exactly" in lowered
                and context.get("failure_class") in {
                    "experiment_failure", "experiment_capability_repair",
                }
                and recovery.get("recovery_mode") in {
                    "repair_then_rerun", "experiment_diagnose_patch_execute_recalculate",
                }
                and bool(repair_ledger)
                and all(
                    isinstance(item, dict)
                    and classify_failure("experiment", item.get("error")) == "model_contract"
                    for item in repair_ledger
                )
                and context.get("results_status") in (None, "not_executed")
                and not self._has_executed_experiment_result(
                    context, self._stage_experiment_capability_id(stage),
                    project_dir=self._current_experiment_result_project_dir(stage),
                )
            )
            legacy_work_order_projection_failure = (
                "work order requires its routing, objective, success and evidence fields"
                in lowered
                and context.get("failure_class") in {
                    "experiment_failure", "experiment_capability_repair",
                }
                and recovery.get("recovery_mode") in {
                    "repair_then_rerun", "experiment_diagnose_patch_execute_recalculate",
                }
                and any(
                    isinstance(item, dict)
                    and "work order requires its routing, objective, success and evidence fields"
                    in str(item.get("error") or "").casefold()
                    for item in repair_ledger
                )
                and context.get("results_status") in (None, "not_executed")
                and not self._has_executed_experiment_result(
                    context, self._stage_experiment_capability_id(stage),
                    project_dir=self._current_experiment_result_project_dir(stage),
                )
            )
            if legacy_work_order_projection_failure and not legacy_intent_contract_failure:
                # This response shape error came from projecting a Composer
                # recovery order into the capability-authoring request. It is
                # a harness defect, not malformed model-authored science. Keep
                # the pending order, prior review, and repair-panel assignments
                # intact so the corrected projection can continue the same
                # research task without a formatting-only retry.
                # Leave the checkpoint byte-for-byte equivalent at this
                # boundary: changing the panel packet here invalidates its
                # content-addressed specialist cache and can repeat completed
                # reviews. The corrected runtime projects the existing order
                # before provider admission.
                continue

            legacy_author_contract_failure = legacy_intent_contract_failure
            if legacy_author_contract_failure:
                archived_review = {
                    key: deepcopy(context[key])
                    for key in (
                        "specialist_reports", "specialist_verifier", "specialist_usage",
                        "experiment_repair_plan", "review_directives",
                        "failure_observed_result", "unresolved_prior_attempts",
                    )
                    if key in context
                }
                if archived_review:
                    deferred_review = {
                        "failure_dossier_ref": context.get("failure_dossier_ref")
                        or recovery.get("dossier_ref"),
                        "failure_class": context.get("failure_class"),
                        "recovery_mode": recovery.get("recovery_mode"),
                        "evidence": archived_review,
                        "reason": (
                            "The experiment candidate was blocked before a result was released; "
                            "retain its scientific review for reassessment against a fresh "
                            "admitted execution."
                        ),
                    }
                    self._append_deferred_preexecution_review(context, deferred_review)
                    for key in archived_review:
                        context.pop(key, None)
                commands = build_repair_commands(
                    "experiment", "model_contract", error_text=error_text)
                checks = [
                    item.get("acceptance_check") for item in commands
                    if isinstance(item, dict) and item.get("acceptance_check")
                ]
                recovery = deepcopy(recovery)
                recovery.update({
                    "failure_class": "model_contract",
                    "recovery_mode": "format_repair_then_rerun",
                    "requires_capability_repair": False,
                    "repair_commands": deepcopy(commands),
                    "acceptance_checks": deepcopy(checks),
                    "review_directives": [],
                })
                context.update({
                    "failure_class": "model_contract",
                    "review_status": "format_recovery_exhausted",
                    "failure_recovery": recovery,
                    "format_recovery": True,
                    "format_recovery_dispatched": True,
                    "repair_commands": deepcopy(commands),
                    "acceptance_checks": deepcopy(checks),
                    "review_directives": [],
                })
                self.context[stage_id] = context

                # Mark only the checkpoint projection stale. The child task,
                # attempt, and any saved response remain in the durable ledger.
                panel_prefix = f"experiment-repair-panel-{self.continuation_cycles}-"
                for panel_id, panel in self.stage_records.items():
                    if (not isinstance(panel_id, str) or not panel_id.startswith(panel_prefix)
                            or not isinstance(panel, dict)):
                        continue
                    live = panel.get("specialist_live")
                    if not isinstance(live, dict) or not live:
                        continue
                    panel["superseded_specialist_live"] = deepcopy(live)
                    panel["specialist_live"] = {}
                    panel["active_agents"] = []
                    panel["status"] = "stale"
                    panel["superseded_reason"] = (
                        "author response contract repair precedes scientific review")
                    self.stage_records[panel_id] = panel

            if not (
                    context.get("format_recovery") is True
                    and context.get("format_recovery_dispatched") is True
                    and context.get("review_status") == "format_recovery_exhausted"
                    and context.get("failure_class") == "model_contract"
            ):
                continue
            revision = self._format_recovery_policy_revision(stage)
            if not revision or context.get("format_recovery_policy_revision") == revision:
                continue
            incomplete_author_response = (
                "stage_seconds requires exactly" in lowered
                or "experiment_intent requires" in lowered
                or "experiment_intent stage_seconds" in lowered
                or (
                    ("program author response was incomplete" in lowered
                     or "program author did not finish normally" in lowered)
                    and ("finish_reason=length" in lowered or "valid json" in lowered)
                )
            )
            if not incomplete_author_response:
                continue
            if (self._persisted_blocking_foundry_feedback(context) is not None
                    and not legacy_author_contract_failure):
                continue
            if context.get("results_status") not in (None, "not_executed"):
                continue

            current_signature = self._format_recovery_signature(stage, error_text)
            prior_entry = self.format_recovery_ledger.get(current_signature)
            if isinstance(prior_entry, dict) and prior_entry.get("status") in {
                    "dispatched", "exhausted"}:
                continue
            request_context = deepcopy(context)
            request_context.update({
                "failure_dossier_ref": context.get("failure_dossier_ref"),
                "format_recovery_policy_revision": revision,
                "format_recovery_signature": current_signature,
            })
            request = self._format_contract_recovery_request(stage, request_context)
            if not isinstance(request, dict):
                continue

            stale_requests = [
                item for item in self.active_research_requests
                if isinstance(item, dict)
                and item.get("target_stage_id") == stage_id
                and (
                    item.get("source_stage_id") == stage_id
                    or (legacy_author_contract_failure
                        and item.get("kind") == "additional_experiment"
                        and item.get("recovery_mode")
                        == "experiment_diagnose_patch_execute_recalculate")
                )
            ]
            self.active_research_requests = [
                item for item in self.active_research_requests
                if item not in stale_requests
            ]
            next_recovery = deepcopy(recovery)
            next_recovery.update({
                "schema_version": "failure-recovery-ledger-1",
                "failure_class": "model_contract",
                "dossier_ref": context.get("failure_dossier_ref")
                or recovery.get("dossier_ref"),
                "input_sha256": context.get("failure_input_sha256")
                or recovery.get("input_sha256"),
                "recovery_mode": "format_repair_then_rerun",
                "requires_capability_repair": False,
                "attempt_number": record.get("attempt_count"),
                "response_contract_revision": revision,
            })
            context.update({
                "status": "research_expansion_required",
                "review_status": "model_contract_repair",
                "failure_class": "model_contract",
                "release_blocking": True,
                "failure_recovery": next_recovery,
                "format_recovery": True,
                "format_recovery_dispatched": False,
                "format_recovery_policy_revision": revision,
                "format_recovery_signature": current_signature,
                "research_requests": [request],
                "research_expansion_requests": [],
                "deferred_research_requests": [],
            })
            entry = self.format_recovery_ledger.setdefault(current_signature, {
                "stage_id": stage_id,
                "status": "pending",
                "first_attempt": record.get("attempt_count"),
                "failure_signature": current_signature,
                "legacy_policy_migration": True,
            })
            if entry.get("status") not in {"pending", "dispatched", "exhausted"}:
                entry["status"] = "pending"
            record.update({
                "status": "research_expansion_required",
                "error": error_text[:4096],
                "recovery_contract_revision": revision,
            })
            self.context[stage_id] = context
            self.stage_records[stage_id] = record
            self.continuation_pending_stage_ids.add(stage_id)
            reconciled.append({
                "stage_id": stage_id,
                "policy_revision": revision,
                "request_id": request["id"],
                "failure_class_migrated": legacy_author_contract_failure,
                "retired_stale_request_ids": [
                    item.get("id") for item in stale_requests
                    if isinstance(item.get("id"), str)
                ],
                "reason": "retry the unexecuted program-author response with the corrected output and fallback policy",
            })
        if reconciled:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "reconcile_experiment_author_output_policy",
                "stages": reconciled,
                "next_action": "run one same-topic format repair before any scientific experiment recovery",
            })
        return reconciled

    @staticmethod
    def _format_recovery_signature(stage, error):
        """Identify the same response-contract failure across attempts and resumes."""
        text = str(error).casefold()
        # Stage records serialize the exception class alongside its message;
        # the initial recovery ledger receives the exception itself.
        text = re.sub(r"^(?:[a-z_][a-z0-9_]*(?:error|blocked)):\s*", "", text)
        text = re.sub(
            r"\b(attempt|cycle)[\s:#_-]*\d+\b", r"\1 <n>", text,
            flags=re.IGNORECASE)
        text = re.sub(r"\b[0-9a-f]{32,64}\b", "<digest>", text,
                      flags=re.IGNORECASE)
        text = re.sub(r"\s+", " ", text).strip()
        identity = {
            "stage_id": stage.get("id") if isinstance(stage, dict) else None,
            "stage_kind": stage.get("kind") if isinstance(stage, dict) else None,
            "failure_class": "model_contract",
            "error": text,
        }
        policy_revision = ComposerRunner._format_recovery_policy_revision(stage)
        if policy_revision:
            identity["response_contract_revision"] = policy_revision
        return hashlib.sha256(canonical_bytes(identity)).hexdigest()

    def _record_failure_recovery(self, stage, attempt_stage, error, context,
                                 specialist_bundle, specialist_verifier,
                                 attempt_number, *, attempt_id=None,
                                 topic_identity=None):
        """Persist a failure dossier and replace blind retry with a repair order."""
        # Keep the result produced by this dispatch separate from the durable
        # context.  A resumed stage may have an older error/result in its
        # checkpoint; using that packet to classify the new failure can turn a
        # scientific review into a stale quota/provider fence and suppress the
        # repair order that should reopen its evidence-producing ancestor.
        current_stage_result = getattr(error, "stage_result", None)
        if not isinstance(current_stage_result, dict):
            current_stage_result = context if isinstance(context, dict) else None
        if not isinstance(current_stage_result, dict):
            current_stage_result = {"status": "blocked", "error": str(error)}
        else:
            current_stage_result = deepcopy(current_stage_result)
            current_stage_result.setdefault("error", str(error))
        # The main scheduler clears its local ``context`` before dispatching a
        # stage. When that stage raises, the durable stage packet is therefore
        # the only place that contains prior format/capability repair counts.
        # Prefer it as the recovery base so a new continuation cannot reset a
        # bounded lease to zero on every failure.  Current runner output wins
        # on collisions; durable state only fills fields the new attempt did
        # not produce.
        durable_context = self.context.get(stage.get("id")) if isinstance(stage, dict) else None
        prior_stage_context = (
            deepcopy(durable_context) if isinstance(durable_context, dict) else {})
        if isinstance(durable_context, dict):
            recovered_base = deepcopy(durable_context)
            if isinstance(context, dict):
                recovered_base.update(deepcopy(context))
            context = recovered_base
        stage_result = current_stage_result
        subject = getattr(error, "repair_subject", None)
        plan_review_failure = isinstance(subject, dict)
        dossier = build_failure_dossier(
            stage=stage, attempt_stage=attempt_stage, error=error,
            stage_result=stage_result,
            specialist_reports=(specialist_bundle or {}).get("reports", [])
            if isinstance(specialist_bundle, dict) else [],
            verifier=specialist_verifier,
            program_snapshot=[] if plan_review_failure else self._failure_program_snapshot(stage),
            foundry_work_snapshot={} if plan_review_failure else self._failed_foundry_work_for_stage(stage),
            attempt_number=attempt_number,
        )
        if plan_review_failure:
            dossier["repair_subject"] = deepcopy(subject)
            dossier["repair_phase"] = "pre_execution_plan_review"
        # Resource fences still get a dossier for the ledger, but they do not
        # create a scientific work order or consume a repair call.
        dossier_record = self._publish(
            f"command/composer/failure-recovery/{stage['id']}/attempt-{attempt_number}",
            "report", dossier, "command.composer",
        )
        dossier["artifact_ref"] = dossier_record["artifact_ref"]
        if not dossier.get("recoverable") or dossier.get("failure_class") == "operational_recovery":
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "failure_dossier_recorded",
                "stage_id": stage["id"],
                "attempt_number": attempt_number,
                "failure_class": dossier.get("failure_class"),
                "dossier_ref": dossier["artifact_ref"],
                "next_action": dossier.get("next_action"),
            })
            return dossier

        if dossier.get("failure_class") == "model_contract":
            prior_attempts = 0
            if isinstance(context, dict) and type(context.get("format_recovery_attempts")) is int:
                prior_attempts = context["format_recovery_attempts"]
            signature = self._format_recovery_signature(stage, error)
            policy_revision = self._format_recovery_policy_revision(stage)
            ledger_entry = self.format_recovery_ledger.get(signature)
            prior_recovery = prior_stage_context.get("failure_recovery")
            if (not isinstance(ledger_entry, dict)
                    and prior_stage_context.get("format_recovery_dispatched") is True
                    and isinstance(prior_recovery, dict)
                    and prior_recovery.get("failure_class") == "model_contract"
                    and (policy_revision is None
                         or prior_stage_context.get("format_recovery_policy_revision")
                         == policy_revision)
                    and self._format_recovery_signature(
                        stage, prior_stage_context.get("error", "")) == signature):
                ledger_entry = {
                    "stage_id": stage["id"], "status": "dispatched",
                    "first_attempt": prior_recovery.get("attempt_number"),
                    "failure_reviewed": self._failure_review_was_material(
                        prior_stage_context, prior_recovery),
                    "legacy_checkpoint_migration": True,
                }
                self.format_recovery_ledger[signature] = ledger_entry
            if isinstance(ledger_entry, dict) and ledger_entry.get("status") in {
                    "dispatched", "exhausted"}:
                ledger_entry.update({
                    "status": "exhausted",
                    "last_attempt": attempt_number,
                    "last_dossier_ref": dossier["artifact_ref"],
                    "repeated_failures": int(ledger_entry.get("repeated_failures", 0)) + 1,
                })
                recovery_context = deepcopy(context) if isinstance(context, dict) else {}
                recovery_context.update({
                    "stage_id": stage["id"],
                    "kind": stage["kind"],
                    "status": "blocked",
                    "error": str(error)[:4096],
                    "review_status": "format_recovery_exhausted",
                    "release_blocking": True,
                    "failure_dossier_ref": dossier["artifact_ref"],
                    "failure_class": "model_contract",
                    "failure_recovery": {
                        "schema_version": "failure-recovery-ledger-1",
                        "failure_class": "model_contract",
                        "dossier_ref": dossier["artifact_ref"],
                        "input_sha256": dossier.get("input_sha256"),
                        "repair_commands": deepcopy(dossier.get("repair_commands", [])),
                        "acceptance_checks": deepcopy(dossier.get("acceptance_checks", [])),
                        "review_directives": deepcopy(dossier.get("review_directives", [])),
                        "model_diagnostics": deepcopy(dossier.get("model_diagnostics", {})),
                        "recovery_mode": "format_repair_then_rerun",
                        "requires_capability_repair": False,
                        "attempt_number": attempt_number,
                        "response_contract_revision": policy_revision,
                    },
                    "format_recovery": True,
                    "format_recovery_signature": signature,
                    "format_recovery_dispatched": True,
                    "format_recovery_attempts": prior_attempts + 1,
                    "format_recovery_policy_revision": policy_revision,
                    "research_requests": [],
                    "research_expansion_requests": [],
                    "deferred_research_requests": [],
                })
                self.context[stage["id"]] = recovery_context
                exhausted_orders = [
                    item for item in self.active_research_requests
                    if isinstance(item, dict)
                    and item.get("source_stage_id") == stage["id"]
                    and item.get("target_stage_id") == stage["id"]
                ]
                if exhausted_orders:
                    exhausted_ids = {
                        item.get("id") for item in exhausted_orders
                        if isinstance(item.get("id"), str)
                    }
                    self.active_research_requests = [
                        item for item in self.active_research_requests
                        if item not in exhausted_orders
                    ]
                    retired_orders = self.departments.retire_superseded_work_orders(
                        {item.get("id") for item in self.active_research_requests
                         if isinstance(item, dict) and isinstance(item.get("id"), str)},
                        reason=("same-stage model-contract recovery was exhausted without "
                                "an admitted experiment program"),
                    )
                    self.department_activity.append({
                        "cycle": self.continuation_cycles,
                        "action": "retire_exhausted_model_contract_work_orders",
                        "stage_id": stage["id"],
                        "request_ids": sorted(exhausted_ids),
                        "retired_work_orders": retired_orders,
                        "next_action": "stop automatic redispatch until the response contract or route changes",
                    })
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "suppress_repeated_model_contract_recovery",
                    "stage_id": stage["id"],
                    "attempt_number": attempt_number,
                    "failure_signature": signature,
                    "dossier_ref": dossier["artifact_ref"],
                    "next_action": "change_the_response_contract_or_model_route_before_retry",
                })
                return dossier
            if not isinstance(ledger_entry, dict):
                ledger_entry = {
                    "stage_id": stage["id"], "status": "pending",
                    "first_attempt": attempt_number,
                    "failure_signature": signature,
                }
                self.format_recovery_ledger[signature] = ledger_entry
            review_reports = (
                specialist_bundle.get("reports", [])
                if isinstance(specialist_bundle, dict) else [])
            same_prior_failure = (
                self._format_recovery_signature(
                    stage, prior_stage_context.get("error", "")) == signature)
            ledger_entry.update({
                "last_attempt": attempt_number,
                "last_dossier_ref": dossier["artifact_ref"],
                "failure_reviewed": bool(
                    any(isinstance(report, dict) and report.get("status") == "succeeded"
                        for report in review_reports)
                    or (isinstance(specialist_verifier, dict)
                        and specialist_verifier.get("status") == "succeeded")
                    or (same_prior_failure and self._failure_review_was_material(
                        prior_stage_context, prior_recovery))),
            })
            recovery = {
                "schema_version": "failure-recovery-ledger-1",
                "failure_class": "model_contract",
                "dossier_ref": dossier["artifact_ref"],
                "input_sha256": dossier.get("input_sha256"),
                "repair_commands": deepcopy(dossier.get("repair_commands", [])),
                "acceptance_checks": deepcopy(dossier.get("acceptance_checks", [])),
                "review_directives": deepcopy(dossier.get("review_directives", [])),
                "model_diagnostics": deepcopy(dossier.get("model_diagnostics", {})),
                "recovery_mode": "format_repair_then_rerun",
                "requires_capability_repair": False,
                "attempt_number": attempt_number,
            }
            recovery_context = deepcopy(context) if isinstance(context, dict) else {}
            if isinstance(attempt_stage, dict) and isinstance(
                    attempt_stage.get("project_dir"), str):
                recovery_context.setdefault(
                    "project_dir", str(Path(attempt_stage["project_dir"]).resolve()))
            recovery_context.update({
                "stage_id": stage["id"],
                "kind": stage["kind"],
                "status": "format_recovery_required",
                "error": str(error)[:4096],
                "review_status": "model_contract_repair",
                "failure_class": "model_contract",
                "failure_recovery": recovery,
                "failure_dossier_ref": dossier["artifact_ref"],
                "repair_commands": deepcopy(dossier.get("repair_commands", [])),
                "acceptance_checks": deepcopy(dossier.get("acceptance_checks", [])),
                "review_directives": deepcopy(dossier.get("review_directives", [])),
                "model_diagnostics": deepcopy(dossier.get("model_diagnostics", {})),
                "research_requests": [],
                "research_expansion_requests": [],
                "deferred_research_requests": [],
                "format_recovery": True,
                "format_recovery_dispatched": False,
                "format_recovery_attempts": prior_attempts + 1,
                "format_recovery_signature": signature,
                "format_recovery_policy_revision": policy_revision,
            })
            format_request = self._format_contract_recovery_request(
                stage, recovery_context, dossier)
            if isinstance(format_request, dict):
                recovery_context["research_requests"] = [format_request]
            self.context[stage["id"]] = recovery_context
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "model_contract_repair_order_issued",
                "stage_id": stage["id"],
                "attempt_number": attempt_number,
                "failure_class": "model_contract",
                "dossier_ref": dossier["artifact_ref"],
                "repair_commands": deepcopy(dossier.get("repair_commands", [])),
                "acceptance_checks": deepcopy(dossier.get("acceptance_checks", [])),
                "next_action": "reroute_and_compact_before_scientific_recovery",
            })
            return dossier

        request = build_repair_request(dossier, stage_id=stage["id"])
        request["failure_dossier_ref"] = dossier["artifact_ref"]
        # A failed experiment is not automatically a failed program.  A
        # malformed specialist verdict should be repaired at the model/task
        # contract; a result-bearing failure, executor/validator failure, or
        # explicit foundry rejection deserves the expensive source-level
        # methods panel. This distinction keeps the controller from regenerating
        # code for every ordinary response-contract defect.
        requires_capability_repair = self._experiment_program_repair_required(
            stage, dossier, stage_result)
        recovery = {
            "schema_version": "failure-recovery-ledger-1",
            "failure_class": dossier.get("failure_class"),
            "dossier_ref": dossier["artifact_ref"],
            "input_sha256": dossier.get("input_sha256"),
            "repair_commands": deepcopy(dossier.get("repair_commands", [])),
            "acceptance_checks": deepcopy(dossier.get("acceptance_checks", [])),
            "review_directives": deepcopy(dossier.get("review_directives", [])),
            "model_diagnostics": deepcopy(dossier.get("model_diagnostics", {})),
            "recovery_mode": "repair_then_rerun",
            "requires_capability_repair": requires_capability_repair,
            "attempt_number": attempt_number,
        }
        recovery_context = deepcopy(context) if isinstance(context, dict) else {}
        if isinstance(attempt_stage, dict) and isinstance(
                attempt_stage.get("project_dir"), str):
            recovery_context.setdefault(
                "project_dir", str(Path(attempt_stage["project_dir"]).resolve()))
        requests = [request]
        experiment_request = self._argument_experiment_repair_request(stage, dossier)
        if experiment_request is not None:
            requests.append(experiment_request)
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "route_argument_evidence_repair_to_experiment",
                "stage_id": stage["id"],
                "target_stage_id": experiment_request["target_stage_id"],
                "directive_count": len(experiment_request.get("review_directives", [])),
                "next_action": "repair_experiment_before_argument_adjudication",
            })
        recovery_context.update({
            "stage_id": stage["id"],
            "kind": stage["kind"],
            "attempt_number": attempt_number,
            **({"attempt_id": attempt_id} if isinstance(attempt_id, str) else {}),
            "status": "research_expansion_required",
            "error": str(error)[:4096],
            "review_status": "scientific_assignment_blocked",
            "failure_recovery": recovery,
            "failure_dossier_ref": dossier["artifact_ref"],
                "failure_observed_result": deepcopy(dossier.get("observed_result", {})),
                "repair_commands": deepcopy(dossier.get("repair_commands", [])),
                "acceptance_checks": deepcopy(dossier.get("acceptance_checks", [])),
                "review_directives": deepcopy(dossier.get("review_directives", [])),
                "model_diagnostics": deepcopy(dossier.get("model_diagnostics", {})),
                "research_requests": requests,
        })
        if isinstance(stage_result, dict):
            # Preserve result-bearing fields so the next capability repair can
            # distinguish a bad program from a bad claim about a real result.
            for key in (
                    "results_package", "raw_results", "metrics", "findings", "assets",
                    "execution_refs", "deterministic_validation_ref", "model_review_refs",
                    "assessment_ref", "survey_ref", "nomination_ref", "survey_current",
                    "assessment_current", "gap_state", "topic_admission", "incumbent_ref",
                    "limitations", "analysis", "study_id", "run_id"):
                if key in stage_result:
                    recovery_context[key] = deepcopy(stage_result[key])
        recovery_context["failure_debt"] = {
            "stage_id": stage["id"], "kind": stage["kind"],
            "failure_class": dossier.get("failure_class"),
            "error": str(error)[:4096], "attempts": attempt_number,
            "next_action": "execute the recorded repair commands before rerunning this scope",
            "release_blocking": True,
            "failure_dossier_ref": dossier["artifact_ref"],
        }
        self.context[stage["id"]] = recovery_context
        if stage.get("kind") != "topic_discovery":
            self._refresh_stage_topic_lineage(
                stage["id"], recovery_context, attempt_id=attempt_id,
                topic_identity=topic_identity,
            )
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "failure_analyzed_repair_order_issued",
            "stage_id": stage["id"],
            "attempt_number": attempt_number,
            "failure_class": dossier.get("failure_class"),
            "dossier_ref": dossier["artifact_ref"],
            "repair_order": deepcopy(request),
            "repair_commands": deepcopy(dossier.get("repair_commands", [])),
            "acceptance_checks": deepcopy(dossier.get("acceptance_checks", [])),
            "next_action": "repair_before_rerun",
        })
        return dossier

    @staticmethod
    def _experiment_program_repair_required(stage, dossier, stage_result=None):
        """Decide whether an experiment failure warrants source-level repair."""
        if not isinstance(stage, dict) or stage.get("kind") != "experiment":
            return False
        if not isinstance(dossier, dict) or dossier.get("failure_class") in {
                "resource_fence", "operational_recovery", "model_contract",
                "evidence_input_unavailable"}:
            return False
        if dossier.get("failure_class") == "experiment_failure":
            return True
        observed = stage_result if isinstance(stage_result, dict) else {}
        if any(observed.get(key) for key in (
                "execution_refs", "results_package", "raw_results",
                "deterministic_validation_ref", "assessment_ref", "metrics", "findings")):
            return True
        text = str(dossier.get("error", "")).casefold()
        return any(marker in text for marker in (
            "capability foundry", "executor", "validator", "estimand",
            "independent recalculation", "results-package", "program admission",
        ))

    def _execute_stage(self, stage, *, attempt_number=1, specialist_reports=None,
                       stage_assignment=None):
        """Preserve authoring usage across every producer failure boundary."""
        before = deepcopy(self.foundry_usage)
        panel_before = self._repair_panel_usage_total(stage["id"])
        try:
            result = self._produce_stage(stage, attempt_number=attempt_number,
                specialist_reports=specialist_reports, stage_assignment=stage_assignment)
            if stage["kind"] == "experiment":
                result["repair_panel_usage"] = self._usage_delta(
                    self._repair_panel_usage_total(stage["id"]), panel_before)
            return result
        except Exception as exc:
            if stage["kind"] == "experiment":
                self._sync_foundry_usage()
                if getattr(exc, "usage_is_snapshot", False):
                    exc.usage = {}
                    exc.usage_is_snapshot = False
                exc.foundry_usage = self._usage_delta(self.foundry_usage, before)
                if not getattr(exc, "usage_includes_foundry", False):
                    self._merge_incremental_error_usage(exc, exc.foundry_usage)
                exc.usage_includes_foundry = True
                panel_usage = self._usage_delta(
                    self._repair_panel_usage_total(stage["id"]), panel_before)
                if not isinstance(getattr(exc, "repair_panel_usage", None), dict):
                    self._merge_incremental_error_usage(exc, panel_usage)
                exc.repair_panel_usage = panel_usage
            raise

    def _produce_stage(self, stage, *, attempt_number=1, specialist_reports=None,
                       stage_assignment=None):
        """Dispatch one allowlisted specialist runner and return its context."""
        kind = stage["kind"]
        foundry_usage_before = deepcopy(self.foundry_usage) if kind == "experiment" else {}
        foundry_usage_delta = {}
        project_dir = Path(stage["project_dir"])
        output_path = None
        stage_deadline = self._stage_remaining(stage)
        retained_topic = stage.get("_resume_topic_result")
        if kind == "topic_discovery" and isinstance(retained_topic, dict):
            retained_path = Path(retained_topic["output_path"]).resolve()
            body = retained_path.read_bytes()
            digest = hashlib.sha256(body).hexdigest()
            if digest != retained_topic.get("output_sha256"):
                raise ValidationError("retained topic output changed after Composer recovery admission")
            result = deepcopy(retained_topic["result"])
            source_usage = result.get("usage")
            source_usage = deepcopy(source_usage) if isinstance(source_usage, dict) else {}
            result["producer_recovery"] = {
                "source_attempt_number": retained_topic.get("source_attempt_number"),
                "source_project_dir": retained_topic.get("source_project_dir"),
                "output_sha256": digest,
                "producer_calls_replayed": 0,
                "source_usage": source_usage,
            }
            return {**result, "stage_id": stage["id"], "kind": kind,
                    "project_dir": retained_topic.get("source_project_dir")
                        or str(retained_path.parent.resolve()),
                    "output_path": str(retained_path)}
        prior_run = (Path(stage["reuse_output_path"])
                     if stage["reuse_output_path"] is not None
                     else project_dir / "output" / "run.json")
        # A fresh free-topic mission must sample a new scholarly pool.  Topic
        # reuse is an explicit replay mode and is opt-in at workflow level;
        # other stages retain their existing checkpoint-reuse contract.
        topic_reuse_allowed = (kind != "topic_discovery"
                               or self.workflow.get("topic_reuse_allowed", False))
        if stage["reuse_completed"] and topic_reuse_allowed and prior_run.is_file():
            try:
                prior = json.loads(prior_run.read_text())
            except (OSError, ValueError) as exc:
                raise ValidationError(f"reusable stage output is unreadable: {prior_run}") from exc
            reusable_experiment = (
                stage["kind"] != "experiment"
                or self._bind_reused_experiment_capability(stage, prior)
            )
            if prior.get("status") in {"completed", "accepted"} and reusable_experiment:
                output_value = (prior.get("output_path") or prior.get("results_package")
                                or prior.get("pdf") or str(prior_run.resolve()))
                context = {**prior, "stage_id": stage["id"], "kind": stage["kind"],
                           "project_dir": str(project_dir.resolve()), "output_path": str(Path(output_value).resolve())}
                if stage["kind"] == "experiment":
                    context["results_package"] = prior.get("results_package")
                if stage["kind"] == "argument":
                    context["argument_package_path"] = context["output_path"]
                if (stage["kind"] == "topic_discovery" and "research_program" not in context
                        and isinstance(context.get("candidates"), list)
                        and isinstance(context.get("selected_id"), str)):
                    from scisaurus.runtime.research_program import build_research_program
                    context["research_program"] = build_research_program(context)
                self._publish(f"command/composer/reuse/{stage['id']}-{len(self.feedback) + 1}",
                              "decision_note", {
                                  "stage_id": stage["id"], "action": "reuse_completed_stage",
                                  "source_run": str(prior_run.resolve()), "status": prior.get("status"),
                              }, "command.composer")
                return context
        config = json.loads(Path(stage["config_path"]).read_text())
        config = self._adapt_continuation_config(stage, config)
        config = self._apply_stage_quota(config, stage)
        if kind != "survey" and isinstance(config.get("model"), dict):
            config["model"] = self._stage_model_config(stage, config["model"])
        # The mission deadline governs total autonomy, not the number of
        # attempts spent repairing one unchanged model assignment.
        if kind in {"survey", "experiment"} and self._allows_provisional_progress():
            config.setdefault("limits", {})["repair_mode"] = "bounded"
        if (kind == "topic_discovery"
                and self._retry_policy().get("mode", "bounded") == "until_deadline"):
            # A descriptor may deliberately impose a tighter intake repair
            # budget.  Only inherit the workflow mode when the descriptor did
            # not state one; otherwise the generic Composer policy silently
            # defeats the topic quota.
            config.setdefault("repair_mode", "until_deadline")
        if stage["id"] in self.reopened_stage_ids and self.continuation_cycles:
            # A continuation must never overwrite its incumbent.  Specialist
            # runners create new output roots, so remap their configured
            # result path into the cycle namespace before dispatch.
            cycle_root = Path(stage["project_dir"]).resolve()
            if kind in {"interpretation", "argument"}:
                configured_output = Path(config["output_path"])
                config["output_path"] = str(cycle_root / configured_output.name)
            elif kind == "paper":
                configured_output = Path(config["output_dir"])
                config["output_dir"] = str(cycle_root / configured_output.name)
        if attempt_number > 1:
            attempt_root = Path(stage["project_dir"]).resolve()
            if kind in {"interpretation", "argument"}:
                output_path = Path(config["output_path"])
                config["output_path"] = str(attempt_root / output_path.name)
            elif kind == "paper":
                output_dir = Path(config["output_dir"])
                config["output_dir"] = str(attempt_root / output_dir.name)
        if kind == "topic_discovery":
            from scisaurus.runtime.topic_discovery import (
                TopicDiscoveryRunner, validate_topic_stage_config,
            )
            # Another fresh Composer mission may have recorded a direction
            # after this process was initialized.  Refresh the family memory
            # at the admission boundary so parallel missions see the latest
            # completed selection before they ask the model for a topic.
            self.topic_history = self._load_topic_history()
            descriptor = validate_topic_stage_config(config)
            model = self._stage_model_config(stage, json.loads(Path(descriptor["model_config_path"]).read_text()))
            runner = TopicDiscoveryRunner(model, deadline_seconds=stage_deadline)
            maturity_rounds = descriptor.get("maturity_review_rounds", 0)
            # Journal-oriented free-topic missions target a research paper,
            # not an executable demo.  Give the intake an independent maturity
            # screen by default; ordinary legacy topic stages keep their
            # original one-pass contract unless they opt in explicitly.
            if maturity_rounds == 0 and (
                    self.workflow.get("experiment_catalog")
                    or any(item.get("kind") == "paper" for item in self.workflow["stages"])):
                maturity_rounds = 2
            try:
                continuation_scope = bool(
                    stage["id"] in self.reopened_stage_ids and self.continuation_cycles)
                configured_topic_budgets = (
                    descriptor.get("continuation_budgets")
                    if continuation_scope and descriptor.get("continuation_budgets")
                    else descriptor.get("budgets")
                )
                if not configured_topic_budgets:
                    configured_topic_budgets = (
                        DEFAULT_TOPIC_CONTINUATION_BUDGETS
                        if continuation_scope else DEFAULT_TOPIC_BUDGETS
                    )
                # Topic production runs before this attempt's reviewers. Keep
                # their full bounded allowances inside the aggregate stage
                # quota even on the first pass, when there are no prior reports
                # to reveal their consumption. Prior-cycle reports are already
                # included in the attempt ledger and must not be charged twice.
                review_reservation = self._topic_review_reservation(stage_assignment)
                topic_budgets = self._topic_budgets_for_attempt(
                    stage["id"], configured_topic_budgets,
                    scope="continuation" if continuation_scope else "intake",
                    reserved_usage=review_reservation)
                topic_refinement = self._topic_refinement_context(stage)
                topic_objective = (
                    topic_refinement.get("objective")
                    if isinstance(topic_refinement, dict)
                    and isinstance(topic_refinement.get("objective"), str)
                    and topic_refinement["objective"].strip()
                    else self.workflow["objective"]
                )
                topic_kwargs = dict(
                    objective=topic_objective,
                    candidate_count=descriptor["candidate_count"],
                    max_attempts=descriptor["max_attempts"],
                    repair_mode=descriptor.get("repair_mode", "bounded"),
                    runtime_context=self._runtime_context(model),
                    bibliography=descriptor.get("bibliography"),
                    budgets=topic_budgets,
                    sampling_seed=self._topic_sampling_seed(attempt_number=attempt_number),
                    maturity_review_rounds=maturity_rounds,
                    refinement_context=topic_refinement,
                )
                if specialist_reports:
                    topic_kwargs["specialist_reports"] = deepcopy(specialist_reports)
                if (isinstance(topic_refinement, dict)
                        and topic_refinement.get("mode") == "response_contract_repair"):
                    result = self._retain_topic_for_contract_repair(
                        self.context.get(stage["id"]), topic_refinement,
                        specialist_reports=specialist_reports)
                else:
                    result = runner.run(**topic_kwargs)
                    self._validate_refined_topic_result(result, topic_refinement)
            except (*PROVIDER_OPERATOR_STOP_ERRORS, ProviderCooldownError):
                raise
            except ValidationError as exc:
                # The bounded descriptor owns one isolated intake. A
                # scientifically rejected direction is still recoverable at
                # the Composer level, where the next attempt receives a fresh
                # sampling boundary and the remaining mission budget. Only
                # the topic runner's explicit evidence trace can authorize
                # that pivot; authentication/provider failures stay on the
                # ordinary provider/error policy instead.
                self._normalize_topic_intake_failure(exc, stage)
                topic_recoverable = (
                    stage.get("kind") == "topic_discovery"
                    and bool(getattr(exc, "topic_intake_recoverable", False))
                )
                topic_retry_reason = getattr(exc, "topic_retry_reason", None)
                if topic_recoverable and not isinstance(topic_retry_reason, str):
                    topic_retry_reason = (
                        "scientific_candidate_rejected"
                        if getattr(exc, "rejected_topic_history", [])
                        else "intake_contract_failure"
                    )
                if (descriptor.get("budgets")
                        and descriptor.get("repair_mode", "bounded") == "bounded"):
                    snapshot = getattr(exc, "topic_budget", {})
                    snapshot = snapshot if isinstance(snapshot, dict) else {}
                    quota_error = QuotaExceededError(
                        "topic discovery bounded intake exhausted after "
                        f"{max(1, len(getattr(exc, 'candidate_attempt_trace', [])))} "
                        "candidate attempt(s) "
                        f"(configured maximum {descriptor['max_attempts']}): {exc}",
                        dimension="topic_attempts", limit=descriptor["max_attempts"],
                        observed=descriptor["max_attempts"],
                        usage=snapshot.get("usage", {}),
                        diagnostics=snapshot.get("events", []),
                    )
                    setattr(quota_error, "retryable_topic_intake", topic_recoverable)
                    if topic_recoverable:
                        # This exception describes an exhausted local
                        # proposal/repair envelope, not exhausted provider
                        # capacity.  Preserve that scope so the outer
                        # Composer can admit a changed intake instead of
                        # routing it to resource-fence reconciliation.
                        quota_error.topic_budget_scope = (
                            "continuation" if continuation_scope else "intake")
                    setattr(quota_error, "topic_retry_reason",
                            topic_retry_reason if topic_recoverable else "intake_failure")
                    setattr(quota_error, "topic_budget", snapshot)
                    # Preserve the bounded runner's scientific trace when the
                    # Composer wraps its validation error as a quota error.
                    # Without this handoff, the run kept provider events but
                    # lost which candidate and review caused each retry.
                    for attribute in ("candidate_attempt_trace", "maturity_review_history",
                                      "rejected_topic_history", "topic_response_repair"):
                        value = getattr(exc, attribute, None)
                        if isinstance(value, (list, dict)):
                            setattr(quota_error, attribute, deepcopy(value))
                    raise quota_error from exc
                if topic_recoverable:
                    # Autonomous topic contracts without a local attempt quota
                    # must still reach the Composer's typed retry path. A raw
                    # ValidationError otherwise looks like an ordinary stage
                    # failure and loses the runner's rejection class.
                    setattr(exc, "retryable_topic_intake", True)
                    setattr(exc, "topic_retry_reason", topic_retry_reason)
                raise
            output_path = Path(descriptor["output_path"])
            if attempt_number > 1 or stage["id"] in self.reopened_stage_ids:
                output_path = Path(stage["project_dir"]) / output_path.name
            output_path.parent.mkdir(parents=True, exist_ok=True)
            if (result.get("schema_version") == "topic-discovery-1"
                    and isinstance(result.get("candidates"), list)
                    and isinstance(result.get("selected_id"), str)):
                from scisaurus.runtime.research_program import build_research_program
                try:
                    research_program = build_research_program(result)
                except ValidationError as exc:
                    # Keep the runner's bounded accounting when a downstream
                    # materializer catches a candidate-level contract issue.
                    # Without this handoff the Composer sees zero usage and
                    # loses the scientific retry class.
                    for attribute in (
                            "usage", "topic_budget", "candidate_attempt_trace",
                            "maturity_review_history", "rejected_topic_history"):
                        value = result.get(attribute)
                        if value is not None and not hasattr(exc, attribute):
                            setattr(exc, attribute, deepcopy(value))
                    self._normalize_topic_intake_failure(exc, stage)
                    raise
                research_program_path = output_path.parent / "research-program.json"
                research_program_path.write_bytes(canonical_bytes(research_program))
                result["research_program"] = research_program
                result["research_program_path"] = str(research_program_path.resolve())
            output_path.write_bytes(canonical_bytes(result))
        elif kind in {"survey", "experiment"}:
            if kind == "survey":
                config = self._apply_topic_to_survey_config(stage, config)
            elif kind == "experiment":
                # Capability authoring runs inside topic projection. Freeze
                # the downstream journal floor first so its generated
                # executor is required to emit the analysis ledger that the
                # result-package gate will later validate.
                config = self._ensure_journal_quality_contract(stage, config)
                config = self._apply_topic_to_experiment_config(
                    stage, config,
                    model_call_budget=self._foundry_model_call_budget(stage))
                self._sync_foundry_usage()
                foundry_usage_delta = self._usage_delta(
                    self.foundry_usage, foundry_usage_before)
            config = self._apply_bindings(config, stage["bindings"])
            stage_deadline = self._stage_remaining(stage)
            if kind == "experiment":
                config = self._ensure_journal_quality_contract(stage, config)
            config.setdefault("limits", {})["wall_clock_seconds"] = min(
                float(config["limits"]["wall_clock_seconds"]), stage_deadline)
            if "time_policy" in config and isinstance(config["time_policy"], dict):
                config["time_policy"]["hard_seconds"] = min(
                    float(config["time_policy"].get("hard_seconds", stage_deadline)), stage_deadline)
                config["time_policy"]["target_seconds"] = min(
                    float(config["time_policy"].get("target_seconds", stage_deadline)),
                    config["time_policy"]["hard_seconds"])
                config["time_policy"]["first_result_seconds"] = min(
                    float(config["time_policy"].get("first_result_seconds", config["time_policy"]["target_seconds"])),
                    config["time_policy"]["target_seconds"])
            if kind == "survey":
                from scisaurus.runtime.survey import SurveyRunner
                project_dir = Path(stage["project_dir"])
                prior_run = project_dir / "output" / "run.json"
                resume_policy = None
                declared_revalidation_scopes = self._survey_revalidation_scopes(stage)
                revalidation_scopes, mapping_milestone = self._survey_revalidation_resume_plan(stage, declared_revalidation_scopes)
                project_has_checkpoint = (project_dir / "state" / "control.sqlite").is_file()
                prior = {}
                if prior_run.is_file():
                    try:
                        prior = json.loads(prior_run.read_text())
                    except (OSError, ValueError):
                        prior = {}
                durable_config = (
                    self._durable_stage_config(project_dir)
                    if project_has_checkpoint else None
                )
                # A continuation can be interrupted after the durable survey
                # store is created but before SurveyRunner writes run.json.
                # That is still a resumable run, not a new-directory request.
                # An empty crash-created scaffold is different: it has no
                # immutable runner input and must be initialized as a fresh
                # survey, not sent through ResumeController.
                resumable_checkpoint = (
                    project_has_checkpoint
                    and durable_config is not None
                    and (bool(revalidation_scopes) or not prior_run.is_file()
                         or prior.get("status") in {"blocked", "paused", "running"})
                )
                if revalidation_scopes and not resumable_checkpoint:
                    raise StateError("survey revalidation requires the retained immutable runner input")
                provider_fallback = None
                if resumable_checkpoint:
                    # The durable runner input is authoritative for a
                    # resumed workspace.  Reapplying the current descriptor
                    # would replace the selected topic, project identity, or
                    # provider route and makes ResumeController reject the
                    # checkpoint.
                    config = durable_config
                    fallback = self.context.get(stage["id"], {}).get("provider_fallback")
                    if (isinstance(fallback, dict)
                            and fallback.get("mode") == "crossref_metadata"):
                        provider_fallback = "crossref_metadata"
                    scopes = revalidation_scopes or [self._survey_resume_scope(
                        prior, stage_context=self.context.get(stage["id"]))]
                    resume_policy = {
                        # Composer owns autonomous recovery.  A process
                        # interruption cannot observe an in-flight model
                        # response, so reconcile it as one conservative
                        # model call before retrying the scoped survey.
                        "additional_seconds": min(
                            float(config["limits"]["wall_clock_seconds"]),
                            self._stage_remaining(stage),
                        ),
                        "unknown_outcomes": {
                            "mode": "charge_and_retry",
                            "usage_per_attempt": {"model_calls": 1},
                        },
                        "source_changes": {"mode": "reopen", "reopen_scopes": scopes},
                    }
                    self._publish(f"command/composer/recovery/{stage['id']}-{len(self.feedback) + 1}",
                                  "decision_note", {
                                      "stage_id": stage["id"], "action": "resume_scoped_stage",
                                      "scopes": scopes, "reason": prior.get("error", "scoped stage revalidation"),
                                      "additional_seconds": resume_policy["additional_seconds"],
                                  }, "command.composer")
                delegation = self._stage_model_delegation(stage)
                result = SurveyRunner(stage["project_dir"], config, on_progress=self._stage_progress(stage),
                                      work_orders=self._survey_producer_work_orders(stage),
                                      review_obligations=self._survey_review_obligations(stage),
                                      resume_policy=resume_policy,
                                      provider_fallback=provider_fallback,
                                      model_call_budget_scopes=[delegation["scope"]] if delegation else [],
                                      model_budget_delegation=delegation).run()
                result["usage"] = self._incremental_stage_usage(stage, result.get("usage", {}))
                if revalidation_scopes:
                    try:
                        self._record_survey_revalidation(stage, result, revalidation_scopes, prior.get("run_id"),
                                                         declared_scopes=declared_revalidation_scopes, mapping_milestone=mapping_milestone)
                    except Exception as exc:
                        exc.usage = deepcopy(result["usage"])
                        raise
                self._raise_stage_failure(result)
            else:
                from scisaurus.runtime.experiment import ExperimentRunner
                result = ExperimentRunner(stage["project_dir"], config,
                                          on_progress=self._stage_progress(stage)).run()
                result["usage"] = self._incremental_stage_usage(stage, result.get("usage", {}))
            if kind == "experiment":
                result["foundry_usage"] = deepcopy(foundry_usage_delta)
                # The runner's result-package schema describes a study, while
                # the Composer tracks the selected capability. Keep both
                # identities explicit in its outer runtime envelope.
                self._annotate_experiment_result_capability(stage, result)
            if kind == "survey":
                gated = self._gate_free_topic_survey(result, stage=stage)
                if gated is not result:
                    # Preserve the SurveyRunner's own output and write the
                    # Composer admission decision beside it so a process
                    # interruption can restore the hold and its work orders
                    # without relying on in-memory state.
                    gated_path = Path(stage["project_dir"]) / "output" / "composer-gated-run.json"
                    gated_path.parent.mkdir(parents=True, exist_ok=True)
                    gated_path.write_bytes(canonical_bytes(gated))
                    result = gated
                    output_path = gated_path
                else:
                    result = gated
            if output_path is None:
                output_path = Path(stage["project_dir"]) / "output" / "run.json"
        elif kind == "interpretation":
            from scisaurus.runtime.scientific_interpretation import ScientificInterpretationRunner
            descriptor_bindings = [item for item in stage["bindings"]
                                   if not item["target"].startswith("packet.")]
            config = self._apply_bindings(config, descriptor_bindings)
            model_path = Path(config.pop("model_config_path"))
            input_path = Path(config.pop("input_path"))
            output_path = Path(config.pop("output_path"))
            if config:
                raise ValidationError(f"interpretation descriptor has unknown fields: {sorted(config)}")
            packet = json.loads(input_path.read_text())
            packet = self._project_continuation_requests(packet, stage)
            packet = self._attach_topic_program(packet)
            for binding in stage["bindings"]:
                if binding["target"].startswith("packet."):
                    value = self._source_value(binding["source"])
                    if isinstance(value, str) and Path(value).is_file() and binding["target"].endswith("results_package"):
                        value = json.loads(Path(value).read_text())
                    _set_path(packet, binding["target"][len("packet."):], value)
            self._synchronize_research_packet_identity(packet)
            packet["maturity_requirements"] = self._active_maturity_requirements(stage)
            self._attach_stage_survey_evidence(packet, stage)
            result = ScientificInterpretationRunner(
                self._stage_model_config(stage, json.loads(model_path.read_text())),
                deadline_seconds=stage_deadline).run(packet)
            output_path.parent.mkdir(parents=True, exist_ok=True)
            output_path.write_bytes(canonical_bytes(result))
            result = {"status": "completed", "output_path": str(output_path.resolve()),
                      "usage": deepcopy(result.get("usage", {})), "interpretation": result}
        elif kind == "argument":
            from scisaurus.runtime.research_argument import ResearchArgumentRunner, argument_evidence_packet
            descriptor_bindings = [item for item in stage["bindings"]
                                   if not item["target"].startswith("packet.")]
            config = self._apply_bindings(config, descriptor_bindings)
            model_path = Path(config.pop("model_config_path"))
            input_path = Path(config.pop("input_path"))
            output_path = Path(config.pop("output_path"))
            if config:
                raise ValidationError(f"argument descriptor has unknown fields: {sorted(config)}")
            packet = json.loads(input_path.read_text())
            # Argument repair orders are scientific work orders, not merely
            # Composer ledger entries.  Put them into the fresh evidence
            # packet before the bound experiment and interpretation artifacts
            # are applied so the adjudicator can act on the exact requested
            # repair instead of replaying the old argument.
            packet = self._project_continuation_requests(packet, stage)
            packet = self._attach_topic_program(packet)
            for binding in stage["bindings"]:
                if binding["target"].startswith("packet."):
                    value = self._source_value(binding["source"])
                    if isinstance(value, str) and Path(value).is_file() and binding["target"].endswith("results_package"):
                        value = json.loads(Path(value).read_text())
                    _set_path(packet, binding["target"][len("packet."):], value)
            self._synchronize_research_packet_identity(packet)
            model = self._stage_model_config(stage, json.loads(model_path.read_text()))
            self._attach_stage_survey_evidence(packet, stage)
            minimums = self._argument_minimums(stage["id"], config)
            result = ResearchArgumentRunner(model, deadline_seconds=stage_deadline).run(
                argument_evidence_packet(packet), max_attempts=1,
                max_response_attempts=2, max_adjudication_attempts=2,
                min_figures=minimums["figures"],
                min_tables=minimums["tables"], min_experiments=minimums["experiments"])
            output_path.parent.mkdir(parents=True, exist_ok=True)
            output_path.write_bytes(canonical_bytes(result))
            result = {"status": "completed", "output_path": str(output_path.resolve()),
                      "usage": deepcopy(result.get("usage", {})),
                      "argument_package": result, "argument": result.get("argument")}
        elif kind == "paper" and config.get("schema_version") == "review-article-config-1":
            from scisaurus.runtime.review_article import ReviewArticleRunner
            config = self._apply_bindings(config, stage["bindings"])
            config["work_orders"] = self._follow_up_projection(self._requests_for_stage(stage))
            result = ReviewArticleRunner(
                config, retained_work_dir=self.root / "retained-review-work" / stage["id"],
                model_config=self._stage_model_config(
                    stage, json.loads(Path(config["model_config_path"]).read_text())),
                deadline_seconds=stage_deadline,
                on_progress=lambda event: self._record_internal_feedback(stage, event),
            ).run()
            output_path = Path(result["output_path"])
        else:  # empirical paper
            from scisaurus.runtime.paper_pipeline import PaperPipelineRunner
            # The paper descriptor names three independently versioned inputs.
            # Bindings addressed as ``packet.*`` or ``paper_config.*`` are
            # applied to those loaded objects; descriptor bindings (for
            # example ``argument_package_path``) are applied before loading.
            descriptor_bindings = [item for item in stage["bindings"]
                                   if not item["target"].startswith(("packet.", "paper_config."))]
            config = self._apply_bindings(config, descriptor_bindings)
            required = {"packet_path", "model_config_path", "paper_config_path", "output_dir", "argument_package_path",
                        "images", "max_review_rounds", "review_deadline_seconds", "pipeline_deadline_seconds",
                        "argument_deadline_seconds", "min_argument_figures", "min_argument_tables", "min_argument_experiments"}
            optional = {"draft_path", "initial_review_package_path", "release_on_review_limit",
                        "review_max_output_tokens", "review_reasoning_effort",
                        "review_call_timeout_seconds", "review_inter_request_interval_seconds",
                        "repair_max_output_tokens", "model_call_timeout_seconds",
                        "review_arbiter_enabled", "model_concurrency",
                        "research_redteam_deadline_seconds", "research_redteam_max_attempts"}
            if set(config) - required - optional or not required.issubset(config):
                raise ValidationError(
                    f"paper descriptor requires {sorted(required)} and permits {sorted(optional)}")
            if "release_on_review_limit" in config and type(config["release_on_review_limit"]) is not bool:
                raise ValidationError("paper descriptor release_on_review_limit must be Boolean")
            if "review_arbiter_enabled" in config and type(config["review_arbiter_enabled"]) is not bool:
                raise ValidationError("paper descriptor review_arbiter_enabled must be Boolean")
            if "research_redteam_deadline_seconds" in config:
                value = config["research_redteam_deadline_seconds"]
                if (type(value) not in (int, float) or not math.isfinite(value) or value <= 0):
                    raise ValidationError(
                        "paper descriptor research_redteam_deadline_seconds must be finite and positive")
            if "research_redteam_max_attempts" in config:
                value = config["research_redteam_max_attempts"]
                if type(value) is not int or not 1 <= value <= 8:
                    raise ValidationError(
                        "paper descriptor research_redteam_max_attempts must be an integer from 1 to 8")
            packet = json.loads(Path(config["packet_path"]).read_text())
            packet = self._project_continuation_requests(packet, stage)
            packet = self._attach_topic_program(packet)
            model = self._stage_model_config(stage, json.loads(Path(config["model_config_path"]).read_text()))
            paper_config = json.loads(Path(config["paper_config_path"]).read_text())
            draft = (json.loads(Path(config["draft_path"]).read_text())
                     if config.get("draft_path") else None)
            initial_review_package = (json.loads(Path(config["initial_review_package_path"]).read_text())
                                     if config.get("initial_review_package_path") else None)
            for binding in stage["bindings"]:
                if binding["target"].startswith("packet."):
                    value = self._source_value(binding["source"])
                    if isinstance(value, str) and Path(value).is_file() and binding["target"].endswith("results_package"):
                        value = json.loads(Path(value).read_text())
                    _set_path(packet, binding["target"][len("packet."):], value)
                elif binding["target"].startswith("paper_config."):
                    value = self._source_value(binding["source"])
                    if binding["target"] == "paper_config.interpretation_file":
                        value = self._interpretation_binding_path(value)
                    _set_path(paper_config, binding["target"][len("paper_config."):], value)
            self._synchronize_research_packet_identity(packet)
            # The paper descriptor is often prepared before discovery.  Once
            # the current survey has been accepted, project its actual source
            # set into the fresh paper input on the first pass as well as on a
            # continuation; otherwise the depth gate would inspect stale
            # references from an earlier mission.
            if "survey" in self.context:
                paper_config = self._synchronize_paper_references(paper_config)
            argument_package_path = config["argument_package_path"]
            argument_package = json.loads(Path(argument_package_path).read_text()) if argument_package_path else None
            paper_config = self._synchronize_paper_figure_arguments(
                paper_config, packet, argument_package)
            paper_config, packet = self._synchronize_catalog_paper_inputs(
                paper_config, packet, argument_package)
            config = self._extend_paper_images(config, packet, paper_config)
            review_call_timeout = config.get("review_call_timeout_seconds")
            if review_call_timeout is not None:
                review_call_timeout = min(review_call_timeout, stage_deadline)
            model_call_timeout = config.get("model_call_timeout_seconds")
            if model_call_timeout is not None:
                model_call_timeout = min(model_call_timeout, stage_deadline)
            runner = PaperPipelineRunner(packet=packet, model_config=model, paper_config=paper_config,
                output_dir=config["output_dir"], image_paths=config["images"],
                max_review_rounds=config["max_review_rounds"],
                review_deadline_seconds=min(config["review_deadline_seconds"], stage_deadline),
                pipeline_deadline_seconds=min(config["pipeline_deadline_seconds"], stage_deadline),
                argument_deadline_seconds=min(config["argument_deadline_seconds"], stage_deadline),
                review_max_output_tokens=config.get("review_max_output_tokens"),
                review_reasoning_effort=config.get("review_reasoning_effort", "xhigh"),
                review_call_timeout_seconds=review_call_timeout,
                review_inter_request_interval_seconds=config.get("review_inter_request_interval_seconds", 0.5),
                repair_max_output_tokens=config.get("repair_max_output_tokens"),
                model_call_timeout_seconds=model_call_timeout,
                model_concurrency=config.get("model_concurrency", 1),
                review_arbiter_enabled=bool(config.get("review_arbiter_enabled", True)),
                research_redteam_deadline_seconds=min(
                    config.get("research_redteam_deadline_seconds", 900.0), stage_deadline),
                research_redteam_max_attempts=config.get("research_redteam_max_attempts", 3),
                draft=draft, initial_review_package=initial_review_package,
                release_on_review_limit=bool(config.get("release_on_review_limit", False)),
                draft_before_research_review=self._allows_provisional_progress(),
                retained_work_dir=self.root / "retained-paper-work" / stage["id"],
                deferred_requirements=[{
                    "stage_id": key, "findings": value.get("deferred_review_findings"),
                    "requirements": value.get("carried_maturity_requirements", []),
                } for key, value in self.context.items() if isinstance(value, dict)
                   and (value.get("deferred_review_findings") or value.get("carried_maturity_requirements"))],
                initial_argument_package=argument_package,
                min_argument_figures=(0 if self._allows_provisional_progress() else config["min_argument_figures"]),
                min_argument_tables=(0 if self._allows_provisional_progress() else config["min_argument_tables"]),
                min_argument_experiments=(1 if self._allows_provisional_progress() else config["min_argument_experiments"]),
                feedback_callback=lambda event: self._record_internal_feedback(stage, event))
            result = runner.run()
            output_path = Path(result["pdf"] or result.get("preflight_path")
                               or result.get("pipeline_result_path") or config["output_dir"])
        if not isinstance(result, dict):
            raise ValidationError(f"{kind} stage returned a non-object result")
        context = {**result, "stage_id": stage["id"], "kind": kind,
                   "project_dir": str(Path(stage["project_dir"]).resolve()),
                   "output_path": str(output_path.resolve())}
        if kind == "experiment":
            context["results_package"] = result.get("results_package")
            # ``_apply_topic_to_experiment_config`` increments the repair
            # lineage before the foundry call. Stage runners return their own
            # result envelope, so explicitly carry the lineage fields into
            # that envelope; otherwise the next failed attempt is mistaken
            # for the first repair and regenerates the same capability.
            incumbent = self.context.get(stage["id"])
            if isinstance(incumbent, dict):
                for key in (
                        "capability_repair_attempts",
                        "experiment_repair_history",
                        "experiment_repair_plan",
                        "capability_repair_panel",
                ):
                    if key in incumbent:
                        context[key] = deepcopy(incumbent[key])
        if kind == "argument":
            context["argument_package_path"] = context["output_path"]
        return context

    def _overlay_child_progress(self, state):
        """Project observed work without changing settled costs or stage authority."""
        settled = state.get("usage", {})
        state["observed_usage"] = deepcopy(settled)
        for stage_id, record in state.get("stages", {}).items():
            record.pop("child_progress", None)
            child = self._child_progress.get(stage_id)
            if (not child or record.get("status") != "running"
                    or record.get("attempt_id") != child["attempt_id"]):
                continue
            record["child_progress"] = deepcopy(child["state"])
            if child["activity_active"]:
                record["active_agents"] = list(dict.fromkeys(
                    operation["actor"] for operation in child["state"]["active_operations"]))
                if state.get("phase", "").split(":", 1)[0] == stage_id:
                    state["phase"] = f"{stage_id}:{child['state']['phase']}"
            namespace = hashlib.sha256(child["state"]["project_dir"].encode()).hexdigest()
            committed = self.stage_usage_totals.get(namespace, {})
            for key, quantity in child["state"]["cumulative_usage"].items():
                baseline = max(child["baseline"].get(key, 0), committed.get(key, 0))
                state["observed_usage"][key] = state["observed_usage"].get(key, 0) + max(0, quantity - baseline)

    def _clear_child_progress(self, stage_id):
        with self._progress_lock:
            self._child_progress.pop(stage_id, None)
            record = self._progress_snapshot.get("stages", {}).get(stage_id, {})
            record.pop("child_progress", None)
            self._progress_snapshot["usage"] = deepcopy(self.usage)
            self._progress_snapshot["observed_usage"] = deepcopy(self.usage)

    def _stage_progress(self, stage):
        attempt_id = self.stage_records.get(stage["id"], {}).get("attempt_id")
        project_dir = str(Path(stage["project_dir"]).resolve())
        _, baseline = self._stage_usage_baseline(project_dir)
        run_id = None

        def callback(state):
            nonlocal run_id
            current = self.stage_records.get(stage["id"], {})
            if current.get("status") != "running" or current.get("attempt_id") != attempt_id:
                return
            if not isinstance(state.get("run_id"), str):
                self._checkpoint(f"{stage['id']}:{state.get('phase', 'progress')}")
                return
            if state.get("project_dir") != project_dir or run_id not in (None, state["run_id"]):
                return
            operations = state.get("active_operations")
            usage = state.get("cumulative_usage")
            if (not isinstance(operations, list) or not isinstance(usage, dict)
                    or any(not isinstance(operation, dict) or any(
                        not isinstance(operation.get(key), str) for key in ("task_id", "actor", "kind"))
                        for operation in operations)
                    or any(type(value) not in (int, float) or not math.isfinite(value) or value < 0
                           for value in usage.values())):
                return
            run_id = state["run_id"]
            telemetry = {key: deepcopy(state[key]) for key in (
                "run_id", "project_dir", "phase", "active_tasks", "active_operations",
                "cumulative_usage", "reserved_usage", "time_plan") if key in state}
            with self._progress_lock:
                self._child_progress[stage["id"]] = {"attempt_id": attempt_id,
                    "baseline": baseline, "state": telemetry, "activity_active": True}
                snapshot = deepcopy(self._progress_snapshot)
                snapshot["usage"] = deepcopy(self.usage)
                snapshot["phase"] = f"{stage['id']}:{state.get('phase', 'progress')}"
                snapshot.setdefault("stages", {})[stage["id"]] = deepcopy(current)
                self._overlay_child_progress(snapshot)
                self._progress_snapshot = snapshot
            self._live_progress(snapshot["phase"])
        return callback

    def _record_feedback(self, stage, context):
        route = self.departments.stage_route(stage["kind"])
        assignment = self.stage_records.get(stage["id"], {})
        action = ("advance" if context.get("status") in {"completed", "accepted", "candidate_needs_review"}
                  else "reconcile_blocker")
        if context.get("status") == "research_expansion_required":
            action = "request_research_expansion"
        elif context.get("status") == "review_rejected":
            action = "editor_rejected"
        if action == "advance":
            consumers = [candidate for candidate in self.workflow["stages"]
                         if stage["id"] in candidate["depends_on"]]
            recipient = (self._address_for_role(STAGE_ROLES[consumers[0]["kind"]])
                         if consumers else COMMAND_ADDRESSES["intent"])
        else:
            recipient = COMMAND_ADDRESSES["arbiter"]
            if action == "request_research_expansion":
                requests = context.get("research_expansion_requests", [])
                owners = {item.get("owner") for item in requests if isinstance(item, dict)}
                if len(owners) == 1 and next(iter(owners)):
                    recipient = self._address_for_role(next(iter(owners)))
            elif action == "editor_rejected":
                recipient = self._address_for_role("editorial.composer")
        feedback = {
            "stage_id": stage["id"], "role": route["role"],
            "department": route["department"],
            "owner_agent": route["chief"],
            "adversary_agent": route["adversary"],
            "required_agents": deepcopy(assignment.get("required_agents", route["required_agents"])),
            "active_agents": deepcopy(assignment.get(
                "active_agents", assignment.get("last_active_agents", []))),
            "verifier_agent": assignment.get("verifier_agent", route["verifier_agent"]),
            "chief_synthesis_ref": assignment.get("chief_synthesis_ref"),
            "verifier_artifact_ref": assignment.get("verifier_artifact_ref"),
            "from": COMMAND_ADDRESSES["progress"], "to": recipient,
            "status": context.get("status"), "output_path": context.get("output_path"),
            "scientific_state": context.get("gap_state") or context.get("review_status") or context.get("argument_status"),
            "research_expansion_requests": deepcopy(context.get("research_expansion_requests", [])),
            "action": action,
            "stage_deadline_seconds": stage["deadline_seconds"],
            "elapsed_seconds": context.get("elapsed_seconds"),
            "dependencies": list(stage["depends_on"]),
            "next_condition": "all declared dependencies current and stage output independently checked",
        }
        if context.get("status") == "research_expansion_required":
            feedback["next_condition"] = "complete every scoped literature, experiment, or analysis request and re-run the admission gate"
        elif context.get("status") == "review_rejected":
            feedback["next_condition"] = "reopen the rejected research or manuscript scope and obtain a new three-stage editorial decision"
        elif context.get("status") not in {"completed", "accepted", "candidate_needs_review"}:
            feedback["next_condition"] = "reconcile the stage blocker before downstream admission"
        elif context.get("status") == "candidate_needs_review":
            feedback["next_condition"] = "principal review is required before external submission"
        feedback["message_id"] = f"composer-feedback-{uuid.uuid4().hex}"
        feedback["message_disposition"] = "scheduled" if action == "advance" else "escalated"
        self.feedback.append(feedback)
        note = self._publish(f"command/composer/feedback/{stage['id']}-{len(self.feedback)}", "decision_note", feedback,
                             "command.composer")
        self._route_feedback(feedback, note)

    def _feedback_address(self, event):
        """Choose the receiving organ for an internal specialist exchange."""
        kind = event.get("kind")
        reviewer = event.get("reviewer_id")
        if kind in {"review_failure", "synthesis_failure", "arbitration_failure", "repair_failure"}:
            return COMMAND_ADDRESSES["arbiter"]
        if kind == "research_gate":
            owners = {item.get("owner") for item in event.get("expansion_requests", [])
                      if isinstance(item, dict)}
            if len(owners) == 1 and next(iter(owners)):
                return self._address_for_role(next(iter(owners)))
            if event.get("decision") in {"proceed", "accept"}:
                return self._address_for_role("editorial.composer")
            return COMMAND_ADDRESSES["arbiter"]
        if kind == "editor_decision":
            return self._address_for_role("editorial.composer")
        if kind == "review":
            # A blocking critique is a dispute for the Arbiter; ordinary
            # findings remain with the department that owns the surface.
            if (event.get("severity_counts") or {}).get("blocking", 0):
                return COMMAND_ADDRESSES["arbiter"]
            if reviewer == "science":
                return self._address_for_role("strategy.interpretation")
            if reviewer == "methods":
                return self._address_for_role("methods.validation")
            if reviewer == "journal_editor":
                # Publication-depth findings are editorial admission
                # decisions.  They must reach the editor-in-chief rather than
                # being treated as an ordinary copy edit.
                return self._address_for_role("editorial.composer")
            return self._address_for_role("editorial.composer")
        if kind in {"argument", "draft", "repair"}:
            return self._address_for_role("editorial.composer")
        if kind == "release":
            return COMMAND_ADDRESSES["intent"]
        if kind == "synthesis":
            return (COMMAND_ADDRESSES["arbiter"]
                    if event.get("decision") == "insufficient_evidence"
                    else self._address_for_role("editorial.composer"))
        return COMMAND_ADDRESSES["arbiter"]

    def _record_internal_feedback(self, stage, event):
        """Route reviewer/editor events through the same Composer desk.

        Stage runners retain write authority over their own artifacts, while
        the Composer owns the organizational exchange. Event IDs are stable
        across checkpoint resume, so replaying a cached review cannot create
        duplicate messages or acknowledgements.
        """
        if not isinstance(event, dict) or not event.get("kind"):
            raise ValidationError("internal composer feedback requires a kind")
        event_id = event.get("event_id")
        if not isinstance(event_id, str) or not event_id.strip():
            stable = canonical_bytes({key: event[key] for key in sorted(event) if key != "artifact_path"})
            event_id = f"{stage['id']}:{hashlib.sha256(stable).hexdigest()[:24]}"
        # PaperPipelineRunner deliberately uses semantic event IDs so a
        # replay inside one pass is idempotent.  A reopened paper is a new
        # scientific pass, so namespace those IDs by Composer cycle while
        # preserving same-cycle deduplication and resume stability.
        # ArtifactRef logical names cannot contain a colon.  Normalize model
        # supplied IDs once at the control boundary and retain a short digest
        # when normalization changed their identity.
        safe_event_id = re.sub(r"[^A-Za-z0-9_.-]+", "-", event_id).strip("-")
        if safe_event_id != event_id:
            safe_event_id = f"{safe_event_id[:72]}-{hashlib.sha256(event_id.encode('utf-8')).hexdigest()[:8]}"
        event_id = safe_event_id or f"{stage['id']}-{hashlib.sha256(canonical_bytes(event)).hexdigest()[:24]}"
        if (self.continuation_cycles and stage["id"] in self.reopened_stage_ids
                and not event_id.startswith(f"cycle-{self.continuation_cycles}-")):
            event_id = f"cycle-{self.continuation_cycles}-{event_id}"
        if any(item.get("event_id") == event_id for item in self.feedback):
            return
        status = event.get("status", "needs_revision")
        failure = event.get("kind", "").endswith("failure") or status == "blocked"
        recipient = self._feedback_address(event)
        route = self.departments.stage_route(stage["kind"])
        internal_role = None
        reviewer_id = event.get("reviewer_id")
        if reviewer_id == "science":
            internal_role = "review.science"
        elif reviewer_id == "methods":
            internal_role = "review.methods"
        elif reviewer_id == "journal_editor":
            internal_role = "review.journal_editor"
        elif event.get("kind") in {"argument", "draft"}:
            internal_role = "strategy.argument"
        elif event.get("kind") == "release":
            internal_role = "editorial.writer"
        internal_assignment = (self.departments.role_for_internal_role(internal_role)
                               if internal_role else None)
        stage_assignment = self.stage_records.get(stage["id"], {})
        action = ("reconcile_blocker" if failure else
                  "request_research_expansion" if status == "research_expansion_required" else
                  "editor_rejected" if status == "rejected" else
                  "request_revision" if status in {"needs_revision", "revise"} else
                  "verify_repair" if event.get("kind") == "repair" else
                  "propose_release" if event.get("kind") == "release" else
                  "record_observation")
        feedback = {
            "event_id": event_id,
            "stage_id": stage["id"],
            "role": STAGE_ROLES[stage["kind"]],
            "department": route["department"],
            "owner_agent": route["chief"],
            "adversary_agent": route["adversary"],
            "required_agents": deepcopy(stage_assignment.get("required_agents", route["required_agents"])),
            "active_agents": deepcopy(stage_assignment.get("active_agents", [])),
            "verifier_agent": stage_assignment.get("verifier_agent", route["verifier_agent"]),
            "internal_role": internal_role,
            "internal_agent": ({"dept": internal_assignment["department"], "agent": internal_assignment["agent"]}
                                if internal_assignment else None),
            "from": {"dept": "specialist-review", "agent": event["kind"]},
            "to": recipient,
            "status": status,
            "action": action,
            "event": deepcopy(event),
            "output_path": event.get("artifact_path") or event.get("pdf_path"),
            "stage_deadline_seconds": stage["deadline_seconds"],
            "dependencies": list(stage["depends_on"]),
            "next_condition": (
                "Arbiter validates the failure and Progress Controller reopens only the affected scope"
                if failure else
                "the receiving department records a scoped response before the next Composer admission"
            ),
            "message_id": "composer-feedback-" + hashlib.sha256(
                f"{self.workflow['id']}:{event_id}".encode("utf-8")).hexdigest()[:32],
            "message_disposition": "escalated" if failure else "scheduled",
        }
        if status == "research_expansion_required":
            feedback["next_condition"] = (
                "Complete every requested literature, experiment, or interpretation workstream, then re-admit the paper stage."
            )
        elif status == "rejected":
            feedback["next_condition"] = (
                "Reopen the rejected research scope and obtain a new three-stage reviewer and editor decision."
            )
        self.feedback.append(feedback)
        note = self._publish(
            f"command/composer/internal/{stage['id']}/{event_id}",
            "decision_note", feedback, "command.composer")
        self._route_feedback(feedback, note)
        self._checkpoint(f"{stage['id']}:feedback:{event['kind']}")

    def _route_feedback(self, feedback, note):
        """Route one durable command decision through the project message bus.

        The note is the immutable decision record; the envelope is the
        asynchronous handoff a department would receive in an ordinary
        organization.  Both carry the same body and reference, so a resumed
        Composer can reconstruct who acted, why, and what must happen next.
        """
        message_type = "decision" if feedback.get("action") == "advance" else "critique"
        envelope = {
            "message_id": feedback["message_id"],
            "project_id": self.workflow["project_id"],
            "type": message_type,
            "from": feedback.get("from", COMMAND_ADDRESSES["progress"]),
            "to": feedback.get("to", COMMAND_ADDRESSES["arbiter"]),
            "subject": f"{feedback.get('action', 'review')}:{feedback.get('stage_id', 'workflow')}",
            "body": json.dumps(feedback, ensure_ascii=False, sort_keys=True),
            "refs": [note["artifact_ref"]],
            "created_at": now_iso(),
            "idempotency_key": f"feedback:{self.workflow['id']}:{feedback.get('event_id') or feedback.get('message_id')}",
        }
        message_id = self.messages.publish(envelope)
        # Persist the receiving department's inbox and any typed work orders
        # before acknowledging the envelope.  This makes a handoff an actual
        # organizational operation rather than metadata attached only to the
        # Composer's own ledger.
        self.departments.receive_message(message_id, feedback, note["artifact_ref"])
        # The recipient's department chief owns receipt.  Acknowledging the
        # envelope here is the bounded command-desk handoff: the specialist
        # stage itself still has to satisfy its own acceptance contract before
        # the next dependency is admitted.  If receipt cannot be committed,
        # surface that control-plane failure instead of presenting a false
        # downstream decision.
        owner = f"{feedback['to']['dept']}.{feedback['to']['agent']}"
        # Receipt is a local control-plane operation and must remain durable
        # even when the stage has just crossed its execution deadline.  The
        # deadline controls new scientific work; it does not erase the audit
        # trail for a failed handoff.
        fence = self.messages.lease(message_id, owner=owner, ttl_seconds=30.0)
        self.messages.acknowledge(message_id, fence, feedback["message_disposition"], actor=owner)
        if message_id != feedback["message_id"]:
            raise ValidationError("message bus returned a different feedback message ID")

    def _record_blocker_feedback(self, stage, error):
        route = self.departments.stage_route(stage["kind"])
        assignment = self.stage_records.get(stage["id"], {})
        feedback = {
            "stage_id": stage["id"], "role": route["role"],
            "department": route["department"],
            "owner_agent": route["chief"],
            "adversary_agent": route["adversary"],
            "required_agents": deepcopy(assignment.get("required_agents", route["required_agents"])),
            "active_agents": deepcopy(assignment.get(
                "active_agents", assignment.get("last_active_agents", []))),
            "verifier_agent": assignment.get("verifier_agent", route["verifier_agent"]),
            "chief_synthesis_ref": assignment.get("chief_synthesis_ref"),
            "verifier_artifact_ref": assignment.get("verifier_artifact_ref"),
            "from": COMMAND_ADDRESSES["progress"], "to": COMMAND_ADDRESSES["arbiter"],
            "status": "blocked", "action": "reconcile_blocker",
            "error": str(error), "stage_deadline_seconds": stage["deadline_seconds"],
            "dependencies": list(stage["depends_on"]),
            "next_condition": "Arbiter validates the blocker and Progress Controller reopens only its affected scope",
        }
        feedback["message_id"] = f"composer-feedback-{uuid.uuid4().hex}"
        feedback["message_disposition"] = "escalated"
        self.feedback.append(feedback)
        note = self._publish(f"command/composer/feedback/{stage['id']}-{len(self.feedback)}", "decision_note", feedback,
                             "command.composer")
        self._route_feedback(feedback, note)

    def _resolve_terminal_stage_work_orders(self, stage):
        """Close scoped work orders when their owning stage is terminally blocked.

        A stage failure can happen before its normal success path reaches the
        work-order resolver. Leaving the request running then makes the
        dashboard claim that a repair is active after the Composer has already
        stopped. Holds intentionally bypass this helper and remain running for
        the next continuation cycle.
        """
        if not self.active_research_requests:
            return []
        resolved = self.departments.resolve_work_orders(
            self.active_research_requests, stage_kind=stage["kind"], stage_id=stage["id"], outcome="blocked")
        if resolved:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "resolve_work_orders",
                "stage_id": stage["id"],
                "outcome": "blocked",
                "work_orders": resolved,
            })
        return resolved

    @staticmethod
    def _valid_topic_pivot_scientific_basis(basis):
        """Accept only typed, persisted research judgments as pivot evidence."""
        if not isinstance(basis, dict):
            return False
        if basis.get("kind") == "topic_candidate_rejection":
            if basis.get("retry_reason") != "scientific_candidate_rejected":
                return False
            rejections = basis.get("rejected_candidates")
            if not isinstance(rejections, list):
                return False
            return any(
                isinstance(item, dict)
                and isinstance(item.get("topic_id"), str)
                and item["topic_id"].strip()
                and item.get("rejection_type") in {
                    "novelty", "source_challenge", "maturity", "refinement",
                }
                and isinstance(item.get("rejection_reason"), str)
                and item["rejection_reason"].strip()
                for item in rejections
            )
        if basis.get("kind") == "parent_refinement_rejection":
            return (
                isinstance(basis.get("parent_topic_id"), str)
                and bool(basis["parent_topic_id"].strip())
                and basis.get("rejection_type") == "refinement"
                and _topic_validation_rejection_type(
                    basis.get("validation_error")) == "refinement"
            )
        return False

    def _pivot_topic_after_scientific_blocker(self, stage, context, completed, by_id,
                                              *, reason, objective, why,
                                              scientific_basis=None,
                                              recovery_mode=None):
        """Refine a topic only from a typed scientific rejection record."""
        context = context if isinstance(context, dict) else {}
        if (stage.get("kind") != "topic_discovery"
                or not self._valid_topic_pivot_scientific_basis(scientific_basis)):
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "reject_topic_pivot_without_scientific_evidence",
                "stage_id": stage.get("id"),
                "reason": str(reason)[:1200],
                "basis_kind": (scientific_basis.get("kind")
                               if isinstance(scientific_basis, dict) else None),
            })
            return False
        recovery = context.get("failure_recovery")
        recovery = recovery if isinstance(recovery, dict) else {}
        superseded = context.get("superseded_scope_failure")
        superseded = superseded if isinstance(superseded, dict) else {}
        stage_record = self.stage_records.get(stage.get("id"), {})
        failure_classes = {
            value for value in (
                context.get("failure_class"), recovery.get("failure_class"),
                superseded.get("failure_class"),
                stage_record.get("failure_class") if isinstance(stage_record, dict) else None,
            ) if isinstance(value, str)
        }
        attempts = stage_record.get("attempts", []) if isinstance(stage_record, dict) else []
        if isinstance(attempts, list):
            failure_classes.update(
                item.get("failure_class") for item in attempts[-8:]
                if isinstance(item, dict) and isinstance(item.get("failure_class"), str)
            )
        technical_classes = {
            "model_contract", "resource_fence", "operational_recovery",
            "context_budget", "evidence_input_unavailable", "experiment_failure",
            "experiment_contract", "stage_contract",
        }
        topic_stage_id = stage.get("id") if stage.get("kind") == "topic_discovery" else None
        if topic_stage_id is None:
            pending = list(stage.get("depends_on", []))
            seen = set()
            while pending:
                candidate_id = pending.pop()
                if candidate_id in seen or candidate_id not in by_id:
                    continue
                seen.add(candidate_id)
                candidate_stage = by_id[candidate_id]
                if candidate_stage.get("kind") == "topic_discovery":
                    topic_stage_id = candidate_id
                    break
                pending.extend(candidate_stage.get("depends_on", []))
        if topic_stage_id is None:
            return False
        same_stage_pivot = stage.get("id") == topic_stage_id
        topic_context = context if same_stage_pivot else self.context.get(topic_stage_id)
        topic_context = deepcopy(topic_context) if isinstance(topic_context, dict) else {
            "kind": "topic_discovery"}
        pivot_cycle = self.continuation_cycles + 1
        failure_recovery = context.get("failure_recovery")
        failure_recovery = failure_recovery if isinstance(failure_recovery, dict) else {}
        failure_dossier_ref = (
            context.get("failure_dossier_ref")
            or failure_recovery.get("dossier_ref")
        )
        repair_directives = context.get("review_directives")
        if not isinstance(repair_directives, list):
            repair_directives = failure_recovery.get("review_directives")
        repair_directives = [
            item.get("text") for item in repair_directives
            if isinstance(item, dict) and isinstance(item.get("text"), str)
        ] if isinstance(repair_directives, list) else []
        evidence_needed = [
            "The failed stage's concrete checks and the parent topic's retained evidence boundary.",
        ]
        if isinstance(failure_dossier_ref, str) and failure_dossier_ref:
            evidence_needed.append("Immutable failure dossier: " + failure_dossier_ref)
        rejected = context.get("rejected_topic_history")
        if isinstance(rejected, list):
            for item in rejected[-4:]:
                if not isinstance(item, dict):
                    continue
                label = item.get("title") or item.get("topic_id") or "rejected candidate"
                question = item.get("research_question")
                rejection = item.get("rejection_reason")
                detail = f"Previously rejected direction: {label}."
                if isinstance(question, str) and question.strip():
                    detail += " Question: " + question.strip()[:500]
                if isinstance(rejection, str) and rejection.strip():
                    detail += " Reason: " + rejection.strip()[:900]
                evidence_needed.append(detail)
        if repair_directives:
            evidence_needed.append(
                "Specific reviewer repairs: " + " | ".join(repair_directives[:8])[:5000])
        if stage.get("kind") in {"survey", "experiment", "topic_discovery"}:
            # Preserve the failed scope for audit, but keep its retry counter
            # and response-contract debt out of the new, parent-anchored task.
            superseded = {}
            for key in (
                    "failure_recovery", "failure_debt", "failure_dossier_ref",
                    "repair_commands", "acceptance_checks", "review_directives",
                    "model_diagnostics", "format_recovery", "format_recovery_attempts",
                    "format_recovery_dispatched", "capability_repair_attempts",
                    "experiment_repair_plan", "experiment_repair_history",
                    "capability_repair_panel"):
                if key in context:
                    superseded[key] = deepcopy(context.pop(key))
            if superseded:
                context["superseded_scope_failure"] = {
                    "source_stage_id": stage.get("id"),
                    "pivot_cycle": pivot_cycle,
                    "reason": reason,
                    "failure_dossier_ref": superseded.get("failure_dossier_ref")
                    or (superseded.get("failure_recovery") or {}).get("dossier_ref"),
                    "failure_class": (superseded.get("failure_recovery") or {}).get(
                        "failure_class") if isinstance(superseded.get("failure_recovery"), dict) else None,
                }
            context["status"] = "research_expansion_required"
            context["review_status"] = "topic_pivot_pending"
            context["error"] = reason
        if same_stage_pivot:
            topic_context = deepcopy(context)
        topic_context["status"] = "research_expansion_required"
        topic_context["topic_pivot"] = {
            "status": "required", "reason": reason,
            "source_stage_id": stage["id"], "cycle": pivot_cycle,
            "scientific_basis": deepcopy(scientific_basis),
        }
        topic_context.pop("generated_capability", None)
        topic_context["research_expansion_requests"] = [{
            "id": f"auto-topic-pivot-{pivot_cycle}",
            "kind": "topic_refinement",
            "owner": "research.intelligence",
            "objective": objective,
            "why": why,
            "success_condition": (
                "A refined question preserves the parent's phenomenon unless independent evidence "
                "directly refutes it or establishes infeasibility, addresses the cited failure findings, "
                "survives maturity and adversarial review, passes the bounded literature gate, and has "
                "an executable primary estimand."
            ),
            "evidence_needed": " ".join(evidence_needed),
            **({"recovery_mode": recovery_mode}
               if isinstance(recovery_mode, str) and recovery_mode else {}),
        }]
        topic_context["research_requests"] = []
        self.context[topic_stage_id] = topic_context
        if not same_stage_pivot:
            context["research_expansion_requests"] = []
            context["research_requests"] = []
            context["pivoted_to_topic"] = topic_stage_id
            self.context[stage["id"]] = context
        if not self._begin_continuation(completed, by_id):
            return False
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "pivot_topic_after_scientific_blocker",
            "stage_id": stage["id"], "topic_stage_id": topic_stage_id,
            "reason": reason, "scientific_basis": deepcopy(scientific_basis),
            "superseded_failure_classes": sorted(failure_classes & technical_classes),
        })
        return True

    def _reconcile_misclassified_model_budget_orders(self):
        """Retire scientific orders whose immutable cause was admission failure."""
        retired = set()
        for request in self.active_research_requests:
            ref = request.get("failure_dossier_ref") if isinstance(request, dict) else None
            if not isinstance(ref, str):
                continue
            manifest, _, dossier = self._read_verified_artifact_json(ref)
            observed = dossier.get("observed_result") or {}
            failure = observed.get("failure") or {}
            if not isinstance(failure.get("budget_admission"), dict):
                continue
            error = ModelCallError.from_failure(observed.get("error") or dossier.get("error", "budget admission"), failure)
            stage_id = dossier.get("stage_id")
            record = self.stage_records.get(stage_id, {})
            owner = next((attempt for attempt in record.get("attempts", [])
                          if attempt.get("failure_dossier_ref") == ref), None)
            if (manifest.get("author") != "command.composer" or owner is None
                    or owner.get("project_dir") != dossier.get("project_dir")
                    or request.get("source_stage_id") != stage_id
                    or request.get("failure_input_sha256") != dossier.get("input_sha256")
                    or getattr(error, "outcome_known", False) is not True):
                raise StateError("model-budget reconciliation has no owned known-outcome failure")
            decision_id = "command/composer/resource-reconciliation/" + request["id"]
            decision = self.store.head(decision_id)
            if decision is None:
                continuation = self.store.head(f"command/composer/continuation/{self.continuation_cycles}")
                self._publish(decision_id, "note", {"action": "supersede_scientific_resource_order",
                    "request_id": request["id"], "failure_dossier_ref": ref, "stage_id": stage_id,
                    "failure_class": "resource_fence", "project_dir": owner["project_dir"],
                    "cycle": self.continuation_cycles}, "command.composer",
                    subjects=[ref, *([continuation["artifact_ref"]] if continuation else [])])
            retired.add(request["id"])
            context = self.context.setdefault(stage_id, {})
            if (context.get("failure_dossier_ref") == ref
                    and context.get("status") in {"research_expansion_required", "blocked"}
                    and record.get("status") in {"blocked", "running", "retrying", "paused"}):
                context.update(status="blocked", failure_class="resource_fence", review_status="resource_capacity_recovery")
            for field in ("research_requests", "research_expansion_requests", "deferred_research_requests"):
                if field in context:
                    context[field] = [item for item in context[field] if item.get("id") != request["id"]]
        if retired:
            self.active_research_requests = [item for item in self.active_research_requests if item.get("id") not in retired]
            self.departments.retire_superseded_work_orders(
                {item["id"] for item in self.active_research_requests}, reason="immutable failure was model-budget admission")
            self.department_activity.append({"cycle": self.continuation_cycles,
                "action": "reconcile_model_budget_work_orders", "request_ids": sorted(retired), "model_calls": 0})
        return sorted(retired)

    def _reopen_blocked_checkpoint(self, completed, by_id):
        """Turn a recoverable stop checkpoint into one fresh work cycle.

        The Composer normally admits recovery in the same process that sees a
        stage failure. A crash, manual restart, or an older runtime can leave
        only the durable ``blocked`` projection behind. Without this bridge,
        the next ``--resume`` merely redispatches or reports the same stale
        blocker. This method is deliberately conservative: environmental
        quota/deadline/cooldown and unknown outcomes are left for their own
        policies, while scientific assignment failures get a new scoped order.
        """
        for stage in self.workflow.get("stages", []):
            stage_id = stage.get("id")
            record = self.stage_records.get(stage_id, {})
            if not isinstance(record, dict) or record.get("status") != "blocked":
                continue
            error_text = str(record.get("error") or "")
            lowered = error_text.casefold()
            if (record.get("failure_class") == "resource_fence"
                    or "modelbudgetexceedederror" in lowered):
                continue
            if any(token in lowered for token in (
                    "hard deadline", "provider cooldown", "result_unknown",
                    "unknown_external_outcome", "process_interrupted")):
                continue
            restored_topic_error = None
            if stage.get("kind") == "topic_discovery":
                attempts = record.get("attempts", [])
                latest = attempts[-1] if isinstance(attempts, list) and attempts else {}
                retry_reason = (latest.get("retry_reason")
                                if isinstance(latest, dict) else None)
                rejected = latest.get("rejected_topic_history")
                if not isinstance(rejected, list) or not rejected:
                    rejected = record.get("rejected_topic_history", [])
                rejected = [
                    deepcopy(item) for item in rejected
                    if isinstance(item, dict)
                    and isinstance(item.get("topic_id"), str)
                and item["topic_id"].strip()
                    and item.get("rejection_type") in {
                        "novelty", "source_challenge", "maturity", "refinement",
                    }
                ] if isinstance(rejected, list) else []
                traces = latest.get("candidate_attempt_trace")
                if not isinstance(traces, list) or not traces:
                    traces = record.get("candidate_attempt_trace", [])
                semantic_rejections = []
                if isinstance(traces, list):
                    for trace in traces:
                        if not isinstance(trace, dict):
                            continue
                        rejection_type = trace.get("rejection_type")
                        selected = trace.get("selected_topic")
                        if (rejection_type not in {
                                "novelty", "source_challenge", "maturity", "refinement"}
                                or not isinstance(selected, dict)
                                or not isinstance(selected.get("id"), str)):
                            continue
                        semantic_rejections.append({
                            "topic_id": selected["id"],
                            "title": selected.get("title"),
                            "domain": selected.get("domain"),
                            "research_question": selected.get("research_question"),
                            "research_form": selected.get("research_form"),
                            "evidence_mode": selected.get("evidence_mode"),
                            "comparison_type": selected.get("comparison_type"),
                            "rejection_type": rejection_type,
                            "rejection_reason": str(trace.get("error") or error_text)[:2048],
                        })
                contract_failures = [
                    trace for trace in traces if isinstance(trace, dict)
                    and trace.get("status") in {
                        "rejected", "incomplete", "maturity_review_error",
                        "source_challenge_error", "refinement_rejected",
                    }
                    and any(marker in str(trace.get("error") or "").casefold()
                            for marker in (
                                "invalid shape", "keys do not match", "requires exactly",
                                "invalid json", "response contract", "missing_fields",
                                "unexpected=", "missing=",
                            ))
                ] if isinstance(traces, list) else []
                # Checkpoints written before typed retry_reason was introduced
                # still contain a bounded-intake marker and durable scientific
                # rejection or contract-failure evidence. Reconstruct only
                # from that pair; a generic quota/provider failure must never
                # become a topic pivot.
                legacy_local_topic_exhaustion = any(marker in lowered for marker in (
                    "topic discovery bounded intake exhausted",
                    "topic discovery quota exhausted",
                ))
                if (retry_reason == "scientific_candidate_rejected"
                        and not rejected and not semantic_rejections):
                    # Older checkpoints mislabeled malformed feasibility plans
                    # as scientific rejection. Do not turn that stale label
                    # into permission to choose a different research question.
                    retry_reason = None
                if (retry_reason not in {
                        "scientific_candidate_rejected", "intake_contract_failure"}
                        and legacy_local_topic_exhaustion
                        and (rejected or semantic_rejections)):
                    retry_reason = "scientific_candidate_rejected"
                elif (retry_reason not in {
                        "scientific_candidate_rejected", "intake_contract_failure"}
                      and legacy_local_topic_exhaustion and contract_failures):
                    retry_reason = "intake_contract_failure"
                if not rejected and semantic_rejections:
                    rejected = semantic_rejections[-24:]
                if retry_reason in {"scientific_candidate_rejected", "intake_contract_failure"}:
                    # The runner records candidate-level exhaustion as a
                    # QuotaExceededError because its local intake lease ended.
                    # Reconstruct that typed local failure from the durable
                    # retry ledger; parsing prose here used to strand resume
                    # behind a generic quota/forward-first fence.
                    restored_topic_error = QuotaExceededError(
                        error_text or "topic discovery bounded intake exhausted",
                        dimension="topic_attempts", limit=0, observed=0,
                        usage=deepcopy(
                            latest.get("topic_usage") or latest.get("usage")
                            or record.get("usage") or {}),
                        diagnostics=[{"kind": "composer_topic_budget"}],
                    )
                    restored_topic_error.topic_budget_scope = "intake"
                    restored_topic_error.retryable_topic_intake = True
                    restored_topic_error.topic_retry_reason = retry_reason
                    if isinstance(rejected, list) and rejected:
                        restored_topic_error.rejected_topic_history = deepcopy(rejected)
                        self._record_topic_rejection_history(rejected)
            if "quotaexceedederror" in lowered and not (
                    restored_topic_error is not None
                    or stage.get("kind") == "topic_discovery"
                    and "topic discovery quota exhausted" in lowered):
                continue
            if restored_topic_error is not None:
                error = restored_topic_error
            elif stage.get("kind") == "topic_discovery" and (
                    "topic discovery quota exhausted" in lowered):
                error = QuotaExceededError(
                    error_text or "topic discovery quota exhausted",
                    dimension="model_calls", limit=0, observed=0,
                    usage=deepcopy(
                        latest.get("topic_usage") or latest.get("usage")
                        or record.get("usage") or {}),
                    diagnostics=[{"kind": "composer_topic_budget"}],
                )
                error.topic_budget_scope = "restored_checkpoint"
                error.usage_is_snapshot = True
                if rejected:
                    error.rejected_topic_history = deepcopy(rejected)
                    self._record_topic_rejection_history(rejected)
            else:
                error = ModelWorkBlocked(error_text or "recoverable stage assignment blocker")
            if self._admit_scientific_blocker_recovery(
                    stage, error, completed, by_id):
                record["status"] = "retrying"
                record["recovery_admitted"] = True
                return True
        return False

    def _reconcile_restored_topic_refinement_failure(self, completed, by_id):
        """Reclassify a saved parent-identity violation as a scientific repair.

        Older checkpoints treated a syntactically valid but off-parent salvage
        proposal as a generic model-contract error, then restarted a full topic
        intake under a local-budget override.  Recover only when the persisted
        validation text is one of the typed refinement failures and a parent
        topic is still available; preserve the failed attempt and issue a new
        evidence-led refinement instead of replaying its format repair.
        """
        stage = next((item for item in self.workflow.get("stages", [])
                      if item.get("kind") == "topic_discovery"), None)
        if not isinstance(stage, dict):
            return False
        context = self.context.get(stage["id"])
        if (not isinstance(context, dict)
                or not isinstance(context.get("topic"), dict)
                or context.get("format_recovery") is not True):
            return False
        failure = context.get("failure_recovery")
        failure = failure if isinstance(failure, dict) else {}
        diagnostic_sources = (
            context.get("model_diagnostics"), failure.get("model_diagnostics"))
        validation_error = None
        for diagnostics in diagnostic_sources:
            if not isinstance(diagnostics, dict):
                continue
            repair = diagnostics.get("topic_response_repair")
            if isinstance(repair, dict):
                candidate = repair.get("previous_validation_error")
                if isinstance(candidate, str) and candidate.strip():
                    validation_error = candidate.strip()
                    break
        if (_topic_validation_rejection_type(validation_error) != "refinement"
                or not isinstance(context.get("topic_pivot"), dict)
                or context["topic_pivot"].get("status") != "required"):
            return False
        rejected = context.get("rejected_topic_history")
        rejected = [deepcopy(item) for item in rejected
                    if isinstance(item, dict)] if isinstance(rejected, list) else []
        traces = context.get("candidate_attempt_trace")
        if isinstance(traces, list):
            for trace in traces[-4:]:
                selected = trace.get("selected_topic") if isinstance(trace, dict) else None
                if (not isinstance(selected, dict)
                        or not isinstance(selected.get("id"), str)):
                    continue
                rejected.append({
                    "topic_id": selected["id"], "title": selected.get("title"),
                    "domain": selected.get("domain"),
                    "research_question": selected.get("research_question"),
                    "rejection_type": "refinement",
                    "rejection_reason": str(trace.get("error") or validation_error)[:2048],
                })
        context["rejected_topic_history"] = rejected[-24:]
        context["candidate_attempt_trace"] = deepcopy(traces[-24:]) if isinstance(traces, list) else []
        context["error"] = validation_error[:4096]
        self.context[stage["id"]] = context
        if rejected:
            self._record_topic_rejection_history(rejected)
        parent_topic = context.get("topic")
        parent_topic_id = (
            parent_topic.get("id") if isinstance(parent_topic, dict) else None)
        admitted = self._pivot_topic_after_scientific_blocker(
            stage, context, completed, by_id,
            reason=(
                "the prior selected topic violated the required parent-preserving scientific refinement: "
                + validation_error[:900]
            ),
            objective=(
                "Continue from the retained parent phenomenon and the existing scholarly evidence. "
                "Refine the failed formulation by changing a supported mechanism, observable, "
                "comparator, evidence boundary, or claim scope; keep the parent's phenomenon and "
                "exclude the rejected formulation. Do not restart unrelated topic discovery."
            ),
            why=(
                "The previous candidate was rejected because it left the parent phenomenon, not because "
                "the response JSON was malformed. Repair the research formulation and carry forward the "
                "same evidence lineage."
            ),
            scientific_basis={
                "kind": "parent_refinement_rejection",
                "parent_topic_id": parent_topic_id,
                "rejection_type": "refinement",
                "validation_error": validation_error,
            },
        )
        if admitted:
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "resume_parent_preserving_topic_refinement",
                "stage_id": stage["id"],
                "rejected_topic_ids": [item.get("topic_id") for item in rejected],
                "validation_error": validation_error[:900],
            })
        return admitted

    @staticmethod
    def _is_survey_evidence_contract_blocker(stage, error):
        """Identify a persisted survey assignment that cannot be repaired in place."""
        return (
            isinstance(stage, dict)
            and stage.get("kind") == "survey"
            and isinstance(error, (ModelWorkBlocked, str))
            and getattr(error, "failure_class", None) != "model_contract"
            and any(marker in str(error).casefold() for marker in (
                "did not satisfy its evidence contract",
                "gap-assessment",
                "unknown or duplicate required check",
            ))
        )

    def _admit_scoped_survey_repair(self, stage, context, completed, by_id, error):
        """Resume only the failed survey milestone from its durable workspace."""
        if not isinstance(stage, dict) or stage.get("kind") != "survey":
            return False
        stage_id = stage["id"]
        prior_context = self.context.get(stage_id)
        prior_context = deepcopy(prior_context) if isinstance(prior_context, dict) else {}
        repair_attempts = prior_context.get("survey_repair_attempts", 0)
        if type(repair_attempts) is not int or repair_attempts >= 1:
            return False

        record = self.stage_records.get(stage_id, {})
        attempts = record.get("attempts", []) if isinstance(record, dict) else []
        candidates = []
        if isinstance(context, dict):
            candidates.append(context.get("project_dir"))
        if isinstance(record, dict):
            candidates.append(record.get("project_dir"))
        candidates.extend(
            attempt.get("project_dir")
            for attempt in reversed(attempts)
            if isinstance(attempt, dict)
        )
        candidates.append(stage.get("project_dir"))

        topic_identity = self._current_topic_identity()
        selected = None
        selected_run = None
        selected_scope = None
        seen = set()
        for candidate in candidates:
            if not isinstance(candidate, str):
                continue
            project = Path(candidate).resolve()
            if str(project) in seen:
                continue
            seen.add(str(project))
            if not (project / "state" / "control.sqlite").is_file():
                continue
            if self._durable_stage_config(project) is None:
                continue
            run_path = project / "output" / "run.json"
            if not run_path.is_file():
                continue
            try:
                prior_run = json.loads(run_path.read_text())
            except (OSError, TypeError, ValueError):
                continue
            if not isinstance(prior_run, dict) or prior_run.get("assessment_current") is True:
                continue
            attempt_identity = next((item for item in reversed(attempts)
                                     if isinstance(item, dict)
                                     and isinstance(item.get("project_dir"), str)
                                     and Path(item["project_dir"]).resolve() == project), {})
            if isinstance(topic_identity, dict):
                attempt_topic_id = attempt_identity.get("topic_id")
                attempt_topic_cycle = attempt_identity.get("topic_cycle")
                if (isinstance(attempt_topic_id, str)
                        and attempt_topic_id != topic_identity["topic_id"]):
                    continue
                if (type(attempt_topic_cycle) is int
                        and attempt_topic_cycle != topic_identity["topic_cycle"]):
                    continue
                checkpoint_topic_id = self._survey_checkpoint_topic_id(prior_run)
                if (isinstance(checkpoint_topic_id, str)
                        and checkpoint_topic_id != topic_identity["topic_id"]):
                    continue
            if (prior_run.get("survey_current") is True
                    and isinstance(prior_run.get("survey_ref"), str)):
                scope = "gap_assessment"
            elif self._survey_review_repair_checkpoint(project):
                scope = "integrated_review"
            else:
                continue
            selected, selected_run, selected_scope = project, prior_run, scope
            break
        if selected is None:
            return False

        request_id = f"survey-repair-{stage_id}-{self.continuation_cycles + 1}"
        if selected_scope == "gap_assessment":
            review_status = "gap_assessment_resume"
            objective = (
                "Complete only the pending gap assessment from the exact accepted literature map, "
                "nomination, counter-search, and evidence catalog. Repair the failed check envelope "
                "without repeating retrieval, remapping, or changing the admitted research question. "
                "If the evidence remains weak, record insufficient_evidence and pass that limitation "
                "to an adjacent, explicitly exploratory experiment."
            )
            success_condition = (
                "The retained evidence receives a current, evidence-bound gap decision; an honest "
                "insufficient_evidence result is a valid decision and does not discard the topic."
            )
        else:
            review_status = "survey_integrity_repair"
            objective = (
                "Repair only the aggregate acceptance review for the retained survey map. Reuse its "
                "catalog, map entries, exact source captures, and pinned per-work reviews; do not "
                "repeat literature acquisition. Keep bounded coverage gaps explicit, and block only "
                "a concrete unsupported included claim, included-work identity conflict, or accounting error."
            )
            success_condition = (
                "The same literature map is accepted with explicit coverage limitations if its "
                "included claims remain source-supported, or the exact offending claim is identified "
                "for a local repair without changing the parent phenomenon."
            )
        request = {
            "id": request_id,
            "kind": "literature_expansion",
            "owner": "research.intelligence",
            "objective": objective,
            "why": (
                "The current survey stopped at a review/assessment boundary, not because the research "
                "phenomenon was refuted. Resume the retained evidence frontier and address this exact "
                "failure: " + str(error)[:1200]
            ),
            "success_condition": success_condition,
            "evidence_needed": (
                "Retained survey " + str(selected_run.get("survey_ref"))
                + "; exact prior run artifact and reviewer diagnostics; the current question and "
                "topic lineage; the missing or non-passing required checks."
            ),
            "target_stage_id": stage_id,
            "repair_strategy": selected_scope,
        }
        context = deepcopy(context) if isinstance(context, dict) else {}
        context.update({
            "stage_id": stage_id,
            "kind": "survey",
            "status": "research_expansion_required",
            "error": str(error)[:4096],
            "review_status": review_status,
            "resume_scope": selected_scope,
            "project_dir": str(selected),
            "survey_ref": selected_run.get("survey_ref"),
            "survey_current": selected_run.get("survey_current") is True,
            "assessment_ref": selected_run.get("assessment_ref"),
            "assessment_current": False,
            "survey_repair_attempts": repair_attempts + 1,
            "research_requests": [request],
            "research_expansion_requests": [],
        })
        if isinstance(topic_identity, dict):
            context["topic_id"] = topic_identity["topic_id"]
            context["topic_cycle"] = topic_identity["topic_cycle"]
            context["topic_lineage"] = deepcopy(topic_identity)
        self.context[stage_id] = context
        if not self._begin_continuation(completed, by_id):
            self.context[stage_id] = prior_context
            return False
        record = deepcopy(record) if isinstance(record, dict) else {"kind": "survey"}
        record.update({
            "status": "retrying",
            "recovery_admitted": True,
            "review_status": review_status,
            "resume_scope": selected_scope,
            "project_dir": str(selected),
        })
        self.stage_records[stage_id] = record
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "admit_scoped_survey_repair",
            "stage_id": stage_id,
            "project_dir": str(selected),
            "resume_scope": selected_scope,
            "survey_ref": selected_run.get("survey_ref"),
            "next_action": (
                "resume_gap_assessment_only" if selected_scope == "gap_assessment"
                else "resume_integrated_review_without_retrieval"
            ),
        })
        return True

    def _resume_stale_survey_contract_repair(self, completed, by_id):
        """Resume an interrupted survey contract failure at its exact evidence frontier.

        A process can stop after the Composer has admitted a continuation but
        before that continuation reaches the stage failure handler.  In that
        window the stage record is ``running`` even though its durable context
        already contains the prior evidence-contract blocker. Reconcile that
        durable context before scheduling so the same accepted survey or
        aggregate-review workspace is resumed without a topic reset.
        """
        if any(
                isinstance(item, dict)
                and (self._is_topic_pivot_request(item)
                     or item.get("kind") == "literature_expansion")
                and (item.get("target_stage_id") == "survey"
                     or item.get("repair_strategy") in {"gap_assessment", "integrated_review"})
                for item in self.active_research_requests):
            return False
        for stage in self.workflow.get("stages", []):
            stage_id = stage.get("id")
            context = self.context.get(stage_id)
            record = self.stage_records.get(stage_id, {})
            if not isinstance(context, dict) or not isinstance(record, dict):
                continue
            if context.get("status") != "research_expansion_required":
                continue
            if stage_id not in self.continuation_pending_stage_ids:
                continue
            if not self._is_survey_evidence_contract_blocker(stage, context.get("error")):
                continue
            record["status"] = "retrying"
            record["error"] = str(context.get("error"))[:4096]
            self.stage_records[stage_id] = record
            return self._admit_scoped_survey_repair(
                stage, deepcopy(context), completed, by_id, context.get("error")
            )
        return False

    def _restore_retained_survey_frontier_after_failed_topic_pivot(self, completed, by_id):
        """Restore a still-actionable survey when its replacement-topic intake failed.

        A topic pivot is justified only after the retained evidence is no longer
        useful. If a gap-assessment contract failure already triggered a pivot,
        but the replacement topic intake then failed before admitting a new
        topic, resume the exact accepted survey frontier instead of paying for
        another topic proposal or repeating literature retrieval.
        """
        topic_stage = next((stage for stage in self.workflow.get("stages", [])
                            if stage.get("kind") == "topic_discovery"), None)
        survey_stage = next((stage for stage in self.workflow.get("stages", [])
                             if stage.get("kind") == "survey"), None)
        if not isinstance(topic_stage, dict) or not isinstance(survey_stage, dict):
            return False

        topic_id_stage = topic_stage["id"]
        survey_id = survey_stage["id"]
        topic_context = self.context.get(topic_id_stage)
        topic_context = topic_context if isinstance(topic_context, dict) else {}
        pivot = topic_context.get("topic_pivot")
        topic_record = self.stage_records.get(topic_id_stage)
        topic_record = topic_record if isinstance(topic_record, dict) else {}
        topic_attempts = topic_record.get("attempts", [])
        topic_attempts = topic_attempts if isinstance(topic_attempts, list) else []
        latest_topic_attempt = next((item for item in reversed(topic_attempts)
                                     if isinstance(item, dict)), {})
        if not (
            topic_record.get("status") == "blocked"
            and latest_topic_attempt.get("failure_class") in {
                "model_contract", "topic_refinement_contract",
            }
            and isinstance(pivot, dict)
            and pivot.get("status") == "required"
            and pivot.get("source_stage_id") == survey_id
        ):
            return False

        pivot_requests = [item for item in self.active_research_requests
                          if isinstance(item, dict)
                          and self._is_topic_pivot_request(item)
                          and item.get("source_stage_id") == topic_id_stage]
        if not pivot_requests:
            return False
        pivot_request = pivot_requests[-1]
        topic_id = pivot_request.get("topic_id")
        topic_cycle = pivot_request.get("topic_cycle")
        if not isinstance(topic_id, str) or type(topic_cycle) is not int:
            return False

        # Re-admission must be grounded in the exact previously successful
        # topic artifact, not just a matching title in a stale survey folder.
        admitted_topic = None
        admitted_topic_attempt = None
        for attempt in reversed(topic_attempts[:-1]):
            if (not isinstance(attempt, dict)
                    or attempt.get("state") not in {"succeeded", "completed"}
                    or not isinstance(attempt.get("project_dir"), str)):
                continue
            root = Path(attempt["project_dir"])
            candidates = (root / "topic-discovery.json",
                          root / "output" / "topic-discovery.json")
            for path in candidates:
                if not path.is_file():
                    continue
                try:
                    payload = json.loads(path.read_text())
                except (OSError, TypeError, ValueError):
                    continue
                candidate_topic = payload.get("topic") if isinstance(payload, dict) else None
                evolution = payload.get("topic_evolution") if isinstance(payload, dict) else None
                if (not isinstance(candidate_topic, dict)
                        or candidate_topic.get("id") != topic_id
                        or not isinstance(evolution, dict)
                        or evolution.get("cycle") != topic_cycle
                        or payload.get("admission_state") not in {
                            "provisional_for_survey", "admitted"}):
                    continue
                admitted_topic = payload
                admitted_topic_attempt = attempt
                break
            if admitted_topic is not None:
                break
        if admitted_topic is None:
            return False

        completed_survey = self._completed_survey_frontier_for_topic(
            survey_id, topic_id, topic_cycle)
        if completed_survey is not None:
            # A quota-triggered pivot can be persisted after a successful
            # exploratory survey and a substantive downstream review. Restore
            # both durable decisions and resume the review's evidence-producing
            # Methods work order; never rerun the catalogue or repeat the
            # already completed experiment just to get past the stale pivot.
            argument_stage = next((stage for stage in self.workflow.get("stages", [])
                                   if stage.get("kind") == "argument"), None)
            if not isinstance(argument_stage, dict):
                return False
            argument_record = self.stage_records.get(argument_stage["id"])
            argument_record = argument_record if isinstance(argument_record, dict) else {}
            argument_attempts = argument_record.get("attempts", [])
            argument_attempts = argument_attempts if isinstance(argument_attempts, list) else []
            repair_requests = None
            source_argument_attempt = None
            for attempt in reversed(argument_attempts):
                if (not isinstance(attempt, dict)
                        or attempt.get("state") != "failed"
                        or attempt.get("failure_class") != "scientific_review"
                        or attempt.get("topic_id") != topic_id
                        or attempt.get("topic_cycle") != topic_cycle
                        or not isinstance(attempt.get("failure_dossier_ref"), str)):
                    continue
                try:
                    manifest = self.store.get(attempt["failure_dossier_ref"])
                    dossier = json.loads(self.store.read_body(manifest["body_hash"]))
                except (NotFoundError, KeyError, OSError, TypeError, ValueError):
                    continue
                if (not isinstance(dossier, dict)
                        or dossier.get("stage_id") != argument_stage["id"]
                        or dossier.get("attempt_number") != attempt.get("attempt_number")
                        or dossier.get("failure_class") != "scientific_review"
                        or not isinstance(dossier.get("review_directives"), list)):
                    continue
                dossier["artifact_ref"] = attempt["failure_dossier_ref"]
                methods_request = self._argument_experiment_repair_request(
                    argument_stage, dossier)
                if methods_request is None:
                    continue
                argument_request = build_repair_request(
                    dossier, stage_id=argument_stage["id"])
                argument_request["failure_dossier_ref"] = attempt["failure_dossier_ref"]
                repair_requests = [argument_request, methods_request]
                source_argument_attempt = attempt
                break
            if repair_requests is None:
                return False

            topic_context = deepcopy(topic_context)
            topic_context.update({
                "kind": "topic_discovery",
                "status": "completed",
                "topic": deepcopy(admitted_topic["topic"]),
                "topic_evolution": deepcopy(admitted_topic["topic_evolution"]),
                "topic_id": topic_id,
                "topic_cycle": topic_cycle,
                "restored_frontier": {
                    "source_attempt": admitted_topic_attempt.get("attempt_number"),
                    "failed_pivot_attempt": latest_topic_attempt.get("attempt_number"),
                    "reason": "retain the admitted topic after a quota-only survey pivot",
                },
                "research_requests": [],
                "research_expansion_requests": [],
            })
            for key in (
                    "topic_pivot", "deferred_research_requests", "failure_recovery",
                    "failure_dossier_ref", "format_recovery", "format_recovery_attempts",
                    "format_recovery_dispatched", "repair_commands", "acceptance_checks",
                    "model_diagnostics", "error"):
                topic_context.pop(key, None)
            self.context[topic_id_stage] = topic_context
            topic_record = deepcopy(topic_record)
            topic_record.update({
                "status": "completed",
                "topic_id": topic_id,
                "topic_cycle": topic_cycle,
                "restored_frontier": deepcopy(topic_context["restored_frontier"]),
            })
            topic_record.pop("error", None)
            self.stage_records[topic_id_stage] = topic_record
            completed.add(topic_id_stage)

            survey_attempt, survey_project, survey_run, survey_result = completed_survey
            survey_context = self.context.get(survey_id)
            survey_context = deepcopy(survey_context) if isinstance(survey_context, dict) else {}
            survey_context.update({
                "stage_id": survey_id,
                "kind": "survey",
                "status": "completed",
                "review_status": "exploratory_pilot_retained",
                "topic_id": topic_id,
                "topic_cycle": topic_cycle,
                "topic_lineage": {"topic_id": topic_id, "topic_cycle": topic_cycle},
                "project_dir": str(survey_project),
                "survey_ref": survey_run["survey_ref"],
                "assessment_ref": survey_run["assessment_ref"],
                "survey_current": True,
                "assessment_current": True,
                "gap_state": survey_result.get("gap_state"),
                "topic_admission": survey_result["topic_admission"],
                "research_requests": [],
                "research_expansion_requests": [],
                "restored_frontier": {
                    "source_attempt": survey_attempt.get("attempt_number"),
                    "survey_ref": survey_run["survey_ref"],
                    "assessment_ref": survey_run["assessment_ref"],
                    "reason": "reuse the current survey and preserve insufficient evidence as a limitation",
                },
            })
            for key in ("topic_pivot_cycle", "superseded_topic_id", "lineage_state",
                        "lineage_transition_ref", "error"):
                survey_context.pop(key, None)
            self.context[survey_id] = survey_context
            survey_record = deepcopy(self.stage_records.get(survey_id, {}))
            survey_record.update({
                "kind": "survey",
                "status": "completed",
                "topic_id": topic_id,
                "topic_cycle": topic_cycle,
                "project_dir": str(survey_project),
                "survey_ref": survey_run["survey_ref"],
                "assessment_ref": survey_run["assessment_ref"],
                "gap_state": survey_result.get("gap_state"),
                "results_status": "completed",
                "restored_frontier": deepcopy(survey_context["restored_frontier"]),
            })
            survey_record.pop("error", None)
            self.stage_records[survey_id] = survey_record
            self.continuation_pending_stage_ids.discard(survey_id)
            completed.add(survey_id)

            self.active_research_requests = repair_requests
            targets = self._continuation_targets(repair_requests, by_id)
            for target_id in targets:
                target_context = self.context.get(target_id)
                target_context = deepcopy(target_context) if isinstance(target_context, dict) else {}
                target_context.update({
                    "stage_id": target_id,
                    "kind": by_id[target_id].get("kind"),
                    "status": "pending",
                    "topic_lineage": {"topic_id": topic_id, "topic_cycle": topic_cycle},
                    "research_requests": [],
                    "research_expansion_requests": [],
                })
                for key in ("superseded_topic_id", "lineage_state",
                            "lineage_transition_ref", "topic_pivot_cycle", "error"):
                    target_context.pop(key, None)
                self.context[target_id] = target_context
                record = self.stage_records.get(target_id)
                if isinstance(record, dict):
                    record = deepcopy(record)
                    record.update({"status": "retrying", "topic_id": topic_id,
                                   "topic_cycle": topic_cycle})
                    self.stage_records[target_id] = record

            # Target preparation clears stale request projections. Restore the
            # durable source-stage requests afterward so the next continuation
            # can be reconstructed from checkpoint context, not only from the
            # transient active-request cache.
            argument_context = self.context[argument_stage["id"]]
            argument_context["research_requests"] = deepcopy(repair_requests)

            for blocker in self.blockers:
                if (isinstance(blocker, dict)
                        and blocker.get("stage_id") == survey_id
                        and blocker.get("stop_reason") == "stage_quota_exhausted"):
                    blocker.update({
                        "recovery": "superseded_by_current_stage_state",
                        "superseded_stage_status": "completed",
                        "superseded_by_survey_ref": survey_run["survey_ref"],
                    })
                elif (isinstance(blocker, dict)
                      and blocker.get("stage_id") == topic_id_stage
                      and blocker.get("attempt_number") == latest_topic_attempt.get("attempt_number")):
                    blocker["disposition"] = "forwarded_with_findings"
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "restore_completed_survey_and_scientific_review_after_quota_pivot",
                "topic_id": topic_id,
                "topic_cycle": topic_cycle,
                "topic_attempt": admitted_topic_attempt.get("attempt_number"),
                "failed_pivot_attempt": latest_topic_attempt.get("attempt_number"),
                "survey_attempt": survey_attempt.get("attempt_number"),
                "survey_ref": survey_run["survey_ref"],
                "assessment_ref": survey_run["assessment_ref"],
                "argument_attempt": source_argument_attempt.get("attempt_number"),
                "argument_dossier_ref": source_argument_attempt.get("failure_dossier_ref"),
                "work_order_ids": [item["id"] for item in repair_requests],
                "model_calls": 0,
                "next_action": "run_methods_calibration_then_rebuild_and_review_the_argument",
            })
            return True

        survey_record = self.stage_records.get(survey_id)
        survey_record = survey_record if isinstance(survey_record, dict) else {}
        survey_attempts = survey_record.get("attempts", [])
        survey_attempts = survey_attempts if isinstance(survey_attempts, list) else []
        retained_project = None
        retained_checkpoint = None
        retained_attempt = None
        for attempt in reversed(survey_attempts):
            if (not isinstance(attempt, dict)
                    or attempt.get("state") != "failed"
                    or attempt.get("failure_class") != "model_contract"
                    or attempt.get("topic_id") != topic_id
                    or attempt.get("topic_cycle") != topic_cycle
                    or not isinstance(attempt.get("project_dir"), str)):
                continue
            project = Path(attempt["project_dir"])
            checkpoint = self._survey_checkpoint(project)
            if (checkpoint is None
                    or not self._survey_checkpoint_matches_topic(
                        checkpoint, {"topic_id": topic_id, "topic_cycle": topic_cycle})
                    or self._durable_stage_config(project) is None):
                continue
            retained_project, retained_checkpoint, retained_attempt = (
                project.resolve(), checkpoint, attempt)
            break
        if retained_project is None:
            return False

        topic_context = deepcopy(topic_context)
        topic_context.update({
            "kind": "topic_discovery",
            "status": "completed",
            "topic": deepcopy(admitted_topic["topic"]),
            "topic_evolution": deepcopy(admitted_topic["topic_evolution"]),
            "topic_id": topic_id,
            "topic_cycle": topic_cycle,
        })
        for key in ("topic_pivot", "research_requests", "research_expansion_requests",
                    "deferred_research_requests", "failure_recovery", "failure_dossier_ref",
                    "format_recovery", "format_recovery_attempts",
                    "format_recovery_dispatched", "repair_commands",
                    "acceptance_checks", "model_diagnostics", "error"):
            topic_context.pop(key, None)
        topic_context["restored_frontier"] = {
            "source_attempt": admitted_topic_attempt.get("attempt_number"),
            "failed_pivot_attempt": latest_topic_attempt.get("attempt_number"),
            "reason": "replacement topic intake failed before a new topic was admitted",
        }
        self.context[topic_id_stage] = topic_context
        topic_record = deepcopy(topic_record)
        topic_record.update({
            "status": "completed",
            "topic_id": topic_id,
            "topic_cycle": topic_cycle,
            "restored_frontier": deepcopy(topic_context["restored_frontier"]),
        })
        topic_record.pop("error", None)
        for key in ("superseded_topic_id", "lineage_state", "lineage_transition_ref",
                    "topic_pivot_cycle"):
            topic_record.pop(key, None)
        self.stage_records[topic_id_stage] = topic_record
        completed.add(topic_id_stage)

        repair_request = {
            "id": f"gap-assessment-recovery-{topic_id}-{topic_cycle}",
            "kind": "literature_expansion",
            "owner": "research.intelligence",
            "objective": (
                "Complete only the pending gap assessment for the accepted survey. Reuse its current "
                "source catalogue, literature map, and counter-search; do not repeat retrieval or work review."
            ),
            "why": (
                "The survey and evidence map are already accepted. The previous assessment response "
                "failed its output contract, while the attempted replacement-topic intake did not admit "
                "a new direction."
            ),
            "success_condition": (
                "A current gap-assessment artifact passes evidence validation against the retained "
                "survey without repeating literature acquisition."
            ),
            "evidence_needed": (
                "The accepted survey reference, exact current literature map and evidence catalogue, "
                "required assessment checks, and the retained assessment failure diagnostics."
            ),
        }
        survey_context = self.context.get(survey_id)
        survey_context = deepcopy(survey_context) if isinstance(survey_context, dict) else {}
        survey_context.update({
            "stage_id": survey_id,
            "kind": "survey",
            "status": "research_expansion_required",
            "review_status": "gap_assessment_resume",
            "error": str(retained_attempt.get("error") or
                          "accepted survey is missing a current gap assessment")[:4096],
            "project_dir": str(retained_project),
            "topic_id": topic_id,
            "topic_cycle": topic_cycle,
            "topic_lineage": {"topic_id": topic_id, "topic_cycle": topic_cycle},
            "survey_ref": retained_checkpoint["survey_ref"],
            "survey_current": True,
            "assessment_ref": None,
            "assessment_current": False,
            "resume_scope": "gap_assessment",
            "research_requests": [repair_request],
            "research_expansion_requests": [],
        })
        survey_context.pop("superseded_topic_id", None)
        survey_context.pop("lineage_state", None)
        self.context[survey_id] = survey_context
        survey_record = deepcopy(survey_record)
        survey_record.update({
            "status": "retrying",
            "topic_id": topic_id,
            "topic_cycle": topic_cycle,
            "project_dir": str(retained_project),
            "restored_frontier": {
                "topic_attempt": admitted_topic_attempt.get("attempt_number"),
                "survey_attempt": retained_attempt.get("attempt_number"),
                "survey_ref": retained_checkpoint["survey_ref"],
                "resume_scope": "gap_assessment",
            },
        })
        survey_record.pop("error", None)
        for key in ("superseded_topic_id", "lineage_state", "lineage_transition_ref",
                    "topic_pivot_cycle"):
            survey_record.pop(key, None)
        self.stage_records[survey_id] = survey_record

        targets = self._continuation_targets([repair_request], by_id)
        for stage_id in targets - {survey_id}:
            context = self.context.get(stage_id)
            context = deepcopy(context) if isinstance(context, dict) else {}
            context.update({
                "stage_id": stage_id,
                "kind": by_id[stage_id].get("kind"),
                "status": "pending",
                "topic_lineage": {"topic_id": topic_id, "topic_cycle": topic_cycle},
                "research_requests": [],
                "research_expansion_requests": [],
            })
            for key in ("superseded_topic_id", "lineage_state", "lineage_transition_ref",
                        "topic_pivot_cycle", "error"):
                context.pop(key, None)
            self.context[stage_id] = context
            record = self.stage_records.get(stage_id)
            if isinstance(record, dict):
                record = deepcopy(record)
                record.update({"status": "retrying", "topic_id": topic_id,
                               "topic_cycle": topic_cycle})
                for key in ("superseded_topic_id", "lineage_state",
                            "lineage_transition_ref", "topic_pivot_cycle"):
                    record.pop(key, None)
                self.stage_records[stage_id] = record

        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "restore_retained_survey_frontier_after_failed_topic_pivot",
            "stage_id": survey_id,
            "topic_id": topic_id,
            "topic_cycle": topic_cycle,
            "topic_attempt": admitted_topic_attempt.get("attempt_number"),
            "failed_pivot_attempt": latest_topic_attempt.get("attempt_number"),
            "survey_attempt": retained_attempt.get("attempt_number"),
            "survey_ref": retained_checkpoint["survey_ref"],
            "next_action": "resume_gap_assessment_only_from_the_accepted_survey_checkpoint",
        })
        return True

    @staticmethod
    def _survey_references_are_durable(project_dir, references):
        """Check that a survey checkpoint's current references exist locally."""
        if not isinstance(project_dir, (str, Path)):
            return False
        refs = {item for item in references
                if isinstance(item, str) and item.startswith("artifact:")}
        if len(refs) != len(references):
            return False
        database = Path(project_dir).resolve() / "state" / "control.sqlite"
        if not database.is_file():
            return False
        connection = None
        try:
            connection = sqlite3.connect(
                database.as_uri() + "?mode=ro", uri=True, timeout=2.0)
            rows = connection.execute(
                "SELECT artifact_ref FROM artifacts WHERE artifact_ref IN (%s)" %
                ",".join("?" for _ in refs), tuple(sorted(refs)),
            ).fetchall()
            return {row[0] for row in rows} == refs
        except (sqlite3.Error, OSError, ValueError):
            return False
        finally:
            if connection is not None:
                connection.close()

    @staticmethod
    def _read_json_object(path):
        if not isinstance(path, (str, Path)):
            return None
        try:
            value = json.loads(Path(path).read_text())
        except (OSError, TypeError, ValueError):
            return None
        return value if isinstance(value, dict) else None

    def _restore_unjustified_refinement_frontier(self, completed, by_id):
        """Restore verified topic/survey artifacts and route their failed experiment.

        A cross-phenomenon checkpoint can be rejected without discarding the
        prior evidence frontier. Re-admit only an exact completed topic and
        survey pair, then turn the matching immutable experiment dossier into
        a Methods repair order. No model call or research artifact is edited by
        this migration.
        """
        reconciliation = self._restored_topic_lineage_reconciliation
        topic_stage = next((stage for stage in self.workflow.get("stages", [])
                            if stage.get("kind") == "topic_discovery"), None)
        survey_stage = next((stage for stage in self.workflow.get("stages", [])
                             if stage.get("kind") == "survey"), None)
        experiment_stage = next((stage for stage in self.workflow.get("stages", [])
                                 if stage.get("kind") == "experiment"), None)
        if not all(isinstance(stage, dict)
                   for stage in (topic_stage, survey_stage, experiment_stage)):
            return False

        topic_id = topic_stage["id"]
        survey_id = survey_stage["id"]
        experiment_id = experiment_stage["id"]
        topic_context = self.context.get(topic_id)
        topic_context = topic_context if isinstance(topic_context, dict) else {}
        survey_context = self.context.get(survey_id)
        survey_context = survey_context if isinstance(survey_context, dict) else {}
        experiment_context = self.context.get(experiment_id)
        experiment_context = experiment_context if isinstance(experiment_context, dict) else {}
        if (not isinstance(reconciliation, dict)
                or reconciliation.get("action")
                != "reject_unjustified_topic_refinement_checkpoint"):
            topic_frontier = topic_context.get("restored_frontier")
            topic_value = topic_context.get("topic")
            experiment_record_for_reentry = self.stage_records.get(experiment_id)
            experiment_record_for_reentry = (
                experiment_record_for_reentry
                if isinstance(experiment_record_for_reentry, dict) else {})
            latest_valid_dossier_ref = None
            experiment_attempts_for_reentry = experiment_record_for_reentry.get("attempts", [])
            experiment_attempts_for_reentry = (
                experiment_attempts_for_reentry
                if isinstance(experiment_attempts_for_reentry, list) else [])
            for attempt in reversed(experiment_attempts_for_reentry):
                if (not isinstance(attempt, dict)
                        or attempt.get("state") != "failed"
                        or attempt.get("topic_id") != topic_context.get("topic_id")
                        or attempt.get("topic_cycle") != topic_context.get("topic_cycle")
                        or not isinstance(attempt.get("failure_dossier_ref"), str)):
                    continue
                recorded_error = attempt.get("error")
                if (isinstance(recorded_error, str)
                        and any(marker in recorded_error
                                for marker in EXPERIMENT_SURVEY_ADMISSION_ERRORS)):
                    continue
                latest_valid_dossier_ref = attempt["failure_dossier_ref"]
                break
            current_dossier_refs = {
                ref for ref in (
                    experiment_context.get("failure_dossier_ref"),
                    experiment_record_for_reentry.get("failure_dossier_ref"),
                    *(request.get("failure_dossier_ref")
                      for request in self.active_research_requests
                      if isinstance(request, dict)
                      and (request.get("target_stage_id") == experiment_id
                           or request.get("target_stage_kind") == "experiment")),
                ) if isinstance(ref, str)
            }
            stale_failure_pointer = (
                isinstance(latest_valid_dossier_ref, str)
                and any(ref != latest_valid_dossier_ref for ref in current_dossier_refs)
            )
            admission_error = (
                isinstance(experiment_context.get("error"), str)
                and any(marker in experiment_context["error"]
                        for marker in EXPERIMENT_SURVEY_ADMISSION_ERRORS)
            )
            if (not isinstance(topic_frontier, dict)
                    or topic_frontier.get("reason") != (
                        "a newer checkpoint changed phenomenon without evidence authorizing a pivot")
                    or not isinstance(topic_value, dict)
                    or not isinstance(topic_value.get("id"), str)
                    or survey_context.get("topic_id") != topic_value["id"]
                    or survey_context.get("topic_cycle") != topic_context.get("topic_cycle")
                    or survey_context.get("survey_current") is not True
                    or survey_context.get("assessment_current") is not True
                    or not isinstance(survey_context.get("survey_ref"), str)
                    or not isinstance(survey_context.get("assessment_ref"), str)
                    or experiment_context.get("topic_id") != topic_value["id"]
                    or experiment_context.get("topic_cycle") != topic_context.get("topic_cycle")
                    or not (admission_error or stale_failure_pointer)):
                return False
            reconciliation = {
                "action": "reject_unjustified_topic_refinement_checkpoint",
                "retained_topic_id": topic_value["id"],
                "rejected_topic_id": topic_frontier.get("rejected_checkpoint_topic_id"),
            }
            self._restored_topic_lineage_reconciliation = reconciliation
        topic = topic_context.get("topic")
        evolution = topic_context.get("topic_evolution")
        topic_record = self.stage_records.get(topic_id)
        survey_record = self.stage_records.get(survey_id)
        experiment_record = self.stage_records.get(experiment_id)
        topic_record = topic_record if isinstance(topic_record, dict) else {}
        survey_record = survey_record if isinstance(survey_record, dict) else {}
        experiment_record = experiment_record if isinstance(experiment_record, dict) else {}
        topic_attempts = topic_record.get("attempts", [])
        survey_attempts = survey_record.get("attempts", [])
        experiment_attempts = experiment_record.get("attempts", [])
        topic_attempts = topic_attempts if isinstance(topic_attempts, list) else []
        survey_attempts = survey_attempts if isinstance(survey_attempts, list) else []
        experiment_attempts = experiment_attempts if isinstance(experiment_attempts, list) else []
        topic_cycle = evolution.get("cycle") if isinstance(evolution, dict) else None
        if (not isinstance(topic, dict) or not isinstance(topic.get("id"), str)
                or topic.get("id") != reconciliation.get("retained_topic_id")
                or type(topic_cycle) is not int):
            return False

        accepted_topic = None
        accepted_topic_attempt = None
        for attempt in reversed(topic_attempts):
            if (not isinstance(attempt, dict)
                    or attempt.get("state") not in {"succeeded", "completed"}
                    or attempt.get("attempt_number") != topic_context.get("attempt_number")
                    or not isinstance(attempt.get("project_dir"), str)
                    or attempt.get("project_dir") != topic_context.get("project_dir")):
                continue
            root = Path(attempt["project_dir"])
            payload = (self._read_json_object(root / "topic-discovery.json")
                       or self._read_json_object(root / "output" / "topic-discovery.json"))
            candidate = payload.get("topic") if isinstance(payload, dict) else None
            candidate_evolution = payload.get("topic_evolution") if isinstance(payload, dict) else None
            if (not isinstance(candidate, dict)
                    or candidate.get("id") != topic["id"]
                    or not isinstance(candidate_evolution, dict)
                    or candidate_evolution.get("cycle") != topic_cycle
                    or payload.get("status") not in {"completed", "accepted"}
                    or payload.get("admission_state") not in {
                        "provisional_for_survey", "admitted"}):
                continue
            accepted_topic = payload
            accepted_topic_attempt = attempt
            break
        if accepted_topic is None:
            return False

        retained_survey = None
        retained_survey_attempt = None
        retained_survey_score = None
        for attempt in reversed(survey_attempts):
            if (not isinstance(attempt, dict)
                    or attempt.get("state") not in {"succeeded", "completed"}
                    or attempt.get("topic_id") != topic["id"]
                    or attempt.get("topic_cycle") != topic_cycle
                    or not isinstance(attempt.get("project_dir"), str)):
                continue
            project = Path(attempt["project_dir"]).resolve()
            report = self._read_json_object(project / "output" / "run.json")
            assessment = self._read_json_object(
                project / "output" / "gap-assessment.json")
            if (not isinstance(report, dict)
                    or report.get("status") not in {"completed", "accepted"}
                    or report.get("survey_current") is not True
                    or report.get("assessment_current") is not True
                    or not isinstance(report.get("survey_ref"), str)
                    or not isinstance(report.get("assessment_ref"), str)
                    or not isinstance(report.get("gap_state"), str)
                    or not isinstance(assessment, dict)
                    or assessment.get("state") != report.get("gap_state")
                    or assessment.get("survey_ref") != report.get("survey_ref")
                    or not self._survey_references_are_durable(
                        project, [report["survey_ref"], report["assessment_ref"]])
                    or not self._survey_attempt_was_accepted(survey_id, attempt, report)
                    or not self._survey_references_are_current(project, report)):
                continue
            nomination = report.get("nomination")
            if (isinstance(nomination, dict)
                    and nomination.get("id") not in {None, f"topic-{topic['id']}"}):
                continue
            coverage = report.get("coverage")
            coverage = coverage if isinstance(coverage, dict) else {}
            verified_full_texts = coverage.get("verified_full_texts")
            unique_works = coverage.get("unique_works")
            score = (
                verified_full_texts if type(verified_full_texts) is int else -1,
                unique_works if type(unique_works) is int else -1,
            )
            if retained_survey_score is None or score > retained_survey_score:
                retained_survey = {
                    "project_dir": str(project), **report, "assessment": assessment,
                }
                retained_survey_attempt = attempt
                retained_survey_score = score
        if retained_survey is None:
            return False

        prior_failure = (experiment_context.get("superseded_scope_failure")
                         if isinstance(experiment_context.get("superseded_scope_failure"), dict)
                         else {})
        preferred_dossier_ref = prior_failure.get("failure_dossier_ref")
        valid_dossiers = {}
        latest_valid_dossier_ref = None
        gate_failure_attempts = []
        for attempt in reversed(experiment_attempts):
            if (not isinstance(attempt, dict)
                    or attempt.get("state") != "failed"
                    or attempt.get("topic_id") != topic["id"]
                    or attempt.get("topic_cycle") != topic_cycle
                    or not isinstance(attempt.get("failure_dossier_ref"), str)):
                continue
            dossier_ref = attempt["failure_dossier_ref"]
            try:
                manifest = self.store.get(dossier_ref)
                dossier = json.loads(self.store.read_body(manifest["body_hash"]))
            except (NotFoundError, KeyError, OSError, TypeError, ValueError):
                continue
            if (not isinstance(dossier, dict)
                    or dossier.get("stage_id") != experiment_id
                    or dossier.get("attempt_number") != attempt.get("attempt_number")
                    or dossier.get("failure_class") != "experiment_failure"):
                continue
            if dossier.get("error") in EXPERIMENT_SURVEY_ADMISSION_ERRORS:
                gate_failure_attempts.append(attempt)
                continue
            if (not isinstance(dossier.get("input_sha256"), str)
                    or not isinstance(dossier.get("error"), str)
                    or not isinstance(dossier.get("repair_commands"), list)
                    or not dossier["repair_commands"]
                    or not isinstance(dossier.get("acceptance_checks"), list)
                    or not isinstance(dossier.get("review_directives"), list)):
                continue
            valid_dossiers[dossier_ref] = (attempt, dossier)
            if latest_valid_dossier_ref is None:
                latest_valid_dossier_ref = dossier_ref
        dossier_ref = latest_valid_dossier_ref
        if not isinstance(dossier_ref, str):
            return False
        failure_attempt, dossier = valid_dossiers[dossier_ref]
        related_dossiers = set(valid_dossiers)
        repair_counts = [
            item.get("repair_attempts")
            for item in self.department_activity
            if isinstance(item, dict)
            and item.get("action") == "schedule_pre_execution_capability_repair"
            and item.get("stage_id") == experiment_id
            and item.get("failure_dossier_ref") in related_dossiers
            and type(item.get("repair_attempts")) is int
            and item["repair_attempts"] >= 0
        ]
        if not repair_counts:
            return False
        prior_repair_count = max(repair_counts)

        gap_state = retained_survey["gap_state"]
        if gap_state not in {"eligible_for_experiment", "insufficient_evidence"}:
            return False
        if (gap_state == "insufficient_evidence"
                and not self._allows_provisional_progress()):
            return False
        retained_evidence_expansions = [
            deepcopy(item) for item in experiment_context.get(
                "survey_evidence_expansion_history", [])
            if isinstance(item, dict)
            and item.get("topic_id") == topic["id"]
            and item.get("topic_cycle") == topic_cycle
        ]

        archived_topic_state = {
            key: deepcopy(topic_context[key]) for key in (
                "topic_pivot", "failure_recovery", "failure_dossier_ref",
                "format_recovery", "format_recovery_attempts",
                "format_recovery_dispatched", "research_requests",
                "research_expansion_requests",
            ) if key in topic_context
        }
        topic_context.update({
            "stage_id": topic_id,
            "kind": "topic_discovery",
            "status": "completed",
            "topic": deepcopy(accepted_topic["topic"]),
            "topic_evolution": deepcopy(accepted_topic["topic_evolution"]),
            "admission_state": accepted_topic["admission_state"],
            "project_dir": accepted_topic_attempt["project_dir"],
            "topic_id": topic["id"],
            "topic_cycle": topic_cycle,
            "restored_frontier": {
                "source_attempt": accepted_topic_attempt.get("attempt_number"),
                "rejected_checkpoint_topic_id": reconciliation.get("rejected_topic_id"),
                "reason": "a newer checkpoint changed phenomenon without evidence authorizing a pivot",
            },
        })
        topic_context["deferred_topic_state"] = archived_topic_state
        for key in (
                "topic_pivot", "failure_recovery", "failure_dossier_ref",
                "format_recovery", "format_recovery_attempts",
                "format_recovery_dispatched", "repair_commands", "acceptance_checks",
                "review_directives", "model_diagnostics", "error", "research_requests",
                "research_expansion_requests", "deferred_research_requests"):
            topic_context.pop(key, None)
        self.context[topic_id] = topic_context

        topic_record.update({
            "kind": "topic_discovery", "status": "completed",
            "topic_id": topic["id"], "topic_cycle": topic_cycle,
            "project_dir": accepted_topic_attempt["project_dir"],
            "admission_state": accepted_topic["admission_state"],
        })
        topic_record.pop("error", None)
        for key in ("superseded_topic_id", "lineage_state", "lineage_transition_ref",
                    "topic_pivot_cycle", "attempt_id", "task_id"):
            topic_record.pop(key, None)
        self.stage_records[topic_id] = topic_record
        completed.add(topic_id)

        assessment = retained_survey["assessment"]
        rationale = assessment.get("rationale")
        survey_context = {
            "stage_id": survey_id,
            "kind": "survey",
            "status": "completed",
            "project_dir": retained_survey["project_dir"],
            "topic_id": topic["id"],
            "topic_cycle": topic_cycle,
            "topic_lineage": {"topic_id": topic["id"], "topic_cycle": topic_cycle},
            "survey_ref": retained_survey["survey_ref"],
            "assessment_ref": retained_survey["assessment_ref"],
            "survey_current": True,
            "assessment_current": True,
            "gap_state": gap_state,
            "nomination": deepcopy(retained_survey.get("nomination")),
            "coverage_summary": {
                "unique_works": (retained_survey.get("coverage", {}).get("unique_works")
                                 if isinstance(retained_survey.get("coverage"), dict) else None),
                "verified_full_texts": (
                    retained_survey.get("coverage", {}).get("verified_full_texts")
                    if isinstance(retained_survey.get("coverage"), dict) else None),
            },
            "scientific_limitations": {
                "novelty_claim_authorized": gap_state not in {
                    "insufficient_evidence", "unknown", "not_assessed"},
                "exploratory_only": gap_state in {
                    "insufficient_evidence", "unknown", "not_assessed"},
                "gap_state": gap_state,
                "rationale": rationale[:2400] if isinstance(rationale, str) else None,
                "assessment_checks": [
                    {"outcome": item.get("outcome")}
                    for item in assessment.get("checks", [])[:12]
                    if isinstance(item, dict)
                ] if isinstance(assessment.get("checks"), list) else [],
            },
            "restored_frontier": {
                "source_attempt": retained_survey_attempt.get("attempt_number"),
                "survey_ref": retained_survey["survey_ref"],
                "assessment_ref": retained_survey["assessment_ref"],
                "reason": "the exact current assessment was completed before the invalid topic branch",
            },
            **{key: deepcopy(retained_survey[key]) for key in
               ("work_orders", "follow_up_ref", "follow_up_result") if key in retained_survey},
        }
        survey_context = self._gate_free_topic_survey(
            survey_context, stage=survey_stage)
        if survey_context.get("topic_admission") not in {
                "provisional_supported_for_experiment", "exploratory_pilot"}:
            return False
        self.context[survey_id] = survey_context
        survey_record.update({
            "kind": "survey", "status": "completed",
            "topic_id": topic["id"], "topic_cycle": topic_cycle,
            "project_dir": retained_survey["project_dir"],
            "survey_ref": retained_survey["survey_ref"],
            "assessment_ref": retained_survey["assessment_ref"],
            "gap_state": gap_state,
        })
        survey_record.pop("error", None)
        for key in ("superseded_topic_id", "lineage_state", "lineage_transition_ref",
                    "topic_pivot_cycle", "attempt_id", "task_id"):
            survey_record.pop(key, None)
        self.stage_records[survey_id] = survey_record
        completed.add(survey_id)

        experiment_context = {
            "stage_id": experiment_id,
            "kind": "experiment",
            "status": "research_expansion_required",
            "review_status": "scientific_assignment_blocked",
            "topic_id": topic["id"],
            "topic_cycle": topic_cycle,
            "topic_lineage": {"topic_id": topic["id"], "topic_cycle": topic_cycle},
            "project_dir": failure_attempt.get("project_dir"),
            "results_status": "not_executed",
            "error": dossier["error"],
            "failure_dossier_ref": dossier_ref,
            "failure_observed_result": deepcopy(dossier.get("observed_result", {})),
            "repair_commands": deepcopy(dossier["repair_commands"]),
            "acceptance_checks": deepcopy(dossier["acceptance_checks"]),
            "review_directives": deepcopy(dossier["review_directives"]),
            "model_diagnostics": deepcopy(dossier.get("model_diagnostics", {})),
            "failure_recovery": {
                "schema_version": "failure-recovery-ledger-1",
                "failure_class": dossier["failure_class"],
                "dossier_ref": dossier_ref,
                "input_sha256": dossier["input_sha256"],
                "repair_commands": deepcopy(dossier["repair_commands"]),
                "acceptance_checks": deepcopy(dossier["acceptance_checks"]),
                "review_directives": deepcopy(dossier["review_directives"]),
                "model_diagnostics": deepcopy(dossier.get("model_diagnostics", {})),
                "recovery_mode": "repair_then_rerun",
                "requires_capability_repair": True,
                "attempt_number": failure_attempt.get("attempt_number"),
            },
            "failure_debt": {
                "stage_id": experiment_id,
                "kind": "experiment",
                "failure_class": "experiment_capability_repair",
                "error": dossier["error"][:4096],
                "attempts": failure_attempt.get("attempt_number"),
                "next_action": "Methods must diagnose, patch, execute, and independently recalculate the experiment",
                "release_blocking": True,
                "failure_dossier_ref": dossier_ref,
            },
            "capability_repair_attempts": prior_repair_count,
            **({"superseded_failure_pointer": {
                "reference": preferred_dossier_ref,
                "reason": "a later valid failure dossier exists for the retained topic lineage",
            }} if (isinstance(preferred_dossier_ref, str)
                   and preferred_dossier_ref != dossier_ref) else {}),
            "quarantined_admission_gate_retries": [
                {
                    "attempt_number": attempt.get("attempt_number"),
                    "cycle": attempt.get("cycle"),
                    "failure_dossier_ref": attempt.get("failure_dossier_ref"),
                    "actual_usage": deepcopy(attempt.get("usage", {})),
                    "disposition": "deterministic_survey_admission_error_not_experiment_evidence",
                }
                for attempt in reversed(gate_failure_attempts)
            ],
            "repair_counter_recovery": {
                "value": prior_repair_count,
                "basis": "the persisted Composer repair orders for the retained topic lineage",
                "failure_dossier_refs": sorted(related_dossiers),
            },
            "research_requests": [],
            "research_expansion_requests": [],
            "survey_evidence_expansion_history": retained_evidence_expansions[-8:],
        }
        self.context[experiment_id] = experiment_context
        experiment_record.update({
            "kind": "experiment", "status": "retrying",
            "topic_id": topic["id"], "topic_cycle": topic_cycle,
            "failure_dossier_ref": dossier_ref,
            "restored_failure_attempt": failure_attempt.get("attempt_number"),
        })
        self.stage_records[experiment_id] = experiment_record

        quarantined_gate_refs = {
            attempt.get("failure_dossier_ref") for attempt in gate_failure_attempts
            if isinstance(attempt.get("failure_dossier_ref"), str)
        }
        if quarantined_gate_refs:
            self.active_research_requests = [
                request for request in self.active_research_requests
                if not (isinstance(request, dict)
                        and request.get("failure_dossier_ref") in quarantined_gate_refs)
            ]
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "quarantine_deterministic_experiment_admission_failures",
                "stage_id": experiment_id,
                "topic_id": topic["id"],
                "topic_cycle": topic_cycle,
                "attempt_numbers": [
                    attempt.get("attempt_number") for attempt in gate_failure_attempts
                ],
                "actual_model_calls_preserved_not_refunded": sum(
                    (attempt.get("usage", {}).get("model_calls", 0)
                     if isinstance(attempt.get("usage"), dict) else 0)
                    for attempt in gate_failure_attempts
                ),
                "next_action": "retry the original same-topic experiment failure, not the admission error",
            })
        request = self._autonomous_experiment_repair_request(
            experiment_stage, experiment_context, dossier["error"], prior_repair_count)
        if request is None:
            return False
        for stage_id in self._continuation_targets([request], by_id) - {experiment_id}:
            stage = by_id[stage_id]
            self.context[stage_id] = {
                "stage_id": stage_id,
                "kind": stage.get("kind"),
                "status": "pending",
                "topic_lineage": {"topic_id": topic["id"], "topic_cycle": topic_cycle},
                "research_requests": [],
                "research_expansion_requests": [],
            }
            record = self.stage_records.get(stage_id)
            if isinstance(record, dict):
                record.update({"status": "retrying", "topic_id": topic["id"],
                               "topic_cycle": topic_cycle})
                for key in ("superseded_topic_id", "lineage_state",
                            "lineage_transition_ref", "topic_pivot_cycle"):
                    record.pop(key, None)
                self.stage_records[stage_id] = record

        # Discard the abandoned branch's pending set before admitting the
        # restored same-topic continuation.
        self.continuation_pending_stage_ids.clear()
        self.reopened_stage_ids.clear()
        admitted = self._begin_continuation(completed, by_id)
        if not admitted:
            return False
        survey_evidence_first = request.get("kind") == "literature_expansion"
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": (
                "restore_verified_frontier_and_acquire_survey_evidence"
                if survey_evidence_first else
                "restore_verified_frontier_and_repair_experiment"
            ),
            "topic_id": topic["id"],
            "topic_cycle": topic_cycle,
            "topic_attempt": accepted_topic_attempt.get("attempt_number"),
            "survey_attempt": retained_survey_attempt.get("attempt_number"),
            "survey_ref": retained_survey["survey_ref"],
            "assessment_ref": retained_survey["assessment_ref"],
            "gap_state": gap_state,
            "failure_dossier_ref": dossier_ref,
            "request_id": request["id"],
            "next_action": (
                "Research resolves the same-topic evidence gap before Methods work; novelty remains exploratory"
                if survey_evidence_first else
                "Methods repairs the same-topic experiment in a fresh attempt; novelty remains exploratory"
            ),
        })
        self._checkpoint(
            "resume:restore_verified_frontier_and_acquire_survey_evidence"
            if survey_evidence_first else
            "resume:restore_verified_frontier_and_methods_repair",
            force=True,
        )
        return True

    def _resume_exhausted_pre_execution_experiment(self, completed, by_id):
        """Repair a legacy unexecuted experiment before redispatching it.

        Older checkpoints did not persist the capability-repair counter and
        could therefore resume directly into the same generated program or
        pivot away after a fixed retry count. Reopen the durable Methods repair
        order at startup instead; only the mission-wide resource fences bound
        this code-repair loop.
        """
        if any(
                self._is_topic_pivot_request(item)
                for item in self.active_research_requests
        ):
            return False
        for stage in self.workflow.get("stages", []):
            if stage.get("kind") != "experiment":
                continue
            stage_id = stage.get("id")
            context = self.context.get(stage_id)
            record = self.stage_records.get(stage_id, {})
            if not isinstance(context, dict) or not isinstance(record, dict):
                continue
            attempts = record.get("attempts", [])
            latest_attempt = next((item for item in reversed(attempts)
                                   if isinstance(item, dict)), None) if isinstance(attempts, list) else None
            if (stage_id in self.continuation_pending_stage_ids
                    and record.get("status") == "retrying"
                    and isinstance(latest_attempt, dict)
                    and latest_attempt.get("state") == "unknown"
                    and latest_attempt.get("cycle") == self.continuation_cycles
                    and latest_attempt.get("attempt_id") == record.get("last_attempt_id")):
                # An interrupted aggregate has no new scientific verdict.
                # Resume its admitted producer frontier before deriving any
                # new repair order from the previous completed result.
                continue
            if context.get("pivoted_to_topic"):
                current_topic = self._current_topic_identity()
                context_topic = {
                    "topic_id": context.get("topic_id"),
                    "topic_cycle": context.get("topic_cycle"),
                }
                record_topic = {
                    "topic_id": record.get("topic_id"),
                    "topic_cycle": record.get("topic_cycle"),
                }
                if (isinstance(current_topic, dict)
                        and context_topic == current_topic
                        and record_topic == current_topic):
                    # The marker survives old lineage transitions in some
                    # checkpoints even after a stage attempt has completed
                    # under the newly admitted topic.  In that state it is
                    # historical metadata, not permission to discard the
                    # current topic's repair dossier.
                    context.pop("pivoted_to_topic", None)
                    repair_request = next((item for item in self.active_research_requests
                                           if self._is_experiment_repair_request(item)
                                           and item.get("target_stage_id", stage_id) == stage_id
                                           and item.get("topic_id") == current_topic["topic_id"]
                                           and item.get("topic_cycle") == current_topic["topic_cycle"]),
                                          None)
                    restored_fields = []
                    if repair_request is not None:
                        for key in (
                                "failure_dossier_ref", "failure_input_sha256",
                                "failure_scope",
                                "failure_observed_result", "experiment_repair_plan",
                                "repair_commands", "acceptance_checks", "review_directives",
                                "model_diagnostics", "capability_repair_attempts",
                                "capability_repair_panel"):
                            if key not in context and key in repair_request:
                                context[key] = deepcopy(repair_request[key])
                                restored_fields.append(key)
                        repair_plan = repair_request.get("experiment_repair_plan")
                        repair_plan = repair_plan if isinstance(repair_plan, dict) else {}
                        repair_lineage = repair_plan.get("lineage")
                        repair_lineage = repair_lineage if isinstance(repair_lineage, dict) else {}
                        repair_input = repair_request.get("failure_input_sha256")
                        repair_dossier = repair_request.get("failure_dossier_ref")
                        repair_mode = repair_request.get("recovery_mode")
                        if (repair_plan.get("schema_version") == "experiment-repair-plan-1"
                                and repair_lineage.get("prior_gate") == "experiment_failure"
                                and repair_request.get("topic_id") == current_topic["topic_id"]
                                and repair_request.get("topic_cycle") == current_topic["topic_cycle"]
                                and repair_mode == "experiment_diagnose_patch_execute_recalculate"
                                and isinstance(repair_dossier, str)
                                and repair_dossier.startswith("artifact:")
                                and isinstance(repair_input, str)
                                and len(repair_input) == 64
                                and all(char in "0123456789abcdef" for char in repair_input)):
                            recovery = context.get("failure_recovery")
                            recovery = recovery if isinstance(recovery, dict) else {}
                            recovery.update({
                                "failure_class": "experiment_failure",
                                "recovery_mode": repair_mode,
                                "requires_capability_repair": True,
                                "dossier_ref": repair_dossier,
                                "input_sha256": repair_input,
                            })
                            context["failure_recovery"] = recovery
                            context["failure_class"] = "experiment_failure"
                            context["failure_dossier_ref"] = repair_dossier
                            context["failure_input_sha256"] = repair_input
                            restored_fields.extend([
                                "failure_recovery.requires_capability_repair",
                                "failure_class",
                            ])
                        if context.get("error") == (
                                "legacy topic pivot lineage retired before new topic execution"):
                            context.pop("error", None)
                        context["status"] = "research_expansion_required"
                        if (isinstance(context.get("failure_recovery"), dict)
                                and context["failure_recovery"].get(
                                    "requires_capability_repair") is True):
                            context["review_status"] = "scientific_assignment_blocked"
                        else:
                            context["review_status"] = "same_topic_repair_pending"
                    self.context[stage_id] = context
                    self.department_activity.append({
                        "cycle": self.continuation_cycles,
                        "action": "reconcile_stale_topic_pivot_marker",
                        "stage_id": stage_id,
                        "topic_id": current_topic["topic_id"],
                        "topic_cycle": current_topic["topic_cycle"],
                        "request_id": repair_request.get("id")
                        if repair_request is not None else None,
                        "restored_fields": restored_fields,
                        "reason": (
                            "the stage record matches the current topic; preserve its active repair order"
                        ),
                    })
                else:
                    # Migrate checkpoints written before topic pivots retired
                    # the old lineage. The pivot marker is durable, but older
                    # packets may still carry a superseded failure gate.
                    stale_keys = (
                        "failure_recovery", "failure_debt", "failure_dossier_ref",
                        "repair_commands", "acceptance_checks", "review_directives",
                        "model_diagnostics", "format_recovery", "format_recovery_attempts",
                        "format_recovery_dispatched",
                        "capability_repair_attempts", "experiment_repair_plan",
                        "experiment_repair_history", "capability_repair_panel",
                    )
                    if any(key in context for key in stale_keys):
                        for key in stale_keys:
                            context.pop(key, None)
                        context["status"] = "research_expansion_required"
                        context["review_status"] = "topic_pivot_pending"
                        context["error"] = "legacy topic pivot lineage retired before new topic execution"
                        self.context[stage_id] = context
                        self.department_activity.append({
                            "cycle": self.continuation_cycles,
                            "action": "migrate_topic_pivot_lineage",
                            "stage_id": stage_id,
                            "next_action": "execute the new topic lineage without the superseded repair gate",
                        })
                    continue
            if not self._is_pre_execution_capability_failure(
                    stage, context, record.get("error")):
                continue
            if self._has_pending_admitted_recovery(stage, by_id):
                continue
            if any(
                    self._is_experiment_repair_request(item)
                    and item.get("target_stage_id", stage_id) == stage_id
                    for item in self.active_research_requests
                    if isinstance(item, dict)):
                continue
            repair_attempts = self._pre_execution_repair_count(
                stage, error=record.get("error"))
            prior = deepcopy(context)
            error = record.get("error") or context.get("error") or (
                "restored experiment capability has no admitted result")
            request = self._autonomous_experiment_repair_request(
                stage, context, error, repair_attempts)
            if request is None or not self._begin_continuation(completed, by_id):
                self.context[stage_id] = prior
                return False
            record["status"] = "retrying"
            record["recovery_admitted"] = True
            self.stage_records[stage_id] = record
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "resume_topic_preserving_experiment_repair",
                "stage_id": stage_id,
                "repair_attempts": repair_attempts,
                "request_id": request["id"],
                "failure_dossier_ref": request.get("failure_dossier_ref"),
                "next_action": "diagnose, patch, execute, and independently recalculate the admitted experiment",
            })
            return True
        return False

    def _admit_scientific_blocker_recovery(self, stage, error, completed, by_id,
                                           specialist_verifier=None):
        """Turn a bounded scientific failure into a fresh scoped work order.

        ``ModelWorkBlocked`` means the current assignment exhausted its own
        validation/repair contract. A Composer-owned topic envelope is the
        same kind of bounded scientific failure: preserve that cycle, change
        the research direction, and reopen only the affected dependency
        closure. Provider/model quotas, deadlines, and process interruptions
        remain environmental fences and never enter this path.
        """
        if getattr(error, "failure_class", None) == "context_budget":
            # The smallest role-specific packet already failed local
            # admission. Reopening the same scientific scope cannot add
            # evidence and would only replay the deterministic failure.
            return False
        prior_context = self.context.get(stage["id"])
        prior_context = deepcopy(prior_context) if isinstance(prior_context, dict) else {}
        failure_recovery = prior_context.get("failure_recovery")
        failure_recovery = failure_recovery if isinstance(failure_recovery, dict) else {}
        if (getattr(error, "failure_class", None) == "evidence_input_unavailable"
                or failure_recovery.get("failure_class") == "evidence_input_unavailable"):
            prior_context.update({
                "status": "research_expansion_required",
                "review_status": "evidence_input_unavailable",
                "release_blocking": True,
                "error": str(error)[:4096],
                "results_status": "not_executed",
            })
            survey_stage = next((candidate for candidate in self.workflow.get("stages", [])
                                 if candidate.get("kind") == "survey"), None)
            dossier = {
                "stage_kind": stage.get("kind"),
                "failure_class": "evidence_input_unavailable",
                "error": str(error),
                "input_sha256": (failure_recovery.get("input_sha256")
                                 or prior_context.get("failure_input_sha256", "")),
                "repair_commands": deepcopy(
                    prior_context.get("repair_commands")
                    or failure_recovery.get("repair_commands") or []),
                "acceptance_checks": deepcopy(
                    prior_context.get("acceptance_checks")
                    or failure_recovery.get("acceptance_checks") or []),
                "review_directives": [],
            }
            request = build_repair_request(
                dossier, stage_id=stage["id"],
                target_stage_id=survey_stage.get("id") if survey_stage else None,
                target_stage_kind="survey",
            )
            request.update({
                "id": f"source-data-recovery-{stage['id']}-{self.continuation_cycles + 1}",
                "recovery_mode": "acquire_evidence_same_topic",
                "failure_dossier_ref": (
                    prior_context.get("failure_dossier_ref")
                    or failure_recovery.get("dossier_ref")),
                "why": (
                    "The experiment has no controller-verified source rows. That describes the current "
                    "data-acquisition state, not evidence against the admitted research question. "
                    "Acquire and verify the declared source data before making any scientific feasibility "
                    "decision."
                ),
                "evidence_needed": (
                    "The unchanged admitted topic and its evidence plan; source repositories and search "
                    "queries; immutable source artifacts; and a controller-verified row manifest. Do not "
                    "substitute synthetic rows or change the topic because an input is missing."
                ),
            })
            topic_identity = self._current_topic_identity()
            if topic_identity is not None:
                request["topic_id"] = topic_identity["topic_id"]
                request["topic_cycle"] = topic_identity["topic_cycle"]
            prior_context["research_requests"] = [request]
            prior_context["research_expansion_requests"] = []
            self.context[stage["id"]] = prior_context
            admitted = self._begin_continuation(completed, by_id)
            if admitted:
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "acquire_source_evidence_without_topic_change",
                    "stage_id": stage["id"],
                    "target_stage_id": request.get("target_stage_id"),
                    "topic_id": request.get("topic_id"),
                    "request_id": request["id"],
                    "failure_dossier_ref": request.get("failure_dossier_ref"),
                })
            return admitted
        topic_retry_reason = getattr(error, "topic_retry_reason", None)
        legacy_topic_contract_failure = (
            stage.get("kind") == "topic_discovery"
            and self._is_topic_intake_retry(error, stage)
            and topic_retry_reason == "intake_contract_failure"
        )
        survey_assignment_blocker = self._is_survey_evidence_contract_blocker(stage, error)
        if (stage.get("kind") == "topic_discovery"
                and self._is_topic_intake_retry(error, stage)
                and topic_retry_reason == "scientific_candidate_rejected"):
            rejected = getattr(error, "rejected_topic_history", None)
            rejected = [deepcopy(item) for item in rejected
                        if isinstance(item, dict)] if isinstance(rejected, list) else []
            traces = getattr(error, "candidate_attempt_trace", None)
            traces = [deepcopy(item) for item in traces
                      if isinstance(item, dict)] if isinstance(traces, list) else []
            if not rejected:
                rejected = [
                    {
                        "topic_id": trace["selected_topic"].get("id"),
                        "title": trace["selected_topic"].get("title"),
                        "domain": trace["selected_topic"].get("domain"),
                        "research_question": trace["selected_topic"].get("research_question"),
                        "rejection_type": trace.get("rejection_type"),
                        "rejection_reason": str(trace.get("error") or error)[:2048],
                    }
                    for trace in traces
                    if isinstance(trace.get("selected_topic"), dict)
                    and isinstance(trace["selected_topic"].get("id"), str)
                ][-8:]
            prior_context.update({
                "status": "research_expansion_required",
                "review_status": "topic_pivot_pending",
                "error": str(error)[:4096],
                "candidate_attempt_trace": traces[-24:],
                "rejected_topic_history": rejected[-24:],
            })
            self.context[stage["id"]] = prior_context
            if rejected:
                self._record_topic_rejection_history(rejected)
            trace_reasons = {}
            for trace in traces:
                selected = trace.get("selected_topic")
                if (isinstance(selected, dict)
                        and isinstance(selected.get("id"), str)
                        and isinstance(trace.get("error"), str)):
                    trace_reasons[selected["id"]] = trace["error"]
            rejected_candidates = []
            for item in rejected:
                candidate_id = item.get("topic_id")
                rejection_reason = (
                    item.get("rejection_reason") or trace_reasons.get(candidate_id))
                if (isinstance(candidate_id, str)
                        and isinstance(rejection_reason, str)
                        and rejection_reason.strip()):
                    rejected_candidates.append({
                        "topic_id": candidate_id,
                        "rejection_type": item.get("rejection_type"),
                        "rejection_reason": rejection_reason[:2048],
                    })
            admitted = self._pivot_topic_after_scientific_blocker(
                stage, prior_context, completed, by_id,
                reason=(
                    "topic intake rejected its selected direction under the recorded novelty or "
                    "parent-preserving refinement constraint"
                ),
                objective=(
                    "Continue from the retained parent phenomenon and supplied literature. Do not "
                    "restart an unrelated candidate portfolio or repeat any rejected direction. "
                    "Use the concrete rejection and evidence to make an adjacent change in mechanism, "
                    "observable, comparator, evidence boundary, or claim scope; preserve the parent's "
                    "phenomenon unless the sources directly refute it or establish infeasibility."
                ),
                why=(
                    "The selected candidate failed a source-backed novelty/refinement check. That rejects "
                    "this formulation, not the retained scientific phenomenon; the next order must use the "
                    "recorded rejection and continue the same evidence lineage."
                ),
                scientific_basis={
                    "kind": "topic_candidate_rejection",
                    "retry_reason": topic_retry_reason,
                    "rejected_candidates": rejected_candidates,
                },
            )
            if admitted:
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "pivot_topic_after_intake_candidate_rejection",
                    "stage_id": stage["id"],
                    "rejected_topic_ids": [item.get("topic_id") for item in rejected],
                    "reason": topic_retry_reason,
                })
            return admitted
        topic_budget_exhausted = self._is_local_topic_budget_exhaustion(error, stage)
        current_failure_class = classify_failure(stage.get("kind"), error)
        current_experiment_failure = (
            stage.get("kind") == "experiment"
            and current_failure_class == "experiment_failure"
        )
        retryable_topic_intake = (
            stage.get("kind") == "topic_discovery"
            and getattr(error, "retryable_topic_intake", False)
            and getattr(error, "status_code", None)
            not in {408, 425, 429, 500, 502, 503, 504}
        )
        if (current_failure_class == "resource_fence"
                and (not topic_budget_exhausted
                     and not retryable_topic_intake
                     or getattr(error, "status_code", None)
                     in {408, 425, 429, 500, 502, 503, 504})):
            return False
        model_contract_failure = not current_experiment_failure and (
            getattr(error, "failure_class", None) == "model_contract"
            or classify_failure(stage.get("kind"), error) == "model_contract"
            or prior_context.get("failure_class") == "model_contract"
            or prior_context.get("review_status") in {
                "model_contract_repair", "format_recovery_exhausted"}
            or legacy_topic_contract_failure
            or (not topic_budget_exhausted
                and failure_recovery.get("failure_class") == "model_contract")
        ) and not survey_assignment_blocker
        format_signature = self._format_recovery_signature(stage, error)
        format_ledger_entry = self.format_recovery_ledger.get(format_signature)
        exact_format_recovery_spent = (
            isinstance(format_ledger_entry, dict)
            and format_ledger_entry.get("status") in {"dispatched", "exhausted"}
        )
        # An exhausted local envelope does not erase a typed response-contract
        # failure. Repair the exact model contract first; only a scientific
        # rejection or genuinely spent proposal budget opens a new topic intake.
        if model_contract_failure and not exact_format_recovery_spent:
            # A bounded format repair is a same-stage route/prompt change. It
            # is still autonomous work: admit one explicit recovery order so
            # the next Composer pass actually reruns this stage. It must not
            # be mislabeled as a scientific pivot or released downstream.
            if ((failure_recovery.get("recovery_mode") == "format_repair_then_rerun"
                 or legacy_topic_contract_failure)
                    and not exact_format_recovery_spent):
                policy_revision = self._format_recovery_policy_revision(stage)
                requests = [item for item in prior_context.get("research_requests", [])
                            if isinstance(item, dict)
                            and item.get("recovery_mode") == "format_repair_then_rerun"
                            and item.get("target_stage_id") == stage["id"]
                            and item.get("repair_policy_revision") == policy_revision]
                if not requests:
                    request = self._format_contract_recovery_request(stage, prior_context)
                    if isinstance(request, dict):
                        requests = [request]
                if requests:
                    prior_format_attempts = prior_context.get("format_recovery_attempts", 0)
                    if type(prior_format_attempts) is not int or prior_format_attempts < 0:
                        prior_format_attempts = 0
                    prior_context.update({
                        "status": "research_expansion_required",
                        "review_status": "model_contract_repair",
                        "release_blocking": True,
                        "format_recovery": True,
                        "format_recovery_attempts": prior_format_attempts + 1,
                        "format_recovery_dispatched": False,
                        "format_recovery_signature": format_signature,
                        "format_recovery_policy_revision": policy_revision,
                        "research_requests": deepcopy(requests),
                        "preserve_work_orders": True,
                    })
                    self.format_recovery_ledger[format_signature] = {
                        **(format_ledger_entry or {}),
                        "stage_id": stage["id"], "status": "pending",
                        "request_ids": [item.get("id") for item in requests],
                        "response_contract_revision": policy_revision,
                    }
                    self.context[stage["id"]] = prior_context
                    if self._begin_continuation(completed, by_id):
                        self.department_activity.append({
                            "cycle": self.continuation_cycles,
                            "action": "admit_model_contract_recovery",
                            "stage_id": stage["id"],
                            "request_ids": [item.get("id") for item in requests],
                            "next_action": "reroute_and_compact_before_scientific_recovery",
                        })
                        return True
        if model_contract_failure:
            # A repeated or unadmittable response is an operational blocker,
            # not evidence against the research question. Preserve the topic
            # and prevent a format-only failure from spawning a scientific
            # pivot or a duplicate recovery call.
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "model_contract_recovery_exhausted",
                "stage_id": stage["id"],
                "failure_signature": format_signature,
                "recovery_status": (format_ledger_entry or {}).get("status", "unavailable"),
                "next_action": "preserve_scope_until_a_distinct_response_repair_is_available",
            })
            return False
        pre_execution_capability_failure = self._is_pre_execution_capability_failure(
            stage, prior_context, error)
        repair_order_available = (
            failure_recovery.get("recovery_mode") == "repair_then_rerun"
            and isinstance(prior_context.get("failure_dossier_ref"), str)
        )
        if (self._forward_first()
                and not pre_execution_capability_failure
                and not repair_order_available
                and not topic_budget_exhausted
                and stage.get("kind") != "survey"):
            # ``run`` converts actionable blockers into non-gating
            # provisional nodes. A restored old ``blocked`` projection must
            # not reopen the same stage and consume another mission cycle.
            return False
        # Aggregate acceptance failures must first reopen the retained review
        # workspace. This includes deterministic source-integrity blockers;
        # they are not evidence against the admitted topic and need no new
        # literature acquisition before the offending map claim is repaired.
        survey_review_blocker = (
            stage.get("kind") == "survey"
            and self._is_survey_aggregate_review_failure(error)
        )
        # A survey evidence-contract failure is not evidence against the topic.
        # Reopen only the retained assessment workspace; if that repair is no
        # longer available, preserve the same-topic blocker for source repair.
        if ((not isinstance(error, ModelWorkBlocked)
             and not topic_budget_exhausted
             and not survey_review_blocker
             and not survey_assignment_blocker
             and not repair_order_available)
                or stage.get("kind") not in STAGE_KINDS):
            return False
        self._remaining()
        if isinstance(error, ModelWorkBlocked) and stage.get("kind") != "topic_discovery":
            # A survey/experiment-only workflow has no upstream frontier to
            # replan. Do not manufacture repeated same-stage repair cycles;
            # preserve the blocker for an explicit caller. Full research
            # missions always have a topic ancestor and continue through that
            # pivot path instead.
            pending = list(stage.get("depends_on", []))
            seen = set()
            has_topic_ancestor = False
            while pending:
                candidate_id = pending.pop()
                if candidate_id in seen or candidate_id not in by_id:
                    continue
                seen.add(candidate_id)
                candidate_stage = by_id[candidate_id]
                if candidate_stage.get("kind") == "topic_discovery":
                    has_topic_ancestor = True
                    break
                pending.extend(candidate_stage.get("depends_on", []))
            if not has_topic_ancestor:
                return False
        context = deepcopy(prior_context)
        observed_experiment = self._has_executed_experiment_result(
            prior_context, self._stage_experiment_capability_id(stage),
            project_dir=self._current_experiment_result_project_dir(stage))
        repair_attempts = self._pre_execution_repair_count(stage, error=error)
        failure_debt = prior_context.get("failure_debt")
        if topic_budget_exhausted:
            # A local topic envelope is a resource boundary, not a scientific
            # rejection. If a topic was already admitted, continue its
            # literature path from retained checkpoints; otherwise resume the
            # initial topic intake with its candidate/rejection trace.
            next_cycle = self.continuation_cycles + 1
            request = self._topic_budget_recovery_request(
                stage, context, error, next_cycle=next_cycle)
            context.update({
                "stage_id": stage["id"],
                "kind": stage["kind"],
                "status": "research_expansion_required",
                "error": str(error)[:4096],
                "review_status": "topic_budget_exhausted",
                "topic_budget_recovery": {
                    "status": "required",
                    "scope": getattr(error, "topic_budget_scope", "unknown"),
                    "reason": "local capacity ended without a scientific rejection",
                    "previous_cycle": self.continuation_cycles,
                    "request_id": request["id"],
                    "topic_id": (context.get("topic") or {}).get("id")
                    if isinstance(context.get("topic"), dict) else None,
                },
                "research_expansion_requests": [request],
                "research_requests": [],
            })
            for attribute in (
                    "candidate_attempt_trace", "maturity_review_history",
                    "rejected_topic_history", "topic_response_repair"):
                value = getattr(error, attribute, None)
                if isinstance(value, (list, dict)) and value:
                    context[attribute] = deepcopy(value[-24:] if isinstance(value, list) else value)
            self.context[stage["id"]] = context
            if not self._begin_continuation(completed, by_id):
                return False
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": (
                    "resume_same_topic_survey_after_budget_exhaustion"
                    if request["kind"] == "literature_expansion"
                    else "resume_topic_intake_after_budget_exhaustion"
                ),
                "stage_id": stage["id"],
                "previous_cycle": self.continuation_cycles - 1,
                "request_id": request["id"],
                "topic_id": ((context.get("topic") or {}).get("id")
                             if isinstance(context.get("topic"), dict) else None),
                "target_stage_id": request.get("target_stage_id"),
                "reason": "local topic budget exhausted; continue the same evidence lineage",
            })
            return True
        if (stage.get("kind") == "experiment"
                and pre_execution_capability_failure):
            # An unexecuted capability failure is repaired on the same topic
            # before any topic pivot. The durable count selects a different
            # repair axis; it does not expire while the global mission fences
            # still permit evidence-producing work.
            prior = deepcopy(context)
            request = self._autonomous_experiment_repair_request(
                stage, context, error, repair_attempts)
            if request is not None and self._begin_continuation(completed, by_id):
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "schedule_pre_execution_capability_repair",
                    "stage_id": stage["id"],
                    "request_id": request["id"],
                    "failure_dossier_ref": request.get("failure_dossier_ref"),
                    "repair_attempts": repair_attempts + 1,
                    "next_action": "methods_diagnose_edit_program_replay_and_recalculate",
                })
                return True
            self.context[stage["id"]] = prior
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "experiment_repair_waiting_for_budget",
                "stage_id": stage["id"],
                "repair_attempts": repair_attempts,
                "reason": "the same-topic source-repair order could not open a continuation",
            })
            return False
        if survey_review_blocker:
            if self._admit_scoped_survey_repair(
                    stage, context, completed, by_id, error):
                return True
            context.update({
                "status": "research_expansion_required",
                "review_status": "survey_integrity_repair_waiting",
                "release_blocking": True,
                "error": str(error)[:4096],
            })
            self.context[stage["id"]] = context
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "hold_same_topic_after_survey_integrity_failure",
                "stage_id": stage["id"],
                "reason": (
                    "bibliographic/source-integrity findings require evidence repair and do not establish "
                    "that the research question is scientifically infeasible"
                ),
            })
            return False
        if survey_assignment_blocker:
            if self._admit_scoped_survey_repair(
                    stage, context, completed, by_id, error):
                return True
            self.department_activity.append({
                "cycle": self.continuation_cycles,
                "action": "hold_same_topic_after_survey_contract_failure",
                "stage_id": stage["id"],
                "reason": "the evidence contract is an output-validation requirement, not a scientific finding",
            })
            return False
        context.update({
            "stage_id": stage["id"],
            "kind": stage["kind"],
            "status": "research_expansion_required",
            "error": str(error)[:4096],
            "review_status": "scientific_assignment_blocked",
        })
        if isinstance(specialist_verifier, dict):
            context["specialist_verifier"] = deepcopy(specialist_verifier)
        self.context[stage["id"]] = context
        if not self._begin_continuation(completed, by_id):
            return False
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "auto_recover_scientific_blocker",
            "stage_id": stage["id"],
            "error": str(error)[:2048],
            "reopened_stage_ids": sorted(self.reopened_stage_ids),
            "next_condition": "complete the cycle-specific work order and re-run every affected admission gate",
        })
        return True

    def _resume_misclassified_argument_review(self, completed, by_id):
        """Resume a persisted scientific review hidden by an older quota error.

        Older checkpoints can contain a valid argument-review dossier whose
        failure class was incorrectly copied from a previous quota blocker.
        Reclassify only when the dossier's own error is non-resource, its
        persisted independent review explicitly requires revision, and its
        directives demand an experiment. This reuses the existing review and
        prevents another argument-model cycle from being spent first.
        """
        stage = next((item for item in self.workflow.get("stages", [])
                      if item.get("kind") == "argument"), None)
        if not isinstance(stage, dict):
            return False
        if any(self._is_topic_pivot_request(item)
               for item in self.active_research_requests):
            return False
        stage_id = stage["id"]
        record = self.stage_records.get(stage_id)
        if not isinstance(record, dict):
            return False
        attempts = record.get("attempts", [])
        if not isinstance(attempts, list):
            return False
        topic_identity = self._current_topic_identity()
        stale_attempts = []

        def belongs_to_superseded_topic(attempt):
            if not isinstance(topic_identity, dict):
                return False
            attempt_topic_id = attempt.get("topic_id")
            attempt_topic_cycle = attempt.get("topic_cycle")
            if (isinstance(attempt_topic_id, str)
                    and attempt_topic_id != topic_identity["topic_id"]):
                return True
            if (type(attempt_topic_cycle) is int
                    and attempt_topic_cycle != topic_identity["topic_cycle"]):
                return True
            # Older checkpoints did not persist topic identity on each
            # attempt.  Topic evolution cycles share the Composer cycle
            # sequence, so an attempt from before the admitted frontier is
            # stale; attempts at or after it remain eligible for recovery.
            attempt_cycle = attempt.get("cycle")
            if (type(attempt_cycle) is int
                    and type(topic_identity.get("topic_cycle")) is int
                    and attempt_cycle < topic_identity["topic_cycle"]):
                return True
            return False

        candidates = [item for item in reversed(attempts)
                      if isinstance(item, dict)
                      and item.get("state") == "failed"
                      and item.get("failure_class") == "resource_fence"
                      and isinstance(item.get("failure_dossier_ref"), str)]
        superseded_record = (
            record.get("lineage_state") == "awaiting_topic_admission"
            or isinstance(record.get("superseded_topic_id"), str)
        )
        candidate = None if superseded_record else next(
            (item for item in candidates
             if not belongs_to_superseded_topic(item)), None)
        stale_attempts = (candidates if superseded_record else [
            item for item in candidates if belongs_to_superseded_topic(item)
        ])
        if candidate is None and stale_attempts:
            context = self.context.get(stage_id)
            context = context if isinstance(context, dict) else {}
            recovery = context.get("failure_recovery")
            recovery = recovery if isinstance(recovery, dict) else {}
            stale_attempt_numbers = {
                item.get("attempt_number") for item in stale_attempts
                if type(item.get("attempt_number")) is int
            }
            context_attempt = recovery.get("attempt_number")
            context_is_stale = context_attempt in stale_attempt_numbers
            if superseded_record or context_is_stale:
                source_attempt = stale_attempts[0]
                transition_ref = record.get("lineage_transition_ref")
                retired_requests = [
                    item.get("id") for item in context.get("research_requests", [])
                    if isinstance(item, dict) and isinstance(item.get("id"), str)
                ] if isinstance(context.get("research_requests"), list) else []
                superseded_topic_id = (
                    record.get("superseded_topic_id") or source_attempt.get("topic_id")
                )
                context_lineage = context.get("topic_lineage")
                if (not isinstance(superseded_topic_id, str)
                        and isinstance(context_lineage, dict)):
                    superseded_topic_id = context_lineage.get("topic_id")
                self.context[stage_id] = {
                    "stage_id": stage_id,
                    "kind": "argument",
                    "status": "topic_pivot_pending",
                    "lineage_state": "awaiting_topic_admission",
                    **({"superseded_topic_id": superseded_topic_id}
                       if isinstance(superseded_topic_id, str) else {}),
                    **({"topic_pivot_cycle": record["topic_pivot_cycle"]}
                       if type(record.get("topic_pivot_cycle")) is int else {}),
                    **({"lineage_transition_ref": transition_ref}
                       if isinstance(transition_ref, str) else {}),
                    "retired_review_recovery": {
                        "source_attempt_number": source_attempt.get("attempt_number"),
                        "source_failure_dossier_ref": source_attempt.get("failure_dossier_ref"),
                        "migrated_failure_dossier_ref": context.get("failure_dossier_ref"),
                        "reason": "review belongs to a superseded topic lineage; immutable attempt and dossier remain auditable",
                        "retired_work_order_ids": retired_requests,
                    },
                }
                already_audited = any(
                    isinstance(item, dict)
                    and item.get("action") == "retire_superseded_argument_review_recovery"
                    and item.get("source_attempt_number") == source_attempt.get("attempt_number")
                    and item.get("lineage_transition_ref") == transition_ref
                    for item in self.department_activity
                )
                if not already_audited:
                    self.department_activity.append({
                        "cycle": self.continuation_cycles,
                        "action": "retire_superseded_argument_review_recovery",
                        "stage_id": stage_id,
                        "source_attempt_number": source_attempt.get("attempt_number"),
                        "source_cycle": source_attempt.get("cycle"),
                        "source_failure_dossier_ref": source_attempt.get("failure_dossier_ref"),
                        "lineage_transition_ref": transition_ref,
                        "retired_work_order_ids": retired_requests,
                        "reason": "a completed topic pivot supersedes this review; no replay or model call is warranted",
                        "model_calls": 0,
                    })
                self._checkpoint("resume:retire_superseded_argument_review", force=True)
            return False
        if candidate is None:
            return False
        old_ref = candidate["failure_dossier_ref"]
        try:
            old_manifest = self.store.get(old_ref)
            dossier = json.loads(self.store.read_body(old_manifest["body_hash"]))
        except (NotFoundError, KeyError, OSError, TypeError, ValueError):
            return False
        if not isinstance(dossier, dict) or dossier.get("failure_class") != "resource_fence":
            return False
        error_text = dossier.get("error")
        attempt_error = str(candidate.get("error") or "")
        if (not isinstance(error_text, str) or not error_text
                or not attempt_error.endswith(error_text)):
            return False
        if classify_failure(stage.get("kind"), error_text, {"error": error_text}) != "scientific_review":
            return False
        diagnostics = dossier.get("model_diagnostics")
        review = diagnostics.get("research_review") if isinstance(diagnostics, dict) else None
        if not isinstance(review, dict) or review.get("decision") not in {"revise", "hold"}:
            return False
        dossier["artifact_ref"] = old_ref
        experiment_request = self._argument_experiment_repair_request(stage, dossier)
        if experiment_request is None:
            return False

        corrected = deepcopy(dossier)
        corrected.update({
            "failure_class": "scientific_review",
            "recoverable": True,
            "next_action": "create_scoped_repair_work_order_and_repair_before_rerun",
            "recovery_migration": {
                "reason": "current argument review was masked by a stale resource-fence classification",
                "supersedes_artifact_ref": old_ref,
                "classification_source": "dossier.error plus persisted independent research review",
            },
        })
        corrected.pop("input_sha256", None)
        corrected.pop("artifact_ref", None)
        corrected["input_sha256"] = hashlib.sha256(canonical_bytes(corrected)).hexdigest()
        corrected_manifest = self._publish(
            old_ref[len("artifact:"):].rsplit("@", 1)[0],
            "report", corrected, "command.composer",
            subjects=[old_ref],
        )
        corrected["artifact_ref"] = corrected_manifest["artifact_ref"]
        request = build_repair_request(corrected, stage_id=stage_id)
        request["failure_dossier_ref"] = corrected_manifest["artifact_ref"]
        experiment_request = self._argument_experiment_repair_request(stage, corrected)
        if experiment_request is None:
            raise StateError("argument review migration lost its experiment repair request")
        recovery = {
            "schema_version": "failure-recovery-ledger-1",
            "failure_class": "scientific_review",
            "dossier_ref": corrected_manifest["artifact_ref"],
            "input_sha256": corrected.get("input_sha256"),
            "repair_commands": deepcopy(corrected.get("repair_commands", [])),
            "acceptance_checks": deepcopy(corrected.get("acceptance_checks", [])),
            "review_directives": deepcopy(corrected.get("review_directives", [])),
            "model_diagnostics": deepcopy(corrected.get("model_diagnostics", {})),
            "recovery_mode": "repair_then_rerun",
            "requires_capability_repair": False,
            "attempt_number": candidate.get("attempt_number"),
        }
        self.context[stage_id] = {
            "stage_id": stage_id,
            "kind": "argument",
            "status": "research_expansion_required",
            "error": error_text,
            "review_status": "scientific_assignment_blocked",
            "failure_recovery": recovery,
            "failure_dossier_ref": corrected_manifest["artifact_ref"],
            "failure_observed_result": deepcopy(corrected.get("observed_result", {})),
            "repair_commands": deepcopy(corrected.get("repair_commands", [])),
            "acceptance_checks": deepcopy(corrected.get("acceptance_checks", [])),
            "review_directives": deepcopy(corrected.get("review_directives", [])),
            "model_diagnostics": deepcopy(corrected.get("model_diagnostics", {})),
            "research_requests": [request, experiment_request],
            "failure_debt": {
                "stage_id": stage_id,
                "kind": "argument",
                "failure_class": "scientific_review",
                "error": error_text[:4096],
                "attempts": candidate.get("attempt_number"),
                "next_action": "execute the review's evidence-producing Methods order before rebuilding the argument",
                "release_blocking": True,
                "failure_dossier_ref": corrected_manifest["artifact_ref"],
            },
        }
        self.department_activity.append({
            "cycle": self.continuation_cycles,
            "action": "recover_misclassified_argument_review",
            "stage_id": stage_id,
            "source_attempt_number": candidate.get("attempt_number"),
            "superseded_dossier_ref": old_ref,
            "failure_dossier_ref": corrected_manifest["artifact_ref"],
            "target_stage_id": experiment_request["target_stage_id"],
            "model_calls": 0,
        })

        # The current execution is known to have been interrupted. Settle its
        # parent lease as unknown before clearing the live assignment; child
        # specialist leases were reconciled by DepartmentRuntime at startup.
        active_attempt_id = record.get("attempt_id")
        if record.get("status") == "running" and isinstance(active_attempt_id, str):
            self._reconcile_interrupted_attempt(active_attempt_id)
            if not any(isinstance(item, dict)
                       and item.get("attempt_id") == active_attempt_id
                       and item.get("state") == "unknown" for item in attempts):
                attempts.append({
                    "attempt_number": record.get("attempt_number", len(attempts) + 1),
                    "attempt_id": active_attempt_id,
                    "cycle": self.continuation_cycles,
                    "state": "unknown",
                    "project_dir": record.get("project_dir"),
                    "error": "Composer resumed after an incomplete stage attempt; outcome was not observed.",
                })
            record["attempts"] = attempts
            record["attempt_count"] = max(
                int(record.get("attempt_count", 0) or 0), len(attempts))
            record["last_attempt_id"] = active_attempt_id
            record.pop("attempt_id", None)
            if record.get("task_id"):
                record["last_task_id"] = record.pop("task_id")
            record["status"] = "retrying"
            self.stage_records[stage_id] = self._retire_stage_assignment(record)

        for downstream in self.workflow.get("stages", []):
            downstream_id = downstream.get("id")
            if (downstream_id == stage_id
                    or downstream.get("kind") not in {"interpretation", "paper"}):
                continue
            old_context = self.context.get(downstream_id)
            if not isinstance(old_context, dict):
                continue
            stale_requests = []
            for key in ("research_expansion_requests", "research_requests",
                        "deferred_research_requests"):
                value = old_context.get(key)
                if isinstance(value, list):
                    stale_requests.extend(item for item in value if isinstance(item, dict))
            if stale_requests:
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "retire_downstream_requests_before_upstream_repair",
                    "stage_id": downstream_id,
                    "request_ids": [item.get("id") for item in stale_requests],
                    "reason": "upstream experiment and argument will be rebuilt before this consumer reruns",
                })
            self.context[downstream_id] = {
                "kind": downstream.get("kind"),
                "status": "upstream_refresh_pending",
            }
        for blocker in self.blockers:
            if (isinstance(blocker, dict) and blocker.get("stage_id") == stage_id
                    and blocker.get("stop_reason") == "stage_quota_exhausted"
                    and blocker.get("recovery") != "cycle_admitted"):
                blocker["recovery"] = "superseded_by_current_scientific_review"
                blocker["superseded_by_dossier_ref"] = corrected_manifest["artifact_ref"]
        return True

    def _pause_at_stage_boundary(self, stage_id):
        if self.stop_after_stage != stage_id:
            return False
        self.status = "paused"
        self.blockers.append({"stage_id": "workflow", "boundary_stage_id": stage_id, "reason": "declared operator stage boundary reached",
                              "stop_reason": "operator_stage_boundary"})
        self._checkpoint(f"{stage_id}:operator_stage_boundary", force=True)
        return True

    def run(self):
        try:
            for stage in self.workflow["stages"]:
                if stage.get("kind") != "topic_discovery" or self._topic_review_revalidation_input(stage) is None:
                    continue
                try:
                    self.revalidate_topic_review(stage["id"])
                except Exception as error:
                    self.status = "paused"
                    self.blockers.append({"stage_id": stage["id"], "reason": f"{type(error).__name__}: {error}",
                                          "stop_reason": "operational_state", "review_revalidation_required": True})
                    self._checkpoint("paused:topic_review_revalidation", force=True)
                    return self._finish()
            if self.stop_after_stage is not None and self.stage_records.get(self.stop_after_stage, {}).get("status") in {"completed", "candidate_needs_review", "research_expansion_required", "review_rejected"}:
                if self._pause_at_stage_boundary(self.stop_after_stage):
                    return self._finish()
            self._execution_started = True
            self.status = "running"
            self._reconcile_interrupted_stage_attempts()
            by_id = {stage["id"]: stage for stage in self.workflow["stages"]}
            foundry_rejections = self._reconcile_interrupted_foundry_rejection(by_id)
            if foundry_rejections:
                self._checkpoint(
                    "resume:restore_same_topic_scientific_repair_after_foundry_rejection",
                    force=True,
                )
            mixed_experiment_failures = self._reconcile_mixed_experiment_response_failure(by_id)
            if mixed_experiment_failures:
                self._checkpoint(
                    "resume:restore_scientific_experiment_repair_after_truncation",
                    force=True,
                )
            author_policy_reconciled = self._reconcile_experiment_author_output_policy(by_id)
            if author_policy_reconciled:
                self._checkpoint("resume:experiment_author_output_policy", force=True)
            stale_forward_handoffs = self._reconcile_stale_forward_handoffs(by_id)
            if stale_forward_handoffs:
                self._checkpoint("resume:reconcile_stale_forward_handoffs", force=True)
            legacy_retry_schedules = self._invalidate_legacy_provider_retry_schedules(by_id)
            if legacy_retry_schedules:
                self._checkpoint("resume:legacy_provider_retry_schedule_invalidated", force=True)
            completed = {stage_id for stage_id, row in self.stage_records.items()
                         if self._stage_releases_dependencies(
                             row, stage_kind=by_id.get(stage_id, {}).get("kind"))}
            if self._restore_interrupted_completed_survey_acquisition(completed, by_id):
                self._checkpoint("resume:completed_survey_acquisition_reused", force=True)
            restored_lineage_frontier = self._restore_unjustified_refinement_frontier(
                completed, by_id)
            if (isinstance(self._restored_topic_lineage_reconciliation, dict)
                    and not restored_lineage_frontier):
                self.status = "paused"
                self.blockers.append({
                    "stage_id": "experiment",
                    "reason": (
                        "the off-lineage checkpoint was rejected, but its prior topic, current "
                        "survey references, or matching experiment repair dossier could not be "
                        "validated for an automatic resume"
                    ),
                    "stop_reason": "lineage_recovery_validation_incomplete",
                    "model_calls_dispatched": 0,
                })
                self._checkpoint("paused:lineage_recovery_validation_incomplete", force=True)
                return self._finish()
            resume_keep_task_ids = {
                row.get("task_id") for row in self.stage_records.values()
                if isinstance(row, dict)
                and row.get("status") in {"running", "retrying"}
                and isinstance(row.get("task_id"), str)
            }
            retired_stage_tasks = self._retire_superseded_stage_tasks(
                by_id,
                reason="superseded by the restored Composer frontier",
                keep_task_ids=resume_keep_task_ids,
            )
            if retired_stage_tasks:
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "retire_stale_stage_tasks_on_resume",
                    "stage_tasks": retired_stage_tasks,
                })
                self._checkpoint("resume:retire_stale_stage_tasks", force=True)
            release_blocked_stage_ids = {
                stage_id for stage_id, row in self.stage_records.items()
                if row.get("status") == "candidate_needs_review"
                and not self._stage_releases_dependencies(
                    row, stage_kind=by_id.get(stage_id, {}).get("kind"))
            }
            # A prior attempt may have produced a release-blocking candidate
            # solely because a provider wrapped an otherwise complete JSON
            # response incorrectly.  Let the exact stage checkpoint consume
            # its one bounded format recovery; do not replay a full mission or
            # silently release a scientific candidate downstream.
            for stage_id in tuple(release_blocked_stage_ids):
                stage = by_id.get(stage_id)
                if self._release_blocked_format_retry_allowed(
                        stage, self.stage_records.get(stage_id, {})):
                    release_blocked_stage_ids.remove(stage_id)
                    self.stage_records[stage_id]["format_recovery_admitted"] = True
                    self._checkpoint(f"resume:{stage_id}:format_recovery_admitted", force=True)
            # Older forward-first checkpoints could park a capability-authoring
            # failure as a release-blocking candidate even though the
            # experiment never produced data. Reopen that scoped failure into
            # the Composer's scientific pivot path instead of replaying the
            # same program or waiting for human review.
            for stage_id in tuple(release_blocked_stage_ids):
                stage = by_id.get(stage_id)
                record = self.stage_records.get(stage_id, {})
                if self._release_blocked_topic_contract_retry_allowed(stage, record):
                    # The failed topic never produced an admitted artifact.
                    # Reuse the already-open continuation, if any, and let
                    # the fixed intake contract consume exactly one fresh
                    # topic attempt instead of reopening another cycle.
                    release_blocked_stage_ids.remove(stage_id)
                    record["contract_recovery_admitted"] = True
                    record["status"] = "retrying"
                    self._checkpoint(
                        f"resume:{stage_id}:contract_recovery_admitted", force=True)
                    continue
                if (stage_id in self.continuation_pending_stage_ids
                        and self._is_pre_execution_capability_failure(
                            stage, self.context.get(stage_id), record.get("error"))):
                    # This blocker already belongs to the active continuation
                    # opened by the prior Composer. Do not create another
                    # pivot or spend a second recovery cycle; simply release
                    # the old provisional node so the new topic can flow back
                    # through survey and experiment in order.
                    release_blocked_stage_ids.remove(stage_id)
                    record["status"] = "retrying"
                    record["recovery_admitted"] = True
                    self._checkpoint(
                        f"resume:{stage_id}:existing_continuation_admitted", force=True)
                    continue
                context = self.context.get(stage_id)
                if not self._is_pre_execution_capability_failure(
                        stage, context, record.get("error")):
                    continue
                error_text = record.get("error") or (
                    context.get("error") if isinstance(context, dict) else None
                ) or "pre-execution capability authoring failed"
                if self._admit_scientific_blocker_recovery(
                    stage, ModelWorkBlocked(str(error_text)), completed, by_id):
                    release_blocked_stage_ids.remove(stage_id)
                    record["status"] = "retrying"
                    record["recovery_admitted"] = True
                    self._checkpoint(f"resume:{stage_id}:scientific_recovery_admitted", force=True)
            # Migrate the old forward-first meaning on resume.  Earlier
            # checkpoints used ``release_blocking`` for every provisional
            # artifact, so the Composer could be left behind its own
            # deterministic repair gate.  The current authority model keeps
            # the same artifact and debt but records an explicit Composer
            # handoff and exposes it to the next dependency.
            for stage_id in tuple(release_blocked_stage_ids):
                stage = by_id.get(stage_id)
                record = self.stage_records.get(stage_id, {})
                if (not self._can_migrate_forward_candidate(
                        record, self.context.get(stage_id))
                        or stage is None or stage.get("kind") == "paper"):
                    continue
                context = self.context.get(stage_id, {})
                context = self._authorize_forward_context(
                    stage, context, reason="resume_migrated_forward_first_candidate")
                self.context[stage_id] = deepcopy(context)
                record.update({
                    "status": "candidate_needs_review",
                    "composer_decision": "advance_with_findings",
                    "progression_state": "advanced_with_findings",
                    "release_blocking": False,
                    "failure_debt": deepcopy(context.get("failure_debt", {})),
                })
                self.stage_records[stage_id] = record
                release_blocked_stage_ids.remove(stage_id)
                completed.add(stage_id)
                self.continuation_pending_stage_ids.discard(stage_id)
                self._mark_forward_blockers_advisory(stage_id)
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "migrate_forward_first_candidate",
                    "stage_id": stage_id,
                    "authority": "command.composer",
                    "release_blocking": False,
                })
                self._checkpoint(
                    f"resume:{stage_id}:composer_advance_with_findings", force=True)
            for stage_id, record in self.stage_records.items():
                if (isinstance(record, dict)
                        and record.get("composer_decision") == "advance_with_findings"):
                    self._mark_forward_blockers_advisory(stage_id)
                    self.continuation_pending_stage_ids.discard(stage_id)
            required_ids = set(self.workflow["completion"]["required_stage_ids"])
            if self.continuation_pending_stage_ids:
                completed.difference_update(self.continuation_pending_stage_ids)
            migration_reopened = restored_lineage_frontier
            if (not migration_reopened
                    and self._reconcile_restored_topic_refinement_failure(completed, by_id)):
                migration_reopened = True
                self._checkpoint("resume:parent_preserving_topic_refinement", force=True)
            restored_topic_failure = (
                None if migration_reopened
                else self._restored_topic_feasibility_failure(by_id)
            )
            if restored_topic_failure is not None:
                topic_stage_id, reason = restored_topic_failure
                self._queue_topic_feasibility_revalidation(topic_stage_id, reason)
                if not self._begin_continuation(completed, by_id):
                    self.status = "blocked"
                    self.blockers.append({
                        "stage_id": topic_stage_id,
                        "reason": "completed topic failed current feasibility revalidation and no continuation window is available",
                        "detail": str(reason)[:2048],
                    })
                    self._checkpoint("blocked:topic_feasibility_revalidation", force=True)
                    return self._finish()
                migration_reopened = True
                self._checkpoint("resume:topic_feasibility_revalidation", force=True)
            if (not migration_reopened
                    and self._resume_misclassified_argument_review(completed, by_id)):
                if not self._begin_continuation(completed, by_id):
                    self.status = "paused"
                    self.blockers.append({
                        "stage_id": "argument",
                        "reason": "a persisted argument review was recovered but its scoped Methods repair could not be admitted",
                        "stop_reason": "recovered_scientific_review_waiting_for_admission",
                    })
                    self._checkpoint("paused:recovered_argument_review_admission", force=True)
                    return self._finish()
                migration_reopened = True
                self._checkpoint("resume:argument_review_routed_to_experiment", force=True)
            # A persisted failed topic refinement with an intact admitted
            # frontier is a recovery case, not a fresh hold to re-admit. Restore
            # its source-grounded survey and scientific work orders before the
            # generic hold handler can reopen the stale pivot request.
            retained_survey_frontier_restored = (
                self._restore_retained_survey_frontier_after_failed_topic_pivot(
                    completed, by_id)
            )
            if retained_survey_frontier_restored:
                if not self._begin_continuation(completed, by_id):
                    self.status = "paused"
                    self.blockers.append({
                        "stage_id": next((stage["id"] for stage in self.workflow["stages"]
                                          if stage.get("kind") == "survey"), "survey"),
                        "reason": (
                            "the retained topic/evidence frontier was restored, but its scoped "
                            "repair work orders could not be admitted"
                        ),
                        "stop_reason": "recovery_admission_blocked",
                        "model_calls_dispatched": 0,
                    })
                    self._checkpoint("paused:retained_survey_recovery_unavailable", force=True)
                    return self._finish()
                migration_reopened = True
                self._checkpoint("resume:retained_survey_frontier_admitted", force=True)
            # A checkpoint may predate the immediate-hold admission rule.  On
            # resume, repair/review holds are reconciled before the scheduler
            # can admit any downstream consumer; this also prevents an
            # interrupted run from silently treating an old proposal as data.
            held = {stage_id for stage_id, row in self.stage_records.items()
                    if row.get("status") in STAGE_HOLD_STATUSES}
            if held and not migration_reopened and self._begin_continuation(completed, by_id):
                self._checkpoint("continuation:resume_admitted", force=True)
            elif held and not migration_reopened:
                hold_status = ("research_expansion_required"
                               if any(self.stage_records[item].get("status") == "research_expansion_required"
                                      for item in held)
                               else "review_rejected")
                self.status = hold_status
                self._checkpoint(f"resume:{hold_status}", force=True)
                return self._finish()
            # A supervisor may restart after the previous process wrote a
            # terminal-looking blocker. Reopen recoverable scientific stages
            # before dependency scheduling so a restart is a continuation, not
            # another pass through the same dead end. Hard deadlines, provider
            # cooldowns, global quotas, and unknown external outcomes remain
            # explicit stop conditions.
            if self._reopen_blocked_checkpoint(completed, by_id):
                self._checkpoint("resume:blocked_stage_recovery_admitted", force=True)
            survey_quota_result_restored = (
                self._restore_completed_survey_after_quota_recovery(completed, by_id)
            )
            if survey_quota_result_restored:
                self._checkpoint("resume:exploratory_survey_result_reused", force=True)
            if self._resume_stage_quota_recovery(completed, by_id):
                self._checkpoint("resume:stage_quota_recovery_admitted", force=True)
            if self._resume_survey_provider_fallback(by_id):
                self._checkpoint("resume:survey_provider_fallback_admitted", force=True)
            if (not retained_survey_frontier_restored
                    and not survey_quota_result_restored
                    and self._resume_stale_survey_contract_repair(completed, by_id)):
                self._checkpoint("resume:survey_contract_repair_admitted", force=True)
            if self._resume_exhausted_pre_execution_experiment(completed, by_id):
                self._checkpoint("resume:experiment_repair_admitted", force=True)
            while True:
                if self._restore_completed_survey_after_quota_recovery(completed, by_id):
                    # Stage outcomes can become durable after startup during a
                    # continuation. Reconcile them before quota admission so
                    # a successful survey is neither charged as a fresh pass
                    # nor converted into a topic pivot.
                    self._checkpoint("survey:reuse_completed_result_before_quota_admission",
                                     force=True)
                paper_gate_changed = self._refresh_paper_release_gate(
                    completed, by_id, release_blocked_stage_ids)
                if paper_gate_changed:
                    self._checkpoint("paper:upstream_scientific_hold", force=True)
                if self._paper_gate_repair_requests:
                    if self._begin_continuation(completed, by_id):
                        # The repair closure includes the paper consumer.  It
                        # must be retried after the repaired upstream packet,
                        # rather than remaining in the old release-blocked set.
                        release_blocked_stage_ids.difference_update(
                            self.reopened_stage_ids)
                        self._checkpoint(
                            f"paper:scoped_repair_admitted:{self.continuation_cycles}",
                            force=True,
                        )
                        continue
                if required_ids.issubset(completed) and self.continuation_pending_stage_ids.issubset(completed):
                    # A completed graph may still contain a first-class
                    # research request or an editorial rejection.  Reopen only
                    # the affected closure, then let the normal dependency
                    # scheduler execute it under the same hard wall.
                    if self._begin_continuation(completed, by_id):
                        continue
                    break
                self._remaining()
                progress = False
                dependency_ready_stages = [
                    stage for stage in self.workflow["stages"]
                    if stage["id"] not in completed
                    and stage["id"] not in release_blocked_stage_ids
                    and set(stage["depends_on"]).issubset(completed)
                ]
                ready_stages = []
                deferred_stages = []
                now_epoch = time.time()
                for stage in dependency_ready_stages:
                    schedule = self.retry_schedule.get(stage["id"])
                    not_before = (schedule.get("not_before_epoch")
                                  if isinstance(schedule, dict) else None)
                    if (type(not_before) in (int, float) and math.isfinite(not_before)
                            and not_before > now_epoch):
                        deferred_stages.append(stage)
                        continue
                    self.retry_schedule.pop(stage["id"], None)
                    ready_stages.append(stage)
                if not ready_stages and deferred_stages:
                    next_epoch = min(
                        self.retry_schedule[stage["id"]]["not_before_epoch"]
                        for stage in deferred_stages)
                    self._remaining()
                    self._checkpoint("agenda:retry_deferred")
                    time.sleep(min(5.0, max(0.0, next_epoch - time.time())))
                    continue
                ordered_ready_stages = self._agenda_order(
                    ready_stages, completed=completed, by_id=by_id)
                if not ordered_ready_stages and release_blocked_stage_ids:
                    self.status = "candidate_needs_review"
                    self._checkpoint("candidate_needs_review:release_blocked", force=True)
                    return self._finish()
                if ordered_ready_stages:
                    self._checkpoint(
                        f"agenda:{self.agenda_decisions[-1]['decision_id']}:selected",
                        force=True)
                for stage in ordered_ready_stages:
                    provider_configuration_error = self._stage_provider_configuration_error(stage)
                    if provider_configuration_error is not None:
                        self.status = "paused"
                        self.blockers.append({
                            "stage_id": stage["id"],
                            "reason": str(provider_configuration_error),
                            "stop_reason": "provider_configuration",
                            "provider": provider_configuration_error.provider,
                            "credential_env": provider_configuration_error.credential_env,
                            "model_calls_dispatched": 0,
                        })
                        self._checkpoint(f"{stage['id']}:provider_configuration", force=True)
                        return self._finish()
                    dependency_gaps = self._stage_dependency_gaps(stage)
                    if dependency_gaps:
                        # A provisional survey can be visible to the agenda
                        # while its gap assessment is still missing.  Route
                        # that scientific debt back to survey before the
                        # consumer is admitted; reporting it as a generic
                        # wiring failure used to strand the whole mission.
                        upstream_recovery = self._admit_upstream_dependency_recovery(
                            stage, dependency_gaps, completed, by_id)
                        if upstream_recovery is not None:
                            upstream_id, recovery_admitted = upstream_recovery
                            if recovery_admitted:
                                self._checkpoint(
                                    f"{stage['id']}:upstream_dependency_recovery", force=True)
                                progress = True
                                break
                            stop_reason = "upstream_scientific_hold"
                            reason = (
                                f"upstream stage {upstream_id} has no current typed handoff "
                                "and no continuation lease is available"
                            )
                        else:
                            stop_reason = "missing_stage_input"
                            reason = "required downstream artifact is unavailable"
                        self.status = "blocked"
                        self.blockers.append({
                            "stage_id": stage["id"],
                            "reason": reason,
                            "stop_reason": stop_reason,
                            "dependencies": dependency_gaps,
                            "model_calls_dispatched": 0,
                        })
                        self._checkpoint(f"{stage['id']}:{stop_reason}", force=True)
                        return self._finish()
                    stage_quota_error = self._stage_quota_error(stage)
                    if stage_quota_error is not None:
                        quota_context = self.context.get(stage["id"])
                        quota_context = quota_context if isinstance(quota_context, dict) else {}
                        quota_recovery = quota_context.get("quota_recovery")
                        quota_recovery = quota_recovery if isinstance(quota_recovery, dict) else {}
                        quota_stage_record = self.stage_records.get(stage["id"])
                        quota_stage_record = (
                            quota_stage_record if isinstance(quota_stage_record, dict) else {}
                        )
                        recovery_admitted = self._admit_stage_quota_recovery(
                            stage, stage_quota_error, completed, by_id)
                        quota_context = self.context.get(stage["id"])
                        quota_context = quota_context if isinstance(quota_context, dict) else {}
                        quota_recovery = quota_context.get("quota_recovery")
                        quota_recovery = quota_recovery if isinstance(quota_recovery, dict) else {}
                        if recovery_admitted:
                            blocker = {
                                "stage_id": stage["id"],
                                "reason": str(stage_quota_error),
                                "stop_reason": "stage_quota_exhausted",
                                "dimension": stage_quota_error.dimension,
                                "limit": stage_quota_error.limit,
                                "observed": stage_quota_error.observed,
                                "usage": deepcopy(stage_quota_error.usage),
                                "model_calls_dispatched": 0,
                                "recovery": "cycle_admitted",
                                "quota_recovery_id": quota_recovery.get("recovery_id"),
                                "continuation_cycle": self.continuation_cycles,
                                "stage_attempt_count": quota_stage_record.get(
                                    "attempt_count", len(quota_stage_record.get("attempts", []))),
                                "repair_mode": "narrow_scope",
                            }
                            self.blockers.append(blocker)
                            stage_record = self.stage_records.setdefault(
                                stage["id"], {"kind": stage.get("kind")})
                            stage_record["status"] = "retrying"
                            stage_record["recovery_admitted"] = True
                            self._checkpoint(
                                f"{stage['id']}:stage_quota_recovery_admitted", force=True)
                            progress = True
                            break
                        self.status = "paused"
                        self.blockers.append({
                            "stage_id": stage["id"],
                            "reason": str(stage_quota_error),
                            "stop_reason": "stage_quota_exhausted",
                            "dimension": stage_quota_error.dimension,
                            "limit": stage_quota_error.limit,
                            "observed": stage_quota_error.observed,
                            "usage": deepcopy(stage_quota_error.usage),
                            "model_calls_dispatched": 0,
                            "quota_recovery_id": quota_recovery.get("recovery_id"),
                            "continuation_cycle": self.continuation_cycles,
                            "stage_attempt_count": quota_stage_record.get(
                                "attempt_count", len(quota_stage_record.get("attempts", []))),
                        })
                        self._checkpoint(f"{stage['id']}:stage_quota_exhausted", force=True)
                        return self._finish()
                    stage_id = stage["id"]
                    # The estimate is a planning reservation, not a promise.
                    # Bounded jobs reserve the complete downstream closure;
                    # an autonomous deadline-governed job may use a residual
                    # window for the next specialist and let that specialist's
                    # own contract decide whether a useful result fits.
                    remaining = self._remaining()
                    downstream_ids = set()
                    frontier = [stage_id]
                    while frontier:
                        current = frontier.pop()
                        if current in downstream_ids:
                            continue
                        downstream_ids.add(current)
                        frontier.extend(item for item, candidate in by_id.items()
                                        if current in candidate["depends_on"])
                    downstream = sum(float(by_id[item]["estimate_seconds"]) for item in downstream_ids)
                    required_window = min(float(stage["estimate_seconds"]), downstream)
                    retry_policy = self._retry_policy()
                    if remaining < required_window:
                        if (retry_policy.get("mode", "bounded") == "until_deadline"
                                and remaining > self._deadline_dispatch_floor()):
                            self.deadline_decisions.append({
                                "stage_id": stage_id,
                                "admission": "residual_window",
                                "remaining_seconds": remaining,
                                "estimated_stage_seconds": float(stage["estimate_seconds"]),
                                "estimated_downstream_seconds": downstream,
                                "safety_margin_seconds": self._deadline_dispatch_floor(),
                                "reason": "full_stage_estimate_does_not_fit; autonomous mode keeps the residual window",
                            })
                        else:
                            self.status = "paused"
                            self.blockers.append({
                                "stage_id": stage_id,
                                "reason": "required_stage_window_does_not_fit_remaining_deadline",
                                "remaining_seconds": remaining,
                                "required_stage_seconds": required_window,
                                "mode": retry_policy.get("mode", "bounded"),
                            })
                            self.deadline_decisions.append({
                                "stage_id": stage_id,
                                "admission": "deferred",
                                "remaining_seconds": remaining,
                                "required_stage_seconds": required_window,
                                "reason": "required_stage_window_does_not_fit_remaining_deadline",
                            })
                            self._checkpoint("paused_deadline", force=True)
                            return self._finish()
                    # Continuation stages receive a cycle-specific project
                    # namespace.  The original stage descriptor remains the
                    # immutable graph identity; only the dispatch copy changes.
                    stage = self._stage_for_cycle(stage)
                    prior_record = self.stage_records.get(stage_id, {})
                    retained_topic_result = self._recover_interrupted_topic_result(
                        stage, prior_record)
                    if retained_topic_result is not None:
                        self.department_activity.append({
                            "cycle": self.continuation_cycles,
                            "action": "recover_materialized_topic_result",
                            "stage_id": stage_id,
                            "source_attempt_number": retained_topic_result.get(
                                "source_attempt_number"),
                            "source_output_path": retained_topic_result["output_path"],
                            "source_output_sha256": retained_topic_result["output_sha256"],
                            "producer_calls_replayed": 0,
                            "next_action": "resume_only_missing_independent_reviews",
                        })
                    attempt_history = deepcopy(prior_record.get("attempts", []))
                    if not isinstance(attempt_history, list):
                        attempt_history = []
                    if prior_record.get("status") == "running" and prior_record.get("attempt_id"):
                        # Preserve the terminal ledger outcome and actual
                        # usage before allocating the next monotonically new
                        # attempt number.
                        attempt_history = self._archive_stage_attempt(
                            prior_record, attempts=attempt_history,
                            cycle=self.continuation_cycles,
                            default_project_dir=stage["project_dir"],
                            error=("Composer resumed after an incomplete stage attempt; "
                                   "outcome was not observed."),
                        )
                    last_error = None
                    stage_succeeded = False
                    context = None
                    adaptive_turn = self._agenda_policy()["mode"] == "adaptive"
                    adaptive_retry_scheduled = False
                    retry_indices = (range(1) if adaptive_turn else (
                        itertools.count()
                        if retry_policy.get("mode", "bounded") == "until_deadline"
                        else range(retry_policy["max_attempts"])
                    ))
                    for retry_index in retry_indices:
                        attempt_number = len(attempt_history) + 1
                        if retry_index:
                            try:
                                if not self._wait_before_retry(
                                        stage, attempt_number=attempt_number,
                                        retry_index=retry_index, error=last_error,
                                        downstream_seconds=downstream):
                                    last_error = ValidationError(
                                        "retry budget no longer fits the Composer hard deadline")
                                    break
                            except ComposerHardDeadlineExceeded:
                                raise
                            except Exception as exc:
                                last_error = exc
                                break
                        attempt_stage = self._attempt_stage(stage, attempt_number)
                        if retained_topic_result is not None:
                            attempt_stage["_resume_topic_result"] = deepcopy(
                                retained_topic_result)
                        task = self._stage_task(stage)
                        task_id = task["task_id"]
                        attempt_id = f"{task_id}-{uuid.uuid4().hex}"
                        attempt_started = self.clock()
                        attempt_seconds = min(float(stage["deadline_seconds"]), self._remaining())
                        attempt_stage["attempt_deadline_at_epoch"] = min(
                            self.deadline_epoch, time.time() + attempt_seconds)
                        self.tasks.start_attempt(
                            task_id, attempt_id, owner="command.composer",
                            lease_ttl_seconds=attempt_seconds,
                            payload={"stage_id": stage_id, "kind": stage["kind"],
                                     "attempt_number": attempt_number,
                                     "model_budget_cycle": (self.continuation_cycles
                                         if stage_id in self.reopened_stage_ids else 0),
                                     "attempt_deadline_at_epoch": attempt_stage["attempt_deadline_at_epoch"],
                                     "project_dir": attempt_stage["project_dir"]})
                        topic_lineage = (
                            self._current_topic_identity()
                            if stage["kind"] != "topic_discovery" else None
                        )
                        self.stage_records[stage_id] = {
                            "kind": stage["kind"], "status": "running",
                            "task_id": task_id, "attempt_id": attempt_id, "attempt_number": attempt_number,
                            "attempt_count": attempt_number,
                            "started_elapsed": attempt_started - self.started,
                            "attempt_deadline_at_epoch": attempt_stage["attempt_deadline_at_epoch"],
                            "project_dir": attempt_stage["project_dir"],
                            "attempts": deepcopy(attempt_history),
                            **({"completed_mapping": deepcopy(prior_record["completed_mapping"])}
                               if isinstance(prior_record.get("completed_mapping"), dict) else {}),
                            **({"topic_id": topic_lineage["topic_id"],
                                "topic_cycle": topic_lineage["topic_cycle"]}
                               if isinstance(topic_lineage, dict) else {}),
                        }
                        self._checkpoint(f"{stage_id}:admitted", force=True)
                        stop_live_progress = self._start_live_progress(attempt_stage)
                        # This belongs to the current attempt only.  A prior
                        # attempt may have produced a candidate before failing
                        # review; retaining it here would misclassify a later
                        # control-plane deadline as a late returned result.
                        context = None
                        stage_assignment = None
                        stage_admitted = False
                        specialist_bundle = {"reports": [], "by_role": {}, "usage": {}, "model_enabled": False}
                        specialist_verifier = None
                        failure_dossier = None
                        usage_recorded = False
                        producer_usage = None
                        producer_foundry_usage = {}
                        producer_repair_panel_usage = {}
                        try:
                            stage_assignment = self.departments.begin_stage(
                                stage_id, stage["kind"], attempt_number=attempt_number,
                                input_ref={
                                    "kind": "composer_stage_task", "ref": task_id,
                                    "digest": hashlib.sha256(canonical_bytes({
                                        "stage_id": stage_id, "attempt_number": attempt_number,
                                        "project_dir": attempt_stage["project_dir"],
                                    })).hexdigest(),
                                },
                                deadline_seconds=self._stage_remaining(attempt_stage),
                                active_role_ids=self._active_stage_role_ids(
                                    stage, stage_context=self.context.get(stage_id)),
                            )
                            stage_admitted = True
                            self.stage_records[stage_id].update(
                                self._stage_assignment_fields(stage_assignment))
                            self.department_activity.append({
                                "cycle": self.continuation_cycles,
                                "action": "activate_specialist_pool",
                                "stage_id": stage_id,
                                "attempt_number": attempt_number,
                                "required_agents": deepcopy(stage_assignment["required_agents"]),
                                "active_agents": deepcopy(stage_assignment["active_agents"]),
                                "verifier_agent": stage_assignment["verifier_agent"],
                                "assignment_plan_ref": stage_assignment["plan_ref"],
                                "assignment_ids": deepcopy(stage_assignment["assignment_ids"]),
                            })
                            self._checkpoint(f"{stage_id}:specialists_admitted", force=True)
                            try:
                                descriptor = json.loads(Path(attempt_stage["config_path"]).read_text())
                            except (OSError, ValueError, TypeError):
                                descriptor = {}
                            # Self-contained producers have no upstream
                            # research package. Their specialists inspect the
                            # generated artifact instead of an empty packet.
                            review_generated_result = (stage["kind"] == "topic_discovery"
                                or descriptor.get("schema_version") == "review-article-config-1")
                            # Methods, interpretation, argument, and editorial
                            # specialists review materialized scientific
                            # artifacts. Running the methods pool before the
                            # capability exists gives reproducibility and
                            # analysis reviewers empty projections; those
                            # deterministic "not run yet" holds do not change
                            # the capability brief and are repeated after a
                            # producer failure. Review the experiment result
                            # or its bounded failure envelope instead.
                            materialized_specialist_review = (
                                review_generated_result
                                or stage["kind"] in {
                                    "experiment", "interpretation", "argument", "paper"
                                }
                            )
                            if not review_generated_result and stage["kind"] == "survey":
                                preflight_error = self._survey_provider_cooldown(
                                    attempt_stage, descriptor)
                                if preflight_error is not None:
                                    # A configured Crossref identity is a
                                    # bounded route change, not permission to
                                    # burn specialist calls against a fenced
                                    # OpenAlex account.
                                    if not self._admit_survey_provider_fallback(
                                            attempt_stage, preflight_error):
                                        raise preflight_error
                            if materialized_specialist_review:
                                prior_topic_reports = None
                                if stage_id in self.reopened_stage_ids:
                                    prior_topic_context = self.context.get(stage_id, {})
                                    if isinstance(prior_topic_context, dict):
                                        prior_topic_reports = prior_topic_context.get(
                                            "specialist_reports")
                                try:
                                    if attempt_number == 1:
                                        context = self._run_stage(
                                            attempt_stage, specialist_reports=prior_topic_reports,
                                            stage_assignment=stage_assignment)
                                    else:
                                        context = self._run_stage(
                                            attempt_stage, attempt_number=attempt_number,
                                            specialist_reports=prior_topic_reports,
                                            stage_assignment=stage_assignment)
                                except Exception as producer_error:
                                    # A failed producer still has a scientific
                                    # object to inspect.  Give the admitted
                                    # reviewers the exact returned package (or
                                    # a bounded failure envelope) before the
                                    # outer recovery path records the dossier.
                                    self._end_child_activity(stage_id)
                                    reviewable_failure = self._should_run_failure_specialist_review(
                                        producer_error, attempt_stage)
                                    if reviewable_failure:
                                        specialist_bundle, specialist_verifier, context = (
                                            self._run_failure_specialist_review(
                                                attempt_stage, stage_assignment, descriptor,
                                                producer_error))
                                        if isinstance(context, dict):
                                            context["specialist_reports"] = deepcopy(
                                                specialist_bundle.get("reports", []))
                                            context["specialist_usage"] = deepcopy(
                                                specialist_bundle.get("usage", {}))
                                            if specialist_verifier is not None:
                                                context["specialist_verifier"] = deepcopy(
                                                    specialist_verifier)
                                    raise
                                self._end_child_activity(stage_id)
                                producer_usage = self._current_attempt_usage(context)
                                producer_foundry_usage = deepcopy(context.get("foundry_usage", {}))
                                producer_repair_panel_usage = deepcopy(context.get("repair_panel_usage", {}))
                                specialist_bundle = self._run_specialist_pool(
                                    attempt_stage, stage_assignment, descriptor,
                                    stage_result=context)
                            else:
                                specialist_bundle = self._run_specialist_pool(
                                    attempt_stage, stage_assignment, descriptor)
                            specialist_bundle = self._publish_specialist_reports(
                                attempt_stage, stage_assignment, specialist_bundle)
                            specialist_reports = specialist_bundle.get("reports", [])
                            limited = [report for report in specialist_reports
                                       if report.get("status") != "succeeded" and report.get("status_code") == 429]
                            if limited:
                                provider_delays = [
                                    float(report["retry_after_seconds"])
                                    for report in limited
                                    if type(report.get("retry_after_seconds")) in (int, float)
                                    and math.isfinite(report["retry_after_seconds"])
                                    and report["retry_after_seconds"] > 0
                                ]
                                raise ProviderCooldownError("specialist provider is cooling down",
                                    retry_after_seconds=max(
                                        provider_delays,
                                        default=DEFAULT_MODEL_RATE_LIMIT_COOLDOWN_SECONDS),
                                    rate_limit={"provider": "model", "status_code": 429,
                                                "retry_after_known": bool(provider_delays)})
                            if not materialized_specialist_review:
                                if attempt_number == 1:
                                    context = (self._run_stage(
                                        attempt_stage, specialist_reports=specialist_reports,
                                        stage_assignment=stage_assignment)
                                        if specialist_reports else self._run_stage(
                                            attempt_stage, stage_assignment=stage_assignment))
                                else:
                                    context = (self._run_stage(
                                        attempt_stage, attempt_number=attempt_number,
                                        specialist_reports=specialist_reports,
                                        stage_assignment=stage_assignment)
                                        if specialist_reports else self._run_stage(
                                            attempt_stage, attempt_number=attempt_number,
                                            stage_assignment=stage_assignment))
                                self._end_child_activity(stage_id)
                                producer_usage = self._current_attempt_usage(context)
                                producer_foundry_usage = deepcopy(context.get("foundry_usage", {}))
                                producer_repair_panel_usage = deepcopy(context.get("repair_panel_usage", {}))
                            if self._deadline_exhausted():
                                raise ComposerLateStageResult(
                                    "stage result exceeded the Composer hard deadline")
                            context = self._gate_survey_work_orders(attempt_stage, context)
                            outcome = context.get("status")
                            if outcome not in {"completed", "accepted", "candidate_needs_review",
                                               "research_expansion_required", "review_rejected"}:
                                raise ValidationError(f"stage {stage_id} did not complete: {outcome}")
                            context["specialist_reports"] = deepcopy(specialist_reports)
                            context["specialist_usage"] = deepcopy(specialist_bundle.get("usage", {}))
                            merged_usage = deepcopy(context.get("usage", {}))
                            if not isinstance(merged_usage, dict):
                                merged_usage = {}
                            for key in ("model_calls", "input_tokens", "output_tokens"):
                                value = specialist_bundle.get("usage", {}).get(key, 0)
                                if type(value) in (int, float) and math.isfinite(value) and value >= 0:
                                    merged_usage[key] = merged_usage.get(key, 0) + value
                            foundry_usage = context.get("foundry_usage", {})
                            if not isinstance(foundry_usage, dict):
                                foundry_usage = {}
                            for key in ("model_calls", "input_tokens", "output_tokens"):
                                value = foundry_usage.get(key, 0)
                                if type(value) in (int, float) and math.isfinite(value) and value >= 0:
                                    merged_usage[key] = merged_usage.get(key, 0) + value
                            repair_panel_usage = context.get("repair_panel_usage", {})
                            if isinstance(repair_panel_usage, dict):
                                for key in ("model_calls", "input_tokens", "output_tokens"):
                                    merged_usage[key] = merged_usage.get(key, 0) + repair_panel_usage.get(key, 0)
                            merged_usage["by_role"] = deepcopy(
                                specialist_bundle.get("usage", {}).get("by_role", {}))
                            context["usage"] = merged_usage
                            specialist_verifier = self._run_specialist_verifier(
                                attempt_stage, stage_assignment, descriptor,
                                specialist_bundle, context, stage_result=context)
                            if specialist_verifier is not None:
                                context["specialist_verifier"] = deepcopy(specialist_verifier)
                                verifier_usage = self._specialist_usage([specialist_verifier])
                                for key in ("model_calls", "input_tokens", "output_tokens"):
                                    value = verifier_usage.get(key, 0)
                                    if type(value) in (int, float) and math.isfinite(value) and value >= 0:
                                        context["usage"][key] = context["usage"].get(key, 0) + value
                                context["specialist_verifier_usage"] = deepcopy(verifier_usage)
                                verdict = (specialist_verifier.get("response", {})
                                           if isinstance(specialist_verifier, dict) else {})
                                if (specialist_verifier.get("status") != "succeeded"
                                        or not isinstance(verdict, dict)
                                        or verdict.get("decision") != "accept"):
                                    carried = (
                                        specialist_verifier.get("status") == "succeeded"
                                        and stage["kind"] == "topic_discovery"
                                        and self._carry_provisional_verifier_challenge(
                                            context, specialist_verifier)
                                    )
                                    if not carried:
                                        defer = (self.workflow.get("progression_policy") in {
                                                     "full_pass", FORWARD_FIRST_POLICY,
                                                 }
                                                 and stage["kind"] != "paper"
                                                 and specialist_verifier.get("status") == "succeeded"
                                                 and outcome in STAGE_READY_STATUSES)
                                        outcome = "candidate_needs_review" if defer else "review_rejected"
                                        if defer:
                                            context["deferred_review_findings"] = deepcopy(verdict)
                                        context["status"] = outcome
                            # ``candidate_needs_review`` is only a valid
                            # forward-first outcome when the experiment has
                            # produced inspectable evidence.  A model-contract
                            # recovery can otherwise look like a successful
                            # specialist pass and release an empty packet to
                            # Interpretation.  Convert every terminal-looking
                            # unexecuted experiment into a blocking, typed hold
                            # before the normal completion bookkeeping.
                            recovery = context.get("failure_recovery")
                            recovery = recovery if isinstance(recovery, dict) else {}
                            explicitly_unexecuted = (
                                context.get("results_status") == "not_executed"
                                or context.get("review_status") == "model_contract_repair"
                                or context.get("format_recovery") is True
                                or recovery.get("recovery_mode") in {
                                    "repair_then_rerun", "format_repair_then_rerun",
                                    "experiment_diagnose_patch_execute_recalculate",
                                }
                            )
                            if (
                                stage["kind"] == "experiment"
                                and explicitly_unexecuted
                                and outcome in {"completed", "accepted", "candidate_needs_review"}
                                and not self._has_executed_experiment_result(
                                    context, self._stage_experiment_capability_id(stage),
                                    project_dir=self._current_experiment_result_project_dir(attempt_stage))
                            ):
                                context = self._hold_unexecuted_experiment(
                                    stage, context,
                                    reason=(context.get("error")
                                            or "experiment returned no executable result"))
                                outcome = context["status"]
                                self.department_activity.append({
                                    "cycle": self.continuation_cycles,
                                    "action": "hold_unexecuted_experiment",
                                    "stage_id": stage_id,
                                    "reason": "no observed experiment result is available for downstream evidence",
                                    "work_order_ids": [item.get("id") for item in context.get("research_requests", [])
                                                       if isinstance(item, dict)],
                                })
                            # A failed independent review is a finding on an
                            # admitted stage, not a deterministic veto.  Keep
                            # the verdict attached to the candidate and let
                            # the Composer expose the dependency with an
                            # explicit backfill debt.
                            if self._should_authorize_forward_hold(outcome, context):
                                context = self._authorize_forward_context(
                                    stage, context, reason="admitted_stage_review_finding")
                                outcome = context["status"]
                            if stage["kind"] == "topic_discovery":
                                # Record the direction at admission time, even
                                # when a later survey or experiment hold stops
                                # the mission.  A failed attempt is still an
                                # attempted direction and must not be selected
                                # again by the next free-topic mission.
                                self._record_topic_history(context)
                            attempt_usage = self._current_attempt_usage(context)
                            producer_recovery = context.get("producer_recovery")
                            if isinstance(producer_recovery, dict):
                                producer_recovery["current_attempt_usage"] = deepcopy(
                                    attempt_usage)
                            foundry_charged = context.get("foundry_usage", {})
                            if not isinstance(foundry_charged, dict):
                                foundry_charged = {}
                            paid_specialists = self._paid_stage_specialist_usage([*specialist_bundle.get("reports", []),
                                *([specialist_verifier] if isinstance(specialist_verifier, dict) else [])])
                            incremental_usage = {}
                            for key in self.usage:
                                value = attempt_usage.get(key, 0)
                                if type(value) in (int, float) and math.isfinite(value) and value >= 0:
                                    already_charged = foundry_charged.get(key, 0) + paid_specialists.get(key, 0)
                                    repair_charged = context.get("repair_panel_usage", {})
                                    if isinstance(repair_charged, dict):
                                        already_charged += repair_charged.get(key, 0)
                                    if type(already_charged) not in (int, float) or already_charged < 0:
                                        already_charged = 0
                                    incremental_usage[key] = max(0, value - already_charged)
                            self._settle_pending_stage_usage(
                                stage_id, already_charged=True, additional_usage=incremental_usage)
                            usage_recorded = True
                            self._clear_child_progress(stage_id)
                            assignment_result = self.departments.finish_stage(
                                stage_id, stage["kind"], attempt_number=attempt_number,
                                outcome=outcome, output_ref=context.get("output_path"),
                                usage=attempt_usage, actor="command.composer",
                                specialist_results=specialist_bundle.get("by_role", {}),
                                verifier_result=specialist_verifier)
                            self.department_activity.append({
                                "cycle": self.continuation_cycles,
                                "action": "complete_specialist_pool",
                                "stage_id": stage_id,
                                "attempt_number": attempt_number,
                                "verifier_agent": assignment_result["verifier_agent"],
                                "verifier_outcome": assignment_result["verifier_outcome"],
                                "chief_synthesis_ref": assignment_result["chief_synthesis_ref"],
                                "verifier_artifact_ref": assignment_result["verifier_artifact_ref"],
                            })
                            self.tasks.finish_attempt(attempt_id, "succeeded", usage=attempt_usage)
                            self.tasks.transition(task_id, "awaiting_review", "command.composer", reason="stage output returned")
                            if outcome not in STAGE_HOLD_STATUSES:
                                self.tasks.transition(task_id, "completed", "command.composer", reason="stage-specific checks passed")
                            context["stage_id"] = stage_id
                            context["attempt_number"] = attempt_number
                            if stage["kind"] != "topic_discovery":
                                self._refresh_stage_topic_lineage(
                                    stage_id, context, attempt_id=attempt_id,
                                    topic_identity=topic_lineage,
                                )
                            previous_stage_context = deepcopy(self.context.get(stage_id))
                            self.context[stage_id] = context
                            if stage["kind"] == "topic_discovery":
                                self._retire_requests_after_topic_change(
                                    previous_stage_context, context)
                            self._mark_research_requests_attempted(stage)
                            if self.active_research_requests and not context.get(
                                    "preserve_work_orders"):
                                self.department_activity.append({
                                    "cycle": self.continuation_cycles,
                                    "action": "resolve_work_orders",
                                    "stage_id": stage_id,
                                    "outcome": outcome,
                                    "work_orders": self.departments.resolve_work_orders(
                                        self.active_research_requests,
                                        stage_kind=stage["kind"], stage_id=stage_id, outcome=outcome),
                                })
                            elif self.active_research_requests:
                                self.department_activity.append({
                                    "cycle": self.continuation_cycles,
                                    "action": "retain_work_orders_for_backfill",
                                    "stage_id": stage_id,
                                    "outcome": outcome,
                                    "work_orders": deepcopy(self.active_research_requests),
                                })
                            self.continuation_pending_stage_ids.discard(stage_id)
                            topic_usage = {}
                            if isinstance(context.get("budget"), dict):
                                topic_usage = context["budget"].get("usage", {})
                            if not isinstance(topic_usage, dict):
                                topic_usage = {}
                            attempt_history.append({
                                "attempt_number": attempt_number,
                                "attempt_id": attempt_id,
                                "cycle": self.continuation_cycles,
                                "state": "succeeded",
                                "project_dir": attempt_stage["project_dir"],
                                **({"topic_id": topic_lineage["topic_id"],
                                    "topic_cycle": topic_lineage["topic_cycle"]}
                                   if isinstance(topic_lineage, dict) else {}),
                                "usage": deepcopy(attempt_usage),
                                "topic_usage": deepcopy(topic_usage),
                                "elapsed_seconds": self.clock() - attempt_started,
                            })
                            self.stage_records[stage_id] = {
                                "kind": stage["kind"],
                                "status": (outcome if outcome in {
                                    "candidate_needs_review", "research_expansion_required", "review_rejected"}
                                           else "completed"),
                                "task_id": task_id, "attempt_id": attempt_id,
                                "attempt_number": attempt_number,
                                "attempt_count": attempt_number,
                                "attempts": deepcopy(attempt_history),
                                "output_path": context.get("output_path"),
                                "elapsed_seconds": self.clock() - self.started,
                                **({"topic_id": topic_lineage["topic_id"],
                                    "topic_cycle": topic_lineage["topic_cycle"]}
                                   if isinstance(topic_lineage, dict) else {}),
                                **self._stage_assignment_fields(stage_assignment, assignment_result),
                            }
                            stage_succeeded = True
                            break
                        except Exception as exc:
                            if isinstance(exc, ModelCallError) and exc.status_code == 429:
                                provider_error = exc
                                retry_after_known = (
                                    type(exc.retry_after_seconds) in (int, float)
                                    and math.isfinite(exc.retry_after_seconds)
                                    and exc.retry_after_seconds > 0
                                )
                                exc = ProviderCooldownError(str(exc),
                                    retry_after_seconds=(exc.retry_after_seconds if retry_after_known
                                        else DEFAULT_MODEL_RATE_LIMIT_COOLDOWN_SECONDS),
                                    rate_limit={"provider": "model", "status_code": 429,
                                                "retry_after_known": retry_after_known,
                                                "provider_error_kind": exc.provider_error_kind})
                                self._copy_error_accounting(provider_error, exc)
                            self._normalize_topic_intake_failure(exc, stage)
                            if classify_failure(
                                    stage.get("kind"), exc,
                                    getattr(exc, "stage_result", None)) == "harness_bug":
                                try:
                                    exc.runtime_frames = [
                                        {"file": frame.filename, "line": frame.lineno,
                                         "function": frame.name}
                                        for frame in traceback.extract_tb(exc.__traceback__)[-12:]
                                    ]
                                except (AttributeError, TypeError):
                                    exc.runtime_frames = []
                            last_error = exc
                            if not usage_recorded and producer_usage is not None:
                                self._merge_incremental_error_usage(exc, producer_usage)
                                if isinstance(producer_foundry_usage, dict):
                                    if not getattr(exc, "usage_includes_foundry", False):
                                        self._merge_incremental_error_usage(exc, producer_foundry_usage)
                                    exc.foundry_usage = deepcopy(producer_foundry_usage)
                                    exc.usage_includes_foundry = True
                                if isinstance(producer_repair_panel_usage, dict):
                                    self._merge_incremental_error_usage(exc, producer_repair_panel_usage)
                                    exc.repair_panel_usage = deepcopy(producer_repair_panel_usage)
                            failure_usage = (deepcopy(context.get("usage", {})) if usage_recorded
                                             else self._record_failed_stage_usage(exc, stage_id=stage_id))
                            specialist_usage = self._specialist_usage([
                                *specialist_bundle.get("reports", []),
                                *([specialist_verifier] if isinstance(specialist_verifier, dict) else []),
                            ])
                            paid_specialists = self._paid_stage_specialist_usage([*specialist_bundle.get("reports", []),
                                *([specialist_verifier] if isinstance(specialist_verifier, dict) else [])])
                            incremental_specialist_usage = {}
                            for key in (() if usage_recorded else self.usage):
                                amount = specialist_usage.get(key, 0)
                                if type(amount) in (int, float) and amount >= 0:
                                    incremental_specialist_usage[key] = max(0, amount - paid_specialists.get(key, 0))
                                    failure_usage[key] = failure_usage.get(key, 0) + amount
                            self._settle_pending_stage_usage(
                                stage_id, already_charged=True, additional_usage=incremental_specialist_usage)
                            self._clear_child_progress(stage_id)
                            provider_paused = isinstance(exc, ProviderCooldownError)
                            provider_operator_stop = isinstance(exc, PROVIDER_OPERATOR_STOP_ERRORS)
                            operational_stop = self._is_operational_stage_failure(exc)
                            provider_rate_limited = isinstance(exc, ProviderRateLimitError)
                            rate_limit = getattr(exc, "rate_limit", None)
                            model_rate_limited = (
                                provider_paused
                                and isinstance(rate_limit, dict)
                                and rate_limit.get("provider") == "model"
                                and rate_limit.get("status_code") == 429
                            )
                            provider_fallback_admitted = (
                                provider_paused
                                and stage["kind"] == "survey"
                                and self._admit_survey_provider_fallback(stage, exc)
                            )
                            repair_order_issued = False
                            model_contract_repair = False
                            stage_contract_failure = (
                                isinstance(exc, (ValidationError, ModelWorkBlocked))
                                or isinstance(getattr(exc, "stage_result", None), dict)
                                or classify_failure(
                                    stage.get("kind"), exc,
                                    getattr(exc, "stage_result", None)) == "harness_bug"
                            )
                            resource_or_control_failure = (
                                provider_paused or provider_operator_stop or operational_stop
                                or isinstance(exc, QuotaExceededError)
                                or isinstance(exc, (ComposerLateStageResult,
                                                    ComposerHardDeadlineExceeded,
                                                    ComposerStageDeadlineExceeded,
                                                    KeyboardInterrupt))
                                or (isinstance(exc, ModelCallError)
                                    and exc.status_code in {408, 425, 429, 500, 502, 503, 504})
                            )
                            # Every known terminal condition gets an immutable
                            # dossier. Resource/control failures are recorded
                            # as fences without creating scientific work orders;
                            # only the scientific classes below can open repair
                            # work. This keeps the audit trail complete while
                            # preventing a quota or provider outage from being
                            # misread as a bad hypothesis.
                            record_failure_dossier = (
                                (stage_contract_failure or resource_or_control_failure)
                                and not isinstance(exc, KeyboardInterrupt)
                            )
                            if record_failure_dossier:
                                try:
                                    failure_dossier = self._record_failure_recovery(
                                        stage, attempt_stage, exc, context,
                                        specialist_bundle, specialist_verifier,
                                        attempt_number, attempt_id=attempt_id,
                                        topic_identity=topic_lineage)
                                    repair_order_issued = (
                                        isinstance(failure_dossier, dict)
                                        and failure_dossier.get("recoverable") is True
                                        and not resource_or_control_failure
                                        and failure_dossier.get("failure_class") not in {
                                            "operational_recovery", "model_contract"
                                        }
                                    )
                                    model_contract_repair = (
                                        isinstance(failure_dossier, dict)
                                        and failure_dossier.get("failure_class") == "model_contract"
                                        and isinstance(self.context.get(stage_id), dict)
                                        and self.context[stage_id].get("format_recovery") is True
                                        and self.context[stage_id].get("format_recovery_dispatched") is not True
                                    )
                                    # Failure recovery replaces the stage packet
                                    # in the durable context. The local
                                    # ``context`` still points at the failed
                                    # runner envelope, so using it below could
                                    # erase the freshly issued repair order and
                                    # authorize a provisional handoff. Carry
                                    # the authoritative recovery packet through
                                    # the remainder of this attempt.
                                    recovered_context = self.context.get(stage_id)
                                    if (isinstance(recovered_context, dict)
                                            and isinstance(
                                                recovered_context.get("failure_recovery"), dict)):
                                        context = deepcopy(recovered_context)
                                except Exception as recovery_error:
                                    # Failure analysis is additive. It must
                                    # never erase the original stage error or
                                    # turn an otherwise recoverable run into a
                                    # control-plane crash.
                                    self.department_activity.append({
                                        "cycle": self.continuation_cycles,
                                        "action": "failure_analysis_error",
                                        "stage_id": stage_id,
                                        "attempt_number": attempt_number,
                                        "error": f"{type(recovery_error).__name__}: {recovery_error}",
                                    })
                            topic_intake_retry = self._is_topic_intake_retry(exc, stage)
                            quota_exhausted = (
                                isinstance(exc, QuotaExceededError)
                                and not topic_intake_retry
                            )
                            if topic_intake_retry:
                                topic_retry_reason = getattr(
                                    exc, "topic_retry_reason", "intake_contract_failure")
                                rejected = list(getattr(exc, "rejected_topic_history", []) or [])
                                if (topic_retry_reason == "scientific_candidate_rejected"
                                        and not rejected):
                                    for trace in reversed(
                                            getattr(exc, "candidate_attempt_trace", [])):
                                        if not isinstance(trace, dict):
                                            continue
                                        rejection_type = trace.get("rejection_type")
                                        if rejection_type not in {
                                                "novelty", "source_challenge", "maturity",
                                                "refinement"}:
                                            continue
                                        selected = (
                                            trace.get("selected_topic")
                                            if isinstance(trace, dict) else None
                                        )
                                        if (not isinstance(selected, dict)
                                                or not isinstance(selected.get("id"), str)):
                                            continue
                                        rejected = [{
                                            "topic_id": selected["id"],
                                            "title": selected.get("title"),
                                            "domain": selected.get("domain"),
                                            "research_question": selected.get("research_question"),
                                            "research_form": selected.get("research_form"),
                                            "evidence_mode": selected.get("evidence_mode"),
                                            "comparison_type": selected.get("comparison_type"),
                                            "rejection_type": rejection_type,
                                            "rejection_reason": str(exc)[:2048],
                                        }]
                                        break
                                if rejected:
                                    try:
                                        self._record_topic_rejection_history(rejected)
                                        self.department_activity.append({
                                            "cycle": self.continuation_cycles,
                                            "action": "pivot_topic_direction",
                                            "stage_id": stage_id,
                                            "attempt_number": attempt_number,
                                            "rejected_topic_ids": [
                                                item.get("topic_id") for item in rejected
                                                if isinstance(item, dict)
                                                and isinstance(item.get("topic_id"), str)
                                            ],
                                            "reason": topic_retry_reason,
                                        })
                                    except Exception as history_error:
                                        # A pivot without durable rejection
                                        # memory could immediately rediscover
                                        # the same weak direction. Preserve the
                                        # failure rather than weakening the
                                        # exclusion contract silently.
                                        topic_intake_retry = False
                                        quota_exhausted = isinstance(exc, QuotaExceededError)
                                        last_error = ValidationError(
                                            "topic pivot history could not be persisted: "
                                            f"{type(history_error).__name__}: {history_error}"
                                        )
                                else:
                                    self.department_activity.append({
                                        "cycle": self.continuation_cycles,
                                        "action": "retry_topic_intake",
                                        "stage_id": stage_id,
                                        "attempt_number": attempt_number,
                                        "rejected_topic_ids": [],
                                        "reason": topic_retry_reason,
                                    })
                            if stage_assignment is not None:
                                try:
                                    assignment_result = self.departments.finish_stage(
                                        stage_id, stage["kind"], attempt_number=attempt_number,
                                        outcome="blocked", output_ref=None,
                                        usage=failure_usage, error=exc,
                                        actor="command.composer",
                                        specialist_results=specialist_bundle.get("by_role", {}),
                                        verifier_result=specialist_verifier,
                                        failure_scope="stage")
                                    self.department_activity.append({
                                        "cycle": self.continuation_cycles,
                                        "action": "record_stage_failure",
                                        "stage_id": stage_id,
                                        "attempt_number": attempt_number,
                                        "failure_scope": "stage",
                                        "verifier_agent": assignment_result["verifier_agent"],
                                        "verifier_outcome": assignment_result["verifier_outcome"],
                                        "chief_synthesis_ref": assignment_result["chief_synthesis_ref"],
                                        "verifier_artifact_ref": assignment_result["verifier_artifact_ref"],
                                    })
                                    self.stage_records[stage_id].update(
                                        self._stage_assignment_fields(stage_assignment, assignment_result))
                                except (NotFoundError, StateError, ValidationError):
                                    # Preserve the stage failure as the primary
                                    # signal; the assignment ledger remains
                                    # inspectable and resume can reconcile any
                                    # child attempt still marked started.
                                    assignment_result = None
                            try:
                                self.tasks.finish_attempt(
                                    attempt_id, "failed", usage=failure_usage)
                                self.tasks.transition(
                                    task_id,
                                    "paused" if (provider_paused or provider_operator_stop or operational_stop) else "blocked",
                                    "command.composer",
                                    reason=str(exc),
                                )
                            except Exception:
                                pass
                            failed_attempt = {
                                "attempt_number": attempt_number,
                                "attempt_id": attempt_id,
                                "cycle": self.continuation_cycles,
                                "state": "failed",
                                "project_dir": attempt_stage["project_dir"],
                                **({"topic_id": topic_lineage["topic_id"],
                                    "topic_cycle": topic_lineage["topic_cycle"]}
                                   if isinstance(topic_lineage, dict) else {}),
                                "error": f"{type(exc).__name__}: {exc}",
                                "usage": deepcopy(failure_usage),
                                "retry_reason": (
                                    getattr(exc, "topic_retry_reason", None)
                                    if topic_intake_retry else None
                                ),
                                "elapsed_seconds": self.clock() - attempt_started,
                            }
                            if provider_paused:
                                failed_attempt["failure_kind"] = "provider_cooldown"
                            if provider_rate_limited:
                                failed_attempt["failure_kind"] = "provider_rate_limit"
                                failed_attempt["provider"] = exc.provider
                                failed_attempt["details"] = deepcopy(exc.details)
                            if isinstance(failure_dossier, dict):
                                failed_attempt["failure_dossier_ref"] = failure_dossier.get("artifact_ref")
                                failed_attempt["failure_class"] = failure_dossier.get("failure_class")
                                failed_attempt["repair_order_issued"] = repair_order_issued
                            if stage["kind"] == "topic_discovery":
                                failed_attempt["topic_usage"] = deepcopy(failure_usage)
                                for attribute in (
                                        "candidate_attempt_trace",
                                        "maturity_review_history",
                                        "rejected_topic_history"):
                                    value = getattr(exc, attribute, None)
                                    if isinstance(value, list) and value:
                                        # Keep the retry ledger useful to the
                                        # dashboard without copying an
                                        # unbounded provider response.
                                        failed_attempt[attribute] = deepcopy(value[-24:])
                            attempt_history.append(failed_attempt)
                            cooldown_retry_index = sum(
                                1 for item in attempt_history
                                if isinstance(item, dict)
                                and (item.get("failure_kind") == "provider_cooldown"
                                     or str(item.get("error", "")).startswith(
                                         "ProviderCooldownError:"))
                            )
                            if provider_paused:
                                exc.cooldown_retry_index = max(1, cooldown_retry_index)
                            # A known provider reset is a transient resource
                            # condition, not another model attempt. Respect its
                            # Retry-After value when supplied; otherwise apply
                            # an escalating cooldown and retry under the same
                            # mission deadline without replaying the blocked call.
                            retry_open = (
                                not provider_operator_stop and not operational_stop
                                and not quota_exhausted
                                and not model_rate_limited
                                # Topic intake already has an explicit
                                # candidate/contract repair loop. Re-entering
                                # that loop here creates a second, deadline-
                                # governed retry controller around a bounded
                                # portfolio and can spend the same stage
                                # allocation without changing its inputs.
                                and (provider_paused or not topic_intake_retry)
                                and not isinstance(
                                    exc, (ComposerLateStageResult,
                                          ComposerHardDeadlineExceeded))
                                and (
                                    model_contract_repair
                                    or not isinstance(exc, ModelWorkBlocked)
                                )
                                and (provider_paused or
                                    retry_policy.get("mode", "bounded") == "until_deadline"
                                    or len(attempt_history) < retry_policy.get("max_attempts", 0)
                                )
                            )
                            # A scientific failure has already been converted
                            # into an evidence dossier and a scoped repair
                            # order.  Retrying the unchanged stage here would
                            # bypass that order and burn the same model/data
                            # budget, so let the Composer continuation handle
                            # the repair first.
                            if repair_order_issued:
                                retry_open = False
                            if retry_open and (adaptive_turn or
                                               (provider_paused and not provider_fallback_admitted)):
                                retry_open = self._schedule_adaptive_retry(
                                    stage, attempt_number=attempt_number, error=last_error,
                                    downstream_seconds=downstream)
                                adaptive_retry_scheduled = retry_open
                            assignment_fields = {
                                key: deepcopy(self.stage_records.get(stage_id, {}).get(key))
                                for key in (
                                    "required_agents", "active_agents", "verifier_agent", "chief_agent",
                                    "assignment_plan_ref", "assignment_ids", "assignment_task_ids",
                                    "assignment_deadline_seconds", "chief_synthesis_ref",
                                    "verifier_artifact_ref", "verifier_outcome", "specialist_assignments",
                                    "topic_id", "topic_cycle",
                                )
                                if key in self.stage_records.get(stage_id, {})
                            }
                            assignment_fields = self._retire_stage_assignment(assignment_fields)
                            self.stage_records[stage_id] = {
                                "kind": stage["kind"],
                                "status": ("retrying" if adaptive_retry_scheduled
                                           else "paused" if (provider_paused or provider_operator_stop or operational_stop)
                                           else "retrying" if retry_open else "blocked"),
                                "task_id": task_id, "attempt_id": attempt_id, "attempt_number": attempt_number,
                                "attempt_count": attempt_number, "attempts": deepcopy(attempt_history),
                                "error": f"{type(exc).__name__}: {exc}",
                                "usage": deepcopy(failure_usage),
                                **assignment_fields,
                            }
                            if provider_paused:
                                retry_after = self._retry_delay_seconds(
                                    exc, getattr(exc, "cooldown_retry_index", attempt_number))
                                cooldown_blocker = {
                                    "stage_id": stage_id,
                                    "attempt_number": attempt_number,
                                    "reason": "provider_cooldown",
                                    "provider_error": str(exc),
                                    "retry_after_seconds": retry_after,
                                    "retry_after_epoch": time.time() + retry_after,
                                    "rate_limit": deepcopy(exc.rate_limit),
                                    "attempts": len(attempt_history),
                                }
                                cooldown_snapshot = getattr(exc, "topic_budget", {})
                                cooldown_snapshot = (
                                    cooldown_snapshot if isinstance(cooldown_snapshot, dict) else {})
                                cooldown_usage = getattr(exc, "usage", None)
                                if not isinstance(cooldown_usage, dict) or not cooldown_usage:
                                    cooldown_usage = cooldown_snapshot.get("usage", {})
                                cooldown_diagnostics = getattr(exc, "diagnostics", None)
                                if not isinstance(cooldown_diagnostics, list) or not cooldown_diagnostics:
                                    cooldown_diagnostics = cooldown_snapshot.get("events", [])
                                if isinstance(cooldown_usage, dict) and cooldown_usage:
                                    cooldown_blocker["usage"] = deepcopy(cooldown_usage)
                                if isinstance(cooldown_diagnostics, list) and cooldown_diagnostics:
                                    cooldown_blocker["diagnostics"] = deepcopy(cooldown_diagnostics)
                                if provider_fallback_admitted and retry_open:
                                    self.department_activity.append({
                                        "cycle": self.continuation_cycles,
                                        "action": "survey_provider_fallback_retry",
                                        "stage_id": stage_id,
                                        "attempt_number": attempt_number,
                                        "provider": "openalex",
                                        "fallback": "crossref_metadata",
                                        "next_condition": "dispatch the changed bibliography route immediately",
                                    })
                                elif retry_open:
                                    # Keep the cooldown in the durable activity
                                    # ledger without misclassifying it as a
                                    # terminal blocker. The next retry waits
                                    # until the provider reset boundary and
                                    # then starts a fresh isolated attempt.
                                    self.department_activity.append({
                                        "cycle": self.continuation_cycles,
                                        "action": "provider_cooldown_auto_retry",
                                        "stage_id": stage_id,
                                        "attempt_number": attempt_number,
                                        "retry_after_seconds": retry_after,
                                        "retry_after_epoch": cooldown_blocker["retry_after_epoch"],
                                        "rate_limit": deepcopy(exc.rate_limit),
                                        "next_condition": "wait for the provider cooldown, then dispatch a fresh isolated attempt",
                                    })
                                    self._checkpoint(
                                        f"{stage_id}:provider_cooldown_retrying", force=True)
                                else:
                                    self.blockers.append(cooldown_blocker)
                                    self.status = "paused"
                                    self._checkpoint(f"{stage_id}:provider_cooldown", force=True)
                                    return self._finish()
                            if provider_fallback_admitted and retry_open:
                                # The fallback changes the next input packet;
                                # do not sleep until the OpenAlex reset or
                                # leave the stale cooldown in the agenda.
                                self.retry_schedule.pop(stage_id, None)
                                self.stage_records.setdefault(stage_id, {})["status"] = "retrying"
                                adaptive_retry_scheduled = True
                            if operational_stop:
                                self.blockers.append({
                                    "stage_id": stage_id, "reason": str(exc),
                                    "stop_reason": "operational_state",
                                    "failure": deepcopy(exc.stage_result["failure"]),
                                    "model_calls_dispatched": failure_usage.get("model_calls", 0),
                                })
                                self.status = "paused"
                                self._checkpoint(f"{stage_id}:operational_state", force=True)
                                return self._finish()
                            if provider_operator_stop:
                                stop_reason = ("provider_rate_limit" if provider_rate_limited
                                               else "provider_configuration")
                                self.blockers.append({
                                    "stage_id": stage_id,
                                    "reason": str(exc),
                                    "stop_reason": stop_reason,
                                    "provider": exc.provider,
                                    **({"details": deepcopy(exc.details)} if provider_rate_limited
                                       else {"credential_env": exc.credential_env}),
                                    "model_calls_dispatched": failure_usage.get("model_calls", 0),
                                })
                                self.status = "paused"
                                self._checkpoint(f"{stage_id}:{stop_reason}", force=True)
                                return self._finish()
                            self._checkpoint(f"{stage_id}:retrying" if retry_open else f"{stage_id}:failed", force=True)
                            if isinstance(exc, ComposerLateStageResult):
                                raise
                            if isinstance(exc, ComposerHardDeadlineExceeded):
                                if isinstance(context, dict):
                                    raise ComposerLateStageResult(
                                        "stage result exceeded the Composer hard deadline"
                                    ) from exc
                                raise
                            if adaptive_retry_scheduled:
                                break
                            if quota_exhausted or not retry_open:
                                # Provider/mission quota exhaustion is a hard
                                # stop. A local scientific intake exhaustion
                                # deliberately does not enter this branch: it
                                # authorizes a fresh direction instead.
                                break
                        finally:
                            stop_live_progress()
                    if adaptive_retry_scheduled:
                        # One failed call is one adaptive agenda turn. The
                        # scheduler can now choose another ready action, or
                        # wait for this retry's not-before boundary and
                        # reassess the frontier before dispatching it again.
                        progress = True
                        break
                    if (not stage_succeeded and stage_admitted
                            and self._composer_can_advance_after_admission(
                                stage, last_error)
                            and last_error is not None):
                        provisional = self._materialize_forward_progress(
                            stage, attempt_stage, last_error, context,
                            specialist_bundle, attempt_history,
                            force_advance=True)
                        if provisional is not None:
                            context = provisional
                            self.context[stage_id] = deepcopy(provisional)
                            current_record = deepcopy(self.stage_records.get(stage_id, {}))
                            current_record.update({
                                "status": "candidate_needs_review",
                                "output_path": provisional.get("output_path"),
                                "forward_progress": True,
                                "composer_decision": "advance_with_findings",
                                "progression_state": "advanced_with_findings",
                                "evidence_state": provisional.get("evidence_state", "unverified"),
                                "results_status": provisional.get("results_status"),
                                "review_status": provisional.get("review_status"),
                                "release_blocking": False,
                                "failure_debt": deepcopy(provisional.get("failure_debt", {})),
                            })
                            self.stage_records[stage_id] = current_record
                            self.continuation_pending_stage_ids.discard(stage_id)
                            stage_succeeded = True
                    if stage_succeeded:
                        release_blocking = (
                            context.get("release_blocking") is True
                            or isinstance(context.get("failure_debt"), dict)
                            and context["failure_debt"].get("release_blocking") is True
                        )
                        # A paper result remains a review candidate until its
                        # own publication contract is accepted.  Never let a
                        # provisional editorial packet satisfy a dependency.
                        if (stage["kind"] == "paper"
                                and context.get("status") == "candidate_needs_review"):
                            release_blocking = True
                        if release_blocking:
                            release_blocked_stage_ids.add(stage_id)
                        else:
                            completed.add(stage_id)
                        self._record_feedback(stage, context)
                        self.stage_records[stage_id] = self._retire_stage_assignment(
                            self.stage_records.get(stage_id, {}))
                        if self._pause_at_stage_boundary(stage_id):
                            return self._finish()
                        if context.get("status") in STAGE_HOLD_STATUSES:
                            # A hold is a control decision, not a successful
                            # dependency.  Start the owning continuation now;
                            # otherwise return the hold without admitting a
                            # consumer that would write against insufficient
                            # or rejected evidence.
                            if self._begin_continuation(completed, by_id):
                                self._checkpoint(f"{stage_id}:continuation_admitted", force=True)
                                progress = True
                                break
                            self.status = context["status"]
                            self._checkpoint(f"{stage_id}:{context['status']}", force=True)
                            return self._finish()
                        self._checkpoint(
                            f"{stage_id}:release_blocked" if release_blocking
                            else f"{stage_id}:completed",
                            force=True,
                        )
                        progress = True
                        break
                    error = last_error or ValidationError(
                        f"stage {stage_id} exhausted its retry policy")
                    assignment_fields = {
                        key: deepcopy(self.stage_records.get(stage_id, {}).get(key))
                        for key in (
                            "required_agents", "active_agents", "verifier_agent", "chief_agent",
                            "assignment_plan_ref", "assignment_ids", "assignment_task_ids",
                            "assignment_deadline_seconds", "chief_synthesis_ref",
                            "verifier_artifact_ref", "verifier_outcome", "specialist_assignments",
                            "topic_id", "topic_cycle",
                        )
                        if key in self.stage_records.get(stage_id, {})
                    }
                    assignment_fields = self._retire_stage_assignment(assignment_fields)
                    self.stage_records[stage_id] = {
                        "kind": stage["kind"], "status": "blocked",
                        "task_id": task_id,
                        "attempt_count": len(attempt_history), "attempts": deepcopy(attempt_history),
                        "error": f"{type(error).__name__}: {error}",
                        **assignment_fields,
                    }
                    if isinstance(failure_dossier, dict):
                        self.stage_records[stage_id].update({
                            "failure_dossier_ref": failure_dossier.get("artifact_ref"),
                            "failure_class": failure_dossier.get("failure_class"),
                            "repair_order_issued": failure_dossier.get("recoverable") is True
                                and failure_dossier.get("failure_class") not in {
                                    "operational_recovery", "model_contract"
                                },
                            "repair_commands": deepcopy(failure_dossier.get("repair_commands", [])),
                            "acceptance_checks": deepcopy(failure_dossier.get("acceptance_checks", [])),
                        })
                    blocker = {"stage_id": stage_id, "reason": str(error),
                               "attempt_number": len(attempt_history),
                               "attempts": len(attempt_history)}
                    if isinstance(failure_dossier, dict):
                        blocker.update({
                            "failure_dossier_ref": failure_dossier.get("artifact_ref"),
                            "failure_class": failure_dossier.get("failure_class"),
                            "repair_order_issued": failure_dossier.get("recoverable") is True
                                and failure_dossier.get("failure_class") not in {
                                    "operational_recovery", "model_contract"
                                },
                        })
                    if getattr(error, "failure_class", None) == "context_budget":
                        blocker["failure_class"] = "context_budget"
                        blocker["context_budget"] = deepcopy(
                            getattr(error, "context_budget", {}))
                    if stage["kind"] == "topic_discovery":
                        rejected_history = getattr(error, "rejected_topic_history", None)
                        if isinstance(rejected_history, list) and rejected_history:
                            try:
                                self._record_topic_rejection_history(rejected_history)
                            except Exception as history_error:
                                blocker["topic_history_error"] = (
                                    f"{type(history_error).__name__}: {history_error}")
                    if isinstance(getattr(error, "usage", None), dict) and error.usage:
                        blocker["usage"] = deepcopy(error.usage)
                    if isinstance(getattr(error, "diagnostics", None), list) and error.diagnostics:
                        blocker["diagnostics"] = deepcopy(error.diagnostics)
                    for attribute in ("candidate_attempt_trace", "maturity_review_history",
                                      "rejected_topic_history"):
                        value = getattr(error, attribute, None)
                        if isinstance(value, list) and value:
                            blocker[attribute] = deepcopy(value)
                    self.blockers.append(blocker)
                    self._record_blocker_feedback(stage, error)
                    if isinstance(error, QuotaExceededError) and getattr(error, "budget_admission", None) is not None:
                        blocker["budget_admission"] = deepcopy(error.budget_admission)
                        blocker.update(dimension=error.dimension, limit=error.limit, observed=error.observed)
                        if self._admit_stage_quota_recovery(stage, error, completed, by_id):
                            blocker.update(stop_reason="stage_quota_exhausted", recovery="cycle_admitted")
                            self.stage_records[stage_id]["status"] = "retrying"
                            self._checkpoint(f"{stage_id}:quota_recovery_admitted", force=True)
                            progress = True
                            break
                        blocker["stop_reason"] = "model_budget_owner_exhausted"
                        self.status = "blocked"
                        self._checkpoint(f"{stage_id}:model_budget_owner_exhausted", force=True)
                        return self._finish()
                    # A failed continuation has consumed the current scoped
                    # work order even when no stage result exists to reach the
                    # normal success bookkeeping.  Fence that exact request
                    # before synthesizing a new repair action; otherwise the
                    # same dossier can reopen the same closure indefinitely.
                    self._mark_research_requests_attempted(stage)
                    recovery_admitted = False
                    try:
                        recovery_admitted = self._admit_scientific_blocker_recovery(
                            stage, error, completed, by_id,
                            specialist_verifier=specialist_verifier)
                    except (ComposerHardDeadlineExceeded, ProviderCooldownError,
                            QuotaExceededError, ValidationError):
                        recovery_admitted = False
                    if recovery_admitted:
                        blocker["recovery"] = "cycle_admitted"
                        self.stage_records[stage_id]["status"] = "retrying"
                        self._checkpoint(f"{stage_id}:scientific_recovery_admitted", force=True)
                        progress = True
                        break
                    try:
                        self._resolve_terminal_stage_work_orders(stage)
                    except (NotFoundError, StateError, ValidationError) as work_order_error:
                        blocker["work_order_resolution_error"] = (
                            f"{type(work_order_error).__name__}: {work_order_error}")
                    self.status = "blocked"
                    self._checkpoint(f"{stage_id}:blocked", force=True)
                    return self._finish()
                if not progress:
                    self.status = "blocked"
                    self.blockers.append({"reason": "composer made no dependency-respecting progress"})
                    self._checkpoint("blocked_no_progress", force=True)
                    return self._finish()
            # A stage can finish its bounded execution while its artifact is
            # still a candidate.  Preserve that distinction at the workflow
            # level so the CLI and any scheduler cannot mistake a candidate
            # for a completed release.
            research_stage = any(
                row.get("status") == "research_expansion_required"
                or self.context.get(stage_id, {}).get("status") == "research_expansion_required"
                for stage_id, row in self.stage_records.items())
            rejected_stage = any(
                row.get("status") == "review_rejected"
                or self.context.get(stage_id, {}).get("status") == "review_rejected"
                for stage_id, row in self.stage_records.items())
            candidate_stage = any(
                row.get("status") == "candidate_needs_review"
                or self.context.get(stage_id, {}).get("status") == "candidate_needs_review"
                for stage_id, row in self.stage_records.items())
            self.status = ("research_expansion_required" if research_stage
                           else "review_rejected" if rejected_stage
                           else "candidate_needs_review" if candidate_stage else "completed")
            self._checkpoint("complete_proposed", force=True)
            return self._finish()
        except ComposerHardDeadlineExceeded as exc:
            self._settle_pending_stage_usage()
            # Reaching the wall after useful research is a resumable mission
            # pause, not a scientific blocker.  A workflow that was already
            # expired before doing any work remains blocked because there is
            # no execution state to resume without an explicit extension.
            had_research_activity = bool(
                self.stage_records or self.context or self.agenda_decisions)
            self.status = "paused" if had_research_activity else "blocked"
            self.blockers.append({
                "stage_id": "workflow",
                "reason": str(exc),
                "stop_reason": "hard_deadline",
            })
            self._checkpoint(
                "paused_deadline" if had_research_activity else "blocked_deadline",
                force=True)
            return self._finish()
        except KeyboardInterrupt as exc:
            self._settle_pending_stage_usage()
            # A process-level stop is a resumable pause, not a failed
            # workflow.  Persist it here so the dashboard and the next
            # resume observe the same durable state.
            self.status = "paused"
            self.blockers.append({
                "stage_id": "workflow",
                "reason": f"{type(exc).__name__}: {exc}",
                "stop_reason": "process_interrupted",
            })
            self._checkpoint("paused_process_interruption", force=True)
            return self._finish()
        except Exception as exc:
            self._settle_pending_stage_usage()
            self.status = "blocked"
            self.blockers.append({"reason": f"{type(exc).__name__}: {exc}"})
            self._checkpoint("blocked", force=True)
            return self._finish()
        finally:
            self.close()

    def _finish(self):
        deadline_exhausted = self._deadline_exhausted()
        # A provider may return just after the fence even when admission was
        # valid.  Such an artifact remains inspectable, but the mission must
        # not report graph completion after its hard wall has passed.
        if deadline_exhausted and self.status not in {"blocked", "paused"}:
            self.status = "blocked"
            self.blockers.append({
                "stage_id": "workflow",
                "reason": "hard_deadline_after_stage_completion",
            })
        elapsed = max(0.0, self.clock() - self.started)
        if self.control is not None and self.active_research_requests:
            paused_orders = self.departments.pause_work_orders(
                self.active_research_requests,
                reason="Composer process ended; continuation order is dormant until resume",
            )
            if paused_orders:
                self.department_activity.append({
                    "cycle": self.continuation_cycles,
                    "action": "pause_work_orders_on_process_exit",
                    "work_orders": paused_orders,
                })
        if self.control is not None:
            # Final publication is on the Composer thread, so it is safe to
            # refresh the durable organization projection here.
            self.organization_snapshot = deepcopy(self.departments.snapshot())
        interim = None
        interim_error = None
        if deadline_exhausted or self.status in {"blocked", "paused"}:
            try:
                stop_reason = "hard_deadline" if deadline_exhausted else None
                active_blockers = self._active_blockers()
                if stop_reason is None and self.status == "paused" and any(
                        isinstance(item, dict)
                        and item.get("reason") == "required_stage_window_does_not_fit_remaining_deadline"
                        for item in active_blockers):
                    stop_reason = "required_stage_window_does_not_fit_remaining_deadline"
                if stop_reason is None and self.status in {"paused", "blocked"} and any(
                        isinstance(item, dict)
                        and item.get("reason") == "provider_cooldown"
                        for item in active_blockers):
                    stop_reason = "provider_cooldown"
                if stop_reason is None and self.status in {"paused", "blocked"}:
                    stop_reason = next((
                        item["stop_reason"] for item in active_blockers
                        if isinstance(item, dict) and item.get("stop_reason") in {
                            "provider_configuration", "provider_rate_limit", "operator_stage_boundary"}
                    ), None)
                if stop_reason is None and self.status in {"paused", "blocked"} and any(
                        isinstance(item, dict)
                        and item.get("stop_reason") == "missing_stage_input"
                        for item in active_blockers):
                    stop_reason = "missing_stage_input"
                if stop_reason is None and self.status in {"paused", "blocked"} and any(
                        isinstance(item, dict)
                        and item.get("stop_reason") == "stage_quota_exhausted"
                        for item in active_blockers):
                    stop_reason = "stage_quota_exhausted"
                if stop_reason is None and self.status == "paused" and any(
                        isinstance(item, dict)
                        and item.get("stop_reason") == "process_interrupted"
                        for item in active_blockers):
                    stop_reason = "process_interrupted"
                interim = self.interim_report(
                    stop_reason=stop_reason or self.status)
            except Exception as exc:
                # The run report remains publishable even if a secondary
                # progress projection encounters an I/O or ledger failure.
                interim_error = f"{type(exc).__name__}: {exc}"
        remaining_seconds = max(0.0, self.deadline - self.clock())
        if isinstance(self.deadline_epoch, (int, float)) and math.isfinite(self.deadline_epoch):
            remaining_seconds = max(0.0, min(remaining_seconds, self.deadline_epoch - time.time()))
        active_blockers = self._active_blockers()
        result = {
            "schema_version": RUN_SCHEMA_VERSION, "run_id": self.run_id, "workflow_id": self.workflow["id"],
            "status": self.status, "execution_policy": execution_policy(), "stages": deepcopy(self.stage_records), "context": deepcopy(self.context),
            "feedback": deepcopy(self.feedback), "blockers": deepcopy(self.blockers),
            "active_blockers": deepcopy(active_blockers),
            "blocker_counts": {
                "active": len(active_blockers),
                "historical": len(self.blockers),
            },
            "usage": deepcopy(self.usage),
            "stage_usage_totals": deepcopy(self.stage_usage_totals),
            "pending_stage_usage": deepcopy(self.pending_stage_usage),
            "foundry_usage": deepcopy(self.foundry_usage),
            "organization": deepcopy(self.organization_snapshot),
            "retry_policy": self._retry_policy(),
            "continuation_policy": self._continuation_policy(),
            "agenda_policy": self._agenda_policy(),
            "agenda_decisions": deepcopy(self.agenda_decisions),
            "retry_schedule": deepcopy(self.retry_schedule),
            "state_revision": self.state_revision,
            "research_state": self._research_state(),
            "continuation_cycles": self.continuation_cycles,
            "continuation_budget_baseline": self._continuation_budget_baseline,
            "continuation_budget_used": self._continuation_budget_used(),
            "reopened_stage_ids": sorted(self.reopened_stage_ids),
            "continuation_pending_stage_ids": sorted(self.continuation_pending_stage_ids),
            "active_research_requests": deepcopy(self.active_research_requests),
            "attempted_request_signatures": sorted(self._attempted_request_signatures),
            "format_recovery_ledger": deepcopy(self.format_recovery_ledger),
            "department_activity": deepcopy(self.department_activity),
            "deadline_decisions": deepcopy(self.deadline_decisions),
            "deadline_extensions": deepcopy(self.deadline_extensions),
            "topic_history_path": str(self.topic_history_path),
            "topic_history_scope": self.topic_history_scope,
            "topic_history_entries": len(self.topic_history.get("entries", [])),
            "started_at_epoch": self.started_epoch, "deadline_at_epoch": self.deadline_epoch,
            "elapsed_seconds": elapsed, "remaining_seconds": remaining_seconds,
            "deadline_seconds": self.workflow["time_policy"]["hard_seconds"],
            "release_status": (
                "research_expansion_required" if self.status == "research_expansion_required"
                else "review_rejected" if self.status == "review_rejected"
                else "candidate_needs_review" if self.status == "candidate_needs_review"
                else "needs_human_approval" if self.status == "completed"
                and self.workflow["completion"]["release_requires_human"]
                else "not_released"
            ),
            "event_chain": self.control.verify_chain() if self.control is not None else None,
            "interim_report_path": interim.get("path") if isinstance(interim, dict) else None,
        }
        if isinstance(interim, dict):
            result["interim_report"] = deepcopy(interim)
        if interim_error:
            result["interim_report_error"] = interim_error
        if self.control is not None:
            self._publish("command/composer/run", "report", result, "command.composer")
            output = self.root / "output"
            output.mkdir(parents=True, exist_ok=True)
            _atomic_write_bytes(output / "run.json", canonical_bytes(result))
            self.on_progress({"phase": self.status, "elapsed_seconds": round(elapsed, 2),
                              "stages": deepcopy(self.stage_records),
                              "blockers": deepcopy(result["active_blockers"]),
                              "active_blockers": deepcopy(result["active_blockers"]),
                              "blocker_counts": deepcopy(result["blocker_counts"]),
                              "usage": deepcopy(result["usage"]),
                              "foundry_usage": deepcopy(result["foundry_usage"]),
                              "organization": deepcopy(result["organization"])})
        return result


def read_interim_report(project_dir):
    """Load the latest concise Composer interim report from a project."""
    path = Path(project_dir).resolve() / "output" / "interim_report.json"
    if path.is_file():
        try:
            report = json.loads(path.read_text())
        except (OSError, ValueError) as exc:
            raise ValidationError(f"Composer interim report is not valid JSON: {path}") from exc
        if not isinstance(report, dict) or report.get("schema_version") != "composer-interim-report-1":
            raise ValidationError(f"Composer interim report has an unsupported schema: {path}")
        return report

    # A hard process interruption can occur before ``_finish`` gets to write
    # the projection.  The live checkpoint is still an inspectable, atomic
    # source for a short recovery report in that case.
    checkpoint_path = path.parent / "progress.json"
    if not checkpoint_path.is_file():
        raise ValidationError(f"Composer interim report does not exist: {path}")
    try:
        checkpoint = json.loads(checkpoint_path.read_text())
    except (OSError, ValueError) as exc:
        raise ValidationError(f"Composer progress checkpoint is not valid JSON: {checkpoint_path}") from exc
    if not isinstance(checkpoint, dict) or checkpoint.get("schema_version") != "composer-checkpoint-1":
        raise ValidationError(f"Composer progress checkpoint has an unsupported schema: {checkpoint_path}")
    stages = checkpoint.get("stages", {})
    if not isinstance(stages, dict):
        stages = {}
    workflow = None
    control = None
    workflow_error = None
    try:
        control = ControlStore(project_dir)
        artifacts = ArtifactStore(control)
        workflow_head = artifacts.head("command/composer/workflow")
        if workflow_head is not None:
            workflow = json.loads(artifacts.read_body(workflow_head["body_hash"]))
    except Exception as exc:
        workflow = None
        workflow_error = f"{type(exc).__name__}: {exc}"
    finally:
        if control is not None:
            control.close()
    workflow_stages = workflow.get("stages", []) if isinstance(workflow, dict) else []
    ordered_ids = [stage["id"] for stage in workflow_stages
                   if isinstance(stage, dict) and isinstance(stage.get("id"), str)]
    stage_kind_by_id = {stage["id"]: stage.get("kind") for stage in workflow_stages
                        if isinstance(stage, dict) and isinstance(stage.get("id"), str)}
    if not ordered_ids:
        ordered_ids = sorted(stages)
    rows = []
    completed, active, pending, held, blocked = [], [], [], [], []
    for stage_id in ordered_ids:
        record = stages.get(stage_id, {}) if isinstance(stages.get(stage_id, {}), dict) else {}
        status = record.get("status", "pending")
        attempts = record.get("attempt_count", len(record.get("attempts", []))
                              if isinstance(record.get("attempts", []), list) else 0)
        row = {"id": stage_id, "kind": record.get("kind") or stage_kind_by_id.get(stage_id), "status": status,
               "attempts": attempts}
        if isinstance(record.get("output_path"), str):
            row["output_path"] = record["output_path"]
        if isinstance(record.get("error"), str):
            row["error"] = record["error"][:240]
        if record.get("forward_progress") is True:
            row["forward_progress"] = True
            row["release_blocking"] = record.get("release_blocking", True)
            debt = record.get("failure_debt")
            if isinstance(debt, dict):
                row["failure_debt"] = {
                    key: deepcopy(debt.get(key))
                    for key in ("failure_class", "error", "attempts", "next_action", "release_blocking")
                    if key in debt
                }
        rows.append(row)
        if status in STAGE_READY_STATUSES:
            completed.append(stage_id)
        elif status in {"running", "retrying"}:
            active.append(stage_id)
        elif status in STAGE_HOLD_STATUSES:
            held.append(stage_id)
        elif status == "blocked":
            blocked.append(stage_id)
        else:
            pending.append(stage_id)
    started_at_epoch = checkpoint.get("started_at_epoch")
    deadline_at_epoch = checkpoint.get("deadline_at_epoch")
    duration = None
    if (type(started_at_epoch) in (int, float) and type(deadline_at_epoch) in (int, float)
            and math.isfinite(started_at_epoch) and math.isfinite(deadline_at_epoch)
            and deadline_at_epoch >= started_at_epoch):
        duration = deadline_at_epoch - started_at_epoch
    report = {
        "schema_version": "composer-interim-report-1",
        "workflow_id": checkpoint.get("workflow_id"),
        "run_id": checkpoint.get("run_id"),
        "status": "interrupted",
        "stop_reason": "process_interrupted",
        "last_phase": checkpoint.get("phase"),
        "elapsed_seconds": checkpoint.get("elapsed_seconds", 0.0),
        "remaining_seconds": checkpoint.get("remaining_seconds", 0.0),
        "deadline_seconds": workflow.get("time_policy", {}).get("hard_seconds", duration)
        if isinstance(workflow, dict) else duration,
        "started_at_epoch": started_at_epoch,
        "deadline_at_epoch": deadline_at_epoch,
        "completed_stage_ids": completed,
        "active_stage_ids": active,
        "pending_stage_ids": pending,
        "held_stage_ids": held,
        "blocked_stage_ids": blocked,
        "stages": rows,
        "pending_work_orders": (checkpoint.get("organization", {}) or {}).get("open_work_orders", [])[:8]
        if isinstance(checkpoint.get("organization"), dict) else [],
        "blockers": checkpoint.get("blockers", [])[-3:]
        if isinstance(checkpoint.get("blockers"), list) else [],
        "active_blockers": checkpoint.get("active_blockers", [])
        if isinstance(checkpoint.get("active_blockers"), list) else [],
        "blocker_counts": checkpoint.get("blocker_counts", {
            "active": len(checkpoint.get("active_blockers", []))
            if isinstance(checkpoint.get("active_blockers"), list) else 0,
            "historical": len(checkpoint.get("blockers", []))
            if isinstance(checkpoint.get("blockers"), list) else 0,
        }),
        "deadline_extensions": checkpoint.get("deadline_extensions", []),
        "next_actions": ["Inspect retained stage outputs and resume the same workflow."],
        "resume_hint": (
            "python -m scisaurus.cli run-composer --workflow "
            "<path-to-the-same-workflow.json> --resume --extend-deadline-seconds <N>"
        ),
        "source": str(checkpoint_path.resolve()),
    }
    if workflow_error:
        report["workflow_metadata_error"] = workflow_error
    return report


__all__ = ["SCHEMA_VERSION", "RUN_SCHEMA_VERSION", "validate_workflow", "ComposerRunner",
           "read_interim_report"]
